\section{Strichartz estimates for the Ornstein Uhlenbeck operator}
In this section, we aim to derive one of the principal results of this work: the Strichartz estimates for the Ornstein-Uhlenbeck operator. As a preliminary step, we recall the classical Strichartz estimates associated with the Laplacian, which serve as a guiding framework for our analysis. The original formulation of Strichartz estimates in \( L^p \) spaces was introduced by R.~Strichartz~\cite{R.S.Strichartz}, in a context that was closely connected to the restriction problem for the Fourier transform on submanifolds. Subsequently, Ginibre and Velo~\cite{ginibre1992smoothing} employed the \( TT^* \) method to obtain such estimates, providing a powerful functional-analytic tool that has influenced much of the subsequent development in this area. 
%\subsection{The Classical Laplacian}
As is well known, Fourier analysis plays a fundamental role in the study of the classical free Schr\"odinger equation on \( \mathbb{R}^d \) for \( d \geq 1 \). Consider 
\begin{align*}
		\begin{cases}
			i\partial_t u-\Delta u=0,\quad  t \in \mathbb{R}, \\
			u(0,x)=u_0(x)\in L^2(\mathbb{R}^d).
		\end{cases}
	\end{align*}
The solution can be written explicitly as
\begin{align}
\label{Homogeneoussolution}u(t,x)&=e^{-it\Delta}u_0(x)\\
      &\nonumber=\frac{1}{(2\pi)^d}\int_{\mathbb{R}^d} e^{it(|\xi|^2+x\cdot \xi)} \widehat{u_0}(\xi) \mathrm{d}\xi\\
      &\nonumber=\frac{1}{(4\pi i t)^\frac{d}{2}}\int_{\mathbb{R}^d} e^{i\frac{|x-y|^2}{4t}} u_0(y) \mathrm{d} y.
\end{align}
 Therefore, we have the following dispersive estimate $L^1\to L^\infty$.
\begin{equation}\label{disest}
\|u(t,\cdot)\|_{L^\infty(\mathbb{R}^d)}=\|e^{it\Delta}u_0\|_{L^\infty(\mathbb{R}^d)}\lesssim \frac{1}{|t|^\frac{d}{2}}\|u_0\|_{L^1(\mathbb{R}^d)},\quad \forall t\ne 0.
\end{equation}
The corresponding inhomogeneous equation is 
\begin{align}
\label{Laplacian NLS}
\begin{cases}
i\partial_t u-\Delta u=F(t,x),\quad x \in \mathbb{R}^d, t \in \mathbb{R}, \\
u(0,x)=u_{0}(x).
\end{cases}
\end{align}
By Duhamel's principle, the integral version of \eqref{Laplacian NLS} has the form 
\begin{align}
\label{Laplacian Duhamel}
u(t,x)=e^{-it\Delta}u_0(x)-i\int_{0}^{t}e^{-i(t-s)\Delta}F(s,\cdot)\ \mathrm{d}s.
\end{align}


From the above dispersive estimate (\ref{disest}), using the $TT^*$ argument, the Strichartz estimate for the free Schr\"odinger equation can be deduced. Here we recall the abstract Stricharz estimates established by Keel-Tao \cite{KT}.
\begin{lemma} Let $(X,dx)$ be a measure space and $H$ be a Hilbert space. Suppose that for each time $t\in\mathbb{R}$ we have an operator $U(t): H\to L^2(X)$ which obey the energy estimate, i.e., for all  we have
\begin{equation*}
\|U(t)\|_{L^2(X)}\lesssim \|f\|_H,\;\forall t\in\mathbb{R},\;f\in H,
\end{equation*}
and that for some $\sigma>0$ the following decay estimate holds
\begin{equation*}
\|U(s)(U(t))^*g\|_{L^\infty(X)}\lesssim |t-s|^{-\sigma} \|g\|_{L^1(X)},\;\forall t\neq s\in\mathbb{R},\; g\in L^1(X).
\end{equation*}
Then we have the estimates 
\begin{align*}
\|U(t)f\|_{L^{q}_{t}(\mathbb{R},L^r(X))}&\lesssim \|f\|_H,\\
\left\|\int_{\mathbb{R}}U(t)(U(s))^*F(s,\cdot)\right\|_{L_{t}^{q}(\mathbb{R},L^r(X))}&\lesssim \|F\|_{L_{t}^{\tilde{q}'}(\mathbb{R},L^{\tilde{r}'}(X))},
\end{align*}
hold for all sharp $\sigma$-admissible pairs $(q,r),(\tilde{q},\tilde{r})$.
\end{lemma}
As a consequence of the above theorem, taking $U(t)=e^{-it\Delta}$ and $H=L^2(\mathbb{R}^d)$, one can obtain the Strichartz estimates for the classical Schr\"odinger operator.
\begin{theorem}
Suppose that $d\geq 1$ and  $(q,r),(\tilde{q},\tilde{r})$ are sharp $\frac{d}{2}$-admissible pairs. Then
\begin{align*}
\|e^{-it\Delta}u_0\|_{L_{t}^{q}(\mathbb{R},L^r(\mathbb{R}^d))}&\lesssim \|u_0\|_{L^2(\mathbb{R}^d)},\\
\left\|\int_{\mathbb{R}}e^{-i(t-s)\Delta}F(s,\cdot)\right\|_{L_{t}^{q}(\mathbb{R},L^r(\mathbb{R}^d))}&\lesssim \|F\|_{L_{t}^{\tilde{q}'}(\mathbb{R},L^{\tilde{r}'}(\mathbb{R}^d))}.
\end{align*}
\end{theorem}






%\subsection{The Ornstein-Uhlenbeck Operator}
Now let us consider the free Schr\"odinger equation related to the Ornstein-Uhlenbeck Operator on $\mathbb{R}^d$ 
\begin{align}\label{eq-OU}
		\left\{\begin{array}{l}
			i\partial_t u- \mathbf{L} u=0,\quad  t \in \mathbb{R}, \\
			u(0,x)=u_0(x) \quad x \in \mathbb{R}^d.
		\end{array}\right.
	\end{align}
The solution of \eqref{eq-OU} can be written explicitly by
\begin{align*}
u(t,x)&=e^{-it\mathbf{L}}u_0(x)\\
      &=\int_{\mathbb{R}^d} M_{it}(x,y) u_0(y) \gamma_d(y)dy.
\end{align*}
It follows from \eqref{schrodinger-kernel} that
\begin{equation*}
|u(t,x)|=|e^{-it\mathbf{L}}u_0(x)|\lesssim \frac{1}{|\sin t|^\frac{d}{2}}\int_{\mathbb{R}^d}e^{\frac{1}{2}(|x|^2+|y|^2)}|u_0(y)|\gamma_d(y)dy,\quad \forall t\in \mathbb{R}\setminus \pi\mathbb{Z}.
\end{equation*}
Let the weight function $w(x)=e^{-\frac{|x|^2}{2}}$ and we have
\begin{equation*}
|u(t,x)w(x)|=|e^{-it\mathbf{L}}u_0(x)w(x)|\lesssim \frac{1}{|\sin t|^\frac{d}{2}}\int_{\mathbb{R}^d}|u_0(y)|w^{-1}(y)\gamma_d(y)dy,\quad \forall t\in \mathbb{R}\setminus \pi\mathbb{Z}.
\end{equation*}
Hence, for all $ 0<|t|\leq \frac{\pi}{2}$ we obtain the local weighted $L^1\to L^\infty$ dispersive estimate as
\begin{equation}\label{weighted dispersive}
\|u(t,\cdot)\|_{L_{\gamma_d}^\infty(w)}=\|e^{-it\mathbf{L}}u_0\|_{L_{\gamma_d}^\infty(w)}\lesssim \frac{1}{|\sin t|^\frac{d}{2}}\|u_0\|_{L_{\gamma_d}^1(w^{-1})}\lesssim \frac{1}{| t|^\frac{d}{2}}\|u_0\|_{L_{\gamma_d}^1(w^{-1})}.
\end{equation}
%\section{Strichartz estimates for the Ornstein-Uhlenbeck Operator}

Using the above dispersive estimate \eqref{weighted dispersive}, we can derive the following weighted Strichartz estimates for the solution of \eqref{eq-OU}.
\begin{theorem}\label{main}
Let $d\geq1$ and $(q,r)$, $(\tilde{q},\tilde{r})$ be sharp $\frac{d}{2}$-admissible pairs. If $d=1$ and $(q,r)=(4,\infty)$, the Strichartz estimates hold
\begin{equation*}
\|e^{-it\mathbf{L}}u_0\|_{L^{4}_{t}([-\frac{\pi}{2},\frac{\pi}{2}],L^\infty_{\gamma_1}(w))}\lesssim \|u_0\|_{L^2_{\gamma_1}}.
\end{equation*}
For other sharp $\frac{d}{2}$-admissible pairs $(q,r)$, one has the weighted Strichartz estimates 
\begin{equation}
\label{HomogeneousStrichartz}
\|e^{-it\mathbf{L}}u_0\|_{L^{q}_{t}([-\frac{\pi}{2},\frac{\pi}{2}],L^r_{\gamma_d}(w^{r-2}))}\lesssim \|u_0\|_{L^2_{\gamma_d}},
\end{equation}
and
\begin{equation}
\label{HomogeneousDualStrichartz}
\bigg\|\int_{-\frac{\pi}{2}}^{\frac{\pi}{2}}e^{i(t-s)\mathbf{L}}F(s,\cdot)\ \mathrm{d}s\bigg\|_{L_{t}^{q}([-\frac{\pi}{2},\frac{\pi}{2}],L^{r}_{\gamma_d}(w^{r-2}))}\lesssim \|F\|_{L_{t}^{\tilde{q}'}([-\frac{\pi}{2},\frac{\pi}{2}], L^{\tilde{r}'}_{\gamma_{d}}(w^{\tilde{r}'-2}))},
\end{equation}
where the weight function is 
\begin{equation*}
w(x)=e^{-\frac{|x|^2}{2}}.
\end{equation*}
\end{theorem}
In order to prove the above theorem, we will apply the general lemma of Keel-Tao \cite{KT}.
\begin{lemma}\label{abstract KT}
Let $\sigma>0$, $H$ be a Hilbert space and $B_0,B_1$ be Banach spaces. Suppose that for each time $t\in I$ we have an operator $U(t): H\to B_0^*$ such that
\begin{align*}
\|U(t)\|_{H\to B_0^*}&\lesssim 1,\\
\|U(t)(U(s))^*\|_{B_1\to B_1^*}&\lesssim |t-s|^{-\sigma}.
\end{align*}
Let $B_\theta$ denote the real interpolation space $(B_0,B_1)_{\theta,2}$. Then we have the estimates
\begin{align}\label{non}
\|U(t)f\|_{L^{q}_{t}(I,B^*_\theta)}&\lesssim \|f\|_H,\\
\label{otherdualpart}\left\|\int_I U(t)(U(s))^*F(s,\cdot)ds\right\|_{L^{q}_{t}(I,B^*_\theta)}&\lesssim \|F\|_{L_{t}^{\tilde{q}'}(I,B_{\tilde{\theta}})},
\end{align}
where $0\leq\theta\leq 1$, $2\leq q=\frac{2}{\sigma\theta}$, $(q,\theta,\sigma)\neq (2,1,1)$ and similarly for $(\tilde{q},\tilde{\theta})$. 
\end{lemma}




\begin{proof}[Proof of Theorem \ref{main}] In our case, let $U(t)=e^{-it\mathbf{L}}$ and
\begin{align*}
H=B_0&=L^2_{\gamma_d},\;B_1=L^1_{\gamma_d}(w^{-1}),\;\sigma=\frac{d}{2},\;2\leq \frac{4}{d\theta},\\
&0\leq \theta\leq 1,\; \left(\frac{4}{d\theta},\theta,\sigma\right)\neq (2,1,1).
\end{align*}
Applying the lemma \ref{abstract KT}, we get
\begin{equation*}
\|e^{-it\mathbf{L}}u_0\|_{L_{t}^\frac{4}{d\theta}([-\frac{\pi}{2},\frac{\pi}{2}],(L^2_{\gamma_d}, L^1_{\gamma_d}(w^{-1}))^*_{\theta,2})}\lesssim \|u_0\|_{L^2_{\gamma_d}}.
\end{equation*}
By Theorem 3.4.1. of Bergh-L\"ofstr\"om \cite{Bergh-Lofstrom}, for any $1\leq h\leq 2$, 
\begin{equation*}
(L^2_{\gamma_d}, L^1_{\gamma_d}(w^{-1}))_{\theta,h}\subseteq(L^2_{\gamma_d}, L^1_{\gamma_d}(w^{-1}))_{\theta,2},
\end{equation*}
and hence
\begin{equation}\label{interpolation}
\|e^{-it\mathbf{L}}u_0\|_{L_{t}^{\frac{4}{d\theta}}([-\frac{\pi}{2},\frac{\pi}{2}],(L^2_{\gamma_d}, L^1_{\gamma_d}(w^{-1}))^*_{\theta,h})}\lesssim \|u_0\|_{L^2_{\gamma_d}}.
\end{equation}
The conditions on $\theta$ can be divided into two cases:
\begin{enumerate}
\item when $d\geq 2$, $0\leq \theta\leq \frac{2}{d}$ and $(\theta,d)\neq (1,2)$;
\item when $d=1$, $0\leq \theta\leq 1$.
\end{enumerate}

\textbf{Case 1: } Let $d\geq 2$, $0\leq \theta\leq \frac{2}{d}$ and $(\theta,d)\neq (1,2)$. In this case, $0\leq \theta<1$. Indeed, for the value $\theta=0$, the operator $e^{it\mathbf{L}}$ obeys the energy conservation, which implies the Strichartz estimates.
\begin{equation}\label{energy conservation}
\|e^{-it\mathbf{L}}u_0\|_{L_{t}^{\infty}([-\frac{\pi}{2},\frac{\pi}{2}],L^2_{\gamma_d})}\lesssim \|u_0\|_{L^2_{\gamma_d}}.
\end{equation}
For any $0<\theta<1$, by Theorem 5.5.1. of Bergh-L\"ofstrom \cite{Bergh-Lofstrom}, 
\begin{equation*}
(L^2_{\gamma_d}, L^1_{\gamma_d}(w^{-1}))_{\theta,h}=L^h_{\gamma_d}(\tilde{w}),
\end{equation*}
with
\begin{equation*}
\frac{1}{h}=\frac{1-\theta}{2}+\frac{\theta}{1} \text{ and } \tilde{w}=w^{-h\theta},
\end{equation*}
which indicates that $1<h=\frac{2}{1+\theta}<2$. Therefore,
\begin{equation*}
(L^2_{\gamma_d}, L^1_{\gamma_d}(w^{-1}))_{\theta,h}=L^\frac{2}{1+\theta}_{\gamma_d}(w^{-\frac{2\theta}{1+\theta}}).
\end{equation*}
From the classical formula
\begin{equation*}
(L^\alpha_{\gamma_d}(w))^*=L^{\alpha'}_{\gamma_d}(w^{-\frac{\alpha'}{\alpha}}),\;\forall 1<\alpha<\infty.
\end{equation*}
It follows that
\begin{equation*}
(L^2_{\gamma_d}, L^1_{\gamma_d}(w^{-1}))_{\theta,h}^*=L^\frac{2}{1-\theta}_{\gamma_d}(w^{\frac{2\theta}{1-\theta}}).
\end{equation*}

Therefore, for $0<\theta<1$, the inequality \eqref{interpolation} gives the weighted Strichartz estimates.
\begin{equation}\label{weighted Strichartz}
\|e^{-it\mathbf{L}}u_0\|_{L^\frac{4}{d\theta}_{t}([-\frac{\pi}{2},\frac{\pi}{2}],L^\frac{2}{1-\theta}_{\gamma_d}(w^{\frac{2\theta}{1-\theta}}))}\lesssim \|u_0\|_{L^2_{\gamma_d}},
\end{equation}
which also holds for $\theta=0$ from \eqref{energy conservation}. 

\textbf{Case 2: } Let $d=1$, $0\leq \theta\leq 1$. For $0\leq \theta<1$. Proceeding in a manner similar to Case 1, one can derive the weighted Strichartz estimates as well, \eqref{weighted Strichartz}. For $\theta=1$, from \eqref{non} it follows that
\begin{equation*}
\|e^{-it\mathbf{L}}u_0\|_{L_{t}^{4}([-\frac{\pi}{2},\frac{\pi}{2}],L^\infty_{\gamma_1}(w))}=\|e^{-it\mathbf{L}}u_0\|_{L_{t}^{4}\left([-\frac{\pi}{2},\frac{\pi}{2}],\left(L^1_{\gamma_1}(w^{-1})\right)^*\right)}\lesssim \|u_0\|_{L^2_{\gamma_1}}.
\end{equation*}

For $0\leq \theta<1$, denoting $q=\frac{4}{d\theta}$ and $r=\frac{2}{1-\theta}$, we have $\frac{2\theta}{1-\theta}=-2+\frac{2}{1-\theta}=r-2$. The pair $(q,r)$ satisfies $\frac{2}{q}+\frac{\sigma}{r}=\frac{\sigma}{2}$ with $q\geq2$, $2\leq r<\infty$, $\sigma=\frac{d}{2}$ and $(q,r,d)\neq (2,\infty,2)$.
Therefore, we have the weighted Strichartz estimates
\begin{equation}\label{weighted Strichartz2}
\|e^{-it\mathbf{L}}u_0\|_{L_{t}^{q}([-\frac{\pi}{2},\frac{\pi}{2}],L^r_{\gamma_d}(w^{r-2}))}\lesssim \|u_0\|_{L^2_{\gamma_d}}.
\end{equation}

Now, using duality arguments  and proceeding with analogous computations as above, one can establish the homogeneous dual Strichartz estimate \eqref{HomogeneousDualStrichartz}.

\end{proof}








