Now, observe that $\epsilon$ shrinks as $\eta$ and $\delta$ are made small. So by taking them sufficiently small we get 
\begin{align*}
\|N(u)-N(v)\|_{\mathcal{N}(I\times \mathbb{R}^{d})}\leq \frac{1}{4C(d)}\|u-v\|_{\mathcal{S}^{0}(I\times\mathbb{R}^{d})},
\end{align*}
enough to make the iteration work. Now we get the unique solution in $\mathcal{S}^{0}(I\times\mathbb{R}^{d})$ and so in $\mathcal{S}(I\times\mathbb{R}^{d})$.
\end{comment}



{\begin{proof}[Proof of Theorem \ref{criticalcase}]
As in the subcritical case, we apply the iteration principle (Proposition \ref{Iterationprinciple}). The iteration is carried out in the same function spaces $\mathcal{N}(I \times \mathbb{R}^d)$ and $\mathcal{S}(I \times \mathbb{R}^d)$, and uses the same operators $D$ and $N$ as in the proof of Theorem \ref{Subcriticalcase}. However, we now introduce a modified space $\mathcal{S}^{0}(I \times \mathbb{R}^d)$, equipped with the norm
\[
\|u\|_{\mathcal{S}^{0}(I \times \mathbb{R}^d)} := \delta \|u\|_{\mathcal{S}(I \times \mathbb{R}^d)} + \|u\|_{L^{p+1}_t L^{p+1}_{\gamma_d}(w^{p-1})},
\]
where $0 < \delta < 1$ is a parameter to be chosen later. Let us also denote by $u_0^* := e^{-it \mathbf{L}} u_0$  corresponding to initial data $u_0 \in B(u_1, \eta)$, where $\|u_0 - u_1\|_{L^2_{\gamma_d}} \leq \eta$.

We first estimate the norm of $u_0^*$ in $\mathcal{S}^{0}$:
\begin{align*}
\|u_0^*\|_{\mathcal{S}^{0}(I \times \mathbb{R}^d)} 
&= \delta \|u_0^*\|_{\mathcal{S}(I \times \mathbb{R}^d)} + \|u_0^*\|_{L^{p+1}_t L^{p+1}_{\gamma_d}(w^{p-1})} \\
&\leq \delta C(d) \|u_0\|_{L^2_{\gamma_d}} + \|e^{-it\mathbf{L}}(u_0 - u_1)\|_{L^{p+1}_t L^{p+1}_{\gamma_d}(w^{p-1})} + \|e^{-it\mathbf{L}} u_1\|_{L^{p+1}_t L^{p+1}_{\gamma_d}(w^{p-1})} \\
&\leq \delta C(d)(R + \eta) + \|u_0 - u_1\|_{L^2_{\gamma_d}} + \eta \\
&\leq \delta C(d)(R + \eta) + 2\eta =: \frac{\epsilon}{2},
\end{align*}
where we have used the Strichartz estimate and triangle inequality.

Next, we show that the operator $D$ is bounded from $\mathcal{N}$ to $\mathcal{S}^{0}$. From the homogeneous Strichartz estimate, we have
\[
\|Df\|_{\mathcal{S}(I \times \mathbb{R}^d)} \leq C(d) \|f\|_{\mathcal{N}(I \times \mathbb{R}^d)}.
\]
Moreover, since $(p+1, p+1)$ is an admissible pair and $\mathcal{S}(I \times \mathbb{R}^d) \subseteq L^{p+1}_t L^{p+1}_{\gamma_d}(w^{p-1})$, we get
\[
\|Df\|_{L^{p+1}_t L^{p+1}_{\gamma_d}(w^{p-1})} \leq \|Df\|_{\mathcal{S}(I \times \mathbb{R}^d)} \leq C(d) \|f\|_{\mathcal{N}(I \times \mathbb{R}^d)}.
\]
Therefore,
\begin{align*}
\|Df\|_{\mathcal{S}^{0}(I \times \mathbb{R}^d)} 
&= \delta \|Df\|_{\mathcal{S}} + \|Df\|_{L^{p+1}_t L^{p+1}_{\gamma_d}(w^{p-1})} \\
&\leq \delta C(d) \|f\|_{\mathcal{N}} + C(d) \|f\|_{\mathcal{N}} \\
&\leq C(d)(1 + \delta) \|f\|_{\mathcal{N}} \leq 2C(d) \|f\|_{\mathcal{N}},
\end{align*}
where we used that $0 < \delta < 1$.

Now, using the same arguments as in the subcritical case, we estimate the nonlinearity:
\begin{align*}
\|N(u) - N(v)\|_{\mathcal{N}(I \times \mathbb{R}^d)} 
&\leq C(d) |I|^{\frac{1}{q'} - \frac{p}{q}} \|u - v\|_{L^{p+1}_t L^{p+1}_{\gamma_d}(w^{p-1})} \\
&\quad \times \left( \|u\|^{p+1}_{L^{p+1}_t L^{p+1}_{\gamma_d}(w^{p-1})} + \|v\|^{p+1}_{L^{p+1}_t L^{p+1}_{\gamma_d}(w^{p-1})} \right).
\end{align*}
Since we are in the critical case \(p = 1 + \frac{4}{d}\), we observe that
\[
\frac{1}{q'} - \frac{p}{q} = \frac{d}{4} \left( \frac{4}{d} + 1 - p \right) = 0.
\]
Thus, the time factor \( |I|^{\frac{1}{q'} - \frac{p}{q}} \) does not provide smallness. However, since \(u, v \in B_\epsilon\), we obtain
\[
\|N(u) - N(v)\|_{\mathcal{N}(I \times \mathbb{R}^d)} \leq 2 C(d) \epsilon^{p+1} \|u - v\|_{\mathcal{S}^{0}(I\times \mathbb{R}^{d})}.
\]
Now, since \(\epsilon\) depends on \(\eta\) and \(\delta\), we can choose them sufficiently small so that
\[
\|N(u) - N(v)\|_{\mathcal{N}(I \times \mathbb{R}^d)} \leq \frac{1}{4C(d)} \|u - v\|_{\mathcal{S}^{0}(I\times \mathbb{R}^{d})}.
\]
Combining all of the above, we can apply the iteration principle to obtain a unique solution \(u \in \mathcal{S}^{0}(I \times \mathbb{R}^d)\), which in turn belongs to \(\mathcal{S}(I \times \mathbb{R}^d)\), completing the proof.
\end{proof}
}
























