\section{Day convolution on \texorpdfstring{$\infty$}{infinity}-categories of presheaves}\label{Subsect:dayconvolution}

The category of functors between two symmetric monoidal categories can be endowed with a symmetric monoidal structure, called Day convolution.

\begin{thm}[\protect{\cite[Prop.\ 2.11]{Glasman}} and \protect{\cite[Ex. 2.2.6.9]{Lurie-HA}}]\label{Prop:maindayconvolution} Let $\calC^\otimes$ and $\calD^\otimes$ be symmetric monoidal categories. Assume that $\calD$ has all small colimits and that the tensor product on $\calD$ preserves them in each variable separately. Then the category $\Fun(\calC,\calD)$ admits a symmetric monoidal structure $\Fun(\calC,\calD)^\otimes$, called \emph{Day convolution}. It has in particular the property that there is an equivalence of categories
$$\CAlg(\Fun(\calC,\calD)^\otimes) \simeq \Fun^\mathsf{lax}(\calC^\otimes,\calD^\otimes).$$
\end{thm}

For any symmetric monoidal category $\calC^\otimes$, in the particular case $\calD^\otimes = \spaces^\times$, Day convolution endows the category of presheaves $\Pre(\calC)$ with a symmetric monoidal structure (because the opposite of $\calC$ has an induced symmetric monoidal structure \cite[Rmk.\ 2.4.2.7]{Lurie-HA}). This symmetric monoidal structure has the following universal property:
\begin{Prop}[\protect{\cite[Cor.\ 4.8.1.12 and Rmk.\ 4.8.1.13]{Lurie-HA}}]\label{Prop:dayconvolutionpsh}
Let $\calC^\otimes$ be a symmetric monoidal category. Day convolution is the essentially unique symmetric monoidal structure on the category $\Pre(\calC)$ such that:
\begin{enumerate}
    \item the tensor product preserves colimits in both variables separately,
    \item and the Yoneda embedding $y: \calC \to \Pre(\calC)$ can be extended into a symmetric monoidal functor $y^\otimes$.
\end{enumerate}  
\end{Prop}

\begin{Prop}\label{Prop:laxdayconvolution} Let $\calC^\otimes$ be a symmetric monoidal category, and consider $\Pre(\calC)^\otimes$ with the Day convolution symmetric monoidal structure. Let $\calD^\otimes \in\CAlg(\PrL)$.

    Then, the symmetric monoidal Yoneda embedding $y^\otimes: \calC^\otimes \to \Pre(\calC)^\otimes$ induces an equivalence
    $$- \circ y^\otimes: \Fun^{\mathsf{L,lax}}(\Pre(\calC)^\otimes,\calD^\otimes) \xrightarrow{\simeq} \Fun^{\mathsf{lax}}(\calC^\otimes,\calD^\otimes),$$
    where $\Fun^{\mathsf{L,lax}}$ denotes colimit-preserving lax symmetric monoidal  functors, and $\Fun^{\mathsf{lax}}$ all lax symmetric monoidal functors.
\end{Prop}

\begin{Def}\label{Def:smLKE} In the setting of Proposition \ref{Prop:laxdayconvolution}, let $\mathsf{LKE}^\otimes$ be an inverse for the equivalence $- \circ y^\otimes$. Given $F\in \Fun^{\mathsf{lax}}(\calC^\otimes,\calD^\otimes)$, we say that the lax symmetric monoidal functor $\mathsf{LKE}^\otimes(F) : \Pre(\calC)^\otimes \to \calD^\otimes$ is \emph{left Kan extended as a lax symmetric monoidal functor} from $F$.
\end{Def}

\begin{proof}[Proof of Proposition \ref{Prop:laxdayconvolution}]
    Day convolution makes $\Fun(\Pre(\calC),\calD)$ and $\Fun(\calC,\calD)$ into symmetric monoidal categories $\Fun(\Pre(\calC),\calD)^\otimes$ and $\Fun(\calC,\calD)^\otimes$, respectively. By \cite[Cor.\ 3.8]{Nikolaus}, precomposition by a lax symmetric monoidal functor induces a lax symmetric monoidal functor with respect to the Day convolution on the functor categories. In our case, this implies that precomposition with the symmetric monoidal Yoneda embedding induces a lax symmetric monoidal functor $\Fun(\Pre(\calC),\calD)^\otimes \to \Fun(\calC,\calD)^\otimes$. By the usual universal property of the presheaf category (free cocompletion), the underlying functor restricts to an equivalence $\Fun^\mathsf{L}(\Pre(\calC),\calD) \to \Fun(\calC,\calD)$. In particular, $\Fun^\mathsf{L}(\Pre(\calC),\calD)$ is a symmetric monoidal subcategory $\Fun(\Pre(\calC),\calD)$, equivalent as a symmetric monoidal category to $\Fun(\calC,\calD)$.

    Therefore, precomposition by the Yoneda embedding induces an equivalence
    $$ \CAlg(\Fun^\mathsf{L}(\Pre(\calC),\calD)^\otimes) \xrightarrow{\ \ \simeq \ \ } \CAlg(\Fun(\calC,\calD)^\otimes).$$

    By Theorem \ref{Prop:maindayconvolution}, the left and right-hand sides are respectively equivalent to $\Fun^{\mathsf{L,lax}}(\Pre(\calC)^\otimes,\calD^\otimes)$ and $\Fun^{\mathsf{lax}}(\calC^\otimes,\calD^\otimes)$. Indeed, for the first one, note that if $\calE^\otimes$ is a symmetric monoidal category with a symmetric monoidal full subcategory $\calF^\otimes$, then the categories of commutative algebras in $\calF$ is that of commutative algebras in $\calE$ whose underlying object lies in $\calF$. This follows from the description of commutative algebras in terms of the representing coCartesian fibrations.
\end{proof}

\begin{Prop}\label{Prop:dayconvolution} The equivalence of Proposition \ref{Prop:laxdayconvolution} restricts to an equivalence:
$$- \circ y^\otimes: \Fun^{\mathsf{L,\otimes}}(\Pre(\calC)^\otimes,\calD^\otimes) \xrightarrow{\simeq} \Fun^{\otimes}(\calC^\otimes,\calD^\otimes)$$
between subcategories of (strongly) symmetric monoidal functors.
\end{Prop}
\begin{proof}
    Since $y^\otimes$ is (strongly) symmetric monoidal, the functor $-\circ y^\otimes$ preserves strong monoidality. On the other hand, if $F\in \Fun^{\mathsf{lax}}(\calC^\otimes,\calD^\otimes)$ is actually strongly symmetric monoidal (which, once we have specified a lax monoidal structure, is a property and does not require additional data), let $H=\mathsf{LKE}^\otimes(F)$. Then, we have to show that $H$ is strongly symmetric monoidal, i.e., that for any $\calF,\calG \in\Pre(\calC)$, the map $H(\calF)\otimes_\calD H(\calG) \longrightarrow H(\calF \otimes_{\Pre(\calC)} \calG)$ (coming from the lax symmetric monoidal structure on $H$) is an equivalence. By assumption, this holds for $\calF$ and $\calG$ representable presheaves. Moreover, the class of presheaves $\calF$ and $\calG$ for which this holds is closed under colimits in both $\calF$ and $\calG$. Indeed, $H$ preserves colimits by construction, and tensor products in both $\calD$ and $\Pre(\calC)$ preserve colimits in each variable (by Proposition \ref{Prop:dayconvolutionpsh}). Since every presheaf is a colimit of representable ones, this concludes the proof.
\end{proof}
