\section{Manipulation of Ridge Regression Fixed-Point Equations}
\label{sec:ridge-reg-eqs-val}

We expand $r_B$ and $\rho_B$ and perform substitution to obtain:
\begin{align}
    r_B &= \kappa^2 \ntrace \Theta \Sigma (\Sigma + \kappa I_d)^{-2} + \kappa (\rho_B / e) \dof_2 (\kappa) / d, \\
    \rho_B / e &= \phi \kappa \ntrace \Theta \Sigma (\Sigma + \kappa I_d)^{-2} + (\rho_B / e) \dof_2 (\kappa) / n \\
    &= \frac{\phi \kappa \ntrace \Theta \Sigma (\Sigma + \kappa I_d)^{-2}}{1 - \dof_2 (\kappa) / n},
\end{align}
\begin{align}
    r_B &= \kappa^2 \ntrace \Theta \Sigma (\Sigma + \kappa I_d)^{-2} + \frac{\dof_2 (\kappa) / n}{1 - \dof_2 (\kappa) / n} \cdot \kappa^2 \ntrace \Theta \Sigma (\Sigma + \kappa I_d)^{-2} \\
    &= \frac{\kappa^2 \ntrace \Theta \Sigma (\Sigma + \kappa I_d)^{-2}}{1 - \dof_2 (\kappa) / n}.
\end{align}

Similarly, with $r_V$ and $\rho_V$:
\begin{align}
     r_V / \lambda &= (1 / e - \rho_V / e^2) \dof_2 (\kappa) / d, \\
     \rho_V / e^2 &= \phi (1 / e) \kappa \ntrace \Sigma ( \Sigma + \kappa I_d)^{-2} + (\rho_V / e^2) \dof_2 (\kappa) / n \\
     &= \frac{(1 / e) (\dof_1 (\kappa) - \dof_2 (\kappa)) / n}{1 - \dof_2 (\kappa) / n} \\
     &= \frac{(1 / e - 1) - (1 / e) \dof_2 (\kappa) / n}{1 - \dof_2 (\kappa) / n} \text{ (Eqn. \ref{eq:fund})}, \\
     r_V / \lambda &= 1/e \cdot \dof_2 (\kappa) / d - \frac{(1 / e - 1) - (1 / e) \dof_2 (\kappa) / n}{1 - \dof_2 (\kappa) / n} \cdot \dof_2 (\kappa) / d \\
     &= \frac{\dof_2 (\kappa) / d}{1 - \dof_2 (\kappa) / n}.
\end{align}



\section{An Algebra of Block Matrices}
\label{sec:algebra}

Let $\mathcal A$ be the (von Neumann) non-commutative unital algebra of all block matrices with the same size and block shapes as the $p \times p$ block matrix $Q'$ (and therefore $Q_X'$). Thus, each block $M[i,j]$ of each $M \in \mathcal A$ has same shape $\alpha_i \times \beta_j$ as the corresponding block $Q'[i,j]$ of $Q'$. Let $1_{\mathcal A}$ be the unit element of $\mathcal A$. Note that $\mathcal A$ is fully determined by the $p^2$ pairs of integers $\{(\alpha_i,\beta_j) \mid 1 \le i,j\le p\}$ representing the shapes of the blocks of $Q'$. The operator $I_{p} \otimes \ntrace$ which extracts the normalized traces\footnote{By convention, the trace of a non-square block is zero.} of the blocks of an element $M \in \mathcal A$ is a \emph{tracial state} for this algebra. It maps a block matrix $M \in \mathcal A$ into a $p \times p$ matrix $(I_d \otimes \ntrace)M$.

   Any $p \times p$ matrix $B$ can be embedded into an element $B^\circ$ of $\mathcal A$ by defining the $(i,j)$-block of the later as follows:
    \begin{eqnarray}
        B^\circ[i,j] = \begin{cases}
            B_{i,j} I_{\alpha_i},&\mbox{ if }\alpha_i=\beta_j,\\
            0_{\alpha_i\times \beta_j},&\mbox{ otherwise.}
        \end{cases}
    \end{eqnarray}
    It is clear that if $B=I_{p}$, then $B^\circ = 1_{\mathcal A}$.

    \textbf{Worked Example.} As an example, observe that if $Q=\left[\begin{matrix}I_n & - Z\\Z^\top  & I_d\end{matrix}\right]$ is the linear pencil we constructed for the MP law in Section \ref{sec:mp}, then by inspecting the shape of the blocks of the symmetrization $Q'$, we get
    $$
    p=4,\, \alpha_1=\alpha_3=\beta_1=\beta_3=n,\, \alpha_2=\alpha_4=\beta_2=\beta_4=d.
    $$
    In this case, any $4 \times 4$ matrix $B$ is mapped to the block matrix $B^\circ \in \mathcal A$ given by
    $$
    B^\circ = \left[\begin{matrix}0 & 0 & B_{1,3}I_n & 0 \\0 & 0 & 0  & B_{2,4}I_d\\
    B_{3,1}I_n & 0 & 0 & 0\\0  & B_{4,2}I_d & 0 & 0\end{matrix}\right].
    $$



\section{Anisotropic MP Law with \code{auto-fpt}}
\label{sec:anisotropic-MP-law}

Consider the case of general covariance matrix $\Sigma$. The design matrix can be written as $X=X_0\Sigma_{sqrt}$, where $\Sigma_{sqrt}=\Sigma^{1/2}$ is the positive square-root of $\Sigma$, i.e., the unique positive-definite matrix such that $\Sigma_{sqrt}^2 = \Sigma$. As before $X_0$ is an $n \times d$ random matrix with IID entries from $\mathcal N(0,1)$. Thus, $X$ has IID rows distributed according to a multivariate Gaussian distribution $\mathcal N(0,\Sigma)$. Our goal is to compute the Stieltjes transform of the empirical covariance matrix $X^\top X/n$, namely the expected value of the trace of the resolvent matrix $R=(X^\top X/n+\lambda I_d)^{-1}$, in the limit $n,d \to \infty$, $d/n\to \infty$. 

As in the isotropic case (Section \ref{sec:mp}), we start by computing a linear pencil for $R$ using \code{auto-fpt}.

\begin{lstlisting}[language=python,numbers=none]
from sympy import Symbol, MatrixSymbol, Identity
import numpy as np
from fpt import calc

# Form the design matrix.
n = Symbol("n", integer=True, positive=True)
d = Symbol("d", integer=True, positive=True)
Z = MatrixSymbol("Z", n, d)
Sigma_sqrt = MatrixSymbol("\Sigma_{sqrt}",d , d)  # Covariance matrix
phi = Symbol(r"\phi", positive=True)

X = Z@Sigma_sqrt  # Design matrix
expr = (X.T@X + Identity(d)).inv()  # Resolvent matrix

# Compute linear pencil using NCAlgebra
Q, (u, v) = compute_minimal_pencil(expr)
\end{lstlisting}
The above code snippet yields:
\begin{align}
Q &= \begin{bmatrix}\mathbb{I} & - Z^\top & 0 & 0\\0 & \mathbb{I} & - Z & 0\\0 & 0 & \mathbb{I} & - \Sigma_{sqrt}\\\Sigma_{sqrt}^\top & 0 & 0 & \mathbb{I}\end{bmatrix},\\
u&=[0, 0, 0, 1],\\
v&=[0, 0, 0, 1].
\end{align}

Similarly to the previous calculation (the isotropic setup), we shall later normalize to take $\lambda$ and the $1/n$ factor into account. We can now compute the fixed-point equations defining the limiting value of $\ntrace R$ like so:

\begin{lstlisting}[language=python,numbers=none]
row_idx, col_idx = np.argmax(u), np.argmax(v)
eqns = calc(Q, random_matrices=["Z"], row_idx=row_idx, col_idx=col_idx,
           normalize="full", subs={d: n * phi})
\end{lstlisting}
This code snippet spits out the following fixed-point equations:
\begin{gather*}
    {G}_{3,3} = \bar{tr}{\left(\lambda \left(\lambda \mathbb{I} + \Sigma_{sqrt}^{2} {G}_{1,1}\right)^{-1} \right)},\\
{G}_{1,1} = - \frac{\lambda}{\phi {G}_{2,0} - \lambda},\\
{G}_{2,0} = \bar{tr}{\left(- \lambda \Sigma_{sqrt}^{2} \left(\lambda \mathbb{I} + \Sigma_{sqrt}^{2} {G}_{1,1}\right)^{-1} \right)}
\end{gather*}
Eliminating $G_{2,0}$ from the above and recalling that $\Sigma_{sqrt}^2=\Sigma$ by construction, we can reorganize these equations as follows:
\begin{align}
    \ntrace R \simeq G_{3,3}/\lambda &= \ntrace (G_{1,1}\Sigma + \lambda I_d)^{-1},\\ \text{ where }
    \lambda/G_{1,1} &= \lambda + \phi \kappa \ntrace\Sigma(\Sigma + (\lambda/G_{1,1}) I_d)^{-1}.
\end{align}
Setting $\kappa:=\lambda/G_{1,1}$, we deduce that $\ntrace R \simeq (\kappa/\lambda)\trace (\Sigma + \kappa I_d)^{-1}$, where $\kappa>0$ uniquely solves the fixed-point equation:
\begin{eqnarray}
    \kappa = \lambda + \phi \kappa \ntrace\Sigma(\Sigma+\kappa I_d)^{-1}.
\end{eqnarray}
This is a well-known result \citep{MP1967} (also see Proposition 1 of \citet{bach2024high} for an alternative derivation).



