           col_idx=col_idx, variances=variances, subs={d: n * phi})
\end{lstlisting}           



\section{Random Features Model with \code{auto-fpt}}
\label{sec:rf-model}

Equations \ref{eq:y-pred-ntk} to \ref{eq:tau1-tau2-rat} are largely from \citet{adlam2020neural}, which we include here for completeness.
The predictions $\hat{y}(X)$ of the network on the training set (when trained using gradient descent and the width of the network becomes large) converges to:
\begin{align}
    \hat{y} (x) &= N_0 (X) + (Y - N_0 (X)) K^{-1} K(X, X) \\
    &= Y - \gamma (Y - N_0 (X)) K^{-1}.
    \label{eq:y-pred-ntk}
\end{align}
We make use of the following definitions:
\begin{gather*}
    K := K(X, X) + \lambda I_n, K(x_1, x_2) = J(x_1) J(x_2)^\top,
\end{gather*}
where $\lambda$ is the regularization penalty and $J$ is the Jacobian of the network's output with respect to its parameters. In the setting $\sigma^2_{W_2} \to 0$, because $K_1 (X, X) = (\partial N_0 (X) / \partial W_1) (\partial N_0 (X) / \partial W_1)^\top = 0$, we have that:
\begin{align}
K(X, X) &= K_2 (X, X) = (\partial N_0 (X) / \partial W_2) (\partial N_0 (X) / \partial W_2)^\top \\
&= F^\top F / m,
\end{align}
where the feature matrix $F:=\sigma(W_1X/\sqrt d)$. Then, the training risk can be decomposed as follows:
\begin{align}
    E_{train} &= \mathbb E \ntrace ((Y - \hat{y} (X))^\top (Y - \hat{y} (X))) \\
    &= \gamma^2 \mathbb E \ntrace ((Y - N_0 (X))^\top (Y - N_0 (X)) K^{-2}) \\
    &= T_1 + T_2, \\
    \text{ with } T_1 &= \gamma^2 \mathbb E \ntrace Y^\top Y K^{-2}, \\
    T_2 &= \gamma^2 \mathbb E \ntrace N_0 (X)^\top N_0(X) K^{-2},
\end{align}
where we have used that the expectation of terms linear in $N_0(X)$ is 0. We observe that because $\sigma_{W_2}^2 \to 0$:
\begin{align}
    N_0 (X) &= W_2 F / \sqrt{m}, \\
    T_2 &= \mathbb E \ntrace W_2^\top W_2 (F / \sqrt{m}) (F^\top F / m)^{-2} (F / \sqrt{m})^\top \\
    &= \sigma_{W_2}^2 \mathbb E \ntrace (F / \sqrt{m}) (F^\top F / m)^{-2} (F / \sqrt{m})^\top = 0.
\end{align}

Now, the \emph{Gaussian Equivalence Theorem} \citep{goldt2022gaussian} tells us that we can replace $F$ with a linearized version $F_{lin}$, and $Y$ similarly with $Y_{lin}$:
\begin{align}
F_{lin}&=\sqrt{\frac{\zeta}{d}}W_1 X+\sqrt{\beta}\Theta_F,\quad Y_{lin}=\sqrt{\frac{1}{d_T d}} \omega \Omega X+ \epsilon,
\end{align}
without changing their limiting spectral distribution.
Here, $\Theta_F$ is a random $m \times n$ matrix independent of $X$ and $W_1$, with IID entries from $\mathcal N(0,1)$. Hence, we deduce that:
\begin{align}
    T_1 &= \gamma^2 \mathbb E \ntrace Y_{lin}^\top Y_{lin} K^{-2} \\
    &= \gamma^2 \mathbb E \ntrace (X^\top X / d + \sigma_\epsilon^2 I_n) K^{-2} \\
    &= \gamma^2 (\mathbb E \ntrace (X^\top X K^{-2}) / d + \sigma_\epsilon^2 \mathbb E \ntrace K^{-2}) \\
    &= -\gamma^2 (\tau_2' + \sigma_\epsilon^2 \tau_1'), \\
\end{align}
where $\tau_1(\lambda) := \mathbb E \ntrace K^{-1}$ and $\tau_2(\lambda) := \frac{1}{d} \mathbb E \ntrace X^\top X K^{-1}$. It now remains to derive fixed-point equations relating $\tau_1, \tau_2$. We define the following random matrices:
\begin{gather*}
    W_0 = \sqrt{\frac{\zeta}{\lambda m}} W_1,\quad X_0 = \sqrt{\frac{1}{d}} X, \quad \Theta_0 = \sqrt{\frac{\beta}{\lambda m}} \Theta_F, \\
    F_0 = W_0 X + \Theta_0.
\end{gather*}

Using the above definitions, we can rewrite $\tau_1, \tau_2$ as:
\begin{align}
   \tau_1 &= \frac{1}{\lambda} \mathbb E \ntrace (F_0^\top F_0 + I_n)^{-1}, \\
   \tau_2 &= \frac{1}{\lambda} \mathbb E \ntrace X_0^\top X_0 (F_0^\top F_0 + I_n)^{-1}.
   \label{eq:tau1-tau2-rat}
\end{align}

NCAlgebra can be used to compute a single minimal pencil for both $\tau_1$ and $\tau_2$, and we apply \code{auto-fpt} to derive a reduced system of fixed-point equations relating the quantities.

\begin{lstlisting}
from sympy import Symbol, MatrixSymbol, Identity, pprint, latex, \
    Eq, solve, symbols, fraction, simplify, expand, factor, together
import numpy as np
from fpt import calc

# Define the relevant random and deterministic matrices and scalars.
n = Symbol("n", integer=True, positive=True)
d = Symbol("d", integer=True, positive=True)
m = Symbol("m", integer=True, positive=True)

phi = Symbol(r"\phi", positive=True)
psi = Symbol(r"\psi", positive=True)
lambd = Symbol(r"\lambda", positive=True)
d = phi * n
m = d / psi

zeta = Symbol(r"\zeta", positive=True)
eta = Symbol(r"\eta", positive=True)
beta = Symbol(r"\beta", positive=True)

W0 = MatrixSymbol("W_0", m, d)
X = MatrixSymbol("X", d, n)
T0 = MatrixSymbol(r"\Theta_0", m, n)
variances = {X: 1 / d, W0: zeta / (m * lambd), T0: beta / (m * lambd)}

# Form the resolvent for Kinv.
F0 = W0 @ X + T0
Kinv = (F0.T @ F0 + Identity(n)).inv()

# Compute a minimal linear pencil for X^T * X * Kinv + Kinv using NCAlgebra.
Q, (u, v) = compute_minimal_pencil(X.T @ X @ Kinv + Kinv)

# Get the index of the entry in u, v corresponding to X^T * X * Kinv.
XTXKinv_i = np.flatnonzero(u)[0]
XTXKinv_j = np.flatnonzero(v)[0]

# Compute the fixed-point equations for Kinv and X^T * X * Kinv 
# using free probability theory.
eqns = calc(Q, random_matrices=[X, W0, T0], row_idx=XTXKinv_i, \
            col_idx=XTXKinv_j, subs={}, variances=variances)

# Get the index of the entry in u, v corresponding to Kinv.
Kinv_i = np.flatnonzero(u)[1]
Kinv_j = np.flatnonzero(v)[0]
\end{lstlisting}

The above code snippet yields the following fixed-point equations for $\tau_1, \tau_2$:
\begin{gather*}
    \lambda \tau_2 = \frac{\lambda {G}_{0,0}}{\beta {G}_{4,4} + \lambda {G}_{3,0} + \lambda},\\
{G}_{3,0} = \frac{\phi \zeta {G}_{4,4}}{\lambda \phi + \zeta {G}_{2,2} {G}_{4,4}},\\
\lambda \tau_1 = \frac{\lambda}{\beta {G}_{4,4} + \lambda {G}_{3,0} + \lambda},\\
{G}_{4,4} = - \frac{\lambda \phi}{- \beta \psi {G}_{2,2} - \lambda \phi + \phi \psi \zeta {G}_{0,3}},\\
{G}_{0,3} = - \frac{\lambda {G}_{2,2}}{\lambda \phi + \zeta {G}_{2,2} {G}_{4,4}},\\
{G}_{0,0} = \frac{\lambda \phi}{\lambda \phi + \zeta {G}_{2,2} {G}_{4,4}}.
\end{gather*}

Via variable elimination (e.g., through programmatic iterative substitution), we arrive at the following reduced system relating $\tau_1, \tau_2$:
\begin{align}
    0 &= - \phi \left(\beta \phi \tau_{1}^{2} - \beta \phi \tau_{1} \tau_{2} + \lambda \tau_{1}^{2} \tau_{2} \zeta + \phi \tau_{1} \tau_{2} \zeta - \phi \tau_{2}^{2} \zeta - \tau_{1} \tau_{2} \zeta\right) := p_1, \\
    0 &= - \lambda \phi \left(\beta \psi \tau_{1}^{2} - \beta \psi \tau_{1} \tau_{2} + \phi \tau_{1} - \phi \tau_{2} + \psi \tau_{1} \tau_{2} \zeta - \psi \tau_{2}^{2} \zeta - \tau_{1} \tau_{2} \zeta\right) := p_2.
\end{align}

By substituting $\beta = \eta - \zeta$ and dividing out constant factors, we observe that:
\begin{align}
    0 &= p_1 / \phi = - \eta \phi \tau_{1}^{2} + \eta \phi \tau_{1} \tau_{2} - \lambda \tau_{1}^{2} \tau_{2} \zeta + \phi \tau_{1}^{2} \zeta - 2 \phi \tau_{1} \tau_{2} \zeta + \phi \tau_{2}^{2} \zeta + \tau_{1} \tau_{2} \zeta \text{ (S68 \citep{adlam2020neural})}, \\
    0 &= -\psi p_1 / \phi + p_2 / \lambda = \lambda \psi \tau_{1}^{2} \tau_{2} \zeta - \phi^{2} \tau_{1} + \phi^{2} \tau_{2} + \phi \tau_{1} \tau_{2} \zeta - \psi \tau_{1} \tau_{2} \zeta \text{ (S67 \citep{adlam2020neural})}.
\end{align}

This exactly recovers the coupled polynomial equations for $\tau_1, \tau_2$ in \citet{adlam2020neural}, namely Proposition 1 thereof with $\sigma^2_{W_2} = 0$. We provide code for programmatic empirical and analytical validation of the equations for $\tau_1, \tau_2$ under the \code{examples} folder in our repository.


