\title{
Hidden Bose-Einstein Singularities of Correlated Electron Systems:\\
 III. Thermodynamic Signals
}

\author{Takafumi Kita}
\affiliation{Department of Physics, Hokkaido University, Sapporo 060-0810, Japan}
