\section{Equality between Eqs.\ (\ref{Omega_MF}) and (\ref{Omega_MF2})}

To show the equality between Eqs.\ (\ref{Omega_MF}) and (\ref{Omega_MF2}),
we consider the following function
%
\begin{align}
f(\xi)\equiv &\, -T \, \sum_{n}\biggl\{{\rm Tr}\, \hat{1}(\varepsilon_n)
\ln \begin{bmatrix} - i\varepsilon_n+\xi_1 \!\!&\!\!\Delta_1 \\ \Delta_1 \!\!&\!\! -i\varepsilon_n-\xi_1\end{bmatrix}
\notag \\
&\,-2 e^{i\varepsilon_n 0_+} \ln (-i\varepsilon_n+\xi)\biggr\}
\label{f(xi)-1}
\end{align}
%
with $\xi_1\equiv\xi+\Sigma_1$,
which satisfies $f(\infty)=0$.
Its derivative can be transformed as
%
\begin{align}
f'(\xi)=&\, -T \, \sum_{n}\biggl\{{\rm Tr}\, \hat{1}(\varepsilon_n)\!
\begin{bmatrix} - i\varepsilon_n+\xi_1 \!\!&\!\! \Delta_1 \\ \Delta_1 \!\!&\!\! -i\varepsilon_n-\xi_1\end{bmatrix}^{-1}\!\hat\tau_3
\notag \\
&\,-2 \frac{e^{i\varepsilon_n 0_+}}{-i\varepsilon_n+\xi}\biggr\}
\notag \\
=&\, 2T\sum_n \left[\frac{i\varepsilon_n+\xi_1}{(i\varepsilon_n)^2-\xi_1^2-E_1^2}-\frac{1}{i\varepsilon_n-\xi}\right]e^{i\varepsilon_n 0_+}
\notag \\
=&\, 2T\sum_n \left(\frac{u_1^2}{i\varepsilon_n-E_1}+\frac{v_1^2}{i\varepsilon_n+E_1}-\frac{1}{i\varepsilon_n-\xi}\right)e^{i\varepsilon_n 0_+}
\notag \\
=&\, 2\frac{\xi_1}{E_1}\bar{n}(E_1)+1-\frac{\xi_1}{E_1}-2\bar{n}(\xi),
\end{align}
%
with $E_1\!\equiv\!\sqrt{\xi_1^2+\Delta_1^2}$, $u_1^2\!\equiv\! \frac{1}{2}\left(1+\frac{\xi_1}{E_1}\right)$, $v_1^2\!\equiv \!\frac{1}{2}\left(1-\frac{\xi_1}{E_1}\right)$, and $\bar{n}(E_1)\equiv(e^{E_1/T}+1)^{-1}$.
Integrating $f'(\xi)$ with the condition $f(\infty)=0$,
we obtain
%
\begin{align}
f(\xi) = -2T\ln\frac{1+e^{-E_1/T}}{1+e^{-\xi/T}}+\xi_1-E_1.
\label{f(xi)-2}
\tag{\ref{f(xi)-1}$^\prime$}
\end{align}
%
Thus, we have proved the equality between Eqs.\ (\ref{f(xi)-1}) and (\ref{f(xi)-2}), which implies the equality between Eqs.\ (\ref{Omega_MF}) and (\ref{Omega_MF2}).

\section{Some analytic expressions at $T_{1{\rm PR}}$}

We here derive crude analytic expressions for the initial slope of $\lambda(T)$
and the discontinuity of the specific heat $\varDelta C_V$ at $T= T_{1{\rm PR}}$.

\subsection{Initial slope of $\lambda(T)$}

Let us express Green's function in the pseudogap phase of $\lambda\neq 0$ 
as $G_\lambda(\vec{k})$.
This phase is characterized by the identity\cite{Kita25}
%
\begin{align}
U\chi_{G\bar{G}}(\vec{0})=1,
\label{PGC}
\end{align}
%
where $\chi_{G\bar{G}}(\vec{0})$ is the particle-particle bubble at zero
momentum and Matsubara frequency defined by
%
\begin{align}
\chi_{G\bar{G}}(\vec{0})\equiv -\frac{T}{{\cal N}_{\rm a}}\sum_{\vec{k}}G_\lambda(\vec{k})G_\lambda(-\vec{k}).
\label{chi_pp}
\end{align}

It follows from Eq.\ (32) and (33) of Ref.\ \onlinecite{Kita25} that 
$G_\lambda(\vec{k})$ can be expanded in $\bar\lambda$ as
%
\begin{align}
G_\lambda(\vec{k})=G(\vec{k})\left[1+\bar\lambda G(\vec{k})G(-\vec{k})+\cdots \right],
\label{G_lambda}
\end{align}
%
where $G(\vec{k})$ denotes Green's function for $\lambda=0$, and $\bar\lambda$ is defined by
%
\begin{align}
\bar\lambda\equiv \frac{{\cal N}_{\rm e}}{{\cal N}_{\rm a}}U \lambda.
\label{bLambda-def}
\end{align}
%
Using Eq.\ (\ref{G_lambda}), 
we can express the pseudogap condition (\ref{PGC}) for $T\lesssim T_{1{\rm PR}}$ 
up to the first order in $\bar\lambda$ as
%
\begin{align}
1=&\, -\frac{UT}{{\cal N}_{\rm a}}\sum_{\vec{k}}G(\vec{k})G(-\vec{k})
-2\bar\lambda \frac{UT}{{\cal N}_{\rm a}}\sum_{\vec{k}}\bigl[G(\vec{k})G(-\vec{k})\bigr]^2 .
\label{PGC2}
\end{align}
%
Let us subtract the corresponding equation at $T= T_{1{\rm PR}}$ with $\bar\lambda=0$
from Eq.\ (\ref{PGC2}).
We thereby obtain an expression of $\bar\lambda$ for $T\lesssim T_{1{\rm PR}}$ as
%
\begin{align}
\bar\lambda 
=&\,\frac{\displaystyle \frac{UT}{{\cal N}_{\rm a}}\sum_{\vec{k}}\left[G(\vec{k})G(-\vec{k})-G(\vec{k})G(-\vec{k})\Bigr|_{T=T_{1{\rm PR}}}\right]}{\displaystyle -2\frac{UT}{{\cal N}_{\rm a}}\sum_{\vec{k}}\bigl[G(\vec{k})G(-\vec{k})\bigr]^2} 
\equiv \frac{I_{\rm n}}{I_{\rm d}} .
\label{bLambda}
\end{align}
%

Both of its numerator $I_{\rm n}$ and denominator $I_{\rm d}$ can be evaluated analytically in a crude
approximation of using the non-interacting Green's function
$G_0(\vec{k})$ in place of $G(\vec{k})$.
Accordingly, we also replace $T_{1{\rm PR}}$ in Eq.\ (\ref{bLambda}) by the superconducting transition temperature 
$T_{{\rm c}0}$ of the mean-field theory given by Eq.\ (20) of Ref.\ \onlinecite{Kita25}.
Repeating the procedure of deriving the analytic expression for $T_{{\rm c}0}$ there,
we can transform the numerator of Eq.\ (\ref{bLambda}) in this approximation into
%
\begin{subequations}
\label{I_nI_d}
\begin{align}
I_{\rm n}\approx-UN(0)\ln \frac{T}{T_{{\rm c0}}},
\end{align}
%
where $N(0)$ is the density of states per spin and per site at the non-interacting Fermi energy $\varepsilon_{\rm F}^0$.
We can also transform the denominator in the present approximation as
%
\begin{align}
I_{\rm d}\approx &\, -\frac{2UT}{{\cal N}_{\rm a}}\sum_{\vec{k}}\frac{1}{(\varepsilon_n^2+\xi_{\bf k}^2)^2}
\notag \\
\approx &\, -2UTN(0)\sum_n  \int_{-\infty}^\infty \frac{d\xi_{\bf k}}{(\varepsilon_n^2+\xi_{\bf k}^2)^2}
\notag \\
\approx &\, -2UTN(0)\sum_n 2\pi i\frac{-2}{(2i\varepsilon_n)^3}=\frac{-2UN(0)}{(\pi T)^2}\frac{7}{8}\zeta(3)
\notag \\
\approx &\,\frac{-UN(0)}{T_{{\rm c}0}^2}\times 0.213,
\label{I_d}
\end{align}
\end{subequations}
%
where $\zeta(3)\approx 1.202$ is the Riemann $\zeta$ function,
and we have approximated (i) the density of states by the value at the Fermi energy and (ii) $T$ by $T_{{\rm c}0}$.
Substituting Eq.\ (\ref{I_nI_d}) in Eq.\ (\ref{bLambda}) with $T_{{\rm c}0}$ replaced by $T_{1{\rm PR}}$, we obtain
%
\begin{align}
\bar\lambda\approx -4.69T_{1{\rm PR}}(T_{1{\rm PR}}-T) .
\label{bLambda2}
\end{align}
%
The value of $\lambda$ at $T=0.098$ just below $T_{1{\rm PR}}=0.100$ in Fig.\ \ref{fig1} is $1.36\times 10^{-2}$,
whereas Eqs.\ (\ref{bLambda-def}) and (\ref{bLambda2}) yield $\lambda=7.82\times 10^{-3}$ 
for the same set of parameters $(T_{1{\rm PR}},T,\frac{{\cal N}_{\rm e}}{{\cal N}_{\rm a}}U)=(0.100,0.098,-0.12)$.
Thus, we realize that Eq.\ (\ref{bLambda2}) may be used as an order-of-magnitude estimate on how $\lambda$ develops initially.
The origin of the quantitative disagreement may be traced to (i) the complete omission of the self-energy in Green's function and (ii) the assumption of the constant density of states in transforming Eq.\ (\ref{I_d}).

\subsection{Discontinuity of ${\cal C}_V$}

The heat capacity ${\cal C}_V$ is obtained by performing the differentiation of Eq.\ (\ref{calC1}) in terms of Eq.\ (\ref{calE1}).
The discontinuity of  ${\cal C}_V$ at $T=T_{1{\rm PR}}$ in Fig.\ \ref{fig4} is caused by the linear emergence of
$\lambda$ in Fig.\ \ref{fig1}. 
To see this, we start by writing the relevant first-order variation of Eq.\ (\ref{calE1}) caused by the emergence of $\lambda$ as
%
\begin{align}
\delta {\cal E} =&\, 2T\sum_{\vec{k}}\biggl\{\left[\xi_{\bf k}+\mu+\frac{1}{2}\Sigma(\vec{k})\right]\delta G_\lambda(\vec{k})
\notag \\
&\, \hspace{10mm}+\frac{1}{2}G(\vec{k})\delta\Sigma_\lambda (\vec{k})\biggr\},
\label{deltaG1}
\end{align}
%
where we have used the fact that $\xi_{\bf k}+\mu\propto k^2$ is the kinetic energy independent of $\lambda$ and $\mu$.
The contribution of $\mu$ in Eq.\ (\ref{deltaG1}) can be omitted due to
the condition of the fixed electron number 
%
\begin{align}
2T\sum_{\vec{k}}\delta G_\lambda(\vec{k})=0 .
\end{align}
%
We subsequently express 
%
\begin{subequations}
\begin{align}
\delta G_\lambda(\vec{k}) =&\, -\bigl[G(\vec{k})\bigr]^2 \bigl[\delta \mu-\delta\Sigma_\lambda(\vec{k})\bigr],
\\
\frac{1}{2}=&\,\frac{1}{2}\bigl[i\varepsilon_n-\xi_{\bf k}-\Sigma(\vec{k})\bigr] G(\vec{k}),
\end{align}
\end{subequations}
%
based on Dyson's equation.
We can thereby transform Eq.\ (\ref{deltaG1}) into
%
\begin{align}
\delta {\cal E} =&\, 2T\sum_{\vec{k}}\biggl\{-\left[\xi_{\bf k}+\frac{1}{2}\Sigma_\lambda(\vec{k})\right]\bigl[G(\vec{k})\bigr]^2\delta\mu
\notag \\
&\,+\frac{i\varepsilon_n+\xi_{\bf k}}{2}\bigl[G(\vec{k})\bigr]^2\delta\Sigma_\lambda (\vec{k})\biggr\}.
\label{deltaG2}
\end{align}
%
We now approximate 
%
\begin{align}
\delta\Sigma_\lambda (\vec{k})\approx G(-\vec{k})\delta \bar\lambda,
\end{align}
%
based on Eq.\ (25) of Ref.\ \onlinecite{Kita25} by neglecting the vertex correction to $\delta\Sigma_\lambda$,
where $\bar\lambda$ is defined by Eq.\ (\ref{bLambda-def}).
We then replace $G$ by $G_0$ in Eq.\ (\ref{deltaG2}) and omit the self-energy contribution accordingly.
The resulting $\delta {\cal E}$ can be transformed as
%
\begin{align}
\delta {\cal E} \approx &\, 2T\sum_{\vec{k}}\biggl\{-\xi_{\bf k}\delta\mu
+\frac{i\varepsilon_n+\xi_{\bf k}}{2}G_0(-\vec{k})\delta\bar\lambda\biggr\}\bigl[G_0(\vec{k})\bigr]^2
\notag \\
=&\, 2\sum_{{\bf k}}\biggl(-\xi_{\bf k}\delta\mu
+\frac{1}{2}\delta\bar\lambda\biggr)\frac{\partial\bar{n}(\xi_{\bf k})}{\partial\xi_{\bf k}}
\notag \\
=&\, -{\cal N}_{\rm a} N(0) \delta\bar\lambda,
\label{deltaG3}
\end{align}
%
where $N(0)$ is the density of states per spin and per site at the Fermi energy, $\bar{n}(\xi_{\bf k})=(e^{\xi_{\bf k}/T}+1)^{-1}$ is the Fermi distribution function, and we have approximated
%
\begin{align}
\frac{\partial\bar{n}(\xi_{\bf k})}{\partial\xi_{\bf k}}\approx-\delta(\xi_{\bf k}),
\end{align}
%
as appropriate at low temperatures.
Substituting Eq.\ (\ref{bLambda2}) in Eq.\ (\ref{deltaG3}) and performing the differentiation of Eq.\ (\ref{calC1})
at $T=T_{1{\rm PR}}$, 
we obtain the discontinuity of the heat capacity as
%
\begin{align}
\varDelta {\cal C}_V\approx -{\cal N}_{\rm a} N(0)\frac{d\bar\lambda}{dT}\biggr|_{T=T_{1{\rm PR}}}\approx 
4.69 T_{1{\rm PR}}{\cal N}_{\rm a} N(0) .
\label{deltaC-analytic}
\end{align}
%
This value is about $0.713$ times the heat capacity
%
$${\cal C}_{V0}=\frac{2\pi^2}{3}T_{1{\rm PR}}{\cal N}_{\rm a} N(0)$$
%
of the corresponding non-interacting electron gas.
The discontinuity of $C_V$ at $T=T_{1{\rm PR}}$ in Fig.\ \ref{fig4} is $7.8\times 10^{-3}$,
whereas Eq.\ (\ref{deltaC-analytic}) yields $1.2\times 10^{-2}$ for the set of parameters
$(T_{1{\rm PR}},\frac{N(0)}{V_{\rm unit}})=(0.100,\frac{1}{4\pi^2})$.
Thus, Eq.\ (\ref{deltaC-analytic}) obtained through several crude approximations 
yields an order-of-magnitude estimate for the magnitude of the discontinuity.

