\subsection{{{\bf The MFG under exponential utility criterion}}}\label{Themfg}
In this subsection, we revise the financial model to construct the Mean Field Game (MFG) under the exponential utility criterion, assuming an infinite number of fund managers. In this case, the parameters of the fund managers are treated as random variables. To formulate the MFG, we now assume that the probability space $(\Omega, \mathcal{F}, \mathbb{P})$ supports an additional independent one-dimensional Brownian motion $W$, as well as a random variable (referred to as the type vector)
\begin{eqnarray}
	\phi = \left(\delta,\theta,\widehat{\mu},\widehat{\sigma},\widehat{\nu}\right)\nonumber
\end{eqnarray}
with the values in the space $\left(0,+\infty\right)\times\left[0,1\right)\times\left(0,+\infty\right)\times\mathbb{R}\times\left(0,+\infty\right)$, which is independent of $W$ and $B$. The distribution of this random variable $\phi$ is called the type distribution. In fact, $\left(\delta,\theta,\widehat{\mu},\widehat{\sigma},\widehat{\nu}\right)$ is exactly the randomization of the parameters $\left(\delta_k,\theta_k,\mu_k,\sigma_k,\nu_k\right)$ of a particular fund manager. The fund manager with type vector $\phi$ can invest in $S^0$, $S^*$, and its exclusive asset $\widehat{S}$ satisfying
\begin{eqnarray}
	\frac{\rd \widehat{S}_t}{\widehat{S}_t} &=& \left(\kappa+\widehat{\mu}\right) \rd t + \widehat{\sigma} \rd B_t + \widehat{\nu} dW_t. \nonumber
\end{eqnarray}

{ Let \( \mathcal{F}^{MF} = \left\{ \mathcal{F}^{MF}_t \right\}_{t \in [0, \mathcal{T}]} \) denote the smallest filtration satisfying the usual conditions, such that \( \phi \) is \( \mathcal{F}^{MF}_0 \)-measurable and both \( W \) and \( B \) are adapted. Additionally, let \( \mathcal{F}^{B} = \left\{ \mathcal{F}^{B}_t \right\}_{t \in [0, \mathcal{T}]} \) represent the natural filtration generated by \( B \).}


{ The logarithmic return $\left\{R_t^\pi\right\}_{t\in \left[0,\mathcal{T}\right]}$ of a fund manager with type vector $\phi$ evolves as }
\begin{eqnarray}
	\rd R_t^\pi &=& \left[\left(\kappa + \mu \alpha_t + \widehat{\mu}\beta_t \right) - \frac{1}{2}\left(\sigma \alpha_t + \widehat{\sigma}\beta_t\right)^2 - \frac{1}{2}\left(\widehat{\nu}\beta_t\right)^2\right] \rd t \nonumber \\&&+ \left(\sigma \alpha_t + \widehat{\sigma}\beta_t \right) \rd B_t + \widehat{\nu}\beta_t \rd W_t,\label{Rt}\\
	R_0^\pi &=& 0.\nonumber
\end{eqnarray}
A strategy $\pi=\left(\alpha,\beta\right)$ is admissible if it is $\mathcal{F}^{MF}$ progressively measurable and satisfies {
\begin{eqnarray}
	\mathbb{E}\int_{0}^{\mathcal{T}}\left(\alpha^{2}_t+\beta^{2}_t\right) \rd t < \infty.\label{admissible}
\end{eqnarray} 
For an admissible strategy \( \eta \), define the \( \mathcal{F}^{B}_\mathcal{T} \)-measurable random process \( \left\{ \overline{R}_t = \mathbb{E}\left[ R^{\eta}_t \mid \mathcal{F}^{B}_\mathcal{T} \right] \right\}_{t \in [0, \mathcal{T}]} \), where \( \left\{ R^{\eta}_t \right\}_{t \in [0, \mathcal{T}]} \) is the logarithmic return process given by Eq.~(\ref{Rt}) corresponding to the strategy \( \eta \). For a fixed \( \eta \), the representative fund manager does not influence \( \overline{R} \), as they are just one fund manager in a continuum.

For any admissible strategy \( \pi \), define the excess logarithmic return process \( \{ Z_t := R^{\pi}_t - \theta \overline{R}_t \}_{t \in [0, \mathcal{T}]} \). The objective of the representative fund manager is to maximize the expected exponential utility of the excess logarithmic return at the terminal time \( Z_\mathcal{T} = R_\mathcal{T}^\pi - \theta \overline{R}_\mathcal{T} \):
\begin{eqnarray}
	J\left(\pi\right):=\mathbb{E}\left\{-\exp\left[-\frac{1}{\delta}Z_\mathcal{T}\right]\right\}.\label{Jpi}
\end{eqnarray} }

\begin{definition}\label{MFE}

	{
An admissible strategy \( \pi^* \) is a mean-field equilibrium (MFE) if it is optimal for the optimization problem of maximizing \( J(\pi) \), as shown in Eq.~(\ref{Jpi}), with \( \overline{R}_t = \mathbb{E}\left[ R^{\pi^*}_t \mid \mathcal{F}^{B}_\mathcal{T} \right] \) for \( t \in [0, \mathcal{T}] \).

A constant MFE is an \( \mathcal{F}^{MF}_0 \)-measurable two-dimensional random variable \( \pi^* \) such that \( \pi_t = \pi^* \) for \( t \in [0, \mathcal{T}] \), and this is also a MFE.
    }
\end{definition}

\begin{theorem}\label{the2}
	There exists a unique constant MFE, given by
	\begin{eqnarray}
		\alpha^*&=&\frac{\delta\widehat{\sigma}\left(\mu\widehat{\sigma}-\widehat{\mu}\sigma\right)}{\left(1+\delta\right)\sigma^2\widehat{\nu}^2}+\frac{\mu\delta+\theta\mu L}{\left(1+\delta\right)\sigma^2},\label{alpha1}\\
		\beta^{*}&=&\frac{\delta\left(\widehat{\mu}\sigma-\mu\widehat{\sigma}\right)}{\left(1+\delta\right)\sigma\widehat{\nu}^2}\label{beta1},\nonumber
	\end{eqnarray}
	where $L$ is defined by  Eq.~(\ref{L}).
\end{theorem}

\begin{proof}
	See Appendix \ref{proof2}.
\end{proof}
\begin{remark}
	The constant MFE $\left(\alpha^*, \beta^*\right)$ has the same expression as in Eqs.~(\ref{limit2}) and (\ref{limit1}), which represents the limit of the equilibrium strategy in Definition \ref{def1} as the number of fund managers approaches infinity.
\end{remark}
\begin{remark}
	By setting $\theta = 0$, we obtain the optimal investment ratio for an optimization problem without competition, which reveals some interesting phenomena. The { allocation fraction} of investment in the private risky asset, $\beta^*$, is unaffected by competition and reflects the optimal result of the optimization problem. Conversely, the { allocation fraction} invested in the public risk asset, $\alpha^*$, can be divided into two components: one that disregards competition and one that addresses competitive risk.
\end{remark}


\vskip 10pt
\section{{{\bf Mean-Variance criterion}}} \label{Mean-Variance criterion}
\vskip 5pt
In this section, we assume that each fund manager has a mean-variance preference for the excess logarithmic return, so the payoff of the $k$-th fund manager is given by { 
\begin{eqnarray}
	J_k\left(\pi^k;\pi^{-k}|t,r_1,\cdots,r_n\right):=\mathbb{E}_t\left(R^{k,\pi^k}_\mathcal{T}-\frac{\theta_k}{n}\sum_{i=1}^{n}R^{i,\pi^i}_\mathcal{T}\right)-\frac{\gamma_k}{2}\mathbb{V}_t\left(R^{k,\pi^k}_\mathcal{T}-\frac{\theta_k}{n}\sum_{i=1}^{n}R^{i,\pi^i}_\mathcal{T}\right),\nonumber 
\end{eqnarray} }
where $\gamma_k > 0$ is the risk aversion parameter for the $k$-th fund manager, and $\mathbb{E}_t$ and $\mathbb{V}_t$ represent the conditional expectation and conditional variance given the condition $\left(R^{1,\pi^1}_t, \cdots, R^{n,\pi^n}_t\right) = \left(r_1, \cdots, r_n\right)$.

The mean-variance criterion is time-inconsistent, meaning Bellman's principle does not hold and the standard stochastic dynamic programming method cannot be applied. To address this time-inconsistent game, we adopt the time-consistent Nash equilibrium strategy proposed by \cite{bjork2017time}. We require that, at any moment, a fund manager unilaterally changing the investment strategy will not achieve better results in the very short term. The time-consistent equilibrium and the constant time-consistent equilibrium are defined strictly below.


\begin{definition}\label{def2}
	{ A strategy $\left(\pi^{1},\cdots,\pi^{n}\right)$ is admissible if, for any $k=1,\cdots,n$, $\pi^k$ is $\{\mathcal{F}_t\}_{0\leq t\leq \mathcal{T}} $ progressively measurable and satisfies
	\begin{eqnarray}
		\mathbb{E}\int_{0}^{\mathcal{T}}\left(\alpha^{k2}_t+\beta^{k2}_t\right) \rd t < +\infty.
	\end{eqnarray}

	An admissible strategy $\left(\pi^{1,*},\cdots,\pi^{n,*}\right)$ is a time-consistent equilibrium if, for any $k=1,\cdots,n$, any fixed initial state $\left(t, r_1, \cdots, r_n\right) \in [0, \mathcal{T}] \times \mathbb{R}^n$, and any admissible strategy $u$ of the $k$-th fund manager, }
	\begin{eqnarray}
		\liminf_{h\rightarrow 0^+} \frac{J_k\left(\pi^{k,*};\pi^{-k,*}|t,r_1,\cdots,r_n\right)-J_k\left(\pi^{k,h,u};\pi^{-k,*}|t,r_1,\cdots,r_n\right)}{h}\ge 0,\nonumber
	\end{eqnarray}
	where $\pi^{k,h,u}$ is defined by { 
	\begin{eqnarray}
		\pi^{k,h,u}_s:=\left\{
		\begin{aligned}
			&u_s,\quad\qquad t\le s < t+h,\\
			&\pi^{k,*}_s, \quad t+h\le s\le \mathcal{T}
		\end{aligned}
		\right.\nonumber
	\end{eqnarray} }
	with any $h\in\mathbb{R}^{+}$.


A constant time-consistent equilibrium is a time-consistent equilibrium in which, for each $k$, $\alpha^{k,*}$ and $\beta^{k,*}$ are constants over time.
\end{definition}
\begin{theorem}\label{the3}
	There exists a unique constant time-consistent equilibrium, given by
	\begin{eqnarray}
		\alpha^{k,*}&=&\frac{\sigma_k\left(\mu\sigma_k-\mu_k\sigma\right)}{\left(1+\gamma_k-\frac{\gamma_k\theta_k}{n}\right)\sigma^2\nu_k^2}+\frac{\mu+\theta_k\sigma K}{\left(1+\gamma_k\right)\sigma^2},\quad k=1,\cdots,n,\label{alp2}\\
		\beta^{k,*}&=&\frac{\mu_k\sigma-\mu\sigma_k}{\left(1+\gamma_k-\frac{\gamma_k\theta_k}{n}\right)\sigma\nu_k^2},\quad k=1,\cdots,n,\label{bet2}
	\end{eqnarray}
	where
	\begin{eqnarray}
		K:= \frac{\frac{1}{n}\sum_{i=1}^{n}\frac{1}{1+\gamma_k}\frac{\mu}{\sigma}}{1-\frac{1}{n}\sum_{i=1}^{n}\frac{\gamma_k\theta_k}{1+\gamma_k}}.\label{K1}
	\end{eqnarray}
\end{theorem}

\begin{proof}
	See Appendix \ref{proof3}.
\end{proof}



\subsection{{{\bf Analysis about the constant time-consistent equilibrium $\left(\alpha^{k,*},\beta^{k,*}\right)$}}}
Similar to Section \ref{Exponential utility}, both the { allocation fraction} $\alpha^{k,*}$ of the investment in $S^*$ and the { allocation fraction} $\beta^{k,*}$ of the investment in $S^k$ are constant. The { allocation fraction} $\alpha^{k,*}$ is influenced by the parameters of other investment managers, including the competition weight parameter $\theta_i$ (for $i \neq k$) and the risk aversion coefficient $\delta_i$ (for $i \neq k$), but does not depend on the parameters associated with the risky assets $S^i$ (for $i \neq k$). In contrast, $\beta^{k,*}$ is not affected by the parameters of other investment managers but is influenced by its own competition weight parameter $\theta_k$. We also consider three cases: case 1, case 2, and case 3, as detailed in Section \ref{Exponential utility}.

{ Similar to Subsection \ref{infity_case}, we can formally obtain the result (the detailed process, including the definition of the type vector, type distribution, and weak convergence of measures, is omitted here):
\begin{eqnarray}
	\beta^{k,*}_{\infty}&:=&\lim\limits_{n\rightarrow +\infty}\beta^k =\frac{\mu_k\sigma-\mu\sigma_k}{\left(1+\gamma_k\right)\sigma\nu_k^2},\label{lim1}\\
	\alpha^{k,*}_{\infty}&:=&\lim\limits_{n\rightarrow +\infty}\alpha^{k} =\frac{\sigma_k\left(\mu\sigma_k-\mu_k\sigma\right)}{\left(1+\gamma_k\right)\sigma^2\nu_k^2}+\frac{\mu+\theta_k\mu R}{\left(1+\gamma_k\right)\sigma^2},\label{lim2}
\end{eqnarray}
where
\begin{eqnarray}
	R := \frac{\mathbb{E}\frac{1}{1+\gamma}}{1-\mathbb{E}\frac{\gamma\theta}{1+\gamma}},\label{R}
\end{eqnarray}
which is the same as Eqs.~ (\ref{limit1}) and (\ref{limit2}).}

%% In Eq.~(\ref{R}), for finite $n$, we define $\mathbb{E}\left[\frac{1}{1+\gamma}\right]$ as $\frac{1}{n}\sum_{i=1}^{n} \frac{1}{1+\gamma_i}$ and $\mathbb{E}\left[\frac{\gamma \theta}{1+\gamma}\right]$ as $\frac{1}{n}\sum_{i=1}^{n} \frac{\gamma_i \theta_i}{1+\gamma_i}$. As $n$ approaches $\infty$, we consider $\theta$ and $\gamma$ to be random variables, where $\theta_i$ (for $i=1, \cdots, n$) are independently and identically distributed with distribution $\theta$, and $\gamma_i$ (for $i=1, \cdots, n$) are independently and identically distributed with distribution $\gamma$. By the law of large numbers, $\mathbb{E}\frac{1}{1+\gamma} = \lim\limits_{n\rightarrow +\infty}\frac{1}{n}\sum_{i=1}^{n}\frac{1}{1+\gamma_k}$ and $\mathbb{E}\frac{\gamma\theta}{1+\gamma} = \lim\limits_{n\rightarrow +\infty}\frac{1}{n}\sum_{i=1}^{n}\frac{\gamma_k\theta_k}{1+\gamma_k}$.

{
The remainder of this section is organized as follows. First, we will examine the impact of one's own parameters. For more complex scenarios, numerical analysis and plotting will be required. Next, we will explore the influence of the parameters of other fund managers. Since the results in this section closely mirror those in Subsection \ref{analysis1}, we will only present the formulas and plots, providing explanations and notes only when necessary. Additionally, we will observe that the conclusions of Remark \ref{remark_new} also apply here.
}

The { allocation fraction} of the investment in $S^k$ denoted $\beta^{k,*}$, is also a modification of the equilibrium solution to the classical optimization problem without competition. We have
\begin{eqnarray}
	\frac{\partial\beta^{k,*}}{\partial\theta_k}&=&\frac{\gamma_k\left(\mu_k\sigma-\mu\sigma_k\right)}{n\left(1+\gamma_k-\frac{\gamma_k\theta_k}{n}\right)^2\sigma\nu_k^2},
\end{eqnarray}
which is the same as Eq.~ (\ref{partial1}).

In addition, 
\begin{eqnarray}
	&&\frac{\partial\beta^{k,*}}{\partial\mu}=\frac{-\sigma_k}{\left(1+\gamma_k-\frac{\gamma_k\theta_k}{n}\right)\sigma\nu_k^2},\qquad
	\frac{\partial\beta^{k,*}}{\partial\sigma}=\frac{\mu\sigma_k}{\left(1+\gamma_k-\frac{\gamma_k\theta_k}{n}\right)\sigma^2\nu_k^2},\nonumber\\
	&&\frac{\partial\beta^{k,*}}{\partial\mu_k}=\frac{1}{\left(1+\gamma_k-\frac{\gamma_k\theta_k}{n}\right)\nu_k^2},\qquad\;\;\;
	\frac{\partial\beta^{k,*}}{\partial\sigma_k}=\frac{-\mu}{\left(1+\gamma_k-\frac{\gamma_k\theta_k}{n}\right)\sigma\nu_k^2},\nonumber\\
	&&\frac{\partial\beta^{k,*}}{\partial\nu_k}=\frac{-2\left(\mu_k\sigma-\mu\sigma_k\right)}{\left(1+\gamma_k-\frac{\gamma_k\theta_k}{n}\right)\sigma\nu_k^3},\qquad
	\frac{\partial\beta^{k,*}}{\partial\gamma_k}=\frac{\left(1-\frac{\theta_k}{n}\right)\left(\mu_k\sigma-\mu\sigma_k\right)}{\left(1+\gamma_k-\frac{\gamma_k\theta_k}{n}\right)^2\sigma\nu_k^2},\nonumber
\end{eqnarray}
and
\begin{eqnarray}
	\frac{\partial\alpha^{k,*}}{\partial\mu}&=&\frac{\sigma_k^2}{\left(1+\gamma_k-\frac{\gamma_k\theta_k}{n}\right)\sigma^2\nu_k^2}+\frac{1}{\left(1+\gamma_k\right)\sigma^2}+\frac{\theta_k}{\left(1+\gamma_k\right)\sigma^2}\frac{\frac{1}{n}\sum_{j=1}^{n}\frac{1}{1+\gamma_j}}{1-\frac{1}{n}\sum_{j=1}^{n}\frac{\gamma_j\theta_j}{1+\gamma_j}},\nonumber\\
	\frac{\partial\alpha^{k,*}}{\partial\sigma}&=&\frac{-2\mu\sigma_k^2+\mu_k\sigma_k\sigma}{\left(1+\gamma_k-\frac{\gamma_k\theta_k}{n}\right)\sigma^3\nu_k^2}-\frac{2\mu}{\left(1+\gamma_k\right)\sigma^3}-\frac{2\mu\theta_k}{\left(1+\gamma_k\right)\sigma^3}\frac{\frac{1}{n}\sum_{j=1}^{n}\frac{1}{1+\gamma_j}}{1-\frac{1}{n}\sum_{j=1}^{n}\frac{\gamma_j\theta_j}{1+\gamma_j}},\nonumber\\
	\frac{\partial\alpha^{k,*}}{\partial\mu_k}&=&\frac{-\sigma_k}{\left(1+\gamma_k-\frac{\gamma_k\theta_k}{n}\right)\sigma\nu_k^2},\nonumber\\
	\frac{\partial\alpha^{k,*}}{\partial\sigma_k}&=&\frac{2\mu\sigma_k-\mu_k\sigma}{\left(1+\gamma_k-\frac{\gamma_k\theta_k}{n}\right)\sigma^2\nu_k^2},\nonumber\\
	\frac{\partial\alpha^{k,*}}{\partial\nu_k}&=&\frac{-2\sigma_k\left(\mu\sigma_k-\mu_k\sigma\right)}{\left(1+\gamma_k-\frac{\gamma_k\theta_k}{n}\right)\sigma^2\nu_k^3},\nonumber\\
	\frac{\partial\alpha^{k,*}}{\partial\theta_k}&=&\frac{\gamma_k\sigma_k\left(\mu\sigma_k-\mu_k\sigma\right)}{n\left(1+\gamma_k-\frac{\gamma_k\theta_k}{n}\right)^2\sigma^2\nu_k^2}+\frac{\mu}{\left(1+\gamma_k\right)\sigma^2}\frac{\frac{1}{n}\sum_{j=1}^{n}\frac{1}{1+\gamma_j}}{1-\frac{1}{n}\sum_{j=1}^{n}\frac{\gamma_j\theta_j}{1+\gamma_j}}\nonumber\\
	&&+\frac{\gamma_k\mu\theta_k}{n\left(1+\gamma_k\right)^2\sigma^2}\frac{\frac{1}{n}\sum_{j=1}^{n}\frac{1}{1+\gamma_j}}{\left(1-\frac{1}{n}\sum_{j=1}^{n}\frac{\gamma_j\theta_j}{1+\gamma_j}\right)^2}.
\end{eqnarray}
The signs of these partial derivatives are consistent with those in Eqs.~(\ref{partial2}) and (\ref{partial5}). Therefore, the sensitivity analysis of the parameters $\mu$, $\sigma$, $\mu_k$, $\sigma_k$, $\nu_k$, $\gamma_k$, and $\theta_k$ with respect to $\beta_k$, as well as the sensitivity analysis of the parameters $\mu$, $\sigma$, $\mu_k$, $\sigma_k$, $\nu_k$, and $\theta_k$ with respect to $\alpha_k$, are the same as those discussed in Section \ref{Exponential utility}.

