\section{Proof of Theorem \ref{the1}.}\label{proof1}

\begin{proof}
	First, the strategies of the other fund managers are fixed and only the $k$-th fund manager's optimization problem is considered. The $k$-th fund manager's strategy $\pi^{k,*}$ in equilibrium, is optimal for this optimization problem. Notice that { 
	\begin{eqnarray}
		R^k_\mathcal{T}-\frac{\theta_k}{n}\sum_{i=1}^{n}R^i_\mathcal{T} = \left(1-\frac{\theta_k}{n}\right)R^k_\mathcal{T}-\theta_k\frac{1}{n}\sum_{i\neq k}R^i_\mathcal{T},\label{eq1}
	\end{eqnarray} }
	and define
	\begin{eqnarray}
		Y_t:=\frac{1}{n}\sum_{i\neq k}R^i_t.\label{eq2}
	\end{eqnarray}
Then, the optimization problem of the $k$-th fund manager becomes {
	\begin{eqnarray}
		v\left(t,r,y\right):=\sup_{\pi^k}\mathbb{E}\left\{-\exp\left[-\frac{1}{\delta_k}\left(\left(1-\frac{\theta_k}{n}\right)R^k_\mathcal{T}-\theta_kY_\mathcal{T}\right)\right]\bigg|\left(R^k_t,Y_t\right)=\left(r,y\right)\right\}.\nonumber
	\end{eqnarray}
The processes $\{R^k_t\}_{t\in\left[0,\mathcal{T}\right]}$ and $\{Y_t\}_{t\in\left[0,\mathcal{T}\right]}$ evolve as }
\begin{eqnarray}
\!\! \!\!	\!\!	\!\!			\rd R^k_t &=& \left(\kappa + \pi^{kT}_t \tilde{\mu}_k   - \frac{1}{2}\pi^{kT}_t\tilde{\sigma}_k\tilde{\sigma}_k^T\pi^{k}_t - \frac{1}{2}\pi^{kT}_t\tilde{\nu}_k\tilde{\nu}_k^T\pi^{k}_t\right) \rd t +  \pi^{kT}_t\tilde{\sigma}_k \rd B_t + \pi^{kT}_t\tilde{\nu}_k \rd W^k_t,\label{r1}\\
		\rd Y_t &=& \left[\frac{n-1}{n}\kappa + \frac{1}{n}\sum_{i\neq k}\pi^{iT}_t \tilde{\mu}_i   - \frac{1}{2n}\sum_{i\neq k}\pi^{iT}_t\left(\tilde{\sigma}_i\tilde{\sigma}_i^T+\tilde{\nu}_i\tilde{\nu}_i^T\right)\pi^{i}_t\right] \rd t \nonumber \\
		&&+  \left(\frac{1}{n}\sum_{i\neq k}\pi^{iT}_t\tilde{\sigma}_i\right) \rd B_t + \frac{1}{n}\sum_{i\neq k}\pi^{iT}_t\tilde{\nu}_i \rd W^i_t, \label{y1}
	\end{eqnarray}
	where 
	$$ \tilde{\mu}_k := \begin{pmatrix}
		\mu \\ \mu_k
	\end{pmatrix},\quad \tilde{\sigma}_k := \begin{pmatrix}
		\sigma \\ \sigma_k
	\end{pmatrix}, \quad \tilde{\nu}_k := \begin{pmatrix}
		0 \\ \nu_k
	\end{pmatrix} .$$

	Assume that the strategies of other fund managers are constant, i.e., $\pi^i_t\equiv \pi^i, \forall i \neq k$.  Define
	\begin{eqnarray}
		A &=& \frac{n-1}{n}\kappa + \frac{1}{n}\sum_{i\neq k}\pi^{iT} \tilde{\mu}_i   - \frac{1}{2n}\sum_{i\neq k}\pi^{iT}\left(\tilde{\sigma}_i\tilde{\sigma}_i^T+\tilde{\nu}_i\tilde{\nu}_i^T\right)\pi^{i},\nonumber\\
		B &=& \frac{1}{n}\sum_{i\neq k}\pi^{iT}\tilde{\sigma}_i,\label{B1}\\
		C &=& \frac{1}{n^2}\sum_{i\neq k}\pi^{iT}\tilde{\nu}_i\tilde{\nu}_{iT}\pi^i.\nonumber
	\end{eqnarray}
Then	the HJB equation of this optimization problem is {
	\begin{eqnarray}
		&&v_t+\max_{\pi\in\mathbb{R}^2}\left\{\left[\kappa+\pi^T\tilde{\mu}_k-\frac{1}{2}\pi^T\left(\tilde{\sigma}_k\tilde{\sigma}_k^T+\tilde{\nu}_k\tilde{\nu}_k^T\right)\pi\right]v_r+\frac{1}{2}\pi^T\left(\tilde{\sigma}_k\tilde{\sigma}_k^T+\tilde{\nu}_k\tilde{\nu}_k^T\right)\pi v_{rr}\right.\nonumber\\
		&&\qquad\qquad\qquad\qquad\qquad\qquad\qquad+\left.Av_y+B\pi^T\tilde{\sigma}_kv_{ry}+\frac{1}{2}\left(B^2+C\right)v_{yy}\right\}=0,\nonumber\\
		&&v(\mathcal{T},r,y) = -\exp\left[-\frac{1}{\delta_k}\left(\left(1-\frac{\theta_k}{n}\right)r-\theta_ky\right)\right].\nonumber
	\end{eqnarray} }
	For this classical optimization problem, the maximum point
	\begin{eqnarray}\label{pi1}
		\pi^{k,*}=-\frac{1}{v_{rr}-v_r}\left(\tilde{\sigma}_k\tilde{\sigma}_k^T+\tilde{\nu}_k\tilde{\nu}_k^T\right)^{-1}\left(\tilde{\mu}_kv_r+B\tilde{\sigma}_kv_{ry}\right)
	\end{eqnarray}
	is the optimal strategy of the $k$-th fund manager, then the HJB equation becomes { 
	\begin{eqnarray} \label{HJB1}
		&&v_t \! + \! Av_y \! + \! \frac{1}{2}\left(B^2 \! + \! C\right)v_{yy} \! - \! \frac{1}{2\left(v_{rr} \! - \! v_r\right)}\left(\tilde{\mu}_kv_r+B\tilde{\sigma}_kv_{ry}\right)^T\!\left(\tilde{\sigma}_k\tilde{\sigma}_k^T+\tilde{\nu}_k\tilde{\nu}_k^T\right)^{-1}\!\left(\tilde{\mu}_kv_r+B\tilde{\sigma}_kv_{ry}\right)=0,\nonumber\\
		&&v(\mathcal{T},r,y) = -\exp\left[-\frac{1}{\delta_k}\left(\left(1-\frac{\theta_k}{n}\right)r-\theta_ky\right)\right].
	\end{eqnarray} }
	The HJB equation (\ref{HJB1}) has a unique solution of the form $v=f\left(t\right)g\left(r,y\right)$, which means that $\pi^{k,*}$ is a constant, and the solution is { 
	\begin{eqnarray}
		v=-\exp\left[-\frac{1}{\delta_k}\left(\left(1-\frac{\theta_k}{n}\right)r-\theta_ky\right)-\rho\left(\mathcal{T}-t\right)\right]\nonumber
	\end{eqnarray} }
	with
	\begin{eqnarray}
		\rho=-A\frac{\theta_k}{\delta_k}-\frac{1}{2}\left(B^2+C\right)\frac{\theta_k^2}{\delta_k^2}+\frac{1-\frac{\theta_k}{n}}{2\left(1-\frac{\theta_k}{n}+\delta_k\right)}\left(\tilde{\mu}_k+B\frac{\theta_k}{\delta_k}\tilde{\sigma}_k\right)^T\!\left(\tilde{\sigma}_k\tilde{\sigma}_k^T+\tilde{\nu}_k\tilde{\nu}_k^T\right)^{-1}\!\left(\tilde{\mu}_k+B\frac{\theta_k}{\delta_k}\tilde{\sigma}_k\right).\nonumber
	\end{eqnarray}

	Define two matrices
	\begin{eqnarray}
  M &:=& \tilde{\sigma}_k\tilde{\sigma}_k^T+\tilde{\nu}_k\tilde{\nu}_k^T=\begin{pmatrix}
			\sigma^2 & \sigma\sigma_k\\\sigma\sigma_k & \sigma_k^2+\nu_k^2
		\end{pmatrix},\label{M1}\\
		N &:=&\begin{pmatrix}
			\sigma_k^2+\left(1-\frac{\theta_k}{n\left(1+\delta_k\right)}\right)\nu_k^2 & -\sigma\sigma_k\\-\sigma\sigma_k & \sigma^2
		\end{pmatrix},\nonumber
	\end{eqnarray}
	and
	\begin{eqnarray}
		E:=\frac{1}{n}\sum_{i\neq k}\pi^{iT}\tilde{\sigma}_i+\frac{1}{n}\pi^{*T}\tilde{\sigma}_k.\label{E1}
	\end{eqnarray}
	 Then the maximum point (\ref{pi1}) can be rewritten as
	\begin{eqnarray}
		\pi^{k,*}&=&\frac{1}{1-\frac{\theta_k}{n}+\delta_k}M^{-1}\left(\delta_k\tilde{\mu}_k+B\theta_k\tilde{\sigma}_k\right)\nonumber\\
		&=&\frac{1}{1-\frac{\theta_k}{n}+\delta_k}M^{-1}\left(\delta_k\tilde{\mu}_k+E\theta_k\tilde{\sigma}_k\right)-\frac{\theta_k}{n\left(1-\frac{\theta_k}{n}+\delta_k\right)}M^{-1}\tilde{\sigma}_k\tilde{\sigma}_k^T\pi^{k,*}.\nonumber
	\end{eqnarray}
	Thus
	\begin{eqnarray}
		\pi^{k,*}&=&\left[\left(1-\frac{\theta_k}{n}+\delta_k\right)I+\frac{\theta_k}{n}M^{-1}\tilde{\sigma}_k\tilde{\sigma}_k^T\right]^{-1}M^{-1}\left(\delta_k\tilde{\mu}_k+E\theta_k\tilde{\sigma}_k\right)\nonumber\\
		&=& \left[M\begin{pmatrix}
			1+\delta_k & \frac{\theta_k\sigma_k}{n\sigma}\\0 & 1+\delta_k-\frac{\theta_k}{n}
		\end{pmatrix}\right]^{-1}\left(\delta_k\tilde{\mu}_k+E\theta_k\tilde{\sigma}_k\right)\nonumber\\
		&=& \frac{1}{\left(1+\delta_k-\frac{\theta_k}{n}\right)\sigma^2\nu_k^2}N\left(\delta_k\tilde{\mu}_k+E\theta_k\tilde{\sigma}_k\right).\label{0pi2}
	\end{eqnarray}

{
	A standard verification argument as in Theorem 3.5.2 of \cite{pham2009continuous} or Theorem III.8.1 of \cite{fleming2006controlled} establishes the optimality of the strategies  $\pi^{k,*}$ derived above. Uniqueness follows from the same verification arguments using the strict concavity of the objective functions. 
}

	Next, consider that each fund manager achieves the optimum, that is, $\left(\pi_1^*,\cdots,\pi_n^*\right)$ is an equilibrium. { From the previous discussion, we can conclude that $\pi^{k,*}$ takes the form given in Eq.~(\ref{0pi2}) for any $k$.} Then $E=\frac{1}{n}\sum_{i=1}^{n}\tilde{\sigma}_i^T\pi^{i,*}$, and we have
	\begin{eqnarray}
		\tilde{\sigma}_k^T\pi^{k,*}=\frac{\delta_k}{1+\delta_k}\frac{\mu}{\sigma}+\frac{\theta_k}{1+\delta_k}E,\quad k=1,\cdots,n.\nonumber
	\end{eqnarray}
	Further,
	\begin{eqnarray}
		E=\frac{1}{n}\sum_{i=1}^{n}\tilde{\sigma}_i^T\pi^{i,*}=\frac{1}{n}\sum_{i=1}^{n}\frac{\delta_k}{1+\delta_k}\frac{\mu}{\sigma}+\frac{1}{n}\sum_{i=1}^{n}\frac{\theta_k}{1+\delta_k}E.\nonumber
	\end{eqnarray}
	Note that $\frac{1}{n}\sum_{i=1}^{n}\frac{\theta_k}{1+\delta_k} <1 $ and then $E$ has the same representation as Eq.~(\ref{D1}), i.e., $E=D$.

	Finally, the equilibrium is given as Eqs.~(\ref{alp1}) and (\ref{bet1}), and the uniqueness follows from the above proof.

\end{proof}
\section{Proof of Theorem \ref{the2}.}\label{proof2}

