		\end{pmatrix}\right]^{-1}\left(\tilde{\mu}_k+E\gamma_k\theta_k\tilde{\sigma}_k\right)\nonumber\\
		&=& \frac{1}{\left(1-\frac{\gamma_k\theta_k}{n}+\gamma_k\right)\sigma^2\nu_k^2}F\left(\tilde{\mu}_k+E\gamma_k\theta_k\tilde{\sigma}_k\right).\nonumber
	\end{eqnarray}
Next, consider that each fund manager achieves their optimum, meaning $\left(\pi_1^*,\cdots,\pi_n^*\right)$ forms a constant time-consistent equilibrium, then
	\begin{eqnarray}
		\tilde{\sigma}_k^T\pi^{k,*}=\frac{1}{1+\gamma_k}\frac{\mu}{\sigma}+\frac{\gamma_k\theta_k}{1+\gamma_k}E,\quad k=1,\cdots,n\nonumber
	\end{eqnarray}
	and
	\begin{eqnarray}
		E=\frac{1}{n}\sum_{i=1}^{n}\tilde{\sigma}_i^T\pi^{i,*}=\frac{1}{n}\sum_{i=1}^{n}\frac{1}{1+\gamma_k}\frac{\mu}{\sigma}+\frac{1}{n}\sum_{i=1}^{n}\frac{\gamma_k\theta_k}{1+\gamma_k}E.\nonumber
	\end{eqnarray}
	Noting that $\frac{1}{n}\sum_{i=1}^{n}\frac{\gamma_k\theta_k}{1+\gamma_k}< 1$ , $E$ has the same representation as Eq.~(\ref{K1}), i.e., $E=K$.

	At last, the equilibrium is given as Eqs.~(\ref{alp2}) and (\ref{bet2}), and the uniqueness follows from the above proof.
\end{proof}
