	{ 
First, for a two-dimensional random variable $\eta$ that is $\mathcal{F}^{MF}_0$-measurable with $\mathbb{E}\|\eta\|^2 < +\infty$, let $\overline{R}_t := \mathbb{E}\left[R^{\eta}_t|\mathcal{F}^{B}_\mathcal{T}\right]$ for $t \in [0, \mathcal{T}]$. Then, the process $\{Z_t\}_{t \in [0, \mathcal{T}]}$ evolves according to Eq.~(\ref{Zt}).


Then,	for any fixed initial state $\left(t,z\right)\in\left[0,\mathcal{T}\right]\times\mathbb{R}$, we have
	\begin{eqnarray}
		\mathbb{E}_t\left[Z_\mathcal{T}\right] &=& z+\int_{t}^{\mathcal{T}}h\left(\pi_s\right)\rd s,\nonumber\\
		\mathbb{V}_t\left[Z_\mathcal{T}\right] &=&\int_{t}^{\mathcal{T}}g\left(\pi_s\right)\rd s,\nonumber\\
	J\left(\pi|\left(t,z\right)\right) &=&  z+\int_{t}^{\mathcal{T}}\left(h\left(\pi_s\right)-\frac{\gamma}{2}g\left(\pi_s\right)\right)\rd s,\nonumber
	\end{eqnarray} }
	where the two functions $h$ and $g$ are defined by
	\begin{eqnarray}
		h\left(\pi\right) &:=& \kappa + \pi^{T} \tilde{\mu}  - \frac{1}{2}\pi^{T}\tilde{\sigma}\tilde{\sigma}^T\pi - \frac{1}{2}\pi^{T}\tilde{\nu}\tilde{\nu}^T\pi-\theta\mathbb{E}\left[\kappa + \eta^{T} \tilde{\mu}   - \frac{1}{2}\eta^{T}\tilde{\sigma}\tilde{\sigma}^T\eta - \frac{1}{2}\eta^{T}\tilde{\nu}\tilde{\nu}^T\eta\right], \nonumber\\
		g\left(\pi\right) &:=& \left(\pi^{T}\tilde{\sigma}-\theta\mathbb{E}\left[\eta^{T}\tilde{\sigma}\right]\right)^2 +  \pi^{T}\tilde{\nu}\tilde{\nu}^T\pi.\nonumber
	\end{eqnarray}
	If $\pi^*$ is a constant time-consistent MFE, form Definition \ref{defination2}, $\eta=\pi^*$ and 
	\begin{eqnarray}
		\pi^*_t\equiv\pi^*=\arg\max_{u}\left\{h\left(u\right)-\frac{\gamma}{2}g\left(u\right)\right\}.\nonumber
	\end{eqnarray}
	Therefore, 
	\begin{eqnarray}
		\pi^*&=&\frac{1}{1+\gamma}\left(\tilde{\sigma}\tilde{\sigma}^T+\tilde{\nu}\tilde{\nu}^T\right)^{-1}\left(\tilde{\mu}+\theta\mathbb{E}\left[\tilde{\sigma}^T\pi^*\right]\tilde{\sigma}\right).\nonumber
	\end{eqnarray}
	Notice that
	\begin{eqnarray}
		\tilde{\sigma}^T\pi^* = \frac{1}{1+\gamma}\tilde{\sigma}^T\left(\tilde{\sigma}\tilde{\sigma}^T+\tilde{\nu}\tilde{\nu}^T\right)^{-1}\left(\tilde{\mu}+\theta\mathbb{E}\left[\tilde{\sigma}^T\pi^*\right]\tilde{\sigma}\right)=\frac{}{1+\gamma}\frac{\mu}{\sigma}+\frac{\theta}{1+\gamma}\mathbb{E}\left[\tilde{\sigma}^T\pi^*\right],\nonumber
	\end{eqnarray}
	then
	{\begin{eqnarray}
		\mathbb{E}\left[\tilde{\sigma}^T\pi^*\right] = \mathbb{E}\left[\frac{1}{1+\gamma}\right]\frac{\mu}{\sigma}+\mathbb{E}\left[\frac{\theta}{1+\delta}\right]\mathbb{E}\left[\tilde{\sigma}^T\pi^*\right].\nonumber
	\end{eqnarray}}
	Thus $\mathbb{E}\left[\tilde{\sigma}^T\pi^*\right] = R\frac{\mu}{\sigma}$,
	where $R$ is shown in Eq.~(\ref{R}). After further analysis, we find that $\alpha^*$ and $\beta^*$ take the forms given in Eqs.~(\ref{alpha2}) and (\ref{beta2}), respectively. The uniqueness then follows from the previous proof.
\end{proof}




