\section{Omitted Material from Preliminaries} %

\begin{definition}[Tree decomposition]\label{def:treeDecomposition}
	A \emph{tree decomposition} of a graph~$G$ is a triple $(T, \beta, r)$, where~$T$ is a tree rooted at node~$r$ and $\beta \colon V(T) \to 2^{V(G)}$ is a mapping that assigns to each node $x$ of the tree its \emph{bag} $\beta(x)$ and satisfies:
	\begin{enumerate}
		\item $\bigcup_{x \in V(T)} \beta(x) = V(G)$;
		\item For every $\{u, v\} \in E(G)$ there exists a node $x \in V(T)$, such that $u, v \in \beta(x)$;
		\item For every $u \in V(G)$ the nodes $\{x \in V(T) \mid u \in \beta(x)\}$ form a connected subtree of~$T$.
	\end{enumerate}
\end{definition}

To distinguish between the vertices of a tree decomposition and the vertices of the underlying graph, we use the term \emph{node} for the vertices of a given tree decomposition.

The \emph{width} of a tree decomposition $(T, \beta, r)$ is $\max_{x \in V(T)} |\beta(x)|-1$.
The \emph{treewidth} of a graph~$G$ (denoted $\tw(G)$) is the minimum width of a~tree decomposition of~$G$ over all such decompositions.

For a tree decomposition $(T, \beta, r)$ and a node $x \in V(T)$, we denote by $\gamma(x)$ the union of vertices in $\beta(x)$ and in~$\beta(y)$ for all descendants~$y$ of~$x$ in~$T$. By $E_x$, we denote the set of edges introduced in the subtree of $T$ rooted in $x$. Altogether, we denote by $G_x$ the graph $(\gamma(x), E_x)$. %

\begin{definition}[Nice tree decomposition~{\cite[p.~168]{CyganFKLMPPS15}}]\label{def:niceTreeDecomposition}
	A tree decomposition of a graph~$G$ is \emph{nice} if $\beta(r) = \emptyset$, and each node $x \in V(T)$ is of one of the following five types:
	\begin{itemize}
		\item \emph{Leaf node}---$x$ has no children and $\beta(x) = \emptyset$;
		\item \emph{Introduce vertex node}---$x$ has exactly one child~$y$ and $\beta(x) = \beta(y) \cup \{u\}$ for some $u \in V(G) \setminus \beta(y)$;
		\item \emph{Introduce edge node}---$x$ has exactly one child~$y$, $\beta(x) = \beta(y)$, and an edge $\{u, v\} \in E(G)$ for $u, v \in \beta(x)$ is introduced (i.e., $E_x = E_y \cup \{\{u,v\}\}$);
		\item \emph{Forget node}---$x$ has exactly one child~$y$ and $\beta(x) = \beta(y) \setminus \{u\}$ for some $u \in \beta(y)$;
		\item \emph{Join node}---$x$ has exactly two children~$y, z$ and $\beta(x) = \beta(y) = \beta(z)$,
	\end{itemize}
	and each edge $e \in E(G)$ is introduced exactly once. %
\end{definition}

We note that any given tree decomposition of width $t$ can be transformed into a nice one of the same width in $O(t^2\cdot n)$ time~\cite[Lemma 7.4, see also the discussion on page 168]{CyganFKLMPPS15}.
}

