We follow standard graph-theoretic notation~\cite{Diestel12}. Also, we refer the reader to~\cite{CyganFKLMPPS15} for a textbook on parameterized complexity.

\noindent \textbf{(Generalized) $N$-fold integer programming ($N$-fold IP)} is the problem of minimizing a separable convex objective (for us it suffices to minimize a linear objective) over a set of constraints of a specific form.
Let $r \in \N$ and $s_i, t_i  \in \N$ for every $i \in [N]$.
The IP has $d = \sum_{i \in [N]} t_i$ variables partitioned into $N$ so-called \emph{bricks}.
The $i$-th brick is denoted $x^{(i)}$ and contains $t_i$ variables.
The constraints have the following form:
\begin{align*}
D_1 x^{(1)} + D_2 x^{(2)} + \cdots + D_N x^{(N)} &= \mathbf{b}_0    &&\text{ \emph{(linking (global) constraints)}}\\%
A_i x^{(i)}                        &= \mathbf{b}_i    & \forall i \in [N] &\text{ \emph{(local constraints)}}\\ %
\mathbf{l}_i \le x^{(i)}                 &\le \mathbf{u}_i  & \forall i \in [N] &\text{ \emph{(box constraints)}}%
\end{align*}
where we have $D_i \in \Z^{r \times t_i}$, $A_i \in \Z^{s_i \times t_i}$, $\mathbf{b}_0 \in \Z^{r}$, $\mathbf{b}_i \in \Z^{s_i}$ and $\mathbf{l}_i,\mathbf{u}_i \in \Z^{t_i}$ for every $i \in [N]$.
Let us denote $s = \max_{i \in [N]} s_i$ and recall that the dimension is $d = \sum_{i \in [N]} t_i$.
%
There are $r$ global constraints and, apart from these, each variable is only involved in at most $s$ local constraints and one box constraint.
We call variables %
not appearing in linking constraints \emph{local}.

The current best algorithm solving the $N$-fold IP in \( (rs\Delta)^{O(r^2s+rs^2)} d\log d \log D \log val_{\max}\) time is by Eisenbrand et al.~\cite[Cor. 97]{EisenbrandHKKLO19}; see also \cite{EisenbrandHK18,KouteckyLO18}, where $D$ is the maximum range of a variable, \mbox{$\Delta = \max_{i \in [N]} \Big( \max \big( \|D_i\|_\infty, \|A_i\|_\infty \big) \Big)$}, and $val_{\max}$ is the maximum feasible value of the objective.

\smallskip

\noindent \textbf{Variants of the problem and basic observations.}
Let us formally introduce the considered problems and establish notation used in the next sections.
\problemQuestion{\DMTSP (\DMTSPshort)}
{A directed graph $G=(V,E)$, edge weights $\wFn \colon E \to \N$, and a budget $\budget \in \N$.}
{Is there a closed directed walk in $G$ of total weight at most $\budget$ that traverses each vertex of $G$ at least once?}%
%
%
%
%
\problemQuestion{\DWRP (\DWRPshort)}
	{A directed graph $G=(V,E)$, set of waypoints $\WP \subseteq V$, edge weights $\wFn \colon E \to \N$, edge capacities $\cFn \colon E \to \N$, budget $\budget \in \N$.}
	{Is there a closed directed walk $C$ in $G$ of total weight at most $\budget$, that traverses each vertex in $\WP$ (at least once) and such that for each edge $e$ the number of times $C$ traverses $e$ is at most $\cFn(e)$?}%
%
To avoid degenerate cases, we assume that $|W|$ is always at least 2 and that the input graph is strongly connected.
We use undirected parameters, and we mean the width of the underlying undirected graph.

%

\begin{lemma}[Folklore]\label{lem:cycle_decomposition}
 Any closed directed walk (in particular a solution to the problem) can be decomposed into edge-disjoint simple cycles, such that the number of times an edge is traversed by the walk equals the number of the cycles it appears in.
\end{lemma}

\begin{observation}[\appmark]\label{obs:n_traversals}
 In each optimal solution to \DWRPshort, each vertex $v$ is visited at most $|W \setminus \{v\}|$ times.
\end{observation}

Hence, an instance of \DMsTSPshort can be interpreted as an equivalent instance of \DWRPshort, by letting $\cFn(e)=|V|$ for every arc.

\toappendix{
\begin{proof}[Proof of \Cref{obs:n_traversals}]
 Consider the decomposition of the optimal solution $S$ to cycles as guaranteed by \Cref{lem:cycle_decomposition}, denote it $\mathcal{C}=\{C_1, \ldots, C_q\}$.
 Consider an undirected bipartite graph $B$ with $V(B) = \mathcal{C} \cup V(G)$ and an edge connecting $u \in V(G)$ with $C \in \mathcal{C}$ if and only if $u \in V(C)$.
 Obviously $\deg_B v$ equals the number of cycles $v$ appears in, which in turn equals the number of times $v$ is visited by~$S$. 
 Let $T$ be a BFS tree for the BFS started from the vertex~$v$ in graph~$B$. 
 It might not contain all vertices of $V(G)$, it only contains vertices visited by $S$, and in particular it contains all vertices in $W$.
 Obviously $\deg_T v =\deg_B v$.

 If $v$ is a leaf of $T$, then we are done.
 Otherwise, let $T'$ be a tree obtained from $T$ by iteratively removing leaves that are not vertices of $W$.
 Let $\mathcal{C}'$ be the set of cycles that appear in $T'$ and $H$ be a multigraph obtained as the edge disjoint union of cycles in $\mathcal{C}'$.
 As $H$ is an edge disjoint union of cycles, it is balanced.
 We claim that it is also connected.
 In particular, there is a path from any vertex $u \in V(H)$ to $v$ in~$H$.
 Indeed, $u$ appears on some cycle $C \in \mathcal{C}'$ and there is a path $P_{T'}$ from $C$ to $v$ in~$T'$.
 By replacing each cycle on $P_{T'}$ by a part of the cycle between the appropriate vertices, we obtain a path from $u$ to $v$ in $H$.
 Thus there is an Eulerian trail $S'$ in $H$.
 Also, since~$T'$ contains all vertices in $W$, $H$ contains all vertices in~$W$, and $S'$ visits all vertices in~$W$.
 Moreover it traverses each edge at most as many times as~$S$.
 Thus it is a solution.
 Therefore, as $S$ is an optimal solution, we have $\mathcal{C}'=\mathcal{C}$.

 This, in particular, implies that $v \in V(T')$ and $\deg_{T'} v = \deg_T v$.
 However, as each leaf of~$T'$ is a vertex of $W\setminus\{v\}$, $T'$ has at most $|W\setminus\{v\}|$ leaves, which implies $\deg_{T'} v \le |W\setminus\{v\}|$.
