\subsection{Characterization of heavy-tailed behavior based on 20/60/20 rule}

In this section, our goal is to project the variance of the central region onto the unconditional variance to assess deviations from a balanced state. This approach allows us to define a distribution characterization metric that quantifies the heaviness of the tails relative to those induced by a normal distribution. By doing so, we provide a numerical measure of the effects discussed in Section~\ref{section:one_dim}, offering an alternative tail metric that does not rely on asymptotic tail behavior, as it is usually done. This enables a more flexible and data-driven assessment of distributional properties across different regimes. To do this, we introduce the statistic $S_n$ given, for any interval $(p,q)$, by
\begin{equation}
\label{s_stat}
    S_n := \sqrt{n} \left(\frac{\hat{\sigma}^2(\mathbf{Y})}{\bar{\sigma}^2(\mathbf{Y}) } -1 \right),
\end{equation}
where $\hat{\sigma}^2(\mathbf{Y})$ and  $\bar{\sigma}^2(\mathbf{Y}) $ are given by Equations \eqref{eq:standard.variance.Y.est} and \eqref{eq:variance_estimator.Y}.
In a nutshell, statistic $S_n$ measures the heaviness of the distribution tails when compared with the normal distribution. As we show now, this statistic is asymptotically normal as the sample size grows to infinity.

\begin{proposition}\label{pr:benchmark}

 Let $X\sim \mathcal{N}_d(\mu,\Sigma)$, and let $\mathbf{X}$ be a sample from $X$. Let us fix $p,q \in (0,1)$ such as $p < q$ and let $\mathbf{Y}$ and $S_n$ be given by \eqref{eq:sample_Y} and \eqref{s_stat}, respectively. Then, $S_n\overset{d}{\to }\mathcal{N}(0,\tau^2)$, as $n \to \infty$, where $\tau >0$ is a constant independent of $\mu$ and $\Sigma$. 


\end{proposition}
\begin{proof}
The proof involves utilizing the multivariate central limit theorem and the delta method. Let
\begin{align}\label{eq.CLT}
P_n:=\sqrt{n}
\begin{bmatrix}
\hat{\sigma}^2(\mathbf{Y}) - \Var(Y) \\
\hat{\sigma}^2_B(\mathbf{Y}) - \Var(Y|Y\in B) \\
\end{bmatrix}.
\end{align}
We demonstrate that $P_n$ converges in distribution to a certain multivariate normal distribution as $n \to \infty$. We begin by presenting alternative expressions for the components of $P_n$.


First, setting $A_k := (Y_k - \mathbb{E}(Y))^2 - \Var(Y) $ and $p_n= -\sqrt n (\hat \mu(\mathbf Y) - \mathbb{E}(Y))^2$, we obtain
\begin{align}
        \sqrt{n}(\hat \sigma^2(\mathbf{Y}) - \Var(Y) )&= \sqrt{n}\frac{1}{n}\sum_{k=1}^n(Y_k-\mathbb{E}(Y))^2 - \sqrt{n}\Var(Y) -\sqrt{n}(\hat \mu(\mathbf Y) - \mathbb{E}(Y))^2.\nonumber\\
        & = \sqrt{n}\frac{1}{n}\sum_{k=1}^nA_k - \sqrt n (\hat \mu(\mathbf Y) - \mathbb{E}(Y))^2\nonumber \\
&=\sqrt n\frac{1}{n}\sum_{k=1}^nA_k + p_n \label{eq:Ak}.
        \end{align}
Next, note that $\sqrt{n}\left( \frac{1}{n} \sum_{k=1}^n A_k \right) \overset{d}{\to} \mathcal{N}(0,\eta^2)$, as $n\to \infty$ for some $\eta^2 > 0$ as a average of i.i.d random variables and by the central limiti theorem we have $p_n = o_p(1)$.
% \begin{align}
%     \sqrt n (\hat{\sigma}^2(\mathbf{Y}) - \Var(Y)) =& \sqrt n \left( \frac{1}{n} \sum_{k=1}^{n}A_k \right) - \sqrt n \left( \Var(Y) + (\hat \mu - \mathbb E(Y))^2 \right) \\ 
