\subsection{Magnetized $T^4/\mathbb{Z}_3$}
We consider the algebraic relation $(ST_1T_2)^3=I$. This makes the following complex structure
\begin{align}
	\Omega_{(ST_1T_2)} = \begin{pmatrix}
		\omega&0\\0&\omega
	\end{pmatrix},\qquad \omega=e^{2\pi i/3}.
\end{align}
The identification is
\begin{align}
	\vec{z} \sim \Omega_{(ST_1T_2)} \vec{z},
\end{align}
which leads to the transformation function
\begin{align}
	V(\vec{z},\vec{\bar{z}})=e^{2\pi i\rho/3},\qquad\rho=(0,1,2).
\end{align}
The $\text{tr} \rho_+ (ST_1 T_2)$ is given by
\begin{align}
\text{tr} \rho_+(ST_1T_2)&=\sqrt{\det(iN^{-1}\Omega_{(ST_1T_2)}^{-1})}\sum_{\vec{K}\in\Lambda_N} e^{3\pi i\vec{K}^TN^{-1}\vec{K}}.
\label{trace_z3}
\end{align}
According to the $T_i$ symmetry, we should define the fluxes $N$ so that the diagonal elements of $N$ can be even
\begin{align}
	N=
	\begin{pmatrix}
		2n_1&m\\m&2n_2
	\end{pmatrix},\quad n_1,n_2,m\in\mathbb{Z}.
\end{align}
\subsubsection{Positive chirality}
When we consider the $\psi_{++}$ spinor, i.e.
\begin{align}
	\det{N} > 0,\quad \text{tr} N>0,
\end{align}
the trace becomes
\begin{align}
	\text{tr}\rho_+(ST_1T_2)&=\frac{i\bar{\omega}}{\sqrt{\det N}}\sum_{\vec{K}\in\Lambda_N} e^{3\pi i\vec{K}^TN^{-1}\vec{K}},
\end{align}
where we take the positive square root.
By use of Eq.\eqref{Landsberg-Schaar}, when we substitute $B=3I$, $\det B=9$, $g=2$, $n_-^B=0$, and $n_-^N=0$, 
the trace simplifies to
\begin{align}
	\text{tr}\rho_+(ST_1T_2)
    &=\frac{-\bar{\omega}}{3}\left[1+2(\bar{\omega}^{n_1}+\bar{\omega}^{n_2}+\bar{\omega}^{n_1+n_2}(\bar{\omega}^m+\bar{\omega}^{2m}))\right].
\end{align}
We check possible $\det{N}$ numerically. The first few solutions for $4n_1n_2-m^2\in\mathbb{Z}_{+}$ are:
\begin{align}
	\det N = 3,4,7,8,11,12,15,16,19,20,23,24,27,28.
\end{align}
\subsubsection{Negative chirality}
By use of Eq.\eqref{trace_z3}, we find
\begin{align}	\text{tr}\rho_-(ST_1T_2)&=s^{-1}\sqrt{\det(iN^{-1}\Omega_{ST_1T_2}^{-1})}\sum_{\vec{K}\in\Lambda_N}e^{3\pi i\vec{K}^TN^{-1}\vec{K}}.
\end{align}
Substituting back, we obtain the entire transformation function as
\begin{align}
	\text{tr}\rho_-(ST_1T_2)	&=\frac{s^{-1}}{\sqrt{-\det N}}\sum_{\vec{K}\in\Lambda_N} e^{3\pi i\vec{K}^TN^{-1}\vec{K}}.
    \label{trace_withspinor_before}
\end{align}
The formulae for the spectrum calculation become
\begin{align}
	&D_{1}+D_{\omega}+D_{\bar{\omega}}=|\det N|,\label{determinant_z3}\\
	&D_{1}+\omega D_{\omega}+\bar{\omega} D_{\bar{\omega}}=tr\rho(ST_1T_2).
    \label{trace_z31}
\end{align}
We can simplify Eq. \eqref{trace_withspinor_before} using Eq. \eqref{Landsberg-Schaar} with $g=2$. 
Since we take $B=3{\bf 1}_2$, $n_-^B=0$. 
Also, we find $n_-^N=1$ and 
\begin{align}
\begin{aligned}
	\text{tr}\rho_-(ST_1T_2)	&=-\frac{s^{-1}}{3}[1+2(\bar{\omega}^{n_1}+\bar{\omega}^{n_2}+\bar{\omega}^{n_1+n_2}(\bar{\omega}^m+\bar{\omega}^{2m}))]\\
					&=(s\bar{\omega})^{-1}\text{tr}\rho_+.
\end{aligned}
\end{align}
The spinor representation in $z'$ coordinates becomes 
\begin{align}
	V\begin{pmatrix}
		\omega&0&0&0\\		0&\sin^2{\phi}_0+\bar{\omega}\cos^2{\phi}_0&(\bar{\omega}-1)\sin{\phi}_0\cos{\phi}_0&0\\
		0&(\bar{\omega}-1)\sin{\phi}_0\cos{\phi}_0&\cos^2{\phi}_0+\bar{\omega}\sin^2{\phi}_0&0\\
		0&0&0&\omega
	\end{pmatrix}
    .
\end{align}
Thus, we find $\text{tr}\rho_-=\text{tr}\rho_+$.
\subsubsection{Trace classification}
There are only 18 possible cases. We list them all below:
