\subsection{Magnetized $T^4/\mathbb{Z}_6$}
To construct $T^4/\mathbb{Z}_6$, we focus on
the algebraic relation $((T_1T_2)^{-1}S)^6 = {\bf{1}}_4$.
According to Ref. \cite{Kikuchi:2022psj},
the complex structure are fixed as
\begin{align}
	 \Omega_{(T_1T_2)^{-1}S} = \begin{pmatrix}
		\omega&0\\0&\omega
	\end{pmatrix} .
\end{align}
The following identification corresponds to the $\mathbb{Z}_6$ twist:
\begin{align}
	\vec{z}\sim\kappa\vec{z},\ \ \ \ \kappa=e^{\frac{\pi i}{3}}.
\end{align}
The transformation function and the modular transformation are given by
\begin{align}
\begin{aligned}
&V(\vec{z},\vec{\bar{z}})=e^{\pi i\rho/3},\ \ \ \ \ \rho=(0,1,2,3,4,5),\\
    &\text{tr}\rho_{+}=\sqrt{\det (iN^{-1} \Omega_{(T_1T_2)^{-1}S})}\sum_{\vec{K}\in\Lambda_N}e^{\pi i\vec{K}^TN^{-1}\vec{K}},
\end{aligned}
\end{align}
where we have used $\vec{J}=\vec{K}\in\Lambda_N$.
\subsubsection{Positive chirality}
The trace becomes
\begin{align}
	{\rm tr}\rho_{+}=\frac{e^{\pi i/6}}{\sqrt{\det N}}\sum_{\vec{K}\in\Lambda_N}e^{\pi i\vec{K}^TN^{-1}\vec{K}}
    = 
    \omega e^{-2\pi i(n_1K_1^2+n_2K_2^2+mK_1K_2)}.
\end{align}
The flux is the same as in the $Z_3$ case. 
We use eq.\eqref{Landsberg-Schaar} with $B=I$, $n_-^B=0$, $n_-^N=0$ and $g=2$.
Therefore we find ${\rm tr}\rho=\omega=\kappa^2$.
Also, we have the following formulae
\begin{align}
\begin{split}
&D_1+D_\kappa+D_{\kappa^2}+D_{\kappa^3}+D_{\kappa^4}+D_{\kappa^5}=\det N,\\
&D_1+\kappa D_\kappa+\kappa^2D_{\kappa^2}+\kappa^3D_{\kappa^3}+\kappa^4D_{\kappa^4}+\kappa^5D_{\kappa^5}={\rm tr}\rho_+=\omega.\label{Z6 trace}
\end{split}
\end{align}
Since $Z_6=Z_2\otimes Z_3$, we have the following $Z_2$ and $Z_3$ properties for some of the eigenvalues
\begin{align}
\begin{split}
	D_1+D_{\kappa^2}+D_{\kappa^4}&=N_{Z_2,+},\\
	D_1+D_{\kappa^3}&=N_{Z_3,1},\\
	D_{\kappa}+D_{\kappa^4}&=N_{Z_3,\omega},\\
       D_{\kappa^2}+D_{\kappa^5}&=N_{Z_3,\bar{\omega}}.
\end{split}
\end{align}
We find the following relation
\begin{align}
	D_1-D_{\kappa^3}=D_{\kappa^4}-D_{\kappa}=D_{\kappa^2}-D_{\kappa^5}-1,
\end{align}
where we have made use of the relations
\begin{align}
	\kappa^3=-1, \qquad
	\kappa^4=-\kappa=\bar{\omega}, \qquad
	\kappa^5=-\kappa^2=-\omega
\end{align}
to rewrite the trace as
\begin{align}
	(D_1-D_{\kappa^3})+\omega(D_{\kappa^2}-D_{\kappa^5})+\bar{\omega}(D_{\kappa^4}-D_{\kappa})=\omega.
\end{align}
Since the spectrum must correspond to that of $Z_3$, and there is no additional conditions on the fluxes, we will have the same $\det N$ values available.
The calculation is straightforward by rewriting
\begin{align*}
	&(2D_1-N_{Z_3,1})+\omega(2D_{\kappa^2}-N_{Z_3,\bar{\omega}})+\bar{\omega}(2D_{\kappa^4}-N_{Z_3,\omega})=\omega,
\end{align*}
and using $1+\omega+\bar{\omega}=1$ as well as the $Z_2$ spectrum constraint.
\subsubsection{Negative chirality}
The trace is now 
\begin{align}
\text{tr}\rho_-((T_1T_2)^{-1}S)&=s^{-1}\sqrt{\det (iN^{-1}\Omega^{' -1 }_{(T_1T_2)^{-1}S})}\sum_{\vec{K}\in\Lambda_N}e^{\pi i\vec{K}^TN^{-1}\vec{K}}.
\end{align}
Then, the trace becomes
\begin{align}
	\text{tr}\rho_-((T_1T_2)^{-1}S)&=\frac{-s^{-1}}{\sqrt{-\det N}}\sum_{\vec{K}\in\Lambda_N}e^{\pi i\vec{K}^TN^{-1}\vec{K}}.
\end{align}
Using Eq. \eqref{Landsberg-Schaar} with $B=I,n_-^B=0,n_-^N=1$ and $g=2$, we get
\begin{align}
	\text{tr}\rho_=((T_1T_2)^{-1}S)&=s^{-1}e^{-2\pi i (n_1K^2_1+n_2K^2_2+mK_1K_2)}=s^{-1}.
\end{align}
The spinor representation in ${z}'$ becomes
\begin{align}
	V\begin{pmatrix}
		\kappa&0&0&0\\
		0&\sin^2{\phi}_0+\kappa^2cos^2{\phi}_0&(\kappa^2-1)\sin{\phi}_0\cos{\phi}_0&0\\
		0&(\kappa^2-1)\sin{\phi}_0\cos{\phi}_0&\cos^2{\phi}_0+\kappa^2\sin^2{\phi}_0&0\\
		0&0&0&\kappa
	\end{pmatrix}
    .
\end{align}
Thus, $\text{tr}\rho_-=\kappa^5=\omega$.
We can calculate the spectrum using the following formulae:
\begin{align}
\begin{split}
&D_1+D_\kappa+D_{\kappa^2}+D_{\kappa^3}+D_{\kappa^4}+D_{\kappa^5}=|\det N|,\\
&D_1+\kappa D_\kappa+\kappa^2D_{\kappa^2}+\kappa^3D_{\kappa^3}+\kappa^4D_{\kappa^4}+\kappa^5D_{\kappa^5}=\tr\rho_-=\omega,
\end{split}
\end{align}
as well as
\begin{align}
\begin{aligned}
	D_1+D_{\kappa^2}+D_{\kappa^4}&=N_{Z_2,+},\\
	D_1+D_{\kappa^3}&=N_{Z_3,1},\\
	D_{\kappa}+D_{\kappa^4}&=N_{Z_3,\omega},\\
D_{\kappa^2}+D_{\kappa^5}&=N_{Z_3,\bar{\omega}},
\end{aligned}
\end{align}
or
\begin{align}
	&(2D_1-N_{Z_3,1})+\omega(2D_{\kappa^2}-N_{Z_3,\bar{\omega}})+\bar{\omega}(2D_{\kappa^4}-N_{Z_3,\omega})=\omega,
\end{align}
where $N_{Z_2,+}$ is the even spectrum for negative chirality (odd sector for positive chirality).
