\section{Introduction}

The phenomenon of long-range dependence (also called long memory) is one of exciting area of research in the probability theory for last few decades due to
non-standard normalizations and non-Gaussian limiting distributions of nonlinear functionals \cite{pipiras2017long}.
The Rosenblatt distribution serves a significant role in the study of  this phenomenon
which occurs in economics, finance, hydrology, turbulence, cosmology and physics \cite{doukhan2002theory,beran2017statistics}.

The Rosenblatt distribution was introduced in \cite{rosenblatt1961independence}
and later it was investigated by many researchers, see \cite{taqqu1975weak,taqqu1979convergence,dobrushin1979non} among many others.
The Rosenblatt distribution appears as the limiting distribution of some popular functionals,
see \cite{doukhan2002theory,berman1979high,rosenblatt1979some} and references therein.

The known analytical form of the characteristic function of the Rosenblatt distribution contains a series which converges in a neighbourhood of zero, see
\cite{rosenblatt1961independence, albin1998note,veillette2013properties}.
It turns out that the Rosenblatt distribution is infinitely divisible \cite{veillette2013properties} and self-decomposable, moreover, it belongs to the Thorin class \cite{maejima2013distribution,leonenko2017non,leonenko2017rosenblatt}.

The density of the Rosenblatt distribution exists and bounded, however, the closed analytical form of the density is unknown, see \cite{veillette2013properties,maejima2013distribution,leonenko2017non,leonenko2017rosenblatt}.
The Edgeworth expansion was used to approximate the density of the Rosenblatt distribution \cite{veillette2012berry}. The numerical evaluation of the density of the Rosenblatt distribution was proposed in \cite{veillette2013properties}.




The present paper is organized as follows.
In Section 2 we review the known facts on the Rosenblatt distribution.
In Section 3 we provide the novel analytic forms of the characteristic function of the Rosenblatt distribution on the entire line and a compelling viewpoint on the structure of the Rosenblatt distribution.
In Section 4 we propose a accurate approximation of all eigenvalues of the Riesz integral operator, which allows us to perform fast numerical computation of the density of the Rosenblatt distribution.

In Section 5
we propose a time-efficient algorithm for simulation of the stationary Gaussian sequences with long-range dependence with the power correlation function and the Mittag-Lefler correlation function.
Furthermore, we demonstrate small sample properties of four popular functionals for analysis of sequences of correlated random variables including their non-standard normalization and convergence to the Rosenblatt distribution. Specifically, we consider  estimation of the mean in Section \ref{sec:5m},  the correlation function in Section \ref{sec:5c},
the sojourn functionals in  Section \ref{sec:5s} and path roughness in Section \ref{sec:5r}.
All these problems are essentials of the statistical analysis of stationary Gaussian sequences with  long-range dependence.


\section{Formal statement}

We consider the Rosenblatt distribution with shape parameter $a$, zero mean,
unit variance and the characteristic function
\begin{equation}\label{eq:Rchfun}
 \phi(z)=\exp\left( \frac{1}{2} \sum_{k=2}
 (2iz)^k\frac{c_{a,k} \sigma_a^k }{k} \right),~a\in[0,1/2],~z\in S_0\subset\mathbb{R},
\end{equation}
where $S_0$ is a small neighbourhood of zero,
$$\sigma_a=\sqrt{(1-2a)(1-a)/2}$$
and
$$
 c_{a,k}=\int_0^1\cdots\int_0^1  |x_1-x_2|^{-a} |x_2-x_3|^{-a}
 \cdots |x_{k-1}-x_k|^{-a} |x_k-x_1|^{-a} dx_1\cdots dx_k.
$$
In the rest of this section we describe the Rosenblatt distribution following  \cite{veillette2013properties}.
The random variable $V$ from the Rosenblatt distribution can be given as
\begin{equation}\label{eq:V}
V=\sum_{n=1}^\infty \lambda_{a,n} (\varepsilon_n^2-1),
\end{equation}
where $\varepsilon_n$ are i.i.d. random variables from the standard normal distribution
and
$\lambda_{a,1},\lambda_{a,2},\ldots$  are eigenvalues of the Riesz integral operator
$\tilde K_a: L^2(0,1)\to L^2(0,1)$ defined as
$$
 (\tilde K_af)(x)=\sigma_a \int_0^1 |x-u|^{-a}f(u)du.
$$
The representation \eqref{eq:V} means that $V$ is a specific instance of second-order Wiener chaos \cite{nourdin2012convergence}.
These eigenvalues  satisfy the relation
$$
\sum_{n=1}^\infty \lambda_{a,n}^k=\begin{cases}
\infty,&k=1,\\
c_{a,k} \sigma_a^k,&k=2,3,\ldots.
\end{cases}
$$
%The multidimensional integral $c_{a,k}$ can explicitly be computed  for small $k$. Specifically,
Moreover, we have
 \begin{eqnarray*}
\sum_{n=1}^\infty \lambda_{a,n}^2&=&1/2, \\
\sum_{n=1}^\infty \lambda_{a,n}^3&=&\frac{2\sigma_a^3}{(1-a)(2-3a)}\beta(1-a,1-a),
 \end{eqnarray*}
where $\beta(u,v)=\int_0^1x^{u-1}(1-x)^{v-1}dx$ is the beta function.
The Rosenblatt distribution is infinitely divisible with
the L\'evy  density
$$
m(x)=\frac{1}{2x}\sum_{n=1}^\infty
\exp\left(-\frac{x}{2\lambda_{a,n}}\right),~x>0,
$$
that shows self-decomposability of the Rosenblatt distribution \cite{veillette2013properties}.



\section{Main results}

The Laplace transform of $V$ defined in \eqref{eq:V} is given by
$$
 \phi_{LT}(s)=\mathbb{E}(e^{-sV})=\exp\left( -\sum_ {n=1}^\infty
 \left(\frac{1}{2}\ln(1+2\lambda_{a,n}s )-\lambda_{a,n}s\right)  \right),
 ~s>-\frac{1}{2\lambda_{a,1}},
$$
see \cite{albin1998note}. We note that the formal expansion of the sum in the above expression gives
$$
 -\frac{1}{2}\sum_ {n=1}^\infty
 \ln(1+2\lambda_{a,n}s ) +
 s\sum_ {n=1}^\infty\lambda_{a,n},
$$
where the latter summand equals infinity.
Using the classical Taylor expansion of the logarithm
$$
\ln(x)=\sum_{k = 1}^{\infty} \frac{(-1)^{k-1}}{k} (x-1)^k,~ x\in(0,2),
$$  which does not converge for all positive $x$, we obtain
\begin{equation}
 \phi_{LT}(s)=\exp\left( \frac{1}{2}\sum_{k=2}^\infty \frac{(-2s)^k}{k}
 \left( \sum_ {n=1}^\infty
 \lambda_{a,n}^k\right)  \right),~|s|<\frac{1}{2\lambda_{a,1}},
 \label{eq:LTstandard}
\end{equation}
which is related to \eqref{eq:Rchfun} as $\phi(z)=\phi_{LT}(-iz)$, $z\in\mathbb{R}$.
We note that the expressions of the characteristic function \eqref{eq:Rchfun}  and the Laplace transform \eqref{eq:LTstandard} cannot be used for numerical calculation because they are defined at a neighbourhood of zero.

In next theorem, we derive new expressions using
 three other expansions of  the logarithm which converge on the full domain $(0,\infty)$ and one integral representation. In other words, we construct analytic continuations for the expressions \eqref{eq:Rchfun} and~\eqref{eq:LTstandard}.

\begin{theorem} \label{th1}
 The characteristic function $\phi(z)$ of the Rosenblatt distribution is given by $\phi(z)=\phi_{LT}(-iz)$,
  where the Laplace transform $\phi_{LT}(s)$ with $s>-\frac{1}{2\lambda_{a,1}}$ admits
  \begin{itemize}
  \item[(i)] the representation using the domain-scaled expansion
 \begin{eqnarray}\nonumber
 \ln ( \phi_{LT}(s))
 = \sum_ {n=1}^\infty \left(
 \frac{(\lambda_{a,n}s)^2}{1+\lambda_{a,n}s}
  - \sum_{k = 2}^{\infty} \frac{1}{2k-1}\left(\frac{\lambda_{a,n}s}{1+\lambda_{a,n}s}\right)^{2k-1}
 \right),\label{eq:LTds}
\end{eqnarray}
 \item[(ii)] the representation using the Ramanujan expansion
\begin{eqnarray}
 \ln ( \phi_{LT}(s))= \sum_ {n=1}^\infty \lambda_{a,n}s  \ln(1+2\lambda_{a,n}s)
 \sum_{k=1}^\infty \frac{1}{2^{k}(1+(1+2\lambda_{a,n}s)^{2^{-k}})},
\end{eqnarray}
  \item[(iii)] the representation using the Ramanujan-Bradley expansion
\begin{eqnarray}
 \ln ( \phi_{LT}(s))=\frac{1}{2} \sum_ {n=1}^\infty \sum_{k=1}^\infty 2^{k-1}
 \left((1+2\lambda_{a,n}s)^{2^{-k}}-1\right)^2,
\end{eqnarray}
  \item[(iv)] the representation using the integral form
  $$
     \ln ( \phi_{LT}(s))=\int_{0}^{ s} \sum_ {n=1}^\infty \frac{2\lambda_{a,n}^2u}{2\lambda_{a,n} u+1}du.
  $$
  \end{itemize}
\end{theorem}

The proof of Theorem \ref{th1} is deferred to the online supplement.
We note that  the evaluation of the characteristic function
of the Rosenblatt distribution requires computation of the infinite sums with a special care because
numerical computation of $\sum_{i=1}^\infty  \lambda_{a,n}^2$ is problematic for $a\in(0.35,0.5)$ due to very slow convergence of the series $\sum_{i=1}^\infty n^{2a-2}$.
To overcome difficulties of numerical computation, we propose to
find smallest integer $M_\epsilon$ such that
$$
 \sum_{n=M_\epsilon+1}^\infty  \lambda_{a,n}^k<\epsilon
$$
 for $k=3,4,\ldots$, where
 $\epsilon$ is a small positive number, for example, $\epsilon=0.0001$.
Then we can write the random variable $V$ defined in \eqref{eq:V} in the form $V=W+Z$, where
$$
 W=\sum_{n=1}^{M_\epsilon}  \lambda_{a,n} (\varepsilon_n^2-1),~
 Z=\sum_{n=M_\epsilon+1}^\infty  \lambda_{a,n} (\varepsilon_n^2-1).
$$
Due to the choice of $M_\epsilon$, the random variable $Z$ has approximately
the normal distribution with mean zero and variance
$$\sigma^2_\epsilon=1-2\sum_{n=1}^{M_\epsilon}  \lambda_{a,n}^2
=2\sum_{n=M_\epsilon+1}^\infty  \lambda_{a,n}^2.$$
Indeed, the characteristic function of $Z$ has the form
\begin{eqnarray*}
 \phi_Z(z)&=&\exp\left( -\sum_ {n=M_\epsilon+1}^\infty
 \left(\frac{1}{2}\ln(1-2\lambda_{a,n}iz )+\lambda_{a,n}iz\right)  \right)\\
 &\stackrel{|z|<\frac{1}{2\lambda_{a,M_\epsilon}}}{=}&\exp\left( \frac{1}{2}\sum_{k=2}^\infty \frac{(2iz)^k}{k}
 \left( \sum_ {n=M_\epsilon+1}^\infty
 \lambda_{a,n}^k\right)  \right)\\
 &\approx&\exp\left(-z^2  \left( \sum_ {n=M_\epsilon+1}^\infty
 \lambda_{a,n}^2\right) +\frac{4}{3} i^3z^3 \epsilon \right)\\
 &\approx& \exp\left(-z^2 \sigma^2_\epsilon/2 \right).
\end{eqnarray*}
Moreover, we have
$$
\max_{|z|\le\frac{1}{2\lambda_{a,M_\epsilon}}}
\Big|\phi_Z(z)-\exp\left(-z^2 \sigma^2_\epsilon/2 \right)\Big|\to 0 \text{~as~}\epsilon\to0.
$$

This argument provides a clear constructive view on the Rosenblatt distribution.
Specifically, the random variable from the Rosenblatt distribution can be simulated as
$$
  V_\epsilon= \sigma_\epsilon\varepsilon_0+ \sum_{n=1}^{M_\epsilon}  \lambda_{a,n} (\varepsilon_n^2-1),
$$
where $\varepsilon_n$ are i.i.d. random variables from the standard normal distribution.
The density of the Rosenblatt distribution can be computed by the inverse Fourier transform
of the characteristic function
$$
 \phi_\epsilon(z)=\exp\left( -z^2 \sigma^2_\epsilon/2-\sum_ {n=1}^{M_\epsilon}
 \left(\frac{1}{2}\ln(1-2\lambda_{a,n}iz )+\lambda_{a,n}iz\right)  \right).
$$
Applying the Stein method for the random variable $V_\epsilon$ and taking the limit as $\epsilon\to0$, we obtain the following characterizing identity,
which follows from \cite[Ch. 3]{arras2019stein}.
\begin{theorem}
 Let $X$ be a random variable with zero mean. The Stein equation
 \begin{equation}
  \mathbb{E}Xf(X)=\mathbb{E}\int_0^\infty \Big(f(X+x)-f(X)\Big)
  \frac{1}{2}\sum_{n=1}^\infty
\exp\left(-\frac{x}{2\lambda_{a,n}}\right)dx
\label{eq:stein}
 \end{equation}
holds for all bounded Lipschitz function $f(\cdot)$ if and only if $X$ has the Rosenblatt distribution with parameter~$a$.
\end{theorem}
Let us use the Stein equation \eqref{eq:stein} with $f(x)=x$,
we refer to \cite[Ch. 3]{arras2019stein} for a discussion on a class of suitable functions.
Then the right hand side  of the Stein equation is
$$
 \mathbb{E}\int_0^\infty (X+x-X)\frac{1}{2}\sum_{n=1}^\infty
\exp\left(-\frac{x}{2\lambda_{a,n}}\right)dx
=
 2\sum_{n=1}^\infty  \lambda_{a,n}^2=1
$$
and
the left hand side of the Stein equation is the second moment, which equals one from the definition of the Rosenblatt distribution. Thus, the Stein equation  for $f(x)=x$ and $X=V$ becomes $\mathbb{E}V^2=1$.
Taking $f(x)=x^2$ and $X=V$ in  the Stein equation \eqref{eq:stein} we obtain
$$
 \mathbb{E}V^3=
  \mathbb{E}\int_0^\infty (2Vx+x^2)\frac{1}{2}\sum_{n=1}^\infty
\exp\left(-\frac{x}{2\lambda_{a,n}}\right)dx
=
 8\sum_{n=1}^\infty  \lambda_{a,n}^3.
$$
For $f(x)=x^3$ and $X=V$ in  the Stein equation \eqref{eq:stein} we obtain
    \begin{equation*}
%        \begin{split}
 \mathbb{E}V^4
 =
  \mathbb{E}\int_0^\infty (3V^2x-3Vx+x^3)\frac{1}{2}\sum_{n=1}^\infty
\exp\left(-\frac{x}{2\lambda_{a,n}}\right)dx
% &=
 % \int_0^\infty (3x+x^3)\frac{1}{2}\sum_{n=1}^\infty
%\exp\left(-\frac{x}{2\lambda_{a,n}}\right)dx
=
 48\sum_{n=1}^\infty  \lambda_{a,n}^4+3.
%        \end{split}
    \end{equation*}
Using the first four moments (mean, variance, skewness, and kurtosis), the Rosenblatt distribution can be  approximated by the Pearson family of distributions.

\section{Computational aspects}

Although moments of the Rosenblatt distribution depend on the multidimensional integrals $c_{a,k}$,
$$
 \mathbb{E}\,V^k=\frac{1}{i^k}\left.\frac{d^k}{dz^k}\phi(z)\right|_{z=0}=
 \begin{cases}
 0,&k=1,\\
 1,&k=2,\\
 8\sigma_a^3 c_{a,3},&k=3\\
 48 \sigma_a^4 c_{a,4}+12 \sigma_a^4 c_{a,2}^2,&k=4\\
 \vdots&k=5,6,\ldots,
 \end{cases}
$$
simulation and computation of the density of the Rosenblatt distribution
is not possible without the eigenvalues $\lambda_{a,n}$.
It was shown in \cite{dostanic1998spectral} that
the eigenvalues $\lambda_{a,n}$  have the asymptotic behaviour
$\lambda_{a,n}=C_a n^{a-1}(1+o(n^{-\delta}))$ as $n\to\infty$ for any $\delta\in(0,1)$ and
admit the accurate approximation
$$
 \lambda_{a,n}\cong C_a n^{a-1},~ n>20,
$$
 where
$$
C_a=\frac{2\sigma_a}{\pi^{1-a}}\Gamma(1-a)\sin(\pi a/2),
$$
see \cite{veillette2013properties} for details.
From extensive numerical calculation of eigenvalues for various $a\in(0,0.5)$, we obtain that
the eigenvalues $\lambda_{a,n}$ admit the accurate approximation
\begin{equation} \label{eq:app-eigs}
 \lambda_{a,n}\cong \begin{cases}
 (1+0.1409a)\sqrt{\pi^a\Gamma(1-a)}\sqrt{\frac{1}{2}-a},&n=1,\\
 C_a n^{a-1}+\frac{5}{4} a^{1.05}\sqrt{\Gamma(a+\frac{1}{2})-1}\,n^{a-2.2},&n=2,3,\ldots.
 \end{cases}
\end{equation}

