\section*{Online supplement. Proof of Theorem 1}

\textbf{(i)}
We note that the logarithm possesses the entire-domain representation
$$
 \ln(x) = 2\sum_{k = 1}^{\infty} \frac{1}{2k-1}\left(\frac{x-1}{x+1}\right)^{2k-1}, ~  x>0,
$$
which is obtained from the Taylor expansion of $\frac{1}{2}\ln(\frac{1+u}{1-u})$ at $u=0$ with substitution $\frac{1+u}{1-u}=x$, see \cite[Eq. 20.19]{spiegel1968mathematical}.
Then we obtain
\begin{eqnarray*}\nonumber
 \ln ( \phi_{LT}(s))&=&- \sum_ {n=1}^\infty \left(
 \frac{\lambda_{a,n}s}{1+\lambda_{a,n}s}  - \lambda_{a,n}s
  + \sum_{k = 2}^{\infty} \frac{1}{2k-1}\left(\frac{\lambda_{a,n}s}{1+\lambda_{a,n}s}\right)^{2k-1}
 \right)\\
 &=& \sum_ {n=1}^\infty \left(
 \frac{(\lambda_{a,n}s)^2}{1+\lambda_{a,n}s}
  - \sum_{k = 2}^{\infty} \frac{1}{2k-1}\left(\frac{\lambda_{a,n}s}{1+\lambda_{a,n}s}\right)^{2k-1}
 \right),
\end{eqnarray*}
which is convenient for numerical computation for all $s>-\frac{1}{2\lambda_{a,1}}$ and
serves as an analytic continuation of the expression \eqref{eq:LTstandard} defined in a neighbourhood of zero.



\textbf{(ii)}
The famous Ramanujan formula is given by
$$
 \frac{1}{\ln(x)}+\frac{1}{1-x}=\sum_{k=1}^\infty \frac{1}{2^{k}(1+x^{2^{-k}})},~  x\in(0,1)\cup(1,\infty),
$$
see \cite{bradley2018concerning}.
We note that $x^{2^{-k}}=x^{(2^{-k})}$ and
$$
 \ln(x)+1-x=(1-x)\ln(x)\left( \frac{1}{\ln(x)}+\frac{1}{1-x} \right)
 =(1-x)\ln(x)\sum_{k=1}^\infty \frac{1}{2^{k}(1+x^{2^{-k}})}.
$$
Then we obtain
\begin{eqnarray*}
 \ln ( \phi_{LT}(s))= \sum_ {n=1}^\infty \lambda_{a,n}s  \ln(1+2\lambda_{a,n}s)
 \sum_{k=1}^\infty \frac{1}{2^{k}(1+(1+2\lambda_{a,n}s)^{2^{-k}})},
\end{eqnarray*}
which is valid for all $s>-\frac{1}{2\lambda_{a,1}}$.



\textbf{(iii)}
The Ramanujan-Bradley expansion is given by
$$
\ln(x)=x-1-\sum_{k=1}^\infty 2^{k-1}(x^{2^{-k}}-1)^2, ~  x>0,
$$
which is similar to the famous Ramanujan formula, see \cite{bradley2017infinite}.
Then we obtain
\begin{eqnarray*}
 \ln ( \phi_{LT}(s))=\frac{1}{2} \sum_ {n=1}^\infty \sum_{k=1}^\infty 2^{k-1}
 \left((1+2\lambda_{a,n}s)^{2^{-k}}-1\right)^2,
\end{eqnarray*}
which is valid for all $s>-\frac{1}{2\lambda_{a,1}}$.


\textbf{(iv)}
The natural logarithm has the integral representation
$$
 \ln(x)=x-1-\int_{1}^x \int_1^t \frac{1}{u^2} du dt.
$$
We can see that
$$
 \ln(x)-x+1=-\int_{1}^x (1-\frac{1}{t})dt=-\int_{0}^{x-1} (1-\frac{1}{u+1})du=-\int_{0}^{x-1} \frac{u}{u+1}du.
$$
For $x=1+2 \lambda_{a,n} s$ we obtain
$$
 \ln(1+2\lambda_{a,n}s )-2\lambda_{a,n}s=
 -\int_{0}^{2 \lambda_{a,n} s} \frac{u}{u+1}du=
  -\int_{0}^{2  s} \frac{\lambda_{a,n}^2u}{\lambda_{a,n} u+1}du.
$$
Then we obtain
$$
 \ln ( \phi_{LT}(s))=\frac{1}{2}\sum_ {n=1}^\infty  \int_{1}^{1+2\lambda_{a,n}s} \int_1^t \frac{1}{u^2} du dt=
 \frac{1}{2}  \int_{0}^{2  s} \sum_ {n=1}^\infty \frac{\lambda_{a,n}^2u}{\lambda_{a,n} u+1}du
 =
   \int_{0}^{ s} \sum_ {n=1}^\infty \frac{2\lambda_{a,n}^2u}{2\lambda_{a,n} u+1}du.
$$
%\textbf{Transformation to the complex argument is not possible.}

\subsection*{A2. R code for the density of the Rosenblatt distribution}

The following R code contains the  algorithm of computation of
the density of the Rosenblatt distribution with shape parameter $a$.

\begin{lstlisting}


getEig1 = function(a) {
  (1+0.1409*a)*(gamma(1-a)*pi^a)^0.5*(0.5-a)^0.5
}
getEig=function(a, n) {
  S = sqrt((1-2*a)*(1-a)/2)
  Coef = 2*S*gamma(1-a)*sin(pi*a/2)/pi^(1-a)
  SecondCoef = 1.05*a^(5/4)*sqrt(gamma(1-(0.5-a))-1)
  lambda = Coef*n^(a-1) + SecondCoef*n^(a-2.2)
  if(length(n)==1) if (n==1)
    lambda = getEig1(a)
  if(length(a)==1&length(n)>1) if(n[1]==1)
    lambda[1] = getEig1(a)
  return(lambda)
}
IFFT_Fun = function(z, x, a, lam, sigz2) {
  chf = exp(-z^2*sigz2/2)
  for(j in (1:length(lam)))
    chf = chf*exp(-0.5*log(1-2*1i*lam[j]*z)-1i*lam[j]*z)
  return(Re(chf*exp(-1i*z*x)))
}
Ros_Density_Fun = function(x, a, lam, sigz) {
  integrate(IFFT_Fun, -20, 20, x, a, lam, sigz,
            stop.on.error = FALSE)$value/(2*pi)
}
getRosenblattDensity = function(x, a, K) {
  lam = getEig(a,(1:K))
  sigz2 = max(0,1-2*sum(lam^2))
  dens = sapply(x, Ros_Density_Fun, a, lam, sigz2)
  return(dens)
}
a = 0.25
K = 100
x = seq(-3,3,by=0.1)
dens = getRosenblattDensity(x, a, K)
plot(x,dens,type='l')
\end{lstlisting}


\subsection*{A3. R code for simulation of a stationary Gaussian sequence with LRD}

The following R code contains the  algorithm of simulation of
a stationary Gaussian sequence $E_1,E_2,\ldots,E_N$
with zero mean, unit variance and the correlation functions $r(t)=(1+|t|)^{-a}$ and $r(t)=E_a(-|t|^a)$.

\begin{lstlisting}
library(pRSR)
getGausSeqLRD4 = function(N, M, b, lam) {
  X = rep(0,N)
  for(j in (1:M))
  {
   A = exp(-lam[j])
   SEps = sqrt(1-A^2)
   XT = SimulateAR1(N, A)
   X = X + sqrt(b[j])*XT
  }
  return(X)
}
getGausSeqLRD = function(N, a, MLcor=FALSE) {
  gamm = exp((2-a)*a)
  m = ceiling(2/a)+8
  q = if(!MLcor) c(0.98,0.9/gamm^(0:m)) else
              c(0.98,0.9,0.7,0.5/gamm^(0:m))
  Z = (sin(q*a*pi)/sin((1-q)*a*pi))^(1/a)
  Z[Z>10^25] = 10^25
  tau = if(MLcor) Z else qgamma(q, a, 1)
  M = length(q)
  lam = c(tau[1],sqrt(tau[1:(M-1)]*tau[2:M]))
  fun_p = function(x) {
    if(!MLcor) x^(a-1)*exp(-x)/gamma(a) else
      sin(pi*a)/pi*x^(a-1)/(1+2*cos(pi*a)*x^a+x^(2*a)) }
  tau1 = c(4*tau[1], tau)
  b = rep(0, M)
  for(j in (1:M))
    b[j] = integrate(fun_p, tau[j], tau1[j])$value
  X = getGausSeqLRD4(N, M, b, lam)
  return(X)
}
a = 0.35
N = 20000
X = getGausSeqLRD(N, a) # 1/(1+|t|)^a correlation
plot(X, type='l')
acf(X, 100)
X2 = getGausSeqLRD(N, a, TRUE) # E_a(-|t|^a) correlation
\end{lstlisting}

