  \begin{array}{ll}
    E_k^1 &= \displaystyle\binom{k}{2}\pi_+ \left\{ \left[ \binom{k}{2} - 1 \right] \pi_+ + \binom{n-k}{2}\pi_- + k (n-k) f(\pi_+,\pi_-)\right\}, \\
    E_k^2 &= \displaystyle\binom{n-k}{2}\pi_-  \left\{ \binom{k}{2} \pi_+ + \left[\binom{n-k}{2}-1\right]\pi_- + k (n-k) f(\pi_+,\pi_-)\right\}, \\
    E_k^3 &= k(n-k) f(\pi_+,\pi_-) \displaystyle \left \{ \binom{k}{2} \pi_+ + \binom{n-k}{2}\pi_- + \left[k (n-k) - 1 \right] f(\pi_+,\pi_-)\right\}.
