\section{Proof of equation (\ref{eq:recurrence})}
\label{sec:appA}

    First, for any $0\leq k\leq n$, we will prove by induction over $k$ that
    \begin{equation}\label{eq:recurrence2}
    P_k=\binom{n}{k} P_0.
    \end{equation}
    The cases $k=0$ and $k=1$, since $P_1=nP_0$, are trivial to check. Suppose now that the claim holds for any $0\leq \ell\leq k$ and we want to prove it for $k+1$. By using \eqref{eq:recequation} together with the induction hypothesis, we get
    \[
    \begin{array}{ll}
   P_{k+1} &= \displaystyle\dfrac{n}{k+1} \binom{n}{k} P_0 - \dfrac{n-k+1}{n} \binom{n}{k-1} P_0  \\
   &= \displaystyle\dfrac{n!}{(k-1)! (n-k)!} \left( \dfrac{n}{k(k+1)} - \dfrac{1}{k+1} \right) P_0 \\
   &= \displaystyle\binom{n}{k+1} P_0.
   \end{array}
    \]
    This concludes the proof of \eqref{eq:recurrence2}. Finally, we prove \eqref{eq:recurrence} by showing that $P_0=1/2^n$ in order to have a probability density. This easily follows by the fact that $\sum_{k=0}^n \binom{n}{k}=2^n$.

\section{Proof of equation (\ref{eq:secondmoment})}
\label{sec:appB}
By \eqref{eq:defS}, note that we can write
\[
\begin{array}{ll}
S^2(t) &= \displaystyle\sum_{i<j} \mathbf{1}\{(i,j)\in E(t)\} \\
& \ + \displaystyle\sum_{i<j} \sum_{\substack{\ell<m \\ (i,j)\neq (\ell,m)}} \mathbf{1}\{(i,j)\in E(t), (\ell,m)\in E(t)\},
\end{array}
\]
which, at stationarity, leads to 
\begin{align*}
    &\ee[S^2(t)] - \ee[S(t)] \\
=   &\displaystyle\sum_{i<j} \sum_{\substack{\ell<m \\ (i,j)\neq (\ell,m)}} \pp\left( (i,j)\in E(t), (\ell,m)\in E(t) \right) \\
= &\displaystyle\sum_{\substack{i<j, \ \ell<m \\ (i,j)\neq (\ell,m)}} \sum_{k=0}^n\pp\left( (i,j),(\ell,m)\in E(t)| N_+(t)=k\right) P_k\\
= &\displaystyle \sum_{k=0}^n P_k \sum_{\substack{i<j, \ \ell<m \\ (i,j)\neq (\ell,m) \\ x_i(t)=+ \\ x_j(t)=+ }} \pp\left( (i,j),(\ell,m)\in E(t)| N_+(t)=k\right) 
\end{align*}
\begin{align*}
+&\displaystyle\sum_{k=0}^n P_k \sum_{\substack{i<j, \ \ell<m \\ (i,j)\neq (\ell,m) \\ x_i(t)=- \\ x_j(t)=-}} \pp\left( (i,j),(\ell,m)\in E(t)| N_+(t)=k\right) \\
+&\displaystyle\sum_{k=0}^n P_k \sum_{\substack{i<j, \ \ell<m \\ (i,j)\neq (\ell,m) \\ x_i(t)\neq x_j(t)}} \pp\left( (i,j),(\ell,m)\in E(t)| N_+(t)=k\right).
\end{align*}
We consider separately the three terms of the sum. The first one can be expanded as
\[
\begin{array}{ll}
\displaystyle \sum_{\substack{i<j, \ \ell<m \\ (i,j)\neq (\ell,m) \\ x_i(t)=+ \\ x_j(t)=+}} \pp\left( (i,j)\in E(t), (\ell,m)\in E(t)| N_+(t)=k\right) \\
  =\displaystyle \sum_{\substack{i<j \\ x_i(t)=x_j(t)=+}} \pp\left( (i,j)\in E(t)| N_+(t)=k\right)  \\
\quad \times \displaystyle\sum_{\substack{\ell<m \\ (i,j)\neq (\ell,m)}}\pp\left((\ell,m)\in E(t)| N_+(t)=k\right)  \\
 =\displaystyle \binom{k}{2}\pi_+ \\
\ \times \left\{ \left[ \binom{k}{2}-1 \right] \pi_+ + \binom{n-k}{2} \pi_- + k(n-k) f(\pi_+,\pi_-) \right\}.
\end{array}
\]
By arguing similarly for the other two terms, the claim follows.


