For an extension to the unknown $d$ setting, we assume access to an estimator $\hat{d}$ which satisfies the following property: 
\begin{align}\label{eq:goodestim}
    \P(\hat{d}=d)\to 1, \quad \mbox{as}\,\, n_Q\to\infty.
\end{align}
Natural choices for $\hat{d}$ include $\hat{d}_{\rm avg}$ and $\hat{d}_{\rm vote}$ described above. By \citet[Corollary 2]{Farahmand2007}, \eqref{eq:goodestim} holds for $\hat{d}_{\rm avg}$ and $\hat{d}_{\rm vote}$ (under appropriate conditions), and the convergence to $1$ is, in fact, exponentially fast. Therefore, even for moderately large $n_Q$, these estimators of the intrinsic dimension $d$ perform really well in practice. The following corollary is an immediate consequence of \cref{thm:lepski_manifold} and it shows that the adaptive estimator from \cref{alg:adaptive-bandwidth} converges at a nearly optimal rate. 

\begin{cor}\label{cor:fulladapt}
    Consider the same setting as in \cref{thm:lepski_manifold} and suppose that the learner has access to an estimator $\hat{d}$ satisfying \eqref{eq:goodestim}. Let $\hat{h}_n$ denote the bandwidth obtained from the output of \cref{alg:adaptive-bandwidth}. Then the estimator $\hat{f}_{\hat{h}_n}$ satisfies 
    $$|\hat{f}_{\hat{h}_n}(\xs)-f^\star(\xs)|=O_p\left(\left(\frac{n_Q+n_P^{\frac{2\beta+d}{2\beta+D}}}{\log{n}}\right)^{-\beta/(2\beta+d)}\right),$$
    provided $n_Q, n_P\to\infty$. 
\end{cor}
\paragraph{Algorithm.} The complete adaptive procedure, which integrates both dimension estimation and smoothness selection, is summarized in Algorithm~\ref{alg:adaptive-bandwidth}. If either \(d\) or \(\beta\) is known in advance, the algorithm can be simplified accordingly: the known quantity can be directly substituted, and only the remaining unknown needs to be estimated.

\begin{algorithm}[H]
\caption{Adaptive Bandwidth Selection under Covariate Shift}
\label{alg:adaptive-bandwidth}

\begin{algorithmic}[1]
\REQUIRE Source data \(\{(X_i,Y_i)\}_{i=1}^{n_P}\); target data \(\{(X_i, Y_i)\}_{i=n_P+1}^{n_P + n_Q}\), source data \(\{X_j\}_{j=1}^{n_P}\); ambient dimension \(D\); predefined constants \(C_h, C_\ell\); candidate set \(\widetilde{\mathcal{B}}\); neighborhood size \(k\)

\ENSURE Estimated intrinsic dimension \(\hat{d}\), smoothness \(\hat{\beta}\), and bandwidth \(\hat{h}\)

\STATE Estimate local dimensions \(\hat{d}(X_i)\) using \(k\)-nearest neighbors as in \eqref{eq:locdim}
\STATE Compute global estimate: \(\hat{d} \equiv \hat{d}_{\rm avg} = \ceilfloor{\frac{1}{n_Q} \sum_{i=n_P+1}^{n_P + n_Q} \left( \hat{d}(X_i) \wedge D \right)}\), or use majority vote, see \cref{sec:adapt}

\STATE For each \(\tilde{\beta} \in \widetilde{\mathcal{B}}\), compute \(\hat{f}_{h_{n, \tilde{\beta}, \hat{d}}}(x^*)\), where
\[
h_{n, \tilde{\beta}, \hat{d}} = C_h \left(\frac{n_Q + n_P^{\frac{2\tilde{\beta} + \hat{d}}{2\tilde{\beta} + D}}}{\log{n}}\right)^{-\frac{1}{2\tilde{\beta} + \hat{d}}}
\]

\STATE Apply Lepski’s method: define
\[
\hat{\beta} = \max \left\{ \tilde{\beta} \in \widetilde{\mathcal{B}} : \left| \hat{f}_{h_{n, \tilde{\beta}, \hat{d}}}(x^*) - \hat{f}_{h_{n, \eta, \hat{d}}}(x^*) \right| \leq C_\ell h_{n, \eta, \hat{d}}^\eta,\ \forall \eta \leq \tilde{\beta} \right\} 
\]

\STATE Compute final bandwidth:
\[
\hat{h}_n = C_h \left(\frac{n_Q + n_P^{\frac{2\hat{\beta} + \hat{d}}{2\hat{\beta} + D}}}{\log{n}}\right)^{-\frac{1}{2\hat{\beta} + \hat{d}}}
\]
\STATE Return the proposed adaptive estimator:
\[
\hat{f}_{\mathrm{adp}}(x^*) := \hat{f}_{\hat{h}_n}(x^*) \quad \text{as in } \eqref{eq:ourestim}
\]

\end{algorithmic}
\end{algorithm}




\section{Numerical experiments}
\label{sec:sim}
