\section{Proofs of Main results}
\label{sec:pfmainres}

Throughout this Section, we will use $\lesssim$ to hide constants that are free of $n_P$ and $n_Q$. 
\subsection{Proof of \cref{thm:approx_manifold_upper_bound}}
 In order to prove \cref{thm:approx_manifold_upper_bound}, we first present some auxiliary lemmas. The first result is a technical lemma that will help us bound expectations under both the source and the target probability measures. 
 \begin{lem}\label{lem:techlem1}
     Suppose Assumptions \ref{asn:covshift} --- \ref{asn:regf}, \eqref{eq:kernel} hold, and $h_n\to 0$. Suppose that the target point $\xs\in \mathcal{M}_{\rho_n}$. Let $\Theta(\cdot)$ defined on $[-1,1]^D$ 
     denote a nonnegative bounded function, and let $\theta(\cdot)$ be a nonnegative function defined on the target domain so that it is bounded around a fixed neighborhood of the target point $\xs$. Then the following conclusions hold: 
     \begin{enumerate}
         \item[(i)] Suppose $h_n\le \rho_n$. Define 
         \begin{align}\label{eq:cenu1}
        \cnu := \left\{s \in \R^d: \left\|\frac{\phi(0)  - \phi(s \rho_n)}{\rho_n} + u_0 + \frac{h_n}{\rho_n} u\right\|_\infty \le 1\right\},
         \end{align}
         for $u\in [-1,1]^D$. Then the Lebesgue measure of $\cnu$ is bounded away from $0$ and $\infty$ uniformly in $n$ and $u$.
         \item[(ii)] Suppose $\rho_n\le h_n$. Define 
         \begin{align}\label{eq:cenu2}
         \ctu := \left\{s \in \R^d : \left\|\frac{\phi(sh_n) - \phi(0)}{h_n}+ \frac{\rho_n}{h_n}(u - u_0)\right\|_\infty \le 1\right\},
         \end{align}
         for $u\in [-1,1]^D$. Then the Lebesgue measure of $\ctu$ is bounded away from $0$ and $\infty$ uniformly in $n$ and $u$. 
         \item[(iii)] For $\upsilon\ge 1$, we have 
         $$\E_{X\sim P}\left[\Theta\left(\frac{X-\xs}{h_n}\right)K_{h_n}(X-\xs)^{\upsilon} \theta(X)\right]\lesssim \frac{1}{h_n^{(\upsilon-1)D}}.$$
         \item[(iv)] If $h_n\le \rho_n$, then we have: 
         $$\E_{X\sim Q}\left[\Theta\left(\frac{X-\xs}{h_n}\right)K_{h_n}(X-\xs)^{\upsilon} \theta(X)\right]\lesssim \frac{\rho_n^{d-D}}{h_n^{(\upsilon-1)D}}.$$
         \item[(v)] If $\rho_n\le h_n$, then we have: 
         $$\E_{X\sim Q}\left[\Theta\left(\frac{X-\xs}{h_n}\right)K_{h_n}(X-\xs)^{\upsilon} \theta(X)\right]\lesssim \frac{1}{h_n^{\upsilon D - d}}.$$
     \end{enumerate}
 \end{lem}
 Define 
 \begin{align}\label{eq:hSn}
     \hat{S}_n := \frac{1}{n}\bZ^{\top}\bW \bZ,  \quad \mbox{and} \quad S_n := \E [\hat{S}_n/\psi_n], 
 \end{align} 
 where $\psi_n$ is defined as in \eqref{eq:psin}. Note that $\hat{S}_n$ and $S_n$ are square matrices of dimension $\deg(\ell)\times \deg(\ell)$. We skip the boldface notation here for ease of readability. Next, let us define 
 \begin{align}\label{eq:hsn}
     \hat{s}_n := \frac{1}{n}\sum_i \bz\left(\frac{X_i - \xs}{h_n}\right) K_{h_n}(X_i - \xs) Y_i \quad \mbox{and} \quad s_n:=\E[\hat{s}_n/\psi_n]\,.
 \end{align}
 The first result shows that the eigenvalues of $S_n$ are bounded away from $0$.

 \begin{lem}\label{lem:lbdeig}
 Suppose \cref{asn:lowman},  \eqref{eq:kernel} hold, and $h_n\to 0$. Then there exists $m>0$ such that, for all large enough $n$, we have $\lmn(S_n)\ge m$.
 \end{lem}

 The second result shows that $\hat{S}_n$ concentrates around $S_n$, which when coupled with \cref{lem:lbdeig}, implies that the minimum eigenvalue of $\hat{S}_n$ is also bounded away from $0$ with high probability.

 \begin{lem}
    \label{lem:conc_matrix}
    Suppose \cref{asn:lowman},   \eqref{eq:kernel} hold, and $h_n\to 0$. 
    For all large enough $n$, the matrix $\hat S_n/\psi_n$ satisfies: 
    $$
    \P\left(\left\|\frac{\hat S_n}{\psi_n} - S_n\right\| \ge 2t\right) \le C\exp{\left(-\frac{t^2 (n\psi_nh_n^D)}{c_1 + c_2 t}\right)} \,,
    $$
    for some constants $C, c_1, c_2 > 0$. Consequently, we have: 
    $$
    \E\left[\left\|\frac{\hat S_n}{\psi_n} - S_n\right\|^k\right] \le \frac{C'}{(n\psi_nh_n^D)^{k/2}}  \,,
    $$
    for some constant $C' > 0$.  
\end{lem}

\begin{lem}
    \label{lem:bounding_mean_part}
    Suppose Assumptions \ref{asn:covshift}---\ref{asn:regf}, \eqref{eq:kernel}  hold, and $h_n\to 0$. Then $\E[\|\hat s_n/\psi_n\|_2^4] \lesssim 1$. 
\end{lem}

\begin{proof}[Proof of \cref{thm:approx_manifold_upper_bound}]
    Recall (from \eqref{eq:weightvec} and \eqref{eq:ourestim}) that our estimator can be written as: 
$$
\hat f(\xs) := \begin{cases}
  e_1^\top \left(\frac{\hat S_n}{\psi_n}\right)^{-1} \left(\frac{\hat s_n}{\psi_n}\right) = \sum_{i=1}^n w_iY_i & \mbox{if}\; \lmn\left(\bZ^{\top} \bW \bZ\right)\ge n\tau_n \psi_n \\ 0 & \mbox{otherwise}\,,
\end{cases}
$$
 where $\hat{S}_n$ and $\hat{s}_n$ are defined in \eqref{eq:hSn} and \eqref{eq:hsn} respectively, and the scaling factor $\psi_n = (n_P/n) + (n_Q/n)(\rho_n \vee h_n)^{d - D}$ (see \eqref{eq:psin}).  
The definition of this estimator relies on the invertibility of $\hat S_n$ or $\hat S_n/\psi_n$. By \cref{lem:lbdeig}, we know that there exists $m>0$ such that $\lambda_{\min}(S_n) \ge m$. 
Based on $\hat S_n, S_n$, We first define a ``good" set
\begin{align}\label{eq:gev}
    \Omega_n := \left\{\left\lVert \frac{\hat{S}_n}{\psi_n}-S_n\right\rVert_{\mathrm\mathrm{op}}\le \frac{1}{2}\lmn(S_n)\right\}\,.
\end{align} 
Note that as $\tau_n$ becomes small for large $n$, by \cref{lem:lbdeig}, eventually it will be smaller than $\lambda_{\min}(S_n)/2$ . Therefore, the estimator will be non-zero on the set $\Omega_n$ almost surely. Based on this, we can first decompose the MSE as: 
$$
\E[(\hat f(\xs) - f^\star(\xs))^2] = \underbrace{\E[(\hat f(\xs) - f^\star(\xs))^2\mathds{1}_{\Omega_n}]}_{ =: I}  + \underbrace{\E[(\hat f(\xs) - f^\star(\xs))^2\mathds{1}_{\Omega^c_n}]}_{ =: II}
$$
{\bf Term I: }Let's first start with $I$ by performing a simple bias-variance decomposition: 
\begin{align*}
    I = \E[(\hat f(\xs) - f^\star(\xs))^2\mathds{1}_{\Omega_n}] = \Var(\hat f(\xs)\mathds{1}_{\Omega_n}) + \left(\E[(\hat f(\xs) - f^\star(\xs))\mathds{1}_{\Omega_n}]\right)^2
\end{align*}
{\bf Bias of Term I: }First, consider the bias part: from the definition of our estimator, we can write: 
\begin{align}\label{eq:biasbd}
    \E[(\hat f(\xs) - f^\star(\xs))\mathds{1}_{\Omega_n}] & = \E\left[\sum_i w_i (Y_i - f^\star(\xs))\mathds{1}_{\Omega_n}\right] \nonumber \\
    & = \E\left[\sum_i w_i (f^\star(X_i) - f^\star(\xs))\mathds{1}_{\Omega_n}\right] \nonumber \\
    & \overset{(i)}{=} \E\left[\sum_i w_i \left(\underbrace{f^\star(X_i) - f^\star(\xs) - \sum_{0 < \balpha \le \lfloor \beta \rfloor} \frac{(X_i - \xs)^{\balpha}}{\balpha!} (f^\star)^{[\balpha]}(\xs)}_{ =: R_i(\xs)}\right)\mathds{1}_{\Omega_n}\right] \nonumber\\
    & = \E\left[\sum_i w_i R_i(\xs) \mathds{1}_{\Omega_n}\right]\nonumber \\
    & = \frac{1}{n\psi_n}\sum_i \E\left[e_1^\top(\hat S_n/\psi_n)^{-1}\bz\left(\frac{X_i - \xs}{h_n}\right) K_{h_n}(X_i - \xs)R_i(\xs)\mathds{1}_{\Omega_n}\right] \nonumber\\
    & \overset{(ii)}{\le} Lh_n^{\beta}\frac{1}{n\psi_n}\sum_i \E\left[\|(\hat S_n /\psi_n)^{-1}\|_{\mathrm{op}} \|\bz((X_i - \xs)/h)\|K_{h_n}(X_i - \xs)\mathds{1}_{\Omega_n}\right]\nonumber \\
    & \overset{(iii)}{\le} \frac{2Lh_n^\beta}{\lambda_{\min}(S_n)}\frac{1}{n\psi_n}\sum_i \E\left[\|\bz((X_i - \xs)/h_n)\| K_{h_n}(X_i - \xs)\right].
\end{align}
Here (i) follows from the reproducing property (see \eqref{eq:reproducing}), (ii) follows from the fact that $K$ is compactly supported (by choice) and the H\"{o}lder assumption on $f^\star$ (see \cref{asn:regf}), and (iii) follows from the fact that, on $\Omega_n$, $\|(\hat S_n /\psi_n)^{-1}\| = 1/\lambda_{\min}(\hat S_n/\psi_n) \le 2/\lambda_{\min}(S_n)$, which in turn follows from a simple application of Weyl's inequality (see \cite{Weyl1912}). Next we will bound the inner expectation in the above display when $X_i\sim P$ and $X_i\sim Q$ separately. To wit, observe that for all large enough $n$, by \cref{lem:techlem1}, part (iii), we have:
\begin{align*}
     \bbE_P\left[\|\bz((X - \xs)/h_n)\|K_{h_n}(X - \xs)\right] \lesssim 1\,.
\end{align*}
Similarly, by \cref{lem:techlem1}, parts (iv) and (v), we get:
\begin{align*}
     \bbE_Q\left[\|\bz((X - \xs)/h_n)\||K_{h_n}(X - \xs)|\right] \lesssim (\rho_n\vee h_n)^{d-D}\,.
\end{align*}

\vspace{0.05in}

\noindent Therefore, the bias term in \eqref{eq:biasbd} is bounded above by: 
\begin{align}\label{eq:biasgenbd}
 \E[(\hat f(\xs) - f^\star(\xs))\mathds{1}_{\Omega_n}] \lesssim h_n^\beta \frac{1}{n\psi_n}(n_P+n_Q(\rho_n\vee h_n)^{d-D})=h_n^{\beta}\,.
\end{align}

\noindent
{\bf Variance of Term I: }We will use the inequality $\Var(X + Y) \le 2\Var(X) + 2\Var(Y)$ multiple times.  A first application of this inequality yields: 
\begin{align*}
\Var(\hat f(\xs)\mathds{1}_{\Omega_n}) & = \Var(e_1^\top(\hat S_n/\psi_n)^{-1}(\hat s_n/\psi_n)\mathds{1}_{\Omega_n}) \\
& = \Var(e_1^\top S_n^{-1}(\hat s_n/\psi_n)\mathds{1}_{\Omega_n} + e_1^\top((\hat S_n/\psi_n)^{-1} - S_n^{-1})(\hat s_n/\psi_n)\mathds{1}_{\Omega_n}) \\
& \le 2\Var(e_1^\top S_n^{-1}(\hat s_n/\psi_n)\mathds{1}_{\Omega_n}) + 2\Var(e_1^\top((\hat S_n/\psi_n)^{-1} - S_n^{-1})(\hat s_n/\psi_n)\mathds{1}_{\Omega_n})
\end{align*}
Let us first consider the second term: 
\begin{align*}
  \Var(e_1^\top((\hat S_n/\psi_n)^{-1} - S_n^{-1})(\hat s_n/\psi_n)\mathds{1}_{\Omega_n}) & \le \E\left[\left(e_1^\top((\hat S_n/\psi_n)^{-1} - S_n^{-1})(\hat s_n/\psi_n)\right)^2\mathds{1}_{\Omega_n}\right] \\
  & \le \E\left[\|(\hat S_n/\psi_n)^{-1} - S_n^{-1}\|^2\|(\hat s_n/\psi_n)\|_2^2{\bf 1}(\Omega_n)\right] \\
  & \le \sqrt{\E\left[\|(\hat S_n/\psi_n)^{-1} - S_n^{-1}\|^4 {\bf 1}(\Omega_n)\right]\E\left[\|(\hat s_n/\psi_n)\|_2^4 {\bf 1}(\Omega_n)\right]}\,.
\end{align*}
Now we note that on the event $\Omega_n$, we have:
\begin{align*}
    \lVert (\hat{S}_n/\psi_n)^{-1}-S_n^{-1}\rVert &\le \lVert (\hat{S}_n/\psi_n)^{-1}\rVert \lVert S_n^{-1}\rVert\lVert (\hat{S}_n/\psi_n)-S_n\rVert \\ &\le \lVert S_n^{-1}\rVert \rVert (\lVert \hat{S}_n/\psi_n)^{-1}-S_n^{-1}\rVert + \lVert S_n^{-1}\rVert)\lVert (\hat{S}_n/\psi_n)-S_n\rVert.
\end{align*}
As $\lVert S_n^{-1}\rVert \lVert (\hat{S}_n/\psi_n)-S_n\rVert \le 1/2$ on $\Omega_n$, the above display implies that, on $\Omega_n$, the following holds: 
\begin{align}\label{eq:invbound}
\lVert (\hat{S}_n/\psi_n)^{-1}-S_n^{-1}\rVert \le 2\lVert S_n^{-1}\rVert^2 \lVert (\hat{S}_n/\psi_n)-S_n\rVert \lesssim \lVert (\hat{S}_n/\psi_n)-S_n\rVert,
\end{align}
where the last inequality uses \cref{lem:lbdeig}. Therefore, we have: 
\begin{align*}
\Var(e_1^\top((\hat S_n/\psi_n)^{-1} - S_n^{-1})(\hat s_n/\psi_n)\mathds{1}_{\Omega_n}) \lesssim \sqrt{\E\big[\lVert \hat{S}_n-S_n\rVert^4\big] \E\big[\lVert (\hat{s}_n/\psi_n)\rVert^4\big]}\,.
\end{align*}
The second term is bounded by some constant as proved in Lemma \ref{lem:bounding_mean_part}. 
For the first term, we use Lemma \ref{lem:conc_matrix}, which yields 
$$
 \Var(e_1^\top((\hat S_n/\psi_n)^{-1} - S_n^{-1})(\hat s_n/\psi_n)\mathds{1}_{\Omega_n}) \lesssim \frac{1}{n\psi_n h_n^D} = \frac{1}{n_P h_n^D + n_Q (\rho_n\vee h_n)^{d-D}h_n^D} \,.
$$
Now, we will go back to the other term, i.e., $\Var(e_1^\top S_n^{-1}(\hat s_n/\psi_n)\mathds{1}_{\Omega_n})$. Once again, the minimum eigenvalue of $S_n$ is bounded away from $0$ by \cref{lem:lbdeig}. We Further decompose this variance as: 
$$
\Var(e_1^\top S_n^{-1}(\hat s_n/\psi_n)\mathds{1}_{\Omega_n}) \le  2\Var(e_1^\top S_n^{-1}(\hat s_n/\psi_n)) + 2 \Var(e_1^\top S_n^{-1}(\hat s_n/\psi_n)\mathds{1}_{\Omega_n^c})
$$
For the first term: 
\begin{align*}
    & \Var(e_1^\top S_n^{-1}(\hat s_n/\psi_n)) \\
    & = \Var\left(e_1^\top S_n^{-1}\left(\frac{1}{n\psi_n}\sum_i \bz\left(\frac{X_i - \xs}{h_n}\right)K_{h_n}(X_i - \xs) Y_i \right)\right) \\
    & = \frac{1}{(n\psi_n)^2}\left\{n_P \Var_P\left(a^\top\bz\left(\frac{X - \xs}{h_n}\right)K_{h_n}(X - \xs) Y\right) + n_Q \Var_Q\left(a^\top\bz\left(\frac{X - \xs}{h_n}\right)K_{h_n}(X - \xs) Y\right)\right\}
\end{align*}
where $a := S_n^{-1}e_1$. By using the law of total variance, we get:
\begin{align*}
    &\;\;\;\;\Var_P\left(a^\top\bz\left(\frac{X - \xs}{h_n}\right)K_{h_n}(X - \xs) Y\right) \\ & = \Var_P\left(a^\top\bz\left(\frac{X - \xs}{h_n}\right)K_{h_n}(X - \xs) f^\star(\xs)\right)+\bbE_P\left[\left(a^\top\bz\left(\frac{X - \xs}{h_n}\right)K_{h_n}(X - \xs)\right)^2\Var(Y|X)\right] \lesssim \frac{1}{h_n^D},
\end{align*}
where the last inequality follows from \cref{lem:techlem1}, part (iii). A similar computation coupled with \cref{lem:techlem1}, parts (iv) and (v), we get: 
\begin{align*}
    &\;\;\;\;\Var_P\left(a^\top\bz\left(\frac{X - \xs}{h_n}\right)K_{h_n}(X - \xs) Y\right) \lesssim \frac{(\rho_n\vee h_n)^{d-D}}{h_n^D},
\end{align*}
We therefore conclude that:
$$
\Var(e_1^\top S_n^{-1}(\hat s_n/\psi_n)) \lesssim \frac{1}{(n\psi_n)^2} \left(\frac{n_P}{h_n^D} + \frac{n_Q (\rho_n\vee h_n)^{d-D}}{h_n^{D}}\right) =  \frac{1}{n\psi_n h_n^D} \,.
$$
So far our conclusion is: 
$$
\Var(\hat f(\xs) \mathds{1}_{\Omega_n}) \lesssim \frac{1}{n\psi_n h_n^D} + \ \Var(e_1^\top S_n^{-1}(\hat s_n/\psi_n)\mathds{1}_{\Omega_n^c}) \,.
$$
Now we control the second term in the above display. Recall that $\lmn(S_n)\ge m>0$ for all large enough $n$ by \cref{lem:lbdeig}. Therefore, note that by \cref{lem:conc_matrix}, there exists constants $c_1,c_2>0$ such that 
\begin{align}\label{eq:tbd}
\P(\Omega_n^c) \lesssim \exp\left(-\frac{m^2 (n\psi_nh_n^D)}{c_1 + c_2 m}\right) \,.
\end{align}
Therefore, for all large enough $n$, we have: 
\begin{align*}
    \Var(e_1^\top S_n^{-1}(\hat s_n/\psi_n)\mathds{1}_{\Omega_n^c}) \lesssim \sqrt{\E\bigg\lVert \frac{\hat{s}_n}{\psi_n}\bigg\rVert^4}\sqrt{\P(\Omega_n^c)}\lesssim \exp\left(-\frac{m^2 (n\psi_nh_n^D)}{c_1 + c_2 m}\right) = o\big((n\psi_n h_n^D)^{-1}\big).
\end{align*}
The last inequality follows from \eqref{eq:tbd} and \cref{lem:bounding_mean_part}.
\\\\
{\bf Term II: }To bound II, we first use a simple inequality: 
$$
\E[(\hat f(\xs) - f^\star(\xs))^2\mathds{1}_{\Omega^c_n}] \le 2 \E[\hat f^2(\xs)\mathds{1}_{\Omega^c_n}] + 2\E[f^\star(\xs)^2 \mathds{1}_{\Omega^c_n}] \,.
$$
By \eqref{eq:tbd}, 
$
\E[f^\star(\xs)^2 \mathds{1}_{\Omega^c_n}] = o((n\psi_nh_n^D)^{-1}) \,.
$

Now, for the term involving $\hat f(\xs)$, we note that for all large enough $n$, we have:

\begin{align}\label{eq:meano1}
\E[\hat f^2(\xs) \mathds{1}_{\Omega_n^c}] & = \E\left[\hat f^2(\xs) \mathds{1}_{\Omega_n^c \cap \{\lambda_{\min}(\hat S_n/\psi_n) > \tau_n\}}\right] \nonumber \\
& = \E\left[\left(e_1^\top \left(\frac{\hat S_n}{\psi_n}\right)^{-1} \left(\frac{\hat s_n}{\psi_n}\right)\right)^2\mathds{1}_{\Omega_n^c \cap \{\lambda_{\min}(\hat S_n/\psi_n) > \tau_n\}}\right] \nonumber \\
& \le \E\left[\left\|\left(\frac{\hat S_n}{\psi_n}\right)^{-1}\right\|_{\rm op}^2\left\|\frac{\hat s_n}{\psi_n}\right\|_2^2\mathds{1}_{\Omega_n^c \cap \{\lambda_{\min}(\hat S_n/\psi_n) > \tau_n\}}\right] \nonumber \\
& \le \E\left[\left(\lambda_{\min}\left(\frac{\hat S_n}{\psi_n}\right)\right)^{-2} \left\|\frac{\hat s_n}{\psi_n}\right\|_2^2\mathds{1}_{\Omega_n^c \cap \{\lambda_{\min}(\hat S_n/\psi_n) > \tau_n\}}\right] \nonumber \\
& \le \tau_n^{-2}\E\left[ \left\|\frac{\hat s_n}{\psi_n}\right\|_2^2\mathds{1}_{\Omega_n^c}\right] \nonumber \\
& \le \tau_n^{-2} \sqrt{\E\left[ \left\|\frac{\hat s_n}{\psi_n}\right\|_4^2\right]}\sqrt{\P(\Omega_n^c)}  \lesssim \tau_n^{-2} \exp{\left(-\frac{m^2 (n\psi_nh_n^D)}{c_1 + c_2 m}\right)} = o\big((n\psi_n h_n^D)^{-1}\big) \,.
\end{align}
In the last inequality, we use \eqref{eq:tbd},  \cref{lem:bounding_mean_part} and the fact that $\tau_n=(n\psi_n h_n^D)^{-p}$ for some $p > 1$. 

\vspace{0.05in}

\noindent Combining the above observations, we get: 

\begin{align}\label{eq:genbound}
\E[(\hat{f}(\xs)-f^\star(\xs))^2]\lesssim h_n^{2\beta}+\frac{1}{n_P h_n^D+n_Q(\rho_n\vee h_n)^{d-D}h_n^D}.
\end{align}

\noindent To get our final rates, we split it into two cases. 

\noindent When $\rho_n\le C_2 (n_P^{\frac{2\beta+d}{2\beta+D}}+n_Q)^{-\frac{1}{2\beta+d}}$, choose $h_n:=C_4(n_P^{\frac{2\beta+d}{2\beta+D}}+n_Q)^{-\frac{1}{2\beta+d}}$. By adjusting the constants, if needed, we have $\rho_n\vee h_n=h_n$. Therefore, in this case, we have: 
\begin{align*}
    \E[(\hat{f}(\xs)-f^\star(\xs))^2] &\lesssim h_n^{2\beta}+\frac{1}{n_P h_n^D +n_Q h_n^d}.
\end{align*}
We claim that $h_n^{2\beta}\gtrsim (n_P h_n^D +n_Q h_n^d)^{-1}$ with the above choices. It suffices to show that $n_P h_n^{2\beta+D}+n_Q h_n^{2\beta+d}\gtrsim 1$. If $n_Q\lesssim n_p^{\frac{2\beta+d}{2\beta+D}}$, then $h_n\ge n_P^{-\frac{1}{2\beta+D}}$. Therefore, $n_P h_n^{2\beta+D}+n_Q h_n^{2\beta+d}\gtrsim n_P h_n^{2\beta+D}\gtrsim 1$. Similarly, if $n_Q\gtrsim n_P^{\frac{2\beta+d}{2\beta+D}}$, then $h_n\gtrsim n_Q^{-\frac{1}{2\beta+d}}$. As a result, $n_P h_n^{2\beta}+n_Q h_n^{2\beta+d}\gtrsim n_Q h_n^{2\beta+d}\gtrsim 1$. Therefore, 
\begin{align*}
    \E[(\hat{f}(\xs)-f^\star(\xs))^2] &\lesssim h_n^{2\beta}\lesssim \big(n_P^{\frac{2\beta+d}{2\beta+D}}+n_Q)^{-\frac{2\beta}{2\beta+d}}.
\end{align*}

\noindent Next, we look at the case when $\rho_n\ge C_1(n_P^{\frac{2\beta+d}{2\beta+D}}+n_Q)^{-\frac{1}{2\beta+d}}$, choose $h_n:=C_4(n_P+n_Q\rho_n^{d-D})^{-\frac{1}{2\beta+D}}$. Once again, by splitting into two cases, namely $n_Q\lesssim n_P^{\frac{2\beta+d}{2\beta+D}}$ or $n_Q\gtrsim n_P^{\frac{2\beta+d}{2\beta+D}}$, it is easy to check that $\rho_n\vee h_n=\rho_n$. Next by splitting up further into two cases, namely $n_P\lesssim n_Q\rho_n^{d-D}$ or $n_P\gtrsim n_Q\rho_n^{d-D}$, we also observe that under the current parameter specifications, $h_n^{2\beta+D}\gtrsim (n_P+n_Q\rho_n^{d-D})^{-1}$ which implies 
\begin{align*}
    \E[(\hat{f}(\xs)-f^\star(\xs))^2] &\lesssim h_n^{2\beta}\lesssim (n_P+n_Q\rho_n^{d-D})^{-\frac{2\beta}{2\beta+d}}.
\end{align*}
This completes the proof.
\end{proof}

 \section{Proof of \cref{thm:minmaxlb}}
  Let $\cX$ denote the support of $P_X$. The proof proceeds with Le Cam's two-point argument (see \cite{LeCam1973} and \cite[Chapter 2]{Tsybakov2009}) for establishing minimax lower bounds. To wit, we consider the following two functions: 
\begin{align*}
    f_{0, n}(x) & \equiv 0 \ \ \text{ on } \cX \,,\\
    f_{1, n}(x) & = Mh_n^{\beta}K\left(\frac{x - \xs}{h_n}\right)\ \ \text{ on } \cX \,.
\end{align*}
Here the value of $h_n$ is taken as in \eqref{eq:def_h}, i.e., 
\begin{equation*}
    h_n = 
    \begin{cases}
        C(n_P + n_Q\rho_n^{d - D})^{-\frac{1}{2\beta + D}}, & \text{if } \rho_n > C'(n_P^{\frac{2\beta + d}{2\beta + D}} + n_Q)^{-\frac{1}{2\beta + d}}\\
        C(n_P^{\frac{2\beta + d}{2\beta + D}} + n_Q)^{-\frac{1}{2\beta + d}} & \text{if } \rho_n \le   C''(n_P^{\frac{2\beta + d}{2\beta + D}} + n_Q)^{-\frac{1}{2\beta + d}} \,,
    \end{cases}
\end{equation*}
for positive constants $C,C',C''$. Here the constant $M>0$ is chosen small enough and the kernel $K$ is chosen as a standard compactly supported $C^{\infty}$ ``bump" function, so as to satisfy \eqref{eq:kernel} and \cref{asn:regf}, i.e., $f_{1n}\in \Sigma(\beta,L)$. Following the same argument as used at the end of the proof of \cref{thm:approx_manifold_upper_bound}, this implies the following relation between $\rho_n$ and $h_n$ (by changing the constants if necessary), which we will use in the proof: 
\begin{align*}
    \rho_n \le   (n_P^{\frac{2\beta + d}{2\beta + D}} + n_Q)^{-\frac{1}{2\beta + d}} & \implies \rho_n \le h_n \\
    \rho_n > (n_P^{\frac{2\beta + d}{2\beta + D}} + n_Q)^{-\frac{1}{2\beta + d}} & \implies \rho_n > (n_P + n_Q\rho_n^{d - D})^{-\frac{1}{2\beta + D}} \implies h_n <  \rho_n \,.
\end{align*}
Now define $d(f, g) := |f(\xs) - g(\xs)|$ for functions $f,g$ on $\cX$. Then we have $d(f_{0, n}, f_{1, n}) = Lh_n^{\beta}K(0)$. 
Furthermore, set $r_n := Lh_n^{\beta}K(0)/3$. 
From the definition of the minimax risk, we have: 
\allowdisplaybreaks
\begin{align*}
    \inf_{\hat f} \sup_{f \in \Sigma(\beta, L)} \E\left[(\hat f(\xs) - f(\xs))^2\right] & \ge \inf_{\hat f} \max_{f \in \{f_{0, n}, f_{1, n}\}} \E\left[(\hat f(\xs) - f(\xs))^2\right] \\
    & \ge r_n^2 \inf_{\hat f} \max_{f \in \{f_{0, n}, f_{1, n}\}} \P\left(|\hat f(\xs) - f(\xs)| \ge r_n\right) \\
    & \ge r_n^2 \inf_{\psi} \max_{j \in \{0, 1\}} \P_{j}(\psi \neq j)
\end{align*}
In the last inequality, the infimum is over all testing functions which, based on observations drawn according to model \eqref{eq:model}, tests whether $f^\star(\xs) = f_{0, n}(\xs)=0$ or $f^\star(\xs) = f_{1, n}(\xs)=L h_n^{\beta}K(0)$. For clarity, $\P_{j}$ denotes the pooled data distribution under the Bayes optimal predictors $f_{0,n}$ and $f_{1,n}$ respectively. The above reduction scheme follows from the fact that by the definition of $r_n$, $d(f_{0, n}, f_{1, n}) > 2r_n$. Therefore, for any estimator $\hat f(\xs)$, we can define a projection based test $\psi$ as: 
$$
\psi = \argmin_{j \in \{0, 1\}} d(\hat f(\xs), f_{j, n}(\xs)) \,.
$$
Now observe that for any $j \in \{0, 1\}$, $j'\in\{0,1\}$, $j'\ne j$, the condition $\psi \neq j$ implies $|\hat f(\xs) - f_{j, n}(\xs)| > |\hat f(\xs)- f_{j', n}(\xs)|$. 
This further implies $|\hat f(\xs) - f_{j, n}(\xs)| > r_n$, because if not, then both $|\hat f(\xs)- f_{j, n}(\xs)| \le r_n$ and $|\hat f(\xs)- f_{j', n}(\xs)| \le r_n$ implies $d(f_{0, n}, f_{1, n}) \le 2r_n$ which yields a contradiction. Therefore, we have: 
$$
 \P_{j}\left(|\hat f(\xs) - f(\xs)| \ge r_n\right) \ge  \P_{j}(\psi \neq j)\,.
$$

This completes the proof of the reduction scheme. Now for any $\psi$: 
\begin{align}
\label{eq:lb_testing_1}
     \bbP_0(\psi \neq 0) +  \bbP_1(\psi \neq 1) & = 1 - \left(\ \bbP_0(\psi \neq 1) -  \bbP_1(\psi \neq 1)\right) \notag \\
    & \ge 1 - \TV( \bbP_0,  \bbP_1) \notag \\
    & \ge 1  - \sqrt{\frac12 \KL\left( \bbP_0 \mid  \bbP_1\right)} \,,
\end{align}
where the last inequality follows from Pinsker's inequality. Throughout the rest of the proof, the $\lesssim$ sign will be used to hide constants that are free of $n,L$, and $C$. We will choose the constants $L$ and $C$ appropriately at the end. 

\noindent Next, we upper bound the KL divergence. As we have $n_P$ observations from the source domain and $n_Q$ observations from the target domain, the KL divergence can be decomposed as: 
\begin{equation}
\label{eq:KL_decomp}
     \KL\left( \bbP_0 \mid  \bbP_1\right) = n_P\KL\left(P_{0} \mid P_{ 1}\right) + n_Q \KL\left(Q_{0} \mid Q_{1}\right)
\end{equation}
Let us first bound the KL divergence on the source domain: 
\begin{align}
\label{eq:source_KL_bound}
    \KL(P_{0} \mid P_{1}) & = \bbE_P\left[ \KL(P_{0}(Y \mid X) \mid P_{1}(Y \mid X))\right] \notag\\
    & = \bbE_P[(f_{0, n}(\xs) - f_{1, n}(\xs))^2] \notag \\
    & = \bbE_P[f^2_{1, n}(\xs)] \notag\\
    & = L^2 h_n^{2\beta} \bbE_P K^2\left(\frac{X-\xs}{h_n}\right) \lesssim \ L^2 h_n^{2\beta + D} \,,
\end{align}
where the last inequality follows from \cref{lem:techlem1}, part (iii). 
Now, we move on to the target domain. %Therefore, we can bound the KL divergence between the distributions on the target domain as follows: 
%\begin{align}
%\label{eq:KL_lb_1}
%    \KL\left(\Pr_{T, 0} \mid \Pr_{T, 1}\right) & = \E_X \left[\left(f_{0, n}(\xs) - f_{1, n}(\xs)\right)^2\right] \notag \\
%     & = \E_X[f_{1, n}(\xs)^2] \notag \\
%     & = L^2h^{2\beta} \E_{Z, U}\left[K^2\left(\frac{\phi(Z) - \phi(z_\star)}{h} + \frac{\rho_n}{h}(U - u_\star)\right)\right]
%\end{align}
We will bound the corresponding KL divergence separately in two cases, depending on whether $\rho_n$ is large or smaller than the threshold $(n_P^{\frac{2\beta + d}{2\beta + D}} + n_Q)^{-\frac{1}{2\beta + d}}$.  
\\\\
\emph{Case 1: When $\rho_n \le C''(n_P^{\frac{2\beta + d}{2\beta + D}} + n_Q)^{-\frac{1}{2\beta + d}}$}.  \ As argued before, in this regime $\rho_n\le h_n$. Therefore,
\begin{align*}
    & \KL(Q_0\mid Q_1) = L^2 h_n^{2\beta}\bbE_Q K^2\left(\frac{X-\xs}{h_n}\right) \lesssim L^2 h_n^{2\beta+d}\,, 
\end{align*}
where the last inequality follows from \cref{lem:techlem1}, part (v).

\noindent \emph{Case 2: $\rho_n > C'(n_P^{\frac{2\beta + d}{2\beta + D}} + n_Q)^{-\frac{1}{2\beta + d}}$}. \ As argued before, in this setting $\rho_n\ge h_n$.  Therefore, 
\begin{align*}
    & \KL(Q_0\mid Q_1) = L^2 h_n^{2\beta}\bbE_Q K^2\left(\frac{X-\xs}{h_n}\right) \lesssim L^2 h_n^{2\beta+D}\rho_n^{d-D}\,, 
\end{align*}
where the last inequality follows from \cref{lem:techlem1}, part (iv). 
Combining our conclusions from Case 1 and Case 2, we conclude:
\begin{equation}
\label{eq:target_KL_bound}
\KL(Q_{0} \mid Q_{1})  \lesssim 
\begin{cases}
     L^2 h_n^{2\beta + d} & \text{if } \ \ \rho_n \le C''(n_P^{\frac{2\beta + d}{2\beta + D}} + n_Q)^{-\frac{1}{2\beta + d}} \\
     L^2 h_n^{2\beta + D}\rho_n^{d - D} & \text{if}\ \ \rho_n > C'(n_P^{\frac{2\beta + d}{2\beta + D}} + n_Q)^{-\frac{1}{2\beta + d}} \,.
\end{cases}
\end{equation}
Combining the bounds on equations  \eqref{eq:KL_decomp}, \eqref{eq:source_KL_bound}, and \eqref{eq:target_KL_bound} we conclude:   
\begin{equation}
    \KL(\bbP_0 \mid \bbP_1) \lesssim  
    \begin{cases}
     L^2 n_P h_n^{2\beta + D} +  L^2 n_Q h_n^{2\beta + d} & \text{if } \ \ \rho_n \le C''(n_P^{\frac{2\beta + d}{2\beta + D}} + n_Q)^{-\frac{1}{2\beta + d}} \\
     L^2 n_P h_n^{2\beta + D} + L^2 n_Q h_n^{2\beta + D}\rho_n^{d - D} & \text{if}\ \ \rho_n > C'(n_P^{\frac{2\beta + d}{2\beta + D}} + n_Q)^{-\frac{1}{2\beta + d}} \,.
\end{cases}
\end{equation}
Therefore, there exists constants $C_0$ and $\tilde{C}_0$ (independent of $L$), such that the following minimax lower bound holds: 
\begin{align*}
 & \inf_{\hat f} \sup_{f \in \Sigma(\beta, L)} \E\left[(\hat f(\xs) - f(\xs))^2\right]  \\
 & \ge 
 \begin{cases}
     \frac{r_n^2}{2}\left(1 - \sqrt{\frac12 C_0 L^2 n_P h_n^{2\beta + D} + C_0 L^2 n_Q h_n^{2\beta + d}}\right) & \text{if } \ \ \rho_n \le C''(n_P^{\frac{2\beta + d}{2\beta + D}} + n_Q)^{-\frac{1}{2\beta + d}} \\
     \frac{r_n^2}{2}\left(1 - \sqrt{\frac12  \tilde{C}_0 L^2 n_P h_n^{2\beta + D} + \tilde{C}_0 L^2 n_Q h_n^{2\beta + D}\rho_n^{d - D} }\right) & \text{if } \ \ \rho_n > C'(n_P^{\frac{2\beta + d}{2\beta + D}} + n_Q)^{-\frac{1}{2\beta + d}}
 \end{cases}
\end{align*}
Finally recall our choice of bandwidth $h_n$ from \eqref{eq:def_h}. If $h_n=C(n_P^{\frac{2\beta+d}{2\beta+D}}+n_Q)^{-\frac{1}{2\beta+d}}$, then $h_n\le C(n_P^{-\frac{1}{2\beta+D}}\wedge n_Q^{-\frac{1}{2\beta+d}})$. This implies $n_P h_n^{2\beta+D}+n_Q h_n^{2\beta+d}\le C^{2\beta+D}+C^{2\beta+d}$. On the other hand, if $h_n=C(n_P+n_Q\rho_n^{d-D})^{-\frac{1}{2\beta+D}}$, then we have $h_n\le C(n_P^{-\frac{1}{2\beta+D}}\wedge (n_Q \rho_n^{d-D})^{-\frac{1}{2\beta+D}})$. This again implies $n_P h_n^{2\beta+D}+n_Q h_n^{2\beta+D}\rho_n^{d-D}\le C^{2\beta+d}+C^{2\beta+D}$. Combining these observations, we have 
$$
 \inf_{\hat f} \sup_{f \in \Sigma(\beta, L)} \E\left[(\hat f(\xs) - f(\xs))^2\right]  \ge 
 \begin{cases}
     \frac{r_n^2}{2}\left(1 - \sqrt{\frac12 C_0 L^2(C^{2\beta + d}+C^{2\beta+D})}\right) & \text{if } \ \ \rho_n \le C''(n_P^{\frac{2\beta + d}{2\beta + D}} + n_Q)^{-\frac{1}{2\beta + d}}\\
     \frac{r_n^2}{2}\left(1 - \sqrt{\frac12 \tilde{C}_0 L^2 (C^{2\beta + d}+C^{2\beta+D})}\right) & \text{if } \ \ \rho_n > C'(n_P^{\frac{2\beta + d}{2\beta + D}} + n_Q)^{-\frac{1}{2\beta + d}}
 \end{cases}
$$
Finally, choosing the constant $L$ (depending on $C$, $\beta$, $d$, $D$, $C_0$) such that $ C_0 L^2(C^{2\beta + d}+C^{2\beta+D}) \le 1/2$ and $\tilde{C}_0 L^2(C^{2\beta + d}+C^{2\beta+D})\le 1/2$, we conclude the proof. 


