\mathbb{P}\left( \frac{|\hat{f}_{h_{\beta_j}}(\xs) - f(\xs)|^2}{\psi_n(\beta_i)} \geq t \right)
&= \mathbb{P}\left( \frac{|\hat{f}_{h_{\beta_j}}(\xs) - f(\xs)|^2}{\psi_n(\beta_j)} \geq t \cdot \frac{\psi_n(\beta_i)}{\psi_n(\beta_j)} \right) \\
&\leq \exp\left( -\frac{t \log n}{C} \cdot \frac{\psi_n(\beta_i)}{\psi_n(\beta_j)} \right).
\end{aligned}
\end{equation}


Next, we evaluate the integral:
\[
\int_{t_j}^\infty \exp\left( -\frac{t \log n}{C} \cdot \frac{\psi_n(\beta_i)}{\psi_n(\beta_j)} \right) dt.
\]

Letting \( t_j = c_1 \cdot \frac{\psi_n(\beta_j)}{\psi_n(\beta_i)} \) for a sufficiently large constant \( c_1 > C \), we compute:
\begin{align*}
\int_{t_j}^\infty \exp\left( -\frac{t \log n}{C} \cdot \frac{\psi_n(\beta_i)}{\psi_n(\beta_j)} \right) dt
&= \int_{t_j}^\infty \exp\left( -\frac{t \log n}{C} \cdot \frac{\psi_n(\beta_i)}{\psi_n(\beta_j)} \right) dt \\
&= \left( \frac{C}{\log n} \cdot \frac{\psi_n(\beta_j)}{\psi_n(\beta_i)} \right)
\int_{c_1}^\infty \exp(-s) ds \\
&= \left( \frac{C}{\log n} \cdot \frac{\psi_n(\beta_j)}{\psi_n(\beta_i)} \right)
\cdot \exp(-c_1).
\end{align*}

So the tail integral is bounded by:
\[
\frac{C}{\log n} \cdot \frac{\psi_n(\beta_j)}{\psi_n(\beta_i)} \cdot \exp(-c_1).
\]

Meanwhile, the first term from \eqref{eq:tail_integral_decomp} is:
\[
t_j \cdot \mathbb{P}(\mathcal{E}_j) 
= \left( c_1 \cdot \frac{\psi_n(\beta_j)}{\psi_n(\beta_i)} \right) \cdot \mathbb{P}(\mathcal{E}_j)
\leq \left( c_1 \cdot \frac{\psi_n(\beta_j)}{\psi_n(\beta_i)} \right) \cdot 2(i-1) \cdot n^{-c_0^2/(4C)}.
\]

Putting the two pieces together, we get:
\begin{equation}
\label{eq:final_single_term}
\begin{aligned}
\mathbb{E} \left[ \frac{|\hat{f}_{h_{\beta_j}}(\xs) - f(\xs)|^2}{\psi_n(\beta_i)} \cdot \mathds{1}(\mathcal{E}_j) \right]
&\leq \underbrace{c_1 \cdot \frac{\psi_n(\beta_j)}{\psi_n(\beta_i)} \cdot 2(i-1) \cdot n^{-c_0^2/(4C)}}_{\text{(I)}} 
+ \underbrace{\frac{C}{\log n} \cdot \frac{\psi_n(\beta_j)}{\psi_n(\beta_i)} \cdot \exp(-c_1)}_{\text{(II)}}.
\end{aligned}
\end{equation}

Choosing \( c_0, c_1 \) large enough such that both (I) and (II) are bounded by \( \frac{1}{2\log^2 n} \), and recalling that \(|\mathcal{B}| = N \asymp \log n\), we conclude:
\[
\sum_{j = 1}^{i-1} \mathbb{E} \left[ \frac{|\hat{f}_{h_{\beta_j}}(\xs) - f(\xs)|^2}{\psi_n(\beta_i)} \cdot \mathds{1}(\mathcal{E}_j) \right]
\leq N \cdot \frac{1}{\log^2 n} \lesssim 1.
\]


\end{comment}

\section{Proof of \cref{thm:lepski_manifold}}\label{sec:lepskithm}
We begin with two technical Lemmas. The first one demonstrates a relationship between the order of the bias and the standard deviation for $\hat{f}$.
    \begin{lem}
    \label{lem:rate_discrepancy_Lepski}
    Suppose that 
    \begin{align}\label{eq:hnb}
    h_{n,\tilde{\beta}}:=\left(\frac{n_P^{\frac{2\tilde{\beta}+d}{2\tilde{\beta}+D}}+n_Q}{\log{n}}\right)^{-\frac{1}{2\tilde{\beta}+d}},
    \end{align}
    for some $\tilde{\beta}>0$, $D\ge 1$, and $1\le d\le D$. 
    Then the following conclusion holds:
    $$
    h_{n,\tilde{\beta}}^{2\tilde{\beta}} \times \left(n_P h_{n,\tilde{\beta}}^D + n_Q h_{n,\tilde{\beta}}^d\right) \ge \frac{\log{n}}{2^{\frac{2\tilde{\beta}+ D}{2\tilde{\beta} + d}}} \,.
    $$
\end{lem}

The next result proves an exponential concentration for $\hat{f}$. 
\begin{lem}[Exponential concentration]
\label{lem:stochastic_conc}
We assume that $\rho_n\ll \hns$ and the $Y_i$s are uniformly bounded. Also suppose that Assumptions \ref{asn:covshift} --- \ref{asn:regf}, and \eqref{eq:kernel} hold. Recall the definitions of $\Omega_n$ and $\psi_n$ from \eqref{eq:gev} and \eqref{eq:psin} respectively. Let $h_n\to 0$ be a sequence of bandwidths such that $n\psi_n h_n^D=n_p h_n^D + n_Q h_n^d\to \infty$.  Then there exists $T_0, c_1, c_2, \upsilon,C>0$ such that for all $t>T_0$, we have:
\begin{align*}
        & \bbP\left(\left|\hat f(\xs) - \bbE[\hat f(\xs)]\right| > t,\Omega_n\right)  \le C\exp\left(-(n\psi_n h_n^D)\frac{(t/2\upsilon)^2}{c_1 + c_2 (t/2\upsilon)}\right)\,.
    \end{align*}
\end{lem}

    \begin{proof}[Proof of \cref{thm:lepski_manifold}]
    The basic structure of the proof is borrowed from the standard proof of Lepski's adaptation argument (see e.g.~\cite{hutter2017notes}). Recall that we first consider a set of smoothness parameters: 
    $$
    \cB = \{0 \equiv \beta_0 < \beta_{\min} \equiv \tilde{\beta}_{1} < \tilde{\beta}_2 < \dots < \tilde{\beta}_N \equiv \beta_{\max}\}\,,
    $$
    where $\tilde{\beta}_{j}-\tilde{\beta}_{j-1}\asymp 1/\log{n}$. In view of \eqref{eq:hnb}, 
    given any $1\le j\le N$, we define 
    \begin{align}
    \label{eq:bandwidth_choice_Lepski}
    h_{n,j} := \left(\frac{n_P^{\frac{2\tilde{\beta}_j + d}{2\tilde{\beta}_j + D}} + n_Q}{\log{n}}\right)^{-\frac{1}{2\tilde{\beta}_j + d}} \,,
    \end{align}
    and $\delta_{n, j} := h_{n,j}^{\tilde{\beta}_j}$. It is easy to check that provided $n_P,n_Q>1$, $\delta_{n,j}\le \delta_{n,j-1}$ for $1\le j\le N$. 

    \noindent We begin by noting that it suffices to assume that $\beta\in\mathcal{B}$. If not, suppose $\beta\in (\tilde{\beta}_{j-1},\tilde{\beta}_j)$, for $1\le j\le N$. As $f^\star$ is $\beta$-H\"{o}lder locally at $\xs$, it is $\tilde{\beta}_{j-1}$-H\"{o}lder continuous around $\xs$. It suffices to show that $\delta_{n,j-1}/\delta_{n,j}\lesssim 1$. To wit, we first observe that 
    \begin{align*}
        \log\frac{\delta_{n,j-1}}{\delta_{n,j}}=\left(\frac{\tilde{\beta}_{j}}{2\tilde{\beta}_j+d}-\frac{\tilde{\beta}_{j-1}}{2\tilde{\beta}_{j-1}+d}\right)\log{\left(\frac{n_P^{\frac{2\tilde{\beta}_{j-1} + d}{2\tilde{\beta}_{j-1} + D}} + n_Q}{\log{n}}\right)}+\frac{\tilde{\beta}_j}{2\tilde{\beta}_j+d}\log{\left(\frac{n_P^\frac{2\tilde{\beta}_j+d}{2\tilde{\beta}_j+D}+n_Q}{n_P^\frac{2\tilde{\beta}_{j-1}+d}{2\tilde{\beta}_{j-1}+D}+n_Q}\right)}.
    \end{align*}
    As 
    $$\frac{\tilde{\beta}_j}{2\tilde{\beta}_j+d}-\frac{\tilde{\beta}_{j-1}}{2\tilde{\beta}_{j-1}+d} \lesssim \tilde{\beta}_j-\tilde{\beta}_{j-1} \lesssim \frac{1}{\log{n}},$$
    and 
    $$\log{\left(n_P^{\frac{2\tilde{\beta}_j+d}{2\tilde{\beta}_j+D}-\frac{2\tilde{\beta}_{j-1}+d}{2\tilde{\beta}_{j-1}+D}}\right)}\lesssim (\tilde{\beta}_j-\tilde{\beta}_{j-1})\log{n_P} \lesssim 1,$$
    we have the desired conclusion $\delta_{n,j-1}/\delta_{n,j}\lesssim 1$. 

    \vspace{0.1in}

    Based on the above argument, it suffices to assume that the true smoothness parameter $\beta$ actually lies in $\cB$, i.e., $\beta = \tilde{\beta}_{i^\star}$, for some $1\le i^\star\le N$, which is obviously unknown to the statistician.  Furthermore, we denote by $\hat f_j$ the estimator with $h_n \equiv h_{n,j}$. With the current notation, recall that our smoothness parameter $\hat \beta$ is estimated as follows: 
    $$
    \hat \beta = \max\{\tilde{\beta}_j: |\hat f_j(\xs) - \hat f_i(\xs)| \le C_\ell \delta_{n, i} \ \ \forall \ \ 1 \le i \le j-1\} \,.
    $$
    where $C_\ell>0$ is chosen large enough (to be specified later). 
    Finally, we have set $\hat f_{\rm adp}(\xs) = \hat f_{h_{n,\hat{\beta}}}(\xs)$. 
    For the subsequent analysis, we define the event $\cE_j := \{\hat \beta = \tilde{\beta}_j\}$. We have: 
    \begin{align}
    \label{eq:lepski_break_1}
        \bbE\left[\frac{|\hat f(\xs) - f^\star(\xs)|}{\delta_{n, i^\star}}\right] & = \sum_{j = 1}^N  \bbE\left[\frac{|\hat f_j(\xs) - f^\star(\xs)|}{\delta_{n, i^*}}\mathds{1}_{\cE_j}\right] \notag \\
        & = \sum_{j = 1}^{i^* - 1}\bbE\left[\frac{|\hat f_j(\xs) - f^\star(\xs)|}{\delta_{n, i^*}}\mathds{1}_{\cE_j}\right] + \sum_{j = i^*}^N \bbE\left[\frac{|\hat f_j(\xs) - f^\star(\xs)|}{\delta_{n, i^*}}\mathds{1}_{\cE_j}\right] 
    \end{align}
Now, for any $j > i^*$, by definition of the event $\cE_j$, we have: 
$$
|\hat f_j(\xs) - \hat f_{i^*}(\xs)| \le c_0 \delta_{n, i^*} \,.
$$

Therefore, 
\begin{align*}
    \sum_{j = i^*}^N \bbE\left[\frac{|\hat f_j(\xs) - f^\star(\xs)|}{\delta_{n, i^*}}\mathds{1}_{\cE_j}\right]  & \le \sum_{j = i^*}^N \bbE\left[\frac{|\hat f_j(\xs) - \hat f_{i^*}(\xs)|}{\delta_{n, i^*}}\mathds{1}_{\cE_j}\right]  + \sum_{j = i^*}^N \bbE\left[\frac{|\hat f_{i^*}(\xs) - f^\star(\xs)|}{\delta_{n, i^*}}\mathds{1}_{\cE_j}\right] \\ & \le C_\ell + \sum_{j = i^*}^N \bbE\left[\frac{|\hat f_{i^*}(\xs) - f^\star(\xs)|}{\delta_{n, i^*}}\mathds{1}_{\cE_j}\right]\lesssim 1,
\end{align*} 
where the last bound follows from \eqref{eq:genbound}.


\noindent
Now, we bound the first part, i.e. when $j < i^*$. We will begin with a bound for $\P(\cE_j)$. First observe that, for such a $j$: 
\begin{align*}
\cE_j & \subseteq \cup_{i = 1}^{i^* 
- 1} \left\{\left|\hat f_{i^*}(\xs) - \hat f_i(\xs)\right| > C_\ell \delta_{n, i}\right\} \\
& \subseteq \cup_{i = 1}^{i^* 
- 1} \left[ \left\{\left|\hat f_{i^*}(\xs) - f^\star(\xs)\right| > C_\ell \delta_{n, i}/2\right\} \cup \left\{\left| f^\star(\xs) - \hat f_i(\xs)\right| > C_\ell \delta_{n, i}/2\right\} \right]\\
& \subseteq \cup_{i = 1}^{i^* 
- 1} \left[\left\{\left|\hat f_{i^*}(\xs) - f^\star(\xs)\right| > C_\ell \delta_{n, i^*}/2\right\} \cup \left\{\left| f^\star(\xs) - \hat f_i(\xs)\right| > C_\ell \delta_{n, i}/2\right\}\right] \,.
 \end{align*}
Here the last inclusion follows from the fact that $\delta_{n, i} > \delta_{n, i^*}$ for $i \le i^*$. 
Next, recall the definition of $\Omega_n$ in \eqref{eq:gev}. 
Now, for the first part, we use the tail bound established in Lemma \ref{lem:stochastic_conc}. First of all, by \eqref{eq:biasgenbd} and \eqref{eq:meano1}, we have: 
$$
\left|\bbE[\hat f_{i}(\xs)] - f^\star(\xs)\right| \lesssim \delta_{n, i}
$$
for any $1 \le i \le i^*$, which follows from the observation that if a function is $\tilde{\beta}_{i^\star}$-smooth, then it is also $\tilde{\beta}_i$-smooth, for all $1 \le i \le i^*$. 
Therefore, if $C_\ell > 0$ is large enough, we have: 
\begin{align*}
    \bbP\left(\left| f^\star(\xs) - \hat f_i(\xs)\right| > C_\ell \delta_{n, i}/2\right) & \le \bbP\left(\left| \bbE[\hat f_i(\xs)] - \hat f_i(\xs)\right| > C_\ell \delta_{n, i}/4\right) \\
    & \le \bbP\left(\left| \bbE[\hat f_i(\xs)] - \hat f_i(\xs)\right| > C_\ell \delta_{n, i}/4, \Omega_n\right) + \bbP(\Omega_n^c) \\
    & \le C \exp\left(-\gamma_n(h_{n,i})\frac{(C_\ell \delta_{n, i}/4)^2}{c_1 + c_2 (C_\ell \delta_{n, i}/4)}\right) + C \exp\left(-c\gamma_n(h_{n,i})\right) =: \zeta_i\,,
\end{align*}
where $\gamma_n(h_{n,i}) := n_P h_{n,i}^D + n_Q h_{n,i}^d = n\psi_n h_n^D$. This implies: 
$$
\bbP(\cE_j) \le \sum_{i = 1}^{i^*- 1} (\zeta_{i^*} + \zeta_i) \lesssim \zeta_{i^*}\log{n}  +  \sum_{i = 1}^{i^*- 1} \zeta_i \,.
$$
From Lemma \ref{lem:rate_discrepancy_Lepski}, we know that $\delta_{n, i}^2 \gamma_n(h_i) \gtrsim \log{n}$ and by definition $\delta_{n, i} \downarrow 0$ as $n \uparrow \infty$. Therefore, it is immediate that 
\begin{align}\label{eq:ejtail}
\bbP(\cE_j) \le Cn^{-C_0}
\end{align}
for some constant $C_0$. Furthermore, we can make $C_0$ larger by choosing $C_\ell$ larger. 
Now, going back to the first summand of  \eqref{eq:lepski_break_1}, we have: 
\begin{align*}
&\;\;\;\sum_{j = 1}^{i^* - 1}\bbE\left[\frac{|\hat f_j(\xs) - f^\star(\xs)|}{\delta_{n, i^*}}\mathds{1}_{\cE_j}\right] \\ & = \sum_{j = 1}^{i^* - 1}\bbE\left[\frac{|\hat f_j(\xs) - f^\star(\xs)|}{\delta_{n, i^*}}\mathds{1}_{\cE_j \cap \Omega_n}\right]    + \sum_{j = 1}^{i^* - 1}\bbE\left[\frac{|\hat f_j(\xs) - f^\star(\xs)|}{\delta_{n, i^*}}\mathds{1}_{\cE_j \cap \Omega_n^c}\right] \\
& \le \sum_{j = 1}^{i^* - 1}\bbE\left[\frac{|\hat f_j(\xs) - \bbE[\hat f_j(\xs)]|}{\delta_{n, i^*}}\mathds{1}_{\cE_j \cap \Omega_n}\right]    + \sum_{j = 1}^{i^* - 1}\bbE\left[\frac{|\hat f_j(\xs) - \bbE[\hat f_j(\xs)]|}{\delta_{n, i^*}}\mathds{1}_{\cE_j \cap \Omega_n^c}\right]  \\
& \qquad \qquad + \sum_{j = 1}^{i^* - 1}\bbE\left[\frac{|\bbE[\hat f_j(\xs)] - f^\star(\xs)|}{\delta_{n, i^*}}\mathds{1}_{\cE_j \cap \Omega_n}\right]    + \sum_{j = 1}^{i^* - 1}\bbE\left[\frac{|\bbE[\hat f_j(\xs)] - f^\star(\xs)|}{\delta_{n, i^*}}\mathds{1}_{\cE_j \cap \Omega_n^c}\right] \\
& \lesssim \sum_{j = 1}^{i^* - 1}\bbE\left[\frac{|\hat f_j(\xs) - \bbE[\hat f_j(\xs)]|}{\delta_{n, i^*}}\mathds{1}_{\cE_j \cap \Omega_n}\right]    + \sum_{j = 1}^{i^* - 1}\bbE\left[\frac{|\hat f_j(\xs) - \bbE[\hat f_j(\xs)]|}{\delta_{n, i^*}}\mathds{1}_{\cE_j \cap \Omega_n^c}\right] + \sum_{j = 1}^{i^* - 1} \frac{\delta_{n, j}}{\delta_{n, i^*}}\bbP(\cE_j)  \\
& =: \Upsilon_1 + \Upsilon_2 + \sum_{j = 1}^{i^* - 1} \frac{\delta_{n, j}}{\delta_{n, i^*}}\bbP(\cE_j) \,.
\end{align*}
Let us first tackle the third summand. As we have we have already established an upper bound on $\bbP(\cE_j)$, we have: 
\begin{align}\label{eq:prelimzero}
    \sum_{j = 1}^{i^* - 1} \frac{\delta_{n, j}}{\delta_{n, i^*}}\bbP(\cE_j) \le Cn^{-C_0} \sum_{j = 1}^{i^* - 1} \frac{\delta_{n, j}}{\delta_{n, i^*}} \le Cn^{-C_0} \ \log{n} \ \frac{\delta_{n, 1}}{\delta_{n, i^*}} \overset{n \uparrow \infty}{\longrightarrow} 0 \,,
\end{align}
where the last conclusion follows from the fact that  $\delta_{n,1}/\delta_{n,i^*}$ is a polynomial in $n$ and that power can be dominated by $C_0$ by choosing this suitably large (i.e., choosing $C_\ell$ suitably large).

\vspace{0.1in}
\noindent We now move on to $\Upsilon_1$. Set $t_j:=C \delta_{n,j}/\delta_{n,i^\star}$ for some constant $C>0$ which is large enough. We will change the constants $C,c_1,c_2>0$ from line to line. Note that by using \cref{lem:stochastic_conc}, we have:
\begin{align*}
    \Upsilon_1 &= \sum_{j = 1}^{i^* - 1} \int_0^\infty \bbP\left(|\hat f_j(\xs) - \bbE[\hat f_j(\xs)]| > t\delta_{n, i^*}, \ \cE_j \cap \Omega_n\right)\ dt \\
    & \le \sum_{j = 1}^{i^* - 1} \left\{t_j \bbP(\cE_j) + \int_{t_j}^\infty \bbP\left(|\hat f_j(\xs) - \bbE[\hat f_j(\xs)]| > t\delta_{n, i^*}, \ \Omega_n\right) \ dt\right\} \\ 
    & \le \sum_{j = 1}^{i^* - 1} \left\{t_j \bbP(\cE_j) + C\int_{t_j}^\infty \exp\left(-\gamma_n(h_{n,j}) \frac{(t\delta_{n, i^*})^2}{c_1 + c_2 (t\delta_{n, i^*})}\right)  \ dt\right\} \\ 
    & = \sum_{j = 1}^{i^* - 1} \left\{t_j \bbP(\cE_j) + \frac{C}{\delta_{n, i^*}}\int_{t_j \delta_{n, i^*}}^\infty \exp\left(-\gamma_n(h_{n,j}) \frac{t^2}{c_1 + c_2 t}\right)  \ dt\right\} \\ 
    & = \sum_{j = 1}^{i^* - 1} \left\{t_j \bbP(\cE_j) + \frac{C}{\delta_{n, i^*}}\int_{t_j \delta_{n, i^*}}^\infty \exp\left(-\frac{(t \sqrt{\gamma_{n}(h_{n,j})})^2}{c_1 + c_2 t}\right)  \ dt\right\} \\
    & = \sum_{j = 1}^{i^* - 1} \left\{t_j \bbP(\cE_j) + \frac{C}{\delta_{n, i^*}\sqrt{\gamma_{n}(h_{n,j})}}\int_{t_j \delta_{n, i^*}\sqrt{\gamma_{n}(h_{n,j})}}^\infty \exp\left(-\frac{t^2}{c_1 + c_2 \frac{t}{\sqrt{\gamma_{n}(h_{n,j})}}}\right)  \ dt\right\} \\
    & \le \sum_{j = 1}^{i^* - 1} \left\{t_j \bbP(\cE_j) + \frac{C}{\delta_{n, i^*}\sqrt{\gamma_{n}(h_{n,j})}}\int_{t_j \delta_{n, i^*}\sqrt{\gamma_{n}(h_{n,j})}}^\infty \exp\left(-\frac12 \min\left\{\frac{t^2}{c_1}, \frac{t\sqrt{\gamma_{n}(h_{n,j})}}{c_2}\right\}\right)  \ dt\right\} 
    % & = \sum_{j = 1}^{i^* - 1} \left\{t_j \bbP(\Omega_n) + C\int_{t_j}^\infty \exp\left(- \frac{(\gamma_n(h_{n,j})t\delta_{n, i^*})^2}{c_1\gamma_n(h_{n,j}) + c_2 (\gamma_n(h_{n,j})t\delta_{n, i^*})}\right)  \ dt\right\} \\ 
    % & = \sum_{j = 1}^{i^* - 1} \left\{t_j \bbP(\Omega_n) + \frac{C}{\gamma_n(h_{n,j})\delta_{n, i^*}}\int_{t_j\gamma_n(h_{n,j})\delta_{n, i^*}}^\infty \exp\left(- \frac{t^2}{c_1\gamma_n(h_{n,j}) + c_2 t}\right)  \ dt\right\} \\
    % & \le \sum_{j = 1}^{i^* - 1} \left\{\frac{t_j \delta_{n,j}}{\delta_{n,i^*}} \bbP(\Omega_n) + \int_{\frac{t_j \delta_{n,j}}{\delta_{n,i^*}}}^\infty \bbP\left(|\hat f_j(\xs) - f^\star(\xs)| > t\delta_{n, i^*}, \ \Omega_n\right) \ dt\right\} \\
    % & \le \sum_{j = 1}^{i^* - 1} \left\{\frac{t_j \delta_{n,j}}{\delta_{n,i^*}} \bbP(\Omega_n) + \int_{\frac{t_j \delta_{n,j}}{\delta_{n,i^*}}}^\infty \bbP\left(|\hat f_j(\xs) - \bbE[\hat f_j(\xs)]| > t_j\delta_{n, j}/2, \ \Omega_n\right) \ dt\right\} \\
    % & \le \sum_{j = 1}^{i^* - 1} \left\{\frac{t_j \delta_{n,j}}{\delta_{n,i^*}} \bbP(\Omega_n) + C\exp\left(-\gamma_n(h_{n,j})\frac{(t_j\delta_{n, j}/2)^2}{c_1 + c_2(t_j\delta_{n, j}/2)}\right)\right\}
\end{align*}
As $t_j\delta_{n,i^{\star}}\sqrt{\gamma_n(h_{n,j})}\ge C \sqrt{\log{n}}$ for some large constant $C$, we have: 
 $$\max_{j<i^\star} \int_{t_j \delta_{n, i^*}\sqrt{\gamma_{n}(h_{n,j})}}^\infty \exp\left(-\frac12 \min\left\{\frac{t^2}{c_1}, \frac{t\sqrt{\gamma_{n}(h_{n,j})}}{c_2}\right\}\right)  \ dt \lesssim C n^{-C_0}$$
 for some large constant $C_0>0$. Also note that $(\delta_{n,i^\star}\sqrt{\gamma_n(h_{n,j})})^{-1}$ grows atmost polynomially in $n$. Therefore, 
 $$\sum_{j = 1}^{i^* - 1} \frac{1}{\delta_{n, i^*}\sqrt{\gamma_{n}(h_{n,j})}}\int_{t_j \delta_{n, i^*}\sqrt{\gamma_{n}(h_{n,j})}}^\infty \exp\left(-\frac12 \min\left\{\frac{t^2}{c_1}, \frac{t\sqrt{\gamma_{n}(h_{n,j})}}{c_2}\right\}\right)  \ dt \to 0.$$
 Finally for the first summand, then we have: 
\begin{align*}
    \sum_{j = 1}^{i^* - 1} t_j \bbP(\cE_j) & = C \sum_{j = 1}^{i^* - 1} \frac{\delta_{n, j}}{\delta_{n, i^*}} \bbP(\cE_j) 
    % \\
    % & \le C_1 \sum_{j = 1}^{i^* - 1} \frac{\delta_{n, j}}{\delta_{n, i^*}}  \exp\left(-c \gamma_n(h_{n,j})\right) \\
    % & \le C_1 \log{n} \ \exp\left(\log{\frac{\delta_{n, 1}}{\delta_{n, i^*}}} - c\gamma_n(h_1)\right)  \overset{n \uparrow \infty}{\longrightarrow} 0 \,.
\end{align*}
which is already shown to converge to $0$ as $n \uparrow \infty$, in \eqref{eq:prelimzero}. This shows that $\Upsilon_1\to 0$.

\vspace{0.1in}
\noindent We move on to the $\Upsilon_2$ term. By \eqref{eq:meano1}, we have:
$$ \bbE\left[\big|\hat{f}_j(\xs)-\bbE[\hat{f}_j(\xs)]\big|\mathds{1}(\Omega_n^c)\right] \lesssim (n_P h_{n,j}^D+n_Q h_{n,j}^d)^{-p} \exp\left(-\frac{m^2(n_P h_{n,j}^D+n_Q h_{n,j}^d)}{c_1+c_2 m}\right)\lesssim n^{-C_0},$$ 
for some large constant $C_0$. Once again as $\delta_{n,i^\star}^{-1}$ grows atmost polynomially in $n$, we have 
$$\frac{1}{\delta_{n,i^\star}}\sum_{j=1}^{i^\star-1}\bbE\left[\big|\hat{f}_j(\xs)-\bbE[\hat{f}_j(\xs)]\big|\mathds{1}(\Omega_n^c)\right] \lesssim \frac{\log{n}}{\delta_{n,i^\star}}n^{-C_0}\to 0.
$$
Therefore, $\Upsilon_2\to 0$. This completes the proof.

\end{proof}

 \section{Proofs of Lemmas from \cref{sec:pfmainres}}\label{sec:pfauxlem}

 \begin{proof}[Proof of \cref{lem:techlem1}]
     (i). We first claim that that Lebesque measure of the set $\cnu$ remains uniformly upper bounded with respect to $n$ and $u\in [-1,1]^D$.  Towards that end, first, observe that there exists $\lambda\in (0,1)$ such that  
\begin{align}\label{eq:uub1}
\left\|\frac{\phi(0)  - \phi(s \rho_n)}{\rho_n} + u_0 + \frac{h_n}{\rho_n} u\right\|_\infty \le 1 & \iff \left\|\nabla \phi(\lambda \rho_n s) s + u_0 + \frac{h_n}{\rho_n} u\right\|_\infty \le 1 \nonumber \\
& \implies \left\|\nabla \phi(\lambda \rho_n s) s\right\|_\infty \le 3 \nonumber \\
& \implies \left\|\nabla \phi(\lambda \rho_n s) s\right\|_2 \le 3\sqrt{D} \nonumber \\
& \implies \sqrt{s^\top \nabla \phi(\lambda \rho_n s)^\top \nabla \phi(\lambda \rho_n s) s} \le 3\sqrt{D} \nonumber \\
& \implies \|s\|_2 \le 3\sqrt{Dc} \,,
\end{align}
where the last line leverages the lower bound from \eqref{eq:manifold_curvature}. Hence $\cnu \subseteq B(0; 3\sqrt{Dc})$, which implies $\cnu$ is uniformly compact in both $n$ and $u$.

It remains to show that the Lebesgue measure of the set $\nu$ is uniformly lower bounded in $n$ and $u$, which we establish next. 
For notational simplicity define $b_{n,u} := u_0 + (h_n/\rho_n) u \in [-1,1]^d$.
We can rewrite $\cnu$ as: 
$$
\left\|\frac{\phi(0) - \phi(s \rho_n)}{\rho_n} + u_0 + \frac{h_n}{\rho_n} u\right\|_\infty \le 1 \quad  \iff \quad \left\|\nabla \phi(0) s + b_{n,u} + r_n\right\|_\infty \le 1 
$$
where $\|r_n\|_\infty = O(\rho_n)$ is the remainder term. Define the set 
$$
(\cnu)' := \left\{s: \left\|\nabla \phi(0) s + b_{n,u}\right\|_\infty \le 1/2\right\}.
$$
Since $\rho_n\to 0$ as $n\to\infty$, we have $\cnu \supseteq (\cnu)'$. Now, as per \eqref{eq:manifold_curvature}, $\nabla \phi(0)$ has full column rank. Therefore, there exists $b'_{n,u} \in \R^d$ such that $\nabla \phi(0) b'_{n,u} = b_{n,u}$. As a result, we have: 
$$
(\cnu)' = \left\{s: \left\|\nabla \phi(0) (s + b'_{n,u})\right\|_\infty \le c\right\} \,.
$$
As a consequence: 
$$
\rm{Leb}((\cnu)') = \rm{Leb}\{y: \left\|\nabla \phi(0)y\right\|_\infty \le c\}
$$
which is bounded from below as $\nabla \phi(0)$ has full column rank by Assumption \ref{asn:lowman}(1). This completes the proof. 

\vspace{0.05in}

\noindent (ii). The proof is very similar to part (i). So we omit the details.

\vspace{0.05in}

\noindent (iii). Note that 
\begin{align*}
    &\;\;\;\;\bbE_P \left[\Theta\left(\frac{X-\xs}{h_n}\right) K_{h_n}^{\upsilon}(X-\xs)\theta(x)\right] \\ &=\frac{1}{h_n^{\upsilon D}}\int_{[-1,1]^D} \Theta\left(\frac{w-\xs}{h_n}\right)K^{\upsilon}\left(\frac{w-\xs}{h_n}\right)\theta(w)p(w)\,dw \\ &=\frac{1}{h_n^{(\upsilon-1)D}}\int_{([-1,1]^D-x)/h_n} \Theta(u)K^{\upsilon}(u) \theta(\xs+u h_n)p(\xs+u h_n)\,du \\ &\overset{(a)}{\lesssim} \frac{1}{h_n^{(\upsilon-1)D}}\int_{[-1,1]^D} \Theta(u)K^{\upsilon}(u) p(\xs+u h_n)\,du \\ &\overset{(b)}{=}\frac{1}{h_n^{(\upsilon-1)D}}\,.
\end{align*}
Here (a) follows from the compact support assumption on $K(\cdot)$ (by choice) and the local boundedness of $\theta(\cdot)$. Also, (b) follows from the boundedness of $K(\cdot)$ and $p(\cdot)$ (see \eqref{eq:kernel} and \cref{asn:lowman}(1) respectively).
\vspace{0.05in}

\noindent (iv). Recall $h_n\le \rho_n$. The density $f_{n, Q}$ of $X$ on the target domain satisfies 
\begin{align}
\label{eq:def_target_X_density}
    f_{n, Q}(w) := \frac{1}{\rho_n^D} \int_{[-1, 1]^d} g\left(\frac{w - \phi(v)}{\rho_n}\right) \ q(v) \ dv \,.
\end{align} 
 Further, when $x\in\mrh$, there exists $z_0\in\mathcal{M}$ and $u_0\in [-1,1]^D$ such that $x=\phi(z_0)+u_0$. Without loss of generality, assume that $z_0=0$. Note that 
\begin{align*}
    &\;\;\;\;\bbE_Q \left[\Theta\left(\frac{X-\xs}{h_n}\right) K_{h_n}^{\upsilon}(X-\xs) \theta(x)\right] \\ & = \frac{1}{h_n^{\upsilon D}}\int_{[-1,1]^D} \Theta\left(\frac{w-\xs}{h_n}\right) K^{\upsilon}\left(\frac{w-\xs}{h_n}\right)\theta(w) f_{n,Q}(w)\, dw \\ & = \frac{1}{h_n^{(\upsilon-1)D}}\int_{([-1,1]^D-x)/h_n} \Theta(u)K^{\upsilon}(u)\theta(\xs+u h_n)f_{n,Q}(\xs+u h_n)\,du \\ & \overset{(a)}{\lesssim} \frac{1}{\rho_n^D h_n^{(\upsilon-1)D}}\int_{[-1,1]^D}\int_{[-1,1]^d} \Theta(u) K^{\upsilon}(u) g\left(\frac{\phi(0)+\rho_n u_0 + u h_n - \phi(v)}{\rho_n}\right) q(v)\,dv \,du \\ &=\frac{\rho_n^{d-D}}{h_n^{(\upsilon-1)D}}\int_{[-1,1]^D}\int_{[-1,1]^d/\rho_n} \Theta(u) K^{\upsilon}(u) g\left(\frac{\phi(0)-\phi(s \rho_n)}{\rho_n}+ u_0 + u \frac{h_n}{\rho_n}\right) q(s\rho_n)\,ds \,du \\ & \overset{(b)}{=}\frac{\rho_n^{d-D}}{h_n^{(\upsilon-1)D}}\int_{[-1,1]^D}\int_{\cnu} \Theta(u) K^{\upsilon}(u) g\left(\frac{\phi(0)-\phi(s \rho_n)}{\rho_n}+ u_0 + u \frac{h_n}{\rho_n}\right) q(s\rho_n)\,ds \,du \\ & \overset{(c)}{\lesssim} \frac{\rho_n^{d-D}}{h_n^{(\upsilon-1)D}}\,.
\end{align*}

Here (a) follows the compact support of $K(\cdot)$ (by choice) and the locally bounded nature of $\theta(\cdot)$. Next, we note that (b) follows from the definition of $\cnu$ in part (i). Finally (c) follows from \cref{asn:lowman}(2).

\vspace{0.05in}

\noindent (v). Recall $\rho_n\le h_n$. Note that 
\begin{small}
\begin{align*}
    &\;\;\;\; \bbE_Q [\Theta((X-\xs)/h_n) K_{h_n}^{\upsilon}(X-\xs) \theta(x)] \\ & = \frac{1}{h_n^{\upsilon D}}\int_{[-1,1]^d} \int_{[-1,1]^D} \Theta\left(\frac{\phi(v)+\rho_n u - \phi(0) - \rho_n u_0}{h_n}\right) K^{\upsilon}\left(\frac{\phi(v)+\rho_n u - \phi(0) - \rho_n u_0}{h_n}\right)\theta(\phi(v)+\rho_n u)g(u) q(v)\, du\, dv \\ & \overset{(a)}{\lesssim} \frac{1}{h_n^{\upsilon D - d}}\int_{[-1,1]^d/h_n}\int_{[-1,1]^D} \Theta\left(\frac{\phi(sh_n)-\phi(0)}{h_n}+\frac{\rho_n}{h_n}(u-u_0)\right) K^{\upsilon}\left(\frac{\phi(sh_n)-\phi(0)}{h_n}+\frac{\rho_n}{h_n}(u-u_0)\right)g(u)q(s h_n)\,du \,dv \\ &\overset{(b)}{=}\frac{1}{h_n^{\upsilon D-d}}\int_{[-1,1]^D} \int_{\ctu} \Theta\left(\frac{\phi(sh_n)-\phi(0)}{h_n}+\frac{\rho_n}{h_n}(u-u_0)\right) K^{\upsilon}\left(\frac{\phi(sh_n)-\phi(0)}{h_n}+\frac{\rho_n}{h_n}(u-u_0)\right)g(u)q(s h_n)\,du \,dv \\ & \overset{(c)}{\lesssim} \frac{1}{h_n^{\upsilon D-d}}\,,
\end{align*}
\end{small}
Once again, (a) follows the compact support of $K(\cdot)$ (by choice) and the locally bounded nature of $\theta(\cdot)$. Next, we note that (b) follows from the definition of $\ctu$ in part (ii). Finally (c) again follows from \cref{asn:lowman}(2). This completes the proof.
 \end{proof}
 \begin{proof}[Proof of \cref{lem:lbdeig}]
 Recall that $\hns=\big(n_P^{\frac{2\beta+d}{2\beta+D}}+n_Q\big)^{-\frac{1}{2\beta+d}}$. We begin by noting that 
     \begin{align}
\label{eq:break_app_man_exp_1}
    S_n=\E[\hat S_n/\psi_n] & = \frac{1}{n\psi_n} \left\{n_P \bbE_P\left[\bz\left(\frac{X - \xs}{h_n}\right)\bz\left(\frac{X - \xs}{h_n}\right)^\top K_{h_n}(X - \xs) \right] \right. \notag \\
    & \qquad \qquad \left. + n_Q \bbE_Q\left[\bz\left(\frac{X - \xs}{h_n}\right)\bz\left(\frac{X - \xs}{h_n}\right)^\top K_{h_n}(X - \xs) \right] \right\} \notag \\
    & =: \frac{n_P}{n\psi_n} T_P + \frac{n_Q}{n\psi_n} T_Q  
\end{align}
For $T_P$ observe that: 
\begin{align*}
    T_P & = \bbE_P\left[\bz\left(\frac{X - \xs}{h_n}\right)\bz\left(\frac{X - \xs}{h_n}\right)^\top K_{h_n}(X - \xs) \right] \\
    & = \frac{1}{h_n^D} \int_{[-1, 1]^D} \bz\left(\frac{w - \xs}{h_n}\right)\bz\left(\frac{w - \xs}{h_n}\right)^\top K\left(\frac{w - \xs}{h_n}\right) p(w) \ dw \\
    & = \int_{[-1, 1]^D/h_n} \bz\left(u\right)\bz\left(u\right)^\top K\left(u\right) p(\xs + h_nu) \ du \\
    & \overset{(i)}{=} \int_{[-1, 1]^D} \bz\left(u\right)\bz\left(u\right)^\top K\left(u\right) p(\xs + h_nu) \ du  \\
    & \overset{(ii)}{=} p(\xs) \int_{[-1, 1]^D} \bz\left(u\right)\bz\left(u\right)^\top K\left(u\right) \ du + O(h_n) =: \bA + O(h_n) \,.
\end{align*}

\noindent Here (i) follows from the compact support assumption on the kernel $K$ (by choice) and (ii) follows from the lower boundedness assumption on $p(\cdot)$ and its Lipschitz continuity (see \cref{asn:lowman}(1)).

\noindent Now, for $T_Q$, we divide the analysis into two parts: (i) $h_n \le \rho_n$ and (ii) $h_n \ge \rho_n$. 

\noindent \emph{Case (i).} Suppose that $h_n \le \rho_n$. Recall that the density $f_{n,Q}$ of $X$ on the target domain satisfies \eqref{eq:def_target_X_density}. Using this, we obtain: 
\begin{align*}
T_Q &= \bbE_Q\left[\bz\left(\frac{X - \xs}{h_n}\right)\bz\left(\frac{X - \xs}{h_n}\right)^\top K_{h_n}(X - \xs) \right]  \\
& =\frac{1}{h_n^D} \int_{\mathcal{M}_{\rho_n}} \bz\left(\frac{w - \xs}{h_n}\right)\bz\left(\frac{w - \xs}{h_n}\right)^\top K\left(\frac{w - \xs}{h_n}\right) f_{n, Q}(w) \ dw \\ 
    & = \int_{(\mrh-\xs)/h_n} \bz\left(u\right)\bz\left(u\right)^\top K\left(u\right) f_{n, Q}(\xs + h_nu) \ du  \\
    & \overset{(i)}{=} \int_{[-1, 1]^D} \bz\left(u\right)\bz\left(u\right)^\top K\left(u\right) f_{n, Q}(\xs + h_nu) \ du  \\
& = \frac{1}{\rho_n^D} \int_{[-1, 1]^D} \bz\left(u\right)\bz\left(u\right)^\top K\left(u\right) \int_{[-1, 1]^d}  g\left(\frac{\xs + h_n u - \phi(v)}{\rho_n}\right) \ q(v) \ dv \ du \\
& = \frac{1}{\rho_n^D} \int_{[-1, 1]^D} \bz\left(u\right)\bz\left(u\right)^\top K\left(u\right) \int_{[-1, 1]^d}  g\left(\frac{\phi(0)  - \phi(v)}{\rho_n} + u_0 + \frac{h_n}{\rho_n} u\right) \ q(v) \ dv \ du \\
& = \frac{\rho_n^d}{\rho_n^D} \int_{[-1, 1]^D} \bz\left(u\right)\bz\left(u\right)^\top K\left(u\right) \int_{[-1, 1]^d/\rho_n}  g\left(\frac{\phi(0)  - \phi(s \rho_n)}{\rho_n} + u_0 + \frac{h_n}{\rho_n} u\right) \ q(s \rho_n) \ ds \ du \\
& = \frac{\rho_n^d}{\rho_n^D} \int_{[-1, 1]^D} \bz\left(u\right)\bz\left(u\right)^\top K\left(u\right) \int_{\cnu}  g\left(\frac{\phi(0)  - \phi(s \rho_n)}{\rho_n} + u_0 + \frac{h_n}{\rho_n} u\right) \ q(s \rho_n) \, ds \, du, 
\end{align*}
where $\cnu$ is defined as in \eqref{eq:cenu1}. By \cref{lem:techlem1}, part (i), the Lebesgue measure of $\cnu$ is uniformly bounded in $n$ and $u$.
The conclusion in (i) follows from the compact support assumption on the Kernel $K$. Therefore, by \cref{asn:lowman}(2), we get:

\begin{align*}
T_Q & = \frac{\rho_n^d}{\rho_n^D} \left(q(0)\int_{[-1, 1]^D} \bz\left(u\right)\bz\left(u\right)^\top K\left(u\right) \int_{\cC_{n,u}}  g\left(\frac{\phi(0)  - \phi(s \rho_n)}{\rho_n} + u_0 + \frac{h_n}{\rho_n} u\right) \ \ ds \ du + O(\rho_n)\right) \\
& =: \frac{\rho_n^d}{\rho_n^D}\left(\bB_n + O(\rho_n)\right).
\end{align*}

\noindent Using the expressions for $T_P$ and $T_Q$, we then have: 
\begin{align*}
    \E\left[\frac{\hat S_n}{\psi_n}\right] & = \frac{\frac{n_P}{n}(\bA + O(h_n)) + \frac{n_Q}{n}\frac{\rho_n^d}{\rho_n^D}(\bB_n + O(\rho_n))}{\frac{n_P}{n} + \frac{n_Q}{n}\frac{\rho_n^d}{\rho_n^D}}
\end{align*}
This immediately implies: 
\begin{align}
\label{eq:min_eig_app_man}
\lambda_{\min}(\hat S_n/\psi_n) & \ge \min\left\{\lambda_{\min}(\bA + O(h_n)), \lambda_{\min}(\bB_n + O(\rho_n))\right\} \notag \\
& \ge \min\left\{\lambda_{\min}(\bA), \lambda_{\min}(\bB_n)\right\} - O(\rho_n) 
\end{align}
where in the last line, we use the fact that we are working under the assumption $\rho_n \ge h_n$. As $\rho_n \downarrow 0$, we effectively need to show that $\lambda_{\min}(\bA)$ and $\lambda_{\min}(\bB_n)$ are bounded away from 0 uniformly over $n$. For $\bA$, the lower bound is immediate from Assumptions \ref{asn:lowman}(1) and \eqref{eq:kernel}, as $\bA$ does not depend on $n$. For $\bB_n$ it is more tricky as $\bB_n$ depends on $n$ through the ratio $h_n/\rho_n$. To provide a lower bound for the minimum eigenvalue of $\bB_n$, we first note that  
$$
\liminf \lambda_{\min}(\bB_n) \ge c_0  q(0) \liminf \left(  \lambda_{\min}\left(\int_{[-1, 1]^D} \rm{Leb}(\cnu)\bz\left(u\right)\bz\left(u\right)^\top 
 \ du \right)\right)
$$
for some constant $c_0>0$ where we have leveraged the lower bounds from \cref{asn:lowman}(2) and \eqref{eq:kernel}. Here $\cnu$ is defined as in \eqref{eq:cenu1}. As $\cnu$ has Lebesgue measure bounded away from $0$ uniformly in $n$ and $u$ (see \cref{lem:techlem1}, part (i)), the conclusion follows.


\noindent
\emph{Case (ii).} Now suppose that $h_n \ge \rho_n$. The analysis of $T_P$ will remain the same. For $T_Q$, we define $\bm:=\bz \bz^{\top}$ and note that 
\begin{align*}
    T_Q &= \bbE_Q\left[\bz\left(\frac{X - \xs}{h_n}\right)\bz\left(\frac{X - \xs}{h_n}\right)^\top K_{h_n}(X - \xs) \right]  \\
    & = \frac{1}{h_n^D}\int_{[-1, 1]^d} \int_{[-1, 1]^D} \bz\left(\frac{\phi(v) - \phi(0)}{h_n} + \frac{\rho_n}{h_n}(u - u_0)\right)\bz\left(\frac{\phi(v) - \phi(0)}{h_n}+ \frac{\rho_n}{h_n}(u - u_0)\right)^\top \\
    & \qquad \qquad \qquad \times K\left(\frac{\phi(v) - \phi(0)}{h_n}+ \frac{\rho_n}{h_n}(u - u_0)\right) \ q(v) g(u) \ dv \ du \\
    & =  \frac{1}{h_n^D}\int_{[-1, 1]^d} \int_{[-1, 1]^D} \bm\left(\frac{\phi(v) - \phi(0)}{h_n}+ \frac{\rho_n}{h_n}(u - u_0)\right)K\left(\frac{\phi(v) - \phi(0)}{h_n}+ \frac{\rho_n}{h_n}(u - u_0)\right) \ q(v) g(u) \ dv \ du \\
    & = \frac{h_n^d}{h_n^D} \int_{[-1, 1]^d/h_n} \int_{[-1, 1]^D} \bm\left(\frac{\phi(s h_n) - \phi(0)}{h_n}+ \frac{\rho_n}{h_n}(u - u_0)\right) \\
    & \qquad \qquad \qquad \times   K\left(\frac{\phi(s h_n) - \phi(0)}{h_n}+ \frac{\rho_n}{h_n}(u - u_0)\right) \ q(s h_n) g(u) \ ds \ du \\ & = \frac{h_n^d}{h_n^D} \int_{[-1, 1]^D} \int_{\ctu} \bm\left(\frac{\phi(s h_n) - \phi(0)}{h_n}+ \frac{\rho_n}{h_n}(u - u_0)\right) \\
    & \qquad \qquad \qquad \times   K\left(\frac{\phi(s h_n) - \phi(0)}{h_n}+ \frac{\rho_n}{h_n}(u - u_0)\right) \ q(sh_n) g(u) \ ds \ du, 
\end{align*}
    where the set $\ctu$ is defined as in \eqref{eq:cenu2}. 


Note that $\ctu$ has Lebesgue measure bounded above and below, away from $\infty$ and $0$ respectively (see \cref{lem:techlem1}, part (ii)).  Therefore, using the fact that $\phi(s h_n)-\phi(0)=h_n\nabla\phi(0)s+o(h_n)$ (by \cref{asn:lowman}(2)), we observe that,

    \begin{align*}
    T_Q & = \frac{h_n^d}{h_n^D} \left(q(0) \int_{[-1, 1]^D} \int_{\ctu} \bm\left(\frac{\phi(s h_n) - \phi(0)}{h_n}+ \frac{\rho_n}{h_n}(u - u_0)\right) \right. \\
    & \qquad \qquad \qquad \left. \times   K\left(\frac{\phi(s h_n) - \phi(0)}{h_n}+ \frac{\rho_n}{h_n}(u - u_0)\right) \ g(u) \ ds \ du + O(h_n)\right) \\
     & = \frac{h_n^d}{h_n^D} \left(q(0) \int_{[-1, 1]^D} \int_{\ctu} \bm\left(\nabla \phi(0) s + \frac{\rho_n}{h_n}(u - u_0) + o(1)\right) \right. \\
    & \qquad \qquad \qquad \left. \times   K\left(\frac{\phi(s h_n) - \phi(0)}{h_n}+ \frac{\rho_n}{h_n}(u - u_0)\right) \ g(u) \ ds \ du + O(h_n)\right) \\
      & = \frac{h_n^d}{h_n^D} \left(q(0) \int_{[-1, 1]^D} \int_{\ctu} \bm\left(\nabla \phi(0) s + \frac{\rho_n}{h_n}(u - u_0)\right) \right. \\
    & \qquad \qquad \qquad \left. \times   K\left(\frac{\phi(sh_n) - \phi(0)}{h_n}+ \frac{\rho_n}{h_n}(u - u_0)\right) \ g(u) \ ds \ du + o(1)\right) \\
    & \triangleq  \frac{h_n^d}{h_n^D} \left(\bB_n + o(1)\right) \,.
\end{align*}
It thus suffices to argue that $\lambda_{\min}(\bB_n)$ is bounded away from $0$ uniformly over $n$. To that end, fix some unit vector $\ba$. Then, we have: 
\begin{align*}
    \ba^\top \bB_n \ba & \ge  c_0\int_{[-1, 1]^D} \int_{\ctu} \left(a^\top \bz\left(\nabla \phi(0) w+ \frac{\rho_n}{h_n}(u - u_0)\right)  \right)^2  \ dw \ du, 
\end{align*}
for some constant $c_0>0$, where we have again used \cref{asn:lowman}(2) and \eqref{eq:kernel}. Now, the right-hand side of the above equation is lower bounded as $\bz$ is a polynomial which can have only finitely many roots, and $\ctu$ has Lebesgue measure bounded away from $0$. 
 \end{proof}

 \begin{proof}[Proof of \cref{lem:conc_matrix}]
     Firstly, using \citet[Lemma 4.4.1]{Vershynin2018}, we observe that there exists some $C>0$ (depending on $d$ and $\ell$), such that 
    \begin{align*}
     \P\left(\left\|\frac{\hat S_n}{\psi_n} - S_n\right\| \ge 2t\right) & \le C  \max_{a: \lVert a\rVert=1} \P\left(\left|\frac{a^\top\hat S_n a}{\psi_n} - a^\top S_n a\right| \ge t\right) 
     \end{align*}
     Let us define $$\mu_i(a):=\frac{1}{n\psi_n}\E (a^{\top}\bz((X_i-\xs)/h_n))^2K_{h_n}(X_i-\xs), \quad \mbox{and} \quad H_i(a):=\frac{1}{n\psi_n}(a^{\top}\bz((X_i-\xs)/h_n))^2K_{h_n}(X_i-\xs)-\mu_i(a)$$ 
     for $1\le i\le n$. The above displays then imply 
     \begin{align*}
      \P\left(\left\|\frac{\hat S_n}{\psi_n} - S_n\right\| \ge 2t\right) \le C \max_{a: \lVert a\rVert=1}\P\left(\bigg|\sum_{i=1}^n H_i\bigg|\ge t\right)\,.
    \end{align*}
 Next, we apply Bernstein's inequality \citet[Theorem 2.8.1]{Vershynin2018}, for which we need a bound on the variance and the $L_\infty$ norm of $H_i$. For $L_\infty$ norm bound, note that  $(a^\top \bz((X_i - \xs)/h_n))^2K_{h_n}(X_i - \xs)$ is uniformly bounded for any unit vector $a$, because this term is non-zero only when $K_{h_n}(X_i - \xs)$, only when $\|X_i - \xs\|/h_n \le C$ (as $K$ is compactly supported). As $\bz$ is a polynomial in $(X_i - \xs)/h_n$, it is bounded for all $\|X_i- x\|/h_n$ and consequently the term is bounded uniformly in $a$ for all $\|a\|=1$. Therefore, $\sup_{a:\|a\|=1}\max_{1\le i\le n} |H_i(a)| \le M/(n\psi_n h_n^d)$ for some constant $M$. Regarding the variance, we have: 
\allowdisplaybreaks
\begin{align*}
    & \Var_P\left((a^\top \bz((X - \xs)/h_n))^2K_{h_n}(X - \xs)\right)  \le \bbE_P\left[\left((a^\top \bz((X - \xs)/h_n))^2K_{h_n}(X - \xs)\right)^2\right] \lesssim \frac{1}{h_n^D} \,.
    \end{align*}
The last inequality follows from \cref{lem:techlem1}, part (iii).

We move on to the variance under $Q$. Here we will divide into two cases (i) $\rho_n\ge h_n$, and (ii) $\rho_n\le h_n$. 

\vspace{0.05in}

\noindent \emph{When $\rho_n\ge h_n$.} In this case, we recall the density $f_{n,Q}(\cdot)$ defined in \eqref{eq:def_target_X_density}. We can then write 
    \begin{align*}
     & \Var_Q\left((a^\top \bz((X - \xs)/h_n))^2K_{h_n}(X - \xs)\right)  \le \bbE_Q\left[\left((a^\top \bz((X - \xs)/h_n))^2K_{h_n}(X - \xs)\right)^2\right] \lesssim \frac{\rho_n^{d-D}}{h_n^D}.
     \end{align*}
     The last inequality follows from \cref{lem:techlem1}, part (iv). 

Next, recall that under $h_n\le \rho_n$, we have $n\psi_n=n_P+n_Q \rho_n^{d-D}$. This implies 
$$
\sum_i \Var(H_i) \lesssim \frac{1}{(n\psi_n)^2} \left(\frac{n_P}{h_n^D} + \frac{n_Q \rho_n^{d-D}}{h_n^D}\right) = \frac{1}{n\psi_n h_n^D} \,.
$$

\noindent \emph{When $\rho_n\le h_n$.} In this case, we bound the variance under $Q$ as follows: 

\begin{align*}
     &\;\;\;\; \Var_Q\left((a^\top \bz((X - \xs)/h_n))^2K_{h_n}(X - \xs)\right) \\
     & \le \bbE_Q\left[\left((a^\top \bz((X - \xs)/h_n))^2K_{h_n}(X - \xs)\right)^2\right] \lesssim \frac{1}{h_n^{2D-d}}.
\end{align*}
Recall that under $\rho_n\le h_n$, we have $n\psi_n=n_P+n_Q h_n^{d-D}$. This implies 

$$
\sum_i \Var(H_i) \lesssim \frac{c_1}{(n\psi_n)^2} \left(\frac{n_P}{h_n^D} + \frac{n_Q}{h_n^{2D - d}}\right) = \frac{1}{n\psi_n h_n^D} \,.
$$
Therefore the same bound holds for $\sum_{i=1}^N \Var(H_i)$ in both cases. An application of the Bernstein inequality (see \citet[Lemma 4.4.1]{Vershynin2018}) then yields: 

\begin{align*}
    \P\left(\left|\sum_{i = 1}^n H_i\right| \ge t\right)  & \le 2\exp{\left(-\frac{t^2}{\frac{c_1}{n\psi_n h_n^D} + \frac{2M}{3n\psi_n h_n^d}t}\right)} \\
    & = \exp{\left(-n\psi_nh_n^D\frac{t^2}{c_1 + \frac{2M}{3}t}\right)} \\
    & \le \exp{\left(-n\psi_nh_n^D\frac{t^2}{c_1 + c_2 t}\right)}\,
\end{align*}
for the constant $c_2=2M/3>0$ and all large enough $n$. This completes the proof of the concentration inequality. Now regarding the $k^{th}$ moment: 
\begin{align*}
    \E\left[\left\|\frac{\hat S_n}{\psi_n} - S_n\right\|^k\right] & = k\int_0^{\infty}t^{k-1}  \P\left(\left\|\frac{\hat S_n}{\psi_n} - S_n\right\| \ge t\right) \ dt \\
    & \lesssim C\int_0^{\infty}t^{k-1}  \exp{\left(-\frac{t^2 (n\psi_nh_n^D)}{c_1 + c_2 t}\right)} \ dt \\
    & = \frac{1}{(n\psi_nh_n^D)^{k/2}} \int_0^{\infty}z^{k-1}  \exp{\left(-\frac{z^2}{c_1 + c_2 \frac{z}{\sqrt{n\psi_n h_n^D}}}\right)} \ dt \\
    & \overset{(i)}{\lesssim} \frac{1}{(n\psi_nh_n^D)^{k/2}} \int_0^{\infty}z^{k-1}  \exp{\left(-\frac{z^2}{c_1 + c_2 z}\right)} \ dt \\
    & \lesssim \frac{1}{(n\psi_nh_n^D)^{k/2}} \,.
\end{align*}
In (i), we have used the fact that $n\psi_n h_n^D \uparrow \infty$. This completes the proof.  
\end{proof}

Next, we move on to the proof of \cref{lem:bounding_mean_part}. We need two preparatory lemmas. 
\begin{lem}
    \label{lem:eps_4_moment_bound}
    Define 
    $$\tilde{s}_n :=\frac{1}{n}\sum_{i=1}^n \bz\left(\frac{X_i-\xs}{h_n}\right) K_{h_n}(X_i-\xs)f^\star(X_i).$$
    Suppose that Assumptions \ref{asn:covshift} --- \ref{asn:regf}, \eqref{eq:kernel} hold, and $h_n\to 0$. Then the following bound holds: 

    $$
    \E\left[\left\|\frac{\hat s_{n}-\tilde{s}_n}{\psi_n}\right\|^4\right] \lesssim \left\{\frac{1}{(n\psi_n h^D)^3} + \frac{1}{(n\psi_n h^D)^2}\right\}  = o(1) \ \ \ \text{ as } \ n\psi_n h^D \uparrow \infty \,.
    $$
\end{lem}
\begin{lem}
\label{lem:bound_centered_s_n_tilde}
Under the same assumptions as in \cref{lem:eps_4_moment_bound}, we have:
$$
\E\left[\left\|\frac{\tilde s_n}{\psi_n} - s_n \right\|_2^4\right] \le \frac{C}{(n\psi_nh^D)^2}  = o(1)\,.
$$
\end{lem}

\begin{proof}[Proof of \cref{lem:bounding_mean_part}]

    First consider the expectation $s_n$ of $\hat s_n/\psi_n$: 
    \allowdisplaybreaks
    \begin{align*}
        s_n = \E\left[\frac{\hat s_n}{\psi_n}\right]  & = \frac{1}{n\psi_n}\sum_i \E\left[\bz\left(\frac{X_i - \xs}{h}\right)K_{h_n}(X_i - \xs) f^\star(X_i)\right] 
    \end{align*}
    By \cref{lem:techlem1}, parts (iii), (iv), and (v), we get: 
    \begin{align}\label{eq:snO1}
    \left\lVert \E\left[\frac{\hat{s}_n}{\psi_n}\right]\right\rVert \lesssim \frac{1}{n\psi_n}(n_P + n_Q (\rho_n\vee h_n)^{d-D})=1.
    \end{align}
    Therefore, we have: 
    \begin{align*}
    \E\left[\left\|\frac{\hat s_n}{\psi_n}\right\|^4\right] & = \E\left[\left\|\frac{\hat{s}_n - \tilde s_n}{\psi_n} + \frac{\tilde{s}_n}{\psi_n} - s_n + s_n\right\|^4\right] \\
    & \lesssim \E\left\|\frac{\hat{s}_n - \tilde s_n}{\psi_n}\right\|^4 + \E\left\lVert\frac{\tilde{s}_n}{\psi_n}-s_n\right\rVert^4 + \lVert s_n\rVert^4 \lesssim 1.
    \end{align*}
    As argued before, $\|s_n\| \lesssim 1$. The conclusion now follows by combining Lemmas \ref{lem:eps_4_moment_bound} and \ref{lem:bound_centered_s_n_tilde}.
\end{proof}

\section{Proofs of Lemmas from Appendices \ref{sec:lepskithm} and \ref{sec:pfauxlem}}\label{sec:pfaddlem}

\begin{proof}[Proof of \cref{lem:rate_discrepancy_Lepski}]
Let us define
\[
S := n_P^{\frac{2\tilde{\beta} + d}{2\tilde{\beta} + D}} + n_Q,
\quad\text{and}\quad
A := \frac{2\tilde{\beta} + D}{2\tilde{\beta} + d}.
\]
We expand the expression:
\begin{align*}
h_{n,\tilde{\beta}}^{2\tilde{\beta}}(n_P h_{n,\tilde{\beta}}^D + n_Q h_{n,\tilde{\beta}}^d)
&= \left( \frac{S}{\log n} \right)^{-\frac{2\tilde{\beta}}{2\tilde{\beta} + d}} \cdot \left[ n_P \left( \frac{S}{\log n} \right)^{-\frac{D}{2\tilde{\beta} + d}} + n_Q \left( \frac{S}{\log n} \right)^{-\frac{d}{2\tilde{\beta} + d}} \right] \\
&= n_P \left( \frac{S}{\log n} \right)^{-\frac{2\tilde{\beta} + D}{2\tilde{\beta} + d}} + n_Q \left( \frac{S}{\log n} \right)^{-1} \\
&= n_P \left( \frac{S}{\log n} \right)^{-A} + \frac{n_Q \log n}{S}.
\end{align*}
We now consider two cases:
\paragraph{Case 1:} If $n_Q \ge n_P^{\frac{2\tilde{\beta} + d}{2\tilde{\beta} + D}}$, then $S \le 2n_Q$, so
\[
\frac{n_Q \log n}{S} \ge \frac{\log n}{2} \ge \frac{\log n}{2^A}.
\]

\paragraph{Case 2:} If $n_Q < n_P^{\frac{2\tilde{\beta} + d}{2\tilde{\beta} + D}}$, then $S \le 2n_P^{\frac{2\tilde{\beta} + d}{2\tilde{\beta} + D}}$, and
\begin{align*}
n_P \left( \frac{S}{\log n} \right)^{-A}
&\ge n_P \left( \frac{2n_P^{\frac{2\tilde{\beta} + d}{2\tilde{\beta} + D}}}{\log n} \right)^{-A}
= \left( \frac{\log n}{2} \right)^A \cdot n_P \cdot n_P^{-A \cdot \frac{2\tilde{\beta} + d}{2\tilde{\beta} + D}} \\
&= \left( \frac{\log n}{2} \right)^A \cdot n_P^{1 - A \cdot \frac{2\tilde{\beta} + d}{2\tilde{\beta} + D}} = \left( \frac{\log n}{2} \right)^A,
\end{align*}
since $A \cdot \frac{2\tilde{\beta} + d}{2\tilde{\beta} + D} = 1$. Hence
\[
n_P \left( \frac{S}{\log n} \right)^{-A} \ge \frac{\log n}{2^A}.
\]
In either case, we have
\[
h_{n,\tilde{\beta}}^{2\tilde{\beta}}(n_P h_{n,\tilde{\beta}}^D + n_Q h_{n,\tilde{\beta}}^d) \ge \frac{\log n}{2^A} =  \frac{\log n}{2^{\frac{2\tilde{\beta} + D}{2\tilde{\beta} + d}}}.
\]
\end{proof}

Next we move on to the proof of \cref{lem:stochastic_conc}. We need a preparatory lemma whose proof is deferred to the end of this Section.

\begin{lem}[Exponential concentration of $\hat s_n$ under boundedness]
    \label{lem:exp_conc_sn}
    Suppose $Y$ is compactly supported. Under the same Assumptions as in \cref{lem:bound_centered_s_n_tilde}, we have:
    $$
    \P\left(\left\|\frac{\hat s_n}{\psi_n} - s_n\right\|_2 \ge t\right) \le  C\exp\left(-n\psi_n h_n^D \frac{t^2}{c_1 + c_2 t}\right) \,.
    $$
    where $s_n = \E[\hat s_n/\psi_n]$. 
\end{lem}

\begin{proof}[Proof of \cref{lem:stochastic_conc}]
    From \eqref{eq:ourestim}, recall that $\hat f(\xs)$ is non-zero only when the minimum eigenvalue of $\hat S_n/\psi_n \ge \tau_n$ where $\tau_n=(n\psi_n h_n^D)^{-p}$ for some $p\ge 1$. For ease of presentation, define the event $A_n:=\{\lmn(S_n/\psi_n)\ge \tau_n\}$. Hence, by definition, $\hat f(\xs) = 0$ on $A_n^c$.  
    Furthermore, recall the definition of the even $\Omega_n$ from \eqref{eq:gev}. We start by showing that $\bbE[|\hat f(\xs)|] \lesssim 1$. To wit, observe that: 
    \begin{align*}
        \bbE\left[|\hat f(\xs)| \right] & =   \bbE\left[|\hat f(\xs)| \mathds{1}_{A_n}\right] \le \bbE\left[|\hat f(\xs)| \mathds{1}_{\Omega_n}\right] +  \bbE\left[|\hat f(\xs)| \mathds{1}_{A_n \cap \Omega_n^c}\right].
    \end{align*}
    The second term is $o(1)$ by \eqref{eq:meano1}. For the first term, note that, by \cref{lem:lbdeig}, we have: 
    \begin{align*}
        \bbE\left[\left|e_1^\top \left(\frac{\hat S_n}{\psi_n}\right)^{-1}\frac{\hat s_n}{\psi_n}\right| \mathds{1}_{\Omega_n}\right] \lesssim \bbE\left[\left\|\frac{\hat s_n}{\psi_n}\right\|_2\right] = O(1)
    \end{align*}
    where the final bound follows from \cref{lem:bounding_mean_part}. This shows $\bbE|\hat{f}(\xs)\lesssim 1$. 
\\\\
\noindent 
Having proved that $\hat f(\xs)$ has a finite $L_1$ norm, we now derive a  concentration bound for all $t > T_0$ (large enough, to be specified later). Observe that  
\begin{align*}
    & \bbP\left(\left|\hat f(\xs) - \bbE[\hat f(\xs)]\right| > t, \Omega_n\right) \le \bbP\left(\left|e_1^\top \left(\frac{\hat S_n}{\psi_n}\right)^{-1}\frac{\hat s_n}{\psi_n} - e_1^{\top} S_n^{-1}s_n + e_1^\top S_n^{-1} s_n - \bbE[\hat f(\xs)]\right| > t, \Omega_n\right).
\end{align*}
By \cref{lem:lbdeig} and \eqref{eq:snO1}, we have $e_1^\top S_n^{-1} s_n\lesssim$ and we just proved above that $\bbE|\hat f(\xs)|\lesssim 1$. Let us choose $T_0$ such that: 
$$
T_0 > 2\sup_{n\ge 1} \left(|e_1^\top S_n^{-1} s_n| + |\bbE[\hat f(\xs)]|\right) \,.
$$
We then have 
\begin{align*}
     & \bbP\left(\left|\hat f(\xs) - \bbE[\hat f(\xs)]\right| > t, \Omega_n\right)   \\
     & \le \bbP\left(\left|e_1^\top \left(\frac{\hat S_n}{\psi_n}\right)^{-1}\frac{\hat s_n}{\psi_n} - e_1^{\top} S_n^{-1}s_n\right| > t/2, \Omega_n\right)\\
     & \le \bbP\left(\left|e_1^\top \left(\frac{\hat S_n}{\psi_n}\right)^{-1}\frac{\hat s_n}{\psi_n} - e_1^\top \left(\frac{\hat S_n}{\psi_n}\right)^{-1}s_n\right| > t/2, \Omega_n\right) +  \bbP\left(\left|e_1^\top \left(\frac{\hat S_n}{\psi_n}\right)^{-1}s_n - e_1^{\top} S_n^{-1}s_n\right| > t/2, \Omega_n\right) \\
     & \le \bbP\left(\left\|\frac{\hat s_n}{\psi_n} - s_n\right\|_2 > \frac{t}{2\upsilon_1}\right) + \bbP\left(\left\|\frac{\hat S_n}{\psi_n} - S_n\right\|_{\rm op} > \frac{t}{2\upsilon_2}\right) \\
     & \le C_1\exp\left(-(n\psi_n h_n^D)\frac{(t/2\upsilon_1)^2}{c_1 + c_2 (t/2\upsilon_1)}\right) + C_2 \exp\left(-(n\psi_n h_n^D)\frac{(t /2\upsilon_2)^2}{c_1 + c_2 (t/2\upsilon_2)}\right) \,.
\end{align*}
The penultimate inequality holds for some $\upsilon_1,\upsilon_2>0$ by \cref{lem:lbdeig} and \eqref{eq:invbound}. The last inequality follows from \cref{lem:exp_conc_sn} and the second inequality follows from  \cref{lem:conc_matrix}. This completes the proof. 
\end{proof}
\begin{proof}[Proof of \cref{lem:eps_4_moment_bound}]
We write the polynomial vector function $\bz(\cdot)=(z_j(\cdot))_{j\ge 1}$, which is a vector of fixed dimension (not growing with $n$). 

    \begin{align*}
    & \E\left[\left\|\frac{\hat s_{n}-\tilde{s}_n}{\psi_n}\right\|_2^4\right] \\
    & = \E\left[\left(\sum_{j} \left(\frac{1}{n\psi_n} \sum_iz_j\left(\frac{X_i - \xs}{h_n}\right)K_{h_n}(X_i - \xs)(Y_i-f^\star(X_i))\right)^ 2\right)^2\right] \\
    & \lesssim \sum_{j} \E\left[\left(\frac{1}{n\psi_n} \sum_i z_j\left(\frac{X_i - \xs}{h_n}\right)K_{h_n}(X_i - \xs)(Y_i-f^\star(X_i))\right)^ 4\right] \\
    & = \frac{1}{(n\psi_n)^4} \sum_{j} \Bigg\{ \sum_{i=1}^n  \E\left[\left(z_j\left(\frac{X_i - \xs}{h_n}\right)K_{h_n}(X_i - \xs)(Y_i-f^\star(X_i))\right)^4\right]  \\
    & \qquad +  \sum_{i \neq i'} \E\left[\left(z_j\left(\frac{X_i - \xs}{h_n}\right)K_{h_n}(X_i - \xs)(Y_i-f^\star(X_i))\right)^2\right]\\ &\qquad\qquad\E\left[\left(z_j\left(\frac{X_{i'} - x}{h_n}\right)K_{h_n}(X_{i'} - x)(Y_{i'}-f^\star(X_{i'}))\right)^2\right]\Bigg\}\,.
    \end{align*}
    By \cref{lem:techlem1}, part (iii), we have: 
    \begin{align*}
        \bbE_P\left[\left(z_j\left(\frac{X - \xs}{h_n}\right)K_{h_n}(X-\xs)(Y-f^\star(\xs))\right)^{\upsilon}\right]\lesssim \frac{1}{h_n^{(\upsilon-1)D}}
    \end{align*}
    for $\upsilon=\{2,4\}$. Further, by using Assumptions \ref{asn:lowman}, parts (2) and (3), coupled with \cref{lem:techlem1}, parts (iv) and (v), we get: 
    \begin{align*}
        \bbE_Q\left[\left(z_j\left(\frac{X - \xs}{h_n}\right)K_{h_n}(X-\xs)(Y-f^\star(\xs))\right)^{\upsilon}\right]\lesssim \frac{(\rho_n\vee h_n)^{d-D}}{h_n^{(\upsilon-1)D}},
    \end{align*}
    for $\upsilon=\{2,4\}$. Combining these observations, we get: 

    \begin{align*}
     &\;\;\;\;\E\left[\left\|\frac{\hat s_{n}-\tilde{s}_n}{\psi_n}\right\|_2^4\right] \\ &\lesssim \frac{1}{(n\psi_n)^4} \left(\frac{n_P}{h_n^{3D}}+\frac{n_Q(\rho_n\vee h_n)^{d-D}}{h_n^{3D}}+\frac{n_P(n_P-1)}{h_n^{2D}}+\frac{n_Q(n_Q-1)(\rho_n\vee h_n)^{2(d-D)}}{h_n^{2D}}+2\frac{n_Pn_Q(\rho_n\vee h_n)^{d-D}}{h_n^{2D}}\right) \\
    & \le \frac{1}{(n\psi_n)^4}\left(\frac{n\psi_n}{h_n^{3D}}+\left(\frac{n_p}{h_n^D}\right)^2+\left(\frac{n_Q(\rho_n\vee h_n)^{d-D}}{h_n^D}\right)^2+2\left(\frac{n_P}{h_n^D}\frac{n_Q(\rho_n\vee h_n)^{d-D}}{h_n^D}\right)\right)\\ &\le \frac{1}{(n\psi_nh_n^D)^3}+\frac{1}{(n\psi_nh_n^D)^2}\,.
    \end{align*}
    This completes the proof. 
\end{proof}

\begin{proof}[Proof of \cref{lem:bound_centered_s_n_tilde}]
    We prove it by proving exponential concentration as in Lemma \ref{lem:conc_matrix}. Note that: 
    $$
    \frac{\tilde s_n}{\psi_n} - s_n = \frac{1}{n\psi_n}\sum_i \left(\bz\left(\frac{X_i - \xs}{h_n}\right)K_{h_n}(X_i - \xs)f^\star(X_i) - \mu_i\right) =: \sum_i H_i 
    $$
    where $\mu_i$ is the expectation of $i^{th}$ term. 
    Note that $H_i$ is a finite-dimensional vector with fixed dimension, say $p$, (not growing with $n$).  Suppose $\cN_{1/2}$ be a $1/2$-covering set of $\bbS^{p-1}$, i.e. given any $a \in \bbS^{p-1}$, we can find $a_{1/2} \in \cN_{1/2}$ such that $\|a - a_{1/2}\| \le 1/2$. Then we have: 
    \begin{align*}
    \|\sum_i H_i \| & = \sup_{a \in \bbS^{p-1}} \langle a, \sum_i H_i \rangle \\
    & = \sup_{a \in \bbS^{p-1}}\langle a - a_{1/2} + a_{1/2}, \sum_i H_i \rangle \\
    & \le \sup_{a \in \bbS^{p-1}}\langle a - a_{1/2} , \sum_i H_i \rangle + \max_{v \in \cN_{1/2}} \langle v, \sum_i H_i \rangle \\
    & \le \|\sum_i H_i\| \sup_{a \in \bbS^{p-1}} \|a - a_{1/2}\| + \max_{v \in \cN_{1/2}} \langle v, \sum_i H_i \rangle \\
    & \le \frac12 \|\sum_i H_i\|+ \max_{v \in \cN_{1/2}} \langle v, \sum_i H_i \rangle 
    \end{align*}
Hence, we have: 
$$
\|\sum_i H_i \| \le 2 \max_{v \in \cN_{1/2}} \langle v, \sum_i H_i \rangle \,.
$$
Therefore, we have: 
$$
\P(\|\sum_i H_i \| \ge 2t) \le \P(\max_{v \in \cN_{1/2}} \langle v, \sum_i H_i \rangle \le t) \le |\cN_{1/2}| \P(|\langle v, \sum_i H_i \rangle| \ge t) \,.
$$
The above calculation indicates that we need to establish the exponential bound for the random variable $\sum_i v^\top H_i$ for some $v \in \bbS^{p-1}$. We apply Bernstein's inequality (see \citet[Theorem 2.8.1]{Vershynin2018}) for this purpose. As $H_i$s are independent mean $0$ random vectors, we bound the variance as follows:    
    \allowdisplaybreaks
    \begin{align*}
        \sum_i \E[(v^\top H_i)^2] & \le \frac{1}{(n\psi_n)^2}\sum_i\E\left[\left(v^\top\bz\left(\frac{X_i - \xs}{h_n}\right)K_{h_n}(X_i - \xs)f^\star(X_i)\right)^2\right] \\
        & \lesssim \frac{1}{(n\psi_n)^2}\left\{\frac{n_P}{h_n^D} + \frac{n_Q(\rho_n\vee h_n)^{d-D}}{h^{D}}\right\} \le \frac{1}{n\psi_n h^D} \,.
    \end{align*}
    The above inequality follows from \cref{lem:techlem1}, parts (iii), (iv), and (v). 
    Furthermore, as $K(\cdot)$ is compactly supported, we have: 
    $$
    \frac{1}{n\psi_n}\left|v^\top\bz\left(\frac{X_i - \xs}{h_n}\right)K_{h_n}(X_i - \xs)f^\star(X_i) - \mu_i\right| \lesssim \frac{C_2}{n\psi_n h_n^d}\,.
    $$
    Therefore, by vector Bernstein's inequality, we have: 
    $$
    \P\left(\left|\sum_i (v^\top H_i)\right| \ge t\right) \lesssim  \exp\left(-n\psi_n h_n^D \frac{t^2}{c_1 + c_2 t}\right)\,.
    $$
    A standard tail integral computation (as in the proof of \cref{lem:conc_matrix}) then yields 
    \begin{align*}
        \E\left[\left\|\frac{\tilde s_n}{\psi_n} - s_n \right\|^4\right]  \lesssim \frac{1}{(n\psi_nh_n^D)^2} \,.
    \end{align*}
This completes the proof. 
    \end{proof}

\begin{proof}[Proof of \cref{lem:exp_conc_sn}]
The proof essentially follows the steps of the proof of Lemma \ref{lem:bound_centered_s_n_tilde}. From \eqref{eq:snO1}, note that $s_n\lesssim 1$. Recall the definition of $(\hat s_n/\psi_n)$ (see \eqref{eq:hsn}): 
    $$
\frac{\hat s_n}{\psi_n} = \frac{1}{n \psi_n}\sum_{i=1}^n \bz\left(\frac{X_i - \xs}{h_n}\right)K\left(\frac{X_i - \xs}{h_n}\right) Y_i 
    $$
    This has basically the same form as $\tilde{s}_n/\psi_n$ except that $f^\star(X_i)$ is replaced with $Y_i$. By leveraging the boundedness assumption on the $Y_i$s, we now repeat the same Bernstein concentration argument used in the proof of \cref{lem:bound_centered_s_n_tilde}. We skip the details for brevity.   
\end{proof}

