\begin{align}
    \label{eq:L1_norm_bound_1}
        \bbE\left[|\hat f(\xs)| \right] & =   \bbE\left[|\hat f(\xs)| \mathds{1}_{A_n}\right] \notag \\
        & =  \bbE\left[|\hat f(\xs)| \mathds{1}_{A_n \cap \Omega_n}\right] +  \bbE\left[|\hat f(\xs)| \mathds{1}_{A_n \cap \Omega_n^c}\right] \notag \\
        & \le  \bbE\left[|\hat f(\xs)| \mathds{1}_{\Omega_n}\right] +  \bbE\left[|\hat f(\xs)| \mathds{1}_{A_n \cap \Omega_n^c}\right] \notag \\
        & =  \bbE\left[\left|e_1^\top \left(\frac{\hat S_n}{\psi_n}\right)^{-1}\frac{\hat s_n}{\psi_n}\right| \mathds{1}_{\Omega_n}\right] +  \bbE\left[|\hat f(\xs)| \mathds{1}_{A_n \cap \Omega_n^c}\right]\notag  \\
        & \le C_1 \bbE\left[\left\|\frac{\hat s_n}{\psi_n}\right\|_2\right] + \int_0^\infty \bbP\left(\left|e_1^\top \left(\frac{\hat S_n}{\psi_n}\right)^{-1}\frac{\hat s_n}{\psi_n}\right| > t, A_n \cap \Omega_n^c\right) \ dt \notag \\
        & \le C_1 \bbE\left[\left\|\frac{\hat s_n}{\psi_n}\right\|_2\right] + t_n \bbP(\Omega_n^c) + \int_{t_n}^{\infty} \bbP\left(\left|e_1^\top \left(\frac{\hat S_n}{\psi_n}\right)^{-1}\frac{\hat s_n}{\psi_n}\right| > t, A_n\right) \ dt \notag \\
        & \le C_1 \bbE\left[\left\|\frac{\hat s_n}{\psi_n}\right\|_2\right]  + t_n \bbP(\Omega_n^c) + \int_{t_n}^{\infty}\bbP\left(\left\|\frac{\hat s_n}{\psi_n}\right\|_2 > \frac{t}{C_n}\right)
    \end{align}

    For the second summand, we use the fact that $\bbP(\Omega_n^c) \le C_1 \exp(-C_2(n\psi_n h^D))$. Therefore, we have: 
$$
t_n\bbP(\Omega_n^c) \le C_1 \exp(\log{(t_n)}-C_2(n\psi_n h^D)) \,.
$$
This term goes to 0 as soon as $t_n = o(e^{(n\psi_n h^D)})$. Furthermore, we also choose $t_n$ in a larger order of magnitude than $C_n$, i.e., $t_n/C_n \uparrow \infty$. When we specify the choice of $t_n$, we will see that these conditions are indeed satisfied. As $t_n/C_n \uparrow \infty$, $t/2C_n$ will be larger than $\|s_n\|_2$ for all large $n$, where, recall that $\|s_n\| = \|\bbE[\hat s_n/\psi_n]\| \le C$ (established in Lemma \ref{lem:exp_conc_sn}). Therefore, for all $t > t_n$, we have: 
$$
\bbP\left(\left\|\frac{\hat s_n}{\psi_n}\right\|_2 > \frac{t}{C_n}\right) \le \bbP\left(\left\|\frac{\hat s_n}{\psi_n} - s_n\right\|_2 > \frac{t}{2C_n}\right) \,.
$$
We now use the exponential concentration of the right hand side as established in Lemma \ref{lem:exp_conc_sn}. This yields: 
\begin{align*}
    \int_{t_n}^{\infty}\bbP\left(\left\|\frac{\hat s_n}{\psi_n} - s_n\right\|_2 > \frac{t}{2C_n}\right) \ dt & \le C_1 \int_{t_n}^{\infty}\exp\left(-(n\psi_nh^D)\frac{(t/2C_n)^2}{c_1  + c_2 (t/2C_n)}\right) \ dt \\
    & = 2C_1C_n\int_{t_n/2C_n}^{\infty}\exp\left(-(n\psi_nh^D)\frac{t^2}{c_1  + c_2 t}\right) \ dt \\
    & = 2C_1C_n\int_{t_n/2C_n}^{\infty}\exp\left(-\frac{(n\psi_nh^D)^2 t^2}{c_1(n\psi_nh^D)  + c_2 (n\psi_nh^D)t}\right) \ dt \\
    & = \frac{2C_1C_n}{n\psi_nh^D}\int_{t_n(n\psi_nh^D)/2C_n}^{\infty}\exp\left(-\frac{t^2}{c_1(n\psi_nh^D)  + c_2 t}\right) \ dt
\end{align*}
As $t_n/C_n \uparrow \infty$, $t_n/2C_n > c_1/c_2$ for all large $n$. This implies, $c_2 t > c_1(n\psi_nh^D)$ for all $t > t_n(n\psi_nh^D)/2C_n$. Hence, 
\begin{align*}
    \int_{t_n}^{\infty}\bbP\left(\left\|\frac{\hat s_n}{\psi_n} - s_n\right\|_2 > \frac{t}{2C_n}\right) \ dt & \le \frac{2C_1C_n}{n\psi_nh^D}\int_{t_n(n\psi_nh^D)/2C_n}^{\infty}\exp\left(-\frac{t}{2c_2}\right) \ dt \\
    & = \frac{4C_1C_nc_2}{n\psi_nh^D} \exp\left(-\frac{t_n(n\psi_nh^D)}{4C_nc_2}\right) \,.
\end{align*}
Therefore, if we choose $C_n = \log{n}$ and $t_n= (\log{n})^2$, then it is immediate that the second and the third summand of Equation \eqref{eq:L1_norm_bound_1} go to 0 as $n \uparrow \infty$. Therefore, we conclude that $\bbE[|\hat f(\xs)|] \le C$ for some constant $C$. 

 As we have assumed $(X, Y)$ is compactly supported (Assumption \ref{}), we define $B = \mathrm{esssup}|Y|$, i.e. $\P(|Y| \le B) = 1$. By definition of $\tau_n$, we have: 
    \begin{align*}
        s_n & = \E\left[\frac{1}{n \psi_n}\sum_{i=1}^n \bz\left(\frac{X_i - \xs}{h}\right)K_{h_n}\left(\frac{X_i - \xs}{h}\right) Y_i\right] \\
        & = \frac{1}{n \psi_n}\sum_{i=1}^n \E\left[\bz\left(\frac{X_i - \xs}{h}\right)K_{h_n}\left(\frac{X_i - \xs}{h}\right) f^\star(X_i)\right] \\
        & = \frac{n_P}{n\psi_n}\bbE_P\left[\bz\left(\frac{X - \xs}{h}\right)K_{h_n}\left(\frac{X - \xs}{h}\right) f^\star(X)\right] + \frac{n_Q}{n\psi_n} \bbE_Q\left[\bz\left(\frac{X - \xs}{h}\right)K_{h_n}\left(\frac{X - \xs}{h}\right) f^\star(X)\right] \\
      & \le C\left(\frac{n_P}{n\psi_n} + \frac{n_Q (\rho_n \vee h)^{d - D}}{n\psi_n}\right) = C \,.
    \end{align*}
Here, the penultimate inequality follows from parts (iv) and (v) of Lemma \ref{lem:techlem1}, and the last equality follows from the definition of $\psi_n$ (Equation \eqref{eq:psin}). For the exponential concentration, the same arguments used in the proof of Lemma \ref{lem:bound_centered_s_n_tilde} work with $f^\star(X_i)$ replaced by $Y_i$, which we skip here for brevity. 

For the second summation, we can further split the integral depending on which term is the minimum among the two terms inside the curly brackets, along with the observation that: 
$$
t_j \delta_{n, i^*}  \sqrt{\gamma_n(h_{n,j})} = C_* \delta_{n, j} \sqrt{\gamma_n(h_{n,j})} \le \frac{c_1}{c_2}  \sqrt{\gamma_n(h_{n,j})} \ \ \forall \ \ \text{large } n \,,
$$
where the last inequality follows from the fact that $\delta_{n, j} \downarrow 0$ as $n \uparrow \infty$. Therefore, 
\begin{align*}
    & \sum_{j = 1}^{i^* - 1}\frac{C}{\delta_{n, i^*}\sqrt{\gamma_{n}(h_{n,j})}}\int_{t_j \delta_{n, i^*}\sqrt{\gamma_{n}(h_{n,j})}}^\infty \exp\left(-\frac12 \min\left\{\frac{t^2}{c_1}, \frac{t\sqrt{\gamma_{n}(h_{n,j})}}{c_2}\right\}\right)  \ dt \\
    & =  \sum_{j = 1}^{i^* - 1}\frac{C}{\delta_{n, i^*}\sqrt{\gamma_{n}(h_{n,j})}}\int_{C\delta_{n, j}\sqrt{\gamma_{n}(h_{n,j})}}^{ \frac{c_1}{c_2}  \sqrt{\gamma_n(h_{n,j})}} \exp\left(-\frac{t^2}{2c_1}\right)  \ dt +  \sum_{j = 1}^{i^* - 1}\frac{C}{\delta_{n, i^*}\sqrt{\gamma_{n}(h_{n,j})}}\int_{ \frac{c_1}{c_2}  \sqrt{\gamma_n(h_{n,j})}}^\infty \exp\left(-\frac{t\sqrt{\gamma_{n}(h_{n,j})}}{2c_2}\right)  \ dt \\
    & \le \sum_{j = 1}^{i^* - 1}\frac{C}{\delta_{n, i^*}\sqrt{\gamma_{n}(h_{n,j})}}\int_{C_*\delta_{n, j}\sqrt{\gamma_{n}(h_{n,j})}}^{ \infty} \exp\left(-\frac{t^2}{2c_1}\right)  \ dt +  \sum_{j = 1}^{i^* - 1}\frac{2Cc_2}{\delta_{n, i^*}\gamma_{n}(h_{n,j})}\int_{ \frac{c_1}{2c_2^2}\gamma_n(h_{n,j})}^\infty \exp\left(-t\right)  \ dt \\
    & \le \sum_{j = 1}^{i^* - 1}\frac{C_1}{\delta_{n, i^*}\sqrt{\gamma_{n}(h_{n,j})}}\exp\left(-\frac{C_*^2 \delta_{n, j}^2\gamma_{n}(h_{n,j})}{2c_1}\right) +  \sum_{j = 1}^{i^* - 1}\frac{2Cc_2}{\delta_{n, i^*}\gamma_{n}(h_{n,j})}\exp\left(-\frac{c_1}{2c_2^2}\gamma_n(h_{n,j})\right) \\
    & \le C_3 \sum_{j = 1}^{i^* - 1} \ \left\{\exp\left(\log{\delta_{n, i*}} + \log{\gamma_n(h_{n,j})} - \frac{C_*^2 \delta_{n, j}^2\gamma_{n}(h_{n,j})}{2c_1}\right) + \exp\left(\log{\delta_{n, i*}} + \log{\gamma_n(h_{n,j})} - \frac{c_1}{2c_2^2}\gamma_n(h_{n,j})\right)\right\}
\end{align*}
As noted in Theorem \ref{lem:rate_discrepancy_Lepski}, $\delta_{n, j}^2 \gamma_n(h_{n,j}) \gtrsim \log{n}$. As $\log{\delta_{n, i}} \lesssim \log{n}$ and $\log{\gamma_n(h_{n,j})} \lesssim \log{n}$, it is evident that by choosing $C_*$ a large enough constant, it is possible to make, 
$$
\exp\left(\log{\delta_{n, i*}} + \log{\gamma_n(h_{n,j})} - \frac{C_*^2 \delta_{n, j}^2\gamma_{n}(h_{n,j})}{2c_1}\right) \le n^{-C_{*, 1}} \ \ \forall \ \ 1 \le j < i^* \,.
$$
for some constant $C_{*, 1} > 0$. Therefore, 
$$
\sum_{j = 1}^{i^* - 1} \exp\left(\log{\delta_{n, i*}} + \log{\gamma_n(h_{n,j})} - \frac{C_*^2 \delta_{n, j}^2\gamma_{n}(h_{n,j})}{2c_1}\right) \le (\log{n})\  n^{-C_{*, 1}} \longrightarrow 0 \,.
$$
The other part is even easier as $\gamma_{n}(h_{n,j})$ grows polynomially in $n$, which implies: 
\begin{align*}
& \sum_{j = 1}^{i^* - 1}\exp\left(\log{\delta_{n, i*}} + \log{\gamma_n(h_{n,j})} - \frac{c_1}{2c_2^2}\gamma_n(h_{n,j})\right)  \\
& \le \log{n} \ \exp\left(\log{\delta_{n, i*}} + \max_{1 \le j \le i^*}\left\{\log{\gamma_n(h_{j})} - \frac{c_1}{2c_2^2}\gamma_n(h_{n,j})\right\}\right)
\overset{n \uparrow \infty}{\longrightarrow} 0 \,.
\end{align*}
Therefore, we conclude that $\Upsilon_1 \to 0$ as $n \uparrow \infty$. \DM{Need to write $\Upsilon_2$}.

%We study pointwise estimation in nonparametric regression under covariate shift, where large amount of labeled data from a source distribution is supplemented with limited labeled samples from an intrinsically low-dimensional target distribution. In contrast to prior work, we allow the regression function to belong to a general H\"{o}lder class of arbitrary smoothness and assume that the target distribution is supported near a smooth manifold rather than exactly on it. Allowing general smoothness helps mitigate the curse of dimensionality by enabling faster convergence when the target function is highly regular, while approximate manifolds provide a more realistic model of structured but noisy data. We identify a phase transition in the minimax estimation rates as a function of the distance of the target domain from the underlying manifold, the source and target sample sizes, the smoothness of the regression function, the ambient and the intrinsic dimensions. We propose a local polynomial estimator that achieves the minimax optimal rate in both the exact and approximate manifold regimes on either side of the phase transition boundary. Furthermore, we develop a data-driven procedure that adapts to unknown smoothness and unknown intrinsic dimension, and prove that the resulting estimator attains nearly optimal rates. Our results unify and extend several strands of the literature on covariate shift, manifold learning, and adaptive nonparametric inference. \DM{Density ratio based trick.}

