Next, we present a standard smoothness assumption on $f^\star$: 

\begin{assn}[Local H\"{o}lder continuity of $f^\star$]\label{asn:regf}
    The function $f^\star\in \Sigma(\beta,L)$, $\beta>0$, $L>0$,  the class of locally $\beta$-H\"{o}lder functions, i.e., there exists a neighborhood $U$ around $\xs$ such that    
    \[
\sup_{\mathbf{x} \in U} \max_{|\mathbf{t}|<\lfloor \beta \rfloor} |D^{\mathbf{t}} f^\star(x)| + \sup_{\mathbf{x} \in U} \max_{|\mathbf{t}| = \lfloor \beta \rfloor} \frac{\left| D^\mathbf{t} f^\star(x) - D^\mathbf{t} f^\star(\xs) \right|}{\|x- \xs\|^{\beta - \lfloor \beta \rfloor}} \leq L,
\]  
where \( \mathbf{t} = (t_1, \dots, t_d) \) is a multi-index with \( |\mathbf{t}| = \sum_{i=1}^d t_i \), and \( D^\mathbf{t} f^\star \) denotes the partial derivative of \( f^\star \) of order \( |\mathbf{t}| \) given by \(
D^\mathbf{t} f^\star = \frac{\partial^{|\mathbf{t}|} f^\star}{\partial x_1^{t_1} \cdots \partial x_d^{t_d}}.  
\) 
\end{assn}

Next up, we present our assumptions on the distribution of the source samples. 
\begin{assn}[On source distribution]\label{asn:source}
\begin{enumerate}
   \item $P_X$ is supported on $[-2,2]^D$. Further $P_X$ admits a Lebesgue density $p$ and there exists a neighborhood $U'$ of $\xs$ such that $p$ is strictly positive and uniformly Lipschitz continuous on $U'$.

   \item The conditional fourth moment, $x\mapsto \bbE_P[(Y-f^\star(X))^4|X=x]$ is bounded for $x\in U'$.
\end{enumerate}
\end{assn}
 The first part of \cref{asn:source} imposes some basic regularity assumptions on the distribution $P_X$. This regularity ensures that $P_X$ puts enough mass around $\xs$ so that the source samples carry meaningful information about $f^\star(\xs)$. As a result of this assumption, a large source sample size $n_P$ will lead to fast rates of convergence when the target sample size $n_Q$ is small. 
 \\\\
 \noindent 
 The first part of \cref{asn:lowman} is a natural model for generating data from an approximate manifold (see \cref{def:appmanif}). The second part of \cref{asn:lowman} imposes some basic regularity on the distribution $Q_X$, similar to \cref{asn:source}(1). Note that when $\rho_n=0$, $Q_X$ need not have a density. When $\rho_n>0$, $Q_X$ will have an unbounded density as $\rho_n\to 0$. An important distinction from the assumption on the source distribution (see \cref{asn:source}) is that the regularity assumptions in \cref{asn:lowman}(2) are global instead of local around $\xs$. This is because according to pir data generating model, the mass of $Q_X$ around $\xs$ depends on the global behavior of both $q$ and $g$. Finally, the third part of \cref{asn:lowman} is a natural moment restriction on $Q_{Y|X}$ locally around $\xs$.
 \\\\
 \noindent
 The second part of \cref{asn:source} imposes some basic moment assumptions on the conditional distribution $P_{Y|X}$ locally around $\xs$.

 \noindent Finally, we state our assumptions on the target data. To wit,  we follow the approximate manifold assumption from \cite{jiao2023deep,bickel2007local}; also see \cite{fefferman2016testing,carlsson2009topology,lee2006riemannian,meilua2024manifold,narayanan2010sample}.
\begin{defn}[Approximate manifold]\label{def:appmanif}
Given a continuously differentiable function $\phi:[-1,1]^d\to [-1,1]^D$, a $\rho$-approximate submanifold $\mathcal{M}_{\rho}$ is defined as: 
$$\mathcal{M}_{\rho}:=\{x\in [-1,1]^D: \, \inf_{z\in [-1,1]^d}\,\lVert x-\phi(z)\rVert\le \rho\}.$$
\end{defn}

\begin{assn}[On target distribution]\label{asn:lowman}
\begin{enumerate}
    \item The target data is supported on an approximate manifold $\mathcal{M}_{\rho_n}$ for some $\rho_n\to 0$. It is generated according to the following model: 
    $$X_i=\phi(V_i)+\rho_n U_i, \quad 1\le i\le n_Q,$$
    where $\phi:[-1,1]^d\to [-1,1]^D$ is continuously differentiable and 
    $$c^{-1}\le \lmn(\nabla \phi(z)^{\top}\nabla \phi(z)) \le \lmx(\nabla \phi(z)^{\top}\nabla \phi(z)) \le c$$ for some $c\in (0,\infty)$.

    \item $V_1,\ldots ,V_{n_Q}\overset{i.i.d.}{\sim} q$ (supported on $[-1,1]^d$) and $U_1,\ldots ,U_{n_Q}\overset{i.i.d.}{\sim} g$ (supported on $[-1,1]^D$) are independent. Here $q(\cdot)$ and $g(\cdot)$ are probability density functions which are unformly lower bounded and Lipschitz continuous.

    \item The map $x\mapsto \bbE_Q[(Y-f^\star(X))^4|X=x]$ is locally bounded around $\xs$.
\end{enumerate}
\end{assn}
The first part of \cref{asn:lowman} is a natural model for generating data from an approximate manifold (see \cref{def:appmanif}). The second part of \cref{asn:lowman} imposes some basic regularity on the distribution $Q_X$, similar to \cref{asn:source} (1). Note that when $\rho_n=0$, $Q_X$ need not have a density. When $\rho_n>0$, $Q_X$ will have an unbounded density as $\rho_n\to 0$. An important distinction from the assumption on the source distribution (see \cref{asn:source}) is that the regularity assumptions in \cref{asn:lowman} (2) are global instead of local around $\xs$. This is because according to our data generating model, the mass of $Q_X$ around $\xs$ depends on the global behavior of both $q$ and $g$. Finally, the third part of \cref{asn:lowman} is a natural moment restriction on $Q_{Y|X}$ locally around $\xs$.

