\section{Proofs}\label{sec:proof-theor-eqrefthm}

In this section, we provide the proofs of our main results, which is strucured
as follows: In Section~\ref{sec:mild-solut-gener}, we present the proof of
Proposition~\ref{prop:existence-mild-Riccati}, which establishes the existence
and convergence of the spectral Galerkin approximation. In
Section~\ref{sec:finite-rank-convergence}, we then prove
Proposition~\ref{prop:embedding-affine-main}, concerning the existence of affine
finite-rank operator-valued processes, and Theorem~\ref{thm:main-convergence},
which demonstrates the convergence of the finite-rank affine process to the
class of irregular affine processes, with values in the cone of positive
self-adjoint trace-class operators. In Section~\ref{sec:proof-section-2}, we
provide the proofs related to the joint model. Specifically, we prove
Theorem~\ref{thm:heat-affine-model}, which establishes the existence of affine
heat-modulated stochastic covariance models for forward curve dynamics, and
Theorem~\ref{thm:finite-dim-approx-ScoV}, which concerns the finite-rank
approximation of such models.

\subsection{Galerkin approximation of the generalized mild Riccati
  equations}\label{sec:mild-solut-gener}

Let $(b,\mathbf{B},m,\mu)$ be an admissible parameter set as in
Definition~\ref{def:admissible-irregular}. Recall the operator $L$ from
\cref{eq:Lyapunov} and the function $\hat{R}\colon\cHplus\to \cH$
from~\eqref{eq:R-hat}. We denote the right-hand side function of the mild
generalized Riccati equations~\eqref{eq:Riccati-psi-mild} by $R$, i.e. we define
it as
\begin{align*}
  R(u)\df L(u)+\hat{R}(u),\quad u\in\dom(L).
\end{align*}
We interpret~\eqref{eq:Riccati-psi-mild} as semi-linear differential equation on
$\cHplus$, with unbounded linear operator $L$ and non-linear continuous
pertubation $\hat{R}$. Note that $\hat{R}$ is even locally Lipschitz continuous,
see~\cite[Remark 3.4]{CKK22a}. In the following lemma, we show that the
semigroup $(\mathcal{T}(t))_{t\geq 0}$, generated by $(L,\dom(L))$, is a
semigroup of \emph{positive operators} on $\cH$ with respect to the cone
$\cHplus$: 
\begin{lemma}\label{lem:prop-semigroup}
  The operator-semigroup $(\mathcal{T}(t))_{t\geq 0}$ is self-adjoint, strongly
  continuous and satisfies $\mathcal{T}(t)(\cHplus)\subseteq \cHplus$ for all
  $t\geq 0$.
\end{lemma}
\begin{proof}
  It follows from~\cref{item:linear-operator-unbounded} that $L$ is
  the generator of a strongly continuous and self-adjoint semigroup
  $(\mathcal{T}(t))_{t\geq 0}$ on $\cH$. From \cite[Theorem
  2.1]{Ros91} it follows that the abstract Cauchy-problem 
  \begin{align*}
    \begin{cases}
      \frac{\partial }{\partial t} \psi_{u}(t)=L\psi_{u}(t)\quad\text{for } t>0,\\
      \psi_{u}(0)=u\in\cHplus,
    \end{cases}
  \end{align*}
  has a unique solution for eqvery $u\in\cHplus$ which is given by
  $\psi_{u}(t)=\mathcal{T}(t)u$ and is such that $\psi_{u}(t)\in\cHplus$ for all
  $t\geq 0$. Since this holds for every $u\in\cHplus$ we see that the semigroup
  $(\mathcal{T}(t))_{t\geq 0}$ satisfies
  $\mathcal{T}(t)(\cHplus)\subseteq \cHplus$ for all $t\geq 0$.
\end{proof}

As before, let $(e_{i})_{i\in\MN}$ be the orthonormal basis of $H$ consisting of
the eigenvectors of $B$ and for every $d\in\MN$, denote by $H_{d}$ the
$d$-dimensional subspace of $H$ spanned by the first $d$ basis vectors,
i.e. $H_{d}\df \lin\set{e_{i}\colon i=1,\ldots,d}$ and let
$\cH_{d}\df \lin\set{\be_{i,j}\colon\, 1\leq i\leq j\leq d\,}$.  To prove the
existence and convergence of the $d^{th}$-Galerkin approximations
$\phi_{d}(\cdot,\bP_{d}(u))$ and $\psi_{d}(\cdot,\bP_{d}(u))$, we collect some
important properties of the operators $L$ and $B$, and the function $\hat{R}$ in
the following lemma:

\begin{lemma}\label{lem:irregular-properties}
  For every $d\in\MN$ the following holds: 
  \begin{lemenum}
  \item $\cH_{d}\subseteq \dom(\mathbf{B}^{*})$ for all $d\in\MN$.
  \item $B\rvert_{H_{d}}$ is a bounded operator.
  \end{lemenum} 
\end{lemma}
\begin{proof}
  By \cref{item:linear-operator-unbounded} the operator $\mathbf{B}$ is linear
  and densely defined, i.e. $\dom(\mathbf{B})\subseteq \cH$ is dense. The set
  $(\be_{i})_{i\in\MN}$ denotes the complete orthonormal basis of eigenvectors of
   $L$ in $\cH$, thus $\cH_{d}\subseteq \dom(L^{*})=\dom(L)$ and hence
   also $\cH_{d}\subseteq \dom(\mathbf{B}^{*})$.

   The restriction of operator $B$ on the finite-dimensional subspace $H_{d}$,
   i.e. $B\rvert_{H_{d}}$, is bounded
   as $H_{d}=\lin\set{e_{i}\colon i=1,\ldots,d}$ for
   $\set{e_{i}\colon i=1,\ldots,d}$ the set of eigenvectors of $B$ and hence
   $\mathrm{ran}(B\rvert_{H_{d}})\subseteq H_{d}$.
 \end{proof}

To ensure that the solution $\psi(t, u)$ remains within the cone $\cHplus$ for
all $t\geq 0$ and $u\in\cHplus$, we introduce the concept of
\emph{quasi-monotonicity}: 

\begin{lemma}\label{lem:quasi-cont}
   For any $k \in \mathbb{N}$, we define $\dmuk \coloneqq \one_{\{\|\xi\| > 1/k\}} \, \dmu$ and, for each $u \in \dom(L)$, we define the map
   \begin{align*}
     \hat{R}^{(k)}(u) \coloneqq \Gamma^{*}(u) - \int_{\cHpluso} \left( \E^{-\langle \xi, u \rangle} - 1 + \langle \chi(\xi), u \rangle \right) \frac{\dmuk}{\|\xi\|^2}.  
   \end{align*}
   Then, for every $k \in \mathbb{N}$, the map $\hat{R}^{(k)}$ is Lipschitz
   continuous and quasi-monotone with respect to $\cHplus$. That is, for all
   $v_1, v_2 \in \cH$ satisfying $v_1 \leq_{\cHplus} v_2$ and $u \in \cHplus$
   such that $ \langle v_2 - v_1, u \rangle = 0$, we have
   \begin{align*}
   \langle \hat{R}^{(k)}(v_2) - \hat{R}^{(k)}(v_1), u \rangle \geq 0.  
   \end{align*}
\end{lemma}
\begin{proof}
   The Lipschitz continuity of $\hat{R}^{(k)}$ on $\cHplus$ follows from
   \cite[Lemma 3.3]{CKK22a}, and the quasi-monotonicity is established by
   \cite[Lemma 3.2]{CKK22a}. 
\end{proof}

With these two lemmas in hand, we can now proceed to prove
Proposition~\ref{prop:existence-mild-Riccati}.

\begin{proof}[Proof of Proposition~\ref{prop:existence-mild-Riccati}]
  Let $d \in \mathbb{N}$, $T > 0$, and $u \in \cHplus$. The uniqueness of the
  solutions $\phi(\cdot, u)$ and $\psi(\cdot, u)$ to equations
  \eqref{eq:Riccati-phi-mild} and \eqref{eq:Riccati-psi-mild}, as well as the
  solutions $\phi_{d}(\cdot,\mathbf{P}_{d}(u))$ and
  $\psi_{d}(\cdot,\mathbf{P}_{d}(u)$ to equations
  \eqref{eq:mild-Riccati-Galerkin-phi} and \eqref{eq:mild-Riccati-Galerkin-psi},
  follows from the fact that the mappings $F$, $\hat{R}$, $F_{d}$, and
  $\hat{R}_{d}$ are Lipschitz continuous on bounded sets.

  Additionally, note that due to the continuity of $F$ and $F^{d}$, given
  solutions $\psi(\cdot, u)$ and $\psi_{d}(\cdot, \mathbf{P}_{d}(u))$ of
  \eqref{eq:Riccati-psi-mild} and \eqref{eq:mild-Riccati-Galerkin-psi},
  respectively, we can define:
   \begin{align*}
      \phi(t, u) = \int_0^t F(\psi(s, u)) \, \D s, \quad t \geq 0,
   \end{align*}
   and
   \begin{align*}
      \phi_{d}(t, \mathbf{P}_{d}(u)) = \int_0^t F^{d}(\psi^{d}(s, \mathbf{P}_{d}(u))) \, \D s, \quad t \geq 0,
   \end{align*}
   which are the unique continuously differentiable solutions to
   \eqref{eq:Riccati-phi-mild} and \eqref{eq:mild-Riccati-Galerkin-phi},
   respectively. Therefore, it remains to show the existence of a solution to
   equations \eqref{eq:Riccati-psi-mild} and
   \eqref{eq:mild-Riccati-Galerkin-psi}.

   By Lemma~\ref{lem:irregular-properties}, the operator $B\rvert_{H_d}$ is
   bounded. Consequently, the existence of a solution to the Galerkin
   approximation follows directly from the corresponding result in the regular
   affine case, as established in \cite[Proposition
   3.1]{karbach2023finiterank}.\par{} 

   It remains to prove the existence of a mild solution $\psi(\cdot,u)$ to the
   semi-linear equation~\eqref{eq:Riccati-psi-mild} on $[0,T]$ with the initial
   condition $\psi(0,u)=u\in\cHplus$, satisfying the variation-of-constants
   formula~\eqref{eq:mild-solution-variation}.

   First, by Lemma~\ref{lem:prop-semigroup}, the operator semigroup
   $(\cT(t))_{t \geq 0}$ is strongly continuous with generator $(L, \dom(L))$,
   and satisfies $\cT(t)(\cHplus)\subseteq \cHplus$ for all $t \geq
   0$. Moreover, by Lemma~\ref{lem:irregular-properties}, the function
   $\hat{R}^{(k)}$ is locally Lipschitz continuous on $\cHplus$ and
   quasi-monotone with respect to $\cHplus$. The quasi-monotonicity of
   $\hat{R}^{(k)}$ is equivalent to the condition
   $\lim_{h \to 0+} \inf_{y \in \cHplus} \frac{\norm{x+h\hat{R}^{(k)}(x)-y}}{h}
   = 0$, as shown in \cite[Lemma 4.1 \& Example 4.1]{Dei77}. Therefore, we can
   apply the results of \cite[Chapter 8, Theorem 2.1 \& Remark 2.1]{Mar76},
   which ensures the existence of a $T_1 > 0$ and a mapping
   $\psi^{(k)}(\cdot,u) \colon [0,T_1) \to \cHplus$, which is the unique local
   solution to equation~\eqref{eq:Riccati-psi-mild} satisfying 
   \begin{align}\label{eq:variation-of-constant-k}
  \psi^{(k)}(t,u)=\cT(t)u+\int_{0}^{t}\cT(t-s)\hat{R}^{(k)}(\psi^{(k)}(s,u))\,\D
  s,\quad t\in [0,T_{1}).   
   \end{align}

   Next, we show that this unique local solution $\psi^{(k)}(\cdot,u)$ can be
   extended to $[0,T]$ for any $T > T_1$. To do this, note that the map
   $u \mapsto \hat{R}^{(k)}(u)$ maps bounded sets of $\cHplus$ to bounded sets
   of $\cH$. By \cite[Chapter 8, Theorem 2.1]{Mar76}, it suffices to show that
   $\norm{\psi^{(k)}(t,u)} < \infty$ for every $t \in [0,T_1)$. This implies
   that the solution $\psi^{(k)}(\cdot,u)$ on $[0,T_1)$ can be extended to $[0,T]$,
   thus proving that $\psi^{(k)}(\cdot,u)$ exists on the entire interval
   $[0,T]$, as desired.

   We now check that $\norm{\psi^{(k)}(t,u)}<\infty$ for every $t\in[0,T_{1})$
   holds. Note first that by part i) of Lemma~\ref{lem:irregular-properties}, it
   holds $\be_{i,j}\in\dom(L)$ for every $i\in\MN$. Moreover, on $[0,T_{1})$ we
   have      
  \begin{align*}
    \langle \frac{\partial}{\partial t} \psi^{(k)}(t,u), \be_{i,j}\rangle&=\langle
                                                                \psi^{(k)}(t,u),L(\be_{i,j})\rangle+\langle
                                                                 \hat{R}^{(k)}(\psi^{(k)}(t,u)),\be_{i,j}\rangle\\
    &=-\lambda_{i,j}\langle \psi^{(k)}(t,u),\be_{i,j}\rangle+\langle
      \hat{R}^{(k)}(\psi^{(k)}(t,u)),\be_{i,j}\rangle.   
  \end{align*}
  Thus, we obtain
  \begin{align*}
    \frac{\partial}{\partial t}\langle \psi^{(k)}(t,u), \be_{i,j}\rangle^{2}&=2\langle
                                                                   \psi^{(k)}(t,u), \be_{i,j}\rangle \langle \frac{\partial}{\partial t}\psi^{(k)}(t,u),\be_{i,j}\rangle \\
                                                                            &=-2\lambda_{i,j}\langle \psi^{(k)}(t,u), \be_{i,j}\rangle^{2}\\
   &\quad + 2\langle \psi^{(k)}(t,u),
      \be_{i,j}\rangle \langle \hat{R}^{(k)}(\psi^{(k)}(t,u)),\be_{i,j}\rangle,
  \end{align*}
  and hence by the variation-of-constant formula we see that
  \begin{align*}
    \langle \psi^{(k)}(t,u), \be_{i,j}\rangle^{2}&=\E^{-2\lambda_{i}t}\langle u,
                                                   \be_{i,j}\rangle^{2}\\
    &\quad+2\int_{0}^{t}\E^{-2\lambda_{i,j}(t-s)}\langle \psi^{(k)}(t,u),
      \be_{i,j}\rangle \langle \hat{R}^{(k)}(\psi^{(k)}(t,u)),\be_{i,j}\rangle \D s. 
  \end{align*}
Given that 
\begin{align*}
\norm{\psi^{(k)}(t,u)}^{2} = \sum_{i,j\in\mathbb{N}, i \leq j} \langle \psi^{(k)}(t,u), \be_{i,j} \rangle^{2}  
\end{align*}
and
\begin{align*}
\langle \psi^{(k)}(t,u), \hat{R}^{(k)}(\psi^{(k)}(t,u)) \rangle = \sum_{i,j\in\mathbb{N}, i \leq j} \langle \psi^{(k)}(t,u), \be_{i,j} \rangle \langle \hat{R}^{(k)}(\psi^{(k)}(t,u)), \be_{i,j} \rangle,  
\end{align*}
it follows from the estimate $\norm{\hat{R}^{(k)}(u)} \leq K \norm{u}$ (see
\cite[Lemma 3.3]{CKK22a}) that: 
\begin{align*}
\norm{\psi^{(k)}(t,u)}^{2} \leq \norm{u}^{2} + M \int_0^t \norm{\psi^{(k)}(s,u)}^{2} \, \D s,  
\end{align*}
for some constant $M > 0$. Thus, by applying Gronwall's inequality, we conclude that for all $t \in [0, T_1)$:
\begin{align*}
  \norm{\psi^{(k)}(t,u)}^{2} \leq \norm{u}^{2} + M \norm{u}^{2} \int_0^t
  \E^{M(t-s)} \, \D s < \infty.   
\end{align*}

Therefore, $\norm{\psi^{(k)}(t,u)} < \infty$ for every $t \in [0,T_1)$. Hence,
following \cite[Chapter 8, Proposition 4.1]{Mar76}, we conclude that there
exists a unique solution $\psi^{(k)}(\cdot,u)$ to
equation~\eqref{eq:Riccati-psi-mild} on the entire interval $[0,T]$ given
by~\eqref{eq:variation-of-constant-k}.

It follows by the same reasoning as in \cite[Proposition 3.7]{CKK22a} that
$\psi^{(k+1)}(t,u)\leq_{\cHplus} \psi^{(k)}(t,u)$ for all $t\in [0,T]$ and
$u\in\cHplus$ and by the regularity of the cone $\cHplus$, we conclude that
for every $t\in [0,T]$ and $u\in\cHplus$ there exists $\psi(t,u)$ defined as
$\psi(t,u)= \lim_{k\rightarrow \infty} \psi^{(k)}(t,u)$. By the same
reasoning as in~\cite[Lemma
3.6]{CKK22a}, we see that $\hat{R}^{(k)}$ converges to $\hat{R}$ uniformly on
bounded sets. Thus by the monotonicity of the sequence $ \psi^{(k)}(t,u)$ in
$k\in\MN$ and by inserting formula~\eqref{eq:variation-of-constant-k}, we obtain
  \begin{equation*}
  \begin{aligned}
   \psi(t,u) &= \lim_{k\rightarrow \infty} \psi^{(k)}(t,u)
   \\ 
   & = \cT(t)u+\lim_{k\rightarrow
     \infty}\int_{0}^{t}\cT(t-s)\hat{R}^{(k)}(\psi^{(k)}(s,u))\,\D s  
   \\   
   & = \cT(t)u + \lim_{k\rightarrow \infty} \int_{0}^{t} \cT(t-s)\left( R^{(k)}(\psi^{(k)}(s,u)) - R(\psi^{(k)}(s,u))\right)\D s
   \\ &
   \quad + \lim_{k\rightarrow \infty} \int_{0}^{t} \cT(t-s)R(\psi^{(k)}(s,u))\D s
   \\
   & = \cT(t)u + \int_{0}^{t} \cT(t-s)R(\psi(s,u))\D s.
   \end{aligned}
  \end{equation*}
  This proves the existence of a unique solution $\psi(\cdot,u)\in
  C([0,T],\cHplus)$ to equation~\eqref{eq:Riccati-psi-mild}
  satisfying the variation-of-constants
  formula~\eqref{eq:mild-solution-variation}.\par{} 


  Lastly, we prove the convergence rate
  in~\eqref{eq:convergence-mild-Galerkin}. First, note that the semigroup
  $(\cT(t))_{t \geq 0}$ commutes with the projection $\bP_d$ for every $d \in
  \mathbb{N}$. By setting $M_T = \sup_{t \in [0,T]} \norm{\cT(t)}_{\cL(\cH)}$,
  we have the following estimate: 
  \begin{align*}
    \norm{\psi(t,u)-\psi_{d}(t,\bP_{d}(u))}&\leq\norm{\cT_{t}\bP_{d}^{\perp}(u)}+\norm{\int_{0}^{t}\cT_{t-s}\big(\hat{R}(\psi(s,u))-\hat{R}_{d}(\psi_{d}(s,u))\big)\,\D
                                                     s}\\
                                                   &\leq
                                                     M_{T}\Big(\norm{\bP_{d}^{\perp}(u)}+\int_{0}^{t}\norm{\hat{R}(\psi(s,u))-\bP_{d}(\hat{R}(\psi(s,u)))}\,\D
                                                     s\Big)\\
                                                   &\leq M_{T}\Big(\norm{\bP_{d}^{\perp}(u)}+\int_{0}^{t}\norm{\hat{R}(\psi(s,u))-\bP_{d}(\hat{R}(\psi(s,u)))}\,\D
                                                     s\\
    &\quad +\int_{0}^{t}\norm{\bP_{d}(\hat{R}(\psi(s,u)))-\hat{R}_{d}(\psi_{d}(s,\bP_{d}(u)))}\,\D
      s\Big).
  \end{align*}
  Now, let $M>0$ be such that $\norm{\psi_{d}(t,\bP_{d}(u))}\leq M$ and
  $\norm{\psi(t,u)}\leq M$ for all $d\in\MN$ and $t\in [0,T]$ then by the local
  Lipschitz property of $\hat{R}$, we find a constant $K_{M}>0$ such that 
  \begin{align*}
   \norm{\bP_{d}(\hat{R}(\psi(s,u)))-\hat{R}_{d}(\psi_{d}(s,\bP_{d}(u)))}\leq
    K_{M}\norm{\psi(s,u)-\psi_{d}(s,\bP_{d}(u))}, 
  \end{align*}
  and thus by setting
  \begin{align*}
   K^{d}_{t}=M_{T}\Big(\norm{\bP_{d}^{\perp}(u)}+\int_{0}^{t}\norm{\hat{R}(\psi(s,u))-\bP_{d}\hat{R}(\psi(s,u))}\,\D
    s\Big), 
  \end{align*}
  we obtain
  \begin{align*}
    \norm{\psi(t,u)-\psi_{d}(t,\bP_{d}(u))}\leq K_{t}^{d}+M_{T}K_{M}\int_{0}^{t}\norm{\psi(s,u)-\psi_{d}(s,\bP_{d}(u))}\,\D
    s.
  \end{align*}

  Again, by an application of Gronwall's inequality, we find that
  \begin{align}\label{eq:Riccati-convergence-3}
    \norm{\psi(\cdot,u)-\psi_{d}(\cdot,\bP_{d}(u))}\leq K_{t}^{d}\E^{M_{T} K_{M} t}. 
  \end{align}
  Hence taking the supremum over all $t\in [0,T]$ on both sides
  of~\eqref{eq:Riccati-convergence-3} yields
  \begin{align*}
    \sup_{t\in [0,T]}\norm{\psi(t,u)-\psi_{d}(t,\bP_{d}(u))}\leq
    K_{T}^{d}\E^{M_{T} K_{M} T}.  
  \end{align*}

  Similarly, to the proof~\cite[Proposition3.1]{karbach2023finiterank} we can
  then also bound the Galerkin approximation error of the first
  equation~\eqref{eq:Riccati-phi-mild} as 
  \begin{align*}
    \sup_{t\in [0,T]}|\phi(t,u)-\phi_{d}(t,\bP_{d}(u))|&\leq K_{2,M}K_{T}^{d}\E^{M_{T} K_{M} T },
                                       \quad t\in [0,T], u\in\cHplus
  \end{align*}
  which then yields~\eqref{eq:convergence-mild-Galerkin} for suitable constant
  $K$.\par{}
\end{proof}


\subsection{Affine Finite-Rank Approximations and Their Weak Convergence}
\label{sec:finite-rank-convergence}

In this section, we provide the proofs for
Proposition~\ref{prop:embedding-affine-main} and
Theorem~\ref{thm:main-convergence}. We build on the finite-rank approximation
framework for \emph{regular affine processes} introduced in
\cite{karbach2023finiterank}, making the necessary adjustments to handle the
\emph{irregular case}.


\subsubsection{Finite-Rank Admissble Parameters}
First, we introduce finite-rank approximations for the irregular admissible
parameter set $(b, \mathbf{B}, m, \mu)$. Then, we demonstrate that a finite-rank
affine process can be associated with this approximate parameter set.

We use the following notation: for any two measurable spaces $(\cE_1, \cB_1)$
and $(\cE_2, \cB_2)$, and a measurable function $f: (\cE_1, \cB_1) \to (\cE_2,
\cB_2)$, we denote the push-forward of a measure $\mu_1: \cE_1 \to [0, \infty]$
with respect to $f$ as $f_* \mu_1$. Specifically, we have $f_*\mu_1(A) =
\mu_1(f^{-1}(A))$ for any $A \in \cB_2$. Note that $f_*\mu_1$ is a proper
measure on $(\cE_2, \cB_2)$. For every $d \in \mathbb{N}$, we define the Borel sets
$$E_d \coloneqq \{\xi \in \cHplus \mid 0 < \|\bP_d(\xi)\| \leq 1, \|\xi\| > 1\},$$
and $E_d^0 \coloneqq \cHplus \cap \{\xi \mid \bP_d(\xi) \neq 0\}$. Note that
$E_d \subseteq E_d^0 \subseteq \cHpluso$ for every $d \in \mathbb{N}$. For any
(vector-valued) measure $\lambda$ on $\cB(\cHpluso)$, the Borel $\sigma$-algebra
on $\cHpluso$, we denote the restriction of $\lambda$ to the trace of the Borel
$\sigma$-algebra generated by the open sets in $E_d^0$ as
$\lambda\vert_{E_d^0}$. We now introduce the following notion, which differs from the corresponding definition in~\cite[Definition
5.1]{karbach2023finiterank} only in the part iv):

\begin{definition}\label{def:admissible-Galerkin}
  For every $d\in\MN$, and admissible parameter set $(b, \mathbf{B}, m, \mu)$ we
  define the parameters $(b_{d},B_{d},m_{d},\mu_{d})$ and $M_{d}$ as follows:
  \begin{defenum}
  \item\label{item:md} The measure $m_{d}\colon \cB(\cHplus_{d}\setminus\set{0})\to
    [0,\infty]$ is defined as the push-forward of $m\vert_{E_{d}^{0}}$ with
    respect to $\bP_{d}$, i.e.
    \begin{align*}
      m_{d}(\D\xi)\df (\bP_{d\,*}m\vert_{E_{d}^{0}})(\D\xi). 
    \end{align*}
  \item The vector \label{item:bd} $b_{d}\in \cH_{d}$ is given by
    \begin{align}\label{eq:bd}
      b_{d}\df \bP_{d}(b)+\int_{\bP_{d}(E_{d})}\xi\,m_{d}(\D\xi). 
    \end{align}
  \item\label{item:mud} The $\cHplus_{d}$-valued measure $\mu_{d}\colon
    \cB(\cHplus_{d}\setminus\set{0})\to \cHplus_{d}$ is defined as the
    $\bP_{d}$-projection of the push-forward of $\mu\vert_{E_{d}^{0}}$ with respect to
    $\bP_{d}$, i.e.
    \begin{align*}
      \mu_{d}(\D\xi)\df \bP_{d}(\bP_{d\,*}\mu\vert_{E_{d}^{0}})(\D\xi).
    \end{align*}
    Moreover, we define the $\cHplus_{d}$-valued measure $M_{d}$ on
    $\cHplus_{d}\setminus\set{0}$ as follows: For every
    $A\in\cB(\cHplus_{d}\setminus\set{0})$ we set
    \begin{align}\label{eq:Md} 
      M_{d}(A)\df
      \int_{E_{d}^{0}}\one_{A}(\bP_{d}(\xi))\frac{1}{\norm{\xi}^{2}}\bP_{d}(\mu\vert_{E_{d}^{0}}(\D\xi)).
    \end{align}
\item[iv)] $\mathbf{B}_{d}\colon \cHplus_{d}\to\cH_{d}$ is given by
    \begin{align}\label{eq:Bd-irregular}
      \quad\mathbf{B}_{d}(u\sP_{d})&\df
      \bP_{d}(\mathbf{B}(u\sP_{d}))+\int_{\bP_{d}(E_{d})}\langle
                                \xi,u\sP_{d}\rangle M_{d}(\D\xi)\nonumber\\
                              &=B u\sP_{d}+u\sP_{d}B^{*}+\Gamma_{d}(u\sP_{d})+\int_{\bP_{d}(E_{d})}\langle
                                \xi,u\sP_{d}\rangle M_{d}(\D\xi),
    \end{align} 
    where $\Gamma_{d}\colon \cHplus_{d}\to\cH_{d}$ is given by
    \begin{align}\label{eq:kGamma-d}
     \Gamma_{d}(u\sP_{d})\df\bP_{d}(\Gamma^{*}(u\sP_{d})). 
    \end{align}
  \end{defenum}
\end{definition}

The idea behind the approximate parameter set is that we can use the parameters
$b_d$, $m_d$, $M_d$, and $\mathbf{B}_d$ to express the functions $F_d$ and
$\hat{R}_d$ as follows: 
\begin{align}
   F_d(u) &= \langle b_d, u \rangle - \int_{\cHplus_d \setminus \{0\}} \left( \E^{-\langle \xi, u \rangle} - 1 + \langle \chi(\xi), u \rangle \right) m_d(\D \xi), \label{eq:F-Galerkin}
\end{align}
and $\hat{R}_d$ for every $u_d \in \cHplus_d$ can be expressed as
\begin{align*}
   \hat{R}_d(u_d) &\coloneqq \bP_d(\Gamma^{*}(u_d)) - \int_{\cHpluso} \left( \E^{-\langle \xi, u_d \rangle} - 1 + \langle \chi(\xi), u_d \rangle \right) \bP_d(M(\D \xi)) \\
                  &= \Gamma_d(u_d) + \int_{\bP_d(E_d)} \langle \xi, u_d \rangle \, M_d(\D \xi) - \int_{\cHplus_d \setminus \{0\}} K(\xi, u_d) \, M_d(\D \xi).
\end{align*}

\subsubsection{Matrix-Valued Admissible Parameters}
Next, we relate the finite-rank approximate admissible parameters $b_d$, $m_d$,
$M_d$, and $\mathbf{B}_d$ to their matrix-valued counterparts. This is necessary
in order to apply the existence results for matrix-valued affine processes
from~\cite{CFMT11}. 

For $d \in \mathbb{N}$, we denote by $\{v_1, \ldots, v_d\}$ the standard basis
of $\mathbb{R}_d$, and define the coordinate system $\Phi_d \colon \mathbb{R}_d
\to H_d$ associated with the basis $\{e_1, \ldots, e_d\}$ of $H_d$ by   
\begin{align}\label{eq:coordinate-system}
  \Phi_d(v_i) = e_i, \quad \text{for } i = 1, \ldots, d.  
\end{align}
The coordinate system $\Phi_d$ identifies the $d$-dimensional subspace $H_d$ with $\mathbb{R}_d$, allowing us to represent every linear operator $A \in \mathcal{L}(H_d)$ as a $d \times d$-matrix through the mapping $i_d \colon \mathcal{L}(H_d) \to \mathbb{S}_d$, defined by  
\begin{align}\label{eq:canonical-identification-d}
  i_d(A) \coloneqq \Phi_d^{-1} \circ A \circ \Phi_d,  
\end{align}
where, under the usual matrix identification, we interpret $i_d(A)$ as an element in $\mathbb{M}_d$. Note that when $A$ is self-adjoint, its matrix representation $i_d(A)$ is also self-adjoint. This can be verified by taking $x, y \in \mathbb{R}_d$ and performing the following computation:
\begin{align*}
  (i_d(A)x, y)_{\mathbb{R}^d} = (A \circ \Phi_d(x), \Phi_d(y))_H = (\Phi_d(x), A^* \circ \Phi_d(y))_H = (x, i_d(A)y)_{\mathbb{R}^d}.  
\end{align*}
Under the mapping $i_d$ in~\eqref{eq:canonical-identification-d}, we identify
$\mathcal{H}_d\vert_{H_d} \subseteq \mathcal{L}(H_d)$ with $\mathbb{S}_d$ and
note that $i_d$ is an isometry between $\mathbb{S}_d$ and
$\mathcal{H}_d\vert_{H_d}$, meaning that it identifies the Frobenius norm with
the Hilbert-Schmidt norm. In the following, we may sometimes omit writing the
restriction $\rvert_{H_d}$ when it is clear from the context. Moreover, we
denote by $\mathbb{S}_d^+$ the convex cone of all symmetric positive
semi-definite $d \times d$-matrices, and observe that positivity is preserved
under $i_d$, i.e. $i_d(\mathcal{H}_d^+) = \mathbb{S}_d^+$.

\begin{definition}\label{def:admissible-matrix}
    Let $(b,B,m,\mu)$ be an admissible parameter set as in
  Definition~\ref{def:admissible-irregular} and for $d\in\MN$ let
  $(b_{d},B_{d},m_{d},\mu_{d})$ and $M_{d}$ be as in
  Definition~\ref{def:admissible-Galerkin}. For every $d\in\MN$ we define the parameters 
  $(\tilde{b}_{d},\tilde{B}_{d},\tilde{m}_{d},\tilde{\mu}_{d})$ and $\tilde{M}_{d}$ as follows:
  \begin{defenum}
  \item\label{item:b-d} The matrix $\tilde{b}_{d}\in\MS_{d}^{+}$ is
    defined as $\tilde{b}_{d}\df i_{d}(b_{d})$.
  \item\label{item:B-d} 
  Define the linear operator
  $\tilde{B}_{d}\colon \MS_{d}\to\MS_{d}$ for $u\in\MS_{d}$ by
 \begin{align}\label{eq:B-d}
 \tilde{B}_{d}(u)\df i_{d}\mathbf{B}_{d}(i^{-1}_{d}x)=
   Bi_{d}^{-1}x+i_{d}^{-1}xB^{*}+\tilde{\Gamma}_{d}(x), 
 \end{align}
 where $\tilde{\Gamma}_{d}(u)\df i_{d}\Gamma_{d}(i_{d}^{-1}u)$.
  \item\label{item:m-d} The measure $\tilde{m}_{d}\colon\cB(\MS_{d}^{+}\setminus\set{0})\to
    [0,\infty]$ is defined as the push-forward of $m_{d}$ with respect to $i_{d}$, i.e.
    \begin{align*}
     \tilde{m}_{d}(\D\xi)\df (i_{d\,*}m_{d})(\D\xi). 
    \end{align*}
  \item\label{item:mu-d} The matrix-valued measure $\tilde{\mu}_{d}\colon
    \cB(\MS_{d}^{+}\setminus\set{0})\to \MS_{d}^{+}$ is defined as the
    composition of $i_{d}$ and the push-forward of $\mu_{d}$ with respect to
    $i_{d}$, i.e. 
    \begin{align*}
      \tilde{\mu}_{d}(\D\xi)=i_{d}((i_{d\,*}\mu_{d})(\D\xi)). 
    \end{align*}
    Moreover, we define the $\MS_{d}^{+}$-valued measure $\tilde{M}_{d}(\D\xi)$
    as follows: For every
    $A\in\cB(\MS_{d}^{+}\setminus\set{0})$ we set 
  \begin{align*} 
    \tilde{M}_{d}(A)=\int_{\cHpluso}\one_{A}(i_{d}(\bP_{d}(\xi)))\frac{1}{\norm{\xi}^{2}}i_{d}(\bP_{d}(\mu(\D\xi))),
  \end{align*}
  and for every $x\in\MS_{d}^{+}$ we write $\tilde{M}_{d}(x,\D\xi)\df\langle x,\tilde{M}_{d}(\D\xi)\rangle$.
\end{defenum}
\end{definition}

With the definition of the matrix-valued admissible parameters at hand we can
now prove Proposition~\ref{prop:embedding-affine-main}. 

\begin{proof}[Proof of Proposition~\ref{prop:embedding-affine-main}]

  Let $d \in \mathbb{N}$ and $\tilde{b}_d$, $\tilde{B}_d$, $\tilde{m}_d$,
  $\tilde{\mu}_d$, and $\tilde{M}_d$ be as defined in parts (i) to (iv) of
  Definition~\ref{def:admissible-matrix}. Since the admissibility of the
  parameters $\tilde{b}_d$, $\tilde{m}_d$, and $\tilde{\mu}_d$ was already shown
  in \cite[Lemma 5.6 and Proposition 5.7]{karbach2023finiterank}, to prove that
  $(\tilde{b}_d, \tilde{B}_d, \tilde{m}_d, \tilde{\mu}_d)$ forms a matrix-valued
  admissible parameter set as defined in \cite[Definition 3.1]{May12}, it
  remains to demonstrate the admissibility of $\tilde{B}_d$. Specifically, we
  need to show that for all $x, u \in \mathbb{S}_d^+$ such that
  $\langle x, u \rangle_d = 0$, we have
  \begin{align*}
    \langle \tilde{B}_d x + x \tilde{B}_d^*, u \rangle_d = 0,
  \end{align*}
  and that
  \begin{align}\label{eq:admissible-matrix-check}
    \langle \Gamma_d(x), u \rangle_d - \int_{\mathbb{S}_d^+ \setminus \{0\}} \langle \chi(\xi), u \rangle_d \tilde{M}_d(x, \D \xi) \geq 0.
  \end{align}

  To prove this, let $x, u \in \mathbb{S}_d^+$ such that
  $\langle x, u \rangle_d = 0$. The quasi-monotonicity condition
  $\langle \tilde{B}_d x + x \tilde{B}_d^*, u \rangle_d = 0$ follows directly as
  shown in \cite{CFMT11}. Moreover, we have $x_d, u_d \in \cHplus$ and
  $\langle u_d, x_d \rangle = 0$, and since
  $\langle \Gamma_d(x), u \rangle_d = \langle \Gamma(x), u \rangle$, and
  \begin{align*}
    \int_{\mathbb{S}_d^+ \setminus \{0\}} \langle \chi(\xi), u \rangle_d
    \tilde{M}_d(x, \D \xi) = \int_{\cHpluso} \langle \chi(\xi), u \rangle
    \frac{\langle \mu(\D \xi), x \rangle}{\|\xi\|^2},     
  \end{align*}
  we see that \eqref{eq:admissible-matrix-check} follows from the admissibility
  condition part (b) of~\cref{item:linear-operator-unbounded}.\par{}

  This proves that $(\tilde{b}_d, \tilde{B}_d, \tilde{m}_d, \tilde{\mu}_d)$ is a
  matrix-valued admissible parameter set. Therefore, by \cite[Theorem
  2.4]{CFMT11} and \cite[Theorem 3.2]{May12}, there exists a unique affine
  process $(\tilde{X}^d)_{t \geq 0}$ with values in $\mathbb{S}_d^+$.

  Note further that the existence of a c\`adl\`ag version of
  $(\tilde{X}^{d})_{t \geq 0}$ follows from \cite{CT13}, and we will denote this
  version again by $(\tilde{X}^{d})_{t \geq 0}$. Moreover, we denote the law of
  $\tilde{X}^{d}$, given that $\tilde{X}^{d}_0 = x$, by $\tilde{\MP}^{d}_x$. By
  \cite[Remark 2.5]{CFMT11}, combined with the second moment assumption in
  \cref{item:m-d} and \cref{item:mu-d}, the
  $\mathbb{S}_d^+$-valued affine process $(\tilde{X}^{d})_{t \geq 0}$ satisfies
  \begin{align*}
    \tilde{\MP}^{d}_x\left(\left\{ \tilde{X}^{d}_t \in \mathbb{S}_d^+ \mid t \geq 0 \right\}\right) = 1.    
  \end{align*}

  For every $d \in \mathbb{N}$ and $x \in \mathbb{S}_d^+$, the law
  $\tilde{\MP}^{d}_x$ is thus defined on $\cB(D(\mathbb{R}^+,
  \mathbb{S}_d^+))$. Furthermore, since the diffusion part is zero, it follows
  from \cite{May12} that $(\tilde{X}^{d})_{t \geq 0}$ is a finite-variation
  process.

  Additionally, from \cite[Theorem 2.6]{CFMT11}, we know that the process
  $\tilde{X}^{d}$ is a semimartingale with characteristics given by: 
\begin{align*}
  \tilde{C}^{d}_t = 0, \quad \tilde{\nu}^{d}(\D t, \D \xi) = \big(\tilde{m}_d(\D \xi) + \tilde{M}_d(\tilde{X}^{d}_t, \D \xi)\big) \D t,  
\end{align*}
and
\begin{align*}
\tilde{A}^{d}_t = \int_0^t \left( \tilde{b}_d + \tilde{B}_d(\tilde{X}^{d}_s) \right) \D s.  
\end{align*}

Finally, since the process $(\tilde{X}^{d}_t)_{t \geq 0}$ is of finite
variation, it is locally bounded and by the admissibility in the matrix sense,
we conclude that 
\begin{align*}
\int_0^t \int_{\mathbb{S}_d^+ \setminus \{0\}} \|\xi\|_d^2 \, \tilde{\nu}^{d}(\D
  t, \D \xi) < \infty,   
\end{align*}
for all $t \geq 0$. By \cite[Proposition 2.29(b)]{JS03}, this implies that $X$ is a square-integrable martingale, i.e.
\begin{align*}
\EXspec{\tilde{\MP}^{d}_x}{\|\tilde{X}^{d}_t\|_d^2} < \infty,  
\end{align*}
for all $t \geq 0$. 

Now, for every $d \in \mathbb{N}$, let
$(\tilde{X}^d, (\tilde{\MP}^d_x)_{x \in \mathbb{S}_d^+})$ be the
$\mathbb{S}_d^+$-valued affine process given as above. More precisely, let
$\tilde{X}^d$ be a version with paths in
$\Omega = D(\mathbb{R}^+, \mathbb{S}_d^+)$, and denote by $\tilde{\MP}^d_x$ the
law of $\tilde{X}^d$, defined on $\cB(\Omega)$, given that
$\tilde{X}_0^d = x \in \mathbb{S}_d^+$. Moreover, let
$(\tilde{\cF}^d_t)_{t \geq 0}$ denote the natural filtration of the process
$\tilde{X}^d$.

By identifying the cones $\mathbb{S}_d^+$ and $\cH_d^+$ under the mapping
$i_d^{-1}$, we define the process $X^d = (X^d_t)_{t \geq 0}$ as
\begin{align*}
  X^d_t \coloneqq i_d^{-1}(\tilde{X}^d_t) = \Phi_d \circ \tilde{X}^d_t \circ \Phi_d^{-1}, \quad t \geq 0.  
\end{align*}

Note that the process $(X^d_t)_{t \geq 0}$ has paths in
$D(\mathbb{R}^+, \cH_d^+)$, and the law of $X^d$ is given by the push-forward
measure $(i_d^{-1})_* \tilde{\MP}^d_x$ for $x \in \mathbb{S}_d^+$. Here,
$i_d^{-1}$ acts pointwise on the functions in
$D(\mathbb{R}^+, \mathbb{S}_d^+)$, such that
\begin{align*}
i_d^{-1}(D(\mathbb{R}^+, \mathbb{S}_d^+)) = D(\mathbb{R}^+, \cH_d^+).  
\end{align*}

Moreover, we observe that
$D(\mathbb{R}^+, \cH_d^+) \subseteq D(\mathbb{R}^+, \cHplus)$ for all
$d \in \mathbb{N}$, see \cite[Remark 4.5]{Jak86}. For every $x \in \cHplus$, we
define the measure $\MP^d_x$ on $D(\mathbb{R}^+, \cHplus)$ as
\begin{align*}
  \MP^d_x(A) = (i_d^{-1})_* \tilde{\MP}^d_{i_d(\bP_d(x))}(A \cap D(\mathbb{R}^+, \cH_d^+)), \quad A \in \cB(D(\mathbb{R}^+, \cHplus)).  
\end{align*}

Note that
\begin{align*}
  \MP^d_x\big(X^d_0 = \bP_d(x)\big) = \tilde{\MP}^d_{i_d(\bP_d(x))}\big(\tilde{X}^d_0 = i_d(\bP_d(x))\big) = 1,  
\end{align*}
and the process $(X^d, (\MP^d_x)_{x \in \cHplus})$ is a Markov process on the
ambient space $\cHplus$ with respect to its natural filtration
$\MF^d = (\cF^d_t)_{t \geq 0}$. We set $\cF^d = \cF^d_\infty$. Moreover, for
every $x \in \cHplus$, denoting by $\mathcal{N}^d_x$ the collection of all
$\MP^d_x$-null sets of $\cF^d$, we define
\begin{align*}
\bar{\cF}_t \coloneqq \cF^d_t \vee \mathcal{N}^d_x \quad \text{for every } t \geq 0,  
\end{align*}

and set $\bar{\MF}^d \coloneqq (\bar{\cF}_t)_{t \geq 0}$. In other words,
$\bar{\MF}^d$ is the usual augmented filtration of $X^d$, and $X^d$ remains a
Markov process with respect to $\bar{\MF}^d$.

Furthermore, we prove in the following proposition that
$(X^d, (\MP^d_x)_{x \in \cHplus})$ satisfies an affine transform formula
associated with the Galerkin approximations in
\eqref{eq:mild-Riccati-Galerkin-phi}-\eqref{eq:mild-Riccati-Galerkin-psi},
and the canonical process of $\MP^d_x$ on $D(\mathbb{R}^+, \mathbb{S}_d^+)$ is a
semimartingale with respect to the stochastic basis
$(\Omega, \bar{\cF}^d, \bar{\MF}^d, \MP^d_x)$.

Then, \cite[Proposition 5.10 and Proposition 5.11]{karbach2023finiterank} holds true for the
admissible parameter set $(b,\mathbf{B},m,\mu)$ as well. Therfore, the process $(X^{d},(\MP_{x})_{x\in\cHplus})$ is an affine process on $\cHplus$ such
that $\MP_{d}^{d}(\set{X_{t}^{d}\in\cHplus_{d}\colon t\geq 0})=1$
and~\eqref{eq:affine-Galerkin} holds true. Moreover, the canonical process of $\MP_{x}^{d}$ on $D(\MRplus,\cHplus)$, still denoted by
$(X_{t}^{d})_{t\geq 0}$ is a semimartingale, such that the process
$(\bar{J}^d_t)_{t \geq 0}$, given by 
\begin{align*}
  \bar{J}^d_t \coloneqq X^d_t \!-\! \bP_d(x) \!-\! \!\int_0^t \!\left(b_d + B_d(X^d_s) - \int_{\cHplus_d \cap \{\|\xi\| > 1\}} \xi \, (m_d(\D\xi) + M_d(X^d_s, \D\xi)) \right) \D s,  
\end{align*}
is a square-integrable martingale on $\cH_d$. 
 \end{proof}


 \subsubsection{Weak Convergence of the Affine Finite-Rank Processes}

 Let $(b, B, m, \mu)$ be an admissible parameter set, and for each
 $d \in \mathbb{N}$, let $X^d$ denote the associated affine finite-rank
 operator-valued process given by
 Proposition~\ref{prop:embedding-affine-main}. In this section, we study the
 tightness and weak convergence of the sequence $(X^d)_{d \in \mathbb{N}}$ in
 the space $D(\mathbb{R}^+, \cHplus)$ equipped with the Skorohod topology. More
 precisely, for each $x \in \cHplus$, we consider the sequence
 $(\MP^d_x)_{d \in \mathbb{N}}$, which represents the laws of $X^d$ given that
 $X^d_0 = \bP_d(x)$, defined on the Borel $\sigma$-algebra
 $\cB(D(\mathbb{R}^+, \cHplus))$, and examine its weak convergence as
 $d \to \infty$.

 To achieve this, we first prove that the sequence of laws
 $(\MP^d_x)_{d \in \mathbb{N}}$ is uniformly tight on $\cB(D(\mathbb{R}^+,
 \cHplus))$. 

\begin{lemma}\label{lem:tightness-irregular}
For every $x\in\cHplus$ the sequence $(\MP^{d}_{x})_{d\in\MN}$ of laws of
$(X^{d})_{d\in\MN}$ is a tight sequence of measures on
$\cB(\!D(\MRplus,\cHplus)\!)$.  
\end{lemma}
\begin{proof}
  Following \cite[Theorem 3.1, Corollary 5.2]{Jak86}, we show that $X^d$
  satisfies the \emph{compact containment} property, i.e., for each
  $\epsilon > 0$, there exists a compact set $K_\epsilon \subseteq \cH$ such
  that $p_d(D_1(K_\epsilon)) > 1 - \epsilon$ for all $d \in \mathbb{N}$, and
  that it is \emph{weakly tight}, meaning that for every $h \in \cH$, the
  sequence of real-valued processes
  $(\langle X^d, h \rangle)_{d \in \mathbb{N}}$ is tight.

  The compact containment property follows from the fact that the embedding
  $\cV \hookrightarrow \cH$ is compact (see \cite[Proposition
  2.1]{Tem71}). Indeed, note that that $\cHplus_d \subseteq \cV$ for all
  $d \in \mathbb{N}$, and thus we conclude that $p_d(D_1(\cV)) = 1$ for all
  $d \in \mathbb{N}$. Therefore, the compact containment property is satisfied.

  Secondly, we show that for every $k\in\MN$, we have $\set{\langle
    X^{d},e_{k}\rangle\colon d\in\MN}$ is tight in $D([0,T];\MR)$, which is
  sufficient by~\cite[Theorem 3.1]{Jak86}. For this, we have to check two
  conditions: first, that for every $k\in\MN$ we have
  \begin{align}\label{eq:weak-tight-1}
    \sup_{d\in\MN}\EX{\sup_{0\leq t\leq T}\langle X_{t}^{d},e_{k}\rangle^{2}}<\infty,
  \end{align}
  and secondly, that:
  \begin{align}\label{eq:weak-tight-2}
    \EX{|\langle X_{\tau_{d}}^{d}, e_{k} \rangle-\langle
    X_{\tau_{d}+\delta_{d}}^{d}, e_{k}\rangle|^{2}}\to 0 \quad\text{as }d\to\infty,
  \end{align}
  for every sequence of stopping times $(\tau_{d})_{d\in\MN}$  with
  $\tau_{d}\leq T$ for all $d\in\MN$.

  Recall that the process $(\bar{J}^{d}_{t})_{t\geq 0}$ given by 
  \begin{align}\label{eq:decomp-martingale} 
    \bar{J}^{d}_{t}&\df
                     X_{t}^{d}\!-\!\bP_{d}(x)\!-\!\int_{0}^{t}\!\!\big(b_{d}+B_{d}(X_{s}^{d})-\!\int_{\cHplus_{d}\cap\set{\norm{\xi}>
                   1}}\!\!\xi\,(m_{d}(\D\xi)\!+\!M_{d}(X_{s}^{d},\D\xi)\big)\D s, 
\end{align}

Note first that by the representation in \eqref{eq:decomp-martingale} we have  
\begin{align*}
  \langle X_{t}^{d},e_{k}\rangle&=\langle
                                  x_{0}^{d},e_{k}\rangle+\int_{0}^{t}-\lambda_{k}\langle
                                  X_{s}^{d},e_{k}\rangle+\langle
                                  \hat{b}_{d},e_{k}\rangle+\langle
                                  X_{s}^{d}, \hat{\Gamma}(e_{k})\rangle+
                                  M_{t}^{d,k},                                      \end{align*}
      Since $(M_{t}^{d,k})_{t\geq 0}$ is of finite-variation the variation of
      constant formula applies and we find: 
      \begin{align}\label{eq:variation-constant-help}
        \langle X_{t}^{d},e_{k}\rangle&=\E^{-\lambda_{k}t}\langle x_{0}^{d},
                                        e_{k}\rangle+\int_{0}^{t}\E^{-\lambda_{k}(t-s)}\big(\langle
                                        \hat{b}_{d},e_{k}\rangle+\langle
                                        X_{s}^{d},
                                        \hat{\Gamma}(e_{k})\rangle\big)\D s\nonumber\\
        &\quad +
                                        \int_{0}^{t}\E^{-\lambda_{k}(t-s)}\D M_{s}^{d,e_{k}}.
      \end{align}
      Then squaring both sides and standard estimations yields:
      \begin{align*}
        \langle X_{t}^{d},e_{k}\rangle^{2}& \leq 3 \E^{-2\lambda_{k}t}\langle
                                            x_{0}^{d}, e_{k}\rangle^{2}+6\int_{0}^{t}\E^{-2\lambda_{k}(t-s)}\big(\langle
                                            \hat{b}_{d},e_{k}\rangle^{2}+\langle
                                            X_{s}^{d},
                                            \hat{\Gamma}(e_{k})\rangle^{2}\big)\D s
                                            \\
        &\quad +3
                                            (\int_{0}^{t}\E^{-\lambda_{k}(t-s)}\D
          \langle M_{t}^{d}, e_{k}\rangle)^{2}\\
        &\leq 3 \langle x_{0}^{d},
          e_{k}\rangle^{2}+6\int_{0}^{t}\big(\langle\hat{b}_{d},e_{k}\rangle^{2}+\langle
          X_{s}^{d},\hat{\Gamma}(e_{k})\rangle^{2}\big)\D s +3\langle M_{t}^{d}, e_{k}\rangle^{2}.
      \end{align*}
      Now, as
      \begin{align*}
        \sup_{d\in\MN}\EX{\langle
        M^{d}\rangle_{T}}&=\sup_{d\in\MN}\int_{0}^{T}\EX{\Tr(-\D^{2}F_{d}(0)-\D^{2}R_{d}(0)^{*}(X_{s}^{d}))\D
        s}\\
        &\leq T \sup_{d\in\MN}\EX{\sup_{0\leq t\leq T}\norm{X_{t}^{d}}}, 
      \end{align*}
      we can estimate
      \begin{align*}
       \EX{\sup_{0\leq t\leq T}\langle X_{t}^{d},
        e_{k}\rangle^{2}}&\leq 3 \langle x_{0}, e_{n}\rangle^{2}+6
                           \big(\norm{\hat{b}_{d}}^{2}+\norm{\hat{\Gamma}^{*}}_{\cL(\cH)}^{2}\int_{0}^{T}\EX{\sup_{0\leq
                           s\leq t}\norm{ X_{s}^{d}}}\big)\D t\\
                                    &\quad + 3 K \int_{0}^{T}\EX{\sup_{0\leq
                                      s\leq t}\norm{X_{s}^{d}}}\D t,
      \end{align*}
      by Gronwall's inequality we find
      \begin{align*}
        \EX{\sup_{0\leq t\leq T}\langle X_{t}^{d},e_{k}\rangle^{2}}&\leq
                                                                     \tilde{K}(1+\norm{x_{d}}^{2}), 
      \end{align*}
      where $\tilde{K}$ does not depend on $d\in\MN$ and hence
      \eqref{eq:weak-tight-1} follows. Now, we show
      \eqref{eq:weak-tight-2}. Let $(\tau_{d})_{d\in\MN}$ be a sequence
      of stopping times such that $\tau_{d}\leq T$ and $(\delta_{d})_{d\in\MN}$ a
      sequence of positive real numbers converging to zero. Then by
      using~\eqref{eq:variation-constant-help}, we obtain::
      \begin{align*}
        \EX{|\langle X_{\tau_{d}}^{d}, e_{k} \rangle-\langle
        X_{\tau_{d}+\delta_{d}}^{d}, e_{k}\rangle|^{2}}\leq
        \delta_{d}\EX{\sup_{0\leq t\leq\delta_{d}}(1+\norm{X_{t}^{d}})^{2}}
      \end{align*}



      % \begin{align*}
      %   \EX{|\langle X_{\tau_{d}}^{d}, e_{k} \rangle-\langle
      %   X_{\tau_{d}+\delta_{d}}^{d}, e_{k}\rangle|^{2}}&\leq 2\EX{|\langle
      %                                                    A_{\tau_{d}}^{d},
      %                                                    e_{k} \rangle-\langle
      %                                                    A_{\tau_{d}+\delta_{d}}^{d},
      %                                                    e_{k}\rangle|^{2}}\\
      %   &\quad+2\EX{|\langle
      %                                                    M_{\tau_{d}}^{d},
      %                                                    e_{k} \rangle-\langle
      %                                                    M_{\tau_{d}+\delta_{d}}^{d},
      %                                                    e_{k}\rangle|^{2}}.
      % \end{align*}
%       Moreover, we have
%       \begin{align*}
%        \EX{|\langle A_{\tau_{d}}^{d},e_{k} \rangle-\langle
%         A_{\tau_{d}+\delta_{d}}^{d}, e_{k}\rangle|^{2}}&\leq
%                                                          \int_{\tau_{d}}^{\tau_{d}+\delta_{d}}\EX{\langle\hat{b}_{d},e_{k}\rangle+\langle \hat{B}^{*}_{d}(e_{k}),
%                                                          X_{s}^{d}\rangle}\D s\\
%         &\leq \delta_{d}
%       \end{align*}
% and 
%       \begin{align*}
%         \EX{|\langle
%                                                          M_{\tau_{d}}^{d},
%                                                          e_{k} \rangle-\langle
%                                                          M_{\tau_{d}+\delta_{d}}^{d},
%         e_{k}\rangle|^{2}}&\leq 4
%                             \int_{\tau_{d}}^{\tau_{d}+\delta_{d}}\EX{\int_{\cHplus_{d}\setminus\set{0}}\langle
%                             \xi,e_{k}\rangle^{2}\,m_{d}(\D\xi)}\D s\\
%         &\quad +4
%                             \int_{\tau_{d}}^{\tau_{d}+\delta_{d}}\EX{\int_{\cHplus_{d}\setminus\set{0}}\langle
%                             \xi, e_{k}\rangle^{2} \langle
%           X_{s}^{d},\mu_{d}(\D\xi)\rangle}\D s\\
%         &\leq \delta_{d}K\EX{\sup_{0\leq t \leq \delta_{d}}(1+\norm{X_{t}^{d}}^{2})}\big),
%       \end{align*}
%       for
%       $K=\int_{\cHplus_{d}\setminus\set{0}}\norm{\xi}^{2}\,m(\D\xi)+\mu(\cHpluso)$. Now,
      and letting $\delta_{d}$ go to zero and Chebyshev's inequality concludes the
      statement.
      \end{proof}

      \begin{proof}[Proof of Theorem~\ref{thm:main-convergence}]
        From Lemma~\ref{lem:tightness-irregular} we know that the
        sequence $(X^{d})_{d\in\MN}$ of affine processes is uniformly
        tight. Therefore there exists a subsequence that converges weakly to the
        law $\MP$. This implies the convergence of the Laplace transforms, i.e.
        \begin{align*}
          \EXspec{x^{d}}{\E^{-\langle X^{d},u\rangle}}\to
          \EXspec{x}{\E^{-\langle X,u\rangle}},   
        \end{align*}
        for all $u\in\cHplus$ and $t\geq 0$ as $d\to\infty$. Moreover, we have
        $\EXspec{x^{d}}{\E^{-\langle X^{d},u\rangle}}=\E^{-\phi_{d}(t,u)-\langle
          x^{d}, \psi_{d}(t,u)\rangle}\to \E^{-\phi(t,u)-\langle x,
          \psi(t,u)\rangle}$ for $u\in\dom(\mathbf{B})$ by
        Proposition~\ref{prop:existence-mild-Riccati} and thus by density of
        $\dom(\mathbf{B})$ in $\cHplus$ we conclude that
        \eqref{eq:affine-formula-main} holds true for all $u\in\cHplus$ and
        $t\in [0,T]$. As the Laplace transform is measure determining, it
        follows
        that the probability measure $\MP$ is unique.\\
        Instead of infering the quasi-left continuity from the Aldous criterion,
        we use the criterion in \cite[Theorem 3.12]{EK86}. Indeed, as we proved
        before the process $X$ is the unique solution to the martingale problem
        for $\cG$ with respect to $(\MG_{t})_{t\geq 0}$ with sample paths in
        $D([0,T],\cHplus)$, this implies the quasi-left continuity of the
        process $X$.
  \end{proof}


