\subsection{Finite-Rank Approximation of Heat Modulated Affine Stochastic Covariance
  Models}\label{sec:proof-section-2} 

We begin with the proof of~\cref{item:finite-dim-approx-ScoV-1}. For this let
$x\in\cHplus$ and denote by $X$ the square-integrable Markovian semimartingale
associated with the admissible parameters $(b,B,m,\mu)$ given by
Theorem~\ref{thm:main-convergence} on the stochastic basis $(\Omega, \cF, \MF,
\MP)$.

We have already argued that the stochastic covariance model $(f,X)$ is
well-defined when Assumption~\ref{assump:integration} is satisfied. If we model
the forward curves in the space $H$, then we require merely
$X_{t}^{1/2}\in\cH$. Now, let $d\in\MN$ and consider
$(f^{d}_{t},X^{d}_{t})_{t\geq 0}$ with $X^{d}$ as given by
Proposition~\ref{prop:embedding-affine-main} where in particular
$X^{d}_{0}=\bP_{d}(x)$.\par{}

It follows from part ii) in Proposition~\ref{prop:embedding-affine-main} that the
process $X^{d}$ is a square-integrable affine Markovian semimartingale on some
stochastic basis $(\Omega^{d},\bar{\cF}^{d},\bar{\MF}^{d},\MP^{d}_{x})$ and from the
representation~\eqref{eq:decomp-martingale} we see that the process
$(f^{d}_{t},X^{d}_{t})_{t\geq 0}$ satisfies
\begin{align}\label{eq:stochastic-covariance-model-approximation}
  \D \begin{bmatrix}
    f^{d}_{t}\\
    X^{d}_{t}
  \end{bmatrix}&= \left(\begin{bmatrix}
    0 \\
    \hat{b}_{d}
  \end{bmatrix}+\begin{bmatrix}
    \cA(f^{d}_{t}) \\
    \hat{B}_{d}(X^{d}_{t}) 
  \end{bmatrix}\right)\, \D t+\begin{bmatrix}
    D^{1/2}(X^{d}_{t})^{1/2} & 0 \\
    0 & 0 
  \end{bmatrix}\D \begin{bmatrix}
    W_{t} \\
      0
    \end{bmatrix}+\D \begin{bmatrix}
      0 \\
      \bar{J}^{d}_{t}
    \end{bmatrix},
\end{align}
with $(f^{d}_{0},X^{d}_{0})=(f,\bP_{d}(x))\in H\times \cHplus\,$,
$\hat{b}_{d}=b_{d} +\int_{\cHplus_{d}\cap \{\|\xi\| >1\}} \xi \,m_{d} (\D
\xi)$ and 
\begin{align*}
\quad \hat{B}(u)=B_{d}(\bP_{d}(u))+\int_{\cHplus_{d}\cap \set{\norm{\xi}>
  1}}\xi\,\langle u,M_{d}(\D\xi)\rangle,\quad \forall\,u\in\cH.
\end{align*}
Thus, the model is of the form in~\cite[Definition
2.9]{CKK22b}. Therefore,~\cref{item:finite-dim-approx-ScoV-1} follows
immediately from~\cite[Theorem 3.3]{CKK22b}.

We continue with~\cref{item:finite-dim-approx-ScoV-2}. Note that for every
$d\in\MN$ the process $f^{d}$ is the mild solution of the first component
in~\eqref{eq:stochastic-covariance-model-approximation} given by
\begin{align*}
  f_{t}^{d}=S(t)f+\int_{0}^{t}S(t-s)(X^{d}_{s})^{1/2}\D W_{s},\quad t\geq 0,
\end{align*}
where the stochastic integral with respect to the cylindrical Brownian motion
is well-defined, see
Secion~\ref{sec:HJMM-equation}. From~\cref{item:main-convergence-2}, we already
know that $X^{d}$ converges weakly to $X$ on $D(\MRplus,\cHplus)$ as
$d$ tends to infinity. From this and~\cite[Theorem 4.2]{KP96} we conclude
the weak convergence of the stochastic integrals, i.e.
$$\Big(\int_{0}^{t}S(t-s)(X^{d}_{s})^{1/2}\D W_{s}\Big)_{t\geq 0}\overset{d\to\infty}{\Rightarrow}
\Big(\int_{0}^{t}S(t-s)X_{s}^{1/2}\D W_{s}\Big)_{t\geq 0},$$
which in turn implies that also the joint processes $(f^{d},X^{d})_{d\in\MN}$
converges weakly to $(f,X)$ as $d$ tends to infinity.\par{}

We now come to the convergence rate
in~\eqref{eq:stochastic-covariance-convergence-rate}. Let $T\geq 0$,
$\tilde{u}\in H$ and $u=(\I\tilde{u},0)$. Note that for every $M\geq 0$ we find
a local Lipschitz constant of the map $u\mapsto \hat{\cR}(h,u)$ on
$\set{u\in\cHplus\colon \norm{u}\leq M}$ independent of $h\in H$ and $d\in\MN$,
when we replace $\hat{\cR}$ by $\bP_{d}\circ \hat{\cR}\circ \bP_{d}$, compare this with
Lemma~\ref{lem:irregular-properties}. Again by a similar argument as in the
proof of Proposition~\ref{prop:existence-mild-Riccati}, we conclude that for
every $M\geq 0$ there exists a $\tilde{H}_{M}>0$, independent of $d\in\MN$, such
that $\norm{\psi_{2}(t,u)}\vee\norm{\psi_{2,d}(t,u)}\leq \tilde{H}_{M}$ for all
$t\in [0,T]$ and all $\tilde{u}\in H$ with $\norm{\tilde{u}}_{H}\leq M$. Note,
that in contrast to the proof of Proposition~\ref{prop:existence-mild-Riccati}
we assume $\psi_{2}(0,u)=0$, but have the additional inhomogeneous-term
$-\frac{1}{2}(\psi_{1}(t,u)\otimes \psi_{1}(t,u))$ where
$\psi_{1}(\cdot,u)$ solves~\eqref{eq:Riccati-phi-psi-1-2}, i.e. it is given by
$\psi_{1}(t,u)=\I S(t)\tilde{u}$. This implies that the $\tilde{H}_{M}$ depends
on $\tilde{u}$ and is in general different to the $H_{M}$ we used before.\par{}

So let $T$, $M$ and $\tilde{H}_{M}$ as above. Then Inserting the
affine-transform formulas~\eqref{eq:extended-affine-formula}
and~\eqref{eq:stochastic-covariance-affine-formula} of $(f,X)$ and
$(f^{d},X^{d})$, respectively, and using standard estimations we obtain
\begin{align}\label{eq:proof-convergence-rate-scov}
  \sup_{t\in [0,T]}\left|\EX{\E^{\I \langle f_{t},
  \tilde{u}\rangle_{H}}}\!-\!\EX{\E^{\I\langle
  f^{d}_{t},\tilde{u}\rangle_{H}}}\right|&\leq \sup_{t\in [0,T]}\big(
                                           \left|\Phi(t,u)-\Phi_{d}(t,u)\right|\nonumber\\
                                         &\qquad +\norm{x}\norm{\psi_{2}(t,u)-\psi_{2,d}(t,u)}\big).
\end{align}

The terms on the right-hand side
of~\eqref{eq:proof-convergence-rate-scov} can be estimated similarly to
what we saw in the proof of
Proposition~\ref{prop:existence-mild-Riccati}. Indeed, for $u\in\cHplus$ and
$s\geq 0$ we define the function $\tilde{R}_{d}(s,u)\df \bP_{d}(\hat{\cR}(\bP_{d}(\psi_{2,d}(s,u))))-\frac{1}{2}(\psi_{1}(s,u))^{\otimes 2}$
and we see that  
\begin{align*}
  \norm{\bP_{d}(\psi_{2}(t,u))-\psi_{2,d}(t,u)}&\leq K+M\int_{0}^{t}\norm{\bP_{d}\big(\hat{\cR}(\psi_{1}(s,u),\psi_{2}(s,u))\big)-\hat{\cR}_{d}(s,u)}\,\D
                                                s\\
                                               &\leq K+M\int_{0}^{t}\norm{\hat{\cR}(\psi_{2}(s,u))-R(\bP_{d}(\psi_{2,d}(s,u)))}\,\D
                                        s\\
                                              &\leq K+
                                                \tilde{L}_{M}^{(1)}\int_{0}^{t}\norm{\psi_{2}(s,u)-\psi_{2,d}(s,u)}\,\D s, 
\end{align*}
where $\tilde{L}^{(1)}_{M}$ denotes a Lipschitz constant of $\hat{\cR}$ on the set
$\set{u\in\cHplus\colon \norm{u}\leq \tilde{H}_{M}}$. Since $u_{2}=0$, we see
that an application of the variation-of-constant formula yields
\begin{align*}
  \psi_{2}(t,u)=\int_{0}^{t}\Big(\cT(t-s)K_{\psi_{2}(s,u)}(\xi)\frac{\mu(\D\xi)}{\norm{\xi}^{2}}-\frac{1}{2}\cT(t-s)(\psi_{1}(s,u))^{\otimes
  2}\Big)\,\D s.  
\end{align*}
Thus by inserting $\psi_{1}(t,u)=\I S(t)\tilde{u}$ we see that 
\begin{align}
  \norm{\bP_{d}^{\perp}(\psi_{2}(t,u))}&\leq
                                         \tilde{H}_{M}^{2}t\sup_{s\in
                                         [0,t]}\norm{\bP_{d}^{\perp}\cT(s)\mu(\cHpluso))}\nonumber\\
                                       &\qquad+\frac{1}{2}t\sup_{s\in[0,t]}\norm{\bP_{d}^{\perp}\cT(t-s)(S(s)\tilde{u})^{\otimes
                                         2}}.\label{eq:scov-convergence-rate-1}
\end{align}
Note that since $\tilde{u}\in V$ and $S(s)(V)\subseteq V$ for every $s\geq
0$, we have $\cT(t-s)(S(s)\tilde{u})^{\otimes 2}\in
\cV_{0}$ for every $s\leq t$, and we therefore conclude that
\begin{align*}
  \sup_{s\in[0,t]}\norm{\bP_{d}^{\perp}(\cT(t-s)S(s)\tilde{u})^{\otimes
                                         2})}&\leq
                                               \norm{\bP_{d}^{\perp}}_{\cL(\cV,\cH)}M_{T}\norm{\tilde{u}}_{V}^{2}M^{2}_{1}\E^{2t
                                               w},
\end{align*}
where we used that
$\norm{S(s)\tilde{u}}_{V}^{2}\leq\norm{\tilde{u}}_{V}^{2}M^{2}_{1}\E^{2t w}$ for the type $M_{1}\geq 0$ and growth bound $w\in\MR$ of the semigroup
$(S(t))_{t\geq 0}$ on $V$, i.e. $\norm{S(t)}_{\cL(V)}\leq M_{1}\E^{t w}$ for
$t\geq 0$. Hence, we conclude as in the proof of
Proposition~\ref{prop:existence-mild-Riccati} that for $\check{K}_{t}^{d}$ with  
\begin{align*}
  \check{K}_{t}^{d}=\big(\tilde{H}_{M}^{2}t\norm{\cT(t)}\norm{\mu(\cHpluso)}_{\cV}+\norm{\cT(t)}M^{2}_{1}\E^{2t
  w}\big)\norm{\bP_{d}^{\perp}}_{\cL(\cV,\cH)},
\end{align*}
we can bound the left-hand side
in~\eqref{eq:proof-convergence-rate-scov} by 
$\tilde{C}_{T}\norm{\bP_{d}^{\perp}}_{\cL(\cV,\cH)}(1+\norm{x})$ with
\begin{align*}
  \tilde{C}_{T}\df \E^{\tilde{L}^{(1)}_{M}T}\big(1+\tilde{L}_{M}^{(2)}T\big)(\E^{t\norm{B}_{\cL(\cH)}}\max(\tilde{H}_{M}^{2}T\norm{\mu(\cHpluso)}_{\cV},M_{1}^{2}\E^{Tw}),  
\end{align*}
which proves the asserted convergence
rate~\eqref{eq:stochastic-covariance-convergence-rate}.

