\section{Proof  of Lemma \ref{lem:initial_estimate}}\label{Proof_IE}
\begin{proof}
 The assertion for the conditional means $\condmean^1_0,\condmean^2_0$ and the entries $\condvar_0^{ij} $, $i,j=1,2$, of the conditional covariance matrix    follow immediately  from Assumption \ref{ass:dfc} saying that the DFCs $\dfc^1$ and $\dfc^2$ are independent with distribution  $\mathcal{N}(\dfcmean^i,\dfcvar^i)$, $i=1,2$. Further, the assumption 	 $Y_{0}^{3} = R_{2,0}^{-}=0$ and $ Y_{0}^{4}= V^-_0 =0$ implies zero conditional means $\condmean^3_0,\condmean^4_0$ and zero entries in third and fourth rows and columns of $\condvar_0$.	



Since  the total population size $N$ is assumed to be constant, the normalization property implies
\begin{align}\label{hY5}
Y_{0}^{5} = N - Y_{0}^{1} - Y_{0}^{2} - Y_{0}^{3} - Y_{0}^{4} - \sum_{i=1}^{10} Z_{0}^{i}.
\end{align}
Taking the conditional expectation given \( \mathcal{F}_{0}^{Z} \), we obtain
\[
\mathbb{E}[Y_{0}^{5} | \mathcal{F}_{0}^{Z}] = N - \mathbb{E}[Y_{0}^{1} | \mathcal{F}_{0}^{Z}] - \mathbb{E}[Y_{0}^{2} | \mathcal{F}_{0}^{Z}] - \sum_{i=1}^{10}Z_{0}^{i}.
\]
For the conditional covariance between \( Y_{0}^{1} \) and \( Y_{0}^{5} \) we use \eqref{hY5} and apply the bilinearity of the conditional covariance to obtain 
\begin{align}
\cov(Y_{0}^{1}, Y_{0}^{5} | \mathcal{F}_{0}^{Z}) &= \cov\Big(Y_{0}^{1}, N - Y_{0}^{1} - Y_{0}^{2} - \sum_{i=1}^{10} Z_{0}^{i} | \mathcal{F}_{0}^{Z}\Big)\\
&= -\cov(Y_{0}^{1}, Y_{0}^{1} | \mathcal{F}_{0}^{Z}) - \cov(Y_{0}^{1}, Y_{0}^{2} | \mathcal{F}_{0}^{Z}) - \sum_{i=1}^{10} \cov(Y_{0}^{1},Z_{0}^{i} | \mathcal{F}_{0}^{Z})\\
&=  -\var(Y_{0}^{1} | \mathcal{F}_{0}^{Z}) = -\dfcvar^1( Z_{0}^{1})^2,
\end{align}
where we have used the conditional independence of \( Y_{0}^{1} \) and \( Y_{0}^{2} \), and that $Z_{0}^{i}$ is  $\mathcal{F}_{0}^{Z}$-measurable, hence  $\cov(Y_{0}^{1},Z_{0}^{i} | \mathcal{F}_{0}^{Z})=0$.
The  expression for the conditional covariance between \( Y_{0}^{2} \) and \( Y_{0}^{5} \) follows analogously, that is 
$
\cov(Y_{0}^{2}, Y_{0}^{5} | \mathcal{F}_{0}^{Z}) = -\var(Y_{0}^{2} | \mathcal{F}_{0}^{Z}) = -\dfcvar^2( Z_{0}^{2})^2.
$

Finally, for the conditional variance of \( Y_{0}^{5} \) it follows from  \eqref{hY5} and the above results 
\[
\var(Y_{0}^{5} | \mathcal{F}_{0}^{Z}) = \var(Y_{0}^{1} | \mathcal{F}_{0}^{Z}) + \var(Y_{0}^{2} | \mathcal{F}_{0}^{Z}).
\]
Substituting $\var(Y_{0}^{i} | \mathcal{F}_{0}^{Z}) = \dfcvar^i( Z_{0}^{i})^2$, $i=1,2$,  gives 
$
\var(Y_{0}^{5} | \mathcal{F}_{0}^{Z}) = \dfcvar^1( Z_{0}^{1})^2 + \dfcvar^2( Z_{0}^{2})^2.
$   
\qed

\end{proof}
