\section{Ergodic theorems, Large deviations and Maximal large deviations}

We start with basic theorems in ergodic theory. 
\begin{definition}[Ergodic theorems]\ \par
    A fundamental Birkhoff's ergodic theorem says that if $\mu_{\mathcal{M}}$ is a probability measure, preserved by an ergodic dynamics $f:\mathcal{M} \to\mathcal{M}$, then almost surely for any function $\phi$ with $\int \phi d\mu_{\mathcal{M}}=0$,
\begin{equation*}\lim_{n\to \infty}\frac{\sum_{i \le n} \phi \circ f^i}{n}=0.  
\end{equation*}
\end{definition}

Equivalently, for any $\epsilon>0$, $\mu_\mathcal{M}$-a.s. $x \in \mathcal{M}$ there is $N=N_x>0$, such that 
\begin{equation*}
   \sup_{n\ge N} \Big|\frac{\sum_{i \le n}\phi \circ f^i(x)}{n}\Big|\le \epsilon.
\end{equation*}

Large deviations theory is concerned with probability of outliers in the convergence of averages of the values of observables along trajectories of dynamical systems, that is,
\begin{equation*}
    \mu_\mathcal{M}\Big(\Big| \frac{\sum_{i \le n}\phi \circ f^i}{n}\Big|\ge \epsilon\Big). 
\end{equation*}

 The paper \cite{vaientiadv} applied large deviations to obtain some geometric properties for certain smooth dynamical systems $f$, while in \cite{explicit}, the explicit estimates of constants in the upper bound of the error term in the large deviations principle were obtained.

If the dynamics is sufficiently strongly chaotic (e.g., if it has fast mixing rates or, in other words, correlations decay exponentially) and $\phi$ is sufficiently smooth, then there is a constant $C>0$, such that for any $n, N \ge 1$
\begin{equation*}
    \mu_\mathcal{M}\Big(\Big| \frac{\sum_{i \le n}\phi \circ f^i}{n}\Big|\ge \epsilon\Big) \approx e^{-Cn}, 
\end{equation*} and 
\begin{equation*}
    \mu_\mathcal{M}\Big(\sup_{n \ge N}\Big| \frac{\sum_{i \le n}\phi \circ f^i}{n}\Big|\ge \epsilon\Big) \approx \sum_{n\ge N}e^{-Cn} \approx e^{-CN}.
\end{equation*}

If the dynamics is weakly chaotic (i.e., slow mixing rates), then this estimate becomes weaker, \begin{equation*}
    \mu_\mathcal{M}\Big(\Big| \frac{\sum_{i \le n}\phi \circ f^i}{n}\Big|\ge \epsilon\Big) \precsim n^{-a} \text{ where }a>0.
\end{equation*}
(see \cite{melbourne09} for more details).

In this situation, in contrast with the case of the exponential estimate, a direct summation over $n$ does not give an analogous estimate 
\begin{equation*}
    \mu_\mathcal{M}\Big(\sup_{n \ge N}\Big| \frac{\sum_{i \le n}\phi \circ f^i}{n}\Big|\ge \epsilon\Big)\precsim N^{-a} \text{ where }a >0.
\end{equation*}

We call this type of estimate a \textbf{maximal large deviation}. 

One of the motivations to consider maximal large deviations is due to a rather typical approach (called an inducing method) in ergodic theory. This approach is usually aimed at finding a reference set $\Delta_0 \subsetneq \mathcal{M}$ and the first return time to it $R: \Delta_0 \to \mathbb{N}$, in order to prove some ``good" properties for the first return map $f^R: \Delta_0 \to \Delta_0$. Then this property is lifted to the original dynamics $f: \mathcal{M} \to \mathcal{M}$. In practice, this lifting technique relies on a quantitative estimate of the time $N$ in $\sup_{n\ge N} \frac{\sum_{i \le n}R \circ (f^R)^i}{n}$ (rather than $ \frac{\sum_{i \le N}R \circ (f^R)^i}{N}$). This is related to the presented below maximal large deviation approach.  

Let a transfer operators (Perron-Frobenius operator)  $P$ associated to $f$ is defined by the duality relations:
\begin{equation*}
    \int g \cdot P(h) d\mu_{\mathcal{M}}= \int g \circ f \cdot h d\mu_{\mathcal{M}} \text{ for all } h \in L^1(\mu_{\mathcal{M}})\text{, } g \in L^{\infty}(\mu_{\mathcal{M}}).
\end{equation*} 

Then we have the following.
\begin{theorem}[Maximal large deviations, see \cite{mldp}]\label{mld} \par
Suppose that $\phi\in L^{\infty}$ has zero mean, and there are constants $p\in \mathbb{N}, C_{\phi}>0, \beta \in (0, p)$ such that
\begin{equation*}
 ||P^n(\phi)||^p_p\le C_{\phi} n^{-\beta}  \text{ for any } n \ge 1.
\end{equation*} 

Then for any $\epsilon>0, N \ge 1$  \begin{equation*}
    \mu_\mathcal{M}\Big(\sup_{n \ge N}\Big| \frac{\sum_{i \le n}\phi \circ f^i}{n}\Big|\ge \epsilon\Big)\precsim_{\epsilon, p, \beta}\max\{||\phi||^{p}_{\infty}, C_{\phi}\}\cdot  ||\phi||^{p}_{\infty} \cdot N^{-\beta },
\end{equation*} and \begin{equation*}
    \Big|\Big|\sup_{n \ge N}\Big| \frac{\sum_{i \le n}\phi \circ f^i}{n}\Big|\Big|\Big|^{2p}_{2p}\precsim_{p, \beta}\max\{||\phi||^{p}_{\infty}, C_{\phi}\}\cdot  ||\phi||^{p}_{\infty} \cdot N^{-\beta}.
\end{equation*} 

In particular, if the function $\phi\in L^{\infty}$ satisfies the inequality $||P^n(\phi)||_1\le C_{\phi} n^{-\beta}$ for some $C_{\phi}>0$ and any $n \ge 1$, then for any $\epsilon>0$
     \begin{gather*}
     ||P^n(\phi)||^{1+\left \lceil \beta \right \rceil}_{1+\left \lceil \beta \right \rceil}\le C_{\phi} ||\phi||^{\left \lceil \beta \right \rceil}_{\infty} n^{-\beta},\\ 
     \mu_\mathcal{M}\Big(\sup_{n \ge N}\Big| \frac{\sum_{i \le n}\phi \circ f^i}{n}\Big|\ge \epsilon\Big)\precsim_{\epsilon,  \beta}\max\{||\phi||^{1+\left \lceil \beta \right \rceil}_{\infty}, C_{\phi} ||\phi||^{\left \lceil \beta \right \rceil}_{\infty}\}\cdot  ||\phi||^{1+\left \lceil \beta \right \rceil}_{\infty}  \cdot N^{-\beta }.
     \end{gather*}
\end{theorem}

Now we present applications to some concrete classes of dynamical systems. Denote by $d$ a Riemannian distance in $\mathcal{M}$, and by $\Leb$ a Riemannian volume form on $\mathcal{M}$. By $C^{1+}$ we denote the class of continuously differentiable maps with 
H\"older continuous derivatives. Let $f : \mathcal{M} \to \mathcal{M}$ be a piecewise $C^{1+}$-endomorphism of a Riemannian manifold $\mathcal{M}$.

\begin{definition}[Gibbs-Markov-Young (GMY) structures, see  \cite{Young2} or \cite{vaientiadv}]\label{GMY}\ \par 

Suppose that there exists a ball $\Delta_0\subset \mathcal{M}$,
a countable partition $\mathcal{P}$ (mod $0$) of $\Delta_0$ into topological balls $U$ with smooth boundaries, and a return time (not necessarily the first return time) function $R: \Delta_0 \to \mathbb{N}$, which is constant on each element of $\mathcal{P}$. We say that $f$ admits a Gibbs–Markov-Young (GMY) structure if the following properties hold:
\begin{enumerate}
    \item{Markov property:} for each $U\in \mathcal{P}$ and $R=R(U)$, $f^R: U\to \Delta_0$ is a $C^{1+}$-diffeomorphism (and, in particular, it is a bijection). Thus the induced map $F: \Delta_0 \to \Delta_0$, $F(x)=f^{R(x)}(x)$, is defined almost everywhere and satisfies a classical Markov property.
\item{Uniform expansion:} there exists $\rho\in (0,1)$ such that for almost all $x \in \Delta_0$ we have $||DF(x)^{-1}||\le \rho$. In particular the separation time $s(x,y)$, which is equal to the smallest integer $i\ge 0$ such that $F^i
(x)$ and $F^i
(y)$ lie in distinct elements of the partition $\mathcal{P}$, is defined and is  finite for almost all $x, y \in \Delta_0$.
\item{Bounded distortion:} there exists $C > 0$ such that for any two points $x,y \in \Delta_0$ with $s(x,y)\in [1,\infty) $ \begin{equation*}
    \Big|\frac{\det DF(x)}{\det DF(y)}-1\Big|\le C  \rho^{s(F(x),F(y))},
\end{equation*}where $\det DF$ is the Radon-Nikodym derivative of $F$ with respect to $\Leb$ on $\Delta_0$.
\end{enumerate}
\end{definition}

Theorem \ref{mld} implies the following corollary, see a proof in \cite{mldp}. 
\begin{corollary} \label{optimalmld}If $f$ admits  a Gibbs–Markov-Young structure, and $\Leb(x\in \Delta_0: R(x)>N)\approx N^{1+\beta}$ for some $\beta>0$, then there exists an invariant probability measure $\mu_{\mathcal{M}}$ and an open and dense set $H_0$ in the space of H\"older functions, such that for any zero mean function $\phi\in H_0$, and for any $\epsilon>0$,
\begin{equation*}
    \lim_{N\to \infty}\frac{\log \mu_{\mathcal{M}}\Big(\sup_{n \ge N}\Big| \frac{\sum_{i \le n}\phi \circ f^i}{n}\Big|\ge \epsilon\Big)}{\log N}=-\beta .
\end{equation*}
\end{corollary}


\section{Recurrences and Poisson Approximations}

The studies of Poisson approximations of the process of recurrences to small subsets in the phase spaces of chaotic dynamical systems are developed now into a large active area in the  dynamical systems theory. Another view at this type of problem is a subject of the theory of open dynamical systems where some positive measure subset $A$ of the phase space is named a hole, and hitting and escape through the hole processes are studied. The third view at this type of problems concerns statistics of extreme events (``record values") in the theory of random processes \cite{haydncmp, FFMA}. In this section we present some new advances in this area.

In a general set up, one picks a small measure subset $A$ in the phase space $\mathcal{M}$ of hyperbolic (chaotic) ergodic dynamical system and attempts to prove that in the limit, when the measure of $A$ approaches  zero, the corresponding process of recurrences to $A$ converges to the Poisson process. 

This area received an essential boost in L-S.Young papers \cite{Young1,Young2}, where a new general framework for analysis of statistical properties of hyperbolic dynamical systems was introduced. This approach employs representation of the phase space of a dynamical system as a tower (later called Young tower, Gibbs-Markov-Young tower, etc), which allow to study dynamics by analysing  recurrences to the base of this tower. Several developments of this method were proposed later, essentially all focused on the dynamical systems with weak hyperbolicity (slow decay of correlations). For such systems the method of inducing was employed, when the base of the tower is chosen as such subset of the phase space where the induced dynamics, generated by the recurrences to the base, is strongly hyperbolic. 


The main results (Theorems \ref{thm2} and \ref{thm}) in this section are dealing with convergence of a random process, generated by the measure preserving dynamics, to the functional Poisson law in the total variation (TV) norm. We also obtain estimates of the corresponding convergence rates in the following form. For almost every $z\in \mathcal{M}$,\begin{align}\label{equaintro}
   d_{TV}\left(\mathcal{N}^{r,z,T}, Poisson \right) \precsim_{T,z} r^{a},
\end{align}where $Poisson$ is a Poisson point process and $\mathcal{N}^{r,z,T}$ is a dynamical point process which counts a number of entrances by an orbit to a metric ball $B_{r}(z)$ with radius $r$ and the center $z$ in the phase space of a dynamical system during a time interval $[0,T]$ (see their definitions below).  The notation $\precsim_{T,z}$ means that a constant in (\ref{equaintro}) depends only on $z$ and $T$. 

\begin{definition}[Dynamical point processes]\label{dynamicptprocess}\ \par
Let $(\mathcal{M},d)$ be a Riemannian manifold (with or without boundaries, connected or non-connected, compact or non-compact), $d$ is the Riemannian metric on $\mathcal{M}$ and $B_{r}(z)$ is a geodesic ball in $\mathcal{M}$ with a radius $r$ and a center $z \in \mathcal{M}$. We assume that dynamics $f: (\mathcal{M},\mu_{\mathcal{M}}) \to (\mathcal{M}, \mu_{\mathcal{M}})$ is ergodic with respect to (w.r.t.) some invariant probability measure $\mu_{\mathcal{M}}$.


Let $T>0$. Consider a dynamical point process on $[0,T]$, so that for any $t \in [0,T]$ 
\[\mathcal{N}^{r,T, z}_{t}:=\sum_{i=0}^{ t/\mu_{\mathcal{M}}(B_r(z))} \mathbbm{1}_{B_r(z)} \circ f^i.\]

Thus the dynamical point process $\mathcal{N}^{r,T, z}$ is a random counting measure on $[0,T]$.

\end{definition}


\begin{definition}[Poisson point processes]\label{poisson}\ \par
For any $T>0$, we say that $Poisson$ is a Poisson point process on $[0,T]$ if
\begin{enumerate}
    \item $Poisson$ is a random counting measure on $[0,T]$.
    \item $Poisson(A)$ is a Poisson-distributed random variable for any Borel set $A \subseteq [0,T]$.
    \item If $A_1, A_2, \cdots, A_n \subseteq [0,T]$ are pairwise disjoint, then  $Poisson(A_1), \cdots, Poisson(A_n)$ are independent.
    \item $\mathbb{E}Poisson(A)=\Leb(A)$ for any Borel set $A\subseteq [0,T]$.
\end{enumerate}

\end{definition}

\begin{definition}[Total variation norms of point processes]\label{totalnorm}\ \par
For any $T>0$ consider the $\sigma$-algebra $\mathcal{C}$ on the space of point processes on $[0,T]$, defined as \begin{align}\label{sigmaalg}
\sigma \left\{\pi^{-1}_AB: A \subseteq [0,T],B \subseteq \mathbb{N}\right\},
\end{align}
where $A, B$ are Borel sets and
$\pi_A$ is an evaluation map defined on the space of counting measures, so that for any counting measure $N$
\[\pi_AN:=N(A).\]

Now we can define the total variation norm for the Poisson approximation of a dynamical point process as
\[d_{TV}\left(\mathcal{N}^{r,T,z},Poisson\right):=\sup_{C\in \mathcal{C}}\left|\mu_{\mathcal{M}}(\mathcal{N}^{r,T,z} \in C)-\mathbb{P}(Poisson \in C)\right|\]
\end{definition}
\begin{definition}[Poisson approximations for small holes with convergence rates]\label{convergencerate}\ \par
Suppose that for any $T>0$ there exists a constant $a>0$ s.t. for almost every  $z\in \mathcal{M}$
\[d_{TV}\left(\mathcal{N}^{r,T,z},Poisson\right) \precsim_{T,z} r^a \to 0.\]

Then $a$ is called a convergence rate of a Poisson approximation.
\end{definition}
\begin{remark}
The convergence rates imply that for any sub-interval $[T_1, T_2]\subseteq [0,T]$, \[\sup_{C\subseteq \mathbb{N}}\left|\mu(\mathcal{N}^{r,T,z}[T_1,T_2]\in C)-\mathbb{P}(Poisson[T_1,T_2] \in C)\right|\precsim_{T,z} r^a \to 0.\]
\end{remark}

We now turn to hyperbolic Gibbs-Markov-Young structures \cite{Young1, Young2}:

\begin{definition}[Hyperbolic Gibbs-Markov-Young structures]\label{gibbs}\ \par


Introduce at first several notions concerning hyperbolic dynamics $f$ on Riemannian manifolds  $(\mathcal{M},d)$.

\begin{enumerate}
    \item An embedded disk $\gamma^u$ is called an unstable manifold if for every $x,y \in \gamma^u$ 
    \[\lim_{n \to \infty}d\Big(f^{-n}(x), f^{-n}(y)\Big)=0\]
    \item An embedded disk $\gamma^s$ is called a stable manifold if for every $x,y \in \gamma^s$ 
    \[\lim_{n \to \infty}d\Big(f^{n}(x), f^{n}(y)\Big)=0\]
    \item $\Gamma^u:=\{\gamma^u\}$ is called a continuous family of $C^1$-unstable manifolds if there is a compact
set $K^s$, a unit disk $D^u$ in some $\mathbb{R}^n$ and a map $\phi^u: K^s \times D^u \to \mathcal{M}$ such that 
\begin{enumerate}
    \item $\gamma^u=\phi^u\left(\{x\}\times D^u\right)$ is an unstable manifold,
    \item $\phi^u$ maps $K^s \times D^u$ homeomorphically onto its image,
    \item $x \to \phi^u|_{\{x\} \times D^u}$ defines a continuous map from $K^s$ to $\Emb^1\left(D^u, \mathcal{M}\right)$, where $\Emb^1\left(D^u, \mathcal{M}\right)$ is the space of $C^1$-embeddings of $D^u$ into $\mathcal{M}$.
\end{enumerate}
\end{enumerate}



A continuous family of $C^1$-stable manifolds $\Gamma^s:=\{\gamma^s\}$ is defined similarly.


\item We say that a compact set $ \Lambda \subseteq \mathcal{M}$ has a
hyperbolic product structure if there exist  continuous families of stable manifolds $\Gamma^s:=\{\gamma^s\}$ and of unstable manifolds $\Gamma^u:=\{\gamma^u\}$ such that

\begin{enumerate}

    \item $\Lambda=\left(\bigcup \gamma^s\right) \bigcap \left(\bigcup \gamma^u\right)$,

    \item $\dim \gamma^s+\dim \gamma^u=\dim \mathcal{M}$,

    \item each $\gamma^s$ intersects each $\gamma^u$ at
    exactly one point,

    \item stable and unstable manifolds are transversal, and the angles between them are uniformly bounded away from 0.
\end{enumerate}

A subset $\Lambda_1 \subseteq \Lambda$ is called a s-subset if $\Lambda_1$ has a hyperbolic product structure and, moreover, the corresponding families of stable and unstable manifolds  $\Gamma^s_1$ 
and $\Gamma^u_1$ can be chosen so that  $\Gamma^s_1 \subseteq \Gamma^s$ and $\Gamma^u_1 = \Gamma^u$. 

Analogously, a subset $\Lambda_2 \subseteq \Lambda$
is called an $u$-subset if $\Lambda_2$ has a hyperbolic product structure and the families $\Gamma^s_2$
and $\Gamma^u_2$ can be chosen so that  $\Gamma^u_2 \subseteq \Gamma^u$ and $\Gamma^s_2 = \Gamma^s$.

For $x \in \Lambda$, denote by $\gamma^u(x)$ (resp. $\gamma^s(x)$) the element of $\Gamma^u$ (resp. $\Gamma^s$)
which contains $x$. Also, for each $n \ge 1$, 
denote by $\left(f^n\right)^u$ the restriction of the map $f^n$ to $\gamma^u$-disks, and by $\det D\left(f^n\right)^u$ denote the Jacobian of $\left(f^n\right)^u$.

We say that the set $\Lambda$ with  hyperbolic product structure has also a \textbf{hyperbolic Gibbs-Markov-Young structure} if  the following  properties are satisfied 

\begin{enumerate}
    \item  Lebesgue detectability:  there exists $\gamma \in \Gamma^u$ such that $\Leb_{\gamma}\left(\Lambda \bigcap \gamma\right) > 0$.
    \item Markovian property: there exist pairwise disjoint $s$-subsets $\Lambda_1,\Lambda_2, \cdots \subseteq \Lambda$ such that
    \begin{enumerate}
        \item $\Leb_{\gamma}\left(\Lambda \setminus \left(\bigcup_{i \ge 1}\Lambda_i\right)\right)=0$ on each $\gamma \in \Gamma^u$,
        \item for each $i \ge 1$ there exists $R_i \in \mathbb{N}$ such that $f^{R_i} (\Lambda_i)$ is an $u$-subset, and for all $x \in \Lambda_i$
        \[f^{R_i}\left(\gamma^s(x)\right) \subseteq \gamma^s\left(f^{R_i}(x)\right)\]
        and
    \[f^{R_i}\left(\gamma^u(x)\right) \supseteq \gamma^u(f^{R_i}(x)).\]
    \end{enumerate}

Define now a return time function $R : \Lambda \to \mathbb{N}$ and a return function $f^R: \Lambda \to \Lambda$, so that for each $i \ge 1$ 
\[R\big|_{\Lambda_i}=R_i
\text{ and }
f^R\big|_{\Lambda_i}=f^{R_i}\big|_{\Lambda_i}\]

Next, the separation time $s(x, y)$ for $x, y \in \Lambda$ is defined as
\[s(x,y):=\min \{n \ge 0: \left(f^R\right)^n(x) \text{ and } \left(f^R\right)^n(y) \text{ belong to different sets } \Lambda_i\}.\]

We also assume that there are constants $C > 1, \alpha > 0$ and $0 < \beta < 1$, which depend only on $f$ and $\Lambda$, such that the following conditions hold

\item Polynomial contraction on stable leaves. For any $\gamma^s \in \Gamma^s, x,y \in \gamma^s,  n \ge 1$,
\[ d\Big(f^n(x), f^n(y)\Big) \le Cn^{-\alpha}.\]

\item Backward polynomial contraction on unstable leaves. For any $ \gamma^u \in \Gamma^u, x,y \in \gamma^u,  n\ge 1$,
\[ d\Big(f^{-n}(x), f^{-n}(y)\Big) \le Cn^{-\alpha}.\]
\item Bounded distortion: for any $ \gamma \in \Gamma^u \text{ and } x, y \in \gamma \bigcap \Lambda_i$ for some $\Lambda_i$, 
\[\log \frac{\det D\left(f^R\right)^u(x)}{\det D\left(f^R\right)^u(y)} \le C  \beta^{s\left(f^R(x), f^R(y)\right)}.\]
\item Regularity of the stable foliation. For each $\gamma, \gamma'\in \Gamma^u$ denote 
\[\Theta_{\gamma, \gamma'}: \gamma' \bigcap \Lambda \to \gamma \bigcap \Lambda: x \to \gamma^s(x)\bigcap \gamma.\]

Then the following properties hold
\begin{enumerate}
    \item $\Theta_{\gamma, \gamma'}$ is absolutely continuous and for any $ x \in \gamma \bigcap \Lambda$
    \[\frac{d\left(\Theta_{\gamma, \gamma'}\right)_{*}\Leb_{\gamma'}}{d\Leb_{\gamma}}(x)=\prod_{n \ge 0} \frac{\det Df^u\left(f^n\left(x\right)\right)}{\det Df^u\left(f^n\left(\Theta_{\gamma, \gamma'}^{-1}x\right)\right)},\]
    \[ \frac{d\left(\Theta_{\gamma, \gamma'}\right)_{*}\Leb_{\gamma'}}{d\Leb_{\gamma}}(x)= C^{\pm 1},\]
    \item for any $x,y \in \gamma \bigcap \Lambda$ 
    \[\log \frac{\frac{d\left(\Theta_{\gamma, \gamma'}\right)_{*}\Leb_{\gamma'}}{d\Leb_{\gamma}}(x)}{\frac{d\left(\Theta_{\gamma, \gamma'}\right)_{*}\Leb_{\gamma'}}{d\Leb_{\gamma}}(y)} \le C  \beta^{s(x,y)}.\]

\end{enumerate}
\item Aperiodicity: $\gcd\left(R_i, i \ge 1\right)= 1$. 
   \item Decay rate of the return times $R$: there exist $\xi>1$ and $\gamma\in \Gamma^u$ such that \begin{align*}
       \Leb_{\gamma}\left(R>n\right) \le Cn^{-\xi}.
   \end{align*}
\end{enumerate}

\textbf{SRB measures}: 
Let the dynamics $f: \mathcal{M} \to \mathcal{M}$ has hyperbolic Gibbs-Markov-Young structure. It was proved in \cite{Young2, Young1} that there exists  an ergodic probability measure $\mu_{\mathcal{M}}$  such that for any unstable manifold $\gamma^u$ (including $\Gamma^u$) we have $\mu_{\gamma^u} \ll \Leb_{\gamma^u}$, where $\mu_{\gamma^u}$ is the conditional measure of $\mu_{\mathcal{M}}$ on an unstable manifold $\gamma^u$. Such measure $\mu_{\mathcal{M}}$ is called Sinai-Ruelle-Bowen measure (SRB measure).


\end{definition}

\begin{assumption}[Geometric regularities]\label{geoassumption}\ \par
Assume that $f: \mathcal{M}\to \mathcal{M}$ has the hyperbolic Gibbs-Markov-Young structure, as described in Definition \ref{gibbs}, and
\begin{enumerate}

   \item $f$ is bijective and a local $C^1$-diffeomorphism on $\bigcup_{i \ge 1} \bigcup_{0 \le j < R_i} f^j(\Lambda_i)$.
   \item The following limit 

  \[ \dim_H\mu_{\mathcal{M}}:=\lim_{r \to 0} \frac{\log \mu_{\mathcal{M}}(B_r(z))}{\log r}\]

exists  for almost every  $z\in \mathcal{M}$. Then  $dim_H\mu_{\mathcal{M}}$ is  called a Hausdorff dimension of the measure $\mu_{\mathcal{M}}$.

 \item $\alpha \dim_H\mu_{\mathcal{M}}>1$, where $\alpha$ is defined in Definition \ref{gibbs}.
\end{enumerate}
\end{assumption}



\begin{assumption}[The first returns \& interior assumptions on $\Lambda$]\label{assumption}\ \par

Assume that $f: \mathcal{M}\to \mathcal{M}$ has the hyperbolic Gibbs-Markov-Young structure, and there are constants $C>1$ and $\beta\in (0,1)$ (the same as in Definition \ref{gibbs}) such that

\begin{enumerate}   
    \item $R: \Lambda \to \mathbb{N}$ is the first return time and $f^R: \Lambda \to \Lambda$ is the first return map for $\Lambda$.

    This implies that $f^R$ is bijective.
    \item  for any $\gamma \in \Gamma^s, \gamma_1 \in \Gamma^u, x, y \in \gamma \bigcap \Lambda, x_1, y_1 \in \gamma_1 \bigcap \Lambda $,
    \[d\Big(\left(f^R\right)^n(x), \left(f^R\right)^n(y)\Big) \le C \beta^n,\]
    and
    \[d\Big(\left(f^R\right)^{-n}(x_1), \left(f^R\right)^{-n}(y_1)\Big) \le C \beta^n  d(x_1,y_1).\]

    \item $\mu_\mathcal{M}\{\interior{(\Lambda)}\}>0$ and $\mu_\mathcal{M}(\partial \Lambda)=0$, where \begin{align*}
        \interior{\Lambda}:=\left\{x \in \Lambda: \text{ there exists } r_x>0 \text{ s.t. } \mu_\mathcal{M}\left(B_{r_x}(x)\setminus \Lambda\right)=0 \right\},\quad \partial \Lambda:=\Lambda \setminus \interior{\Lambda}. 
    \end{align*}    

    In other words, $x \in \interior{\Lambda}$ if and only if $x \in \Lambda$ and there is a small ball $B_{r_x}(x)$ s.t. $B_{r_x}(x) \subseteq \Lambda$ $\mu_\mathcal{M}$-almost surely. 
\end{enumerate}

\end{assumption}

We formulate now the first result in this section.

\begin{theorem}[Convergence rates for Poisson laws \Romannum{1}, see \cite{Sucmp}]\label{thm1}\ \par
Assume that the dynamics $f: (\mathcal{M}, \mu_{\mathcal{M}}) \to (\mathcal{M}, \mu_{\mathcal{M}})$ has a first return hyperbolic Gibbs-Markov-Young structure (see Definition \ref{gibbs}) and satisfies Assumptions \ref{geoassumption} and \ref{assumption}. Then for any $T>0$ the following results hold 

\begin{enumerate}
    \item $\dim_H\mu_\mathcal{M} \ge \dim {\gamma}^u$ 
    \item if either $\alpha> \frac{2}{\dim \gamma^u}-\frac{1}{\dim_H \mu}$ or  $\mu_{\mathcal{M}} \ll \Leb_{\mathcal{M}}$ with $\frac{d\mu_\mathcal{M}}{d\Leb_{\mathcal{M}}} \in L^{\infty}_{loc}(\mathcal{M})$, then for almost every $z \in \mathcal{M}$
    \[d_{TV}\left(\mathcal{N}^{r,z,T}, Poisson\right) \precsim_{T,\xi,z} r^{a},\]
    where a computable constant $a>0$ depends on $\xi>1$, $\dim_H \mu_{\mathcal{M}}, \dim \gamma^u $ and $\alpha$, but it does not depend on $z\in \mathcal{M}$. 

\end{enumerate}

\end{theorem}

\begin{definition}[Induced measurable partitions]\label{mpartition}\ \par
We say that a probability measure $\mu_\mathcal{M}$ for the dynamics $f: \mathcal{M} \to \mathcal{M}$ has an induced measurable partition if there are constants $\beta \in (0,1), C>1$ (the same as in the Definition \ref{gibbs}) and $b>0$ such that
\begin{enumerate}
    \item There exists a subset $X \subseteq \mathcal{M}$ with $\mu_{\mathcal{M}} \{\interior{(X)}\}>0$, $\mu_{\mathcal{M}}(\partial X)=0$.
    \item The subset $X$ has a measurable  partition $\Theta:=\{\gamma^u(x)\}_{x \in X}$ (which could be different from $\Gamma^u$), such that the elements of $\Theta$ are  disjoint  connected unstable manifolds, so that $\mu_{\mathcal{M}}$-almost surely $X=\bigsqcup_{x \in X} \gamma^u(x)$ and for any function $g$
    \[\mu_{X}(g)=\int_X \mu_{\gamma^u(x)}(g) d\mu_X(x),\]
    where $\mu_X:=\frac{\mu_\mathcal{M}|_{X}}{\mu_\mathcal{M}(X)}$ and $\mu_{\gamma^u(x)}$ is the conditional probability induced by $\mu_{X}$ on $\gamma^u(x)\in \Theta$.
    \item Each $\gamma^u\in \Theta$ is (at least $C^1$) smooth.
    \item All $\gamma^u\in \Theta$ have uniformly bounded sectional curvatures and the same dimensions.
    \item For any $\epsilon \in (0,1)$\[\mu_X \{x \in X: |\gamma^u(x)|< \epsilon\}\le C  \epsilon^b,\] where $|\gamma^u(x)|$ is the radius of the largest inscribed geodesic ball  in $\gamma^u(x) \in \Theta$, where a 
    geodesic ball is defined with respect to the distance   $d_{\gamma^u(x)}$ on $\gamma^u(x)$, induced by the Riemannian metric. This property implies that almost every $\gamma^u(x)\in \Theta$ is non-degenerate, i.e., $|\gamma^u(x)|>0$ for almost every $x\in X$.
    \item For almost every point $x\in X$ we have $\mu_{\gamma^u(x)} \ll \Leb_{\gamma^u(x)}$, $\mu_{\gamma^u(x)}\left(\gamma^u(x)\right)>0$, and for any $y, z \in\gamma^u(x)$
   \[\frac{d\mu_{\gamma^u(x)}}{d\Leb_{\gamma^u(x)}}(y)=C^{\pm 1}  \frac{d\mu_{\gamma^u(x)}}{d\Leb_{\gamma^u(x)}}(z).\]
    \item Denote by $\overline{R}$ the first return time to $X$ for $f$. Then the first return map $f^{\overline{R}}: X \to X$ has an exponential u-contraction, i.e., for any $\gamma^u \in \Theta, x,y \in \gamma^u, n \ge 1$
    \[d\Big(\left(f^{\overline{R}}\right)^{-n}(x),\left(f^{\overline{R}}\right)^{-n}(y)\Big) \le C \beta ^n d(x,y),\]
    and an exponential decay of correlations, i.e., for any $h \in \Lip(X)$\begin{align*}
        \left|\int h \circ \left(f^{\overline{R}}\right)^n  h d\mu_{X}-\left(\int h d\mu_X\right)^2\right|\le C\beta^n ||h||^2_{\Lip}. 
    \end{align*}
\end{enumerate}
\end{definition}

Now we can formulate the second result in this section. 

\begin{theorem}[Convergence rates for the Poisson laws  \Romannum{2}, \cite{Sucmp}]\label{thm2}\ \par
Assume that the dynamics $f: (\mathcal{M}, \mu_{\mathcal{M}}) \to (\mathcal{M}, \mu_{\mathcal{M}})$ has the hyperbolic Gibbs-Markov-Young structure (see Definition \ref{gibbs}), satisfies the Assumption \ref{geoassumption}, and $\mu_\mathcal{M}$ has an induced measurable partition (see Definition \ref{mpartition}). Then for any $T>0$, the following results hold.

\begin{enumerate}
    \item $\dim_H \mu_{\mathcal{M}} \ge \frac{ b}{b+\dim \gamma^u} \dim \gamma^u$ and 
    \item if either $\alpha>  \frac{2}{\dim \gamma^u} \frac{b+\dim \gamma^u}{b}-\frac{1}{\dim_H \mu_{\mathcal{M}}} $ or  $\mu_{\mathcal{M}} \ll \Leb_{\mathcal{M}}$ and $\frac{d\mu_{\mathcal{M}}}{d\Leb_{\mathcal{M}}} \in L^{\infty}_{loc}(\mathcal{M})$, then for almost every (a.e.) $z \in \mathcal{M}$,
    \[d_{TV}\left(\mathcal{N}^{r,z,T}, Poisson\right) \precsim_{T, \xi, z,b} r^{a},\]
    where a constant $a>0$ depends on $\xi>1$, $\dim_H \mu_{\mathcal{M}}, \dim \gamma^u, b$ and $\alpha$, but it does not depend on $z\in \mathcal{M}$. 
\end{enumerate}

\end{theorem}

We will consider now some applications of the above Theorems.
\subsection{Intermittent solenoids}\label{appsolenoid}
Following \cite{Alves} let $\mathcal{M}=S^1 \times \mathbb{D}$, $f_{\gamma}(x,z)=(g_{\gamma}(x), \theta  z+e^{2\pi i x}/2)$, where $g_{\gamma}: S^1 \to S^1$ is a continuous map of degree $d\ge 2$ and $\gamma \in (0, +\infty)$ such that 
\begin{enumerate}
    \item $g_{\gamma}$ is $C^2$ on $S^1 \setminus \{0\}$ and $Dg_{\gamma}>1$ on $S^1 \setminus \{0\}$,
    \item $g_{\gamma}(0)=0, Dg_{\gamma}(0+)=1$ and  $xD^2g_{\gamma}(x) \sim x^{\gamma}$ for sufficiently small positive $x$,
    \item $Dg_{\gamma}(0-)>1$,
    \item $\theta>0$ is so small that $\theta  ||Dg_{\gamma}||_{\infty}< 1-\theta$.
\end{enumerate}

By Theorem \ref{thm1} we have the following
\begin{corollary}\label{fplsolenoid}
Poisson limit laws  hold for $f_{\gamma}$ for any $\gamma \in (0,1)$ with convergence rates  (\ref{equaintro}) . 
\end{corollary}



\subsection{Axiom A attractors}\label{appA}

It was well-known that for Axiom A attractors $\Sigma \subsetneq \mathcal{M}$ with $\dim \gamma^u=1$ the Poisson limit laws hold. We will show that conditions on $\dim_H\mu$ and $\dim \gamma^u$ can be dropped. 

\begin{definition}[Axiom A attractors]\ \par

Let $f : \mathcal{M} \to  \mathcal{M}$ be a  $C^2$-diffeomorphism. A compact set $\Sigma \subseteq \mathcal{M}$ is called an Axiom A attractor
if 
\begin{enumerate}
    \item There is a neighborhood $U$ of $\Sigma$, called its basin, such that $f^n(x) \to \Sigma$ for every $x \in U$.
\item The tangent bundle over $\Sigma$ is split into $E^u \oplus E^s$,  where $E^u$ and $E^s$ are $df$-invariant subspaces. 
\item $df|_{E^u}$ is uniformly expanding, and $df|_{E^s}$ is uniformly contracting.
\item $f: \Sigma \to \Sigma$ is topologically mixing.
\end{enumerate}
\end{definition}

The support of the SRB measure $\mu_{\mathcal{M}}$ is $\Sigma$. Applying now Theorem \ref{thm1} we obtain the following.

\begin{corollary}\label{axiomfpl}
Poisson limit laws hold for Axiom A attractors with convergence rates  (\ref{equaintro}).
\end{corollary}


\subsection{H\'enon attractors}\label{henon}

The Poisson limit laws for certain H\'enon attractors (see \cite{Young1}) have been proved in \cite{collet}. However, convergence rate for this class of dynamical systems was obtained  in a weaker form. A stronger rate of convergence  was derived (see \ref{equaintro}) by using Theorem \ref{thm2}.


\begin{corollary}\label{fplhenon}
Poisson limit laws with convergence rates (\ref{equaintro}) hold for H\'enon attractors which can be modelled by Young towers. 
\end{corollary}

\subsection{Billiards}
\begin{definition}[Billiard tables, billiard maps and phase spaces]\label{billiarddef} \par
We consider a billiard in a two-dimensional region $Q\subseteq \mathbb{R}^2$ (called a billiard table) with a piece-wise smooth (of class $C^3$) boundary $\partial Q$. Each smooth piece has a uniformly bounded curvature. The boundary $\partial Q$ is equipped with a field of inward unit normal vectors $n(q), q \in \partial Q$. 

A billiard is a dynamical system generated by the motion of a point
particle with the unit velocity inside the region $Q$, and being reflected from its
boundary according to the law ``the angle of incidence equals the angle of
reflection". It means that upon reflection the tangent component of the
velocity remains the same, while the normal component changes its sign
according to the rule $v_{+}=v_{-}-2\langle n(q), v_{-}\rangle n(q)$, where $v_{+}$ (resp. $v_{-}$) is the velocity of the particle immediately after (resp. before) reflection.

The phase space of a billiard is the restriction of the unit tangent
bundle of $\mathbb{R}^2$ to $Q$. We will use the standard notation for phase points $x=(q, v)$, where $q$ is the point of the configuration space $Q$ and $v$ is the unit velocity vector. The billiard preserves the Liouville measure $d\nu:=dq dv$ where $dq$ and $dv$ are Lebesgue measures on $Q$ and on the unit
one-dimensional sphere respectively. The corresponding flow will be denoted by $\{S^t\}$. It is customary for billiard-type systems to study instead of $\{S^t\}$ a
dynamical system with discrete time, which is called a billiard map $f$. Denote \[\mathcal{M}=\{x=(q, v), q \in \partial Q, \langle v, n(q)\rangle >0\}.\]  For $x=(q, v) \in \mathcal{M}$ let $\tau (x)$ be
the first positive moment of reflection of the billiard
orbit defined by $x$ off the boundary. Then the billiard map is defined by $f(x)=(q', v')=S^{\tau}
x$, so that $q'$ is the point of
the next reflection and $v'$ is the outcoming velocity vector at that point. We call $\mathcal{M}$ a phase space of the billiard map $f$.

Due to the structure of $\partial Q$,  the set of singular points of the boundary $\partial Q$ has measure zero. The angle $\phi$ of the velocity vector $v$ varies from $-\pi/2$ to $\pi/2$ at any regular point $q \in \partial Q$.  Hence $\mathcal{M}=\partial Q \times [-\pi/2,\pi/2]$ almost surely. In what follows we always identify $\mathcal{M}$ with $\partial Q \times [-\pi/2,\pi/2]$, and denote the phase point $x\in \mathcal{M}$ by $(q, \phi) \in \partial Q \times [-\pi/2,\pi/2]$ throughout this subsection.

The phase space  $\mathcal{M}=\partial Q \times [-\pi/2,\pi/2]$ is endowed with a natural Riemannian metric $d_{\mathcal{M}}$ and Riemannian volume $\Leb_{\mathcal{M}}$. The billiard map $f$ preserves the measure
\[d\mu_{\mathcal{M}}:=(2\Leb_{\partial Q} \partial Q)^{-1}\cos \phi d\phi dq=(2\Leb_{\partial Q} \partial Q)^{-1}\cos \phi \Leb_{\mathcal{M}},\]where $dq$ is the one-dimensional Lebesgue measure on the boundary $\partial Q$ and
$d\phi$ is the one-dimensional Lebesgue (uniform) measure on $[-\pi/2,\pi/2]$. 
\end{definition}

Before presenting the results, we introduce some more definitions.


\begin{definition}[An induced system]\label{inducesystem}\ \par
Suppose that there is a fixed subset $X\subseteq \mathcal{M}$ with $\Leb_{\mathcal{M}}(X)>0$. The first return time to $X$ is denoted as $R: X\to \mathbb{N}$. We assume that $X$ can be partitioned into countably many connected pieces
\begin{equation}\label{parition}
    X=\bigcup_{i\ge 1} X_i,
\end{equation} so that $R$ is constant on each $X_i$, and  \[\Leb_{\mathcal{M}} (\partial X_i)=0,\quad \interior{X_i} \bigcap \interior{X_j}=\emptyset \text{ for } i \neq j.\]

The first return time $R$ induces the first return map  $f^R: X \to X$ and a new dynamical system $(X, f^R)$.

\end{definition}
\begin{definition}[Singularities and (un)stable manifolds]\label{unstablemfd} \par
 Denote by $\mathbb{S}\subseteq X$ the singularity set for $f^R$. The set $\mathbb{S}$ has zero Lebesgue measure, and $\mathbb{S}^c \subseteq X$ consists of countably many open connected components. Unstable (resp. stable) manifolds are connected components of $(\bigcup_{i \ge 0}(f^R)^{i}\mathbb{S})^c$ (resp. $(\bigcup_{i \ge 0}(f^R)^{-i}\mathbb{S})^c$). A closed and connected part of the unstable (resp. stable) manifold will be called an unstable (resp. stable ) disk. We denote each unstable (resp. stable) manifold/disk by $\gamma^u$ (resp. $\gamma^s$), and its tangent vectors by $v^u$ (resp. $v^s$).
\end{definition}

\begin{remark}\label{singular}
The singularity set $\mathbb{S}$ consists of the points in $X $ which are not ``well-behaved". It includes the discontinuities and the points where the map $f^R$ is not differentiable. (It may also include other points in $X$ with some ``bad" properties).
\end{remark}
\begin{definition}[Chernov-Markarian-Zhang (CMZ) structures]\label{cmz}\ \par
We say that an induced system $(X, f^R)$ in Definition \ref{inducesystem} is a CMZ structure on $(\mathcal{M}, f)$ if there are constants $C>0$ and $\beta \in (0,1)$ such that the following conditions hold
\begin{enumerate}
    \item Hyperbolicity. For any $n\in \mathbb{N}$, $v^u$ and $v^s$,\begin{align*}
        |D(f^R)^n v^u|\ge C\beta^{-n} |v^u|, \quad  |D(f^R)^{n} v^s|\le C\beta^n |v^s|,
    \end{align*}where $|\cdot|$ is the Riemannian metric induced from $\mathcal{M}$ to (un)stable manifolds.
    \item SRB measures and u-SRB measures. The conditional probability measure $\mu_X:=\frac{\mu_{\mathcal{M}}|_X}{\mu_{\mathcal{M}}(X)} \ll \Leb_{X}$ with $\frac{d\mu_X}{d\Leb_X}\in L^{\infty}$ and $\frac{d\mu_X}{d\Leb_X}>0$ $\Leb_X$-a.s. on $X$. Moreover, conditional distributions on $\gamma^u$ (say $\mu_{\gamma^u}$) are absolutely continuous w.r.t. Lebesgue measure $\Leb_{\gamma^u}$ on $\gamma^u$.
    \item Distortion bounds. Let $d_{\gamma^u}(\cdot, \cdot)$ be the distance measured along $\gamma^u$. By $\det D^uf^R$ we denote the Jacobian of $Df^R$ along the unstable manifolds. Then, if $x, y\in X$ belong to a $\gamma^u$, and $(f^R)^n$ is $C^2$-smooth on $\gamma^u$, then the following relation holds
    \begin{align*}
        \log \frac{\det D^u(f^R)^n(x)}{\det D^u(f^R)^n(y)}\le \psi\left[d_{\gamma^u}\Big((f^R)^nx,(f^R)^ny\Big)\right],
    \end{align*}where $\psi(\cdot)$ is some function, which does not depend on $\gamma^u$, and $\lim_{s\to 0^+}\psi(s)=0$.
    \item Bounded curvatures. The curvatures of all $\gamma^u$ are uniformly
bounded by $C$.
\item Absolute continuity. Consider a holonomy map $h: \gamma^u_1 \to \gamma^u_2$,  which maps a point $x \in \gamma^u_1$ to the point $h(x)\in \gamma^u_2$, such that both $x$ and $h(x)$ belong to the same $\gamma^s$. We assume that the holonomy map satisfies the following relation \begin{align*}
    \frac{\det D^u(f^R)^n(x)}{\det D^u(f^R)^n\big(h(x)\big)}=C^{\pm 1} \text{ for all }n \ge 1 \text{ and }x\in \gamma^u_1,
\end{align*}
\item Growth lemmas. For any
sufficiently small $\delta>0$ and for any disk on a $C^1$-smooth unstable manifold  $\gamma^u$ with $\diam \gamma^u \le \delta_0$ denote by $U_{\delta} \subseteq \gamma^u$ a $\delta$-neighborhood of the subset $\gamma^u \bigcap \bigcup_{0\le i \le N}(f^R)^{-i}\mathbb{S}$ within the set $\gamma^u$. Then there exist $N \in \mathbb{N}$, sufficiently small $\delta_0>0$ and
constants  $ \kappa, \sigma > 0$ which satisfy the following condition. There exists an open subset $V_{\delta} \subseteq \gamma^u \setminus U_{\delta}$, such that $\Leb_{\gamma^u}\big(\gamma^u \setminus (U_{\delta}\bigcup V_{\delta})\big)=0$, and for any $\epsilon >0$ \begin{gather*}
    \Leb_{\gamma^u}(r_{V_{\delta},N}<\epsilon)\le 2\epsilon \beta+\epsilon C \delta_0^{-1} \Leb_{\gamma^u} (\gamma^u),\\
    \Leb_{\gamma^u}(r_{U_{\delta},0}< \epsilon)\le C \delta^{-\kappa} \epsilon,\\
    \Leb_{\gamma^u}(U_{\delta})\le C \delta^{\sigma},
\end{gather*}where $r_{U_{\delta},0}(x):=d_{\gamma^u}(x, \partial U_{\delta})$, $r_{V_{\delta}, N}(x):=d_{(f^R)^N\gamma^u}\big((f^R)^Nx, \partial (f^R)^NV_{\delta}(x)\big)$, and $V_{\delta}(x)$ is a connected component of $V_{\delta}$, which contains $x$.


\item Finiteness: $\int R d\mu_X< \infty$.
\item Mixing: $\gcd \{R\}=1$.

\end{enumerate}

\end{definition}

\begin{remark}
 In the growth lemmas a positive integer $N$ is usually chosen as a sufficiently large number.The conditions that $\gcd{R}=1$ and K-mixing of $f^R$ guarantee that $f$ is also K-mixing.
\end{remark}

Consider now the first return tower \begin{align*}
    \Delta:=\{(x,n)\in X \times \{0,1,2,\cdots\}: n < R(x)\}.
\end{align*}

Dynamics $F: \Delta \to \Delta$ is defined as $F(x, n)=(x, n+1)$ if $n+1\le R(x)-1$ and $F(x,n)=(f^Rx, 0)$ if $n=R(x)-1$. The projection $\pi:\Delta \to \mathcal{M}$ is defined by $\pi(x,n):=f^n(x)$ as $\pi \circ F=f \circ \pi$. Finally we introduce projections $\pi_{X}: \Delta \to X$ and $\pi_{\mathbb{N}}: \Delta \to \mathbb{N}_0$, so that for any $(x,n) \in \Delta$ \begin{equation}\label{projections}
    \pi_{X}(x,n)=x,\quad \pi_{\mathbb{N}}(x,n)=n.
\end{equation}

Extend now $\mu_X$ from $X$ to $\Delta$ as \begin{align*}
    \mu_{\Delta}:=(\int R d\mu_X)^{-1}\sum_{j}(F^j)_{*}\big(\mu_X|_{\{R>j\}}\big),
\end{align*} which reproduces the invariant probability measure on $\mathcal{M}$ \begin{align*}
\mu_{\mathcal{M}}=(\pi)_{*}\mu_{\Delta}.  \end{align*}

We identify $\Delta_0:=(X \times \{0\})\bigcap \Delta$ with $X$, $\mu_{\Delta_0}$ with $\mu_X$ and $F^R$ with $f^R$. Therefore $\pi: X \to X$ is the identity map.

Note that $\pi:\Delta \to \mathcal{M}$ is bijective. Thus $(\Delta,F)$ is identical to $(\mathcal{M},f)$, and $(X, f^R)=(\Delta_0, F^R)$ is a CMZ structure on $(\Delta, F)$.


\begin{remark}\ \par
\begin{enumerate}
    \item If $R=1$, then $X=\mathcal{M}$, and thus $(\mathcal{M}, f, \mu_{\mathcal{M}})$ has a CMZ structure.
    \item It follows from \cite{Chernovjsp, CZnon} that $(X, f^R, \mu_X)$ can be modelled by a hyperbolic Young tower \cite{Young1}.
    \item $(\mathcal{M}, f, \mu_{\mathcal{M}})$ is a K-system (and therefore mixing) because of the condition that $f^R$ is K-mixing and $\gcd \{R\}=1$.
\end{enumerate}
\end{remark}
\begin{definition}[Holes and dynamical point processes]\label{dynamicalpointprocess} \par
Throughout this subsection, a hole within the boundary $\partial Q$ is an open disk $B_{r}(q)$ with radius $r$ and the center at a regular point $q \in \partial Q$ of the boundary of a billiard table. 

Similar to Definition \ref{dynamicptprocess}, define now a different dynamical point process $\mathcal{N}^{r,q}$ on $\mathbb{R}^{+}\bigcup\{0\}$. For any measurable $A\subseteq \mathbb{R}^{+}\bigcup\{0\}$, and any $x \in \mathcal{M}$. \begin{align*}
    \mathcal{N}^{r,q}(x)(A):&=\#\{i\ge 0: f^i(x) \in B_r(q) \times [-\pi/2,\pi/2], \quad i \cdot \mu_{\mathcal{M}}\big(B_r(q) \times [-\pi/2,\pi/2]\big) \in A\}\\
    &=\sum_{i \cdot \mu_{\mathcal{M}}(B_r(q)\times [-\pi/2,\pi/2])\in A}\mathbbm{1}_{B_r(q)\times [-\pi/2,\pi/2]}\circ f^i(x).
\end{align*}

We will usually drop the symbol $x$ and write 
 \begin{align*}
    \mathcal{N}^{r,q}(A)=\sum_{i \cdot \mu_{\mathcal{M}}(B_r(q)\times [-\pi/2,\pi/2])\in A}\mathbbm{1}_{B_r(q)\times [-\pi/2,\pi/2]}\circ f^i.
\end{align*}

By using $\mu_{\mathcal{M}}:=(\pi)_{*}\mu_{\Delta}$, we get 
 \begin{align*}
    \mathcal{N}^{r,q}(A)=\sum_{i \cdot \mu_{\Delta}(A_r)\in A}\mathbbm{1}_{A_r}\circ F^i,
\end{align*}where $A_{r}:=\pi^{-1}(B_r(q)\times [-\pi/2,\pi/2])$.
\end{definition}
\begin{remark}
Following the theory of point processes  we have that 
\[\mathcal{N}^{r,q}(x)=\sum_{i\ge 0: f^i(x) \in B_r(q) \times [-\pi/2,\pi/2]} \delta_{i\cdot \mu_{\mathcal{M}}(B_r(q)\times [-\pi/2, \pi/2]) },\] where $\delta$ is a Dirac measure. Hence, $\mathcal{N}^{r,q}$ is a random counting measure, e.g., $\mathcal{N}^{r,q}(x)[0,1]$ counts the number of $i \in [0, \frac{1}{\mu_{\mathcal{M}}\{B_r(q)\times [-\pi/2, \pi/2]\}}]$, such that $f^i(x)$ belongs to $B_r(q)\times [-\pi/2, \pi/2]$. $B_r(q)\times [-\pi/2, \pi/2]$ is a large hole in the phase space $\mathcal{M}$.
\end{remark}



\begin{definition}[Poisson approximations for large holes]\label{pdef} \par
We say that $\mathcal{N}^{r,q} \to_d Poisson$ (see Definition \ref{poisson}) if  $\mathcal{N}^{r,q}g \to_d Poisson(g)$ for any $g\in C^{+}_c(\mathbb{R}^+\bigcup\{0\})$, i.e.,
\begin{align*}
    \lim_{r\to 0}\int \exp{(-t\cdot  \mathcal{N}^{r,q}g)}d\mu_{\mathcal{M}}=\int \exp{[-t\cdot Poisson(g)]}d\mathbb{P} \text{ for all }t>0,
\end{align*} where $C^{+}_c(\mathbb{R}^+\bigcup \{0\})$ is the space consisting of positive continuous functions with a compact support, defined on $[0,\infty)$.

This is equivalent to the relation \begin{align*}
    (\mathcal{N}^{r,q}I_1,\mathcal{N}^{r,q}I_2, \cdots, \mathcal{N}^{r,q}I_k) \to_d (Poisson(I_1), Poisson(I_2), \cdots, Poisson(I_k)) 
\end{align*}for any $k \in \mathbb{N}$ and any bounded intervals $I_1, \cdots I_k\subseteq{R}^+\bigcup\{0\}$.

In other words, the limit distribution of $\mathcal{N}^{r,q}$ is Poissonian, when the disk $B_r(q)$ shrinks to a regular point on the boundary $\partial Q$ of a billiard table.

\end{definition}

\begin{remark}
    If $I_1,\cdots, I_k$ are restricted inside an interval $[0,T]$, the convergence in this definition is equivalent to the  $d_{TV}$-convergence in Definition \ref{convergencerate} without convergence rates.
\end{remark}

\begin{definition}[Sections and quasi-sections]\ \par
Recall that $\pi_X: \Delta \to X $ is defined as $\pi_X(x,n)=x$. We say that $B_r(q) \times [-\pi/2, \pi/2]\subseteq \mathcal{M}$ is a section if $\pi_X: \pi^{-1} \big(B_r(q) \times [-\pi/2, \pi/2]\big) \to X$ is injective for any sufficiently small $r>0$. Further, $B_r(q) \times [-\pi/2, \pi/2] \subseteq \mathcal{M}$ is a quasi-section if for any sufficiently small $r>0$ there is a measurable set $S_r \subseteq B_r(q) \times [-\pi/2, \pi/2]$, such that  $\mu_{\mathcal{M}}[\big(B_r(q) \times [-\pi/2, \pi/2]\big)\setminus S_r]=o\big(\mu_{\mathcal{M}}\big[B_r(q) \times [-\pi/2, \pi/2]\big]\big)$,  and $\pi_X: \pi^{-1} S_r \to X$ is injective. In this case, we also refer to $S_r$ as a section in $B_r(q) \times [-\pi/2, \pi/2]$.  
\end{definition}
\begin{remark}\label{remarkonsection}
In applications to two-dimensional billiards, $B_r(q)\times [-\pi/2,\pi/2]$ is a strip in $\mathcal{M}$, and $ B_r(q)\times [-\pi/2,\pi/2]\setminus S_r$ is usually a union of finitely many rectangles, whose measures are of order $O(r^2)$. To avoid unnecessary complications, we always assume that $ B_r(q)\times [-\pi/2,\pi/2]\setminus S_r$ has a regular shape, e.g., as a union of finitely many rectangles.
\end{remark}

\begin{assumption}[\textbf{Geometric assumptions}]\label{assumption1}\ \par
\begin{enumerate}
    \item For a.e. $q \in \partial Q$ the set $B_r(q)\times [-\pi/2, \pi/2]$ is a quasi-section.
    \item $\bigcup_{i\ge 1}\partial X_i\subseteq \mathbb{S}$ (see the definition of $X_i$ in (\ref{parition})).
    \item There are constants $C>0$ and $\alpha \in (0,1]$, such that for any $\gamma^k$, where $k=u$ or $s$,  and for any $x,y \in \gamma^k$, \begin{align*}
        d_{f^j\gamma^k}(f^jx, f^jy)\le C d_{\gamma^k}(x,y)^\alpha \text{ for all }j\in[0,R(x)).
    \end{align*}
    (Observe that the condition $\bigcup_{i\ge 1}\partial X_i\subseteq \mathbb{S}$ implies that $\gamma^k \subseteq X_i$ for some $i\ge 1$).
    \item There exist two cones (i.e. affine subspaces) $C^u,C^s \subseteq \mathcal{T}(\mathcal{M})$, such that \[\dim(\interior{C^u}\bigcap \interior{C^s})<1, \quad (Df)C^u \subseteq C^u, \quad (Df)^{-1}C^s \subseteq C^s,\]
    and for all $n\ge 1$ and $\Leb_{\partial Q}$-a.e. $q \in \partial Q$
    \[\dim \big(\mathcal{T}(\{q\}\times [-\pi/2, \pi/2])\bigcap \interior{C^u}\big)<1, \quad \dim \big(\mathcal{T}(\{q\}\times [-\pi/2, \pi/2])\bigcap \interior{C^s}\big)<1,\]
    \[(Df)^n\mathcal{T}(\{q\}\times [-\pi/2, \pi/2]) \subseteq{\interior{C^u}}, \quad (Df)^{-n}\mathcal{T}(\{q\}\times [-\pi/2, \pi/2]) \subseteq{\interior{C^s}},\]where $\interior{C^u}$ (resp. $\interior{C^s}$) is the interior of $C^u$ (resp. $C^s$) and $\mathcal{T}(A)$ means a tangent space of a (sub)manifold $A$.
\end{enumerate}
\begin{remark}\ \par
\begin{enumerate}
    \item The existence of $C^u, C^s$ always holds for two dimensional hyperbolic billiards. 
    \item The H\"older condition is natural, and it is traditionally used for hyperbolic systems, (particularly, for billiards).
\end{enumerate}

\end{remark}
\end{assumption}

Now we can present the main results in this subsection.
\begin{theorem}[Poisson limit laws, see \cite{Subbb}]\label{thm}\ \par
Suppose that dynamical system $(\mathcal{M}, f)$ has a CMZ structure $(X, f^R)$ (see Definitions \ref{cmz} and \ref{inducesystem}), and the  Assumption \ref{assumption1} holds. Then, when $r\to 0$, we have $\mathcal{N}^{r,q} \to_d Poisson$ (see Definition \ref{pdef}) for $\Leb_{\partial Q}$-a.s. $q\in\partial Q$.
\end{theorem}
\begin{remark}
    The convergence rate (see Definition \ref{convergencerate}) for this approximation in Theorem \ref{thm} can be obtained by maximal large deviations \cite{mldp} and assuming polynomial mixing rates, while in Theorem \ref{thm} the convergence can be proven without specifying mixing rates.
\end{remark}

\begin{corollary}[First hitting times, see \cite{Subbb}]\ \par
Under the same conditions as in Theorem \ref{thm} consider the moment of time when the first hitting of (passage through) the hole occurs, i.e., $\tau_{r,q}(x):=\inf\left\{n \ge 1: f^n(x) \in B_r(q)\times [-\pi/2, \pi/2]\right\}$ for any $x \in \mathcal{M}$. Then for any $t>0$ and almost every $q \in \partial Q$, the following relation for the first hitting probability holds
\begin{equation*}
    \lim_{r\to 0}\mu_{\mathcal{M}}\Big\{\tau_{r,q}>t\big/\mu_{\mathcal{M}}\Big(B_r(q)\times [-\pi/2, \pi/2]\Big)\Big\}=e^{-t}.
\end{equation*}
\end{corollary}

We present now applications of Theorem \ref{thm} to some weakly chaotic billiards.
