\section{Central limit theorems and invariance principles}In this section we consider random dynamical systems.
A special subclass of random systems is formed by stationary systems.
\begin{definition}[Random and stationary dynamical systems]\ \par
     A random dynamical system is defined as $(\mathcal{M},(T_{\omega})_{\omega \in \Omega},  \Omega, \mathbb{P}, \sigma, (\mu_{\omega})_{\omega \in \Omega})$. Here  $\sigma: (\Omega, \mathbb{P})\to (\Omega,\mathbb{P})$ preserves a probability measure $\mathbb{P}$, and it is ergodic, $T_{\omega}: \mathcal{M} \to \mathcal{M}$ is a map,  $\mu_{\omega}$ is a probability measure on $X$ satisfying $(T^k_{\omega})_{*}\mu_{\omega}=\mu_{\sigma^k \omega}, k \ge 0$ where $T_{\omega}^k:=T_{\sigma^{k-1}\omega}\circ \cdots \circ T_{\sigma \omega}\circ T_{\omega}$.

     If $\Omega$ is a single point, then we call this system a stationary dynamical system.
\end{definition}

\begin{definition}[Vector-valued Almost Sure Invariance Principle (VASIP)]\
\par\label{rds}For a random dynamical system $(\mathcal{M},(T_{\omega})_{\omega \in \Omega},  \Omega, \mathbb{P}, \sigma, (\mu_{\omega})_{\omega \in \Omega})$, consider observables (functions on the phase space of all states of the system) $ \{\phi_{\omega} \in L^{\infty}(\mathcal{M},\mu_\mathcal{M}; \mathbb{R}^d): \omega \in \Omega\}$ which satisfy $$\sup_{\omega \in \Omega}||\phi_{\omega}||_{\infty}< \infty ,\quad  \int{\phi_{\omega}  d\mu_{\omega}}=0 \text{ for all } \omega \in \Omega.$$

We say that $ (\phi_{\sigma^k\omega} \circ T_{\omega}^k)_{k \ge 1, \omega \in \Omega} $ satisfies a quenched vector-valued almost sure invariance principle (quenched VASIP) if, for a.e. $\omega \in \Omega$, there exists a constant $\epsilon \in (0,1) $ and a family of zero mean $d$-dimensional independent Gaussian random vectors $ (G^{\omega}_k)_{k \ge 1}$ defined on some extended probability space of $(\mathcal{M}, \mu_{\omega})$ such that
\begin{equation} \label{qmatching}
\sum_{k=1}^{n} \phi_{\sigma^k\omega} \circ T_{\omega}^k - \sum_{k=1}^{n} G^{\omega}_k=o(n^{\frac{1-\epsilon}{2}}) \text{ a.s.}
\end{equation}
\begin{equation} \label{qvariancegrowth}
 \sigma^2_n(\omega)=\sum_{k=1}^{n} \tilde{\mathbb{E}}^{\omega}[{ (G^{\omega}_k) (G^{\omega}_k)^{T}}]+ o(n^{1-\epsilon}),
\end{equation}
\begin{equation}\label{qlinear}
\sigma_n^2(\omega) \approx_{\omega} n  I_{d \times d},
\end{equation}
where $\sigma_n^2(\omega):=\int(\sum_{k=1}^{n} \phi_{\sigma^k\omega} \circ T_{\omega}^k )(\sum_{k=1}^{n} \phi_{\sigma^k \omega}\circ T_{\omega}^k )^{T} d\mu_{\omega}$ and $\tilde{\mathbb{E}}^{\omega}$ in (\ref{qvariancegrowth}) is the expectation w.r.t. the probability $\tilde{P}^{\omega}$ on an extended probability space of $(\mathcal{M},  \mu_{\omega})$. Here the extended probability space is $(\mathcal{M}, \mu_{\omega}) \otimes \otimes_{ i \ge 1}(I_i, \Leb) $ where $I_i$ is a copy of $[0,1]$.
\end{definition}

\begin{remark} If $d=1$, then the quenched VASIP implies the quenched central limit theorem (CLT): \begin{align*}
    \lim_{n\to \infty }\mu_{\omega} \Big(\frac{\sum_{k=1}^{n} \phi_{\sigma^k \omega} \circ T_{\omega}^k}{\Sigma \sqrt{n} }\le z\Big) =\frac{1}{\sqrt{2\pi}}\int_{-\infty}^{z}e^{-s^2/2}ds \text{ for all } z \in \mathbb{R}, 
\end{align*}(in other words, $\frac{\sum_{k=1}^{n} \phi_{\sigma^k \omega} \circ T_{\omega}^k}{\Sigma \sqrt{n} }$ converges in distribution to a Gaussian variable $\mathcal{N}(0,1)$) and the quenched iterated logarithm  law(LIL): \begin{align*}
  \limsup_{n\to \infty}\frac{\sum_{k=1}^{ n} \phi_{\sigma^k\omega} \circ T_{\omega}^k}{\sqrt{n\log\log n}}=\Sigma \quad \mu_{\omega}\text{-a.s.}
\end{align*}
for a.e. $\omega \in \Omega$ and a constant $\Sigma > 0$, which does not depend on $\omega$. 
\end{remark}

\begin{remark}\label{singlept}
    If $\Omega$ is a single point $\{\omega_0\}$, then the random system becomes a stationary system. Then VASIP, CLT and LIL have the following forms, respectively: 
\begin{gather*}
    \sum_{k=1}^{n} \phi_{\omega_0} \circ T_{\omega_0}^k - \sum_{k=1}^{n} G_k=o(n^{\frac{1-\epsilon}{2}}) \text{ a.s.}\\
     \lim_{n\to \infty }\mu_{\omega_0} \Big(\frac{\sum_{k=1}^{n} \phi_{\omega_0} \circ T_{\omega_0}^k}{\Sigma \sqrt{n} }\le z\Big) =\frac{1}{\sqrt{2\pi}}\int_{-\infty}^{z}e^{-s^2/2}ds \text{ for all } z \in \mathbb{R}, \\
     \limsup_{n\to \infty}\frac{\sum_{k=1}^{ n} \phi_{\omega_0} \circ T_{\omega_0}^k}{\sqrt{n\log\log n}}=\Sigma \quad \mu_{\omega_0}\text{-a.s.}
\end{gather*}
\end{remark}

The following is a general VASIP result for random dynamical systems.
\begin{theorem}[Random Dynamical Systems, see \cite{Sutams}]\ \label{thm3} \par
Consider a random dynamical system $(\mathcal{M}, (T_{\omega})_{\omega \in \Omega},  \Omega, \mathbb{P}, \sigma, (\mu_{\omega})_{\omega \in \Omega})$, where $d\mu_{\omega}=h_{\omega}d\mu_\mathcal{M}$ is a probability distribution  on $\mathcal{M}$ and $\mu_{\mathcal{M}}$ is a measure on $\mathcal{M}$. Let the transfer operators (Perron-Frobenius operators)  $P_{\omega}$ associated to $T_{\omega}$ are defined by the  following duality relations
\begin{equation*}
    \int g \cdot P_{\omega} (h) d\mu_{\mathcal{M}}= \int g \circ T_{\omega} \cdot h d\mu_{\mathcal{M}} \text{ for all } h \in L^1(\mu_{\mathcal{M}})\text{, } g \in L^{\infty}(\mu_{\mathcal{M}}).
\end{equation*}


Let the observables $\{\phi_{\omega} \in L^{\infty}(\mathcal{M},\mu_{\mathcal{M}};\mathbb{R}^d):  \omega \in \Omega\}$ be the ones from the Definition \ref{rds}. Suppose that they satisfy the conditions (\ref{A1'})-(\ref{A3'}) below, and there is a constant $C>0$ such that for any $i,j\ge 0,n \ge 1$, and for almost every $\omega\in \Omega$,
\begin{equation} \label{A1'}
\int |P_{\sigma^{i}\omega}^{n} (\phi_{\sigma^i \omega}  h_{\sigma^{i} \omega})|d\mu_{\mathcal{M}} \le C n^{1-1/\alpha}, \tag{A1'}
\end{equation}
\begin{equation} \label{A2'}
\int \Big|P_{\sigma^{i}\omega}^{n} \Big[(\phi_{\sigma^i \omega}  \phi_{\sigma^i \omega}^T - \int \phi_{\sigma^i \omega}   \phi_{\sigma^i \omega}^T  d\mu_{\sigma^i\omega}) h_{\sigma^{i}\omega}\Big] \Big|  d\mu_{\mathcal{M}} \le C  n^{1-1/\alpha}, \tag{A2'}
\end{equation}
\begin{equation} \label{A3'}
\int \Big|P_{\sigma^{i+j} \omega}^{n} \Big[P^{j}_{\sigma^{i} \omega}(\phi_{\sigma^{i} \omega} h_{\sigma^{i}\omega})  \phi_{\sigma^{i+j} \omega}^T - h_{\sigma^{i+j}\omega}\int P^{j}_{\sigma^{i} \omega}(\phi_{\sigma^{i} \omega}  h_{\sigma^{i}\omega}) \phi_{\sigma^{i+j} \omega}^T d\mu_{\mathcal{M}}\Big] \Big| d\mu_{\mathcal{M}}
\le C n^{1-1/\alpha}, \tag{A3'}
\end{equation}
where $\alpha < 1/2$, $|\cdot|$ is the Euclidean norm for vectors or the spectral norm for matrices.

Then there are two linear subspaces (which do not depend on $\omega$): $W_1, W_2 \subseteq{\mathbb{R}^d}$, $\mathbb{R}^d= W_1 \bigoplus W_2$ with projections $\pi_1:W_1\bigoplus W_2 \to W_1, \pi_2: W_1 \bigoplus W_2 \to W_2$ such that
\begin{enumerate}
    \item $(\pi_1 \circ  \phi_{\sigma^k \omega}  \circ T^{k}_{\omega})_{k \ge 1, \omega \in \Omega}$ satisfies the quenched VASIP (see Definition \ref{rds}).
    \item $(\pi_2 \circ  \phi_{\sigma^k \omega}  \circ T^{k}_{\omega})_{k \ge 1, \omega \in \Omega}$ is a coboundary, i.e., there is $\psi \in L^1(\Omega \times X, d\mu_{\omega}d\mathbb{P})$ such that \[  \pi_2 \circ \phi_{\sigma \omega}(T_{\omega}x)=\psi(\sigma \omega,T_{\omega}x)-\psi(\omega,x) \text{ a.e. }(\omega,x)\in \Omega \times X.\]
\end{enumerate}
\end{theorem}

The paper \cite{LSV} considers the so called Pomeau-Manneville type maps, which are expanding everywhere besides at an indifferent (parabolic) point. Existence of just one such point may essentially change  dynamics. This class of maps is defined in the following way. Let $\beta\in [0,1)$,

\begin{eqnarray}\label{pmmap}
 T_{\beta}(x) =
\begin{cases}
x+2^{\beta}x^{1+\beta},      & 0\le x \le 1/2\\
2x-1,  & 1/2< x \le 1 \\
\end{cases}.
\end{eqnarray}

According to \cite{LSV, Young2}, its mixing rate is $O(n^{1-1/\beta})$ and this map preserves a probability measure absolutely continuous respect to the Lebesgue measure on $[0,1]$. If we randomly perturbed the parameters $\beta \in [0,1/2)$, and apply Theorem \ref{thm3} to the class of these random systems, then the following result holds.

\begin{corollary}[Polynomially mixing random systems, see \cite{Sutams}]\ \label{cor7} \par
Let $\mu_{\mathcal{M}}:=\Leb$ be the Lebesgue measure on $\mathcal{M}:=[0,1]$,  $\Omega:=[0,1/2)^{\mathbb{Z}}$, and $T_{\omega}:=T_{\omega_{[0]}}$ are the Pomeau-Manneville type maps (\ref{pmmap}) which are picked from $\{T_{\beta}: \beta \in [0,1/2)\}$. Let also $ \sigma : \Omega \to \Omega$ is a $\mathbb{P}$-preserving ergodic and invertible left shift, and  $\omega_{[0]}$ is the 0th entry of $\omega$.

Then there are functions $h_{\omega} \in L^1(\Leb)$ and probabilities $d\mu_{\omega}: =h_{\omega}d\Leb$ such that $(T_{\omega})_{*} \mu_{\omega}=\mu_{\sigma \omega}$ for a.e. $\omega \in \Omega$. Moreover, suppose that the observables $(\phi_{\omega})_{\omega \in \Omega} \subseteq \mathrm{Lip}([0,1]; \mathbb{R}^d)$ satisfy the relations $\sup_{\omega}||\phi_{\omega}||_{\mathrm{Lip}}<\infty$ and $\int \phi_{\omega}d\mu_{\omega}=0$. Then there are two linear subspaces (which do not depend on $\omega$) $W_1, W_2 \subseteq{\mathbb{R}^d}$, $\mathbb{R}^d= W_1 \bigoplus W_2$ with projections $\pi_1:W_1\bigoplus W_2 \to W_1, \pi_2: W_1 \bigoplus W_2 \to W_2$ such that 

\begin{enumerate}
    \item $(\pi_1 \circ  \phi_{\sigma^k \omega}  \circ T^{k}_{\omega})_{k \ge 1,\omega \in \Omega}$ satisfies the quenched VASIP.
    \item $(\pi_2 \circ  \phi_{\sigma^k \omega}  \circ T^{k}_{\omega})_{k \ge 1,\omega \in \Omega}$ is a coboundary, which means that there is $\psi \in L^1(\Omega \times [0,1], d\mu_{\omega}d\mathbb{P})$ such that \[\pi_2 \circ  \phi_{\sigma \omega}(T_{\omega}x)=\psi(\sigma \omega,T_{\omega}x)-\psi(\omega,x) \text{ a.e. }(\omega,x)\in \Omega \times [0,1].\]
\end{enumerate}

\end{corollary}
\begin{remark}
$\sigma: \Omega \to \Omega$ is ergodic, and $1/2$ is optimal, see also \cite{nonclt}. If $\sigma$ is Bernoulli, then the range of $\beta$ can be larger than $[0,1/2)$ (see  \cite{Suetds}).
\end{remark}
\begin{remark}\label{singlemaplimit}
By Remark \ref{singlept}, when $\beta\in [0,1/2), \Omega=\{\beta\}$ and $\phi$ has zero mean, then  we obtain the corresponding results for the  single dynamics $T_{\beta}$ and a zero mean function $\phi$  \begin{gather*}
    \sum_{k=1}^{n} \phi \circ T_{\beta}^k - \sum_{k=1}^{n} G_k=o(n^{\frac{1-\epsilon}{2}}) \text{ a.s.}\\
    \frac{\sum_{k=1}^{n} \phi \circ T_{\beta}^k}{\Sigma \sqrt{n} } \to_d \mathcal{N}(0,1)
\end{gather*} (Gaussian distribution) or there is a function $\chi$ such that $\phi=\chi\circ T_{\beta}-\chi$ a.s.
\end{remark}


If $\beta \in (1/2,1)$, then weakly chaotic stationary dynamics $T_{\beta}$ does not satisfy the standard CLT or VASIP,  but the following different limit law holds \cite{nonclt}.

\section{Stable limit laws}
Let $1/2<\beta <1$, and the corresponding stationary dynamics $T_{\beta} : [0, 1] \to [0, 1]$ be the Liverani-Saussol-Vaienti map described by (\ref{pmmap}). 

\begin{theorem}[see \cite{nonclt}]\label{gouezelstable} \par
   Let $h$ be the density of its unique absolutely continuous invariant probability measure $\mu_{\beta}$, and $\phi: [0, 1] \to \mathbb{R}$ is H\"older with  $\int \phi d\mu_{\beta} = 0$.

If $\phi (0) \neq 0$, then the following stable limit law holds: \[\frac{\sum_{i \le n} \phi\circ T_{\beta}^i}{n^\beta} \to_d X_{1/\beta,c,sgn(\phi(0))}\] whose characteristic function is $\mathbb{E}(e^{itX_{1/\beta,c,sgn(\phi(0))}} ) = e^{-c|t|^{1/\beta}(1-isgn(\phi(0))sgn(t)\tan(\pi/(2\beta) ))} $ with $c = \frac{h(1/2)}{4(\beta/|\phi (0)|)^{1/\beta}} \Gamma(1-1/\beta)\cos(\pi/(2\beta))$.

If $\phi(0) = 0$, we may also assume that $|\phi(x)|\le Cx^{\gamma}$ with $\gamma >\beta-1/2$. Then there
exists a constant $\sigma^2\ge 0$ such that \[\frac{\sum_{i\le n}\phi\circ T_{\beta}^i}{\sqrt{n}} \to_d \mathcal{N}(0, \sigma^2).\] Moreover,
$\sigma^2 = 0$ if and only if there exists a measurable function $\chi$ such that $\phi = \chi \circ T_{\beta} -\chi$.
\end{theorem}
Besides expadning maps $T_{\beta}$,  we next consider two-dimensional dispersing billiards with a cusp at a flat point. More precisely, for any fixed constant $\eta> 2$
(which will determine the sharpness of the cusp), we take a dispersing
billiard table $Q = Q_{\eta}$ with a boundary consisting of a finite number of $C^3$
smooth curves $\Gamma_i$, $i = 1 \cdots, n_0$, where $n_0 \ge 3$, where a cusp formed by two  curves $\Gamma_1, \Gamma_2$ such that  cusp at $P = \Gamma_1 \bigcap \Gamma_2$. Moreover, both $\Gamma_1$ and $\Gamma_2$ have zero derivatives up to $\eta- 1$ order
at $P$, and the $\eta$-order derivative is not zero. We also assume that all other
boundary components are dispersing and have curvature bounded away from
zero.
Choose now a Cartesian coordinate system $(s, z)$ with the origin at $P$, and with
the horizontal $s$-axis being the tangent line to both $\Gamma_1$ and $\Gamma_2$. Assume also that $\Gamma_1$ and
$\Gamma_2$ can be represented as
\begin{equation}\label{cusps}
    z_1(s) = \eta^{-1}s^\eta, z_2(s) = -\eta^{-1}s^\eta
\end{equation}
for $s \in [0, \epsilon_0]$ with $\epsilon_0 > 0$ being a small fixed number. The mixing rate for this billiard system is $O(n^{-1/(\eta-1)})$. A stable limit law for this billiard system ($\mathcal{M}, f$) (see Definition \ref{billiarddef}) is proved by Paul and Zhang \cite{hongkunstable}.

\begin{theorem}[see \cite{hongkunstable}]\ \par
    Let $Q_{\eta}$, where
$\eta \in(2,\infty)$, is a billiard table with a cusp defined by (\ref{cusps}), $\alpha = \eta/(\eta-1)$ and suppose that a mean zero function $\psi$ is  H\"older and defined on  $\mathcal{M}$. Let also $$I_\psi:= 1/4 \int^{\pi}_0(\psi(q''
, \phi) + \psi(q', \phi)) \sin^{1/\alpha} \phi d\phi \neq 0,$$ where $q', q''$ are the $q$-coordinates of the cusps point $P$ in the phase space $\mathcal{M}$ with respect to $\Gamma_1$ and $\Gamma_2$, respectively. Then as $n \to \infty$, \[\frac{\sum_{i \le n}\psi \circ f^i}{n^{1/\alpha}} \to_d S_{\alpha, \sigma}\]
where $\sigma = \frac{2I_\psi}{\eta \Leb_{\partial Q}\partial Q}$ and the characteristic function of $S_{\alpha,\sigma}$ is $\mathbb{E}(e^{itS_{\alpha, \sigma}})=e^{-|\sigma|^{\alpha}|t|^{\alpha}(1-isgn(t)\tan(\alpha\pi/2 ))} $.
\end{theorem}

\begin{remark}
    We note that when the mixing rate is slower and slower, the Poisson limit laws (Theorem \ref{thm}) still hold, while the central limit theorems (Remark \ref{singlemaplimit})  will change to stable limit laws (Theorem \ref{gouezelstable}). 
\end{remark}

