\section{Explicit expression of \texorpdfstring{$\boldsymbol{L}_* ^\top \boldsymbol{y}$}{L* y} in \eqref{MSE}}\label{sec:A}
Since
\begin{align*}
&\E\left[ \| \boldsymbol{L}^\top \boldsymbol{y}- \boldsymbol{\beta} \|^2|\ \boldsymbol{\beta},\sigma^2 \right]\\
& = \E\left[ \| (\boldsymbol{L}^\top \boldsymbol{y}-\boldsymbol{L}^\top \boldsymbol{X} \boldsymbol{\beta})+(\boldsymbol{L}^\top\boldsymbol{X}-\boldsymbol{I}_k)\boldsymbol{\beta}\|^2|\ \boldsymbol{\beta},\sigma^2 \right]\\
& = \E\left[ \|\boldsymbol{L}^\top \boldsymbol{y}-\boldsymbol{L}^\top \boldsymbol{X} \boldsymbol{\beta} \|^2|\ \boldsymbol{\beta},\sigma^2 \right]
+ \E\left[ \|(\boldsymbol{L}^\top\boldsymbol{X}-\boldsymbol{I}_k)\boldsymbol{\beta}\|^2|\ \boldsymbol{\beta},\sigma^2 \right]\\
& = \tr\left\{\E\left[(\boldsymbol{L}^\top \boldsymbol{y}-\E[\boldsymbol{L}^\top \boldsymbol{y}])(\boldsymbol{L}^\top \boldsymbol{y}-\E[\boldsymbol{L}^\top \boldsymbol{y}])^\top|\ \boldsymbol{\beta},\sigma^2\right]\right\} + \tr\left\{\E\left[(\boldsymbol{L}^\top\boldsymbol{X}-\boldsymbol{I}_k)\boldsymbol{\beta}\boldsymbol{\beta}^\top(\boldsymbol{L}^\top\boldsymbol{X}-\boldsymbol{I}_k)^\top|\ \boldsymbol{\beta},\sigma^2\right]\right\}\\
& = \tr\left\{\sigma^2 \boldsymbol{L}^\top\boldsymbol{\Omega}\boldsymbol{L}+(\boldsymbol{X}^\top \boldsymbol{L}-\boldsymbol{I}_k)^\top\boldsymbol{\beta}\boldsymbol{\beta}^\top(\boldsymbol{X}^\top \boldsymbol{L}-\boldsymbol{I}_k)\right\},
\end{align*}
the right-hand side of \eqref{MSE} can be calculated as follows:
\begin{align*}
&\E_{\boldsymbol{\beta},\sigma^2}\left[\E[ \| \boldsymbol{L}^\top \boldsymbol{y}- \boldsymbol{\beta} \|^2|\ \boldsymbol{\beta},\sigma^2 ]\right]\\
& = \tr\left\{\E_{\sigma^2}[\sigma^2]\boldsymbol{L}^\top\boldsymbol{\Omega}\boldsymbol{L}+(\boldsymbol{X}^\top \boldsymbol{L}-\boldsymbol{I}_k)^\top\E_{\boldsymbol{\beta}}[\boldsymbol{\beta}\boldsymbol{\beta}^\top](\boldsymbol{X}^\top \boldsymbol{L}-\boldsymbol{I}_k)\right\}\\
& = \tr\left\{\gamma \boldsymbol{L}^\top\boldsymbol{\Omega}\boldsymbol{L}+ (\boldsymbol{X}^\top \boldsymbol{L}-\boldsymbol{I}_k)^\top\boldsymbol{W}(\boldsymbol{X}^\top \boldsymbol{L}-\boldsymbol{I}_k)\right\}\\
& = \tr\left(\gamma \boldsymbol{L}^\top\boldsymbol{\Omega}\boldsymbol{L} + \boldsymbol{L}^\top \boldsymbol{XWX}^\top \boldsymbol{L}-2\boldsymbol{L}^\top \boldsymbol{XW}+\boldsymbol{W}\right).
\end{align*}
To find the solution $\boldsymbol{L}_*$ in \eqref{MSE}, we partially differentiate the above equation with respect to $\boldsymbol{L}$, set it equal to $\boldsymbol{0}$, and solve for $\boldsymbol{L}$.
From the following differentiation formula
\begin{align*}
\cfrac{\partial}{\partial \boldsymbol{A}} \ \tr(\boldsymbol{A}^\top \boldsymbol{B}\boldsymbol{A}) = (\boldsymbol{B}+\boldsymbol{B}^\top)\boldsymbol{A} \quad  \an \quad
\cfrac{\partial}{\partial \boldsymbol{A}} \ \tr(\boldsymbol{A}^\top \boldsymbol{B}) = \boldsymbol{B},
\end{align*}
we obtain
\begin{align*}
& 2 \gamma \boldsymbol{\Omega L} + 2\boldsymbol{XWX}^\top \boldsymbol{L}- 2\boldsymbol{XW} = \boldsymbol{0}\\
\Leftrightarrow \quad & \boldsymbol{L}_* = (\boldsymbol{\Omega} + \boldsymbol{X}\boldsymbol{W}_*\boldsymbol{X}^\top)^{-1} \boldsymbol{X}\boldsymbol{W}_*,
\end{align*}
where $\boldsymbol{W}_* = \gamma^{-1}\boldsymbol{W}$. 
So, the Bayes linear estimator can be expressed as 
\begin{align*}
\boldsymbol{L}_*^\top \boldsymbol{y} = \boldsymbol{W}_*\boldsymbol{X}^\top (\boldsymbol{\Omega} + \boldsymbol{X}\boldsymbol{W}_*\boldsymbol{X}^\top)^{-1}\boldsymbol{y}.
\end{align*}
