    \dot{\bm{d}} -\mathbf{W} \bm{d} &= -\frac{1}{J \eta_D} \left[ \frac{\partial \Psi}{\partial \bm{d}} - \left( \frac{\partial \Psi}{\partial \bm{d}} \cdot \bm{d} \right) \bm{d} \right]. \label{eq_d_circle}
\end{align}
Here, $\mathbf{L}^\mathrm{v} = \dot{\mathbf{F}}^\mathrm{v} \mathbf{F}^{\mathrm{v}^{-1}}$ is the viscous rate of deformation tensor, $\mathbf{W}$ is the spin tensor,  $\eta_D$ and $\eta_N$ are the viscosities associated with director rotation and viscous deformation of the polymer network, respectively. 


Substituting equations \eqref{eq_Psi} and \eqref{eq_Psi_specify} into \eqref{eq_sigma} gives the Cauchy stress:
\begin{align}
    \boldsymbol{\upsigma} &= \boldsymbol{\upsigma}^\mathrm{eq} + \boldsymbol{\upsigma}^\mathrm{neq},  \\%= \frac{1}{J} \text{sym} \left( \frac{\partial (\overline{\Psi}^{eq} + \Psi^b)}{\partial \mathbf{F}} \mathbf{F}^{\top} \right) + \frac{1}{J} \text{sym} \left( \frac{\partial \overline{\Psi}^{neq}}{\partial \mathbf{F}^e} {\mathbf{F}^e}^{\top} \right), \notag \\
    %
    \text{where} \\
    \boldsymbol{\upsigma}^\mathrm{eq} &= \frac{1}{J} \left( \frac{\mu^\mathrm{eq}}{1 - Q} \frac{I_m}{I_m - (I^N - 3)} \right) \left[ \mathbf{F} \bm{l}_0 \mathbf{F}^{\top} - \frac{3Q}{1 + 2Q} \text{sym} (\bm{d} \otimes \mathbf{F} \bm{l}_0 \mathbf{F}^{\top} \bm{d}) \right] - \left[ \frac{\mu^\mathrm{eq}}{J} - \kappa (J - 1) \right] \mathbf{I}, \notag \\
    %
    \boldsymbol{\upsigma}^\mathrm{neq} &= \frac{1}{J} \left( \frac{\mu^\mathrm{neq}}{1 - Q} \frac{I_m} {I_m - (I^{N\mathrm{e}} - 3)} \right) \left[ \mathbf{F}^\mathrm{e} \bm{l}_0 {\mathbf{F}^\mathrm{e} }^{\top} - \frac{3Q}{1 + 2Q} \text{sym} (\bm{d} \otimes \mathbf{F}^\mathrm{e} \bm{l}_0 {\mathbf{F}^\mathrm{e} }^{\top} \bm{d}) \right] - \frac{\mu^\mathrm{neq} }{J} \mathbf{I}.
\label{eq:cauchy_stress}
\end{align}
%
%
Similarly, substituting equations \eqref{eq_Psi} and \eqref{eq_Psi_specify} into \eqref{eq_L^v} gives the viscoelastic flow rule:
\begin{equation}
    \mathbf{L}^\mathrm{v} = \frac{\mu^\mathrm{neq} }{\eta_N} \left( \frac{I_m}{I_m - (I^{N\mathrm{e} } - 3)} \mathbf{F}^{\mathrm{e} {\top}} \bm{l}^{-1} \mathbf{F}^\mathrm{e}  \bm{l}_0 - \mathbf{I} \right).
\end{equation}


For director rotation, substituting equations \eqref{eq_Psi} and \eqref{eq_Psi_specify} into \eqref{eq_d_circle} gives:
\begin{equation}
\begin{aligned}
    \dot{\bm{d}} %&= \mathbf{W}\bm{d} -\frac1{J\eta_D}  \left[ \frac{\partial\Psi}{\partial\bm{d}}-\left(\frac{\partial\Psi}{\partial\bm{d}}\cdot\bm{d}\right)\bm{d} \right] \\ 
    %
%    &= \mathbf{W}\bm{d} -\frac1{J\eta_D} \underbrace{ \left[ \frac{\partial \overline{\Psi}^{eq}}{\partial\bm{d}}-\left(\frac{\partial \overline{\Psi}^{eq}}{\partial\bm{d}}\cdot\bm{d}\right)\bm{d} \right]}_\textbf{$\bm{m}^{eq}$} -\frac1{J\eta_D} \underbrace{\left[\frac{\partial \overline{\Psi}^{neq}}{\partial\bm{d}}-\left(\frac{\partial \overline{\Psi}^{neq}}{\partial\bm{d}}\cdot\bm{d}\right)\bm{d}\right]}_\textbf{$\bm{m}^{neq}$} \\
