    %
    &= \mathbf{W}\bm{d} -\frac1{J\eta_D} (\bm{m}^\mathrm{eq} + \bm{m}^\mathrm{neq})  + \frac{\gamma}{J\eta_D} (\bm{d} \cdot \bm{d} - 1)^2 \bm{d},
\end{aligned}
\label{eq:d_dot_penalty}
\end{equation}
where, 
\begin{equation}
\begin{aligned}
\bm{m}^\mathrm{eq}&=-\mu^\mathrm{eq}\frac{3Q}{(1-Q)(1+2Q)}\frac{I_m}{I_m-(I^N-3)}\left[\mathbf{F}\bm{l}_0\mathbf{F}^{\top}\cdot\bm{d}-(\bm{d}\cdot\mathbf{F}\bm{l}_0\mathbf{F}^{\top}\cdot\bm{d})\bm{d}\right]\\
\bm{m}^\mathrm{neq}&=-\mu^\mathrm{neq}\frac{3Q}{(1-Q)(1+2Q)}\frac{I_m}{I_m-(I^{N\mathrm{e}}-3)}\left[\mathbf{F}^\mathrm{e}\bm{l}_0{\mathbf{F}^\mathrm{e}}^{\top}\cdot\bm{d}-(\bm{d}\cdot\mathbf{F}^\mathrm{e}\bm{l}_0{\mathbf{F}^\mathrm{e}}^{\top}\cdot\bm{d})\bm{d}\right],
