\section{Determining parameters for the finite-strain viscoelastic model}
\label{app:ParameterForTiltedBeams}
\setcounter{table}{0}
\setcounter{figure}{0}

The storage modulus master curves (Figure~\ref{fig:Fig_S0}a–b) were used to extract viscoelastic parameters for modeling the tilted LCE beams. Relaxation spectra $(\tau_k, \mu_k^{\mathrm{neq}})$ were obtained from the curves. For the polydomain LCE with higher crosslinking density, a fractional viscoelastic model was used to capture the experimental response with minimal fitting parameters~\citep{Haupt2000OnParameters}.

Following fractional calculus~\citep{Caputo1971LinearSolids, Koeller1984ApplicationsViscoelasticityb, Bagley1986OnBehavior}, the fractional derivative $\frac{d^\alpha f}{dt^\alpha}$ for $0 < \alpha < 1$ is defined as~\citep{Haupt2000OnParameters}:
%
\begin{equation}
    \frac{d^\alpha f}{dt^\alpha} = \frac{1}{\Gamma(1 - \alpha)} \int_0^t \frac{f'(s)}{(t - s)^\alpha} \, ds, \quad f(0) = 0,
    \label{eq:frac_derivative}
\end{equation}
%
where $\Gamma(\cdot)$ is the Gamma function. The fractional damping element~\citep{Lion1997OnElements, HSchiessel1995GeneralizedSolutions} relates stress to fractional strain rate:
%
\begin{equation}
    \frac{d^\alpha \epsilon}{dt^\alpha} = \frac{\sigma}{E \zeta^\alpha}.
\end{equation}
%
Here, $E$, $\zeta$, and $\alpha$ are non-negative parameters. The model recovers Hookean and Newtonian behavior as $\alpha \rightarrow 0$ and $1$, respectively (Figure~\ref{fig:Fig_S6}). Storage and loss moduli are given by~\citep{Haupt2000OnParameters, Nguyen2010ModelingPolymers}:
%
\begin{equation}
\begin{aligned}
    E_{frac}'(\omega) &= 3 \mu^{\mathrm{eq}} + \frac{2.7 \mu^{\mathrm{neq}}((\omega \zeta)^{2\alpha} + (\omega \zeta)^{\alpha} \cos(\alpha \pi / 2))}{1 + (\omega \zeta)^{2\alpha} + 2 (\omega \zeta)^{\alpha} \cos(\alpha \pi / 2)}, \\
    E_{frac}''(\omega) &= \frac{3 \mu^{\mathrm{neq}} (\omega \zeta)^{\alpha} \sin(\alpha \pi / 2)}{1 + (\omega \zeta)^{2\alpha} + 2 (\omega \zeta)^{\alpha} \cos(\alpha \pi / 2)}.
\end{aligned}
\end{equation}



The parameters $\mu^{\mathrm{eq}}$ and $\mu^{\mathrm{neq}}$ were estimated from the rubbery and glassy plateaus, assuming $\nu_g = 0.35$ and $\nu_r = 0.5$. The fractional exponent $\alpha$ controls the relaxation spectrum breadth, and $\zeta$ sets the characteristic time scale. Fitting yielded $\zeta = 3 \times 10^{-8}$~s and $\alpha = 0.46$ (Figure~\ref{fig:Fig_S7}). Deviations at high frequencies were considered negligible given the focus on moderate rates and lower frequencies.




\begin{figure}[H]
    \centering     
    \includegraphics[width=0.35\textwidth]{FractionalModel.pdf}
    \caption{Fractional viscoelastic model with equilibrium and nonequilibrium shear moduli $\mu^{\mathrm{eq}}$, $\mu^{\mathrm{neq}}$, spectral breadth $\alpha$, and characteristic relaxation time $\zeta$. Reproduced from~\citep{Haupt2000OnParameters}, with permission from Elsevier.}
    \label{fig:Fig_S6}
\end{figure}


\begin{figure}[H]
    \centering     
    \includegraphics[width=0.55\textwidth]{MasterCurveFit_StiffPD.pdf}
    \caption{Storage modulus master curve fit using the fractional model at 25~$^\circ$C.}
    \label{fig:Fig_S7}
\end{figure}


The continuous relaxation spectrum is:
\begin{equation}
    h_{\mathrm{frac}}(\omega) = \frac{2.7 \mu^{\mathrm{neq}}(\omega \zeta)^{\alpha} \sin(\alpha \pi)}{\pi \omega \left[1 + (\omega \zeta)^{2\alpha} + 2 (\omega \zeta)^{\alpha} \cos(\alpha \pi)\right]}.
    \label{eq:frac_hw}
\end{equation}
Its cumulative form is:
\begin{equation}
    H_{\mathrm{frac}}(\omega) = \int_{0}^{\omega} h_{\mathrm{frac}}(z) \, dz,
\end{equation}
with analytic expression:
\begin{equation}
    H_{\mathrm{frac}}(\omega) = \frac{2.7 \mu^{\mathrm{neq}}}{\alpha \pi} \left[ \arctan\left(\frac{(\omega \zeta)^{\alpha} + \cos(\alpha \pi)}{\sin(\alpha \pi)}\right) - \pi \left(\frac{1}{2} - \alpha\right) \right].
    \label{eq:frac_Hw}
\end{equation}

Discrete relaxation frequencies were defined logarithmically:
\begin{equation}
    \omega_k = \omega_{\text{min}} \left( \frac{\omega_{\text{max}}}{\omega_{\text{min}}} \right)^{\frac{k-1}{N-1}}, \quad \tau_k = 1/\omega_k.
\end{equation}
Discrete moduli $\mu_i^{\mathrm{neq}}$ were calculated to approximate $H_{\mathrm{frac}}(\omega)$:
\begin{equation}
\begin{aligned}
    \mu_1^{\mathrm{neq}} &= \frac{1}{2.7} \cdot \frac{1}{2} \left[ H_{\mathrm{frac}}(\omega_1) + H_{\mathrm{frac}}(\omega_2) \right], \\
    \mu_k^{\mathrm{neq}} &= \frac{1}{2.7} \cdot \frac{1}{2} \left[ H_{\mathrm{frac}}(\omega_{k+1}) - H_{\mathrm{frac}}(\omega_{k-1}) \right], \quad 2 \leq k \leq N-1, \\
    \mu_N^{\mathrm{neq}} &= \mu^{\mathrm{neq}} - \sum_{k=1}^{N-1} \mu_k^{\mathrm{neq}}.
\end{aligned}
\end{equation}



The final model used $N = 20$ to balance accuracy and cost (Figure~\ref{fig:Fig_S8}). Final parameters for the polydomain LCE with higher crosslinking density are summarized in Table~\ref{tab:Parameters_StiffPD}, including relaxation times $\tau_i^{\mathrm{neq}}$, shear moduli $\mu_i^{\mathrm{neq}}$, viscosities $\eta_i^{\mathrm{neq}}$, and the normalized Prony series terms dimensionless shear (deviatoric) $g_i$ and bulk (volumetric) moduli $k_i$ for Abaqus \citep{dassaultsystemesSIMULIAUserAssistance2023}.


Normalized moduli $g_i$ are defined as:
\begin{equation}
g_i = \frac{\mu_i^{\mathrm{neq}}}{\mu_0} = \frac{\mu_i^{\mathrm{neq}}}{\sum_{i=1}^{N} \mu_i^{\mathrm{neq}} + \mu^{\mathrm{eq}}},
\end{equation}
with $\mu_0$ as the instantaneous shear modulus. Bulk relaxation was neglected by setting $k_i = 0$. The hyperelastic baseline used $C_{10} = \mu^{\mathrm{eq}}/2 = 0.333$ MPa and $D_1 = 2/\kappa^{\mathrm{eq}} = 2.29 \times 10^{-4}$.

The same fitting procedure was applied to all six LCE types. Their fitted storage modulus curves and discrete spectra are shown in Figure~\ref{fig:Fig_S9}.



