\section{Proof of \texorpdfstring{\cref{thm:t_step_crossings}}{Theorem 1}}
\label{app:proof_one_step_crossings}

\setcounter{theorem}{0}
\begin{theorem}
	Given a point set $P_0$, a $k$-edge-coloring $\col_0$, a matching $\hm_0$, and details at all vertices of $P_0$, the number of monochromatic crossings after $t$ iterations of the doubling construction is
    \begin{align}
    \begin{split}
        \crk(P_t; \col_t) =&\ 16^t\;\crk(P_0; \col_0) + \sum_{i=0}^{t-1}16^{t-i-1}\left[\binom{2^i|P_0|}{2} - 2^i|P_0|\right] \\
        &\ +\ 4 \sum_{p \in P_0} \sum_{c = 1}^{k} \sum_{i=0}^{t-1}16^{t-i-1}\sum_{j=1}^{2^i}\left[ \binom{\lset{c}{p^i_j}}{2} + \binom{\rset{c}{p^i_j}}{2} \right] \\
        &\ +\ 2 \sum_{p \in P_0} \sum_{i=0}^{t-1}16^{t-i-1} \sum_{j=1}^{2^i}\left[\lset{\cbar(p)}{p^i_j} + \rset{\cbar(p)}{p^i_j}. \right]
    \end{split}
    \end{align}
\end{theorem}

\begin{proof}
    We first proof the following claim about the number of crossings after a single iteration.
    \begin{claim}
        \label{claim:one_step_crossings}
        Given a point set $P_0$, a $k$-edge-coloring $\col_0$, a matching $\hm_0$, and details at all vertices of $P_0$, the number of monochromatic crossings after one step of the doubling construction is
        \begin{align*}
        \begin{split}
            \crk(P_1; \col_1) =&\ 16\;\crk(P_0; \col_0) +\ \binom{|P_0|}{2} - |P_0| \\
            &\ +\ 4 \sum_{p \in P_0} \sum_{c = 1}^{k} \left[\binom{\lset{c}{p}}{2} + \binom{\rset{c}{p}}{2}\right] \\
            &\ +\ 2 \sum_{p \in P_0} \left[\lset{\cbar(p)}{p} + \rset{\cbar(p)}{p}\right]
        \end{split}
        \end{align*}
    \end{claim}
    \begin{proof}[Proof of \cref{claim:one_step_crossings}]
        Each crossing in $P_1$ is determined by a quadruple of points in convex position whose two diagonals have the same color. Four such points can be the children of either 2, 3 or 4 points of $P_0$, see \cref{fig:proof_counting_crossings}. 
        We count crossings based on these three types (I, II, and III).
        \begin{enumerate}[I.]
            \item[I.] For each pair of points $p,q \in P_0$, the points $p_1, p_2, q_1, q_2$ form a monochromatic crossing in $P_1$ under $\col_1$ except if $pq$ is the matching edge of $p$ or $q$. As there are $|P_0|$ matching edges in total, we have $\binom{|P_0|}{2} - |P_0|$ such crossings.
            \item[II.] Given $p\in P_0$, we investigate under which conditions $p_1, p_2$ yield a monochromatic crossing in $P_1$ with two vertices $q_i, r_j$ of different parents $q,r \in P_1$. To this end, distinguish two further subcases.
            \begin{enumerate}
                \item[IIa.] If $\hm_0(p) \notin \{q, r\}$, then $p_1, p_2, q_i, r_j$ form a crossing if and only if $q$ and $r$ lie on the same side of $p \hm_0(p)$ in $P_0$ and $\col_0(p q) = \col_0(p r)$. Since this is independent of $i$ and $j$, there are $4 \sum_{c = 1}^{k} \binom{\lset{c}{p}}{2} + \binom{\rset{c}{p}}{2}$ crossings for any given $p$.

                \item[IIb.] Otherwise, w.l.og.\ $\hm_0(p) = q$ and then $p_1, p_2, q_i, r_j$ form a crossing if $q_i$ and $r$ lie on the same side of $p \hm_0(p)$ and $\col_0(p r) = \col_0(p q) = \cbar(p)$. Since for each $r$ with $\col_0(p r) = \cbar(p)$ exactly one of the $q_i$ lies on its side of $p \hm_0(p)$, and there are two possibilities for $j$, we have a total of $2 (\lset{\cbar(p)}{p} + \rset{\cbar(p)}{p})$ such crossings at $p$.
            \end{enumerate}
                \item[III.] Finally, four points in $P_1$ that are children of distinct points in $P_0$ form a monochromatic crossing if and only if their parents do. In total, this yields $16\;\crk(P_0; \col_0)$ crossings.
        \end{enumerate}
        The formula is obtained by summing over the different types of crossings.
    \end{proof}
