\author{Alexander Erb\footnote{Technical University Darmstadt, Institute of Material Science, Physics of surfaces, Peter-Grünberg-Str. 16, 64287 Darmstadt, Germany}, Johanna Steinmann$^*$, Youngeun Lee$^*$, Robert W. Stark$^*$\footnote{Corresponding author email address: robert.stark@tu-darmstadt.de}}
