\section{An isoperimetric inequality}\label{sec:iso}

In this section, we provide an isoperimetric inequality, which is a generalization of Sanki-Vadnere's \cite[Theorem 1.1]{sanki2021conjecture}. 

\begin{thm}\label{thm:isoperim}
Let $D_1,...,D_k$ be hyperbolic $m_i$-gons with $m_i\geqslant 4$. Let $D$ be a regular $m$-gon with inner angle $\theta\geqslant\frac\pi2$. If 
\begin{enumerate}
\item\label{item:thm_isoperim_gauss} $m-4 = \sum_{i=1}^k m_i -4k$;
\item\label{item:thm_isoperim_area} $\area(D) = \sum_{i=1}^k \area(D_i)$, 
\end{enumerate}
then 
$$\perim(D)\leqslant \sum_{i=1}^k \perim(D_i).$$
The equality holds if and only if $k=1$ and $D_1$ is a regular $m$-gon with inner angle $\theta\geqslant\frac\pi2$.
\end{thm}
\subsection{Perimeter functions of regular hyperbolic polygons}
For a hyperbolic regular $n$-gon with inner angle $\theta$ and area $a$, its perimeter can be represented by 
\begin{eqnarray}
P_n(a) &=& 2n\arccosh\bracket{\frac{\cos \frac{\pi}{n}}{\sin \frac{(n-2)\pi-a}{2n}}},\text{ or } \\
\phi_{\theta}(n) &=& 2n\arccosh\bracket{\frac{\cos \frac{\pi}{n}}{\sin \frac{\theta}{2}}}. 
\end{eqnarray}
By Gauss-Bonnet theorem, area of the $n$-gon can be represented by $\theta$ and $n$:
$$	a = (\pi-\theta)n-2\pi.$$
The derivative of $P_n(x)$ to $x$ is 
\begin{equation}\label{eqn:P_derivative_to_x}
P^\prime_n(x)=\frac{\dps{\cos\frac{\pi}n\tan\frac{2\pi+x}{2n}}}{\sqrt{\dps{\cos^2\frac{\pi}n-\cos^2\frac{2\pi+x}{2n}}}}.
\end{equation}

Let
$$f(n, a, x)= P_4(x)+P_n(a-x)-P_n(a).$$
We will show that the partial derivative $\frac{\partial f}{\partial x}(n,a,x)$ is positive and $n>10$ and $3\pi<a<\bracket{\frac{n}2-2}\pi$.

From \eqref{eqn:P_derivative_to_x}, we obtain
\begin{equation}\label{eqn:f_derivative_to_x}
\frac{\partial f}{\partial x}(n,a,x)=\frac{\tan\dps{\frac{2\pi+x}{8}}}{\dps{\sqrt{\sin\frac{x}4}}} - \frac{\dps{\cos\frac{\pi}n\tan\frac{2\pi+a-x}{2n}}}{\sqrt{\dps{\cos^2\frac{\pi}n-\cos^2\frac{2\pi+a-x}{2n}}}}.
\end{equation}
Under our assumption, all terms in \eqref{eqn:f_derivative_to_x} are non-negative. $\dps{\frac{\partial f}{\partial x}(n,a,x)>0}$ if and only if
\begin{equation}\label{eqn:f_derivative_to_x_positivity_1}
\frac{\tan^2\dps{\frac{2\pi+x}{8}}}{\sin\dps{\frac{x}4}}>\frac{\dps{\cos^2\frac{\pi}n\tan^2\frac{2\pi+a-x}{2n}}}{\dps{\cos^2\frac{\pi}n-\cos^2\frac{2\pi+a-x}{2n}}}.
\end{equation}
\eqref{eqn:f_derivative_to_x_positivity_1} is equivalent to
\begin{equation}\label{eqn:f_derivative_to_x_positivity_3}
\frac{\dps{\bracket{1+\sin\frac{x}4}\bracket{\cos\frac{2\pi}{n}-\cos\frac{2\pi+a-x}{n}}\bracket{1+\cos\frac{2\pi+a-x}{n}}}}{\dps{\sin\frac{x}4\bracket{1-\sin\frac{x}4}\bracket{1+\cos\frac{2\pi}n}\bracket{1-\cos\frac{2\pi+a-x}{n}}}}>1.
\end{equation}

\begin{lemma}\label{lemma:f_derivative_to_x_positive_n_bigger_than_8}
For $n\geqslant8$, $\dps{\frac{\partial f}{\partial x}(n,a,x)>0}$ when $\frac32\pi\leqslant a \leqslant\bracket{\frac{n}2-2}\pi$ and $0<x<\min(a-\pi,2\pi)$.
\end{lemma}

\begin{proof}
We prove the following equivalent form of \eqref{eqn:f_derivative_to_x_positivity_3}. Note that we have $a-x\geqslant\pi$.
It is easy to get $\dps{\frac{1+t}{t(1-t)}\geqslant 3+2\sqrt{2}}$ when $0<t<1$. Since $a-x\geqslant\pi$, we have
$$\frac{3\pi}{n}\leqslant\frac{2\pi+a-x}{n}<\frac{2\pi+\bracket{\frac{n}2-2}\pi}{n}=\frac{\pi}2.$$
From the basic facts
$$\sin3t\leqslant 3\sin t\text{ for }0<t<\frac{\pi}2 \qquad\text{and}\qquad
\sin(t)\geqslant\frac45t\ \text{when}\ 0\leqslant t\leqslant\frac{5}{16}\pi.
$$
we have
\begin{equation*}
\frac{\dps{\cos\frac{2\pi}{n}-\cos\frac{2\pi+a-x}{n}}}{\dps{1-\cos\frac{2\pi+a-x}{n}}}\geqslant \frac{\dps{\cos\frac{2\pi}{n}-\cos\frac{3\pi}{n}}}{\dps{1-\cos\frac{3\pi}n}}
=\frac{\dps{\sin\frac{5\pi}{2n}\sin\frac{\pi}{2n}}}{\dps{\sin^2\frac{3\pi}{2n}}}
\geqslant \frac13\cdot\frac{\dps{\sin\frac{5\pi}{2n}}}{\dps{\sin\frac{3\pi}{2n}}}
\geqslant \frac13\cdot \frac{\dps{\frac45\cdot\frac{5\pi}{2n}}}{\dps{\frac{3\pi}{2n}}}=\frac{4}{9}.
\end{equation*}
Therefore
$$\text{LHS of \eqref{eqn:f_derivative_to_x_positivity_3}}\geqslant (3+2\sqrt{2})\cdot \frac{4}{9}\cdot\frac{1}{2}\sim 1.29521>1.$$
\end{proof}

The following lemma is a generalization of \cite[Lemma 6.3]{sanki2021conjecture}. 

\begin{lemma}\label{lemma:Pn_second_derivative}
	When $n \geqslant 4$, $P''_n(x)$ has a unique zero in $(0,n\pi-2\pi)$ and is negative in the left of this zero, positive in the right of this zero. 
	\label{lem:convex_derivative}
\end{lemma}

\begin{proof}
From \eqref{eqn:P_derivative_to_x}, we get
\begin{equation}
	P_n''(x) = \frac{\cos \frac{\pi}{n} \sin^{-2} \frac{(n-2) \pi -x}{2n}}{2n \sqrt{\cos^2 \frac{\pi}{n} - \sin^{2} \frac{(n-2) \pi -x}{2n}}}
	- \frac{\cos \frac{\pi}{n} \cos^{2} \frac{(n-2) \pi -x}{2n}}
	{2n \left(\cos^2 \frac{\pi}{n} - \sin^{2} \frac{(n-2) \pi -x}{2n}\right)^{ \frac{3}{2}}}.
\end{equation}
$P_n''(x) \geqslant 0$ if and only if
$$\frac{\cos \frac{\pi}{n} \sin^{-2} \frac{(n-2) \pi -x}{2n}}{2n \sqrt{\cos^2 \frac{\pi}{n} - \sin^{2} \frac{(n-2) \pi -x}{2n}}} \geqslant \frac{\cos \frac{\pi}{n} \cos^{2} \frac{(n-2) \pi -x}{2n}}{2n \left(\cos^2 \frac{\pi}{n} - \sin^{2} \frac{(n-2) \pi -x}{2n}\right)^{ \frac{3}{2}} },$$
$$\cos^2 \frac{\pi}{n} - \sin^{2} \frac{(n-2) \pi -x}{2n} \geqslant \sin^2\frac{(n-2) \pi -x}{2n} \cos^2\frac{(n-2) \pi -x}{2n},$$
and equivalently,
$$\cos^2 \frac{\pi}{n} \geqslant \sin^{2} \frac{(n-2) \pi -x}{2n} + \sin^2\frac{(n-2) \pi -x}{2n} \cos^2\frac{(n-2) \pi -x}{2n}.$$

Since $t\mapsto \sin^2(t) + \sin^2(t)\cos^2(t)$ is injective when  $t\in (0,\pi/2)$, then $P_n''(x)$ has at most one zero in $(0,n\pi-2\pi)$. Since $\dps{\lim_{x\to 0+}P_n'(x) = +\infty}$ and $\dps{\lim_{x\to (n\pi-2\pi)-}P_n'(x) = +\infty}$ by \eqref{eqn:P_derivative_to_x}, $P_n''(x)$ has exactly one zero in $(0,n\pi-2\pi)$ and the lemma follows. 

\end{proof}

\begin{lemma}\label{lemma:Pn(x)_by_x_decreasing}
For $n=7,8,9,10$, $\dps{\frac{P_n(x)}x}$ is decreasing on $\dps{\bracket{0,\bracket{\frac{n}2-2}\pi}}$.
\end{lemma}

\begin{proof}
Since 
$$\frac{\dd{}}{\dd{x}}\bracket{\frac{P_n(x)}x}=\frac{xP_n^\prime(x)-P_n(x)}{x^2},$$
it suffices to show $xP_n^\prime(x)-P_n(x)<0$. The derivative of $xP_n^\prime(x)-P_n(x)$ is $xP^{\prime\prime}_n(x)$. By Lemma \ref{lemma:Pn_second_derivative}, $xP_n^\prime(x)-P_n(x)$ reaches its 
maximum at $0$ or $\bracket{\frac{n}2-2}\pi$. We have
$$\lim_{x\to0+}(xP^{\prime}_n(x)-P_n(x))=\lim_{x\to0+}xP^{\prime}_n(x)=0$$
It remains to show that 
\begin{equation*}
P_n\bracket{\bracket{\frac n2-2}\pi}> P_n^\prime\bracket{\bracket{\frac n2-2}\pi} \cdot \bracket{\frac n2-2}\pi,
\end{equation*}
which can be simplified as (by \eqref{eqn:P_derivative_to_x})
\begin{equation}\label{eqn:Pn(x)_by_x_decreasing_1}
2n\arccosh \bracket{\sqrt{2} \cos \frac{\pi}{n}}>\bracket{\frac n2-2}\pi\cdot \frac{\dps{\cos\frac{\pi}n}}{\sqrt{\dps{\cos^2\frac{\pi}n-\frac12}}}=\bracket{\frac n2-2}\pi\cdot\frac{\dps{\sqrt{2}\cos\frac{\pi}n}}{\dps{\sqrt{\cos\frac{2\pi}n}}}.
\end{equation}
For $n=7,8,9,10$, we have 
$$\frac32>\sqrt{2}\cos\frac{\pi}{n}>\sqrt{2}\cos\frac{\pi}{7}>\frac54,$$
hence, combining the basic fact
$$\arccosh(x)>0.55 x\quad\text{for}\quad\frac54<x<\frac32,$$
we have
$$2n\arccosh \bracket{\sqrt{2} \cos \frac{\pi}{n}}>1.1 \cdot n\cdot\sqrt{2}\cos\frac{\pi}n,$$
Then \eqref{eqn:Pn(x)_by_x_decreasing_1} reduces to the basic fact
$$1.21\cos\frac{2\pi}n-\bracket{\frac\pi2-\frac{2\pi}n}^2>0\quad\text{for}\quad n=7,8,9,10.$$
\end{proof}

We note that Lemma \ref{lemma:Pn(x)_by_x_decreasing} does not hold for large $n$, say $n>20$.

We will need the following result from \cite{sanki2021conjecture}.

\begin{prop}[Sanki-Vadnere]\label{prop:prep}
$\phi_{\theta}(n)$ and $P_n(x)$ satisfy the following properties:
\begin{enumerate}
\item\label{prop:phimono}
If we treat $\phi_{\theta}(n)$ as a function of $n$ defined on $\mathbb{R}_+$, then $\phi_{\theta}(n)$ is positive and strictly concave when $n\in (\frac{2\pi}{\pi-\theta}, +\infty)$ and $\phi_\theta(\frac{2\pi}{\pi-\theta})=0$. Moreover, a hyperbolic regular polygon with inner angle $\theta$ contains at least $\left\lfloor \frac{2\pi}{\pi-\theta} \right\rfloor +1 $ edges. (\cite[Lemma 7.1]{sanki2021conjecture}) 
\item\label{prop:pmono}
For $a\in \mathbb{R}_+$ and $n\in ( \frac{a}{\pi}+2,+\infty)$, $P_n(a)$ is strictly decreasing in $n$. (\cite[Lemma 5.1]{sanki2021conjecture})
\item\label{prop:pconcave}
$P_n(x) -P_{n+1}(x)\geqslant 0$, when $x\geqslant 0$; $P_n(x) -P_{n+1}(x)$ is monotonically increasing in $x$. (\cite[Proposition 4.1]{sanki2021conjecture})
\end{enumerate}
\end{prop}

\subsection{Isoperimetric inequality for two polygons}

We first prove the following proposition.

\begin{prop}\label{lem:four_edge}
For $n\geqslant 5$, $0 \leqslant a \leqslant  \bracket{\frac{n}{2}- 2}\pi$ and $0 \leqslant x\leqslant \min(a,2\pi)$, we have $f(n,a,x)\geqslant0$, that is,
\begin{equation}\label{eqn:four_edge}
P_4(x)+P_n(a-x)\geqslant P_n(a).
\end{equation}
The equality of \eqref{eqn:four_edge} holds if and only if $x=0$. 
\end{prop}


We make the following induction on $n$.

\begin{lemma}\label{cor:inequality_induction}
For $n\geqslant5$, if $a\in\gauss{0, \bracket{\frac{n}{2}- 2}\pi}$ and $x\in \gauss{0, \min(a,2\pi)}$ satisfies
$$P_4(x)+P_n(a-x)\geqslant P_n(a),$$
then 
$$P_4(x)+P_{n+1}(a-x)\geqslant P_{n+1}(a).$$
\end{lemma}

\begin{proof}
\begin{equation*}
\begin{aligned}
 & P_4(x)+P_{n+1}(a-x) \\
=& P_4(x) + P_n(a-x) + (P_{n+1}(a-x) -P_n(a-x) )\\
\ge& P_4(x) + P_n(a-x) + (P_{n+1}(a) -P_n(a) )  & \bracket{\text{By Proposition \ref{prop:prep}} (\ref{prop:pconcave})}\\
\ge& P_4(0) + P_n(a)+ (P_{n+1}(a) -P_n(a) ) & \bracket{\text{By induction}}\\ 
=& P_{n+1}(a). 
\end{aligned}
\end{equation*}
\end{proof}

\begin{proof}[Proof of Proposition \ref{lem:four_edge}]
By Proposition \ref{prop:prep}, $P_4(x)+P_m(a-x)\geqslant P_m(x)+P_m(a-x)$. 
$P_n(x)$ satisfies
\begin{equation*}
(P^\prime_n(x))^2=\frac{\dps{\cos^2\frac{\pi}n\tan^2\frac{2\pi+x}{2n}}}{\dps{\cos^2\frac{\pi}n-\cos^2\frac{2\pi+x}{2n}}}=\frac{\dps{\cos^2\frac{\pi}{n}\cdot\bracket{1-\cos^2\frac{2\pi+x}{2n}}}}{\dps{\cos^2\frac{2\pi+x}{2n}\cdot\bracket{\cos^2\frac{\pi}n-\cos^2\frac{2\pi+x}{2n}}}}.
\end{equation*}
Let $y=\cos^2\frac{2\pi+x}{2n}$ and $\kappa=\cos^2\frac{\pi}{n}$, then $y\in\left[\frac12,\kappa\right)$. The function $\dps{\frac{\kappa(1-t)}{t(\kappa-t)}}$ is strictly increasing on $(1-\sqrt{1-\kappa}, \kappa)$. It follows that $P_n^\prime(x)$ is decreasing and $P_n^{\prime\prime}(x)<0$ on $\left(0, \bracket{\frac{n}2-2}\pi\right)$ and  $P_n(x)$ is strictly concave on $\left[0, \bracket{\frac{n}2-2}\pi\right]$ when $n=5,6$. We remark that $1-\sqrt{1-\kappa}\leqslant\frac12$ requires $n\leqslant6$ and the concavity does not work for $n>6$. Therefore, for $n=5,6$ we have
$$P_n(x)+P_n(a-x)\geqslant P_n(0)+P_n(a) = P_n(a).$$ 

For $n=7,8,9,10$, by Lemma \ref{lemma:Pn(x)_by_x_decreasing}, we have
$$\frac{P_n(x)}{x}\geqslant \frac{P_n(a)}{a},\quad\text{and} \quad \frac{P_n(a-x)}{a-x}\geqslant \frac{P_n(a)}{a}.$$
Hence
$$P_n(x)+P_n(a-x)\geqslant \frac{x}{a}\cdot P_n(a)+\frac{a-x}{a}\cdot P_n(a)=P_n(a),$$
and \eqref{eqn:four_edge} follows from $P_4(x)\geqslant P_n(x)$ for $n>4$.

For $n>10$, when $a\leqslant3\pi$, the conclusion comes from the result for $n=10$ and induction on $n$ by Lemma \ref{cor:inequality_induction}. When $a\geqslant 3\pi$, the lemma follows from $f(n,a,0)\equiv0$ and $\frac{\partial f}{\partial x}(n,a,x)>0$ when $0<x<2\pi$ (Lemmas \ref{lemma:f_derivative_to_x_positive_n_bigger_than_8}).

In all of the three cases, the concerned functions are strictly increasing or strictly decreasing or strictly concave. Thus the equality holds only when $x=0$. 
\end{proof}

Now we are ready to prove the isoperimetric theorem when $k=2$. 

\begin{prop}
Let $D_1$, $D_2$ be regular hyperbolic $m_1$- and $m_2$-gons with positive areas. Let $D$ be a regular hyperbolic $m$-gon with inner angle $\theta \geqslant \frac{\pi}{2}$. If $m+4 = m_1+m_2$ and $\area(D)=\area(D_1)+\area(D_2)$, then 
%$$\phi_{\theta}(m) \leqslant \phi_{\theta_1}(m_1) + \phi_{\theta_2}(m_2).$$
$$\perim(D)<\perim(D_1) + \perim(D_2).$$

%The equality holds only if $m_1, m_2$ are at the boundary of their domain of definition. 
	\label{prop:k=2}
\end{prop}

\begin{proof}
Let $\theta_1$ and $\theta_2$ be the inner angles of $D_1$ and $D_2$ respectively.
By Gauss-Bonnet theorem, $\area(D)=\area(D_1)+\area(D_2)$ is equivalent to 
\begin{equation}\label{equ:area}
%	(\pi-\theta)m - 2\pi &=& (\pi-\theta_1)m_1 - 2\pi + (\pi-\theta_2)m_2 - 2\pi \nonumber \\
	(\pi-\theta)m - 2\pi = (\pi-\theta_1)m_1 - 2\pi + (\pi-\theta_2)(m+4-m_1) - 2\pi. 
\end{equation}

	%For $\phi_{\theta_1}(m_1)$, $m_1 \geqslant \frac{2\pi}{\pi-\theta}$ is equivalent to $\phi_{\theta_1}(m_1) \geqslant 0$. Therefore, 
	Consider the function
	\begin{equation}
		F(m_1) = \phi_{\theta_1}(m_1)+\phi_{\theta_2}(m_2) = \phi_{\theta_1}(m_1)+\phi_{\theta_2}(m+4-m_1).
		\label{equ:phi}
	\end{equation}

	We treat $\theta_1, \theta_2, m$ as constants, then (\ref{equ:phi}) is a function in $m_1$. Our aim is to prove the minimum of this function in its domain is greater or equal to $\phi_\theta(m)$. 

	By Proposition \ref{prop:prep}, $\phi_{\theta_1}(m_1)+\phi_{\theta_2}(m+4-m_1)$ is defined on $\{m_1|m_1 \geqslant \max(4,\frac{2\pi}{\pi-\theta_1}), m+4-m_1 \geqslant \max(4,\frac{2\pi}{\pi-\theta_2}) \}$, namely $m_1\in [\max(4,\frac{2\pi}{\pi-\theta_1}),\min(m, m+4 - \frac{2\pi}{\pi-\theta_2})] $, and is strictly concave in this domain. 
	Therefore, the minimum of $\phi_{\theta_1}(m_1)+\phi_{\theta_2}(m+4-m_1)$ is obtained at the domain end points $\max(4,\frac{2\pi}{\pi-\theta_1})$ or $\min(m, m+4 - \frac{2\pi}{\pi-\theta_2})$. 

	First we consider the case $m_1 = \max(4,\frac{2\pi}{\pi-\theta_1})$. 

	If $\max(4,\frac{2\pi}{\pi-\theta_1}) = 4$, we consider $F(4) = \phi_{\theta_1}(4) + \phi_{\theta_2}(m)$. We let $x = area(D_1)$,  $a = area(D)$ and $a-x = area(D_2)$. Then $\phi_{\theta_1}(4) = P_4(x)$, $\phi_{\theta_2}(m) = P_m(a-x)$ and $\phi_\theta(m) = P_m(a)$. By Proposition \ref{lem:four_edge}, $P_4(x) + P_m(a-x) \geqslant P_m(a)$, namely $F(4) = \phi_{\theta_1}(4) + \phi_{\theta_2}(m) \geqslant \phi_\theta(m)$. 

	If $\max(4,\frac{2\pi}{\pi-\theta_1}) = \frac{2\pi}{\pi-\theta_1}$, we consider $F(\frac{2\pi}{\pi-\theta_1})$. Then $\phi_{\theta_1}(\frac{2\pi}{\pi-\theta_1}) = 0$, $F(\frac{2\pi}{\pi-\theta_1}) = 0 + \phi_{\theta_2}(m+4 - \frac{2\pi}{\pi-\theta_1})$. 
	By (\ref{equ:area}), let $m_1 = \frac{2\pi}{\pi-\theta_1}$, then 
	\[
	(\pi-\theta)m - 2\pi =   (\pi-\theta_2)\left(m+4-\frac{2\pi}{\pi-\theta_1}\right) - 2\pi. 
	\]
Let $a = 
(\pi-\theta)m - 2\pi =   (\pi-\theta_2)\left(m+4-\frac{2\pi}{\pi-\theta_1}\right) - 2\pi$. Then $\phi_\theta(m) = P_m(a)$ and   $F(\frac{2\pi}{\pi-\theta_1}) = 0 + \phi_{\theta_2}(m+4 - \frac{2\pi}{\pi-\theta_1}) = P_{m+4 - \frac{2\pi}{\pi-\theta_1}}(a)$. Since $\max(4,\frac{2\pi}{\pi-\theta_1}) = \frac{2\pi}{\pi-\theta_1}$, $m+4 - \frac{2\pi}{\pi-\theta_1} < m$. Therefore by Proposition \ref{prop:prep}(\ref{prop:pmono}), $ P_{m+4 - \frac{2\pi}{\pi-\theta_1}}(a) > P_m(a)$, namely $F(\frac{2\pi}{\pi-\theta_1}) > \phi_\theta(m)$. 

If $m_1 = \min(m, m+4 - \frac{2\pi}{\pi-\theta_2})$, the proof is exactly the same as the case $m_1 = \max(4,\frac{2\pi}{\pi-\theta_1})$. 
\end{proof}

\begin{cor}
	%Let $m_1+m_2 = m+4$, 
Let $D$ be a regular hyperbolic $m$-gon with inner angle $\theta\geqslant\frac\pi2$, and $D_1$ and $D_2$ be hyperbolic $m_1$- and $m_2$-gons respectively, $m_1+m_2 = m+4$. If $area(D_1)+ area(D_2) = area(D)$, $perim(D_1) + perim(D_2) = perim(D)$, $m_1 \geqslant m_2$, then $D_1 =D$, $D_2$ is a degenerated polygon with area and perimeter $0$. 
	\label{cor:equal}
\end{cor}

\begin{proof}
	By the proof of Proposition \ref{prop:k=2}, if $\phi_{\theta_1}(m_1)+ \phi_{\theta_2}(m_2) = \phi_{\theta}(m)$, then $m_1=m$ and $m_2 =4$. By Proposition \ref{lem:four_edge}, if $P_4(x)+P_m(a-x) = P_m(a)$, then $x=0$ and this corollary follows. 
\end{proof}


\subsection{General case}
We prove the isoperimetric theorem in this subsection by induction. 

\begin{lemma}
	Let $D_i$ be regular hyperbolic $m_i$-gons with inner angle $\theta_i$, $i = 1,...,k$. $\theta_1 \geqslant \theta_2 \geqslant ... \geqslant \theta_k$. Let $D$ be a regular hyperbolic $m$-gon with inner angle $\theta \geqslant \frac{\pi}{2}$. If 
	\begin{enumerate}
		\item $\sum_{i=1}^{k}\area(D_i) =\area(D)$ ; \label{cond:area}
		\item $m -4 =\sum_{i=1}^{k} m_i -4k $. \label{cond:euler}
	\end{enumerate}
	Then 
	\begin{enumerate}
		\item $\theta_1 \geqslant \frac{\pi}{2}$ ;
		\item $\theta_k \leqslant \theta$. 
	\end{enumerate}
	\label{lem:induction}
\end{lemma}
\begin{proof}
	By Gauss-Bonnet theorem, $\area(D_i) = (\pi-\theta_i)m_i - 2\pi$. Therefore, the condition (\ref{cond:area}) is equivalent to 
	\[
		\pi\sum_{i=1}^{k} m_i - \sum_{i=1}^{k} m_i \theta_i - 2k\pi = (\pi-\theta)m - 2\pi. 
	\]
	Using the condition (\ref{cond:euler}), we get 
	\[
		(2k-2)\pi + m\theta = \sum_{i=1}^{k} m_i \theta_i. 
	\]
Then 
\begin{eqnarray*}
		(4k-4+m)\frac{\pi}{2} =	(2k-2)\pi + m \frac{\pi}{2} 
				      \leqslant (2k-2)\pi + m\theta 
				      = \sum_{i=1}^{k} m_i \theta_i 
				     \leqslant  \sum_{i=1}^{k} m_i \theta_1 = (m+4k-4)\theta_1.
\end{eqnarray*}
Hence $\theta_1 \geqslant \frac{\pi}{2}$. On the other hand
	\begin{eqnarray*}
		(4k-4+m)\theta =	(4k-4)\theta + m \theta 
				      \geqslant (2k-2)\pi + m\theta 
				      = \sum_{i=1}^{k} m_i \theta_i 
				     \geqslant  \sum_{i=1}^{k} m_i \theta_k = (m+4k-4)\theta_k.
	\end{eqnarray*}
	Hence $\theta_k \leqslant \theta$. 
\end{proof}
Now we are ready to prove the isoperimetric theorem
\begin{proof}[Proof of Theorem \ref{thm:isoperim}]
	Without loss of generality, we assume the inner angle of $D_i$ is $\theta_i$ and $\theta_1 \geqslant \theta_2 \geqslant ... \geqslant \theta_k$. We consider a series of hyperbolic regular polygons $ \widetilde{D}_1, \widetilde{D}_2,..., \widetilde{D}_k$. 
	$\widetilde{D}_j$ is defined as the polygon with $ \widetilde{m}_j:= \sum_{i=1}^{j} m_i -4j+4$ edges and area equals to $\sum_{i=1}^{j}\area(D_i)$. 
	%The polygon $ \widetilde{D_j}$ has $ \widetilde{m_j}$ edges and inner angle $ \widetilde{\theta_j}$. 
	\begin{lemma}
		The inner angle of $ \widetilde{D}_j $ (denoted as $ \widetilde{\theta_j}$) is greater or equal than $ \frac{\pi}{2}$. 
		\label{lem:angle}
	\end{lemma}
	\begin{proof}
		%By Lemma \ref{lem:induction}, \widetilde{\theta_j} \geqslant \frac{\pi}{2}$. 
		We prove it by induction. 
		We observe that $\area(\widetilde{D}_k) = \sum_{i=1}^{k}\area(D_i)=\area(D)$ and $ \widetilde{m}_k = \sum_{i=1}^{k} m_i -4k+4 = m$. Therefore $\widetilde{D}_k$ is isometric to  $D$, hence $ \widetilde{\theta}_k = \theta \geqslant \frac{\pi}{2}$. 

		Assume $ \widetilde{\theta}_j \geqslant \frac{\pi}{2}$, then it is sufficient to prove that $ \widetilde{\theta}_{j-1} \geqslant \frac{\pi}{2}$. Applying Lemma \ref{lem:induction} to $D_1,D_2,...,D_j$, we have $\theta_j \leqslant \widetilde{\theta}_j$. 
		Then we consider $\widetilde{D}_{j-1}$, $D_j$ and $\widetilde{D}_j$. 
		We mention that from the definition of $ \widetilde{m}_j$ and $\area(\widetilde{D}_j) = \area(\widetilde{D}_{j-1})+\area(D_{j})$, we have 
		\begin{equation}
			\widetilde{m}_j +4 = \widetilde{m}_{j-1}+ m_j ; \widetilde{m}_j\widetilde{\theta}_j + 2\pi = \widetilde{m}_{j-1}\widetilde{\theta}_{j-1} + m_j \theta_j. 
		\label{equ:twopolygon}	
		\end{equation}
		If $\widetilde{\theta}_{j-1}\geqslant \theta_j$, then by Lemma \ref{lem:induction}, $\widetilde{\theta}_{j-1}\geqslant \frac{\pi}{2}$. If $\widetilde{\theta}_{j-1}< \theta_j$, then $\widetilde{\theta}_{j-1}< \theta_j \leqslant  \widetilde{\theta}_j$. By \eqref{equ:twopolygon}, 
		\[
			\widetilde{m}_j\widetilde{\theta}_j + 2\pi = \widetilde{m}_{j-1}\widetilde{\theta}_{j-1}+ m_j \theta_j > (\widetilde{m}_{j-1}+ m_j) \widetilde{\theta}_j= (\widetilde{m}_j+4)\widetilde{\theta}_j. 
		\]
		Hence $ \widetilde{\theta}_j< \frac{\pi}{2}$, which contradicts to the assumption $ \widetilde{\theta_j} \geqslant \frac{\pi}{2}$. 
		%by \ref{lem:induction}, 
		%< \frac{\pi}{2}
	\end{proof}
	The $k=2$ case has been proved in Proposition \ref{prop:k=2}. Assume this inequality is true for $k-1$ polygons. The remaining work is to prove the isoperimetric theorem for $k$ polygons $D_1,...,D_k$. By Lemma \ref{lem:angle}, the inner angle $ \widetilde{\theta}_2$ of $ \widetilde{D}_2$ is greater or equal than $ \frac{\pi}{2}$. Therefore by Proposition \ref{prop:k=2}, $$\perim( \widetilde{D}_2) \leqslant\perim(D_1)+\perim(D_2). $$
Then for the polygons $ \widetilde{D}_2, D_3,...,D_k$, it is easy to check that $$ \widetilde{m}_2 + \sum_{i=3}^k m_i - 4(k-1) = m -4.$$ Therefore by induction, 
$$\perim(D) \leqslant \perim( \widetilde{D}_2) + \sum_{i=3}^k \perim(D_i) \leqslant \sum_{i=1}^k \perim(D_i) .$$ 
If $\perim(D) = \sum_{i=1}^k\perim(D_i) $, then 
$$\perim(D) = \perim( \widetilde{D}_2) + \sum_{i=3}^k\perim(D_i) = \sum_{i=1}^k\perim(D_i) .$$ 
Therefore $$\perim( \widetilde{D}_2) = \perim(D_1) + \perim(D_2).$$ 
By Corollary \ref{cor:equal}, $\widetilde{D}_2$ equals $D_1$ or $D_2$ and the other polygon is a quadrilateral with $0$ area and perimeter. Without loss of generality, we assume $\widetilde{D}_2= D_1$. Thus 
$$\perim(D) =\perim( \widetilde{D}_2) + \sum_{i=3}^k \perim(D_i) = \perim(D_1) + \sum_{i=3}^k\perim(D_i).$$
By induction, $k=1$ and $D= D_1$. 
	%If the equality holds, to show $k=1$ and $D_1 = D$, by the induction above, it is sufficient to show this when there are two polygons. 

	%By Proposition \ref{lem:k=2} and \ref{lem:four_edge}, the equality holds only if $k=1$ and $D_1=D$. 
\end{proof}

The following example shows that Theorem \ref{thm:isoperim} does not hold if triangles are allowed.

\begin{example}\label{emp:triangle_fail}
Let $D_1$ be a regular hexagon with area $x$ and $D_2$ be a regular triangle with area $a-x$. Let $D$ be a regular pentagon with area $a$. Then the conditions \eqref{item:thm_isoperim_gauss} and \eqref{item:thm_isoperim_area} in Theorem \ref{thm:isoperim} are satisfied. If the isoperimetric inequality holds, then
\begin{equation}\label{eqn:example_triangle_fail}
P_{6} (x) + P_3(a-x) \geqslant P_5(a).
\end{equation}

However, by Proposition \ref{prop:prep}(\ref{prop:pmono}), we have
$$\lim_{x\to a-}\bracket{P_6(x)+P_3(a-x)}=P_6(a)<P_5(a)$$
Thus for $x$ sufficiently close to $a$, we have $P_{6} (x) + P_3(a-x) < P_5(a)$. In fact, a direct computation show that $P_6(4.99)+P_3(0.01)+\frac12<P_5(5)$, which fails \eqref{eqn:example_triangle_fail}.
\end{example}

