\subsubsection{Isotropic ADC}
A surface $\tw$ is said to exhibit isotropic ADC if $\ka_A(\tw; \p)$ remains constant for all directions $\p$. In this case, the ADC equals its average value $\ka_A^{\mathrm{Avg}}$, thus the upper bound in Theorem~\ref{thm:tpms-opt-adc} applies uniformly in all directions:
\begin{theorem}
	If $\tw$ exhibits isotropic ADC, then
	\begin{equation}
		\label{eq:iso-cub-cons-bound}
		\ka_A(\tw)\le \frac{2}{3}\ka,
	\end{equation}
	and  equality holds if and only if $\tw$ is a TPMS (with isotropic ADC).
\end{theorem}


A typical class of surfaces with isotropic ADC are those with cubic symmetry.
This is claimed by Neumann’s principle~\cite{nye1985physical}, which states that cubic lattices always exhibit isotropic effective conductivity.
We can also show that  the RHS in~\eqref{eq:ka-upp-bound-p3}  simplifies to the constant $\frac{2}{3}\ka$ in this special case (see Lemma~\ref{lm:cubic-srf-int}).

\subsubsection{Associate family}
In addition to cubic-symmetric TPMS, Theorem~\ref{thm:adc-upper-bound} suggests a broader class of surfaces that achieve optimal isotropic ADC.
Specifically, it implies that the ADC of TPMS in a given direction $\p$ is determined solely by the distribution of its normal vectors.
It is well known that each minimal surface belongs to an associate family, comprising minimal surfaces that share  identical Weierstrass data and differ only by a Bonnet rotation~\cite{lawson-minsurf,conj-surf}.
A fundamental  property of such families is that all member surfaces  have the same normal vector distribution,  and thus exhibit the same ADC.
One typical example is the Schwarz D family, which includes Schwarz P and Gyroid surfaces (Figure~\ref{fig:asso-family}).
Despite the Gyroid and Schwarz D not being cubic-symmetric, they retain isotropic ADC due to the inclusion in the  family of Schwarz P, which is cubic-symmetric.


\subsection{Relation to Hashin-Shtrikman bound}
We stress that the upper bound in~\eqref{eq:iso-cub-cons-bound} aligns with the classical Hashin–Shtrikman (HS) upper bound~\cite{hashin1962variational,PABST2007479}, which provides a theoretical limit on the effective conductivity of isotropic composites. For a given volume fraction $\rho(\toe)$, the HS bound is given by:
\begin{equation}
	\label{eq:hs-bound-iso}
	\ka_\eps(\tw)  \le \ka^{HS}\pr{\rho(\toe)}:= \frac{2\rho(\toe)}{3-\rho(\toe)} \ka.
\end{equation}
Applying this bound to the definition of ADC yields:
\begin{equation}
	\kappa_A(\tilde\omega)\le \limsup_{\epsilon\to0}\frac{\kappa_\epsilon(\tilde\omega)}{\rho_\epsilon(\tilde\omega)}\le\lim_{\rho\to0}\frac{\ka^{HS}\pr{\rho}}{\rho}=\frac{2}{3}\kappa,
\end{equation}
which is exactly the asymptotic bound in~\eqref{eq:iso-cub-cons-bound}.
Therefore, our theorems suggest that \emph{any cubic TPMS shell lattice achieves the HS upper bound when the volume fraction is sufficiently small}.


\subsection{Third-order accuracy of ADC}
By definition~\eqref{eq:dir-asymp-cond}, the asymptotic directional conductivity $\ka_A(\tw; \p)$ captures the leading-order (first-order) behavior of the effective directional conductivity as the shell thickness $\eps$ tends to zero.
Interestingly, we show that this approximation is significantly more accurate, achieving third-order precision in $\eps$.
\begin{theorem}
	\label{thm:adc-3-order}
	The ADC of $\tw$ satisfies
	\begin{equation}
		\label{eq:adc-3-order}
		\ka_\eps(\tw;\p) -\frac{2\eps|\tw|}{|Y|}\ka_A(\tw;\p)\sim O(\eps^3) \quad as\,\,\eps\to0.
	\end{equation}
\end{theorem}
Here, the term ${2\eps |\tw|}/{|Y|}$ corresponds to the first-order approximation of the volume fraction $\rho_\eps(\tw)$.
The detailed proof of this result is provided in the \ref{app:third-oder-acc}, and numerical validation is presented in Section~\ref{sec:3order-acc}.

\begin{remark}
	The factor ${2\eps |\tw|}/{|Y|}$ in~\eqref{eq:adc-3-order} can be replaced by the full volume fraction $\rho_\eps(\tw)$, as the difference between them is also $O(\eps^3)$. See Lemma~\ref{lem:vol-remainder} for details.
\end{remark}



\section{Discretization}
\label{sec:discrete}
We discretize the continuous surface $\tw$ using a triangular mesh consisting of a set of vertices $\mathcal{V}$, edges $\mathcal{E}$, and faces $\mathcal{F}$. 
In Section~\ref{sec:dis-adc-form}, we first describe the numerical evaluation of the ADC matrix $\k_A$. 
Then, in Section~\ref{sec:shap-opt}, we derive the $L^2$ gradient of the ADC under normal deformation, which is used in a gradient descent flow for our shape optimization algorithm.

\subsection{Evaluation of ADC matrix}
\label{sec:dis-adc-form}
Following  the derivation of~\eqref{eq:kap-ku2},  we rewrite~\eqref{eq:bar-k-A-expr} in the form
\begin{equation}
	\begin{aligned}
		k_A^{ij}&= \frac{1}{|\tw|}\int_{\tw}\left(\e^i_{\tw}\cdot\e^j_{\tw} -\nabla\bar u^i\cdot\nabla\bar u^j\right).  \\
	\end{aligned}
\end{equation}
Using the identity
\begin{equation}
	\e^i_{\tw}\cdot\e^j_{\tw} = (\e^i\cdot\e^j) - (\e^i\cdot\n)(\e^j\cdot\n)=\delta_{ij}-n_in_j,
\end{equation}
we obtain the following matrix expression for the ADC:
\begin{equation}
	\begin{aligned}
		\k_A=\ka\pr{\I-\frac{1}{|\tw|}\int_{\tw}\n\n^\top-\mathbf{R}},
	\end{aligned}
\end{equation}
where $\mathbf I$ is the identity matrix, and $\mathbf{R}$ is given by
\begin{equation}
	\label{eq:asym-mat-L-def}
	[\mathbf R]^{ij} = -\frac{1}{|\tw|}\int_{\tw} \bar u^i\Delta \bar u^j,
\end{equation}
using the identity $\int_{\tw}\nabla\bar u^i\cdot\nabla\bar u^j=-\int_{\tw}\bar u^i\Delta \bar u^j$  through integration by parts.


The computation of $\k_A$ thus involves the following three steps:
\begin{itemize}
	\item Evaluate the integral $\int_{\tw}\n\n^\top$.
	We approximate this integral by 
	\begin{equation}
		\int_{\tw}\n\n^\top\approx \sum_{f\in \mathcal F} \n_f\n_f^\top A_f,
	\end{equation}
	where $\n_f$ denotes the normal vector of triangular face $f$.
	The notation $A_f$ denotes the area of $f$.

	\item Solve  for solution $\bar u^i$ from the equation $\Delta u=-\div\p_{\tw}$ on $\tw$ with $\p=\e_i$, i=1,2,3. We first represent $\bs p_{\tw}$ as its line integral on edges $\mathcal E$.
	Suppose $e_{ij}\in\mathcal E$ denotes the edge linking $\bs v_i\in\mathcal V$ to $\bs v_j\in\mathcal V$,  we assign a variable $p_{ij}$ to it, given by
	\begin{equation}
		p_{ij} := \int_{e_{ij}} \p_{\tw}\cdot d\r=\int_{e_{ij}}\p \cdot d\r \approx\p\cdot \pr{\bs v_j - \bs v_i}.
	\end{equation}
	The second equality holds because each edge is regarded as the geodesic path on $\tw$ and thus $d\r$ is tangent on $\tw$. 
	Then the divergence at vertex $v_i$ is approximated by its integral as
	\begin{equation}
		\rho_{v_i} :=-\int_{A_{v_i}} \div\p_{\tw}\itd\tw \approx -\sum_{v_j\in N(v_i)} w_{ij} p_{ij},
	\end{equation}
	where $N(v_i)$ signifies the set of adjacent vertices of $v_i$; the notation $w_{ij}$ denotes the cotangent weight and $A_{v_i}$ signifies the local averaging region~\cite{pmp-book} at vertex $\bs v_i$.
	Next, we stack all $\rho_{v_i}$ into a vector $\bs \rho=(\rho_{v_1},\rho_{v_2},\cdots,\rho_{v_n})^\top$, and represent the unknown as a vector $\bs u=\pr{u_{v_1}, u_{v_2},\cdots,u_{v_n}}^\top$, which stores the value of the solution $u$ at each vertex.  
	The Laplace operator $\Delta$ is discretized as the cotangent Laplacian matrix $\mathbf L$~\cite{pmp-book}.
	Then~\eqref{eq:u-div-eq-hp3} is discretized into the following linear equation
	\begin{equation}
		\label{eq:discr-poisson-eq}
		\mathbf L \bs u = \bs{ \rho}.
	\end{equation}
	After solving $\bs u$ from this equation, we obtain the solution's value at each vertices.
	We repeat this process with $\p=\e_i$, $i=1,2,3$ and denote the corresponding $\bs\rho$ and solution $\bs u$ as $\bs\rho^i$ and $\u^i$, respectively.
	\item Evaluate integral $\int_{\tw} \bar u^i\Delta \bar u^j$. We approximate it as 
	\begin{equation}
		\int_{\tw} \bar u^i\Delta \bar u^j \approx \u^i \cdot \bs\rho^j.
	\end{equation}
	Here, we have utilized the relation $\Delta \bar u^j = -\div\p_{\tw}$ where $\p=\e_j$.
\end{itemize}
The accuracy and convergence rate of this approximation are investigated in Section~\ref{sec:dis-conv-rate}. 

\subsection{Shape optimization}
\label{sec:shap-opt}
We adopt the shape optimization framework introduced in~\cite{ads} to optimize the ADC objective.
As tangential movement does not change the shape of $\tw$, we consider the evolution of $\tw$ under a normal velocity field $v_n: \tw \to \R$.

According to~\eqref{eq:ka-dir-expr},  ADC is computed as the ratio of an integral (denoted as $I_a^c$) to the surface area $A:=|\tw|$.
The time derivative of ADC is then expressed as the following form
\begin{equation}
	\label{eq:common-ad-rate}
	\dot{\kappa}_A=\frac{\dot{I}_a^c}{A}-\frac{I_a^c \dot{A}}{A^2}.
\end{equation}
To derive a gradient descent flow, we first identify the $L^2$-gradient of $\ka_A$ by requiring:
\begin{equation}
	\dot{\ka}_A[v_n]=\langle\text{grad }\ka_A, v_n \rangle_{L^2(\tw)}.
\end{equation}
Once the gradient $\text{grad }\ka_A$ is obtained, the optimization proceeds via an $L^2$-gradient flow:
\begin{equation}
	\label{eq:l2-grad-flow}
	\frac{d\tw}{dt}=-\text{grad }\ka_A.
\end{equation}

The change of area is easily computed by
\begin{equation}
	\label{eq:area-rate}
	\dot{A}:=-\int_{\tw}2v_n H.
\end{equation}
The remaining task is to compute the time derivative $\dot{I}_a^c$, which we address in the next section.

\subsubsection{Sensitivity analysis}
\label{sec:sens-ana}
To compute the $L^2$ gradient,  we first state the following result:
\begin{proposition}
	\label{prop:adc-sens}
	The time derivative $\dot{I}_a^c$ is given by
	\begin{equation}
		\label{eq:Ic-grad}
		\dot{I}_a^c=\int_{\tw}2v_n(\bs b-H\bs I)(\nabla \bar u+\p_{\tw})\cdot(\nabla \bar u+\p_{\tw}),
	\end{equation}
	where $\bar u$ is the solution of~\eqref{eq:u-div-eq-hp3}, $\bs{b}$ is the second fundamental form, $H$ is the mean curvature, and $\bs{I}$ is the identity matrix.
\end{proposition}
We provide the derivation details in \ref{app:dtime-flow}.

The normal velocity of $v_n$ is approximated by piecewise linear functions on $\mathcal M$.
Then time derivative $\dt{I}_a^c$ is discretized as
\begin{equation}
	\label{eq:Ic-grad-h}
	\small
	\begin{aligned}
		\dt{I}^c_a 
		&\approx\sum_{f\in\mathcal{F}}\sum_{i\in V(f)}2v_n^i\int_{f}\phi_i\pr{\nabla\bar u^h+P_f\bs p}^\top\pr{\bs b_f -\frac{\tr{\bs b_f}}{2}\mathbf I}\pr{\nabla\bar u^h+P_f\bs p}.
	\end{aligned}
\end{equation}
where

\textbf{-} $V(f)$ denotes the vertices of face $f$;

\textbf{-}  $\bar{u}^h=\sum_{i\in\mathcal{V}}\bar{u}_{i}\phi_i$ is the piecewise linear interpolation of the solution on the mesh vertices, computed in Section~\ref{sec:dis-adc-form};

\textbf{-} $P_f\in\mathbb R^{2\times3}$ is the projection matrix consisting of two orthonormal basis vectors on face $f$, i.e., $P_f = (\bs{g}_1, \bs{g}_2)^\top$;

\textbf{-}  $\bs{b}_f \in \mathbb{R}^{2 \times 2}$ is the second fundamental form of face $f$ under the basis $\{\bs{g}_1, \bs{g}_2\}$, approximated using a finite difference scheme~\cite{Rusinkiewicz2004,ads}.

The time derivative of the surface area is similarly discretized as:
\begin{equation}
	\label{eq:area-time-rate}
	\dt{A}\approx -\sum_{f\in\mathcal{F}}\sum_{i\in N(f)}v_n^i\int_{f}\phi_i\tr{\bs b_f}.
\end{equation}
where $N(f)$ denotes the vertices of face $f$.

Both integrals in~\eqref{eq:Ic-grad-h} and~\eqref{eq:area-time-rate} are evaluated using single-point quadrature per face.
We assemble the coefficients of $v_n^i$ in the discretized version of~\eqref{eq:common-ad-rate} into a vector $\bs{G}_{n}$, considered as the discrete $L^2$ gradient of $\ka_A$.

