\paragraph*{Custom objective}
To optimize a custom objective of the ADC matrix $f(\k_A)$, one must compute  its sensitivity.
Reusing the derivation from Proposition~\ref{prop:adc-sens}, we obtain the following result:
\begin{proposition}
	The time derivative $\dot{k}_A^{ij}$ is given by
	\begin{equation}
		\dot{k}_A^{ij}=\frac{\dot{I}_{ij}^c}{A}-\frac{I_{ij}^c\dot{A}}{A^2},
	\end{equation}
	where $I_{ij}^c$ denotes the integral in~\eqref{eq:bar-k-A-expr}, and its time derivative is 
	\begin{equation}
		\dot{I}^c_{ij}=\int_{\tw} 2v_n\pr{\bs b- H \bs I}\pr{\nabla \bar{u}^i+\e^i_{\tw}}\cdot\pr{\nabla \bar{u}^j+\e^j_{\tw}}.
	\end{equation}
\end{proposition}

The derivation is similar to Proposition~\ref{prop:adc-sens} with minor changes on the integrand, and is thus omitted here.
The corresponding discretization is given by
\begin{equation}
		\label{eq:Ic-ij-grad-h}
		\begin{aligned}
			\dot{I}^c_{ij} 
			&\approx\sum_{f\in\mathcal{F}}\sum_{q\in N(f)}2v_n^q\int_{f}\phi_q\pr{\nabla\bar u^h_i+P_f\e_i}^\top\pr{\bs b_f -\frac{\tr{\bs b_f}}{2}\mathbf I}\pr{\nabla\bar u^h_j+P_f\e_j},
		\end{aligned}
\end{equation}
where $\bar u_i^h$ is the solution of~\eqref{eq:u-div-eq-hp3} when $\p=\e^i$, computed in Section~\ref{sec:dis-adc-form}.

