\section{Auxiliary lemmas}
\begin{lemma}
	\label{lem:nec-cond-upp}
	If equality in~\eqref{eq:ka-upp-bound-p3} holds, then $\tw$ is either minimal or a cylinder parallel to $\p$.
\end{lemma}
\begin{proof}
	Assume~\eqref{eq:prove-equali-cond} equals zero, then we have $\nabla\bar u=0$, which implies that $\bar u$ is a constant.
	Thus we obtain $2Hp_3=\div \p_{\tw}=-\Delta\bar u=0$, indicating that either $H = 0$ or $p_3 = 0$ must hold on $\tw$.
	Let $F := \{ y \in \tw \mid H(y) \ne 0 \}$ denote the set of points with nonzero mean curvature. Due to the smoothness of $\tw$, $F$ is an open subset of $\tw$. We now consider two cases depending on whether $F$ is empty.

	\begin{itemize}
		\item 	Assume $F \ne \emptyset$. Let $\{F_k\}_{k \in I}$ be the collection of maximal connected open subsets of $F$, where $I$ is an index set. On each $F_k$, we have $H \ne 0$ and $H p_3 = 0$, thus $p_3 = 0$, meaning that each $F_k$ is a cylindrical surface parallel to $\p$.
		Note that on each ruling line (generator) of such a cylinder, the mean curvature is a nonzero constant that depends only on the curvature of the directrix. 

		We now prove that no generator of the cylinder intersects the boundary $\partial F_k$.
		Assume the contrary: there exists a point $x \in \partial F_k$ belongs to some ruling line such that $H(x) \ne 0$. Since $F_k$ is maximal, any neighborhood of $x$ must contain points where $H = 0$. By the smoothness of the surface, the mean curvature at $x$ must be continuous, and thus equal to 0 — a contradiction.
		Therefore, each generator of $F_k$ extends infinitely in the direction of $\p$, and so does $\partial F_k$.

		For the remainder of the surface, i.e., $\tw \setminus \bigcup_k F_k$, we have $H = 0$, implying that this region is a minimal surface with the boundaries $\{\partial F_k\}$, which are composed of straight lines parallel to $\p$.
		Since the normal vectors on the boundary of these minimal surfaces match those of the adjacent cylindrical regions $\overline{F_k} := F_k \cup \partial F_k$, the only possible surface satisfying both boundary position and boundary normal conditions is a plane. Hence, the entire surface $\tw$ must be a cylinder parallel to $\p$.
		\item 
		If $F = \emptyset$, then $H \equiv 0$, and thus $\tw$ is minimal.
	\end{itemize}
\end{proof}

\begin{lemma}
	\label{lm:cubic-srf-int}
	For a cubic symmetric periodic surface $\tw$ and any $\p\in \mathbb R^3$ with $\|\p\|=1$, we have 
	\begin{equation}
		\label{eq:lem-p3sq-13}
		\int_{\tw} p_3^2=\frac{1}{3}|\tw|
	\end{equation}
	where $p_3=\p\cdot\mathbf n$ denotes the normal component of $\p$ on surface $\tw$.
\end{lemma}
\begin{proof}
	The cubic symmetric group $G=\br{G_1,\cdots,G_{48}}$ is generated from 6 matrix
	\begin{equation}
		\begin{aligned}
			D_x=
			\begin{pmatrix}
				-1&&\\
				&1&\\
				& &1
			\end{pmatrix}
			D_y=
			\begin{pmatrix}
				1&&\\
				&-1&\\
				& &1
			\end{pmatrix}
			D_z=
			\begin{pmatrix}
				1&&\\
				&1&\\
				& &-1
			\end{pmatrix}\\
			S_{xy}=
			\begin{pmatrix}
				&1&\\
				1&&\\
				& &1
			\end{pmatrix}\quad
			S_{yz}=
			\begin{pmatrix}
				1&&\\
				&&1\\
				& 1&
			\end{pmatrix}
			S_{zx}=
			\begin{pmatrix}
				&&1\\
				&1&\\
				1& &
			\end{pmatrix}
		\end{aligned}.
	\end{equation}
	As all generators are symmetric matrices, the transpose of any element in $G$ is still in $G$.

	Now, we consider $\p_0=\pr{1,2,3}^\top$ and let $G$ act on it to get an orbit set $\br{\p_k},k=1,\cdots, 48$, where $\p_k=G_k\p_0$.  Hence, we have
	\begin{equation}
		\label{eq:qsol-condition}
		\int_{\tw}\pr{\p_k\cdot\n}^2=\int_{\tw}\pr{\p_0\cdot G_k^\top\n}^2=\int_{\tw}\pr{\p_0\cdot\n}^2.
	\end{equation}
	The last equality is because $G_k^\top\in G$ and $\tw$ is cubic symmetric.

	Note that the integral in~\eqref{eq:lem-p3sq-13} is a quadratic form on $\p$, i.e.,
	\begin{equation}
		\int_{\tw}p_3^2=\int_{\tw}\pr{\p\cdot\n}^2=\p^\top\mathbf{Q}\p,
	\end{equation}
	where $\mathbf Q$ is a symmetric matrix defined as
	\begin{equation}
		\mathbf{Q}= \int_{\tw}\n\n^\top.
	\end{equation}
	Since $\mathbf Q$ is symmetric, there are only 6 independent elements which can be solved from the following linear system derived from~\eqref{eq:qsol-condition}:
	\begin{equation}
		\label{eq:lin-sol-q}
		\p_k^\top\mathbf Q\p_k = c\|\p_0\|^2,\quad k=1,\cdots, 48.
	\end{equation}
	Here, we regard elements of $\mathbf Q$ as the unknown variables, and
	$c=\int_{\tw}\pr{\p_0\cdot\n}^2/\|\p_0\|^2$ is a constant.
	It can be verified through computation that the matrix form of the linear system~\eqref{eq:lin-sol-q} has rank $6$, and thus it has a unique solution.
	However, $\mathbf Q=c \mathbf I$ is a solution of~\eqref{eq:lin-sol-q}.
	Hence, the only solution to~\eqref{eq:lin-sol-q} is $\mathbf Q=c\mathbf I$.
	Consequently, any $\p\in\mathbb R^3$ with $\|\p\|=1$ satisfies
	\begin{equation}
		\label{eq:all-dir-same}
		\int_{\tw} \pr{\p\cdot\n}^2 = c.
	\end{equation}

	Extend $\br{\p}$ into a orthonormal basis $\br{\p,\p^1,\p^2}$, then we have
	\begin{equation}
		\int_{\tw} 1 = \int_{\tw} \pr{\p\cdot\n}^2+\pr{\p^1\cdot\n}^2 +\pr{\p^2\cdot\n}^2
	\end{equation}
	and 
	\begin{equation}
		\int_{\tw}\pr{\p\cdot\n}^2=
		\int_{\tw}\pr{\p^1\cdot\n}^2=
		\int_{\tw}\pr{\p^2\cdot\n}^2
	\end{equation}
	according to~\eqref{eq:all-dir-same}.
	It follows that
	\begin{equation}
		\int_{\tw}\pr{\p\cdot\n}^2=\frac{1}{3}|\tw|,
	\end{equation}
	and thus proves the lemma.
\end{proof}


\begin{lemma}
	\label{lem:div-tg-hp3}
	For a periodic surface $\tw$  and constant vector $\p\in\R^3$, we have the following identity
	\begin{equation}
		\label{eq:divpw-2hp3}
		\div \p_{\tw} = 2Hp_3
	\end{equation}
	where `$\,\div$' denotes the intrinsic divergence operator on $\tw$; $\p_{\tw}$ is the tangent component of $\p$ on $\tw$ and $H$ denotes the mean curvature.
\end{lemma}

\begin{proof}
	We can verify this through direct computation. By definition of divergence, we have
	\begin{equation}
		\div\p_{\tw}=a^{\a\b}\partial_\a p_\b -a^{\a\c}\Gamma_{\a\c}^\b p_\b
	\end{equation}
	under the local coordinate system of $\tw$.
	Note that
	\begin{equation}
		\begin{aligned}
			\partial_{\a} p_\b =\partial_\a \pr{\p\cdot \boldsymbol{a}_\b}=\p\cdot\partial_\a \boldsymbol{a}_\b&=\p\cdot\pr{\Gamma_{\a\b}^\c \boldsymbol a_\c + b_{\a\b}\n}\\
			&=\Gamma_{\a\b}^\c p_\c+b_{\a\b}p_3
		\end{aligned}
	\end{equation}
	Hence
	\begin{equation}
		\div\p_{\tw}= a^{\a\b}b_{\a\b} p_3= 2H p_3
	\end{equation}
\end{proof}

\begin{lemma}
	\label{lem:vol-remainder}
	The volume of $\toe$ is given by
	\begin{equation}
		\label{eq:close-volum-form}
		|\toe|=2\eps |\tw| +\frac{4\pi}{3}\eps^3\chi(\tw)
	\end{equation}
	where $\chi(\tw)$ is the Euler characteristic of middle surface $\tw$.
\end{lemma}
\begin{proof}
	Considering the local parameterization of $\toe$
	\begin{equation}
		\bs r^\eps:U\times (\eps,\eps)\to \toe,\, (y, x_3)\mapsto \bs r(y)+\eps x_3\bs n(y)
	\end{equation}
	where $\bs r(y)$ is the parameterization map of $\tw$, and $U\subset\R^2$ is the parameter domain.
	Let $g^\eps(y,x_3)$ and $\sqrt{a}$ be the volume forms along $\toe$ and $\tw$ induced by $\bs r^\eps$ and $\bs r$, respectively. 
	Then one can verify the following relation (see also Lemma~\ref{lem:vector-asymp-approx})
	\begin{equation}
		\sqrt{g^\eps(y,x_3)}=\pr{1-2H(y) x_3 + K(y)x_3^2}\sqrt{a(y)}
	\end{equation}
	Therefore, we have
	\begin{equation}
		\begin{aligned}
			|\toe|&=\int_U\int_{-\eps}^\eps\sqrt{g^\eps}dx_3 dy\\
			&=\int_U\int_{-\eps}^\eps\pr{1-2H(y) x_3 + K(y)x_3^2}\sqrt{a(y)}dx_3 dy\\
			&=\int_U \pr{2\eps +\frac{2}{3}\eps^3K(y)}\sqrt{a} dy\\
			&=2\eps|\tw|+\frac{2}{3}\eps^3\int_{\tw}K 
		\end{aligned}
	\end{equation}
	Applying Gauss-Bonnet theorem, we have 
	\begin{equation}
		\int_{\tw} K = 2\pi \chi(\tw),
	\end{equation}
	then we arrive at~\eqref{eq:close-volum-form}.
\end{proof}

\section{Effective conductivity of lattice metamaterial}
\label{sec:eff-cond}
Numerical homogenization is a well-established tool to determine the effective property of lattice metamaterials~\cite{Allaire2002}.
Given a RVE $Y=[-1,1]^3$ of the lattice metamaterial, with the solid region denoted as $\Omega\subset Y$,
the homogenization method computes the effective conductivity tensor $\k_H:=k_H^{ij}\e_i\otimes\e_j$ as 
\begin{equation}
	\label{eq:CH}
	k_H^{ij}=\frac{1}{|Y|}\int_\Omega\k(\nabla 
	u^{i}+\e^{i})\cdot(\nabla u^{j}+\e^{j})\itd\Omega
\end{equation}
where the temperature field $u^{i}$ is the solution of the following  \emph{cell problem} when $\p=\e^i$:
\begin{equation}
	\label{eq:cell-prop}
	\left\{
	\begin{aligned}
		&\nabla\cdot\left(\k\left(\nabla u+\p\right)\right)=\mathbf 0,\quad &x\in\Omega\qquad\\
		&\k\left(\nabla u+\p\right)\cdot\n=\mathbf 0,\quad &x\in\partial\Omega\backslash\partial Y\\
		&u \quad\text{Y-periodic}\\
		&\int_{\Omega}u= 0
	\end{aligned}
	\right.
\end{equation}
Here, the matrix
$
\k=\kappa\mathbf I
$
is the thermal conductivity matrix of the isotropic base material within $\Omega$;  $\kappa$ is the conductivity and $\mathbf I$ is the identity matrix. 
The notation $\p\in\R^3$ denotes the \emph{macroscopic temperature gradient}.
The constraint $\int_\Omega u=\mathbf 0$ is used to remove the constant shift and hence guarantee the unique solution.

The above cell problem is typically converted into a variational equation, also known as the weak form of~\eqref{eq:cell-prop}.
Considering the periodic boundary conditions, we identify $Y$ with the unit 3-dimensional flat torus $\T^3:=\R^3/(2\mathbb Z)^3$ via isometric covering map~\cite{Allaire2002}
\begin{equation}
	\label{eq:R-2-T}
	\tau:\R^3\to \T^3, (x,y,z)\mapsto (\tilde{x},\tilde{y},\tilde{z})
\end{equation}
where $\tilde{x}:=x+2\mathbb Z$, same as $\tilde{y},\tilde{z}$. We denote $\tilde{\Omega}:={\tau(\overline{{\Omega}})}$, which is a periodic domain.
Through integration by parts, the cell problem is then converted into the following variational equation
\begin{problem}
	\label{prob:vari-form}
	Find $u\in V_\#(\t\Omega)$, such that
	\begin{equation}
		\label{eq:vari-form}
		\int_{\t\Omega}\k\nabla u\cdot \nabla v=-\int_{\t\Omega} \k\p\cdot\nabla v,\quad\forall v\in V_\#(\t\Omega),
	\end{equation}
	where the function space $V_\#(\t\Omega)$ is 
	\begin{equation}
		\label{eq:func-sp-shell}
		V_\#(\t\Omega):=\left\{v\in H^1(\t\Omega):  \int_{\t\Omega} v= 0 \right\}.
	\end{equation}
	and $H^1(\tO)$ denotes the first-order Sobolev space.
\end{problem}
\begin{remark}
	The cell problem is also equivalent to the following minimization problem
	\begin{equation}
		\label{eq:vari-min}
		\argmin_{u\in V_\#(\t\Omega)} I_{\t\Omega}(u;\p)
	\end{equation}
	where 
	\begin{equation*}
		I_{\t\Omega}(u;\p):=\frac{1}{|Y|}\int_{\t\Omega} \k(\nabla u+\p)\cdot(\nabla u+\p).
	\end{equation*}
\end{remark}
\begin{remark}
	\label{rm:homogenization}
	The effective directional conductivity is computed as
	\begin{equation}
		\ka_{\p}=\k_H\p\cdot\p=k^{ij}_H p_ip_j
	\end{equation}
	for a direction $\p$ with $\|\p\|=1$.
	According to~\eqref{eq:CH} and noting that the solution $u$ of cell problem is linearly dependent on $\p$, we have
	\begin{equation}
		\ka_{\p} =\frac{1}{|Y|}\int_{\tO}\k\pr{\nabla u_{\p}+\p}\cdot\pr{\nabla u_{\p}+\p}=\min_{u\in V_\#(\tO)} I_{\tO}(u;\p)
	\end{equation}
	where $u_{\p}$ is the solution of cell problem when the macroscopic temperature gradient is $\p$.
	In the main text, we are considering the  shell lattice $\toe$ and use notation $\ka_\eps(\tw;\p)$ to denote the effective conductivity. 
	Applying above formulas, we have
	\begin{equation}
		\label{eq:min-energy}
		\ka_\eps(\tw;\p) = \min_{u\in V_\#(\toe)} I_{\toe}(u;\p)
	\end{equation}

\end{remark}

\begin{remark}
	\label{eq:pois-shell}
	As the base material is isotropic with conductivity matrix $\k=\ka\mathbf I$, we have $\Delta u=0$ according to the first equation in~\eqref{eq:cell-prop}.
\end{remark}

\section{Mathematical model of shell lattice metamaterial}
\label{sec:shell-repr}

\emph{
The content of this section largely follows Section 2 of the supplementary material in~\cite{ads}, and is included here for completeness and ease of reference.
	}

\subsection{Representation}
We consider a closed smooth 2-manifold $\tw$ isometrically embedded in $\T^3$,
which serves as the middle surface of the shell. 
As $\tw$ is compact, there exist finite charts $\br{\pr{S_i,\boldsymbol\psi_i}}_{i\in I}$ covering $\tw$, where 
$
\boldsymbol{\psi}_i:= S_i\to \U_i
$
is a map from a open set $S_i\subset\tw$ to the parameter domain $\U_i\subset\R^2$ and
$I$ is a finite index set.
We suppose all $\U_i$ are bounded in $\R^2$ and $\boldsymbol{\psi}_i$ are  continuous to boundary of $\U_i$, w.l.o.g.
Then we construct the shell as a 3-manifold embedded in $\T^3$ by offsetting  $\tw$ normally on both sides by a small distance.
This can be formally stated as the following lemma
\begin{lemma}
	\def\bx{\boldsymbol x}
	\def\by{\boldsymbol y}
	\label{lem:shell-is-mani}
	For sufficiently small\footnote{ Hereafter, sufficiently small $\eps$ means there exist $\eps_0$, such that the conclusion is true when $0<\eps\le\eps_0$. }
	$\eps$, the shell lattice  is the subset 
	\begin{equation}
		\label{eq:toe-uni-thick}
		\tilde{\Omega}^\eps:=\left\{{\bx}\in\T^3: {\bx}={\by}+x_3\n({\by}), x_3\in(-\eps,\eps),{\by}\in\tw\right\},
	\end{equation}
	where $\n({\boldsymbol{y}})$ denotes the normal vector of $\tw$ at ${\boldsymbol{y}}\in\tw$. 
	Moreover, it is a smooth manifold embedded in $\T^3$ with charts $(B_i^\eps,\boldsymbol{\Phi}_i^\eps)_{i\in I}$ given by
	\begin{equation}
		\label{eq:shell-chart-eps-map}
		\begin{aligned}
			B_i^\eps=\left\{{\bx}\in\T^3: {\bx}={\by}+x_3\n({\by}), x_3\in(-\eps,\eps),{\by}\in S_i\right\}\\
			\P_i^\eps: B_i^\eps\to \mathcal{V}_i^\eps,\, {\by}+x_3\n({\by})\mapsto\left(\boldsymbol\psi_i(\by),x_3\right)
		\end{aligned}
	\end{equation}
	where $\mathcal{V}_i^\eps:=\U_i\times(-\eps,\eps)$.
\end{lemma}
\noindent As  above lemma is clear, the proof is omitted.

To conduct the asymptotic analysis as $\epsilon$ approaches zero, we utilize the native curvilinear coordinates on shell.
These curvilinear coordinates rely on the chart of the middle surface.
However, covering the middle surface $\tilde\omega$ with a single chart is infeasible due to its  non-trivial topology. Therefore, we partition the middle surface $\tilde{\omega}$ into several disjoint patches $\{\tw_i\}$.
We suppose $\tw_i$ is covered by chart $(S_i,\bs\psi_i)$. 
The parametric domain for $\tw_i$ is denoted as $U_i:=\boldsymbol\psi_i(\tw_i)$.
It follows that $\tw_i\subset S_i$ and $U_i\subset \U_i$.
Subsequently, we split the shell along normal direction from the cut locus on the mid-surface. 
The split patches constitutes the partition of $\toe$, denoted as $\{\t{\Omega}_i^\eps\}$, and the corresponding chart of each $\toe_i$ is $(B_i^\eps,\boldsymbol\Phi^\eps_i)$.
We denote  $\Omega_i^\eps:=\boldsymbol\Phi^\eps_i(\t{\Omega}_i^\eps)$.
Then we have $\t{\Omega}_i^\eps\subset B_i^\eps$ and $\Omega_i^\eps=\P^\eps_i(\t{\Omega}_i^\eps)=U_i\times(-\eps,\eps)\subset\mathcal{V}_i^\eps$.
See the illustration in Figure~\ref{fig:parameter}.


