\mysection{Estimates}
\subsection{Estimates of radial supersolutions}

\bth{sup-1} Let $N\geq 1$ and $q>1$.\smallskip

\nind (i) If $u\in C(\overline {B_{r_0}}\setminus\{0\})$ is a radial supersolution of $(\ref{I-1})$ in $B_{r_0}\setminus\{0\}$ it satisfies
\bel{III-2}
e^{u(r)}\leq Cr^{-\max\{2,q\}}\quad\text{in }B_{\frac{r_0}{2}}\setminus\{0\},
\ee
where $C=C(N,M,q,u)>0)$ in the general case and $C=C(N,M,q)>0)$ if $r\mapsto u(r)$ is non-increasing.\smallskip

\nind (i) If $u\in C(\overline {B^c_{r_0}})$ is a supersolution of $(\ref{I-1})$ in $B^c_{r_0}$ it satisfies
\bel{III-3}
e^{u(r)}\leq Cr^{-\min\{2,q\}}\quad\text{in }B^c_{2r_0},
\ee
where $C=C(N,M,q,u)>0$ is as in case (i).
\es
\Proof If $u$ is a radial supersolution it is clear that it has at most one local maximum. Indeed at each local extremal point $\tilde r$ there holds $-u_{rr}(\tilde r)\geq e^{u(\tilde r)}>0$. Hence $u_r$ keeps a constant sign near $0$.
We set $w=e^u$, then $w\geq 0$ satisfies.

\bel{III-5}
-\Gd w+\frac{|\nabla w|^2}{w}+M\frac{|\nabla w|^q}{w^{q-1}}-w^2
=-w_{rr}-\frac{N-1}{r}w_r+\frac{w_r^2}{w}+M\frac{|w_r|^q}{w^{q-1}}-w^2\geq 0.
\ee

\nind (i) We first assume that  the function $w$ is nondecreasing on $(0,r_1]$ for some $r_1\in (0,r_0]$, the estimate $(\ref{III-2})$ holds with $C$ depending on $u$.\\
Next we assume that $m$ is nonincreasing on $(0,r_1]$ the it stays decreasing on the whole interval $(0,r_0]$. For $\ge\in (0,\frac 12)$ let $\phi_\ge$ be a $C^\infty(\BBR_+)$ nonnegative function vanishing on $[0,1-\ge]\cup [1+\ge,\infty)$,
with value $1$ on $[1-\frac\ge2,1+\frac\ge 2]$, such that $\ge|\phi'_\ge|$ and $\ge^2|\phi_\ge''|$ are bounded on $[1-\ge,1-\frac\ge 2]\cup[1+\frac\ge 2,1+\ge]$. If $0<R<\frac{r_0}{2}$ we define $v$ by
$$v(x)=w(x)-w(R)\phi_\ge\left(\frac{|x|}{R}\right)
$$
Clearly  $v(R)=0$. There exists $\tilde r_{R,\ge}\in [1-\ge)R,1+\ge)R]$ where 
$v$ achieves a nonpositive minimum, hence $w(\tilde r_{R,\ge})\leq w(R)$, $v_r(\tilde r_{R,\ge})=0$ and $\Gd v(\tilde r_{R,\ge})\geq 0$. There holds 
$w_r(\tilde r_{R,\ge})=w(R)\phi'_\ge(\frac {r_{R,\ge}}{R})$ and $\Gd w(\tilde r_{R,\ge})\geq w(R)\Gd \phi_\ge(\frac{|x_{R,\ge}|}{R})$. Therefore
\bel{III-6}\BA{lll}\dsps
w^2(\tilde r_{R,\ge})\leq -\Gd w(\tilde r_{R,\ge})+\frac{|\nabla w(\tilde r_{R,\ge})|^2}{w(\tilde r_{R,\ge})} +M\frac{|\nabla w(\tilde r_{R,\ge})|^q}{w^{q-1}(\tilde r_{R,\ge})} \\[4mm]
\phantom{w^2(\tilde r_{R,\ge})}
\dsps \leq -w(R)\Gd \phi_\ge(\frac{r_{R,\ge}}{R})+w^2(R)\frac{|\nabla \phi_\ge(\frac{r_{R,\ge}}{R})|^2}{w(\tilde r_{R,\ge})} +
w^q(R)\frac{|\nabla \phi_\ge(\frac{r_{R,\ge}}{R})|^q}{w^{q-1}(\tilde r_{R,\ge})}\\[4mm]
\phantom{w^2(\tilde r_{R,\ge})}\dsps
\leq C\left(\frac{w(R)}{\ge^2R^2}+\frac{w^2(R)}{\ge^2R^2w(\tilde r_{R,\ge})}+\frac{w^q(R)}{\ge^qR^qw^{q-1}(\tilde r_{R,\ge})}\right).
\EA\ee
where $C=C(N,q,M)>0$. \\
Now, if $q>2$, we multiply by $w^{q-1}(\tilde r_{R,\ge})$ and obtain the estimate
$$\BA{lll}\dsps
w^{q+1}(\tilde r_{R,\ge})\leq C\left(\frac{w(R)}{\ge^2 R^2}w^{q-1}(R)+\frac{w^2(R)}{\ge^2 R^2}w^{q-2}(R)+\frac{w^q(R)}{\ge^q R^q}\right)\leq C'\frac{w^q(R)}{\ge^q R^q}.
\EA$$
Because $\dsps w^{q+1}(\tilde r_{R,\ge})\geq \min_{(1-\ge)R\leq r\leq (1+\ge)R}w^{q+1}(r)\geq w^{q+1}((1+\ge)R)$ we obtain
$$w^{q+1}((1+\ge)R)\leq C\frac{w^{\frac q{q+1}}(R)}{\ge^{\frac{q}{q+1}}R^{\frac q{q+1}}}.
$$
We apply the bootstrap method of \cite[Lemma 2.1]{BiVe1} with $\Phi(\gr)=\gr^{-\frac q{q+1}}$  and $d=-h=\frac q{q+1}$ and we conclude that 
$$w(R)\leq C(\Phi(R))^{\frac{1}{1-d}}=CR^{-q}.
$$
If $1<q<2$ we have from $(\ref{III-6})$, 
$$\BA{lll}\dsps w^3(\tilde r_{R,\ge})\leq C\left(\frac{w(R)}{\ge^2R^2}w(\tilde r_{R,\ge})+\frac{w^2(R)}{\ge^2R^2}+\frac{w^q(R)}{\ge^qR^qw^{2-q}}(\tilde r_{R,\ge})\right)\\[4mm]
\phantom{w^3(\tilde r_{R,\ge})}\dsps
\leq C\left(\frac{w(R)}{\ge^2R^2}w(R)+\frac{w^2(R)}{\ge^2R^2}+\frac{w^q(R)}{\ge^qR^qw^{2-q}(r})\right)
\\[4mm]
\phantom{w^3(\tilde r_{R,\ge})}\dsps
\leq C'\left(\frac{w^2(R)}{\ge^2R^2}+\frac{w^2(R)}{\ge^qR^2}\right)\leq C''\frac{w^2(R)}{\ge^2R^2}.
\EA$$
Then 
$$w((1+\ge)R)\leq c\frac{w^{\frac 23}(R)}{\ge^{\frac 23}R^\frac 23}.
$$
Now applying \cite[Lemma 2.1]{BiVe1} with $\Phi(\gr)=\gr^{-\frac 23}$, $d=-h=\frac 23$, we obtain
$$w(R)\leq C(\Phi(R))^{\frac{1}{1-d}}=CR^{-2}.
$$
Note that in the two cases, the upper estimate is independent of $u$.\smallskip

\nind (ii) Assume that $u$ satisfies  $(\ref{III-2})$ in $B^c_{r_0}$. Here also the function $w$ is monotone on $[r_1,\infty)$ for some $r_1\geq r_0$. Let $0<\ge\leq\frac 12$ and $R>r_1+1$. If $w$ is nondecreasing on $[R(1-\ge),R(1+\ge)]$, then 
$w(R)\geq w(\tilde r_{R,\ge})\geq w(R(1-\ge))$ and therefore
$$w(R(1-\ge))\leq w(\tilde r_{R,\ge})\leq C\left(\frac{w^q(R)}{\ge^2R^2}+\frac{w^q(R)}{\ge^qR^q}\right)^{\frac 1{q+1}}
\leq\left\{\BA{lll}\dsps2C\frac{w^{\frac{q}{q+1}}}{\ge^{\frac{2}{q+1}}R^{\frac{2}{q+1}}}\quad\text{if }q>2\\[4mm]
\dsps2C\frac{w^{\frac{q}{q+1}}}{\ge^{\frac{q}{q+1}}R^{\frac{q}{q+1}}}\quad\text{if }1<q<2.
\EA\right.
$$
From the bootstrap argument,
$$w(R)\leq\left\{\BA{lll} C_1R^{-2}\quad&\text{if }q>2\\[2mm]
2CR^{-q}\quad&\text{if }1<q<2,
`\EA\right.
$$
which contradicts the fact that $w$ is nondecreasing. Hence $w$ is nonincreasing and we obtain the estimate
$$w(R(1+\ge))\leq\left\{\BA{lll}\dsps2C\frac{w^{\frac{q}{q+1}}}{\ge^{\frac{2}{q+1}}R^{\frac{2}{q+1}}}\quad\text{if }q>2\\[4mm]
\dsps2C\frac{w^{\frac{q}{q+1}}}{\ge^{\frac{q}{q+1}}R^{\frac{q}{q+1}}}\quad\text{if }1<q<2.
\EA\right.$$
Therefore we obtain $(\ref{III-2})$ as before.\qeda\medskip

\nind\Remark Note that in the non-radial case, such a kind of estimates of supersolutions are extended in \cite{BiVe2} to similar estimates of the spherical minimum of $u$.
