\subsection{General gradient estimates}
Here we obtain a general estimate of the gradient of a solution, non-necessarily radial, in terms of the function itself. It is based upon a combination of Bernstein and Keller-Osserman methods.

\bth{sup-2} Let $N\geq 1$ and  $q>1$. If $u\in C(\overline {B_{r_0}}\setminus\{0\})$ is a solution of $(\ref{I-1})$ in $B_{r_0}\setminus\{0\}$. 
Then for any $\gr\in (0,\frac{r_0}{2}]$ and any $x\in B_{\gr}\setminus\{0\}$
\bel{III-7}
|\nabla u(x)|\leq c_1|x|^{-\frac{1}{q-1}}+c_2\max_{B_\gr(x)}e^{\frac{u}{q}}+c_3\max_{B_\gr(x)}e^{\frac{u}{2(q-1)}},
\ee
where $c_j=c_j(N,q,M)>0$, for $j=1,2,3$.
\es
\Proof The technique is standard and we recall it for the sake of completeness. We set $z=|\nabla u|^2$, then by Schwarz inequality,
$$-\frac{1}{2}\Gd z+\frac{(\Gd u)^2}{N}+\langle\nabla \Gd u,\nabla u\rangle\leq 0.
$$ 
Then, for $\ge>0$ small enough, 
$$-\frac{1}{2}\Gd z+\frac{(Mz^{\frac q2}-e^u)^2}{N}\leq e^uz+\frac {Mq}{2}z^{\frac q2-2}|\langle \nabla z,\nabla u\rangle|\leq e^uz+\ge z^q+C_{\ge,q,M}\frac{|\nabla z|^2}{z}
$$
Using again H\"older and Young inequalities, we obtain
$$\BA{lll}\dsps
-\frac{1}{2}\Gd z+\frac{M^2z^{q}}{N}\leq 2Me^uz^{\frac q2}+e^uz+\ge z^q+C_{\ge,q,M}\frac{|\nabla z|^2}{z}\\[3mm]
\phantom{-\frac{1}{2}\Gd z+\frac{M^2z^{q}}{N}}\dsps\leq
\ge_1z^q+C_{\ge_1}e^{2u}+\ge_2z^q+C_{\ge_2}e^{q'u}+\ge z^q+C_{\ge,q,M}\frac{|\nabla z|^2}{z}
\EA$$
With the choice $\ge$, $\ge_1$ and $\ge_2$ small enough and the last inequality turns out into
\bel{III-8}
-\frac{1}{2}\Gd z+\frac{M^2z^{q}}{2N}\leq C_1e^{2u}+C_2e^{q'u}+C_{q,N,M}\frac{|\nabla z|^2}{z}
\ee
Then we use a variant of the Osserman-Keller inequality proved in \cite [Lemma 3.1]{BiVe1} and obtain $(\ref{III-7})$.\qeda\medskip

The next result which holds only if $q>2$ is a universal a priori estimate of $u$ and $\nabla u$ solution of $(\ref{I-1})$. The proof is delicate and can be found in \cite{BiVe2}
\bth{sup-3} Let $N\geq 2$ and $q>2$. If $u\in C(\overline {B_{r_0}}\setminus\{0\})$ is a solution of $(\ref{I-1})$ in $B_{r_0}\setminus\{0\}$. 
Then there exists $C>0$ depending on $N,q, M, u$ such that
\bel{III-9}
e^{u(x)}\leq \frac{C}{|x|^q}\quad\text{and }\;|\nabla u(x)|\leq \frac{C}{|x|}\quad\text{for all } x\in B_{\frac{r_0}2}\setminus\{0\}.
\ee
\es


\mysection{The dynamical system approach}
A radial solution of $(\ref{I-1})$ satisfies
\bel{II-1}
\CL^{rad}_{m,p,q}u:=-u_{rr}-\frac{N-1}{r}u_r+M|u_r|^q-e^u=0
\ee
In all the sequel we consider essentially radially symmetric solutions $u$ of  $(\ref{I-1})$ that means functions satisfying $(\ref{II-1})$. Furthermore, solutions are at least $C^3$ on their maximal interval of existence.
\subsection{Monotonicity and global properties}

\blemma{mono} Let $q>1$ and $u$ be a radial solution of $(\ref{II-1})$ on $(0,r_0)$. Then $u$ has at most one local maximum and $u_r$ keeps a constant sign near $r=0$ and 
the following dichotomy holds:\\
\nind (i) either $u_r(r)<0$ on $(0,r_0)$ and $u(r)\to\infty$ when $r\to 0$,\\
\nind (ii) or $u_r(r)<0$ on $(0,r_0)$ and $u(r)\to u_0$ when $r\to 0$,\\
\nind (iii) or $u_r(r)>0$ near $0$ and $u(r)\to u_0$ when $r\to 0$,\\
\nind (iv) or $u_r(r)>0$ near $0$ and $u(r)\to -\infty$ when $r\to 0$.
\es
\Proof The proof follows easily from the monotonicity of $u$.\qeda
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%e %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%finally%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%e %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%MAINTHEOREM%%%%%%%%finally%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%e %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%finally%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%e %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%MAINTHEOREM%%%%%%%%finally%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\bprop{glob} Let $N\geq 2$ and  $q>1$. If $u$ is a solution of $(\ref{II-1})$ nonincreasing near $0$ and defined on a maximal interval $(0,R)$, then 
$R=\infty$. Furthermore $u(r)\to-\infty$ and $u_r(r)\to 0$ when $r\to\infty$. As a consequence, if $u$ is positive near $0$, it has a unique zero on $(0,\infty)$.
\es
\Proof By \rlemma {mono}, $u_r<0$ on $(0,R)$. Set 
\bel{IV-2*}
\CH(r)=e^u+\frac{u_r^2}{2}.
\ee
Then
$$
\CH_r(r)=-\frac{N-1}{r}u_r^2+M|u_r|^qu_r=-\frac{N-1}{r}u_r^2-M|u_r|^{q+1}.
$$
Hence $\CH$ is decreasing on $(0,R)$. As a consequence for any $\tilde r\in (0,R)$, $u^2_r$ is bounded on $[\tilde r,R)$.  If $R<\infty$, by integration $u(r)$ is also bounded on $[\tilde r,R)$ which is impossible since $R$ is maximal. Hence $R=\infty$. Since $e^{u(r)}$ is decreasing and positive, there exists $\ell\geq 0$ such that  $e^{u(r)}\to\ell$ when $r\to\infty$. Moreover, since it is positive and decreasing $\CH(r)$ admits a limit $\gl\geq 0$ when $r\to\infty$ and therefore $u_r(r)$ shares this property. This implies that 
$\CH_r$ is integrable and therefore $u_r(r)\to 0$ when $r\to\infty$. Since $e^{u(r)}\to\ell\geq 0$, and $u_r(r)\to 0$ we obtain that $-u_{rr}(r)\to -\ell$. If $\ell>0$ we would obtain that 
$u(r)\to \ln\ell$, which is not compatible. Hence $\ell=0$ and $u(r)\to-\infty$ $r\to\infty$.\qeda\medskip

\nind {\bf Remark 3.2 bis}  More generally, if $u$ is a solution defined on a maximal interval $I_u$ containing $r_0>0$ and if $u_r(r_0)\leq 0$, then $u_r(r)<0$ for $r\in I_u\cap(r_0,\infty)=(r_0,\infty)$, 
$u(r)\to-\infty$ and $u_r(r)\to 0$ when $r\to\infty$. On the contrary, if $u_r(r_0)> 0$, then either $u$ admits a unique maximum at $r_1>r_0$ and therefore $u(r)\to-\infty$ and $u_r(r)\to 0$ when $r\to\infty$, or 
$u$ is increasing on $I_u\cap(r_0,\infty)$. In such a case two situations could occur: either $I_u\cap [r_0,\infty)=[r_0,r_1)$ and $\lim_{r\to r_1}u(r)=\infty$ ($u$ is a large solution), or $I_u\cap [r_0,\infty)=[r_0,\infty)$ and $\lim_{r\to \infty}u(r)=\infty$.
\subsection{Associated differential systems}
To the equation $(\ref{II-1})$ we associate several system autonomous or not.
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsubsection{Non-autonomous systems of order 2}
\blemma{L-1} Let $x$, $X$ and $\Phi$ be defined by 
\bel{II-2}
x(t)=r^2e^{u(r)}\,,\;\; X(t)=r^qe^{u(r)}\,,\;\Phi(t)=-ru_r(r)\quad\text{with }\;t=\ln r.
\ee
Then $u$ is a solution of $(\ref{II-1})$ if and only if 
\bel{II-3}
\left\{\BA{lll} 
x_t=x(2-\Phi)\\
\Phi_t=(2-N)\Phi-Me^{(2-q)t}|\Phi|^q+x,
\EA
\right.
\ee
where $x>0$. This system is also equivalent to
\bel{II-4}
\left\{\BA{lll} 
X_t=X(q-\Phi)\\
\Phi_t=(2-N)\Phi-e^{(2-q)t}\left(-M|\Phi|^q+X\right).
\EA
\right.
\ee
\es
\Proof We set 
\bel{II-5}
u(r)=U(t)\quad\text{with }t=\ln r.
\ee
Then
\bel{II-6}
-U_{tt}-(N-2)U_t-e^{2t}e^U+Me^{(2-q)t}|U_t|^q=0,
\ee
and $\Phi=-U_t=-r\frac{v_r}{v}$ with $v=e^u$. The proof follows.\qeda\medskip

\nind\Remark For the Emden equation $(\ref{I-E-C})$ the system in $(x,\Phi)$ is
$$
\left\{\BA{lll} 
x_t=x(2-\Phi)\\
\Phi_t=(2-N)\Phi+x.
\EA
\right.
$$
The equilibrium are $(0,0)$ and $(2(N-2),2)$. If $N>2$, the characteristic value of the linearisation at $(0,0)$ are $\gl_1=2-N$ with eigenvector $(0,1)$ and $\gl_2=2$ with eigenvector $(N,1)$. Hence $(0,0)$ is a saddle point. The stable trajectory at $(0,0)$ is located on $x=0$ and actually it is
$(x(t),\Phi(t))\equiv (0,ce^{(2-N)t})$. It is not admissible.  The unstable trajectory at $(0,0)$ satisfies $(x(t),\Phi(t))= (Ne^{2t},e^{2t}) (c+o(1))$ ($c>0$) when $t\to-\infty$, which corresponds to a solution $u$ 
satisfying $(u(0),u_r(0)=(\ln cN,0)$. Replacing $\ln cN$ by $u_0$, we obtain all the regular with $u(0)=u_0$.
