\mysection{Isolated sigularities when $1<q<2$}

\subsection{Singular behaviour}

In this section we use a perturbation argument due to \cite[Proposition 4.1]{LoRy} that we recall below.

\bprop{LR} Let $h:\BBR_+\ti \BBR^N\to\BBR^N$ be a Carath\'eodory function. Assume that there exists locally continuous  function $h^*:\BBR^N\to\BBR^N$ such that for all 
compact set $C\subset\BBR^N$ and all $\ge>0$ there exists $T=T(\ge,C)>0$ such that 
$${\rm {ess}}\sup_{\!\!\!\!\!\!x\in C}\sup_{t\geq T}|h(\gt,x)-h^*(x)|\leq \ge.
$$
If $x(t)$ is a bounded solution of $x_\gt=h(\gt,x)$ on $\BBR_+$ such that $x(0)=x_0$,
then the omega-limit set of the positive trajectory of $x$ is a no-empty connected compact set of $\BBR^N$ which is invariant under the flow of the equation $x_\gt=h^*(x)$.
\es

\nind{\it Mutatis mutandis} a similar result holds if $\BBR_+$ is replaced by $\BBR_-$ and omega-limit set by alpha-limit set.\\

 Our first result is a complete description of the behaviour of any solution near $0$.


\bth{compsub} Let $1<q<2$ and $N\geq 3$. If $u$ is any radial solution of $(\ref{I-1})$ in $B_{r_0}\setminus\{0\}$ there holds\smallskip

\nind (i) either 
\bel{IV-3*}\lim_{r\to 0}r^2e^{u(r)}=2(N-2)\,,\;\text{ that is } \;\lim_{r\to 0}\left(u(r)-2\ln\frac 1r\right)=\ln 2(N-2).
\ee 
\nind (ii) or $u$ is a regular solution, i.e. there exists $u_0\in\BBR$ such that $\dsps\lim_{r\to 0}u(r)=u_0$ and $\dsps\lim_{r\to 0}u_r(r)=0$,\smallskip

\nind (iii) or $\dsps\lim_{r\to 0}u(r)=-\infty$ and
\bel{IV-4*}
\lim_{r\to 0}r^{N-2}u(r)=\gg<0\quad\text{when }\, 1<q<\frac{N}{N-1},
\ee
\bel{IV-5log}
\lim_{r\to 0}r^{N-2}|\ln r|^{N-1}u(r)=-\frac{1}{N-2}\left(\frac{N-1}{M}\right)^q\quad\text{when }\, q=\frac{N}{N-1},
\ee
\bel{IV-6}
\lim_{r\to 0}r^{\frac{2-q}{q-1}}u(r)=-\xi_M:=-\frac{q-1}{2-q}\left(\frac{(N-1)q-N}{M(q-1)}\right)^{\frac{1}{q-1}}\quad\text{when }\, \frac{N}{N-1}<q<2.
\ee

\es 
%%
\Proof By \rth{sup-1} we have that $r^2e^{u(r)}\leq C=C(N,p,q,M)>0$ when $0<r\leq \frac {r_0}2$. We consider the system $(\ref{II-3})$ in $(x,\Phi)=(r^2e^{u(.)},-ru_r)$ in the variable $t=\ln r$, that is 
\bel{IV-7}\left\{\BA{lll}
x_t=x(2-\Phi)\\
\Phi_t=x+(2-N)\Phi
-Me^{(2-q)t}|\Phi|^q.\EA\right.\ee
{\it Step 1: }We assume that $u$ is decreasing near $r=0$. Then $\Phi>0$ and $x(r)\leq C$ for $0<r\leq \frac{r_0}2$.\\
 If $\Phi$ is unbounded on $(-\infty, \tilde T]$ with $\tilde T=\ln\tilde r$, we encounter two possibilities:\\
- either $\Phi$ is monotone as $t\to -\infty$ and $\Phi(t)\to \infty$. Then for any $A>0$ we have that $x_t(t)\leq -Ax(t)$ for $t\leq t_A\leq \tilde T$, which implies that $t\mapsto e^{At}x(t)$ is decreasing on 
$(-\infty,t_A]$, thus $x(t)\geq e^{A(t_A-t)}x(t_A)$ on this interval, an inequality which contradicts the boundedness of $x(t)$. \\
- or $\Phi$ is not monotone and thus there exists a sequence $\{t_n\}$ tending to $-\infty$ such as $\Phi(t_n)$ is a local maximum of $\Phi$, and the sequence $\{\Phi(t_n)\}$ tends to $\infty$ when $n\to\infty$. From $(\ref{IV-7})$ we have that $x(t_n)=(N-2)\Phi(t_n)
+Me^{(2-q)t_n}|\Phi(t_n)|^q\to\infty$.  This contradicts the boundedness of $x$. Hence $\Phi$ is bounded. therefore there exists $\gk>0$ such that 
$\sup\{|x(t)|,|\Phi(t)|\}\leq \gk$  for $t\leq \ln\tilde T$.  Since $q<2$ this system is an exponential perturbation as $t\to-\infty$ of the sytem  
\bel{IV-8*}\left\{\BA{lll}
x_t=x(2-\Phi)\\
\Phi_t=x+(2-N)\Phi,\EA\right.\ee
in the sense of \rprop{LR}, which is the system associated to the Chandrasekhar-Emden equation $-\Gd u=e^u$. This system admits the equilibria $(2(N-2),2)$ and $(0,0)$ which both are hyperbolic. The point $(2(N-2),2)$ is a sink while $(0,0)$ is a saddle point. Therefore $(2(N-2),2)$ is repulsive when $t\to-\infty$ and the only solution in its neighbourhood is the constant solution $(2(N-2),2)$ which corresponds to the explicit solution of the Chandrasekhar-Emden equation, $u(r)=\ln\frac{2(N-2)}{r^2}$. To the stable trajectory of $(\ref{IV-8*})$ converging to $(0,0)$ corresponds the regular solution of the same equation.\\
By  \rprop{LR} any bounded solution of $(\ref{IV-7})$ admits a limit set at $-\infty$ which is invariant under the flow of $(\ref{IV-8*})$, actually, the only possibilities are $(2(N-2),2)$ and $(0,0)$. Then either $(x(t),\Phi(t))\to (2(N-2),2)$ or $(x(t),\Phi(t))\to (0,0)$ when $t\to-\infty$.\\
 In the first case $u(r)$ satisfies $(\ref{IV-3*})$. In the second case we introduce the system $(\ref{II-9})$ with 
$\Gth(t)=e^{(2-q)t}$ and we are in the situation where $(x(t,\Phi(t),\Gth(t))\to (0,0,0)$ when $t\to-\infty$. We recall the system  $(\ref{II-9})$ in $(x,\Phi,\Gth)$ 
with $\Gth(t)=e^{(2-q)t}$, 
\bel{IV-7-2}\left\{\BA{lll}
x_t=x(2-\Gf)\\
\Phi_t=x+(2-N)\Phi-M|\Phi|^q\Gth\\
\dsps
\Gth_t=(2-q)\Gth.
\EA\right.\ee
The associated linearised system  at $(0,0,0)$ is 
\bel{IV-9}\left\{\BA{lll}
\;x_t=2x\\
\,\Phi_t=x+(2-N)\Phi\\
\,\Gth_t=(2-q)\Gth.
\EA\right.\ee
The eigenvalues are $\gl_1=2>0$, $\gl_2=2-N<0$ and $\gl_3=2-q>0$. Hence there exists  a 2-dimensional unstable manifold $\CM_s$ of trajectories issued of $(0,0,0)$ as $t\to-\infty$; $\CM_s$ is relative to the eigenvalues 
$\gl_1$ and $\gl_3$ with corresponding eigenvectors $\gw_1=(N,1,0)$ and $\gw_3=(0,0,1)$ which generate the tangent $2$-plane at this point. In the manifold $\CM$ there exists one trajectory $\CT_f$, called the fast trajectory,  
associated to $\gl_1$ and admitting the vector $\gw_1$ for tangent vector at this point. However this trajectory is located in the plane $\Gth=0$ since the point $(0,0)$ of the restriction of $(\ref{IV-7-2})$ to this plane is a saddle point, hence this trajectory is also the unstable trajectory of $(0,0)$. Therefore this trajectory is not admissible. 
Hence our trajectory is associated to $\gl_3$ with tangent  vector  $\gw_3$ at $(0,0,0)$.
Along this trajectory there holds $x(t)=o(e^{(2-q)t})=o(\Gth(t))$ and $\Phi(t)=o(e^{(2-q)t})$. Then 
$r|u_r(r)|=o(r^{2-q})$ when $r\to 0$, and thus $u(r)$ has a finite limit $u_0$ at $r=0$, which implies $x(t)=e^{u_0}e^{2t}(1+o(1))$ as $t\to-\infty$. It follows from the equation $(\ref{I-1})$ and elliptic equation regularity that 
$u$ can be extended as a $C^2$ solution, thus $u_r(0)=0$ and $u$ is a regular solution.\smallskip

\nind{\it Step 2: }We assume that $u$ is increasing near $r=0$. Then either $u(r)$ has a finite limit $u_0$ when $r\to 0$ or $u(r)\to-\infty$. Moreover $u_r$ is monotone near $0$: indeed  at any point $\tilde r$ where $u_{rr}(\tilde r)=0$ the following identity
$$u_{rrr}(\tilde r)=\left(\frac{N-1}{\tilde r}-e^{u(\tilde r)}\right)u_{r}(\tilde r)>0.
$$
Then \\
- either $u_r(r)\to 0$ but in that case $u(r)\to u_0$ at $0$ and $u$ is concave near $0$, hence it is decreasing, contradiction,\\
- or $u_r$ has a positive limit $c_0$ at $0$, then again  $u(r)\to u_0$ but from the equation $u_{rr}$ is not integrable at $0$, contradiction,\\ 
- or $u_r$ tends to $\infty$. In that case $e^{u(r)}=o(u^q_r(r))$. In that case equation $(\ref{II-1})$ can be written under the form 
\bel{IV-10}-u_{rr}-\frac{N-1}{r}u_r+\tilde M(r)u^q_r=0
\ee
where $\tilde M(r)=M-(u_r(r)^{-q})e^{u(r)}\to M$ when $r\to 0$. Equation $(\ref{IV-10})$ is completely integrable by quadrature and we
have
\bel{IV-11}\BA{lll}\dsps r^{-(N-1)(q-1)}X(r)=r_0^{-(N-1)(q-1)}X(r_0)+(q-1)\int_r^{r_0}s^{-(N-1)(q-1)}\tilde M(s)ds.
\EA\ee
where $X(r)=u_r^{1-q}$. By performing a direct integration of $(\ref{IV-11})$ we obtain (iii).\qeda
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%e %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%{\color{red}Proof to be finished}%%%%%%%%%%%%%%%%%%%%%%%%%%%%%finally%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Existence of singular solutions of Emden type}

\bth{posi} Let $1<q<2$ and $N\geq 3$. Then there exists a unique radial solution $u_\gw$ of $(\ref{II-1})$ defined on $(0,\infty)$ such that 
\bel{Ex-1}
\lim_{r\to 0}r^2e^{u(r)}=2(N-2)\quad\text{and }\,\lim_{r\to 0}ru_r(r)=-2.
\ee
\es
\Proof We still consider the systems $(\ref{IV-7})$ and $(\ref{IV-7-2})$ relative to $(x,\Phi,\Gth)$. Here we prove the existence of a unique trajectory $\CT$ of $(\ref{IV-7-2})$ converging to the point $P_0=(2(N-2),2,0)$ as $t\to-\infty$. The linearised system at $P_0$ with $x=2(N-2)+\bar x$ and $\Phi=2+\bar\Phi$ is 
 \bel{Ex-4}\left\{\BA{lll}
\bar x_t=-2(N-2)\bar \Phi\\
\bar \Phi_t=\bar x+(2-N)\bar \Phi-M2^q\bar \Gth\\
\Gth_t=(2-q)\Gth.
\EA\right.
\ee
Set 
$$A=\left(\BA{llll} 0\;&-2(N-2) \!\!\!\!\!\!&&0\\
1\; &\;\;\;2-N \!\!\!\!\!\!\!\!&&-2^qM\\
0\; &\;\;\;\;\;\;0 \!\!\!\!\!\!&&2-q \EA\!\!\right)
$$
The characteristic polynomial associated is
 \bel{Ex-VP}\det(A-\gl I):=P(\gl)=(2-q-\gl)\left(\gl^2+(N-2)\gl+2(N-2)\right).
\ee

The corresponding eigenvalues are $\gl_1=2-q>0$ and $\gl_2, \gl_3$ which are real and negative if $N\geq 10$ and complex with negative real part if $3\leq N\leq 9$.  Hence we have the standard decomposition
$$\BBR^3=\ker (A-\gl_1I)\oplus H
$$
where $H$ is either $\ker (A-\gl_2I)\oplus \ker (A-\gl_3I)$ if $\gl_2\neq \gl_3$ are real, or  $\ker (A-\gl_2I)^2$  if $\gl_2=\gl_3$ (necessarily real), or 
$\CR e\left(\ker (A-\gl_2I)\oplus \ker (A-\gl_3I)\right)$ if $\gl_2\neq \gl_3$ are not real but conjugate. Then $\ker (A-\gl_1I)=$span$ \,\{\gw_1\}$ where $\gw_1$ has for components
$$\gw_1=(2(N-2),q-2,2^qMf(q))\,\text{ where }\;f(q)=q^2-(N+2)q +4(N-1).
$$
We prove that that $f(q)\neq 0$. This is clear if $N<10$. If $N\geq 10$ it admits two positive roots $q_1<q_2$, with $2<q_2$. Since $f(2)>0$, then $2<q_1$. Therefore 
$f(q)>0$. Then
 there exists a unique trajectory $\CT^*$ associated to $(x^*,\Phi^*,\Gth^*)$ such that 
$\dsps \lim_{t\to-\infty}(x^*(t),\Phi^*(t),\Gth^*(t))=(2(N-2),2,0)$ with tangent vector at the trajectory at $P_0$ is colinear to $\gw_1$ and such that $\Gth^*(t)>0$ as $t\to\infty$.  To this trajectory is associated a solution $u_\gw$ of $(\ref{II-1})$ satisfies 
$(\ref{Ex-1})$. It is decreasing; by \rprop{glob} it is defined on $(0,\infty)$ and it satisfies $\dsps \lim_{r\to\infty}u(r)=-\infty$ and $\dsps \lim_{r\to\infty}u_r(r)=0$. Any other solution corresponding to the same trajectory is just a time shift of $(x^*(t),\Phi^*(t),\Gth^*(t)$ and it corresponds to the same function $u_\gw$. \qeda\medskip

\subsection{Existence of solution of Hamilton-Jacobi type}
Next we show the existence of solutions satisfying $(\ref{IV-6})$.
\bth{nega} Let $\frac N{N-1}<q<2$. Then there  exists infinitely many radial solutions $u$ of $(\ref{II-1})$ defined on $(0,\infty)$ such that 
 \bel{Ex-5}\BA{lll}\dsps
\lim_{r\to 0}r^\gb u(r)=-\xi_M,
\EA\ee
where $\gb=\frac {2-q}{q-1}$.
\es
\Proof We set $U=-u$, then 
$$-\Gd U-M|\nabla U|^q+e^{-U}=0
$$
and put
 \bel{Ex-6}
U(r)=r^{-\gb}\xi(t)\,,\;U_r(r)=-r^{-\frac1{q-1}}\eta(t)=-r^{-\gb-1}\eta(t)\;\text{ with }\,t=\ln r.
\ee
We are led to the system
 \bel{Ex-7}\left\{\BA{lll}
\xi_t=\beta\xi-\eta\\
\eta_t=-\gk\eta+M\eta^q-e^{\frac{qt}{q-1}}e^{-e^{-\gb t}\xi(t)},
\EA\right.\ee
with $\gk=\frac{(N-1)q-N}{q-1}>0$. The couple $(\xi,\eta)$ is a solution if $(\xi(t),\eta(t))\to(\xi_M,\gb\xi_M)$ when $t\to-\infty$. Set 
$\bar \xi=\xi-\xi_M$ and $\bar \eta=\eta-\gb\xi_M$. Then 
 \bel{Ex-8}\left\{\BA{lll}
\bar\xi_t=\beta\bar\xi-\bar\eta\\
\bar\eta_t=(q-1)\bar\eta+F(\bar\eta)-e^{\frac{qt}{q-1}}e^{-e^{-\gb t}(\bar\xi +\xi_M)},
\EA\right.\ee
where $F(\bar\eta)=O(|\bar\eta|^{2})$. Let $\gth>4(2-q)$, then there exists $\gm:=\mu(\gth)>0$ such that  
$$\theta\beta x^2-\theta xy+(q-1) y^2\geq \gm(\theta x^2+y^2).
$$
Hence 
 \bel{Ex-9}\frac 12\frac{d}{dt}(\theta \bar\xi^2+\bar\eta^2)\geq\gm (\theta \bar\xi^2+\bar\eta^2)+\bar\eta\left(F(\bar\eta)-e^{\frac{qt}{q-1}}e^{-e^{-\gb t}(\bar\xi +\xi_M)}\right)
\ee
There exists $(x_0,y_0)$  such that 
$$\BA{lll}
(i)&\dsps|x_0|\leq\frac 14\xi_M\\[2mm]
\dsps
(ii)&\dsps|y_0|\leq \min \{\frac \gb4\xi_M,c\}\Longrightarrow |F(y_0)|\leq \frac\gm 2|y_0|^3\leq \frac\gm 2|y_0|^2
\EA$$
and if  we choose $(\bar\xi_0,\bar\eta_0)$  such that  $|\bar\xi_0|\leq |x_0|$ and $|\bar\eta_0|\leq |y_0|$. We denote by $(\bar\xi(t),\bar\eta(t))_{t\leq t_0}$ the solution of $(\ref{Ex-8})$ with initial data 
$(\bar\xi(t_0),\bar\eta(t_0))=(\bar\xi_0,\bar\eta_0)$. As long as $|\bar\xi(t)|\leq |x_0|$ and $|\bar\eta(t)|\leq |y_0|$ we have
$$|\eta|e^{\frac{qt}{q-1}}e^{-e^{-\gb t}(\bar\xi +\xi_M)}\leq \frac\gm4\eta^2+\frac 4\gm e^{\frac{2qt}{q-1}}e^{-2e^{-\gb t}\frac{\xi_M}{2}}
$$
and 
$$\frac 12\frac{d}{dt}(\theta \bar\xi^2+\bar\eta^2)\geq\frac\gm2(\theta \bar\xi^2+\bar\eta^2)-\frac {c(t)}2,
$$
where $C(t)$ is a positive function which satisfies 
$$\lim_{t\to-\infty}e^{-at}c(t)=0\quad\text{for all }a>0.
$$
This implies
 \bel{Ex-10}
 \theta \bar\xi(t)^2+\bar\eta(t)^2\leq e^{\gm(t-t_0)}  (\theta \bar\xi_0^2+\bar\eta_0^2)
 +e^{\gm t}\int_t^{t_0}e^{-\gm s }c(s) ds\quad\text{for }t\leq t_0.
\ee
As long as $|\bar\xi(t)|\leq |x_0|$ and $|\bar\eta(t)|\leq |y_0|$, the above inequality holds. If we take $\theta \bar\xi_0^2+\eta_0^2\leq \min\{\theta x_0^2,y_0^2\}$, inequality 
$(\ref{Ex-10})$ holds for all $t\leq t_0$. Hence $(\bar \xi(t),\bar\eta(t))\to (0,0)$ when $t\to-\infty$, which implies 
 \bel{Ex-11}
\lim_{t\to-\infty}(\xi(t),\eta(t))=(\xi_M,\gb\xi_M).
\ee
If we set $r_0=e^{t_0}$ and $u(r)=-r^{-\gb}\left(\xi_M+\bar\xi(\ln r)\right)$, then $u$ is a solution of $(\ref{II-1})$ in $(0,r_0]$ which satisfies $(\ref{Ex-5})$. Such a solution can be extended to 
$(0,\infty)$ by \rprop{glob} and the choice of its data at $r=r_0$ has for unique restriction $u(r_0)$ and $u_r(r_0)$ corresponding to $(\bar\xi_0,\bar\eta_0)$.\qeda\medskip

Next we show the existence of solutions of $(\ref{II-1})$ satisfying $(\ref{IV-4*})$ by a fixed point method.

\bth{dirac} Let $N\geq 3$ and $1<q<\frac N{N-1}$. Then there exists $\gr_0>0$ and $k_0>0$ such that for $0<\gr\leq \gr_0$ and $-k_0<\gg\leq 0$ there exists a radial function $u_\gg$ satisfying
 \bel{Ex-12}\BA{lll}
-\Gd u_\gg+M|\nabla u_\gg|^q-e^{u_\gg}=c_N\gg\gd_0\qquad&\text{in }\CD'(B_\gr)\\
\phantom{-\Gd +M|\nabla u_\gg|^q-e^{u_\gg}}
u_\gg=0&\text{on }\prt B_\gr.
\EA\ee
Furthermore
 \bel{Ex-13*}
\lim_{r\to 0}r^{N-2}u_\gg(r)=\gg.
\ee
\es
\Proof We look for a radial solution $u$satisfying
 \bel{Ex-14}
\lim_{r\to 0}r^{N-2}u(r)=\gg \,\text{and }\;\lim_{r\to 0}r^{N-1}u(r)=(1-N)\gg.
\ee
If such a solution exists $e^u$ and $|\nabla u|^q$ are integrable and $(\ref{Ex-12})$ holds. 
The function $U=-u$ has to satisfy (note that $-\gg>0$)
 \bel{Ex-13}\BA{lll}\dsps
-U_{rr}-\frac{N-1}{r}U_r-M|\nabla U|^q+e^{-U}=0\qquad\text{in }(0,\gr)\\[2mm]
\phantom{,,,,,,,,,,,,,,,,,,,,,}\dsps\!\lim_{r\to 0}r^{N-2}U(r)=-\gg\\[2mm]
\phantom{,,,,,,,,,,,,,,,,,,,,,}\dsps\!\!\lim_{r\to 0}r^{N-1}U_r(r)=(N-1)\gg\\[2mm]
\phantom{,,,,,,,,,,,,,,,,,,,,,,,,,,,,,,,}\!\!U(\gr)=0.
\EA\ee
Hence the function $V(r)=U_r(r)$ satisfies
 \bel{Ex-15}
V(r)=(N-1)\gg r^{1-N}-r^{1-N}\int_0^r\left(M|V|^q-e^{-U}\right)s^{N-1}ds.
\ee
We combine this with 
 \bel{Ex-16}
U(r)=-\int_r^\gr V(s)ds,
\ee
and define the operator $(U,V)\mapsto K(U,V)=(K_1(U,V),K_2(U,V))$ with
 \bel{Ex-17}\BA{lll}\dsps
K_1(U,V)(r)=-\int_r^\gr V(s)ds\\[2mm]
\dsps
K_2(U,V)(r)=(N-1)\gg r^{1-N}-r^{1-N}\int_0^r\left(M|V|^q-e^{-|U|}\right)s^{N-1}ds.
\EA\ee
We define $K$ on the subspace $\CK$ of $C((0,\gr])\times C((0,\gr])$ of functions $W=(U,V)$ which satisfy 
$$\norm{W}_\CK=\norm{(U,V)}_\CK=\max\left\{\gs\sup_{0<r<\gr}r^{N-2}|U(r)|,\sup_{0<r<\gr}r^{N-1}|V(r)|\right\}:=\max\left\{\gs N_1(U),N_2(V)\right\}<\infty,
$$
where $0<\gs<1$.\smallskip

\nind{\it Step 1: Lipschitz estimate.} We have
$$\BA{lll}\dsps \norm{K(U_1,V_1)-K(U_2,V_2)}_\CK=\max\left\{\gs\sup_{0<r<\gr}r^{N-2}\left|\int_r^\gr(V_1-V_2)ds\right|,\right.\\[4mm]
\phantom{----------------}\dsps\left.\sup_{0<r<\gr}\left|\int_0^r\left(M\left(|V_1|^q-|V_2|^q\right)-\left(e^{-|U_1|}-e^{-|U_2|}\right)\right)s^{N-1}ds\right|\right\}\\[4mm]
\phantom{\dsps \norm{K(U_1,V_1)-K(U_2,V_2)}_\CK}=\max\left\{I_1,I_2\right\}.
\EA$$
Since for $r<s<\gr$
$$|(V_1-V_2)(s)|\leq s^{1-N}\sup_{0<r<\gr}r^{N-1}|(V_1-V_2)(r)|,
$$
we have that
$$I_1\leq \frac\gs{N-2}\sup_{0<r<\gr}r^{N-1}|(V_1-V_2)(r)|=\frac{\gs}{N-2}N_2(V_1-V_2).
$$
Concerning $I_2$, we have
$$\left|(e^{-|U_1|}-e^{-|U_2|}\right|\leq ||U_1|-|U_2||\leq |U_1-U_2|,
$$
hence
$$\BA{lll}\dsps\sup_{0<r<\gr}\left|\int_0^r\left(e^{-|U_1|}-e^{-|U_2|}\right)s^{N-1}ds\right|\leq \left(\sup_{0<r<\gr}r^{N-2}|U_1(r)-U_2(r)|\right)\int_0^\gr sds\\[4mm]
\phantom{\dsps\sup_{0<r<\gr}\left|\int_0^r\left(e^{-|U_1|}-e^{-|U_2|}\right)s^{N-1}ds\right|}\dsps\leq \frac {\gr^2}2\sup_{0<r<\gr}r^{N-2}|U_1(r)-U_2(r)|\\[4mm]
\phantom{\dsps\sup_{0<r<\gr}\left|\int_0^r\left(e^{-|U_1|}-e^{-|U_2|}\right)s^{N-1}ds\right|}\dsps\leq \frac {\gr^2}2N_1(U_1-U_2),
\EA$$
and
$$\BA{lll}\dsps \left||V_1|^q-|V_2|^q\right|(s)\leq q\sup\{|V_1(s)|^{q-1},|V_2(s)|^{q-1}\}|V_1-V_2|(s)\\[4mm]
\phantom{\dsps \left||V_1|^q-|V_2|^q\right|(s)}\dsps \leq q\sup_{0<r<\gr}\max\left\{|r^{N-1}V_1(r)|^{q-1},|r^{N-1}V_2(r)|^{q-1}\right\}s^{(q-1)(1-N)}|V_1-V_2|(s),
\EA$$
$$\BA{lll}\dsps \sup_{0<r<\gr}\left|\int_0^rm\left(|V_1|^q-|V_2|^q\right)s^{N-1}ds\right|\\[4mm]
\phantom{-----}
\dsps\leq \sup_{0<r<\gr}\frac{mq\max\left\{|r^{N-1}V_1(r)|^{q-1},|r^{N-1}V_2(r)|^{q-1}\right\}}{N-q(N-1)}\sup_{0<r<\gr}r^{N-1}|V_1(r)-V_2(r)|\\[4mm]
\phantom{-----}
\dsps\leq \sup_{0<r<\gr}\frac{mq\max\left\{|r^{N-1}V_1(r)|^{q-1},|r^{N-1}V_2(r)|^{q-1}\right\}}{N-q(N-1)}N_2(V_1-V_2).
\EA$$
Finally,
 \bel{Ex-18}\BA{lll}\dsps 
\norm{K(U_1,V_1)-K(U_2,V_2)}_\CK\leq \max\left\{ \frac \gs{N-2}N_2(V_1-V_2),\right.\\[3mm]
\phantom{\norm{K(U_1,V_1)---,,}}\dsps\left.\frac {\gr^2}2N_1(U_1-U_2)+\frac{Mq\max\{N^{q-1}_2(V_1),N^{q-1}_2(V_2)\}}{N-q(N-1)}N_2(V_1-V_2)\right\}.
\EA\ee
{\it Step 2: Bounds on the mapping $K$.} We still have to estimate the terms $N^{q-1}_2(V_j)$ and for such a task we have to find a ball $B^{\CK}$ in $C((0,\gr])\times C((0,\gr])$ endowed with the norm 
$||\,.\,||_\CK$ which is invariant under $K$. If $(U,V)\in B^{\CK}=B^{\CK}_R((0,0))$ we have by assumption
\bel{Ex-19}|U(r)|\leq\frac R\gs r^{2-N} \,\text{ and }\;|V(r)|\leq Rr^{1-N}\,\text{ for all }\;0<r\leq\gr.
\ee
Then
\bel{Ex-20}N_1(K_1(U,V)\leq \sup_{0<r\leq \gr}r^{N-2}\int_r^\gr Rs^{1-N}ds\leq  \frac R {N-2}.
\ee
Since by $(\ref{Ex-19})$
$$\int_0^r\left|M|V|^q-e^{-|U|}\right|s^{N-1}ds\leq \frac{r^N}{N}+\frac{MR^qr^{N-q(N-1)}}{N-q(N-1)}
$$
we obtain
 \bel{Ex-21}\BA{lll}\dsps 
N_2(K_2(U,V))\leq \frac {\gr^2}2N_1(U)+(N-2)|\gg|+\frac{\gr^N}{N}+\frac{MR^q\gr^{N-q(N-1)}}{N-q(N-1)},
\EA\ee
and finally
 \bel{Ex-22}
\norm{K(U,V)}_\CK\leq \max\left\{\frac{\gs R} {N-2},\frac{\gr^2R}{2\gs}+(N-2)|\gg|+\frac{\gr^N}{N}+\frac{MR^q\gr^{N-q(N-1)}}{N-q(N-1)}\right\}
\ee
We fix $\gs=\frac 34$. Therefore for any $R>0$ there exist $0<\gr_0<1$ and $k_0>0$ such that for $0\leq|\gg|\leq k_0$ and $0<\gr\leq\gr_0$ there holds
 \bel{Ex-23*}
\norm{(U,V)}_\CK\leq R\Longrightarrow \norm{K(U,V)}_\CK\leq R.\ee
%%%%
{\it Step 3: End of the proof.} With the choice of $\gs$, we have $\frac \gs{N-2}=\frac{3}{4(N-2)}\leq \frac 34$. Furthermore, if 
$\norm{(U,V)}_\CK\leq R$ we have also $\dsps\sup_{0<r\leq \gr}r^{N-1}|V(r)|\leq R$, hence $N^{q-1}_2(V)\leq R^{q-1}$. Combining this fact with estimate $(\ref{Ex-18})$ 
we obtain that if $(U_1,V_1)$ and $(U_2,V_2)$ are in $B_R^{\CK}$ there holds
if 
 \bel{Ex-23}\BA{lll}\dsps 
\norm{K(U_1,V_1)-K(U_2,V_2)}_\CK\leq \max\left\{ \frac 3{4}N_2(V_1-V_2),\right.\\[3mm]
\phantom{\norm{K(U_1,V_1)-------,}}\dsps\left.\frac {\gr^2}{2}N_1(U_1-U_2)+\frac{MqR^{q-1}}{N-q(N-1)}N_2(V_1-V_2)\right\}
\EA\ee
Up to reducing the value of $R$, always with $R\leq 1$, we can assume that $\frac{mqR^{q-1}}{N-q(N-1)}\leq\frac 14$. 
A straightforward verification shows that 
 \bel{Ex-24}\BA{lll}\dsps \max\left\{ \frac 34N_2(V_1-V_2),\frac {\gr^2}{2}N_1(U_1-U_2)+\frac{1}{4}N_2(V_1-V_2)\right\}\leq \max\left\{\frac34,\gr^2\right\}\norm{U-V}_\CK.
\EA\ee
Since $\gr<1$, the mapping $K$ admits a fixed point $(U,V)$. Hence $U$ satisfies
$$\BA{lll}\dsps
-U_{rr}-\frac{N-1}{r}U_r-M|\nabla U|^q+e^{-|U|}=0\quad\text{in }(0,\gr)\\
\dsps \phantom{----------}
\lim_{r\to 0}r^{N-2}U(r)=-\gg
 \EA$$
 and it vanishes on $r=\gr$. Since $-\gg>0$ and $\lim_{r\to 0}r^{N-2}U(r)=-\gg$ there exists  $\gr_1\in (0,\gr]$ such that $U(r)>0$ for $0<r\leq \gr_1$. Hence $e^{-|U|}=e^{-U}$. Thus 
 $u=-U$ satisfies $(\ref{Ex-12})$ in $B_{\gr_1}$. By \rprop {glob} $u$ can be extended as a solution of 
  \bel{Ex-25}
 -\Gd u+M|\nabla u|^q-e^{u}=c_N\gg\gd_0\qquad\text{in }\CD'(\BBR^N).
 \ee
 Note that the existence of solutions to $(\ref{Ex-25})$ is natural as soon as it is proved that $|\nabla u|^q$ is integrable by using the classical result of \cite{BrLi}.
 \qeda
