\mysection{Isolated singularities when $q>2$}
We first denote by $U_{eik}$ the solution of the eikonal equation
\bel{IV-3}
M|u_r|^q-e^u=0.
\ee
Its expression is
\bel{IV-4'}
U_{eik}(r)=\ln\frac{Mq^q}{r^q}=-q\ln r+\Gl_{N,q,M}\quad\text{with }\Gl_{N,q,M}=\ln Mq^q .
\ee
Notice that if $N=2$, $U_{eik}$ is a solution of $(\ref{II-1})$ in $\BBR^2\setminus\{0\}$. If $N\geq 2$ it is a supersolution. \\
Our first key result is the description of singularities at $r=0$ when $q>2$.
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%e %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%MAINTHEOREM%%%%%%%%finally%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Singular behaviour}

\bth{sing q>2} Let $N\geq 1$ and $q>2$. If $u\in C^2(B_{r_0}\setminus\{0\})$ is a radial solution of $(\ref{I-1})$ in $B_{r_0}\setminus\{0\}$, the following dichotomy holds:\smallskip

\nind (i) either 
\bel{IV-4}
\lim_{r\to 0}r^qe^{u(r)}=Mq^q\quad\text{and }\,\lim_{r\to 0}ru_r(r)=-q,
\ee

\nind (ii) or there exists $u_0\in\BBR$ such that 
\bel{IV-5}
u(r)=u_0+c_{M,N,q}r^{\frac{q-2}{q-1}}(1+o(1))\quad\text{as }\,r\to 0,
\ee
where $c_{M,N,q}=\frac{q-1}{q-2}\left(\frac{(N-1)q-N}{M(q-1)}\right)^{\frac 1{q-1}}$ if $N>1$ and $c_{M,1,q}=-\frac{q-1}{q-2}\left(\frac{1}{M(q-1)}\right)^{\frac 1{q-1}}$,\smallskip

\nind (iii) or $u$ is regular at $0$ in the sense that there exists $u_0\in\BBR$ such that 
\bel{IV-7**}\dsps\lim_{r\to 0}u(r)=u_0\;\text{and }\;\dsps\lim_{r\to 0}u_r(r)=0,
\ee
\nind (iv) or $N=1$  there exists $u_0\in\BBR$ such that 
\bel{IV-7q>2}
\lim_{r\to 0}u(r)=u_0\in\BBR\quad\text{and }\lim_{r\to 0}u_r(r)=b\,\in\BBR_*.
\ee.
\es

For proving this result we need two intermediate lemmas.
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%e %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%LEMMA-1%%%%%%%%finally%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\blemma{sing q>2-1} Assume $N\geq 1$ and $q>2$. If $u$ is a solution of $(\ref{II-1})$ in $(0,1)$, then \smallskip

\nind either for any $C\in (0,1)$ there exists $r_C>0$ such that\smallskip
\bel{IV-7***}r^qe^{u(r)}\geq CMq^q\;\text{ for all }r\geq r_C,
\ee
\nind or $u$ satisfies (ii), (iii) or (iv) in the previous statement.
\es
\Proof {\it Step 1: the case of decreasing solutions}. Assume $u_r<0$ near $0$. Then $u_r<0$ in $(0,1)$ by \rlemma{mono}. Following an idea of Serrin and Zou \cite{SeZo}, for any $C\in (0,1)$ we define the function $F_C$ by
\bel{IV-Fc}F_C(r)=e^u-CM|u_r|^q.
\ee
(i)- We first prove that given $C\in (0,1)$, $F_C$ has a constant sign near $0$. There holds
$$F'_{C}(r)=-e^u|u_r|+CMq|u_r|^{q-1}\left(M|u_r|^q+\frac{N-1}{r}|u_r|-e^u\right).
$$
At a point $r^*$ such that $F_{C}(r^*)=0$ we have
$$\BA{lll}\dsps
F'_{C}(r^*)=-CM|u_r|^{q+1}+CMq|u_r|^{q-1}\left(M(1-C)|u_r|^{q}+\frac{N-1}{r^*}|u_r|\right)\\[2mm]
\phantom{F'_{C}(r^*)}\dsps=-CM|u_r|^{q+1}+CMq|u_r|^{q}\left(M(1-C)|u_r|^{q-1}+\frac{N-1}{r^*}\right)\\[2mm]
\phantom{F'_{C}(r^*)}\dsps=CM|u_r|^{q}\left(qM(1-C)|u_r|^{q-1}+q\frac{N-1}{r^*}-|u_r|\right).
\EA$$
As a consequence, if furthermore $F'_C(r^*)<0$ we obtain that for $r=r^*$,
\bel{IV-7*}qM(1-C)|u_r|^{q-1}+q\frac{N-1}{r^*}<|u_r|.
\ee
Since $q>2$, this inequality implies that $|u_r(r^*)$ is bounded and more precisely $|u_r(r^*)|\leq A_{C,M,q}=(qM(1-C))^{\frac{1}{2-q}}$ which in turn implies 
$e^{u(r^*)}=CM|u_r(r^*)|^q\leq B_{C,M,q}=CM(qM(1-C))^{\frac{q}{2-q}}$. This implies also that $q\frac{N-1}{r^*}$ is bounded. Therefore, for 
$N>1$ this cannot happen and $F_C$ has a constant sign near $0$.\\
\nind Next, if $N=1$, $u_r$ is monotone near $0$ by \rlemma{mono}. If the function $F_C$ is oscillating near $0$, there exist two sequences $\{r_n\}$ and $\{\tilde r_n\}$ tending to $0$ such that $F_C(r_n)=F_C(\tilde r_n)=0$ with $F'_C(r_n)<0$ and $F'_C(\tilde r_n)>0$. This implies 
$|u_r(r_n)|<A_{C,M,q}$ and $|u_r(\tilde r_n)|>A_{C,M,q}$, which contradicts the monotonicity of $u_r$. As a consequence,  for $N=1$ also, $F_C$ keeps a constant sign near $0$.\smallskip

 \nind (ii)- Suppose that for any $C\in (0,1)$ there exists $r_C\in (0,1)$ such that $F_C(r)>0$ for $0<r<r_C$. Then $e^{\frac uq}+(CM)^\frac 1q u_r\geq 0$ on this interval which implies 
that $r\mapsto (CM)^\frac 1qr-qe^{-\frac {u(r)}q}$ in increasing on $(0,r_C)$. Since $u_r<0$, either $u(r)\to\infty$ when $r\to 0$, in which case  $(CM)^\frac 1qr-qe^{-\frac {u(r)}q}\geq 0$ and therefore 
$e^{u(r)}\geq CMq^qr^{-q}$ which is $(\ref{IV-7***})$. Or $u(r)\to u_0$ and the assumption $F_C>0$ implies  that $u_r$ is bounded on $(0,r_C]$. By standard regularity theory , $u_{rr}$ is also bounded. This implies that $u_r(r)$ has a limit when $r\to 0$, and this limit is necessarily zero from the equation if $N>1$. Therefore in that case $u$ satisfies 
$(\ref{IV-7q>2})$ or $(\ref{IV-7**})$.\smallskip

 \nind (iii)- Suppose now  that for some $C\in (0,1)$ there exists  $r_C\in (0,1)$ such that $F_C(r)<0$ for $0<r<r_C$. Then 
 $$-u_{rr}-\frac{N-1}{r}u_r+M(1-C)|u_r|^q\leq 0.
 $$
Set $\gm=M(1-C)$ and $W=-r^{N-1}u_r=r^{N-1}|u_r|$, then 
$$\gm r^{-(N-1)(q-1)}+W^{-q}W_r\leq 0.
$$
By integration, it implies that the function 
$$r\mapsto W^{1-q}(r)+\frac{\gm (q-1)}{(N-1)q-N}r^{N-(N-1)q}
$$
is nondecreasing. When $N>1$ we have that $(N-1)q-N>0$ since $q>2$ and we get a contradiction. When $N=1$, $W=-u_r$ and $r\mapsto |u_r(r)|^{1-q}-\gm(q-1)r$ is nondecreasing. Hence it admits  a limit $\ell\geq 0$ when $r\to 0$. If $\ell=0$ then $|u_r(r)|\to\infty$. Since $|u_r(r)|^{1-q}-\gm(q-1)r\to 0$, we have that $|u_r(r)|^{1-q}\geq \gm(q-1)r$. Hence 
$|u_r(r)|\leq (\gm(q-1)r)^{-\frac{1}{q-1}}$. By integration we obtain that $u(r)$ has a limit $u_0$. Since $-u_{rr}+M|u_r|^q(1+o(1))=0$ we deduce by integration that $(\ref{IV-5})$ holds. If $\ell>0$ then $|u_r(r)|\to \frac{\ell}{q-1}$ and $(\ref{IV-7q>2})$ holds.\smallskip


\nind {\it Step 2: the case of increasing solutions}. Since $u$ is bounded from above,  it follows by \rth {sup-2} that $|u_r(r)|\leq cr^{-\frac{1}{q-1}}$ near $0$. Since $q>2$ it follows that 
$u(r)$ admits a limit $u_0$ when $r\to 0$. The function $v=u-u_0$ satisfies
$$-v_{rr}-\frac{N-1}{r}v_r+M|v_r|^q=e^{u_0}(e^{v}-1):=\phi v
$$
where $\phi=e^{u_0}\frac{e^{v}-1}{v}\to e^{u_0}$ as $r\to 0$. Set $W=r^{N-1}v_r$, then
$$W_r=r^{N-1}\left(Mr^{-(N-1)q}W^q-\phi v\right).
$$
The function $u_r$ is monotone near $0$. Indeed, at a point $\tilde r$ where $u_{rr}(\tilde r)=0$ there holds
$$u_{rrr}(\tilde r)=\left(\frac{N-1}{\tilde r^2}-e^{u(\tilde r)}\right)u_r(\tilde r);
$$
as $u(r)\to u_0$ when $r\to 0$, $\frac{N-1}{ r^2}-e^u$ is positive near $0$ if $N\geq 2$, negative if $N=1$ and in any case this expression keeps a constant sign. \\
Either $u_r\to\infty$ when $r\to 0$ or $u_r$ has a finite limit. In the first case 
we have that $\phi v=o(v_r)$ when $r\to 0$. Thus we can write the equation satisfied by $v$ under the form
$$-r^{1-N}(r^{N-1}v_r)_r+M^*(r)|v_r|^q=0
$$
where $M^*(r)=M(1+o(1))$. This equation  is just a perturbation of  $-r^{1-N}(r^{N-1}v_r)_r+Mv_r|^q$ and it is completely integrable. If $N>1$ it yields $v_r(r)=\Gth_{M,N}r^{-\frac{1}{q-1}}(1+o(1))$ where 
$\Gth_{M,N}=\left(\frac{(N-1)q-N}{M(q-1)}\right)^{\frac 1{q-1}}$. We obtain $(\ref{IV-5})$. If $N=1$ we obtain a contradiction. In the case where $u_r$ has a finite limit, the function $u$ satisfies $(\ref{IV-7**})$ or $(\ref{IV-7q>2})$.\qeda\medskip
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

Next we give the precise behaviour of solutions of $(\ref{II-1})$ such that $r^qe^u$ is positively bounded from below. The result is obtained thanks to an energy function adapted from Leighton's method \cite{Lei}.
\blemma{conver} Let $N\geq 1$ and $q>2$. If $u$ is a solution of $(\ref{II-1})$ such that $r^qe^{u}\geq C_1$ for some $C_1>0$ in a neighbourhood of $0$. Then $(\ref{IV-4})$ holds.
\es
\Proof Since $u(r)\geq -q\ln r+c$ and $u_r$ has constant sign near $0$, it is negative. We set 
\bel{IV-8}X(t)=r^qe^{u(r)}\,,\; Y(t)=-r^{q+1}e^{u(r)}u_r(r)\quad\text{with }t=\ln r.
\ee
Then $(X,Y)$ satisfies 
\bel{IV-9+}\BA{lll}
X_t=qX-Y:=f(X,Y)\\[1mm]
Y_t=(q-N+2)Y-\frac{Y^2}{X}+e^{(2-q)t}\left(X^2-M\frac{Y^q}{X^{q-1}}\right)=g(X,Y,t).
\EA\ee
This system is a variant of system $(\ref{II-3})$ where the unknown are $X(t)$ and $\Phi(t)=-ru_r(r)$. Hence $Y(t)=X(t)\Phi(t)$.  Note that the use of $(X,Y)$ is the most natural transformation for the equation associated to $(\ref{III-5})$. We recall that Leighton's method relative to an autonomous system
$$\BA{lll}
\CX_t=\tilde f(\CX,\CY)\\[1mm]
\CY_t=\tilde g(\CX,\CY).
\EA$$
which has the property that the relation $\tilde f(\CX,\CY)=0$ is equivalent to $\CY=\tilde h(\CX)$ consists in analysing the variations of  the function 
$t\mapsto \CF(\CX(t),\CY(t))$ defined by
\bel{IV-10+}\CF(\CX,\CY)=\int_{h(\CX)}^{\CY}\tilde f(\CX,s)ds-\int_{h(\CX)}^{\CY}\tilde g(s,h(s))ds.
\ee
We adapt this methods to the non-autonomous system (\ref{IV-9+}) in considering first
$$\BA{lll}\dsps F(t)=\int_{qX(t)}^{Y(t)}f(X(t),s)ds-\int_{qX(t)}^{Y(t)}g(s,qs,t)ds\\[3mm]
\phantom{F(t)}\dsps =(N-2)q\frac {X(t)}2-\frac {X_t^2(t)}2+e^{(2-q))t}\left(Mq^q\frac{X^2(t)}{2}-\frac{X^3(t)}{3}\right).
\EA$$
In this expression the term $e^{(2-q))t}$ tends to $\infty$ when $t\to-\infty$. Therefore we replace $F$ by 
\bel{IV-G}G(t):=e^{(q-2)t}F(t)=Mq^q\frac{X^2(t)}{2}-\frac{X^3(t)}{3}+e^{(q-2))t}\left((N-2)q\frac {X(t)}2-\frac {X_t^2(t)}2\right).
\ee
 Then we obtain
 $$\BA{lll}\dsps G_t=(Mq^q-X)XX_t+(q-2)e^{(q-2))t}\left((N-2)q\frac {X}2-\frac {X_t^2}2\right)+e^{(q-2))t}X_t\left(\frac {(N-2)q}2-X_{tt}\right)\\[4mm]
 \phantom{G_t}\dsps =(Mq^q-X)XX_t+(q-2)e^{(q-2))t}\left((N-2)q\frac {X}2-\frac {X_t^2}2\right)\\[4mm]
 \phantom{G_t-------}\dsps+e^{(q-2))t}X_t\left(\frac {(N-2)q}2-(N-2)Y-\frac{X_t^2}{X}-e^{(2-q)t}\left(M\frac{Y^q}{X^{q-1}}-X^2\right)\right)
 \\[4mm]
 \phantom{G_t}\dsps=\left(Mq^qX-M\frac{Y^q}{X^{q-1}}\right)X_t+e^{(q-2))t}\Psi(t), \EA$$
where
  $$\BA{lll}\dsps
  \Psi(t)=(q-2)\left((N-2)q\frac X2-\frac{X_t^2}{2}\right)+X_t\left(\frac{(N-2)q}{2}-(N-2)Y-\frac{X_t^2}{X}\right)\\[4mm]
  \phantom{  \Psi(t)}\dsps
  =(q-2)\left((N-2)q\frac X2-\frac{X_t^2}{2}\right)+\frac{(N-2)q}{2}X_t-\frac{X_t^3}{X}+(N-2)(X_t-qX)X_t.
  \EA$$
Replacing $X_t$ by its value we obtain the following expression for $G_t(t)$
  \bel{IV-11*}
  G_t(t)=MX^{1-q}(qX-Y)(q^qX^q-Y^q)+e^{(q-2)t}\Psi(t).
\ee
Using the assumption and the bound from \rth{sup-1}, we have in a neighbourhood of $0$
$$C_1\leq r^qe^{u(r)}\leq C_2.
$$
This implies that $X(t)$ is bounded from above and from below. By the proof of \rlemma{sing q>2-1} we have for any $C<1$,
$CM|u_r|^q\leq e^{u(r)}$ near $0$, hence $|u_r|\leq \frac{C_3}{r}$ near $0$. Since $X(t)$  is bounded  when $t\to-\infty$ and $Y(t)=\phi(t)X(t)=-ru_r(r)X(t)$, we have also that $\Phi(t)$ and $Y(t)$ are bounded at $-\infty$. Hence $X_t(t)=qX(t)-Y(t)$ shares the same property. Furthermore
$\frac{X_t^3}{X(t)}=X^2(t)(q-\Phi(t))^2)$ is bounded which implies that the function $\Psi(t)$ is bounded. Noticing that  $(qX-Y)(((qX)^q-Y^q)\geq 0$, we obtain
$$G_t(t)=MX^{1-q}(qX-Y)(((qX)^q-Y^q)+e^{(q-2)t}\Psi\geq -Ce^{(q-2)t}\quad\text{for }t\leq .
$$
This implies that the function $t\mapsto G(t)+\frac{C}{q-2}e^{(q-2)t}$ is increasing. Hence either it tends to some finite $\ell$ or it tends to $-\infty$ when $t\to -\infty$. Since $X(t)$ is bounded from above and below and $Y(t)$ is bounded, we deduce that $\ell$ is finite. By the definition of $G(t)$ we have that $Mq^q\frac{X^2(t)}{2}-\frac{X^3(t)}{3}\to\ell$ when $t\to-\infty$, hence $X(t)$ converges to some 
$\gl$ such that $Mq^q\frac{\gl^2}{2}-\frac{\gl^3}{3}=\ell$, and $\ell\neq 0$ since $X(t)$ is bounded from below. Concerning $Y(t)$, either it has a limit $\Gl$ and $X_t(t)\to q\gl-\Gl$. But the only possible limit for $X_t(t)$ at $-\infty$ is zero, thus $\Gl=q\gl$. Or $Y(t)$ is not monotone, thus it oscillates at infinity and for a sequence $\{t_n\}$ of extremal points of $Y$ tending to $-\infty$,    we have that
$(q-N+2)Y(t_n)-\frac{Y^2(t_n)}{X(t_n)}=O(e^{(q-2)t_n})\to 0$  from the equation. Since $X(t_n)\to \gl$ and $e^{(q-2)t_n}\to 0$ it follows that $Y(t_n)$ admits a limit when $t_n\to\infty$, which implies in turn that 
 $Y^q(t_n)\to \frac{\gl^{q+1}}{M}$. Hence, even if it oscillates, $Y(t)$ admits a limit that we denote $\tilde \Gl$ at $-\infty$,  and $\tilde \Gl= \left(\frac{\gl^{q+1}}{M}\right)^{\frac 1q}$. Therefore 
 $\dsps\lim_{r\to 0}r^qe^{u(r)}=Mq^q$. Since $\Gf(t)=\frac{Y(t)}{X(t)}$, then  $\dsps\lim_{t\to-\infty}\Gf(t)=q=-\lim_{r\to 0}ru_r(r)$.\qeda\medskip

 In the next lemma we give precise estimates of the behaviour of such solutions by a method inspired from \cite{BiGaVe4}.

 \blemma{dev1} Let $N>1$ and $q>2$. If $u$ is a solution of $(\ref{II-1})$ satisfying $(\ref{IV-4})$, then
   \bel{IV-12}
u_{rr}(r)=\frac{q}{r^2}(1+o(1))\quad\text{as }r\to 0.
\ee
Furthermore
   \bel{IV-13}
u(r)=\ln\frac{Mq^q}{r^q}-\frac{N-2}{Mq^q(q-1)}r^{q-2}(1+o(1))\quad\text{as }r\to 0,
\ee
and
   \bel{IV-14}
u_r(r)=-\frac{q}{r}\left(1-\frac{(N-2)(q-2)}{Mq^q(q-1)}r^{q-2}(1+o(1))\right)\quad\text{as }r\to 0.
\ee
 \es
 \Proof In the proof we uses the system $(\ref{II-4})$ in $X(t)=r^qe^{u(r)}$ and $\Phi(t)=ru_r(r)$ with $t=\ln r$. We recall it below 
 $$\left\{\BA{lll}
 X_t=X(q-\Phi)\\[1mm]
 \Phi_t=(2-N)\Phi+e^{(2-q)t}(X-M|\Phi|^q).
\EA \right.$$
Then $\Phi>0$ since $u_r<0$. Note that $(Mq^q,q)$ is an equilibrium of $(\ref{II-4})$ only if $N=2$.\smallskip

\nind (i) {\it We claim that }
   \bel{IV-14*}
\lim_{t\to-\infty}e^{(2-q)t}(X(t)-M\Phi^q(t))=(N-2)q.
\ee
Set
$$\Psi(t)=e^{(2-q)t}(X(t)-M\Phi^q(t))=\Phi_t(t)+(N-2)\Phi(t)
$$
Then
$$\BA{lll}
\Psi_t=\Phi_{tt}+(N-2)\Phi_t=(2-q)e^{(2-q)t}(X-M\Phi^q)+e^{(2-q)t}(X(q-\Phi)-Mq\Phi^{q-1}\Phi_t)\\[1mm]
\phantom{\Psi_t}=(2-q)\Psi+e^{(2-q)t}X(q-\Phi)-Mqe^{(2-q)t}\Phi^{q-1}((2-N)\Phi+\Psi)\\[1mm]
\phantom{\Psi_t}=\left((2-q-Mqe^{(2-q)t}\Phi^{q-1}\right)\Psi+e^{(2-q)t}\left(X(q-\Phi)+Mq(N-2)\Phi^q\right)\\[1mm]
\phantom{\Psi_t}=e^{(2-q)t}\left(X(q-\Phi)+Mq(N-2)\Phi^q+\Psi\left((2-q)e^{(q-2)t}-Mq\Phi^{q-1}\right)\right).
\EA$$
If $\Psi$ is not monotone near infinity, at each $t^*<0$ where $\Psi_t(t^*)=0$ there holds
$$\left((q-2)e^{(q-2)t^*}+Mq\Phi^{q-1}(t^*)\right)\Psi(t^*)=X(t^*)(q-\Phi(t^*))+Mq(N-2)\Phi^q(t^*).
$$
Equivalently
$$\left(\frac{q-2}{Mq\Phi^{q-1}(t^*)}e^{(q-2)t^*}+1\right)\Psi(t^*)=\frac{X(t^*)(q-\Phi(t^*))}{Mq\Phi^{q-1}(t^*)}+(N-2)\Phi(t^*)
$$
By assumption $\Phi(t)\to q$ and $X(t)\to Mq^q$ as $t\to-\infty$. If $t^*=t_n\to-\infty$, we have that  $\Psi(t_n)\to (N-2)q$, then $\Psi(t)\to (N-2)q$. \\
If $\Psi$ is monotone near infinity, then it admits a limit $L\in [-\infty,\infty]$. Since $\Phi_t(t)\to L-(N-2)q$ and $\Phi(t)\to q$ when $t\to-\infty$, then necessarily $L$ is finite, $\Phi_t(t)\to 0$  and finally   $L=(N-2)q$ as in the previous case. It follows that 
$$\lim_{t\to-\infty}\Psi(t)=(N-2)q=\lim_{t\to-\infty}e^{(2-q)t}(X(t)-M\Phi(t))
$$
which can be written
$$X(t)-M\Phi(t)=(N-2)qe^{(q-2)t}(1+o(1))\quad\text{as }t\to-\infty
$$
which is the claim.\smallskip

\nind (ii) {\it End of the proof. } Relation (\ref{IV-14*}) can be expressed by
\bel{IV-14**}r^2(e^{u(r)}-M|u_r(r)|^q)=(N-2)q(1+o(1))\quad\text{as }r\to 0.
\ee
By  $(\ref{II-1})$ we obtain $(\ref{IV-12})$ since
$$\BA{lll}\dsps
u_{rr}=\frac{N-1}{r}|u_r|-e^u+M|u_r|^q\\[4mm]
\phantom{u_{rr}}
\dsps =\frac{(N-1)q}{r^2}(1+o(1))-\frac{(N-2)q}{r^2}(1+o(1))=\frac{q}{r^2}(1+o(1)).
\EA$$
Since $M|u_r(r)|^q=e^{u(r)}(1+o(1))$ when $r\to 0$, we define $W$ by $u_r(r)=-\frac{e^{\frac{u(r)}{q}}}{M^{\frac 1q}}(1+W(r))$. Then $W(r)\to 0$ and we have when $r\to 0$,
$$r^2(e^{u(r)}-M|u_r(r)|^q)=r^2e^{u(r)}(1-(1+W(r))^q)=-qr^2e^{u(r)}W(r)(1+o(1)).
$$
This implies
$$W(r)=-\frac{(N-2)e^{-u(r)}}{r^2}(1+o(1))=-\frac{(N-2)r^{q-2}}{Mq^q}(1+o(1)).
$$
Therefore
   \bel{IV-15}-u_r(r)=\frac{e^{\frac{u(r)}{q}}}{M^\frac 1q}\left(1-\frac{(N-2)r^{q-2}}{Mq^q}(1+o(1))\right)
\ee
which can be written as
$$M^\frac 1q e^{-\frac{u(r)}{q}}u_r(r)+1-\frac{(N-2)r^{q-2}}{Mq^q}(1+o(1))=0.
$$
By integration, 
$$-qM^\frac 1q e^{-\frac{u(r)}{q}}+r\left(1-\frac{(N-2)r^{q-2}}{M(q-1)q^q}(1+o(1))\right)=0.
$$
This yields the expansion of $e^{u(r)}$,
   \bel{IV-16}
e^{u(r)}=\frac{Mq^q}{r^q}\left(1+\frac{(N-2)r^{q-2}}{M(q-1)q^{q-1}}(1+o(1))\right),
\ee
from which follows 
   \bel{IV-17}\BA{lll}\dsps
u(r)=\ln\frac {Mq^q}{r^q}+\frac{(N-2)r^{q-2}}{Mq^q(q-1)}(1+o(1))\quad\text{as }r\to 0.
\EA\ee
Combining $(\ref{IV-15})$ and $(\ref{IV-16})$ we obtain
   \bel{IV-18}\BA{lll}\dsps
-u_r(r)=\frac{q}{r}\left(1-\frac{(N-2)(q-2)r^{q-2}}{Mq^q(q-1)}(1+o(1))\right)\quad\text{as }r\to 0.
\EA\ee
This ends the proof.\qeda\medskip

\nind\Remark By $(\ref{IV-16})$ we obtain the 
   \bel{IV-19}\BA{lll}\dsps
r^qe^{u(r)}>Mq^q \, \left(\text{resp }\; r^qe^{u(r)}<Mq^q\right) \,\text{ if }\;N\geq 2\,\left( \text{resp }\;N=1\right).
\EA\ee
