 %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%


 \bth{q>2-beta*} Let $N\geq 2$ and $q>2$. Then for any $u_0\in\BBR$ there exists at least one solution $u$ of $(\ref{II-1})$ in $(0,\infty)$ satisfying
\bel{IV-28}
u(r)=u_0+\frac{q-1}{q-2}\left(\frac{N(q-1)-N}{M(q-1)}\right)^{\frac 1{q-1}}r^{\frac{q-2}{q-1}}(1+o(1))\quad\text{when }\;r\to 0.
\ee
The function $u$ is increasing near $0$.\es
\Proof We use the system $(\ref{II-12})$ with $Z=-\frac{re^u}{u_r}$, $V=r|u_r|^{q-1}$ and $\Gf=-r u_r$. Since we search increasing solutions the system is
\bel{IV-29**}\left\{\BA{lll}
Z_t=Z(N-\Phi-MV-Z)\\
\dsps
V_t=V\left(N-(N-1)q+(q-1)(Z+MV)\right)\\
\Phi_t=\Phi\left(2-N+Z+MV\right).
\EA\right.\ee

{\it In this system the relation $V=e^{(2-q)t}|\Gf|^{q-1}$ holds and thus
$$Z=e^{(2-q)t}\frac{X}{\Gf}\,,\; X=\frac{|\Gf|^{q-1}\Gf}{V}\,\text{and }\;  e^{qt}X=ZV^{\frac{2}{q-2}}|\Phi|^{-\frac q{q-2}}.
$$
The solution $u$ we look for satisfies $\dsps \lim_{r\to 0}u(r)=u_0$ and $\dsps \lim_{r\to 0}r^{\frac 1{q-1}}u_r(r)=k$ for some real number $k$}. The system $(\ref{II-12})$ admits
$P_0=(0,V_0,0)$ for stationary point with $V_0=\frac{(N-1)q-N}{M(q-1)}$. Setting
$V=V_0+\bar V$ the linearised system is
\bel{IV-29}\left\{\BA{lll}\dsps
Z_t=\frac q{q-1}Z\\[2mm]
\dsps \bar V_t=(q-1)V_0(M\bar v+Z)\\[1mm]
\dsps \Phi_t=\frac{q-2}{q-1}\Phi.
\EA\right.\ee
The eigenvalues of the linearised system $(Z,\bar V,\Phi)$ at $(0,0,0)$ are $(\frac{q}{q-1},(N-1)q-N,\frac{q-2}{q-1})$. They are all positive. Hence there exists a 
neighbourhood  $\CV$ of $P_0$ such that all trajectories with a point in $\CV$ converge to $P_0$ when $t\to-\infty$.\smallskip

\nind {\it Step 2: End of the proof}. We recall that $u$ is a solution of $(\ref{II-1})$ if and only if $(X,\Gf)$ defined by $(\ref{II-2})$ satisfies the system $(\ref{II-4})$ but this system is not equivalent to  $(\ref{II-12})$. Let $\gs>0$ such that 
the ball $B_\gs(P_0)$ is in the attractive basin of $P_0$ when $t\to-\infty$. If $P^*:=(Z^*,V^*,\Phi^*) \in B_\gs(P_0)$ with $Z^*,\Phi^*<0$ we denote by $\CT_{P^*}$ the backward trajectory of 
$P^*$ and we set 
$$H(t)=\frac{V^{\frac 1{q-1}}}{\Phi}e^{\frac{q-2}{q-1}t}$$
Then
$$\BA{lll}\dsps
(q-1)\frac {H_t}{H}=q-2+\frac{V_t}{V}-(q-1)\frac{\Phi_t}{\Phi}\\[2mm]
\phantom{(q-1)\frac {H_t}{H}}\dsps =q-2+N-q(N-1)+q-1)(MV+Z)-(q-1)(2-N+MV+Z)\\[2mm]
\phantom{(q-1)\frac {H_t}{H}}\dsps = q-2+N-(N-1)q+(q-1)(N-2)=0
\EA$$
Hence the function $H$ is constant. This implies that $V=be^{(2-q)t}|\Phi|^{q-1}$ for some $b>0$. It is easy to check by computation that $X=\frac{Z|\Phi|^{q-1}\Phi}{V}=b^{-1}e^{(q-2)t}Z\Phi$ satisfies  the following system,
$$\left\{\BA{lll}\dsps
X_t=(q-\Phi)X\\[2mm]
\Phi_t=-(N-2)\Phi+be^{(2-q)t}(X-M|\Phi|^q).
\EA\right.$$
We define $a=\frac1{2-q}\ln b$, $\gt=t+a$, $X^{(a)}(\gt)=X(\gt-a)$ and $\Phi^{(a)}(\gt)=\Gf(\gt-a)$. Then $\Phi^{(a)}(\gt)\sim -V_0^{\frac 1{q-1}}e^{\frac{q-2}{q-1}t}$ as $\gt\to-\infty$ and 
$(X^{(a)},\Phi^{(a)})$ satisfies the system
$$\left\{\BA{lll}\dsps
X^{(a)}_t=(q-\Phi^{(a)})X^{(a)}\\[2mm]
\Phi^{(a)}_t=-(N-2)\Phi^{(a)}+e^{(2-q)\gt}(X^{(a)}-M|\Phi^{(a)}|^q).
\EA\right.$$
By \rlemma{L-1}, equivalently the function $\gr\mapsto u^{(a)}(\gr)=\ln(\gr^{-q}X^{(a)})(\ln\gr)$ satisfies $(\ref{II-1})$, with $\gr u^{(a)}_\gr=-\Phi^{(a)}(\gt)$ and 
$\gr (u^{(a)}_\gr)^{q-1}=e^{(2-q)\gt}(-\Phi^{(a)})^{q-1}$, thus $\dsps\lim_{\gr\to 0}\gr (u^{(a)}_\gr(\gr))^{q-1}=V_0$. Since $q>2$ the function $u^{(a)}_\gr$ is integrable near 
$0$ and there exists some $u_0$ such that $\dsps\lim_{\gr\to 0}u^{(a)}(\gr)=u_0$. This implies that 
$$u(r)-u_0=\frac {q-1}{q-2}V_0^{\frac 1{q-1}}r^{\frac{q-2}{q-1}}(1+o(1))\quad\text{as }r\to 0.
$$
Since $D\CG(P_0)$ is invertible the flows of $\CG$ is conjugate to the one of $D\CG(P_0)$ in a neighbourhood of $P_0$. hence there exists a $C^2$ diffeomorphism $\Gth$ from 
$B_\gs(P_0)$ (up to reducing $\gs$ in order $B_\gs(P_0)$ is a subset of the basin of attraction of $P_0$) to a neighbourhood $\CV$ of $0$ such that $\CG-\CG(P_0)=\CV\circ D\CF(P_0)$, and the trajectories of $(\ref{IV-29**})$ in $B_a(P_0)$ (for some $a>0$) are in one to one correspondence 
via $\CV$ with the trajectories of 
\bel{IV-31}(Z_t,V_t,\Phi_t)=D\CF(P_0)((Z,V,\Phi))
\ee
Since all the trajectories of $(\ref{IV-31})$ converge to $0$ when $t\to-\infty$, all the trajectories of $(\ref{IV-29**})$ issued from $B_\gs(P_0)$ converge to $P_0$ when $t\to-\infty$. This ends to proof.
Given arbitrary  coefficients $C_j$ ($j=1,2,3$) with $C_3>0$, the solutions of the linearized system $(\ref{IV-31})$ are expressed by
$$\left\{\BA{lll}Z(t)=C_1e^{\frac {qt}{q-1}}\\
\dsps \bar V(t)=C_2e^{(N(q-1)-N)t}+\frac{(q-2)C_1}{M(q-1)}e^{\frac{qt}{q-1}}\\
\Phi(t)=C_3e^{\frac {(q-2)t}{q-1}},
\EA\right.
$$
in general, with a standard modification if $N=3$ and $q=\frac{3+\sqrt 3}{2}$ or $N=2$ and $q=2+\sqrt 2$ since in these two cases $\frac{q}{q-1}=(N-1)q-N$. If $(V,\Gf)$ satisfies  $(\ref{II-12})$, then the equivalence of trajectories yields
$$V(t)=be^{(2-q)t}\Gf^{q-1}(t)\sim be^{(2-q)t}C_3^{q-1}e^{(q-2)t}=bC_3^{q-1}.
$$
This implies that $b=V_0C_3^{1-q}=e^{(2-q)a}$ with the previous notations. Hence $e^{qa}=(V_0C_3^{1-q})^{\frac{q}{2-q}}$ which implies
\bel{IV-32}
u_0=(V_0C_3^{1-q})^{-\frac{q}{q-2}}V_0^{\frac{2}{q-2}}C_1C_3^{\frac{2}{q-2}}=V_0^{-1}C_1C_3^{-\frac{q(q-1)+2}{q-2}}.
\ee
This implies that $u_0$ can take any value.
\qeda
\mysection{Behaviour of solutions in an exterior domain}
In this section we consider radial solutions of $(\ref{I-1})$ defined in $B^c_{r_0}$. If $u$ is such a solution, it satisfies $(\ref{III-3})$ that we recall 
\bel{V-1}
e^{u(r)}\leq Cr^{-\min\{2,q\}}\qquad\text{for all }\,r\geq 2r_0.
 \ee
Equivalently
\bel{V-2}
e^{u(r)}\leq C\left\{\BA{lll}r^{-2}&\quad\text{if }\,q>2\\
r^{-q}&\quad\text{if }\,1<q<2.
\EA\right.
 \ee
 Applying \rth{sup-2} in $B_{\frac{|x|}{2}}(x)$ for $x\in B_{r_0}^c$ we obtain
 \bth{sup-1*} Let $N\geq 1$ and $q>1$. If $u\in C(B_{r_0}^c)$ is a radial solution of $(\ref{I-1})$ in $B^c_{r_0}$, there holds  in $B^c_{2r_0}$,
  for some positive constant $\tilde C=\tilde C(N,q,M)$,
 \bel{V-3}
|u_r(r)|\leq \tilde C\left\{\BA{lll}r^{-\frac{1}{q-1}}&\quad\text{if }\,q>2\\
r^{-1}&\quad\text{if }\,1<q<2.
\EA\right.
 \ee
 \es
 We will see see later on that in both case the estimate is of the form
 \bel{V-3*}
 |u_r(r)|\leq \tilde C r^{-1}.
 \ee

  \bth{inftyq>2} Let $N\geq 3$ and $q>2$. If $u\in C(B_{r_0}^c)$ is a radial solution of $(\ref{I-1})$ in $B^c_{r_0}$, it satisfies
 \bel{V-4}
\lim_{r\to\infty}r^2e^{u(r)}=2(N-2)\quad\text{and }\;\lim_{r\to\infty}ru_r(r)=-2.
 \ee
 \es
 \Proof As in \rth{posi} we use the systems $(\ref{II-3})$ and $(\ref{II-9})$ with variables variables $x(t)=r^2e^{u(r)}$, $\Phi=-ru_r(r)$  and $\Gth(t)=e^{(2-q)t}$. Here since $q>2$ and $t=\ln r\to\infty$ we have that $\Gth(t)\to 0$ when $t\to\infty$. The system   with $t=\ln r$,  admits  $O=(0,0,0)$ and 
 $P_0=(2(N-2),2,0)$ for equilibria.  
 The  eigenvalues of the linearised operator at $P_0$ given by $(\ref{Ex-VP})$ are $\gl_1=2-q<0$ and $\gl_2,\gl_3$ negative too if $N\geq 11$, double with value $2-N$ if $N=10$ or complex with negative real part $\CR e(\gl_j)=2-N$ if $3\leq N\leq 9$. Therefore $P_0$ is a sink with a domain of attraction which contains some ball $B_a(P_0)$. The eigenvalues of the linearised operator at $O$ 
 $$\left\{\BA{lll}
 x_t=2x\\
 \Phi_t=x-(N-2)\Phi\\
 \Gth_t=(2-q)\Gth,
 \EA\right.$$
 are $2$, $2-q$ and $2-N$, hence $O$ is a saddle point with a $2$-dimensional stable manifold $\CM$ and a unstable trajectory $\CT_0$. \\
 {\it We claim that all the solutions in $B_{r_0}^c$ belong to the domain of attraction of $P_0$ and behave as in $(\ref{V-4})$}.
 Indeed $(x,\Phi)$ satisfies $(\ref{II-3})$ that is
  $$\left\{\BA{lll}
x_t=(2-\Phi)x\\
\Phi_t=x+(2-N)\Phi-Me^{(2-q)t}|\Phi|^q.
\EA\right.$$
Since $e^{u(r)}\to 0$ from $(\ref{V-2})$, $u$ is decreasing, thus $u_r(r)<0$ (the inequality is strict from the equation),  then $\Phi(t)>0$ and $x(t)$ is bounded from $(\ref{V-2})$. Suppose now that 
$\Phi$ is unbounded.\\
- either $\Phi$ is monotone, thus $\Phi(t)\to\infty$. From $(\ref{II-3})$ we have $\Phi_t<\-\frac{N-2}{2}\Phi$ for $t$ large enough, which implies that $t\mapsto e^{\frac{N-2}{2}t}\Phi(t)$ is decreasing. 
Therefore it is bounded which is contradictory.\\
- or there exists a sequence $\{t_n\}$ tending to infinity such that $\Phi(t_n)$ is a local maximum of $\Phi$ and $\Phi(t_n)\to\infty$. Since $\Phi_t(t_n)=0$ we obtain from $(\ref{II-3})$ that 
$x(t_n)=(N-2)\Phi(t_n)+Me^{(2-q)t_n}\Phi(t_n)^q\to\infty$ which contradicts the boundedness of $x(t)$.\\
Therefore $\Phi(t)$ remains bounded. This implies that the system $(\ref{II-3})$ is an exponentially small perturbation of the system associated to Emden-Chandrashekar equation $(\ref{I-E-C})$
  \bel{V-6}\left\{\BA{lll}
x_t=(2-\Phi)x\\
\Phi_t=x+(2-N)\Phi.
\EA\right.\ee
By \rprop {LR} the omega-limit set of any trajectory of $(\ref{II-9})$ is a compact connected subset invariant for $(\ref{V-6})$. This system is well studied (e.g. \cite{Cha}, \cite{BiVe0}). It is known that the solutions of $(\ref{V-6})$ converges to an equilibrium when $t\to\infty$ and this equilibrium is either 
$(2(N-2),2)$ or $(0,0)$. In the first case we obtain $(\ref{V-4})$. In the second case we use system $(\ref{II-9})$ and we analyse the eventual convergence of a solution $(x,\phi,\Gth)$ to 
$O=(0,0,0)$. This would imply that this trajectory belong to the stable manifold $\CM$, therefore 
  \bel{V-7}|\Phi(t)|=O(e^{(2-N)t}).
\ee
If we plug this estimate into $(\ref{II-3})$, we obtain that 
$$x(t)=x(t_0)e^{\int_{t_0}^t(2-\Phi(s))ds}.
$$
Set 
$A(t_0,t)=e^{-\int_{t_0}^t(\Phi(s))ds}$, then there exists $\gth_1>\gth_2>0$ such that $\gth_2\leq A(t_0,t)\leq \gth_1$, for all $t>t_0>0$. This implies 
$$|x(t)|\geq |x(t_0)|e^{2(t-t_0)}\gth_2\quad\text{for all }\,t\geq t_0.
$$
Consequently, if the omega limit set of the trajectory $(x(t),\Phi(t))$ of $(\ref{II-3})$ is $(0,0)$ there must hold $x(t_0)=0$. As a consequence this trajectory must be contained in the plane 
in the plane $x=0$. In such a case $\Phi$ satisfies the equation
  \bel{V-8}\Phi_t=(2-N)\Phi-Me^{(2-q)t}|\Phi|^q.
\ee
This equation is completely integrable and we obtain
$$|\Phi(t)|^{-q}\Phi(t)=t^{(q-1)(N-2)}|\Phi(1)|^{-q}\Phi(1)+\frac{M}{(q-1)(N-2)}(t^{(q-1)(N-2)}-t)
$$
This relation is not compatible with $(\ref{V-7})$. Hence the omega limit set of the trajectory in $P_0$, which ends the proof.\qeda\medskip

In the case $1<q<2$ we show that all the solutions behave at infinity like the solution of the eikonal equation.
 \bth{inftyq<2} Let $N\geq 3$ and $1<q<2$. If $u\in C(B_{r_0}^c)$ is a radial solution of $(\ref{I-1})$ in $B^c_{r_0}$, it satisfies
 \bel{V-8*}
\lim_{r\to\infty}r^qe^{u(r)}=Mq^q\quad\text{and }\;\lim_{r\to\infty}ru_r(r)=-q.
 \ee
 Note that this behaviour is satisfied both by any regular solution or by the singular solution we have constructed.
 \es
 \Proof We use the system $(\ref{II-4})$ with variables $X(t)=r^qe^{u(r)}$ and $\Phi(t)=-ru_r(r)$, always with $t=\ln r$, that is
$$
\left\{\BA{lll} 
X_t=X(q-\Phi)\\
\Phi_t=(2-N)\Phi-e^{(2-q)t}\left(-M|\Phi|^q+X\right).
\EA
\right.
$$
  Note that $u(r)$ cannot have local minimum, and since  it tends to $-\infty$ by 
 $(\ref{V-2})$ it is decreasing, thus $\Phi(t)\geq 0$. 
Here $X$ is bounded by $(\ref{V-2})$ and also $\Phi$ is bounded by $(\ref{V-3})$. \smallskip

 \nind {\it We claim that $X$ is bounded from below.} We still use the function $G$ defined at $(\ref{IV-G})$, that is 
 $$G(t)=Mq^q\frac{X^2}{2}-\frac{X^3}{3}+e^{(q-2)t}\left((N-2)q\frac{X}{2}-\frac{X_t^2}{2}\right).
 $$
 Then from $(\ref{IV-11*})$, 
 $$G_t(t)=MX^{1-q}\left(qX-Y\right)\left(q^qX^q-Y^q\right)+e^{(q-2)t}\Psi(t),
 $$
 where
 $$\Psi(t)=(q-2)\left((N-2)q\frac{X}{2}-\frac{X_t^2}{2}\right)+\frac{(N-2)q}{2}X_t-\frac{X^3_t}{X}+(N-2)(X_t-qX)X_t.
 $$
 Since $X$ and $\Phi$ are bounded  the same holds with $X_t$ from the equation $(\ref{II-4})$, and because $\frac{X^3_t}{X}=X^2(q-\Phi)^3$, we obtain that $\Psi$ is also bounded by some constant $C>0$.
 Because $\left(qX-Y\right)\left(q^qX^q-Y^q\right)\geq 0$ we obtain that $G_t\geq -Ce^{(q-2)t}$ from what it follows that the function 
 $t\mapsto G(t)+\frac{C}{q-2}e^{(q-2)t}$ is increasing. Since it is bounded, it converges to some limit $\ell$ when $t\to\infty$. Hence the function 
 $t\mapsto Mq^q\frac{X^2(t)}{2}-\frac{X^(t)}{3}$ tends to $\ell$ which implies that $X(t)$ admits a limit $\gl$ when $t\to\infty$,  and $\gl$ satisfies
$Mq^q\frac{\gl^2}{2}-\frac{\gl^3}{3}=\ell$.  If $\Phi(t)$ is not monotone, then at each extremum $t_n$ of $\Phi(t)$ we have 
$$X(t_n)-M\Phi^q(t_n)=(N-2)e^{(q-2)t_n}\Phi(t_n)\Longrightarrow \lim_{n\to\infty}\Phi^q(t_n)=\frac\gl M.
$$ 
This implies that 
$$\limsup_{t\to\infty}\Phi(t)=\left(\frac{\gl}{M}\right)^\frac 1q=\liminf_{t\to\infty}\Phi(t)=\lim_{t\to\infty}\Phi(t)
$$
If $\Phi$ is monotone, then it admits a limit. In both case let $\dsps L=\lim_{t\to\infty} \Phi(t)$. From the equation $(\ref{II-4})$ we have
$$\frac{d}{dt}\left(e^{(N-2)t}\Phi(t)\right)=e^{(N-q)t)}(X(t)-M\Phi^q(t)).
$$
Hence 
 \bel{V-9}\Phi(t)=e^{(2-N)(t-t_0)}\Phi(t)+e^{(2-N)t}\int_{t_0}^te^{(N-q)s}(X(s)-M\Phi^q(s))ds
\ee
If $\gl-ML^q\neq 0$ we obtain a contradiction, since the integration of $(\ref{V-9})$ implies
$$\Phi(t)=\frac{e^{(2-q)t}}{N-q}(\gl-ML^q)(1+o(1)).
$$
Therefore 
$$\lim_{t\to\infty}X(t)=M\left(\lim_{t\to\infty}\Phi(t)\right)^q.
$$
 Again from $(\ref{II-4})$,
 $$X(t)=X(t_0)e^{\int_{t_0}^t(q-\Phi(s)ds}.
 $$
 Then, if $L<q$, $e^{\int_{t_0}^t(q-\Phi(s)ds}\to\infty$, contradiction. If $L>q$, $e^{\int_{t_0}^t(q-\Phi(s)ds}\to 0$, then $X(t)\to 0$, then $\gl=L=0$. We use again the first equation in 
 $(\ref{V-9})$ and we have
 $X_t=\tilde q(t)X(t)$ with $\tilde q=q-\Phi(t)\to q$ when $t\to\infty$. Then for any $t_0>0$ we have
 $$X(t)=X(t_0)e^{\int_{t_0}^t\tilde q(s)ds}.
 $$
 Thus $X(t)\to\infty$, contradiction. Hence 
  \bel{V-10}
  \lim_{t\to\infty}\Phi(t)=q\quad\text{and }\lim_{t\to\infty}X(t)=Mq^q.
\ee
This ends the proof.\qeda
