\mysection{Appendix}
In \rlemma{dev1} formula $(\ref{IV-13})$ gives an  expansion of $u$ near zero at the order $1$. We show below that $u(r)$ satisfies an {\it unique} expansion of order $n$ of the form
   \bel{IV-20}\BA{lll}\dsps
u(r)=\ln \frac {Mq^q}{r^q}+a_1r^{q-2}+a_2r^{2(q-2)}+...+r^{n(q-2)}\left(a_n+o(1)\right).
\text{as }r\to 0,
\EA\ee
where the $a_n$ can be computed by induction.


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\bth . Let $N\geq 2$ and $q>2$. There exists a unique sequence of real numbers
$\{a_n\}_{n\geq 1}$ such that any radial function $u$ satisfying $(\ref{VI-1})$ in $B_{r_0}\setminus\{0\}$ and  $(\ref{IV-4})$ there holds   for any $n\in\BBN^*$,
  \bel{VI-2}
  u(r)=\ln\frac{q^q}{r^q}+a_1r^{q-2}+a_2r^{2(q-2)}+...+a_nr^{n(q-2)}(1+d_n(r)),
\ee
where $d_n(r)\to 0$ when $r\to 0$.
\es
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\Proof For the sake of simplicity we consider equation $(\ref{II-1})$ with $M=1$. Actually, this is not a restriction since if $u^*$ satisfies $(\ref{I-1})$, the function 
$x\mapsto u(x)=u^*(M^{\frac{1}{q-2}}x)+M^{\frac{2}{q-2}}$ satisfies
  \bel{VI-1}-\Gd u+|\nabla u|^q-e^{u}=0.
\ee
Since any solution is decreasing, we consider $u_r$ as a function of $u$ and set
$$u_r=-f(u).
$$
Then $u_{rr}=-f(u)\frac{df}{du}=f^q(u)-e^{u}+\frac{N-1}{r}f(u)$. Thus we obtain the system
  \bel{VI-3}\left\{\BA{lll}\dsps
\frac{df}{du}=\frac{N-1}{r}+\frac{f^q(u)-e^{u}}{f(u)}\\[3mm]
\dsps \frac{dr}{du}=-\frac{1}{f(u)}.
\EA\right.\ee
Using $(\ref{IV-4})$ we have
$$f(u)=e^{\frac uq}(1+o(1))\,\text{ and }\;r(u)=qe^{-\frac uq}(1+o(1))\,\text{ as }\;u\to \infty.
$$
We set
  \bel{VI-4}
\varpi=e^{-\frac uq}f(u),\quad V=\varpi-1\;\text{ and }\;\gth=\frac{q-2}{q}.
\ee
Notice that $e^{\gth u}\to\infty$ since $q>2$. The new system in $(\varpi,r)$ is
  \bel{VI-5}\left\{\BA{lll}\dsps
\frac{d\varpi}{du}=-\frac{\varpi}{q}+\frac{N-1}{re^{\frac uq}}+\frac{\varpi^q-1}{\varpi}e^{\gth u}\\[3mm]
\dsps \frac{dr}{du}=-\frac{e^{-\frac uq}}{\varpi}.
\EA\right.\ee
{\it Step 1: Development of order 1}. We look for $A_1$ such that 
$$\varpi(u)=1+A_1e^{-\gth u}(1+o(1))\,\text{ as }\;u\to \infty.
$$
Equivalently $V(u)=A_1e^{-\gth u}(1+o(1))$. The system in $V$ and $r$ is 
  \bel{VI-6}\left\{\BA{lll}\dsps
\frac{dV}{du}=-\frac{1+V}{q}+\frac{N-1}{re^{\frac uq}}+\frac{(1+V)^{q}-1}{1+V}e^{\gth u}\\[3mm]
\dsps \frac{dr}{du}=-\frac{e^{-\frac uq}}{1+V}.
\EA\right.\ee
We set $\psi(u)=e^{\gth u}V(u)$, then $\psi(u)=o(e^{\gth u})$ when $u\to\infty$. Hence
$$e^{-\gth u}\left(\frac{d\psi}{du}-\frac{q-2}{q}\psi\right)=-\myfrac{1+e^{-\gth u}\psi}{q}+\frac{N-1}{re^{\frac uq}}+e^{\gth u}\frac{(1+e^{-\gth u} )^q\psi-1}{1+e^{-\gth u}\psi},
$$
$$\frac {dr}{du}=\frac{e^{-\frac uq}}{1+e^{-\gth u}\psi}.
$$
As a consequence
$$\BA{lll}\dsps\frac{d\psi}{du}=\frac{q-2}{q}\psi-\frac{e^{\gth u}}{q}-\frac \psi q+\frac{N-1}{re^{\frac uq}}e^{\gth u}+qe^{\gth u}\psi(1+o(1))\\[3mm]
\phantom{\dsps\frac{d\psi}{du}}\dsps=qe^{\gth u}\psi(1+o(1)))+e^{\gth u}\left(-\frac 1q+\frac{N-1}{q}(1+o(1))\right),
\EA$$
that we can write under the following form
  \bel{VI-7}\frac{d\psi}{du}-qe^{\gth u}\psi(1+o(1))=\frac{N-2}{q}e^{\gth u}(1+o(1)).
\ee
- Either $\psi$ is not monotone for large $u$. At each $u$ where $\frac{d\psi}{du}=0$, we get that $\psi(u)=\frac{2-N}{q^2}(1+o(1))$. These implies 
$\dsps\lim_{u\to\infty}\psi(u)=\frac{2-N}{q^2}$. \\
- Or $\psi$ is monotone and there holds $\dsps\lim_{u\to\infty}\psi(u)=\pm\infty$. Therefore $\frac{d\psi}{du}=qe^{\gth u}\psi(1+o(1))$, which implies $\frac{d}{du}(\ln |\psi|-e^{(q-2)u})>0$ and thus 
$|\psi(u)|\geq Ke^{e^{(q-2)u}}$. Since $\psi(u)=o(e^{\gth u})$ we obtain a contradiction.\smallskip

\nind- Or $\psi$ is monotone and $\psi(u)\to \ell$ when $u\to\infty$ for some $\ell$. If $\ell\neq \frac{2-N}{q^2}$, we obtain the following relation  
$\frac{d\psi}{du}=\left(q\ell-\frac{N-2}{q}\right)(1+o(1)))$ which is not compatible with $\psi(u)\to \ell$. \\
In all the cases we obtain
  \bel{VI-8}\lim_{u\to\infty}\psi(u)=\frac{2-N}{q^2}.
\ee
This yields the first term of our expansion
  \bel{VI-9}
  \varpi=1+V=1+A_1e^{-\gth u}(1+o(1))\quad\text{with }\;A_1=\frac{2-N}{q^2}.
\ee
as a consequence
  \bel{VI-10}
\frac{dr}{du}=-\frac{e^{-\frac uq}}{1+A_1e^{-\gth u}(1+o(1))}=-e^{-\frac uq}\left(1-A_1e^{-\gth u}(1+o(1))\right)=-e^{-\frac uq}+A_1e^{\frac {1-q}q u}(1+o(1)).
\ee
Integrating this relation and using that $r(u)\to 0$ when $u\to\infty$, we obtain
  \bel{VI-11}\BA{lll}\dsps
r(u)=-\int_u^\infty\frac{dr}{ds}ds=\int_u^\infty e^{-\frac sq}ds-A_1\int_u^\infty e^{\frac {1-q}{q}s}(1+\ge(s))ds\\[3mm]
\phantom{\dsps
r(u)}\dsps=qe^{-\frac uq}+\frac{qA_1}{1-q}e^{\frac{1-q}{q}u}(1+o(1))=qe^{-\frac uq}+\frac{N-2}{q(q-1)}e^{\frac{1-q}{q}u}(1+o(1)),
\EA
\ee
since for any $\ge_0>0$and $|\ge(s)|\leq\ge_0$ there exists $u_{\ge_0}$ such that for any $u\geq u_{\ge_0}$ there holds
$$\left|\int_u^{\infty}e^{\frac{1-q}qs}(1+\ge(s))ds-\int_u^{\infty}e^{\frac{1-q}qs}ds\right|\leq \frac{q\ge_0}{q-1}.
$$
{\it Step 2: Development of order n}. We proceed by induction assuming that we have already obtained the development of $\varpi$ at the order $n-1$
  \bel{VI-12}
\varpi(u)=1+V=1+A_1e^{-\gth u}+A_2e^{-2\gth u}+...+e^{-(n-1)\gth u}\left(A_{n-1}+\ge_{n-1}(u)\right)
\ee
where the $A_j$ depend on $N$ and $q$ and $\ge_{n-1}(u)\to 0$ when $u\to\infty$. Consequently 
\bel{VI-bis}\BA{lll}\dsps
\frac{dr}{du}=-\frac{e^{-\frac uq}}{1+V}=-\frac{e^{-\frac uq}}{1+A_1e^{-\gth u}+A_2e^{-2\gth u}+...+e^{-(n-1)\gth u}\left(A_{n-1}+\ge_{n-1}(u)\right)}\\
[3mm]\phantom{\dsps
\frac{dr}{du}}\dsps
=e^{-\frac uq}\left(1+B_1e^{-\gth u}+B_2e^{-2\gth u}+...+e^{-(n-1)\gth u}\left(B_{n-1}+\tilde \ge_{n-1}(u)\right)\right),
\EA
\ee
where $\tilde \ge_{n-1}(u)\to 0$ as $u\to\infty$, with $B_1=-A_1$   and the other coefficients can be made explicit through a lengthy but explicit computation. Set
\bel{VI-ter}\varpi=1+A_1e^{-\gth u}+A_2e^{-2\gth u}+...+A_{n-1}e^{-(n-1)\gth u}+e^{-n\gth u}\Phi.
\ee
We do not know if $\Gf$ is bounded but only that $\Phi=\tilde\ge_{n-1}e^{\gth u}$, thus $e^{-\gth u}\Phi(u)\to 0$ when $u\to\infty$. Thus
\bel{help0}\frac{dV}{du}=-\gth A_1e^{-\gth u}-2\gth A_2e^{-2\gth u}-...-(n-1)\gth A_{n-1}e^{-(n-1)\gth u}-n\gth \Phi e^{-n\gth u}+\frac{d\Phi}{du}e^{-n\gth u}.
\ee
We recall the expression
\bel{help1}\frac{dV}{du}=-\frac{1+V}{q}+\frac{N-1}{re^{\frac uq}}+e^{\gth u}\frac{(1+V)^q-1}{1+V},
\ee
and there we use the following expansion at the order $n-1$ (actually, valid at any order)
\bel{help1-bis}\frac{(1+V)^q-1}{1+V}
=qV\left(1+g_1V+...+g_kV^k+...+g_{n-1}V^{n-1}(1+\eta_{n-1}(V))\right),
\ee
where $g_1=\frac{q-3}{2}$ and the $g_k$ are polynomials in $k$ and $q$ and also $\eta_{n-1}(V)\to 0$ when $V\to 0$.\\ Moreover, by integration of $(\ref{VI-bis})$, we obtain
$$\BA{lll}\dsps
r(u)=-\int_u^\infty\frac{dr}{ds}ds=-\int_u^\infty e^{-\frac sq}ds+B_1\int_u^\infty e^{\frac{1-q}{q}s}+...+\int_u^\infty e^{-\frac{1+(n-1)(q-2)}{q}s}(B_{n-1}+\hat \ge_{n-1}s))ds\\[4mm]
