    \label{fig:metrics_simulation_continuous}
\end{figure*}

\begin{figure*}[!htbp]
\centering
\includegraphics[width=0.4\linewidth]{entrevenueDTE_simple.boot.png}
\includegraphics[width=0.4\linewidth]{entrevenueDTE_adj.boot.png}
