\section{Probability Treatment Effect}\label{app:other-parameters}
Let $\rho_w(y_j, s, x):= P(y_{j-1} < Y(w) \leq y_j | S=s, X=x) = \mathbb{E}[\1\{y_{j-1}<Y(w)\leq y_j\}|S=s, X=x]$ and its estimator be denoted by $\widehat \rho_w(y_j, s, x)$. The empirical estimator for the bin probability for $y_j\in\Y$ is as follows:
\begin{align} \label{eq:empirical-pdf}
    \widehat f^{emp}_{Y(w)}(y_j) := & \sum_{s=1}^{S} \widehat p(s) \Big\{\frac{1}{n_w(s)} \sum_{i: W_i=w, S_i=s} \1\{y_{j-1}<Y_i \leq y_j\}\Big\} \nonumber \\
     = & \frac{1}{n}\sum_{i=1}^{n} \frac{ \1\{W_i=w\} }{\widehat \pi_w(S_i)}\cdot \1\{y_{j-1} <Y_i \leq y_j\}.
\end{align}
Also, similarly, the regression-adjusted estimator for the bin probability for $y_j\in\Y_J$ is:
\begin{align} 
\widehat f_{Y(w)}^{adj} (y_j)  := &
\frac{1}{n} \sum_{i=1}^{n} \Big \{\frac{ \1\{W_i=w\} }{\widehat \pi_w(S_i)}\cdot \big( \1\{y_{j-1}<Y_i \leq y_j\} - \widehat \rho_w(y_j, S_i, X_i) \big) + \widehat \rho_w(y_j, S_i, X_i) \Big \}. 
\end{align}
Using these, we can define empirical and regression-adjusted PTE estimators as follows:
\begin{align}
\widehat{\Delta}^{PTE, emp}_{w, w'}(y_j) := \widehat f_{Y(w)}^{emp} (y_j) - \widehat f_{Y(w')}^{emp} (y_j), \\
\widehat{\Delta}^{PTE, adj}_{w, w'}(y_j) := \widehat f_{Y(w)}^{adj} (y_j) - \widehat f_{Y(w')}^{adj} (y_j).
\end{align}

Then, the results in the paper also apply to the PTE, as the indicator functions $\1\{Y(w)\leq y_j\}$ used in the analysis of DTE can be replaced with $\1\{y_{j-1}<Y(w)\leq y_j\}$ for the analysis of the PTE.

\section{Proofs for Section \ref{sec:asymptotics}} \label{app:proofs}
\subsection{Some definitions}
We first introduce some definitions from empirical process theory that will be used in the proofs. See also \citet{van1996weak} and \citet{chernozhukov2014gaussian} for more details.
\begin{definition}[Covering numbers]
The \emph{covering number} $N(\varepsilon, \mathcal{F}, \| \cdot \|)$ is the minimal number of balls $\{g: \|g-f\|<\varepsilon\}$ of radius $\varepsilon$ needed to cover the set $\mathcal F$. The centers of the balls need not belong to $\mathcal F$, but they should have finite norms.
\end{definition}
\begin{definition}[Envelope function]
An \emph{envelope function} of a class $\mathcal F$ is any function $x \mapsto F(x)$ such that $|f(x)| \leq F(x)$ for every $x$ and $f$.
\end{definition}
\begin{definition}[VC-type class]
We say $\mathcal{F}$ is of \emph{VC-type} with coefficients $(\alpha,v)$ and envelope $F$ if the uniform covering numbers satisfy the following:
{\abovedisplayskip=2pt
 \belowdisplayskip=2pt
\begin{align*}
\sup_Q N\left(\varepsilon||F||_{Q,2}, \mathcal{F}, L_2(Q) \right) \leq \left(\frac{\alpha}{\varepsilon}\right)^{v}, \quad \forall \varepsilon \in (0,1],
\end{align*}
}
where the supremum is taken over all finitely discrete probability measures.     
\end{definition}

\subsection{Asymptotic Distribution}
\begin{proof}[\textbf{Proof of Theorem \ref{thm:asymptotics}}]
Recall the notation $\mu_w(y, s) = \E[\mu_w(y, S_i, X_i)|S_i=s]$. Additionally, denote $\eta_{i,w}(y, s) := \1\{Y_i(w)\leq y\} - \mu_w(y,s)$ and $D_{w}(s) := \sum_{i=1}^{n}(\1\{W_i=w\}-\pi_w(s))\cdot\1\{S_i=s\}$. Note that we have $\widehat\pi_w(s)-\pi_w(s) = \frac{D_w(s)}{n(s)}$.
We start with the linear expansion of $\widehat F_{Y(w)}^{adj}$ for treatment $w$ and decompose it into two terms $I_1(y)$ and $I_2(y)$ as follows:
{\abovedisplayskip=2pt
 \belowdisplayskip=2pt
\begin{align*}
\sqrt{n} (\widehat F_{Y(w)}^{adj}(y) - F_{Y(w)}(y))
& =  \frac{1}{\sqrt{n}}\sum_{i=1}^{n} \bigg[\frac{ \1\{W_i=w\} \cdot \big(\1\{Y_i \leq y\} - \widehat \mu_w(y, S_i, X_i) \big) }{\widehat \pi_w(S_i)} + \widehat \mu_w(y, S_i,X_i) \bigg] -\sqrt{n}F_{Y(w)}(y) \\
& = \underbrace{\frac{1}{\sqrt{n}}\sum_{i=1}^{n}\bigg[ \frac{ \1\{W_i=w\}}{\widehat \pi_w(S_i)} \cdot \1\{Y_i \leq y\} \bigg] - \sqrt{n}F_{Y(w)}(y)}_{ \equiv  I_1(y)} \\
& - \underbrace{\frac{1}{\sqrt{n}}\sum_{i=1}^{n}\bigg[   \frac{ (\1\{W_i=w\} -\widehat \pi_w(S_i)) }{\widehat \pi_w(S_i)} \cdot \widehat \mu_w(y, S_i, X_i)  \bigg]}_{\equiv  I_2(y)}
\end{align*}
}
Then, for the first term, we have
\begin{align*}
 I_1(y) & = \frac{1}{\sqrt{n}}\sum_{i=1}^{n} \sum_{s\in\S}  \frac{ \1\{W_i=w\}}{\pi_w(s)} \1\{S_i=s\} \1\{Y_i \leq y\}\\
 & - \frac{1}{\sqrt{n}}\sum_{i=1}^{n} \sum_{s\in\S}  \frac{ \1\{W_i=w\}\1\{S_i=s\}(\widehat\pi_w(s)-\pi_w(s)) }{\widehat\pi_w(s)\pi_w(s)} \1\{Y_i \leq y\}- \sqrt{n}F_{Y(w)}(y)\\
& =  \frac{1}{\sqrt{n}}\sum_{i=1}^{n} \sum_{s\in\S}  \frac{ \1\{W_i=w\}}{\pi_w(s)} \1\{S_i=s\} \1\{Y_i \leq y\} \\
&- \sum_{i=1}^n \sum_{s \in \mathcal{S}}\frac{\1\{W_i=w\}\1\{S_i = s\}D_w(s)}{n(s)\sqrt{n}\hat{\pi}_w(s)\pi_w(s)}\eta_{i,w}(y,s) -  \sum_{s \in \mathcal{S}} \frac{D_w(s)\mu_w(y,s)}{n(s)\sqrt{n}\hat{\pi}_w(s)\pi_w(s)} D_w(s) - \sum_{s \in \mathcal{S}} \frac{D_w(s)\mu_w(y,s)}{\sqrt{n}\hat{\pi}_w(s)} \notag \\ 
& = \sum_{s \in \mathcal{S}} \frac{1}{\sqrt{n}}\sum_{i =1}^n \frac{\1\{W_i=w\}\1\{S_i = s\}}{\pi_w(s)}\eta_{i,w}(y,s) + \sum_{s \in \mathcal{S}} \frac{D_w(s)}{\sqrt{n}\pi_w(s)}\mu_w(y,s) + \sum_{i=1}^n \frac{\mu_w(y,S_i)}{\sqrt{n}} \notag \\
& - \sum_{i=1}^n \sum_{s \in \mathcal{S}}\frac{\1\{W_i=w\}\1\{S_i = s\}D_w(s)}{n(s)\sqrt{n}\hat{\pi}_w(s)\pi_w(s)}\eta_{i,w}(y,s) -  \sum_{s \in \mathcal{S}} \frac{D_w(s)\mu_w(y,s)}{n(s)\sqrt{n}\hat{\pi}_w(s)\pi_w(s)} D_w(s) - \sum_{s \in \mathcal{S}} \frac{D_w(s)\mu_w(y,s)}{\sqrt{n}\hat{\pi}_w(s)} \notag \\
& = \sum_{s \in \mathcal{S}} \frac{1}{\sqrt{n}}\sum_{i =1}^n \frac{\1\{W_i=w\} \1\{S_i = s\}}{\pi_w(s)}\eta_{i,w}(y,s)  + \sum_{i=1}^n \frac{\mu_w(y,S_i)}{\sqrt{n}}+ I_{1,1}(y),
\end{align*}
where 
\begin{align*}
I_{1,1}(y) = & - \sum_{i=1}^n \sum_{s \in \mathcal{S}}\frac{\1\{W_i=w\}1\{S_i = s\}D_w(s)}{n(s)\sqrt{n}\hat{\pi}_w(s)\pi_w(s)}\eta_{i,w}(y,s) -  \sum_{s \in \mathcal{S}} \frac{D_w(s)\mu_w(y,s)}{n(s)\sqrt{n}\hat{\pi}_w(s)\pi_w(s)} D_w(s) \\
& + \sum_{s \in \mathcal{S}} \frac{D_w(s)\mu_w(y,s)}{\sqrt{n}}\left(\frac{1}{\pi_w(s)} - \frac{1}{\hat{\pi}_w(s)}\right) \\
& = - \sum_{i=1}^n \sum_{s \in \mathcal{S}}\frac{\1\{W_i=w\}\1\{S_i = s\}D_w(s)}{n(s)\sqrt{n}\hat{\pi}_w(s)\pi_w(s)}\eta_{i,w}(y,s).
\end{align*}

Note that the class $\{\1\{Y_i(w) \leq y\} - \mu_w(y,S_i):y \in \Y\}$ is of the VC-type with fixed coefficients $(\alpha,v)$ and bounded envelope,  and $\E[\1\{Y_i(w) \leq y\} - \mu_w(y,S_i)|S_i=s] = 0$. Therefore,
\begin{align*}
\sup_{y\in\Y,s\in\S}\left|\frac{1}{\sqrt{n}}\sum_{i =1}^n \1\{W_i=w\}\1\{S_i=s\}\eta_{i,w}(y,s)\right|  = O_p(1).
\end{align*}
By Assumption \ref{ass:dgp_treatment_assignment}, for all $w\in\W$, we have $\max_{s \in \mathcal{S}}|D_w(s)/n(s)| = o_p(1)$, $\max_{s \in \mathcal{S}}|\hat{\pi}_w(s) - \pi_w(s)| = o_p(1)$, and $\min_{s \in \mathcal{S}} \pi_w(s)>c>0$, which imply $\sup_{y\in\Y}|I_{1,1}(y)| = o_p(1)$. 

Next, we analyze the second term $I_2(y)$.
\begin{align*}
I_2(y) & = \frac{1}{\sqrt{n}} \sum_{s \in \mathcal{S}} \sum_{i =1}^n\frac{\1\{W_i=w\}}{\hat{\pi}_w(s)} \mu_w(y,s,X_i)\1\{S_i=s\} - \frac{1}{\sqrt{n}}\sum_{i =1}^n  \mu_w(y, S_i,X_i) \notag \\
& + \frac{1}{\sqrt{n}} \sum_{s \in \mathcal{S}} \frac{1}{\hat{\pi}_w(s)}\sum_{i =1}^n(\1\{W_i=w\} - \hat{\pi}_w(s))\left(\widehat{\mu}_w(y,s,X_i) - \mu_w(y,s,X_i)\right)\1\{S_i=s\} \notag \\
& =  \frac{1}{\sqrt{n}} \sum_{s \in \mathcal{S}} \sum_{i =1}^n\frac{\1\{W_i=w\}}{\hat{\pi}_w(s)} (\mu_w(y,s,X_i) - \mu_w(y,s))\1\{S_i=s\} - \frac{1}{\sqrt{n}}\sum_{i =1}^n  \left(\mu_w(y,S_i,X_i)-\mu_w(y,S_i)\right) \notag \\
& + \frac{1}{\sqrt{n}} \sum_{s \in \mathcal{S}} \frac{1}{\hat{\pi}_w(s)}\sum_{i =1}^n(\1\{W_i=w\} - \hat{\pi}_w(s))\left(\widehat\mu_w(y,s,X_i) - \mu_w(y,s,X_i)\right)\1\{S_i=s\} \notag \\
& =  \frac{1}{\sqrt{n}} \sum_{s \in \mathcal{S}} \sum_{i =1}^n\frac{\1\{W_i=w\}}{\pi_w(s)} (\mu_w(y,s,X_i) - \mu_w(y,s))\1\{S_i=s\} - \frac{1}{\sqrt{n}}\sum_{i =1}^n  \left(\mu_w(y,S_i,X_i)-\mu_w(y,S_i)\right) \notag \\
& + \underbrace{\frac{1}{\sqrt{n}} \sum_{s \in \mathcal{S}} \left(\frac{\pi_w(s) - \hat{\pi}_w(s)}{\hat{\pi}_w(s)\pi_w(s)}\right)\left(\sum_{i =1}^{n}\1\{W_i=w\} (\mu_w(y,s,X_i) - \mu_w(y,s))\1\{S_i=s\}\right)}_{\equiv I_{2,1}(y)} \notag \\
& + \underbrace{\frac{1}{\sqrt{n}} \sum_{s \in \mathcal{S}} \frac{1}{\hat{\pi}_w(s)}\sum_{i =1}^n(\1\{W_i=w\} - \hat{\pi}_w(s))\left(\widehat\mu_w(y,s,X_i) - \mu_w(y,s,X_i)\right)\1\{S_i=s\}}_{\equiv I_{2,2}(y)} \notag \\
\end{align*}
where the second equality holds because 
\begin{align*}
\sum_{s \in \mathcal{S}}\sum_{i=1}^{n}\frac{\1\{W_i=w\}}{\hat{ \pi}_w(s)}\mu_w(y,s)\1\{S_i=s\} = \sum_{s \in \mathcal{S}}n(s)\mu_w(y,s) = \sum_{i =1}^n\mu_w(y,S_i). 
\end{align*}

For the first term $I_{2,1}(y)$, we have
\begin{align*}
&\sup_{y \in \Y}\left|\frac{1}{\sqrt{n}} \sum_{s \in \mathcal{S}} \left(\frac{\pi_w(s) - \hat{\pi}_w(s)}{\hat{\pi}_w(s)\pi_w(s)}\right)\left(\sum_{i =1}^n\1\{W_i=w\} (\mu_w(y,s,X_i) - \mu_w(y,s))\1\{S_i=s\}\right)\right|\\
& \leq \sum_{s \in \mathcal{S}} \left|\frac{D_w(s)}{n_w(s) \pi_w(s)}\right|\sup_{y \in \Y,s\in \mathcal{S}}\left|\frac{1}{\sqrt{n}}\sum_{i =1}^n\1\{W_i=w\}\1\{S_i=s\}(\mu_w(y,s,X_i) - \mu_w(y,s))\right|.
\end{align*}
Assumption \ref{ass:asymptotic-dist} implies that the class $\{ \mu_w(y,s,X_i) - \mu_w(y,s) : y \in \Y\}$ is of the VC-type with fixed coefficients $(\alpha,v)$ and an envelope $F_i$ such that $\mathbb{E}(|F_i|^d|S_i=s)<\infty$ for $d>2$. Therefore, 
\begin{align*}
\sup_{y \in \Y,s\in \mathcal{S}}\left|\frac{1}{\sqrt{n}}\sum_{i =1}^n\1\{W_i=w\}\1\{S_i=s\}(\mu_w(y,s,X_i) - \mu_w(y,s))\right| = O_p(1). 
\end{align*}
It is also assumed that $D_w(s)/n(s) = o_p(1)$ and $n(s)/n_w(s)\overset{p}{\longrightarrow} 1/\pi_w(s)<\infty$. Therefore, we have
\begin{align*}
\sup_{y \in \Y}\left|I_{2,1}(y)\right| = o_p(1). 
\end{align*}

As for the second term $I_{2,2}(y)$, using the notation $\delta_w(y,s,X_i) = \widehat\mu_w(y,s,X_i) -\mu_w(y,s,X_i)$, by Assumption \ref{ass:asymptotic-dist}(i), we have 
\begin{align*}
& \sup_{y\in\Y} \left|\frac{1}{\sqrt{n}} \sum_{s \in \mathcal{S}} \frac{1}{\hat{\pi}_w(s)}\sum_{i =1}^n(\1\{W_i=w\} - \hat{\pi}_w(s))\delta_w(y,s,X_i)\1\{S_i=s\}\right| \\
\leq & \frac{1}{\sqrt{n}}\sum_{s \in \mathcal{S}}n(s)\sup_{y \in \Y}\biggl|\frac{\sum_{i\in I_w(s)}\delta_w(y,s,X_i)}{n_w(s)} - \frac{\sum_{i \in I_{w'}(s)}\delta_{w}(y,s,X_i)}{n_{w'}(s)}\biggr| = o_p(1).
\end{align*}
Therefore, we have
\begin{align*}
\sup_{y \in \Y}|I_{2,1}(y)+I_{2,2}(y) | = o_p(1).
\end{align*} 

Combining the two terms, we have
\begin{align*}
\sqrt{n}( \widehat F_{Y(w)}^{adj}(y) - F_{Y(w)}(y)) & = \sum_{s \in \mathcal{S}} \frac{1}{\sqrt{n}}\sum_{i =1}^n \1\{W_i=w\} \1\{S_i = s\}\left[\frac{\eta_{i,w}(y,s)}{\pi_w(s)} + \left(1-\frac{1}{\pi_w(s)}\right)\left(\mu_w(y,s,X_i)-\mu_w(y,s)\right) \right] \\
&+ \sum_{s \in \mathcal{S}} \frac{1}{\sqrt{n}}\sum_{i =1}^n (1-\1\{W_i=w\}) \1\{S_i = s\}\left(\mu_w(y,s,X_i)-\mu_w(y,s)\right) \\
& + \sum_{i=1}^n \frac{\mu_w(y,S_i)}{\sqrt{n}} + R_{1,1}(y),  
\end{align*}
where $\sup_{y\in\Y}|R_{1,1}(y)|=o_p(1)$.

Define 
\begin{align}
\label{eq:phi_xyz}
\phi_{w}(y, S_i, Y_i(w), X_i) : = & \frac{\eta_{i,w}(y,s)}{\pi_w(s)} + \left(1-\frac{1}{\pi_w(s)}\right)\left(\mu_w(y,s,X_i)-\mu_w(y,s)\right) - 
\left(\mu_{w'}(y,s,X_i)-\mu_{w'}(y,s)\right), \\
\zeta_i(y) : = &  \mu_w(y,S_i) - \mu_{w'}(y,S_i). \notag
\end{align}

Taking the difference between treatments $w$ and $w'$, we obtain
\begin{align*}
\sqrt{n} \big (\widehat \Delta^{DTE, adj}_{w, w'}(y) - \Delta^{DTE}_{w, w'}(y) \big) 
& =  \sum_{s \in \mathcal{S}} \frac{1}{\sqrt{n}}\sum_{i =1}^n \1\{W_i=w\} \1\{S_i = s\} \phi_{w}(y, S_i, Y_i(w), X_i) \\
& - \sum_{s \in \mathcal{S}} \frac{1}{\sqrt{n}}\sum_{i =1}^n \1\{W_i=w'\} \1\{S_i = s\}\phi_{w'}(y, S_i, Y_i(w'), X_i)\\
&  + \frac{1}{\sqrt{n}}  \sum_{i=1}^n\zeta_i(y) + R(y),
\end{align*}
where $\sup_{y\in\Y}|R(y)|=o_p(1)$. Denote
\begin{align*}
\varphi_{n,1}(y) := & \sum_{s \in \mathcal{S}}\frac{1}{\sqrt{n}}\sum_{i =1}^n \1\{W_i=w, S_i=s\} \phi_w(y,s,Y_i(w),X_i) - \sum_{s \in \mathcal{S}}\frac{1}{\sqrt{n}}\sum_{i =1}^n
\1\{W_i=w',S_i=s\}\phi_{w'}(y,s,Y_i(w'),X_i),
\end{align*}
and 
\begin{align*}
\varphi_{n,2}(y) := \frac{1}{\sqrt{n}} \sum_{i =1}^n\zeta_i(y).
\end{align*}
Then, uniformly over $y\in\Y$,  we first show that
\begin{align*}
(\varphi_{n,1}(y),\varphi_{n,2}(y)) \rightsquigarrow (\mathcal{G}_1(y),\mathcal{G}_2(y)),
\end{align*}
where $(\mathcal{G}_1(y),\mathcal{G}_2(y))$ are two independent Gaussian processes with covariance kernels $\Omega_1(y,y')$ and $\Omega_2(y,y')$, respectively, such that  
\begin{align*}
\Omega_1(y,y') =&  \mathbb{E}[\pi_w(S_i)\phi_w(y,S_i,Y_i(w),X_i)\phi_w(y',S_i,Y_i(w),X_i)]\\
&  + \mathbb{E}[\pi_{w'}(S_i)\phi_{w'}(y,S_i,Y_i(w'),X_i)\phi_{w'}(y',S_i,Y_i(w'),X_i)],
\end{align*}
and 
\begin{align*}
\Omega_2(y,y') = \mathbb{E}[\zeta_i(y)\zeta_i(y')]. 
\end{align*}

The following argument follows the argument provided in the proofs of \citet[Lemma B.2]{bugni2018inference} and \citet[Lemma C.1]{bugni2019inference}. We first argue that, uniformly over $y \in \Y$, 
\begin{align*}
(\varphi_{n,1}(y), \varphi_{n,2}(y)) \rightsquigarrow  ( \varphi^\star_{n,1}(y), \varphi_{n,2}(y)), 
\end{align*}
where $\varphi^\star_{n,1}(y) \indep \varphi_{n,2}(y)$ and $\varphi^\star_{n,1}(y) \rightsquigarrow \mathcal{G}_1(y)$ uniformly over $y \in \Y$.

Under Assumption \ref{ass:dgp_treatment_assignment}, the distribution of $\varphi_{n,1}(y)$ is the same as the distribution of the same quantity with units ordered by strata $s\in\S$ and then ordered by treatment assignment $w\in\W$ within strata. In order to exploit this observation, we introduce the following notations. Define $N(s) := \sum_{i =1}^n\1\{S_i <s\}$, $N_w(s) := \sum_{i =1}^n\1\{W_i<w, S_i =s\}$, $F(s):= \mathbb{P}(S_i<s)$, and  $F_w(s):= \mathbb{P}(W_i<w, S_i=s)$ for all $(w,s)\in\W\times \S$. Furthermore, let $\{(X_i^s,Y_i^s(1), \dots, Y_i^s(| \mathcal{W}|)): 1\leq i \leq n\}$ be a sequence of i.i.d. random variables with marginal distributions equal to the distribution of $(X_i,Y_i(1),\dots, Y_i(| \mathcal{W}|))|S_i = s$ and 
\begin{align*}
\varphi_{n,1}(y)|\{ (W_i,S_i)_{i \in [n]} \}  & \stackrel{d}{=} \widetilde{\varphi}_{n,1}(y)|\{ (W_i,S_i)_{i \in [n]} \} 
\end{align*}
where
\begin{align*}
\widetilde{\varphi}_{n,1}(y) &:=  \sum_{s \in \mathcal{S}}\frac{1}{\sqrt{n}}\sum_{i = N(s)+N_w(s)+1}^{N(s)+N_{w+1}(s)} \phi_w(y,s,Y^s_i(w),X^s_i) -   \sum_{s \in \mathcal{S}}\frac{1}{\sqrt{n}}\sum_{i = N(s)+N_{w'}(s)+1}^{N(s)+N_{w'+1}(s)} \phi_{w'}(y,s,Y^s_i(w'),X^s_i).
	\end{align*}
As $\varphi_{n,2}(y)$ is only a function of $\{S_i\}_{i \in [n]}$, we have
\begin{align*}
(\varphi_{n,1}(y),\varphi_{n,2}(y)) \stackrel{d}{=} (\widetilde{\varphi}_{n,1}(y),\varphi_{n,2}(y)). 
\end{align*}
Next, define
\begin{align*}
\varphi^\star_{n,1}(y) :=  \sum_{s \in \mathcal{S}}\frac{1}{\sqrt{n}}\sum_{i = \lfloor nF(s)+F_w(s)\rfloor+1}^{\lfloor n(F(s)+F_{w+1}(s))\rfloor} \phi_w(y,s,Y^s_i(w),X^s_i)-\sum_{s \in \mathcal{S}}\frac{1}{\sqrt{n}}\sum_{i = \lfloor n(F(s)+F_{w'}(s))\rfloor+1}^{\lfloor n(F(s)+F_{w'+1}(s)\rfloor} \phi_{w'}(y,s,Y^s_i(w'),X^s_i).
\end{align*}
Note $\varphi^\star_{n,1}(y)$ is a function of $(Y_i^s(1),\dots, Y_i^s(|\W|),X_i^s)_{ i \in [n],s\in \mathcal{S}}$, which is independent of $\{W_i,S_i\}_{i \in [n]}$ by construction. Therefore, 
	\begin{align*}
	\varphi^\star_{n,1}(y) \indep \varphi_{n,2}(y).
	\end{align*} 
Note that 
\begin{align*}
\frac{N(s)}{n} \overset{p}{\longrightarrow} F(s),\quad \frac{N_w(s)}{n} \overset{p}{\longrightarrow} F_w(s), \quad \text{and} \quad \frac{n(s)}{n} \overset{p}{\longrightarrow} p(s). 
\end{align*}
We shall show that 
\begin{align*}
\sup_{y \in \Y}|\widetilde{\varphi}_{n,1}(y) - \varphi^\star_{n,1}(y)| = o_p(1) 
\ \  \text{ and } \ \ 
\varphi_{n,1}^\star(y) \rightsquigarrow \mathcal{G}_1(y).
\end{align*}

Since $\S$ and $\W$ have finite cardinality, we fix 
$(s, w) \in \S \times \W$ in the remainder of the proof.
We define  
$$
\Gamma_{n}(t,\phi_w ) 
:= 
\frac{1}{\sqrt{n}}
\sum_{i =1}^{n}
\1 \{i \le \lfloor nt \rfloor \}
\cdot 
\phi_w \big (y,s,Y_i^s(w),X_i^s \big),
$$ 
for $t \in (0, 1]$. 
The function
$
\phi_w(y,s,Y_i^s(w),X_i^s)
$
defined in (\ref{eq:phi_xyz})
can be decomposed as a weighted sum of bounded random functions indexed by $y \in \Y$
with bounded weight functions. 
More precisely, 
the class 
$
\mathcal{F} := 
\big \{
\phi_w \big (y,s,Y_i^s(w),X_i^s \big)
: y \in \Y 
\big\}
$
consists of functions from the following function classes:
$\mathcal{F}_{1}:= \{ 
y \mapsto \eta_{i,w}(y,s)
\}$,
$\mathcal{F}_{2, w}:= \{y \mapsto \mu_w(y,s,X_i)\}$ 
and 
$\mathcal{F}_{3,w}:= \{y \mapsto \mu_w(y,s)\}$.
We can show that the class $\mathcal{F}_{1}$ is Donsker, for instance, by  using the bounded, monotone property as established in
Theorem 2.7.5 of \citet{van1996weak}. 
Also, 
under Assumption \ref{ass:asymptotic-dist}(ii), 
Theorem 2.5.2 of \citet{van1996weak} yields that 
$\mathcal{F}_{2, w}$
and 
$\mathcal{F}_{3, w}$ are Donsker.
Since all the random weights are uniformly bounded,
Corollary 2.10.13 of \citet{van1996weak} shows that $\mathcal{F}$ 
is Donsker. 
Also, 
the class  $\{ t \mapsto \1 \{i \le \lfloor nt \rfloor \}$
is VC class and hence Donsker. 
Since Theorem 2.10.6 of \citet{van1996weak}
shows that products of uniformly bounded Donsker classes 
are Donsker, 
we conclude that the indexed process 
$\{\Gamma_{n}(t,\phi_w) : t \in (0,1], \phi_w \in \mathcal{F}\}
$
is Donsker. Hence, the result follows.

Next, for a given $y$, by the triangular array central limit theorem, 
\begin{align*}
	\varphi_{n,1}^\star(y) \rightsquigarrow N(0,\Omega_1(y,y)),
	\end{align*}
	where 
	\begin{align*}
	\Omega_1(y,y) &=  \lim_{n\rightarrow \infty} \sum_{s \in \mathcal{S}} \frac{(\lfloor n(F(s)+F_{w+1}(s))\rfloor -\lfloor n(F(s)+F_w(s))\rfloor)}{n}\mathbb{E}[\phi_w^2(y,s,Y_i^s(w),X_i^s)] \\
	& + \lim_{n\rightarrow \infty} \sum_{s \in \mathcal{S}} \frac{(\lfloor n(F(s)+F_{w'+1}(s))\rfloor -\lfloor n(F(s)+F_{w'}(s))\rfloor)}{n}\mathbb{E}[\phi_{w'}^2(y,s,Y_i^s(w'),X_i^s)] \\
	&=  \sum_{s \in \mathcal{S}} p(s) \mathbb{E}[\pi_w(s)\phi_w^2(y,S_i,Y_i(w),X_i) +\pi_{w'}(s)\phi_{w'}^2(y,S_i,Y_i(w'),X_i) |S_i=s] \\
	&=  \mathbb{E}[\pi_w(S_i)\phi_w^2(y,S_i,Y_i(w),X_i)] + \mathbb{E}[\pi_{w'}(S_i)\phi_{w'}^2(y,S_i,Y_i(w'),X_i)].
	\end{align*}

Using the Cram\'{e}r–Wold device to verify finite-dimensional convergence, we find that the covariance kernel can be written as    
\begin{align*}
\Omega_1(y,y') = & \mathbb{E}[\pi_w(S_i)\phi_w(y,S_i,Y_i(w),X_i)\phi_w(y',S_i,Y_i(w),X_i)] \\
& +\mathbb{E}[\pi_{w'}(S_i)\phi_{w'}(y,S_i,Y_i(w'),X_i)\phi_{w'}(y',S_i,Y_i(w'),X_i)].
\end{align*}

Finally, since $\{\mu_w(y,S_i):y \in \Y \}$ is of the VC-type with fixed coefficients $(\alpha,v)$ and a constant envelope function, $\{\mu_w(y,S_i) - \mu_{w'}(y,S_i):y \in \Y \}$ is a Donsker class and we have 
\begin{align*}
\varphi_{n,2}(y) \rightsquigarrow \mathcal{G}_2(y),
\end{align*}
where $ \mathcal{G}_2(y)$ is a Gaussian process with covariance kernel 
\begin{align*}
\Omega_2(y,y') = \mathbb{E} [ (\mu_w(y,S_i) - \mu_{w'}(y,S_i)) \left(\mu_w(y',S_i) - \mu_{w'}(y',S_i)\right) ] \equiv \mathbb{E}[\zeta_i(y)\zeta_i(y')]. 
\end{align*}


Therefore, combining the results, we have, uniformly over $y\in\Y$, 
\begin{align*}
\sqrt{n} \big (\widehat \Delta^{DTE, adj}_{w, w'}(y) - \Delta^{DTE}_{w, w'}(y) \big) \rightsquigarrow \mathcal{G}(y),
\end{align*}
where $\mathcal{G}(y)$ is a Gaussian process with covariance kernel
\begin{align*}
    \Omega(y, y') = &\E[\pi_w(S_i)\phi_w(y, S_i, Y_i(w), X_i)\phi_{w}(y', S_i, Y_i(w), X_i)]\\
    + &\E[\pi_{w'}(S_i)\phi_{w'}(y, S_i, Y_i(w'), X_i)\phi_{w'}(y', S_i, Y_i(w'), X_i)] \\
    + &\E[\zeta_i(y)\zeta_i(y')].
\end{align*}
This concludes the proof.
\end{proof}

\clearpage
\subsection{Semiparametric Efficiency Bound}
\begin{proof}[\textbf{Proof of Theorem \ref{thm:semi-eff-bound}}]
Part (a). We follow the approach used in \citet{hahn1998role} and calculate the semiparametric efficiency bound of the DTE: $\Delta^{DTE}_{w, w'}(u)$ for a given $u\in\Y$. Throughout the proof of part (a), we use $u$ to indicate this evaluation location to keep the notation clear. First, we characterize the tangent space. To that end, the joint density of the observed variables $(Y,W, X, S)$ can be written as:
\begin{align*}
f(y,w,x,s) =  f(y|w,x,s)f(w|x,s)f(x|s)f(s) 
=  \prod_{w=1}^{K}\{f_w(y|x, s)\pi_w(s)\}^{\1\{W=w\}} f(x|s)f(s), \end{align*}
where $f_w(y|x, s) := P(Y=y|W=w, X=x, S=s)$ and $\pi_w(s) := P(W=w|X=x, S=s)$ for all $x\in\mathcal X$.

Consider a regular parametric submodel indexed by $\theta$: 
\begin{align*}
f(y,w,x, s; \theta) :=  \prod_{w=1}^{K} \{f_w(y|x, s; \theta) \pi_w(s; \theta)\}^{\1\{W=w\}}f(x,s ;\theta) f(s; \theta),
\end{align*}
which equals $f(y,w,x, s)$ when $\theta = \theta_0$.

The corresponding score of $f(y,w,x; \theta)$ is given by
\begin{align*}
    s(y,w,x, s; \theta) := & \frac{\partial \ln f(y,w,x,s;\theta) }{\partial\theta} \\
    = & \sum_{w=1}^{K} \Big( \1\{W=w\} \dot{f}_w(y|x,s; \theta) + \1\{W=w\} \dot{\pi}_w(s;\theta) \Big) +\dot{f}(x, s ; \theta) + \dot{f}(s; \theta),
\end{align*}
where $\dot{f}$ denotes a derivative of the log, i.e, $\dot{f}(x; \theta) = \frac{\partial \ln f(x; \theta)}{\partial \theta}$.

At the true value, the expectation of the score equals zero. The tangent space of the model is the set of functions that are mean zero and satisfy the additive structure of the score:
\begin{align}\label{tangent-space}
  \mathcal{T} = \Big\{ \sum_{w=1}^{K} \Big(\1\{W=w\} a_w(y|x,s) + \1\{W=w\} a_{\pi}(s)\Big) + a_x(x,s) + a_s(s)  \Big\},
\end{align}
where $a_w(y|x,s)$, $a_\pi(s)$, $a_x(x,s)$ and $a_s(s)$ are mean-zero functions.

The semiparametric variance bound of $\Delta^{DTE}_{w, w'}(u)$ is the variance of the projection on $\mathcal T$ of a function $\psi_u(Y,W,X, S)$ (with mean zero and finite second order moment) that satisfies for all regular parametric submodels
\begin{equation} \label{semiparametric-bound}
\frac{\partial \Delta^{DTE}_{w,w'}(u; F_\theta)}{\partial \theta}\Big|_{\theta=\theta_0} = \mathbb{E}[\psi_u(Y, W, X,S) \cdot s(Y,W,X,S)]\Big|_{\theta=\theta_0}
\end{equation}

If $\psi_u$ itself already lies in the tangent space, the variance bound is given by $\mathbb{E}[\psi_u^2].$

Now, the DTE is
\begin{align*}
\Delta^{DTE}_{w,w'}(u; F_\theta) = &
\iiint \1\{y \leq u\} f_w(y|x,s; \theta) f(x|s; \theta)f(s;\theta)dy dx ds \\
&- \iiint \1\{y \leq u\} f_{w'}(y|x,s; \theta) f(x|s; \theta)f(s;\theta)dy dx ds.  
\end{align*}

We thus have
\begin{align*}
\frac{\partial \Delta^{DTE}_{w,w'}(u; F_\theta)}{\partial \theta} |_{\theta=\theta_0} = & \iiint \1\{y \leq u\}\dot{f}_w(y|x,s; \theta) f_w(y|x, s)f(x|s)f(s)dydxds \\
& + \iint \mu_w(u,s,x)\dot{f}(x|s; \theta) f(x|s)f(s) dxds \\
& + \int \mu_w(u, s,x)f(x|s)\dot{f}(s; \theta) f(s) ds  \\
& - \iiint \1\{y \leq u\}\dot{f}_{w'}(y|x,s; \theta) f_{w'}(y|x, s)f(x|s)f(s)dydxds\\
& - \iint \mu_{w'}(u,s,x))\dot{f}(x|s; \theta) f(x|s)f(s) dxds \\
& - \int \mu_{w'}(u,s,x)f(x|s)\dot{f}(s; \theta) f(s) ds. 
\end{align*}

Letting $\mu_{w,w'}(u, S, X):=\mu_w(u,S,X) - \mu_{w'}(u,S,X)$, we choose $\psi_u(Y, W, X,S)$ as 
\begin{align*}
\psi_u(Y,W,X, S) = & \frac{\1\{W=w\}}{\pi_w(S)}(\1\{Y\leq u\}-\mu_w(u,S,X)) - \frac{\1\{W=w'\}}{\pi_{w'}(S)}(\1\{Y\leq u\}- \mu_{w'}(u,S,X))\\
& + \mu_{w,w'}(u,S,X) - \Delta^{DTE}_{w, w'}(u).
\end{align*}

Notice that $\psi_u$ satisfies equation \eqref{semiparametric-bound} and that $\psi_u$ lies in the tangent space $\mathcal{T}$ given in equation \eqref{tangent-space}. Since $\psi_u$ lies in the tangent space, the variance bound is given by the expected square of $\psi_u$:
\begin{align*}
\Omega(u): = \E \big[ & \psi_u(Y,W,X, S)^2 \big] \\
     =  \E \Big[ & \Big(\frac{\1\{W=w\}}{\pi_w(S)}(\1\{Y\leq u\}-\mu_w(u,S,X)) - \frac{\1\{W=w'\}}{\pi_{w'}(S)}(\1\{Y\leq u\}- \mu_{w'}(u,S,X)) \\
     + & \mu_{w, w'}(u,S,X) - \Delta^{DTE}_{w, w'}(u)\Big) ^2 \Big] \\
     = \E[ & \pi_w(S)\phi_w^2(u, S, Y(w), X)]
     + \E[\pi_{w'}(S)\phi_{w'}^2(u, S, Y(w'), X)]+ \E[\zeta_i^2(u)].
\end{align*}
This concludes the proof of part (a).

Next, for part (b), under Assumption \ref{ass:asymptotic-dist}, the regression-adjusted estimator defined in Algorithm \ref{alg:reg-adj-estimator}  satisfies the following asymptotic distribution for any given $y\in\Y$:
\begin{align*}
\sqrt{n} \big (\widehat \Delta^{DTE, adj}_{w, w'}(y) - \Delta^{DTE}_{w, w'}(y) \big) \rightsquigarrow  \mathcal N(0, \Omega(y)),
\end{align*}
where $\Omega(y)$ is the semiparametric efficiency bound derived in part (a). This completes the proof of part (b).
\end{proof}

\begin{proof}[\textbf{Proof of Corollary \ref{cor:variance-reduction}}]
The result follows directly from the fact that, for a given $y\in\Y$,  $\widehat\Delta^{DTE,emp}_{w, w'}(y)$ is a regular, consistent and asymptotically normal estimator for the DTE. Moreover, the variance of $\tilde\Delta^{DTE, adj}_{w, w'} (y)$ coincides with the semiparametric efficiency bound $\Omega(y)$ established in Theorem \ref{thm:semi-eff-bound}. Consequently, we obtain
\begin{align*}
Var\big (\tilde\Delta^{DTE, adj}_{w, w'}(y)\big ) \leq Var\big (\widehat\Delta^{DTE,emp}_{w, w'}(y)\big ),
\end{align*}
which concludes the proof. 
\end{proof}

