\title{Lagrangian Translating Solitons and Special Lagrangians in $\mathbb{C}^{m}$ with Symmetries}

\author{Wei-Bo Su}
\address{National Center for Theoretical Sciences, Mathematics Division, Taipei 106319, Taiwan}
\email{weibo.su@ncts.tw}


