\section{Preliminaries}

Throughout, we work in $\mathbb{C}^m$ for $m \geq 2$, equipped with its usual Calabi-Yau structure: the Euclidean metric $g_0$, the K\"ahler form $\omega_0 = \sum_{i=1}^m dx_i \wedge dy_i$, and the holomorphic volume form $\Omega_0 := dz_1 \wedge\ \ldots \wedge dz_m$.

\subsection{Lagrangian Translators}\label{sec-lagtrans}

Let $F:L\to\mathbb{C}^{m}$ be an oriented Lagrangian immersion, with unit volume form $\text{vol}_L$. The immersion is said to be \textit{zero-Maslov} if there exists a function $\theta: L \to \mathbb{R}$ satisfying $F^*(\Omega_0) = e^{i\theta}\text{vol}_L$. In this case, we have the differential relation $J\nabla \theta = \vec{H}$, where $\vec{H}$ is the mean curvature vector of the immersion $F$. 

$F$ is called a \textit{special Lagrangian submanifold} if $\vec{H} = 0$, equivalently if $\theta = \overline\theta$ for some $\overline\theta\in\mathbb{R}$. Such submanifolds are calibrated by the form $\text{Re}(e^{-i\overline\theta}\Omega_0)$, and therefore volume-minimising \cite{HL82}. If instead the range of $\theta$ is less than $\pi$, we say the Lagrangian is \textit{almost-calibrated}. 

$F$ is called  a \textit{Lagrangian translating soliton} (in the $e_m$ direction) if $\vec{H}  = e_{m}^{\perp}$ (where $e_{m} = (0, \cdots, 0, 1)$). The name comes from the fact that for such an $F$, the translating family of immersions $F_t := F + t e_m$ satisfies mean curvature flow. As in the special Lagrangian case, we may integrate to a scalar equation involving $\theta$:
\begin{align}\label{eq-translator}
    \theta(F) + \langle F, Je_{m}\rangle = c
\end{align}
for some $c\in\mathbb{R}$. By a translation in the $Je_{m}$-direction, we may assume $c = 0$. Thus, the imaginary part of the last coordinate function $F_{m}$ is equal to $-\theta(F)$.

It was noted in \cite{Su2019a} that for $f = -2\langle F, e_m\rangle$, the weighted volume $e^{-\frac{f}{2}}\text{vol}_{L}$ of a Lagrangian translating soliton is calibrated by $\re\Omega_{f}$, where in our case
\begin{align}
    \Omega_{f} := e^{z_{m}}dz_{1}\wedge\cdots\wedge dz_{m} \, = \, e^{z_m} \Omega_0.
\end{align}
Hence, an equivalent condition for $F:L\to\mathbb{C}^{m}$ being a Lagrangian translating soliton is
\begin{align}
    F^{*}\omega = F^{*}\im\Omega_{f} = 0. \label{eq-translatorcalibration}
\end{align}

\subsection{Lie Group Actions}\label{sec-liegroupactions}

Consider a group action $G \circlearrowright M$ for $M$ a  manifold, say of dimension $n$. For a point $z \in M$, we denote the \textit{orbit} by $\mathcal{O}_z := \{g \cdot z \, : \, g \in G\}$, and the \textit{isotropy subgroup} or \textit{stabiliser} by $G_z = \Stab(z) := \{g \in G\,:\, g\cdot z = z\}$. For $X \in \mathfrak{g}$, we denote the \textit{fundamental vector field} associated to $X$ by $\rho(X)_z := \frac{\partial}{\partial t}|_{t=0} (\exp(-tX) \cdot z)$. 

We say $z \in M$ has \textit{isotropy type $(H)$} for a subgroup $H \leq G$ if the isotropy group $G_z$ of $z$ is conjugate to $H$. Given $H \leq G$, we denote the set of points in $M$ with isotropy type $H$ by $M_{(H)}$. We note that the orbit $\mathcal{O}_z$ is diffeomorphic to the quotient $G / G_z$, and in particular $\text{dim}(\mathcal{O}_z) = \text{dim}(G) - \text{dim}(G_z)$.

We will say $M$ is \textit{cohomogeneity-$k$} if every point of $M$ has the same isotropy type $(H)$ (i.e. $M = M_{(H)}$) and $\text{dim}(G/H) = n-k$. This implies that all orbits in $M$ have dimension $n-k$. We remark that our notion of cohomogeneity-$k$ is slightly stricter than that of some other authors, who may allow orbits of different types, and `singular orbits' of lower dimensions.

Now assume $(M, \omega)$ is symplectic, and $G \circlearrowright M$ is a compact Hamiltonian group action\footnote{For an introduction to Hamiltonian group actions and moment maps, see \cite{DaSilva2006}.} with moment map $\mu:M \to \mathfrak{g}$, where $\mathfrak{g}$ and $\mathfrak{g}^*$ are identified via an $\text{Ad}$-invariant inner product (e.g. $M = \mathbb{C}^m$, $G \leq U(m)$ and $\mu:\mathbb{C}^m \to \mathfrak{g}$ the standard moment map of equation \eqref{eq-standardmomentmap}). We have the following useful result regarding the level sets of the moment map.

\begin{theorem}[Principal Orbit Theorem for Moment Map Level Sets]\label{thm-principalorbitthm}
    Let $X \in \mathfrak{g}$, and let $Z \subset \mu^{-1}(X)$ be a connected component of the level set of $\mu$ at $X$.
    \begin{itemize}
        \item For each conjugacy class $(K)$ of $G$, $Z_{(K)}$ is a smooth submanifold of $M$.
        \item There exists a unique conjugacy class $(H)$ of $G$ such that $Z_{(H)}$ is open, connected and dense in $Z$.
        \item If $(K) \neq (H)$ and $Y$ is a connected component of $Z_{(K)}$, then $\dim(Y) < \dim(Z_{(H)})$.
    \end{itemize}
\end{theorem}
\begin{proof}
     The claims follow from the stratification of $Z / G$ by orbit types (see \cite[Theorem 2.1]{Sjamaar1991}). For the second claim in particular, see \cite[Remark 5.10]{Sjamaar1991}.
\end{proof}

\subsection{The Affine Unitary Group}

Of particular importance to this work is the \textit{affine unitary group}, defined as the semidirect product
\[ \text{AU}(m) = \U(m) \ltimes \mathbb{C}^n = \{ (A, t) \, : \, A \in \U(m), \, t \in \mathbb{C}^n\}\]
with group product $(A_1, t_1) \cdot (A_2, t_2) = (A_1 A_2, A_1 t_2 + t_1)$. 
% The Lie algebra of $AU(m)$ is
% \[\mathfrak{au}(m) \, = \, \mathfrak{u}(n)\ltimes \mathbb{C}^m \,= \, \{(X, v) \, : \, X \in \mathfrak{u}(n), \, v \in \mathbb{C}^m\} \]
% with Lie bracket $[(X_1,v_1),(X_2,v_2)] \, = \, (X_1X_2 - X_2X_1, \, X_1v_2 - X_2v_1)$. We will also require the following formula for the exponential map $\exp:\mathfrak{au}(m) \to AU(m)$:
% \begin{equation}\label{eq-affineexponential}
%     \exp_{\mathfrak{au}(m)}(X, v) \, = \, \left(\exp_{\mathfrak{u}(m)}(X), \, \left[\text{Id} + \frac{1}{2!}X + \frac{1}{3!}X^2 + \ldots\right]v \right)
% \end{equation}
$\text{AU}(m)$ has a natural action on $\mathbb{C}^m$, given by $(A, t)\cdot z := Az + t$.
% and an adjoint action on $\mathfrak{au}(m)$, given by
% \begin{equation} \label{eq-affineadjointaction}
% \text{Ad}_{(A, t)}(X, v) \, = \, (AXA^{-1}, \, Av - AXA^{-1}v).
% \end{equation}
We note that by the Mazur-Ulam theorem, any group action preserving $(g_0, \omega_0)$ must be a subgroup of $\text{AU}(m)$:

\begin{lemma}
    If $G \circlearrowright \mathbb{C}^m$ is an effective group action preserving $g_0$ and $\omega_0$, then $G$ is isomorphic to a subgroup of $\emph{AU}(m)$, and the group action is induced by this isomorphism.
\end{lemma}

\section{Affine Group Actions Preserving $\Omega_f$}\label{sec-affinegroups}

Our aim is to construct $G$-invariant Lagrangian translating solitons for affine groups $G \leq \text{AU}(m)$ acting on complex Euclidean space $\mathbb{C}^m$ via the natural action. In light of equation \eqref{eq-translatorcalibration}, it is natural to restrict to subgroups $G \leq \text{AU}(m)$ preserving the form $\Omega_f$. In this section, we investigate such subgroups. Here are a couple of motivational examples:
\begin{example}
    The special orthogonal group $\SO(m-1)$ acts on $\mathbb{C}^m$ by acting on $\mathbb{C}^{m-1}$ in the standard way and by acting trivially on the final factor $\mathbb{C}$. Since $\SO(m-1) \leq \SU(m-1)$, and since it acts trivially on the $m$th factor, it is clear that this action preserves $(g_0, \omega_0, \Omega_f)$.
\end{example}
\begin{example}\label{ex-um-1}
    The universal cover of $\U(m-1)$ is $\SU(m-1) \times i\mathbb{R}$, with projection
\begin{align*}
    \pi:\widetilde{\U(m-1)} &\rightarrow \U(m-1)\\
    (B, i\theta) &\mapsto e^{i\theta}B.
\end{align*} 
Let $B: \widetilde{\U(m-1)}\to \SU(m-1)$, $\theta:\widetilde{\U(m-1)}\to \mathbb{R}$ be the projections. For any subgroup $G \leq \widetilde{\U(m-1)}$, we get an affine action $G \circlearrowright \mathbb{C}^{m}$:
\[ g \cdot (z', z_m) := \left(e^{i\theta(g)}B(g)\cdot z', \, z_m - i(m-1)\theta(g)\right).\]
It can be easily shown that such group actions preserve $(g_0, \omega_0, \Omega_f)$. The action of $\SO(m-1)$ in Example 1 is a special case of this group action.
\end{example}

The second example shows that certain `twisted' group actions are allowed, where a linear action of the first $(m-1)$ coordinates is paired with a translation in the final coordinate. We now generalise this observation, and find the most general subgroup of $\text{Aut}(\mathbb{C}^m)$ preserving $(g_0, \omega_0, \Omega_f)$. Recall that an automorphism $\phi:\mathbb{C}^m \to \mathbb{C}^m$ preserves $\Omega_f$ if for all $z \in \mathbb{C}^m$ and all $X_1, \ldots, X_m \in T_z\mathbb{C}^m$,
\[  (\Omega_f)_z(X_1, \ldots, X_m) = (\Omega_f)_{\phi(z)}(\phi_*(X_1), \ldots, \phi_*(X_m)). \]
In the case of $(A, t) \in \text{AU}(m)$, this is equivalent to 
\begin{align*}
    e^{z_m}\Omega(X_1, \ldots, X_m) \, &= \, (\Omega_f)_{Az + t}((A,t)_*X_1, \ldots, (A,t)_*X_m)\\
    &= \, e^{(Az + t)_m}\det(A)\,\Omega(X_1, \ldots, X_m)\\
    \iff e^{(Az + t)_m} \det(A) &= e^{z_m}.
\end{align*} 
By considering several values of $z \in \mathbb{C}^m$, this is equivalent to 
% \begin{align*}
%     e^{t_m + (Az)_m + (m-1)\theta\, i} &= e^{z_m}\quad \quad \quad \quad\text{ for all } z \in \mathbb{C}^n,\\ 
%     \iff \exists k \in \mathbb{Z} \,\text{ s.t. }\, t_m + (Az)_m + (m-1)\theta i&= z_m + 2\pi k i \quad \text{ for all } z \in \mathbb{C}^n.
% \end{align*}
% By changing $\theta$ by a multiple of $\frac{2\pi}{m-1}$, we may assume that $k=0$. It follows that if $(A,t)\in AU(m)$ preserves $\Omega_f$, then
\begin{align*}
\begin{cases}
    (Az)_m = z_m ,\\
    e^{t_m} = \text{det}(A)^{-1}.
\end{cases}
\end{align*}
We can therefore conclude that 
\begin{align*}
        A = \begin{pmatrix}
            B & b \\ 0 & 1
        \end{pmatrix}, \,\,\,\,
        t = \begin{pmatrix}
            t' \\
            - i \theta
        \end{pmatrix},
\end{align*}
for some $B \in \U(m-1)$, $b, \,t' \in \mathbb{C}^{m-1}$, and $\theta \in \mathbb{R}$ satisfying $e^{i\theta} = \det(A) = \det(B)$. To sum up, we have the following result:

\begin{proposition}\label{prop-affinegrouppreservingomegaf}
The subgroup of $\emph{AU}(m)$ that preserves $\Omega_f$, which we denote $G_f$, is given by:
\begin{align*}
       G_f \, = \, \bigg\{ \bigg(
         \begin{pmatrix}
            B & b \\ 0 & 1
        \end{pmatrix}&, \,\begin{pmatrix}
            t' \\
            -i\theta  
        \end{pmatrix} \bigg) \in AU(m) \,:\\
        &B \in \U(m-1), \, b,\,t' \in \mathbb{C}^{m-1}, \, \theta \in \mathbb{R}, \,e^{i\theta}= \det(B) \bigg\},
\end{align*}
with action on $\mathbb{C}^{m}$ induced by the action of $AU(m)$:
\begin{align}
    \left(
    \begin{pmatrix}
        B & b \\ 0 & 1
    \end{pmatrix}, \,\begin{pmatrix}
        t' \\
        -i\theta 
    \end{pmatrix} \right) \cdot
    \begin{pmatrix}
        z'\\ z_m
    \end{pmatrix}
    =
    \begin{pmatrix}
    B z' + b z_m + t' \\ z_m - i \theta
    \end{pmatrix}.\label{eq-gfaction}
\end{align}
\end{proposition} 

\begin{example}
The group $\widetilde{\U(m-1)}$ considered in Example \ref{ex-um-1} is precisely the subset of $G_f$ for which $b=0,\, t'=0$, with the corresponding group action on $\mathbb{C}^m$.
\end{example}

If $G \leq G_f$ is the symmetry group of an \textit{almost-calibrated} Lagrangian translating soliton $L$ with no linear factor (i.e. $L$ is not a Riemannian product of $L'$ with a line), then a further restriction can be made:

\begin{proposition} Let $G \leq G_f$, and let $L \subset \mathbb{C}^{m}$ be a $G$-invariant, almost-calibrated, Lagrangian translating soliton with no linear factor. Then $G \leq \emph{ASU}(m-1)$.
\end{proposition}\label{prop-acadmissiblegroup}
\begin{proof}
    Since $L$ is almost-calibrated, we have from (\ref{eq-translator}) that the imaginary part of the $z_m$ coordinate is bounded on both sides, i.e. there exist $c, C$ such that $L \subset \{z \in \mathbb{C}^m \, : \, c < \text{Im}(z_m) < C\}.$ It follows from the expression (\ref{eq-gfaction}) for the group action that $\theta = 0$ for all $g \in G$. Furthermore, since $L$ does not split off a line, we can conclude that $G$ preserves the translation direction $e_m$, and so $b = 0$ for all $g \in G$. 
\end{proof}

\begin{remark}
    If $L$ is a special Lagrangian, then it may be shown that the connected symmetry subgroup $\emph{Sym}^0(L) \leq \emph{AU}(m)$ is a subgroup of $\emph{ASU}(n)$. It would be desirable to establish the analogous result for Lagrangian translators, namely that if $L$ is a Lagrangian translator then $G:=\emph{Sym}^0(L) \leq G_f$. It may be proven using Lie group structure theory that if $L$ is a Lagrangian translator with no linear component, and if the elements of $G$ have no translational component in the direction of $e_m$, then this is the case.
\end{remark}

\section{$G$-invariant Lagrangian Submanifolds}\label{sec-4}

We now develop structure theory for $G$-invariant Lagrangian submanifolds in $\mathbb{C}^m$ for $m \geq 2$. With Section \ref{sec-affinegroups} in mind, we restrict to $G \leq \text{ASU}(m-1)$.

\subsection{Symmetric Lagrangians with Linear Symmetry Group}\label{sec-glinear}

We first consider the linear case. Consider a compact, connected subgroup $G \leq \SU(m-1)$ along with its natural action on $\mathbb{C}^{m-1}$. We will show that a cohomogeneity-two Lagrangian $L \subset \mathbb{C}^n$ is characterised by the surface $\check L$ given by intersection with a `complex profile plane', and we provide conditions on $\check L$ which equate to $L$ being special Lagrangian or a translating soliton for mean curvature flow. The results of this section adapt the work of Madnick--Wood \cite{Wood2022}. 

We first make the key observation that $G$-invariant Lagrangian submanifolds are contained in level sets of the moment map; indeed in the \textit{principal part} of those level sets.

\begin{proposition}[$G$-invariant Lagrangians are contained in $\mu$ level sets]\label{prop-laginlevelset}
    Let $G \leq \SU(m-1)$ be compact and connected, and consider the action $G \circlearrowright \mathbb{C}^{m-1}$. Let $\mu:\mathbb{C}^{m-1}\to \mathfrak{g}$ be the standard moment map, and let $L$ be a closed, immersed Lagrangian submanifold. Then:
    \begin{itemize}
        \item[a)] $L$ is $G$-invariant if and only if there exists $X \in \mathfrak{g}$ fixed by the coadjoint action such that $L \subset \mu^{-1}(X)$.
        \item[b)] $L$ is $G$-invariant of cohomogeneity-$k$ and isotropy type $(H)$ if and only if there exists $X \in \mathfrak{g}$ fixed by the coadjoint action and a connected component $Z$ of $\mu^{-1}(X)$ such that $Z_{(H)}$ is open, connected and dense in $Z$, $L \subset Z_{(H)}$ and $\dim(Z) = \dim(Z_{(H)}) =  m-1+k$.
    \end{itemize}
\end{proposition}

\begin{proof}
    For part a), the forward direction follows from \cite[Proposition 4.2]{Joyce2001a}, and the converse is \cite[Corollary 3.13]{Wood2022}. For part b), the reverse direction follows from \cite[Corollary 3.15]{Wood2022}. For the forward direction, consider a cohomogeneity-$k$ Lagrangian $L\subset \mathbb{C}^{m-1}_{(H)}$. By part a) there exists $X \in \mathfrak{g}$ and a connected component $Z$ of $\mu^{-1}(X)$ such that $L \subset Z$. It remains to show that $(H)$ is the principal orbit type of $Z$, in the sense of Theorem \ref{thm-principalorbitthm}.

    Let $Y$ be the connected component of $Z_{(H)}$ containing $L$, and assume for a contradiction that $(H') \neq (H)$ is the principal orbit type.  By Theorem \ref{thm-principalorbitthm}, $\dim(Y) < \dim(Z_{(H')})$. There are now two options. If $(H)$ is an exceptional orbit type, i.e. $\dim(G/H) = \dim(G/H')$, then by the decomposition (18) of \cite{Wood2022},we would have $\dim(\mathcal{H}_z)<k$. This contradicts \cite[Corollary 3.15]{Wood2022}. On the other hand, if $(H)$ is a singular orbit type, then $\dim(G/H') = m-1-l$ for $l < k$. Now by \cite[Remark 3.10]{Wood2022} and \cite[Corollary 3.15]{Wood2022}, $\dim(Z_{(H')}) \leq m-1 + l < m-1 + k = \dim(Y)$, which gives a contradiction.
\end{proof}

The geometry of the zero level set $\mu^{-1}(0)$ is particularly simple, as the next proposition shows, and we will restrict to this setting for the remainder of the paper. As well as being convenient, the restriction is natural, and occurs in several common settings. For example, if $L$ is an \textit{exact} almost-calibrated cohomogeneity-one $G$-invariant Lagrangian (as might occur as a blow-up model for Lagrangian mean curvature flow, see \cite[Theorem 2.12]{Joyce2015}), it must lie in $\mu^{-1}(0)$ by \cite[Proposition 4.10]{Wood2022}. In fact, if $G$ is semisimple, then \textit{all} $G$-invariant Lagrangians lie in $\mu^{-1}(0)$ by Proposition \ref{prop-laginlevelset} part a).

\begin{proposition}[Geometry of the zero level set]\label{prop-levelsetgeometry}
    Let $G \leq \SU(m-1)$ be compact and connected, and consider the action $G \circlearrowright \mathbb{C}^{m-1}$. Let $\mu:\mathbb{C}^{m-1} \to \mathfrak{g}$ be the standard moment map. Let $Z$ be a connected component of $\mu^{-1}(0)$, and assume that $Z$ contains a cohomogeneity-one $G$-invariant Lagrangian submanifold $L$, so that $\text{dim}(Z) = m$. Then:
    \begin{itemize}
        \item[a)] $L \subset Z \setminus \{0\}$.
        \item[b)] Given $z \in Z\setminus\{0\}$, and denoting by $P_z$ the complex line through $z$, we have \[ Z \, = \, \{g\cdot \lambda z \, :\, g \in G, \, \lambda \in \mathbb{C}\} \, = \, G \cdot P_z.\]
        \item[c)] There exists a finite cyclic group $C_k$ defined as $C_k := \Stab(P_z)/\Stab(z)$ with order $k|(2m-2)$ acting in the natural way on $P_z$ such that $L \cap P_z$ is $C_k$-invariant.
    \end{itemize}
\end{proposition}

\begin{proof}
    By Proposition \ref{prop-laginlevelset}, $L\subset Z_{(H)}$ for $H$ the principal orbit type. In particular, since $\{0\}$ is a singular orbit, $L \subset Z \setminus \{0\}$.
    Part b) follows from Proposition 4.11 a) of \cite{Wood2022}, and part c) follows from Propositions 4.6 and 4.11 c) of the same.
\end{proof}

The following two examples are the easiest to describe explicitly, although there are many other subgroups $G \leq \SU(m-1)$ admitting cohomogeneity-one Lagrangians in $\mu^{-1}(0) \subset \mathbb{C}^{m-1}$. 

\begin{example}\label{ex-so(m-1)}
    Consider $\SO(m-1) \subset \SU(m-1)$ acting diagonally on $\mathbb{C}^{m-1} \cong \mathbb{R}^{m-1} \oplus \mathbb{R}^{m-1}$. The zero level set can be calculated to be:
    \begin{align*}
        \mu^{-1}(0) \, &= \, \{ z \in \mathbb{C}^{m-1} \, : \, z_i \overline z_j = \overline z_i z_j \, \text{ for } 1 \leq i, j \leq m-1\}\\
        &= \, \{ (x,y) \in \mathbb{R}^{m-1} \oplus \mathbb{R}^{m-1} \, : \, \{x,y\} \text{ linearly dependent}\}\\
        &= \, \SO(m-1) \cdot P_z
    \end{align*}
    where $z = (1,0,\ldots,0).$ For this choice of $z$, we have
    \[ \emph{Stab}(z) \cong \SO(m-2), \quad \emph{Stab}(P_z) \cong \emph{O}(m-2),\]
    so that $C_k = \emph{O}(m-2)/\SO(m-2) = C_2$. Note that $\SO(m-1)$ is a simple group, and so by Proposition \ref{prop-laginlevelset}, any $G$-invariant Lagrangian $L$ must lie in $\mu^{-1}(0)$, and $l := L \cap P_z$ is a $C_2$-invariant curve.
\end{example}
\begin{example}\label{ex-t(m-2)}
    Consider the set of diagonal elements $T^{m-2} \subset \SU(m-1)$. In this case,
    \begin{align*}
        \mu^{-1}(0) \, &= \, \{ z \in \mathbb{C}^{m-1} \, : \, |z_i|^2 = |z_j|^2\text{ for } 1 \leq i, j \leq m-1\}\\
        &= \, T^{m-1} \cdot P_z
    \end{align*}
    where $z = (1,1,\ldots,1).$ For this choice of $z$, we have
    \[ \emph{Stab}(z) = \{\emph{Id}\}, \quad \emph{Stab}(P_z) = \{\emph{diag}(e^{\frac{2k\pi i}{m-1}}, \ldots, e^{\frac{2k\pi i}{m-1}}) \, : \, k \in \mathbb{Z}\},\]
    so that $C_k = C_{m-1}$. $T^{m-2}$ is abelian, and unlike for $G = \SO(m-1)$, \emph{every} level set $\mu^{-1}(X)$ of $\mu$ admits cohomogeneity-one Lagrangian submanifolds. The other level sets do not admit such a simple description as $\mu^{-1}(0)$.
\end{example}

The following proposition considers the case where $G \circlearrowright \mathbb{C}^{m-1}$ is extended to act on $\mathbb{C}^m$, and gives an expression for the structure of $\mu^{-1}(0)$.

\begin{proposition}\label{prop-cohom1reduction}
    Let $G \leq \SU(m-1)$ be compact and connected. Extend the action $G \circlearrowright \mathbb{C}^{m-1}$ to an action on $\mathbb{C}^m$ by acting trivially on the final coordinate. Denote by $\mu_{\mathbb{C}^m}:\mathbb{C}^m \to \mathfrak{g}$ the standard moment map for the action of $G$ on $\mathbb{C}^m$. Then 
    \begin{equation*}
        \mu_{\mathbb{C}^m}^{-1}(0) = \mu^{-1}(0) \times \mathbb{C}.
    \end{equation*}
         % If $L \subset \mathbb{C}^m$ is a cohomogeneity-two $G$-invariant Lagrangian, and we define $L_{z_m} := L \cap \pi_m^{-1}(z_m)$, then $L_{z_m}$ is a cohomogeneity-one $G$-invariant Lagrangian submanifold in $\mu^{-1}_{z_m}(0) \subset \mathbb{C}^{m-1} \times \{z_m\}$.
    \end{proposition}

\begin{proof}
    This is an immediate consequence of the definition of the standard moment map.
\end{proof}

From this point on, we focus on cohomogeneity-two Lagrangians in $\mu_{\mathbb{C}^m}^{-1}(0)$. For the remainder of the section, we will therefore assume we are in the following setting:
\begin{assumption}\label{as1}
    Consider a compact, connected subgroup $G \leq \SU(m-1)$ acting on $\mathbb{C}^{m-1}$ and a connected component $Z$ of $\mu^{-1}(0)$ admitting cohomogeneity-one Lagrangian submanifolds. Extend to an action on $\mathbb{C}^m$ by acting trivially on the final coordinate. Choose $z' \in Z \setminus \{0\}$.

    Define $P := P_{z'}$ to be the complex line through $z'$ in $\mathbb{C}^{m-1}$, so that $P \times \mathbb{C}$ is then a Kähler subspace of $\mathbb{C}^m = \mathbb{C}^{m-1}\times \mathbb{C}$. Define $C_k$ to be the finite cyclic group acting on $P$ as in Proposition \ref{prop-levelsetgeometry}.
\end{assumption}

From equations (21) and (23) of \cite{Wood2022}, along with Proposition \ref{prop-cohom1reduction}, we get the following orthogonal decompositions of tangent spaces for any $z_m \in \mathbb{C}$:
\begin{align}
    T_{(z',z_m)}\mathbb{C}^m \, &= \, T_{z'} \mathcal{O}_{z'} \oplus JT_{z'}\mathcal{O}_{z'} \oplus P \oplus \mathbb{C} \label{eq-ambientspacedecomposition},\\
    T_{(z',z_m)} \mu^{-1}_{\mathbb{C}^m}(0) \, &= \, T_{z'}\mathcal{O}_{z'} \oplus P \oplus \mathbb{C}. \label{eq-levelsettangentdecomposition}
\end{align}

The key fact about cohomogeneity-two Lagrangians in $\mu^{-1}(0)$ is that they are characterised by the intersection $\check{L} := L \cap (P \times \mathbb{C})$, which is a 2 dimensional Lagrangian submanifold.

\begin{proposition}\label{prop-correspondence}
    In the setting of Assumption \ref{as1}, there is a 1-1 correspondence between:
    \begin{itemize}
        \item $G$-invariant embedded/immersed cohomogeneity-two Lagrangian submanifolds $L \subset Z \times \mathbb{C} \subset \mathbb{C}^m$,
        \item $C_k$-invariant 2-dimensional embedded/immersed Lagrangian submanifolds $\check{L} \subset (P \setminus \{0\}) \times \mathbb{C} \subset \mathbb{C}^{m-1}\times \mathbb{C}$ ,
    \end{itemize}
    where $P = P_{z'}, C_k$ are as in Proposition \ref{prop-levelsetgeometry} parts b) and c) respectively. The map $L \mapsto \check{L}$ is given by intersection with $P \times \mathbb{C} \subset \mathbb{C}^{m-1}\times\mathbb{C}$, and the map $\check{L} \mapsto L$ is given by $L := G \cdot \check{L}$.

\end{proposition}

\begin{proof}
    The proof follows exactly as in \cite[Proposition 4.12]{Wood2022}. We outline one direction.
    Consider a $G$-equivariant cohomogeneity-two immersion $F:\hat{L} \to \mu^{-1}(0) \subset \mathbb{C}^m$; we show that $F|_{F^{-1}(P \times \mathbb{C})}$ is a 2-dimensional $C_m$-equivariant Lagrangian immersion. 

    Choose $p \in F^{-1}(P \times \mathbb{C})$, and an open neighbourhood $U \ni p$ in $\hat{L}$ such that $F(U)$ is an embedded Lagrangian. By (\ref{eq-levelsettangentdecomposition}), the intersection of $T_{F(p)}F(U)$ with $P \times \mathbb{C}$ is transverse in $\mu^{-1}(0)$, and so $F(U) \cap (P\times \mathbb{C})$ is an embedded submanifold of dimension 2. It follows that $F|_{F^{-1}(P\cap\mathbb{C})}$ is a Lagrangian immersion. The $C_k$-invariance follows from the definition of the $C_k$ action on $P$ (see \cite[Proposition 4.6]{Wood2022}).
\end{proof}

Furthermore, we may express the Lagrangian angle of a cohomogeneity-two Lagrangian $L$ in terms of the Lagrangian angle of $\check{L}\subset P \times \mathbb{C}$. For the purpose of defining the latter Lagrangian angle, we identify the 2-dimensional Kähler subspace $P \times \mathbb{C}$ with $\mathbb{C}^2$ (with its standard Calabi-Yau structure) using an isomorphism $\Phi$.

\begin{proposition}\label{prop-lagangle}
    In the setting of Assumption \ref{as1}, there exists an isomorphism $\Phi:P \to \mathbb{C}$ such that the following is true.

    Consider a $C_k$-invariant immersed Lagrangian submanifold $\check{L} \subset P \times \mathbb{C}$, corresponding to a cohomogeneity-two Lagrangian $L := \{g\cdot w \, : \, w \in \check{L}\}$, and denote, for $w = (w', w_m) \in \check{L}$:
    \begin{itemize}
        \item $\theta_L (g \cdot w)$ the Lagrangian angle of $L \subset \mathbb{C}^m$ at $g \cdot w$,
        \item $\theta_{\check{L}}(w)$ the Lagrangian angle of $(\Phi\oplus \text{Id})(\check{L}) \subset \mathbb{C}^2$ at $(\Phi\oplus \text{Id})(w)$,
        \item $\arg_{\Phi}(w')$ the argument of $\Phi(w')$ in $\mathbb{C}$.
    \end{itemize}
    Then for $w = (w', w_m) \in L$ and $g \in G$:
    \[ \theta_L(g\cdot w) \equiv \theta_{\check{L}}(w) \, + \, (m-2)\arg_{\Phi}(w') \quad (\emph{mod } \pi).\]
\end{proposition}

\begin{proof}
    For a point $v \in P \times \mathbb{C}$, we embed $P \times \mathbb{C} \subset \mathbb{C}^{m-1}\times \mathbb{C}$ as usual, and consider the orbit $\mathcal{O}_v$ of $v$ in $\mathbb{C}^m$ of dimension $m-2$. Let $\pm\nu_{v}$ denote the pair of unit elements of $\Lambda^{m-2}T_v\mathcal{O}_v$.

    Noting that $(e^{i\phi})^*\Omega = e^{im\phi}\Omega$, it follows that we may choose $V \in P$ such that $\{\Omega_V(\pm\nu_V, V, e_m)\} = \{\pm 1\}$. Define $\Phi:P \to \mathbb{C}$ to be the unique complex linear map such that $\Phi(V) = 1$. This implies that, for $X, Y \in P \times \mathbb{C}$, 
    \begin{equation}\label{eq-omegaeq1}
        \{\Omega_V(\pm \nu_V, X, Y)\} \, = \, \{\pm \Omega_0((\Phi\oplus\text{Id})X,(\Phi\oplus\text{Id})Y)\},
    \end{equation}
    where $\Omega_0$ denotes the standard holomorphic volume form on $\mathbb{C}^2$. Choose a point $w=(w', w_m) \in \check{L}$, and choose an orthonormal basis $\{X_1, X_2\}$ of $T_w\check{L}$, so that
    \begin{equation}\label{eq-omegaeq2}
        e^{i \theta_{\check{L}}(w)} = \Omega_0((\Phi\oplus\text{Id})X_1, (\Phi\oplus\text{Id})X_2).
    \end{equation}
    Then, writing $w' = re^{i\alpha}$, and using (\ref{eq-omegaeq1}) and (\ref{eq-omegaeq2}) for the final equality:
    \begin{align*}
        \pm e^{i\theta_L(w)} \, &= \, \Omega_{re^{i\alpha}V}(\pm \nu, X_1, X_2)\\
        &= \, ((e^{i\alpha})^*\Omega)_{rV}(\pm \nu, e^{-i\alpha} X_1, e^{-i\alpha}X_2)\\
        &=e^{i(m-2)\alpha}\,\Omega_{rV}(\pm \nu, X_1, X_2)\\
        &= \pm e^{i(m-2)\alpha\, + \, \theta_{\check{L}}(w)}
    \end{align*}
    (where all equalities are of sets). This implies the result for $g=e$; the general case follows since $L$ is $G$-invariant and $G$ preserves the form $\Omega$.
\end{proof}

We conclude in the following corollary that the study of cohomogeneity-two translating solitons is reduced to studying certain 2-dimensional Lagrangian submanifolds in $\mathbb{C}^2$.

\begin{corollary}[Characterisation of cohomogeneity-two translators/special Lagrangians]\label{cor-cohom2translators}
    In the setting of Assumption \ref{as1}, there is a 1-1 correspondence between:
    \begin{itemize}
        \item $G$-invariant embedded/immersed cohomogeneity-two Lagrangian translating solitons $L \subset Z \times \mathbb{C} \subset \mathbb{C}^m$,
        \item $C_k$-invariant embedded/immersed Lagrangian submanifolds $\check{L}\subset \mathbb{C}^2$, satisfying the equation
        \begin{equation}\label{eq-cohom2translator} \theta_{\check{L}}(z_1, z_2) + (m-2)\emph{arg}(z_1) + \emph{Im}(z_2)\, \equiv \, 0 \quad (\emph{mod }\pi).
        \end{equation}
    \end{itemize}
    Furthermore, there is a 1-1 correspondence between:
    \begin{itemize}
         \item $G$-invariant embedded/immersed cohomogeneity-two special Lagrangians $L \subset Z \times \mathbb{C} \subset \mathbb{C}^m$ (with Lagrangian angle $0$),
        \item $C_k$-invariant embedded/immersed Lagrangian submanifolds $\check{L}\subset \mathbb{C}^2$, satisfying the equation
        \begin{equation}\label{eq-cohom2SL}
        \theta_{\check{L}}(z_1, z_2) + (m-2)\emph{arg}(z_1) \, = \, 0.
        \end{equation}
    \end{itemize}
    In both cases, the map $L \mapsto \check{L}$ is given by intersection with $P \times \mathbb{C} \subset \mathbb{C}^{m-1}\times\mathbb{C}$, and the map $\check{L} \mapsto L$ is given by $L := G \cdot \check{L}$.
\end{corollary}

\subsection{Symmetric Lagrangians with Translational Symmetries}\label{sec-gaffine}

We briefly consider more general affine symmetry groups $G \leq \text{ASU}(m-1)$. We show we may reduce to the case where $G$ contains no one-parameter family of pure translations, equivalently where $L$ has no linear factor.

\begin{proposition}\label{prop-translationreduction}
    Consider a connected Lagrangian $L \subset \mathbb{C}^{m-1}$ with connected symmetry group $G := \emph{Sym}^0(L) \leq \emph{ASU}(m-1)$ with Lie algebra $\mathfrak{g} := \emph{Lie}(G) \leq \mathfrak{asu}(m-1)$. Let $P := \exp(\mathfrak{g} \cap (0 \times \mathbb{C}^{m-1}))$ be the identity component of the subgroup of pure translational symmetries, and denote $d := \dim(P)$. Then:

    \begin{itemize}
        \item $P$ is  an isotropic subspace of $\mathbb{C}^{m-1}$. $G$ may be expressed as $G' \ltimes P$, where $G'$ preserves the subspace $\mathbb{C}^{m-1-d} := (P \oplus JP)^\perp$.
        \item Up to a translation by $w \in JP$, $L = P \times L'$ for $L' \subset (P \oplus JP)^\perp \cong \mathbb{C}^{m-1-d}$ a Lagrangian submanifold. 
        \item $\check L$ is invariant under the restricted group $G'|_{\mathbb{C}^{m-1-d}} \leq \emph{ASU}(m-1-d)$. This contains no pure translations, in the sense that $\emph{Lie}(G'|_{\mathbb{C}^{m-1-d}}) \cap (0\times \mathbb{C}^{m-1-d}) = 0.$  Furthermore, if $L$ is cohomogeneity-$k$ with respect to $G \ltimes P$, then $L'$ is cohomogeneity-$k$ with respect to $G'$.
    \end{itemize}
\end{proposition}
\begin{proof}

    Since $L$ is $G$-invariant, it follows that $P$ is isotropic. The action of $P$ has moment map $\mu_P:\mathbb{C}^{m-1} \to P^*$, $\langle \mu_P(z), \, p\rangle = \langle -iz, \, p\rangle.$ Since $L$ is invariant under the action of $P$, it follows from \cite[Corollary 4.4]{Joyce2001a} that there exists $\xi \in P
    ^*$ such that $L \subset \mu_P^{-1}(\xi)$, which means that the projection of $L$ to $JP$ is constant. Translating by this constant, we may assume that $L = \check L \times P \subset \mathbb{C}^{m-1-d} \times P$, for $\mathbb{C}^{m-1-d} := (P\oplus JP)^\perp$.

    Now, we may write $G = G' \ltimes P$, where the elements of $G'$ are of the form $(g, v)$ for $g \in \SU(m-1)$, $v \in \mathbb{C}^{m-1-d}$. Note that for $(g,v) \in G'$ and $(\text{Id}, p) \in P$,
    \[ (g, v)\cdot (\text{Id}, p) \cdot (g, v)^{-1} \, = \, (\text{Id}, g\cdot p) \, \in \, P,\]
    so $G$ preserves the orthogonal decomposition $P \oplus JP \oplus \mathbb{C}^{m-1-d}$. It follows that $\check L$ is invariant under the group $G' |_{\mathbb{C}^{m-1-d}}$. Finally, $G'|_{\mathbb{C}^{m-1-d}}$ cannot have any pure translations, else $\check L$, and therefore $L$, would have those same translational symmetries, and so they would have been elements of $P$.
\end{proof}

\begin{remark} By the above proposition we may extend the structure theory of Section \ref{sec-glinear} to apply to Lagrangians with symmetry groups of the form $G' \ltimes P$ where $G'\leq \SU(m-1)$ and $P$ is a $G'$-invariant isotropic subspace, by applying it to $L'$ with symmetry group $G'|_{\mathbb{C}^{m-1-d}}$.
\end{remark}

\begin{remark}
    We note that there are affine subgroups that are not of the form $G \ltimes P$, i.e. `screw-type' subgroups that combine linear and translational movements. Example \ref{ex-um-1} gives one such subgroup, and we consider examples of Lagrangian translators invariant under such subgroups in Section \ref{sec-moreexamples}. The structure of the moment map level sets is different to those of linear subgroups, and the theory of Section \ref{sec-glinear} does not apply.
\end{remark}

