We now use Corollary \ref{cor-cohom2translators} together with a generalisation of a construction by Castro--Lerma to construct new cohomogeneity-two Lagrangian translators and special Lagrangians.

\subsection{Definition of the Ansatz}\label{sec-ansatz}

Let $I\subseteq\mathbb{R}$ be an open interval and $s_{0}\in I$. Let $\gamma:I\to\mathbb{C}$ be a smooth curve, $\gamma(s) = x(s) + iy(s)$, $x(s), y(s)\in\mathbb{R}$. Consider the function $\beta_\gamma: I \to \mathbb{R}$, defined by
\begin{equation}
    \beta_{\gamma}(s) \, := \,  -\int_{s_{0}}^{s}\langle\gamma(t), i\gamma'(t)\rangle\:dt.
\end{equation}
Then if $\lambda := \frac{1}{2i}(\overline z dz - zd\overline{z})$ denotes the standard Liouville form on $\mathbb{C}$ (satisfying $d\lambda = 2\omega_0$), we have:
\begin{align*}
    \gamma^*(\lambda) = (x(s)y'(s) - y(s)x'(s))\:ds = \langle\gamma(s), -i\gamma'(s)\rangle\:ds = \frac{d\beta_{\gamma}}{ds}\:ds,
\end{align*}
i.e. $\beta_{\gamma}$ is the primitive of $\gamma
^*(\lambda)$. We also define the related integral quantity
\begin{equation}
    \widetilde \beta_\gamma(s) \, := \, -\int_{s_0}^s |\gamma^2(t)|\, \langle \gamma(t), \, i\gamma'(t)\rangle \: dt,
\end{equation}
which satisfies $d\widetilde \beta_\gamma(s) = |\gamma(s)|^2\frac{d\beta_\gamma}{ds}ds \, = \, |\gamma(s)|^2 \, \gamma^*(\lambda)$, i.e. $\widetilde \beta_\gamma$ is the primitive of $|\gamma|^2\gamma^*(\lambda)$.

\begin{remark}\label{rem-betapositivity}
    We note that if a curve $\gamma$ is parametrised in polar coordinates $\gamma = r(s)e^{is}$, we have
\begin{align*}
    \gamma'(s) &= (r'(s) + ir(s))e^{is},
    \,\,\,\, \beta_{\gamma}(s) \, = \, \int_{s_0}^s |r(t)|^2\, dt.
\end{align*}
In particular, $\beta_\gamma(s)$ is strictly increasing in $s$.
\end{remark}

The following Ansatz, based on that of Castro and Lerma \cite{Castro2010}, produces a Lagrangian surface from two curves $\gamma$, $\xi \subset \mathbb{C}$.

\begin{proposition}\label{prop-lagrangianansatz}
    Let $I_{1}, I_{2}\subseteq\mathbb{R}$ be open intervals, and let $\gamma: I_{1}\to\mathbb{C}$,  $\xi:I_{2}\to\mathbb{C}$ be smooth curves, at least one of which doesn't intersect $0$. Then the map $\check F:I_{1}\times I_{2}\to\mathbb{C}^{2}$ given by
    \begin{align}\label{eq-ansatz}
        \check F(x, y) = \left(\gamma(x)\xi(y), \frac{1}{2}(|\xi(y)|^{2} - |\gamma(x)|^{2}) + i(\beta_{\xi}(y) - \beta_{\gamma}(x)) \right)
    \end{align}
    is a Lagrangian immersion, with Lagrangian angle
    \begin{align}
        \check \theta(x, y) \, = \, \arg\left(\gamma'(x)\right)+\arg\left(\xi'(y)\right).
    \end{align}
    Furthermore, if $\lambda := \frac{1}{2i}\sum_{i=1}^2(\overline z_i dz_i - z_id\overline{z_i})$ denotes the standard Liouville form on $\mathbb{C}^2$, then 
    \begin{equation}\label{eq-restrictionofliouville}
        \check F^*(\lambda) = d\left( -\frac{1}{2}(|\gamma(x)|^2 - |\xi(y)|^2)(\beta_\gamma(x) - \beta_\xi(y)) + \widetilde \beta_\gamma(x) + \widetilde \beta_\xi(y) \right),
    \end{equation}
    i.e. the image of $\check F$ is an exact Lagrangian submanifold of $\mathbb{C}^2$.
\end{proposition}

\begin{remark}
    Up to translation in the second complex coordinate, the function $\check F$ is given by \[ \check F(x,y) \, = \, \left( \gamma(x)\xi(y), \, \int_0^y \overline {\xi(s)} \xi'(s)\, ds \, - \, \int_0^x \overline {\gamma(s)} \gamma'(s)\,ds \right).\]
\end{remark}

\begin{proof}
    Observe that by the definition of $\beta_{\xi}$,
    \begin{align*}
        \frac{d}{dy}\left(\frac{|\xi(y)|^{2}}{2} + i\beta_{\xi}(y)\right) &= \frac{\overline{\xi(s)}\xi'(s) + \overline{\xi'(s)}\xi(s)}{2} - i\langle\xi(s), i\xi'(s)\rangle\\
        &= \re\left(\overline{\xi(s)}\xi'(s)\right) + i\im\left(\overline{\xi(s)}\xi'(s)\right)\\
        &= \overline{\xi(s)}\xi'(s).
    \end{align*}
    The same holds for $\gamma(x)$. Thus,
    \begin{align*}
        &\frac{\partial \check F}{\partial x} = \left(\gamma'(x)\xi(y), -\gamma'(x)\overline{\gamma(x)}\right) = \gamma'(x)(\xi(y), -\overline{\gamma(x)}),\\
        &\frac{\partial \check F}{\partial y} = \left(  \gamma(x)\xi'(y), \xi'(y)\overline{\xi(y)}\right) = \xi'(y)(\gamma(x), \overline{\xi(y)}),
    \end{align*}
    so since one of $\gamma, \xi$ avoids $0$, $\check F$ is an immersion. Moreover,
    \begin{align*}
      \left\langle \frac{\partial \check F}{\partial x},  J\frac{\partial \check F}{\partial y}\right\rangle  = -\im\left(\overline{\gamma'(x)}\overline{\xi(y)}\xi'(y)\gamma(x) - \overline{\gamma'(x)}\gamma(x)\xi'(y)\overline{\xi(y)}\right) = 0,
    \end{align*}
    so $\check F$ is Lagrangian. The Lagrangian angle of $\check F$ is given by
    \begin{align*}
        \check \theta(x, y) = \arg\det\left(D\check F\right) &= \arg\left(\gamma'(x)\xi'(y)\left(|\gamma(x)|^{2}+|\xi(y)|^{2}\right)\right) \\
        &= \arg\left(\gamma'(x)\right)+\arg\left(\xi'(y)\right).
    \end{align*}
    Finally, we calculate the primitive of the pullback of the  Liouville form $\lambda$. From the definition of $\check F$, along with the fact that $\beta_\gamma'(x) = \im(\overline{\gamma(x)} \gamma'(x))$, we have 
    \begin{align*}
        \check F^*(\overline z_1 dz_1 - z_1 d\overline{z_1}) \, &= \, 2i \im(\overline{\gamma(x)}\gamma'(x))|\xi(y)|^2\,dx \, + \, 2i\im(\overline{\xi(y)}\xi'(y))|\gamma(x)|^2\,dy \\
        &= \, 2i \beta_\gamma'(x)|\xi(y)|^2 dx \, + \, 2i\beta_\xi'(y)|\gamma(x)|^2 dy, \\
        \check F^*(\overline{z_2}dz_2 - z_2 d\overline{z_2}) \, &= \, -2i\left(\beta_\xi(y) - \beta_\gamma(x)\right)\left(\xi(y)\xi'(y)dy - \gamma(x)\gamma'(x)dx\right) \, \\
        &\quad\qquad+ \, i\left(|\xi(y)|^2 - |\gamma(x)|^2\right)\left(\beta'_\xi(y)dy - \beta'_\gamma(x)dx\right),
    \end{align*}
    so that
    \begin{align*}
        \check F^*(\lambda) \, &= \, -\left(\beta_\xi(y) - \beta_\gamma(x)\right)\left(\xi(y)\xi'(y)dy \, - \, \gamma(x)\gamma'(x)dx\right) \:\\
        &\qquad\quad + \, \frac{1}{2} \left(|\xi(y)|^2 + |\gamma(x)|^2\right)\left(\beta'_\xi(y) dy \, + \, \beta'_\gamma(x)dx \right) \\ 
        &= \, -\frac{1}{2} \, d\left( \left(|\gamma(x)|^2 - |\xi(y)|^2\right)\left(\beta_\gamma(x) - \beta_\xi(y)\right) \right) \, + \, d\beta_\gamma(x) |\gamma(x)|^2 \, + \, d\beta_\xi(y) |\xi(y)|^2 \\
        &= \, d\left(
        -\frac{1}{2}\left(|\gamma(x)|^2 - |\xi(y)|^2\right)\left(\beta_\gamma(x) - \beta_\xi(y)\right) \, + \, \widetilde \beta_\gamma(x) \, +\,  \widetilde \beta_\xi(y)
        \right).
    \end{align*}
\end{proof}

We now find conditions on the curves $\gamma$, $\xi$ so that $\check F$ solves equations \eqref{eq-cohom2translator} and \eqref{eq-cohom2SL}. 
% This in turn will give cohomogeneity-two $G$-invariant special Lagrangians and translators in the setting of Assumption \ref{as1}, by Corollary \ref{cor-cohom2translators}.

\begin{proposition}\label{prop-translatoransatz}
    Let $m\geq 2$, $I_{1}, I_{2}\subseteq\mathbb{R}$ be open intervals, $(a, b)\in\mathbb{R}^{2}$ be constants, and let $\gamma: I_{1}\to\mathbb{C}$,  $\xi:I_{2}\to\mathbb{C}$ be smooth curves satisfying
    \begin{align}\label{eq-curveeqs}
        \vec{\kappa}_{\gamma} - (m-2)\frac{\gamma^{\perp}}{|\gamma|^{2}} = a\gamma^{\perp},\quad \vec{\kappa}_{\xi} - (m-2)\frac{\xi^{\perp}}{|\xi|^{2}} = b\xi^{\perp}.
    \end{align}
    Then the Lagrangian immersion $\check F:I_{1}\times I_{2}\to\mathbb{C}^{2}$ given in Proposition \ref{prop-lagrangianansatz}, equation \eqref{eq-ansatz} has Lagrangian angle
    \begin{align}\label{eq-ansatzlagangleformula}
        \check \theta(x, y) = a_{1}\beta_{\gamma}(x) + b\beta_{\xi}(y) - (m-2)\arg(\gamma(x)\xi(y)) +c
    \end{align}
    for some $c\in\mathbb{R}$.
    In particular:
    \begin{itemize}
        \item If $a = b = 0$, then the immersion $\check F$ satisfies \eqref{eq-cohom2SL}.
        \item If $a = -b = 1$, then the immersion $\check F$ satisfies \eqref{eq-cohom2translator}.
    \end{itemize}
\end{proposition}

% The solutions to \eqref{eq-curveeqs} are fully classified - we give the classification later as Theorem \ref{thm-curveeqssolutions}. 
To prove Proposition \ref{prop-translatoransatz}, we first prove the following Lemma.

\begin{lemma}\label{lem: curve computations}
    Let $I\subseteq\mathbb{R}$ and let $\gamma:I\to\mathbb{C}$ be a smooth curve. Then
    \begin{equation}\label{eq: diff of arg of curve position}
        \frac{d}{ds}\arg(\gamma(s)) = \frac{d\beta_{\gamma}(s)}{ds}|\gamma(s)|^{-2}.
    \end{equation}
    Moreover, if $\gamma$ satisfies
    \begin{equation}
        \vec{\kappa}_{\gamma} - (m-2)\frac{\gamma(s)^{\perp}}{|\gamma(s)|^{2}} = a\gamma(s)^{\perp}
    \end{equation}
    for some $a\in\mathbb{R}$, then
    \begin{equation}\label{eq: diff of arg of curve tangent}
        \frac{d}{ds}\arg(\gamma'(s)) = -\left(\frac{m-2}{|\gamma(s)|^{2}}+a\right)\frac{d \beta_{\gamma}(s)}{ds}. 
    \end{equation}
\end{lemma}

\begin{proof}
    Let $\theta := \arg\gamma$. Write $\gamma = (\gamma\overline{\gamma})^{\frac{1}{2}}e^{i\theta}$, then we find
\begin{align*}
    \log\gamma = \frac{1}{2}\log\gamma + \frac{1}{2}\log\overline{\gamma} + i\theta.
\end{align*}
Thus,
\begin{align*}
    \frac{d}{ds}\theta = \frac{1}{2i}\left(\frac{\gamma'}{\gamma} - \frac{\overline{\gamma}'}{\overline{\gamma}}\right) = \frac{1}{|\gamma|^{2}}\frac{1}{2i}(\overline{\gamma}\gamma' - \gamma\overline{\gamma}')= -\frac{\im(\overline{\gamma}'(s)\gamma(s))}{|\gamma(s)|^{2}} = \frac{d\beta_{\gamma}(s)}{ds}|\gamma(s)|^{-2}.
\end{align*}
This proves (\ref{eq: diff of arg of curve position}). Next, we prove (\ref{eq: diff of arg of curve tangent}). Parametrising $\gamma$ by its arc-length gives
\begin{align*}
    \frac{d}{ds}\gamma'(s) \, = \,  \vec{\kappa}_{\gamma} = \left(\frac{m-2}{|\gamma(s)|^{2}}+a\right)\langle \gamma(s), i\gamma'(s)\rangle i\gamma'(s) \, = \,  -\left(\frac{m-2}{|\gamma(s)|^{2}}+a\right)\frac{d \theta}{ds} |\gamma(s)|^2 i\gamma'(s).
\end{align*}
The result follows by noting that $\frac{d}{ds}\arg(\gamma'(s)) \, = \, \langle \gamma'', \, i\gamma'\rangle$.
\end{proof}

\begin{proof}[Proof of Proposition \ref{prop-translatoransatz}]
From Lemma~\ref{lem: curve computations}, we have
\begin{align*}
    \frac{d}{dx}\arg\left(\gamma'(x)\right) &= -\left(\frac{m-2}{|\gamma(x)|^{2}} + a\right)\frac{d\beta_{\gamma}(x)}{dx}\\
    &= -(m-2)\frac{d}{dx}\arg\left(\gamma(x)\right) + a\frac{d}{dx}\beta_{\gamma}(x).
\end{align*}
Therefore,
\begin{equation}\label{eq: scalar eq for gamma}
    \arg\left(\gamma'(x)\right) + (m-2)\arg\left(\gamma(x)\right) = a\beta_{\gamma}(x) + c_{1}
\end{equation}
for some $c_{1}\in\mathbb{R}$. Similarly, we have
\begin{equation}\label{eq: scalar eq for xi}
        \arg\left(\xi'(y)\right) + (m-2)\arg\left(\xi(y)\right) = b\beta_{\xi}(y) + c_{2}
\end{equation}
for some $c_{2}\in\mathbb{R}$. Combining these with the expression for the Lagrangian angle in Proposition \ref{prop-lagrangianansatz} yields
\begin{align*}
    \check\theta(x, y) &= \arg\left(\gamma'(s)\right) + \arg\left(\xi'(y)\right)\\
    &= -(m-2)\arg\left(\gamma(x)\xi(y)\right) + a\beta_{\gamma}(x) + b\beta_{\xi}(y) + c
\end{align*}
for some $c = c_{1}+c_{2}\in\mathbb{R}$, and equation \eqref{eq-ansatzlagangleformula} is proved. Now, consider the case $a = -b \in\mathbb{R}$.
    By (\ref{eq: scalar eq for gamma}), (\ref{eq: scalar eq for xi}), we have
    \begin{align}
        a(\beta_{\gamma} - \beta_{\xi}) + c_{1}+c_{2} \, &= \,  \arg(\gamma'(x)\xi'(y)) + (m-2)\arg(\gamma(x)\xi(y)) \nonumber\\
        \implies a\im(z_{2})(x, y)  \,&=\, a(\beta_{\xi}(y) - \beta_{\gamma}(x))\nonumber\\
        &=\, -\left[\arg(\gamma'(x)\xi'(y)) + (m-2)\arg(\gamma(x)\xi(y)) - c_1 - c_2 \right]. \nonumber
    \end{align}
    Thus, 
    \begin{align}
        \check\theta(x, y) + (m-2)\arg(z_1)(x, y) + a\im(z_2)(x, y) = c_1 + c_2. \nonumber
    \end{align}
    The result now follows by choosing $a=0$ and $a=1$.

\end{proof}

Combining the results of this chapter with Corollary \ref{cor-cohom2translators}, we arrive at our main theorem.

\begin{theorem}\label{thm-slagsandtranslators}
    Assume we are in the setting of Assumption \ref{as1}, and let $\Phi:P \to \mathbb{C}$ be the isomorphism from Proposition \ref{prop-lagangle}. Let $I_1$ $I_2 \subset \mathbb{R}$ be open intervals, and $\gamma:I_1 \to \mathbb{C}$, $\xi:I_2 \to \mathbb{C}$ be smooth curves satisfying \eqref{eq-curveeqs} for $a, b \in \mathbb{R}$. Let $\check F$ be the map from Proposition \ref{prop-lagrangianansatz}.

    Then the image $L$ of the map 
    \[ F:G \times I_1 \times I_2 \to \mathbb{C}^{m-1} \times \mathbb{C}, \quad  F(g, x, y) = g \cdot (\Phi\oplus \text{Id})^{-1} \circ \check F(x,y) \]
    is an exact cohomogeneity-two $G$-invariant Lagrangian submanifold, immersed away from $\{0\} \times \mathbb{C}$. The restriction of the Liouville form $\lambda$ is given by:
    \begin{equation}
        F^*\lambda = d\left( -\frac{1}{2}(|\gamma(x)|^2 - |\xi(y)|^2)(\beta_\gamma(x) - \beta_\xi(y)) + \widetilde \beta_\gamma(x) + \widetilde \beta_\xi(y) \right).
    \end{equation} 
    Furthermore:
    \begin{itemize}
        \item If $a = b = 0$ then $L$ is a special Lagrangian, i.e. $\theta(F) = 0$.
        \item If $a = -b = 1$ then $L$ is a Lagrangian translator, i.e. $\theta(F) = -\langle F, Je_m\rangle$.
    \end{itemize}
\end{theorem}
\begin{proof}
    The only statement still requiring justification regards the restriction of the Liouville form. This follows from equation \eqref{eq-restrictionofliouville}, along with the following claim, denoting by $\Psi$ the map $\Psi := (\Phi \oplus \text{Id})^{-1}$ and by $\pi$ the projection $\pi: G \times I_1 \times I_2 \to I_1 \times I_2$:
    \[ F^* \lambda \, = \, \pi^* \check F^* \Psi^* \lambda.\]
    To prove this claim, choose $(g,x,y) \in G \times I_1 \times I_2$, and denote $w := g \cdot \Psi\circ \check F(x,y)$. We evaluate each side of the equation in two cases:
    \begin{itemize}
        \item[a)] Assume $X \in T_g G$, so that $F_*(X) \in T_w \mathcal{O}_w$. Then by equation \eqref{eq-ambientspacedecomposition}, $F_*(X), JF_*(X) \perp P_w$, which implies that $\lambda(F_* X) = -\langle w, J F_* X\rangle \, = \, 0$. This matches the right-hand side as $\pi_* X = 0$.
        \item[b)] Assume $X \in T_{(x,y)}I_1 \times I_2$. Then by $G$-invariance of $\lambda$, 
        \[\lambda_w(F_* X) = \lambda_{\Psi \circ \check F(x,y)}((\Psi\circ \check F)_*X) \, = \,  (\pi^*\check F^* \Psi^* \lambda)(X). \]
    \end{itemize}
\end{proof}

\subsection{Classification of Admissible Curves}\label{sec-classification1}

We consider solutions to \eqref{eq-curveeqs}. For $a>0$, (\ref{eq-curveeqs}) implies that $\gamma$ is the profile curve of a cohomogeneity-one Lagrangian expander in $\mathbb{C}^{m-1}$, and that $\xi$ is the profile curve of a cohomogeneity-one Lagrangian shrinker in $\mathbb{C}^{m-1}$. If $a = 0$, $\gamma$ and $\xi$ are profile curves of cohomogeneity-one special Lagrangians. Such curves have been fully classified by Anciaux, Castro and Romon (see \cite{Anciaux2006, AnciauxRomon2009, AnciauxCastroRomon2006}). We summarise the classification here.

\begin{theorem}[Classification of Solutions to \eqref{eq-curveeqs}]\label{thm-curveeqssolutions}
    Up to rotation by $e^{i\phi}$, the only complete, properly immersed solutions to the equation
    \begin{equation}\label{eq-curveeq}
        \kappa_\gamma - (m-2)\frac{\gamma^\perp}{|\gamma^2|} = a\gamma^\perp
    \end{equation} 
    are:
    \begin{align*}
        &\text{Line, }a \in \mathbb{R}: 
         &&\tilde{c} (s) := s, \text{ for } s \in \mathbb{R}\\
        &\text{Lawlor neck profile, }a=0: &&\tilde l(s) := \frac{1}{\sqrt[m-1]{\cos((m-1)s)}\quad}\,e^{is}, \text{ for } s \in (-\tfrac{\pi}{2(m-1)}, \tfrac{\pi}{2(m-1)})\\
        &\text{(along with its scalings by $\mu \in \mathbb{R}^+$})\\
        &\text{Anciaux shrinker profile, } a<0: &&\tilde \sigma_{b,p,q}(s), \text{ for } s \in \mathbb{R}\\
        &\text{Anciaux expander profile, } a>0: &&\tilde \epsilon_{a,\alpha}(s), \text{ for } s \in (-\tfrac{\alpha}{2}, \tfrac{\alpha}{2})        
    \end{align*}
    (as well as unions thereof), where:
    \begin{itemize}
        \item $\tilde \sigma_{b,p,q}$ is the profile curve of the Anciaux shrinker at scale $b = -a$ with winding number $p$ and number of points of maximum curvature $q$ (see Figure \ref{fig-shrinker}).
        \item $\tilde \epsilon_{a,\alpha}$ is the profile curve of the Anciaux expander at scale $a$, centred on the positive real axis, spanning an angle $\alpha \in (0, \frac{\pi}{m-1})$ (see Figure \ref{fig-expander}).
    \end{itemize}
\end{theorem}

