\begin{remark}\label{rem-betaforthecurves}
    We briefly discuss the properties of $\beta_\gamma(s)$ for each of these curves. For the line $\tilde c$, $\beta$ is constant, so we may take it to be zero. Each of the other curves $\tilde l$, $\tilde \sigma_{b,p,q}$, $\tilde \epsilon_{a, \alpha}$ is a polar graph $\gamma(s) = r(s)e^{is}$ (e.g. the curves of Figure \ref{fig-curves}). It follows from Remark \ref{rem-betapositivity} that $\beta = \int_{s_0}^s |r(t)|^2 \,dt$, and is strictly increasing. 

    In the case of $\tilde l$ and $\tilde \epsilon_{a, \alpha}$ we choose $s_0 = 0$ so that $\beta(s) = -\beta(-s)$. For $\tilde \sigma_{b,p,q}$, it is clear that $\beta$ is unbounded in the positive and negative directions. For $\epsilon_{a,\alpha}$, one can integrate \eqref{eq-curveeqs} to find that the range of $\beta$ is $\frac{1}{a}(\pi - (m-1)\alpha)$.
\end{remark}

\subsection{Cohomogeneity-Two Special Lagrangians}\label{sec-classification2}

We now consider what properties the Lagrangian immersion of Proposition \ref{prop-translatoransatz} and corresponding cohomogeneity-two Lagrangian immersion of Theorem \ref{thm-slagsandtranslators} have with these choices of curves $\gamma, \xi$. For $a=b=0$, the options for the pair $(\gamma, \xi)$ are (without loss of generality, where $\phi \in \mathbb{R},\, \mu \in \mathbb{R}^+$):
\begin{itemize}
    \item[(a)] $(\gamma = e^{i\phi}\tilde c,\, \xi = \tilde c)$, i.e. both curves are lines through $0$. Then the image of the mapping
    \begin{equation}\label{eq-Fa}
        \check F_{(a)}(x,y) = \left(e^{i\phi}xy,\,\frac{1}{2}(y^2 - x^2)\right)
    \end{equation} 
    is simply a flat copy of $\mathbb{R}^2$ in 
    $\mathbb{C}^2$.
    \item[(b)] $(\gamma = \mu \tilde l, \, \xi = e^{i\phi}\tilde c)$, i.e. $\gamma$ is a Lawlor neck profile and $\xi$ is a line. Then:
    \begin{equation}\label{eq-Fb}
    \check F_{(b)}(x,y) = \left(e^{i\phi}\mu \, y\,  \tilde l (x),\,\frac{1}{2}(y^2-\mu^2|\tilde l (x)|^2) \, - \, i\mu^2 \beta_{\tilde l}(x) \right).
    \end{equation}
    \item[(c)] $(\gamma = e^{i\phi}\mu_1 \tilde l, \, \xi = \mu_2 \tilde l)$, i.e. $\gamma$ and $\xi$ are both Lawlor neck profiles. Then:
    \begin{equation}\label{eq-Fc}
    \check F_{(c)}(x,y) = \left(e^{i\phi}\mu_1\mu_2 \, \tilde l(x)\,  \tilde l (y),\,\frac{1}{2}(\mu_2^2|\tilde l (y)|^2 - \mu_1^2|\tilde l(x)|^2) \, + \, i(\mu_2^2 \beta_{\tilde l}(y) - \mu_1^2\beta_{\tilde l}(x) )\right).
    \end{equation}

\end{itemize}
The latter two can be seen to be exact Lagrangian embeddings of $\mathbb{R}^2$ into $\mathbb{C}^2$, by checking that the map $\check F$ is injective. By Theorem \ref{thm-slagsandtranslators}, these are `profile surfaces' corresponding to special Lagrangians in $\mathbb{C}^m$. Whether these special Lagrangians are immersed/embedded or not depends on the group $G$. In total, we have the following:

\begin{proposition}\label{prop-slclassification}
    In the setting of Assumption \ref{as1}, define the Lagrangians $L_{(b)}$, $L_{(c)}$ corresponding to the maps $\check F_{(b)}$, $\check F_{(c)}$ in \eqref{eq-Fb}, \eqref{eq-Fc} as the image of the map $F$ of Theorem \ref{thm-slagsandtranslators}.

    Then $L_{(b)}$, $L_{(c)}$ are exact special Lagrangian submanifolds. Furthermore: 
    \begin{itemize}
        \item $L_{(b)}$ is embedded if $G = \SO(m-1)$, and otherwise embedded away from a 1-dimensional singular set corresponding to $\{x=0\}$,
        \item $L_{(c)}$ is immersed for any $G$, and an embedding provided that the discrete group $C_k$ has order $k\leq m-1$.
    \end{itemize}
\end{proposition}

\begin{proof}
    Given $\check F:I_1\times I_2 \to\mathbb{C}^2$, we define the map $F:G \times I_1 \times I_2 \to \mathbb{C}^m$ as in Theorem \ref{thm-slagsandtranslators}. 

    In the case of $(b)$, since $(\Phi \oplus \text{Id})^{-1}(\check L)$ intersects the singular orbit $\{0\}\times \mathbb{C} \subset \mu_{\mathbb{C}^m}^{-1}(0)$, the only way the image $L$ of $F$ can be nonsingular is if $G = \SO(m-1)$, in which case $L$ has the topology of $\mathbb{R}^m$ near $x=0, y=0$. In this case, embeddedness of $L$ corresponds to embeddedness of $C_2 \cdot \check L \subset \mathbb{C}^2$. Since $\check L_{(b)}$ is $C_2$-symmetric by the domain mapping $x \mapsto -x$, this is clear.

    For $(c)$, $\check L$ does not intersect the singular orbit, so we may consider a general group $G$ satisfying $|C_k| \leq m-1$. Then by Proposition \ref{prop-correspondence}, $L$ is immersed, and embedded if and only if $C_k \cdot \check L$ is embedded. To show this, assume that $e^{i\varphi}\cdot \check F_{(c)}(x_1, y_1) \, = \, \check F_{(c)}(x_2, y_2)$, for $e^{i\varphi} \in C_k$. Using polar coordinates $\tilde l(x) = r(x)e^{ix}$, this gives the following four equations:
    \begin{itemize}
        \item[1.] $\varphi + x_1 + y_1 \, \equiv \, x_2 + y_2 \quad (\text{mod }2\pi)$,
        \item[2.] $\mu_1\mu_2r(x_1)r(x_2) \, = \, \mu_1 \mu_2 r(x_2)r(y_2)$,
        \item[3.] $\mu_2^2r(y_1)^2 - \mu_1^2 r(x_1)^2 \, = \, \mu_2^2r(y_2)^2 - \mu_1^2 r(x_2)^2$,
        \item[4.] $\mu_2^2 \beta_{\tilde l}(y_1) - \mu_1^2 \beta_{\tilde l}(x_1) \, = \, \mu_2^2 \beta_{\tilde l}(y_2) - \mu_1^2 \beta_{\tilde l}(x_2)$.
    \end{itemize}
    Combining equations 2 and 3 gives the single complex equation
    \begin{align}
         (\mu_2 r(y_1) + i\mu_1 r(x_1))^2 \, &= \, (\mu_2 r(y_2) + i\mu_1 r(x_2))^2 \notag \\
         \implies r(y_1) \, = r(y_2), \,\,r(x_1) \, &= \, r(x_2). \label{eq-sameradius}
    \end{align}
    \indent Assume first that $x_1 \neq x_2$, without loss of generality we may assume $x_1 > x_2$. By \eqref{eq-sameradius} we see that $x_2 = -x_1$, and by Remark \ref{rem-betaforthecurves} we have $\beta_{\tilde l}(x_2) = -\beta_{\tilde l}(x_1)$. Equation 4 now gives that $\mu_2^2(\beta_{\tilde l}(y_1) - \beta_{\tilde l}(y_2)) \, = \, 2\mu_1^2 \beta_{\tilde l}(x_1) \, > 
    \, 0$, so we must have $y_1 > y_2$, indeed by \eqref{eq-sameradius} $y_2 = -y_1$. Now we have $ 0 < 2x_1 + 2y_1 < \tfrac{2\pi}{m-1}$, which contradicts equation 1 since $\varphi + 2x_1 + 2y_1$ cannot be an integer for $e^{i\varphi} \in C_k$, $k \leq m-1$. 

    Therefore, we must have $x_1 = x_2$, which by equations 1 and 4 imply $y_1 = y_2$ and $e^{i\varphi} = 1$.
\end{proof}

\begin{remark} For example, $\check F_{(c)}$ corresponds to a special Lagrangian embedding when $G = SO(m-1)$ and $T^{m-2}$, since in those cases $C_k = C_2$ and $C_{m-1}$ respectively (see Examples \ref{ex-so(m-1)} and \ref{ex-t(m-2)}). Indeed, since in general we have $k|2(m-1)$ by Proposition \ref{prop-levelsetgeometry} c), the assumption $k \leq m-1$ only fails when $k = 2(m-1)$. The authors are unaware of any group actions with this property.
\end{remark}

\subsection{Cohomogeneity-Two Lagrangian Translators}\label{sec-classification3}

For $a=-b = 1$, the options for the pair $(\gamma, \xi)$ are (without loss of generality, and suppressing the subscripts $a, p, q, \alpha$ for the Anciaux curves):

\begin{itemize}
    \item[d)] $(\gamma = e^{i\phi}\tilde c, \, \xi = \tilde \sigma)$, i.e. $\gamma$ is a line and $\xi$ is an Anciaux shrinker profile. Then:
    \begin{equation}\label{eq-Fd}
        \check F_{(d)}(x,y) = \left(e^{i\phi} \,x \, \tilde \sigma(y), \, \frac{1}{2}(|\tilde \sigma(y)|^2 - x^2) \, + \, i\beta_{\tilde \sigma}(y)\right).  
    \end{equation}
    \item[e)] $(\gamma =  \tilde\epsilon, \, \xi = e^{i\phi}\tilde c)$, i.e. $\gamma$ is an Anciaux expander profile and $\xi$ is a line. Then:
    \begin{equation}\label{eq-Fe}
    \check F_{(e)}(x,y) = \left(e^{i\phi} \,y \, \tilde \epsilon(x), \, \frac{1}{2}(y^2 - |\tilde \epsilon(x)|^2 ) \, - \, i\beta_{\tilde \epsilon}(x)\right).
    \end{equation}
    \item[f)] $(\gamma = e^{i\phi} \tilde \epsilon(x), \, \xi = \tilde \sigma(y))$, i.e. $\gamma$ is an Anciaux expander profile and $\xi$ is an Anciaux shrinker profile. Then:
    \begin{equation}\label{eq-Ff}
    \check F_{(f)}(x,y) = \left(e^{i\phi}  \, \, \tilde \epsilon(x) \tilde \sigma(y), \, \frac{1}{2}(|\tilde \sigma(y)|^2 - |\tilde \epsilon(x)|^2 ) \, + \, i(\beta_{\tilde \sigma}(y) - \beta_{\tilde \epsilon}(x))\right).
    \end{equation}
\end{itemize}
Among these, d) and e) can be seen to be exact Lagrangian embeddings of $\mathbb{R}^2$ into $\mathbb{C}^2$ as in the $a=b=0$ case, and $f)$ can be seen to be an exact Lagrangian immersion. Note that this is true for d) despite $\tilde \sigma_{a,p,q}$ not necessarily being embedded itself for all values of $(p, q)$ - the Ansatz `unwinds' the shrinker into an embedded surface.

By Theorem \ref{thm-slagsandtranslators}, the immersions $\check F$ in d), e) and f) are `profile surfaces' corresponding to Lagrangian translators in $\mathbb{C}^m$. Note that the Lagrangian angle of the corresponding Lagrangian translators is negative the imaginary part of the second coordinate of $\check F$. Therefore, the translators corresponding to d) and f) are never almost-calibrated, whereas Remark \ref{rem-betaforthecurves} shows the translator corresponding to e) is almost-calibrated. Depending on the group $G$, the corresponding translators are embedded submanifolds of $\mathbb{C}^m$:

\begin{proposition}\label{prop-translatorclassification}
    In the setting of Assumption 1, define the Lagrangians $L_{(d)}$, $L_{(e)}$, $L_{(f)}$ corresponding to the maps $\check F_{(d)}$, $\check F_{(e)}$, $\check F_{(f)}$ in \eqref{eq-Fd}, \eqref{eq-Fe}, \eqref{eq-Ff} respectively as the image of the map $F$ of Theorem \ref{thm-slagsandtranslators}. 

    Then $L_{(d)}$, $L_{(e)}$, $L_{(f)}$ are exact zero-Maslov Lagrangian translating solitons, and $L_{(e)}$ is almost-calibrated. Furthermore: 
    \begin{itemize}
        \item $L_{(d)}, L_{(e)}$ are embeddings if $G = \SO(m-1)$, and otherwise embeddings away from a 1-dimensional singular set corresponding to $\{x=0\} , \{y=0\}$ respectively,
        \item $L_{(f)}$ is an immersion for any $G$.
    \end{itemize}
\end{proposition}

\begin{remark}
    The example $L_{(e)}$ with $G = \SO(m-1)$ is the symmetric Joyce--Lee--Tsui translator (see \cite{Joyce2010}). By considering a suitable sequence of expander profile curves $\epsilon_{a_i, \alpha_i}$ converging to a Lawlor neck profile curve $\tilde l$, the translator $L_{(e)}$ converges to the special Lagrangian $L_{(b)}$.
\end{remark}

\begin{proof}
    We sketch the argument for $\check F_{(d)}$ only, in the case where $G = \SO(m-1)$. Since $\check F$ has $C_2$-symmetry achieved by the mapping $x \mapsto -x$, to show embeddedness we must show that if $e^{i\varphi}\check F_{(d)}(x_1,y_1) = \check F_{(d)}(x_2, y_2)$, then either $\varphi \equiv 0 \,\,(\text{mod } 2\pi), x_1 = x_2, y_1 = y_2$, or $\varphi \equiv \pi \,\,(\text{mod } 2\pi), x_1 = -x_2, y_1 = y_2$.
    When the equality holds, we have the three equations
    \begin{align*}
        e^{i\varphi}x_1 \tilde \sigma(y_1) = x_2 \tilde \sigma(y_2), \quad |\tilde \sigma(y_1)|^2 - x_1^2 = |\tilde \sigma(y_2)|^2 - x_2^2, \quad \beta_{\tilde \sigma}(y_1) = \beta_{\tilde \sigma}(y_2).
    \end{align*}
    By Remark \ref{rem-betaforthecurves}, $\beta_{\tilde \sigma}$ is strictly increasing, and so we must have $y_1 = y_2$. The result follows from the other two equations.
\end{proof}

\section{Affine-Invariant Cohomogeneity-One Lagrangian Translators} \label{sec-moreexamples}

Finally, we describe a construction of explicit cohomogeneity-one examples of Lagrangian translators corresponding to an affine group action, using the level set method by Harvey--Lawson \cite{HL82}.

\subsection{$\widetilde{\U(1)}^{2}$-invariant Examples}

Consider the action of $G := \widetilde{\U(1)}^{2}\simeq\mathbb{R}^{2}$ on $\mathbb{C}^{3}$ by
\begin{align*}
	(e^{i\theta_{1}}, e^{i\theta_{2}})\cdot(z_{1}, z_{2}, z_{3}) = (e^{i\theta_{1}}z_{1}, e^{i\theta_{2}}z_{2}, z_{3} - i(\theta_{1} + \theta_{2})).
\end{align*}
By Proposition \ref{prop-affinegrouppreservingomegaf}, $\widetilde {\U(1)}^2 \leq G_f$, and so the action preserves $\Omega_f$. Define a map $\mu:\mathbb{C}^{3}\to\mathbb{R}^{3}$  by
\begin{align*}
	\mu(z_{1}, z_{2}, z_{3}) = \left(\re z_{3} - \frac{1}{2}|z_{1}|^{2}, \re z_{3} - \frac{1}{2}|z_{2}|^{2}, \im\left(z_{1}z_{2}e^{z_{3}}\right)\right).
\end{align*}
Let $\mu = (\mu_{1}, \mu_{2}, \mu_{3})$, then in terms of real coordinates of  $\mathbb{C}^{3}\simeq\mathbb{R}^{6}$,
\begin{align*}
	&\mu_{1}(z_{1}, z_{2}, z_{3}) := \frac{1}{2}(z_{3} + \overline{z_{3}} - |z_{1}|^{2}) = x_{3} - \frac{x_{1}^{2} + y_{1}^{2}}{2},\\
	&\mu_{2}(z_{1}, z_{2}, z_{3}) := \frac{1}{2}(z_{3} + \overline{z_{3}} - |z_{2}|^{2}) = x_{3} - \frac{x_{2}^{2}+y_{2}^{2}}{2},\\
	&\mu_{3}(z_{1}, z_{2}, z_{3}) = \frac{1}{2i}(z_{1}z_{2}e^{z_{3}} - \overline{z_{1}z_{2}}e^{\overline{z_{3}}}) = e^{x_{3}}[(x_{1}y_{2}+x_{2}y_{1})\cos y_{3}+(x_{1}x_{2} - y_{1}y_{2})\sin y_{3}].
\end{align*}
It is straightforward to check that $d\mu:\mathbb{C}^{3}\to\mathbb{R}^{3}$ is surjective if and only if $(z_1 , z_2)\neq (0, 0)$, and the Poisson brackets $\{\mu_{j}, \mu_{k}\}$ vanish for all $j, k = 1, 2, 3$. Hence, by \cite[Section III.2.C]{HL82}, the smooth part of $L_{a, b, c} := \mu^{-1}(a, b, c)$ is Lagrangian. Notice that $(\mu_{1}, \mu_{2})$ is the moment map of the $G
$ action, and $\mu_{3}$ can be viewed as a generalized moment map corresponding to $\im\Omega_{f}$. Now $L_{a, b, c}$ is the intersection of $3$ level sets $\mu_{1}^{-1}(a)\cap\mu_{2}^{-1}(b)\cap\mu_{3}^{-1}(c)$, so it is generically real $3$-dimensional. Let $z = (z_{1}, z_{2}, z_{3})\in L_{a, b, c}$, then $T_{z}^{\perp}L_{a, b, c}$ is spanned by $\{\nabla\mu_{1}(z), \nabla\mu_{2}(z), \nabla\mu_{3}(z)\}$. Since $L_{a, b, c}$ is Lagrangian, $T_{z}L_{a, b, c}$ is spanned by
\begin{align*}
	J\nabla\mu_{j} = J\left\{\sum_{k=1}^{3}\frac{\partial\mu_{j}}{\partial x_{k}}\frac{\partial}{\partial x_{k}} + \frac{\partial\mu_{j}}{\partial y_{k}}\frac{\partial}{\partial y_{k}}\right\} = \sum_{k=1}^{3}\frac{\partial\mu_{j}}{\partial x_{k}}\frac{\partial}{\partial y_{k}} - \frac{\partial\mu_{j}}{\partial y_{k}}\frac{\partial}{\partial x_{k}},\quad j = 1, 2, 3.
\end{align*}
Note that 
\begin{align*}
	2i\frac{\partial\mu_{j}}{\partial\overline{z}_{k}} = -\frac{\partial\mu_{j}}{\partial y_{k}}+ i\frac{\partial\mu_{j}}{\partial x_{k}},
\end{align*}
so the matrix $M_{jk} = 2i\frac{\partial\mu_{j}}{\partial\overline{z}_{k}}$ sends the standard basis $\{e_{1}, e_{2}, e_{3}\}$ to $\{J\nabla\mu_{1}(z), J\nabla\mu_{2}(z), J\nabla\mu_{3}(z)\}$. Therefore, the Lagrangian angle $\theta$ is given by the argument of
\begin{align*}
	\det M_{jk} = \frac{e^{\overline{z}_{3}}}{8i}\left(|z_{1}|^{2} + |z_{2}|^{2} + |z_{1}|^{2}|z_{2}|^{2}\right),
\end{align*}
which is $-\im z_{3} - \frac{\pi}{2}$. Hence, we have $\theta + \im z_{3} = -\frac{\pi}{2}$ is a constant, that is, (the smooth part of) $L_{a, b, c}$ is a Lagrangian translating soliton.

\subsection{A Lagrangian translator fibration}

Since $d\mu:\mathbb{C}^{3}\to\mathbb{R}^{3}$ is not surjective on $\{(0, 0, z_3)\:|\:z_3\in\mathbb{C}\}$, the fibers $L_{a, b, c} := \mu^{-1}(a, b, c)$ over $\Gamma := \{\mu(0, 0, z_3)\:|\:z_3\in\mathbb{C}\} = \{(a, a, 0)\:|\:a\in\mathbb{R}\}$ are singular. Indeed, for any $a\in\mathbb{R}$,
\begin{align*}
	L_{a, a, 0} &= \left\{\left(z_{1}, z_{2}, z_{3}\right)\::\:\re z_{3} - \frac{1}{2}|z_{1}|^{2} = \re z_{3} - \frac{1}{2}|z_{2}|^{2} = a,\; \im(z_{1}z_{2}e^{z_{3}}) = 0\right\}\\
	&= \left\{\left(z_{1}, z_{2}, z_{3}\right)\::\:|z_{1}|^{2} = |z_{2}|^{2} = r^{2}, \;\re z_{3} = a+\frac{r^{2}}{2},\; \im(z_{1}z_{2}e^{z_{3}}) = 0\right\}\\
	&=\left\{\left(re^{i\theta_{1}}, re^{i\theta_{2}}, a+\frac{r^{2}}{2} -i(\theta_{1} + \theta_{2}) \right)\::\:r\geq 0, \;(\theta_{1}, \theta_{2})\in\mathbb{R}^{2}\right\}
\end{align*}
has a $1$-dimensional singular set $\{(0, 0, a + it)\:|\:t\in\mathbb{R}\}$, and it is \emph{Hamiltonian stationary}, namely, its Lagrangian angle is harmonic. 

We now describe the geometry of a general fiber. Let $(a, b, c)\in\mathbb{R}^{3}$. Then
\begin{align}
    L_{a, b, c} &= \left\{\left(z_{1}, z_{2}, z_{3}\right)\::\:\re z_{3} - \frac{1}{2}|z_{1}|^{2} = a, \re z_{3} - \frac{1}{2}|z_{2}|^{2} = b,\; \im(z_{1}z_{2}e^{z_{3}}) = c\right\}\nonumber\\
    &=\left\{\left(z_{1}, z_{2}, \frac{a+b}{2} + \frac{|z_1|^{2}+|z_2|^{2}}{4} - i\theta(z_1, z_2)\right)\::\:|z_1|^{2} - |z_2|^{2} = 2(b-a)\right\},
\end{align}
where the Lagrangian angle is given by
\begin{align}\label{eq: imaginary part of Labc}
    \theta(z_1, z_2) = \arg(z_1 z_2)-\arcsin\left[\frac{c\cdot {\exp\left(-\frac{a+b}{2}-\frac{|z_1|^{2}+|z_2|^{2}}{4}\right)}}{|z_1 z_2|}\right].
\end{align}
One can view $L_{a, b, c}$ as a graph over the  submanifold
\begin{align}
    M_{2(b-a)} := \{(z_1, z_2)\in\mathbb{C}^{2}\::\:|z_1|^{2} - |z_2|^{2} = 2(b-a)\}.
\end{align}
Note that $M_{2(b-a)}$ is diffeomorphic to $\SU(1, 1)\simeq \text{SL}_{2}(\mathbb{R})$ if $a\neq b$, and is a $\mathbb{T}^{2}$-cone $M_{0}$ if $a = b$. Now $\text{SL}_{2}(\mathbb{R})$ acts on the upper half plane $\mathbb{H}^{2}$ transitively by M\"obius transform, with stabilizer $\SO(2)\simeq\mathbb{S}^{1}$. Hence, for $a\neq b$, $M_{2(b-a)}$ is a circle bundle over $\mathbb{H}^{2}$, which is diffeomorphic to $\mathbb{R}^{2}\times\mathbb{S}^{1}$. The translator $L_{a, b, c}$ is diffeomorphic to $\mathbb{R}^{3}$ if $a\neq b$, and it can be visualized as a `helical staircase', with each `step' corresponding to the graph of the function $h(z_1, z_2) = \frac{|z_2|^{2}+|z_2|^{2}}{4}$ over $M_{2(b-a)}$. To make $L_{a, b, c}$ complete, one needs to lift $M_{2(b-a)}$ to its universal cover, which lift its circle fibers to $\mathbb{R}$, and one also needs to lift the argument function in (\ref{eq: imaginary part of Labc}) to be multivalued.


