	\section{Introduction}
	\par In recent years, the theory of jet schemes has been widely studied and applied since it was introduced by Nash in his paper \cite{c5}. Ein and Mustaţă studied some invariants of singularities using jet schemes, with results collected in \cite{c6}. We will discuss jet schemes of determinantal varieties in this paper.
	\par Let $K$ be an algebraically closed field of characteristic zero and $\mathbf{A}^{mn}_{K}$ be the affine space of dimension $mn$ with $m\le n$. For a fixed $m \times n$ matrix $(x_{i,j})_{1\le i\le m, 1\le j\le n}$, all $r \times r$ minors of the matrix generate an ideal $I^{m,n}_{r}$ in $K[x_{i,j}|1\le i\le m, 1\le j\le n]$, which determines an algebraic variety $\mathcal{L}^{m,n}_{r}$. We say $\mathcal{L}^{m,n}_{r}$ is a determinantal variety of $m \times n$ matrix.
	\par Let $x_{i,j}(t)=\underset{s=0}{\overset{\infty}{\sum}} x^{(s)}_{i,j}t^{s}$ and $X(t)=(x_{i,j}(t))_{1 \le i \le m,1 \le j \le n}$ an $m \times n$ matrix. Every $r \times r$ minor of $X(t)$ is of the form $\underset{l=0}{\overset{\infty}{\sum}}f_{l}(x^{(s)}_{i,j})t^{l}$, where $f_{l}$ is a polynomial in $K[x_{i,j}^{(s)}|s\in \mathbb{Z}_{\ge 0},1\le i\le m,1\le j\le n]$. We denote $I^{m,n}_{r,k}$ to be the ideal generated by $f_{0},f_{1},\cdots,f_{k}$ from all $r \times r$ minors. The variety determined by $I^{m,n}_{r,k}$ is the $k$th jet scheme of $\mathcal{L}^{m,n}_{r}$, denoted by $\mathcal{L}^{m,n}_{r,k}$. The $0$th jet scheme of $\mathcal{L}^{m,n}_{r}$ is just itself.
	\par The Hilbert series of the classical determinantal varieties was obtained by Alde Conca and Jürgen Herzog in their paper \cite{c9}.  \\\\
	\textbf{Theorem 1.1. }(\cite{c9}, Corollary 1) \textit{The Hilbert series of $\mathcal{L}^{m,n}_{r+1}$ is}
	\begin{equation}
		\centering
		H_{\mathcal{L}^{m,n}_{r+1}}(z)= \frac{det\big( \underset{k\ge 0}{\sum}\binom{m-i}{k} \binom{n-j}{k} z^{k}\big)_{1\le i\le r,1\le j\le r}}{z^{\binom{r}{2} }(1-z)^{r(m+n-r)}}.
	\end{equation}\\
	\par It is complicated to compute the Hilbert series for jets of arbitrary order of determinantal varieties. The simplest nontrivial case is when $(r,k)=(2,1)$, and this case has been addressed in  three papers. In \cite{c3}, the authors gave a Gröbner basis for $I^{m,n}_{2,1}$. Then Boyan Jonov characterized the Stanley-Reisner simplicial complex of the leading ideal of $I^{m,n}_{2,1}$ and showed its shellability (see Definition 2.11) in \cite{c4}. Finally in \cite{c8}, the authors computed the Hilbert series of $\mathcal{L}^{m,n}_{2,1}$, obtaining the following result:
	\begin{equation}
		\centering
		H_{\mathcal{L}^{m,n}_{2,1}}(z)=\Bigg( 
		\frac{\underset{k=0}{\overset{m-1}{\sum}}\binom{m-1}{k} \binom{n-1}{k} z^{k}}{(1-z)^{m+n-1}}
		\Bigg)^{2}.
	\end{equation}
	\par This study extends the work of these three papers. The computation of Gröbner bases of $\mathcal{L}^{m,n}_{r,k}$ is quite difficult when $r$ and $k$ are larger. Hence we deal with cases for small $r$ and $k$. The computation is involved and highly non-trivial even in these cases. In \cite{c10}, Chen and Zuo have obtained some results on the Hilbert series of $\mathcal{L}^{3,n}_{3,1}$, with result as follows:
	\begin{equation}
		H_{\mathcal{L}^{3,n}_{3,1}}(z)=\big(  \frac{1+(n-2)z+\frac{(n-1)(n-2)}{2}z^{2}}{(1-z)^{2n+2}}\big)^{2}.
	\end{equation}
	\par In this paper we will compute the Hilbert series of $\mathcal{L}^{2,n}_{2,2}$. For convenience, we will denote $x^{(0)}_{i,j}+x^{(1)}_{i,j}t+x^{(2)}_{i,j}t^{2}$ by $x_{i,j}+y_{i,j}t+z_{i,j}t^{2}$. The form of $X(t)$ in this case is as follows:
	\begin{equation}
		X(t)=\left(
		\begin{array}{cccc}
			x_{1,1}+y_{1,1}t+z_{1,1}t^{2} & x_{1,2}+y_{1,2}t+z_{1,2}t^{2} & \cdots & x_{1,n}+y_{1,n}t+z_{1,n}t^{2} \\ x_{2,1}+y_{2,1}t+z_{2,1}t^{2} & x_{2,2}+y_{2,2}t+z_{2,2}t^{2} & \cdots & x_{2,n}+y_{2,n}t+z_{2,n}t^{2}
		\end{array}
		\right).
	\end{equation}
	\par We state our main result here: \\\\
	\textbf{Main Theorem. }\textit{Let $L(I_{2,2}^{2,n})$ be the leading ideal of $I^{2,n}_{2,2}$. Suppose  $\Delta_{L(I^{2,n}_{2,2})}$ is the Stanley-Reisner simplicial complex corresponding to $K[x_{i,j},y_{i,j},z_{i,j}|1\le i\le 2,1\le j\le n]/L(I_{2,2}^{2,n})$. Then $\Delta_{L(I^{2,n}_{2,2})}$ is shellable and the Hilbert series of $\mathcal{L}^{2,n}_{2,2}$ is  }
	\begin{center}
		$H_{\mathcal{L}^{2,n}_{2,2}}(z)=\big( \frac{1+(n-1)z}{(1-z)^{n+1}}\big) ^{3}$.
	\end{center}
	\par We will give a short introduction to Gröbner bases, Stanley-Reisner complexes and shellable complexes in the second section. Then we will find a Gröbner basis for $I_{2,2}^{2,n}$ in the third section and find all facets of $\Delta_{L(I^{2,n}_{2,2})}$ in the fourth section. Finally we will show $\Delta_{L(I^{2,n}_{2,2})}$ is shellable in the fifth section and compute the Hilbert series of $\mathcal{L}^{2,n}_{2,2}$ in the sixth section. Indeed, we also propose a conjecture about the relation between the Hilbert series of determinantal varieties and their $k$th order jets, which is included in the sixth section. We introduce it here first.\\\\
	\textbf{Conjecture. }The Hilbert series of $\mathcal{L}^{m,n}_{r,k}$ is the $(k+1)$-th power of the Hilbert series of $\mathcal{L}^{m,n}_{r}$.  \\

	\section{Preliminaries}
	\subsection{Gröbner Bases}
	\par $\quad$
	\par In this section, $K$ is always a field and $K[x_{1},\cdots,x_{n}]$ is the polynomial ring in $n$ indeterminates. A polynomial of the form
	\begin{center}
		$t=x_{1}^{e_{1}}x_{2}^{e_{2}} \cdots x_{n}^{e_{n}}$($e_{i}\in \mathbb{N}$)
	\end{center}
	\par \noindent is called a monomial.\\
	\textbf{Definition 2.1. }Let $M$ be the set of all monomials in $K[x_{1},\cdots,x_{n}]$. A monomial ordering on $K[x_{1},\cdots,x_{n}]$ is a total ordering "$\le$"on $M$ satisfying the following properties:
	\par (1)$1\le t$ for all $t\in M$.
	\par (2)if $s$, $t_{1}$, $t_{2}\in M$ and $t_{1}\le t_{2}$, then $st_{1}\le st_{2}$.\\
	\par If $f\in K[x_{1},\cdots,x_{n}]$ is a nonzero polynomial written as $f=c_{1}t_{1}+c_{2}t_{2}+\cdots+c_{m}t_{m}$ with $t_{1}> \cdots > t_{m}$ under a fixed monomial ordering, then we define $lm(f)=t_{1}$ (leading monomial), $lc(f)=c_{1}$ (leading coefficient), and $lt(f)=c_{1}t_{1}$ (leading term). Let $S\subset K[x_{1},\cdots ,x_{n}]$ be a subset of polynomials. The ideal generated by all leading monomials in $S$ is called the leading ideal of $S$, denoted by $L(S)$ .
	\par For convenience, we fix a monomial ordering $\le$ on $K[x_{1},...,x_{n}]$ for following discussion.\\\\
	\textbf{Definition 2.2. }Let $I\subset K[x_{1},\cdots ,x_{n}]$ be an ideal. A finite subset $G\subset I$ is called a Gröbner basis (with respect to the chosen monomial ordering "$\le$") of $I$ if $L(I)=L(G)$.\\\\
	\textbf{Proposition 2.3. }(\cite{c1}, Corollary 9.10) \textit{Let $G$ be a Gröbner basis of an ideal $I\subset K[x_{1},\cdots ,x_{n}]$. Then $I$ is equal to the ideal generated by $G$.}\\
	\par It is not easy to compute Gröbner bases of an ideal. Here we introduce Buchberger's criterion to identify whether a finite set is a Gröbner basis of the chosen ideal or not. \\\\
	\textbf{Definition 2.4. }Let $S=\{g_{1},\cdots ,g_{r}\}$ be a finite subset of $K[x_{1},\cdots ,x_{n}]$ and $f\in K_[x_{1},\cdots ,x_{n}]$. We say $h\in K[x_{1},\cdots ,x_{n}]$ is a normal form of $f$ with respect to $S$ if 
	\par (1)no monomial of $h$ is divisible by $lm(g_{i})$ for any $i=1,\cdots ,r$.
	\par (2)there exist polynomials $h_{1},\cdots ,h_{r}\in K[x_{1},\cdots ,x_{n}]$ such that $f-h=\underset{i=1}{\overset{r}{\sum}}g_{i}h_{i}$ and $lm(h_{i}g_{i})\le lm(f)$ for all $i$.
	\par \noindent We write $f\to_{S}0$ if $f\in K[x_{1},\cdots ,x_{n}]$ satisfies (2) in Definition 2.4.\\\\
	\textbf{Theorem 2.5. }(\cite{c1}, Theorem 9.9) \textit{Let $G$ be a Gröbner basis of an ideal $I\subset K[x_{1},\cdots ,x_{n}]$. Every $f\in K[x_{1},\cdots ,x_{n}]$ has precisely one normal form with respect to $G$.}\\
	\par For $f,g\in K[x_{1},\cdots ,x_{n}]$ nonzero, let $t$ be the gcd of $lm(f)$ and $lm(g)$. Then 
	\begin{center}
		$S(f,g)=\frac{lt(g)}{t}f-\frac{lt(f)}{t}g$
	\end{center} 
	\par \noindent is called the s-polynomial of $f$ and $g$. \\\\
	\textbf{Theorem 2.6. }(\cite{c1}, Theorem 9.12) \textit{Let $I$ be an ideal in $K[x_{1},\cdots ,x_{n}]$ and $G=\{g_{1},\cdots ,g_{r}\}$ be a finite set generating $I$. Then $G$ is a Gröbner basis of $I$ if and only if $S(g_{i},g_{j})\to_{G}0$ for all $ 1\le i<j\le r$.}\\
	\par For the condition $S(g_{i},g_{j})\to_{G}0$, we have convenient methods to check in some special cases. One common proposition is as follows:\\\\
	\textbf{Proposition 2.7. }\textit{Let $G$ be a finite subset of $K[x_{1},\cdots ,x_{n}]$. We have $S(f,g)\to_{G}0$ for polynomials $f,g\in K[x_{1},\cdots ,x_{n}]$ if $lm(f)$ and $lm(g)$ are coprime.}\\
	\par We will use the graded reverse lexicographic ordering, as defined below: \\\\
	\textbf{Definition 2.8. }Let $t=x_{1}^{e_{1}}\cdots x^{e_{n}}_{n}$ and $t^{'}=x_{1}^{e_{1}^{'}}\cdots x^{e_{n}^{'}}_{n}$ be monomials. The graded reverse lexicographic ordering on $K[x_{1},x_{2},\cdots ,x_{n}]$ with $x_{1}>x_{2}>\cdots >x_{n}$ is defined by saying that $t\le t^{'}$ if $t=t^{'}$ or deg($t$) $<$ deg($t^{'}$), or deg($t$) $=$ deg($t^{'}$) and $e_{i}>e^{'}_{i}$ for the largest index $i$ with $e_{i} \neq e_{i}^{'}$.\\
	\par For example, we have $x_{1}x_{3}<x_{2}^{2}$ if $x_{1}>x_{2}>x_{3}$.
	\par For $\mathcal{L}^{2,n}_{2,2}$, we use the graded reverse lexicographic ordering on $K[x_{i,j},y_{i,j},z_{i,j}]$ induced by the ordering of variables:
	\begin{center}
		$z_{1,1}>z_{1,2}>\cdots >z_{2,1}>\cdots >z_{2,n}>y_{1,1}>\cdots >y_{2,n}>x_{1,1}>\cdots >x_{2,n}$
	\end{center}
	\subsection{Stanley-Reisner Complexes and Shellable Complexes}
	\par $\quad$\\\\
	\textbf{Definition 2.9. }Let $S=\{1,2,\cdots ,n\}$. An abstract simplicial complex $\Delta$ on $S$ is a collection of subsets of $S$ closed under taking subsets, that is, if $X\in \Delta$ and $Y\subset X$, then $Y\in \Delta$. $\Delta$ is a partially ordered set under the inclusion relation. The maximal elements are called facets of $\Delta$. The minimal elements are called vertices of $\Delta$. The dimension of a facet $X$ is $|X|-1$. The dimension of $\Delta$ is the maximal dimension of its facets, denoted by $dim\Delta$.\\
	\par An abstract simplicial complex corresponds to a ring, which is called its Stanley-Reisner ring, as defined below:\\\\
	\textbf{Definition 2.10. }Let $\Delta$ be an abstract simplicial complex with $n$ vertices. The Stanley-Reisner ring of $\Delta$ is $R_{\Delta}=K[x_{1},x_{2},\cdots ,x_{n}]/I_{\Delta}$, where the Stanley-Reisner ideal $I_{\Delta}$ is generated by $\{x_{i_{1}}x_{i_{2}}\cdots x_{i_{s}}|\{ i_{1},i_{2},\cdots ,i_{s}\}\notin \Delta \}$.\\
	\par Let $I$ be an ideal of $K[x_{1},x_{2},\cdots ,x_{n}]$. If $I$ is radical, then there exists a unique abstract simplicial complex $\Delta_{I}$, such that its Stanley-Reisner ideal is $I$.\\\\
	\textbf{Definition 2.11. }Let $\Delta$ be an abstract simplicial complex. We say $\Delta$ is pure if all facets of $\Delta$ have the same dimension. We say $\Delta$ is shellable, if it is pure and its facets can be ordered as $F_{1}<F_{2}<\cdots <F_{e}$ such that there exist $v\in F_{j}-F_{i}$ and $k<j$ satisfying $F_{j}-F_{k}=\{v\}$ for all $1\le i\le j\le e$. This ordering on facets is called a shelling of $\Delta$.\\\\
	\textbf{Definition 2.12. }Let $\Delta$ be a shellable simplicial complex with a shelling $F_{1}<F_{2}<\cdots <F_{e}$. We define $c(F_{t})=\{v\in F_{t}|$ $F_{t}-F_{s}=\{v\}$ for some $s<t\}$. If $T$ is a family of facets of $\Delta$, we define $h_{j}(T)=|\{F_{t}\in T||c(F_{t})|=j\}|$ and $h_{j}=h_{j}(S)$ where $S$ is the family of all facets of $\Delta$.\\
	\par The following proposition about shelling is important for our computation. \\\\
	\textbf{Proposition 2.13. }(\cite{c2}, Theorem 6.3) \textit{Let $\Delta$ be a shellable simplicial complex with a shelling $F_{1}<F_{2}<\cdots <F_{e}$. Then:}
	\par (1)\textit{the Stanley-Reisner ring $R_{\Delta}$ is a Cohen-Macaulay ring of dimension $d=1+dim\Delta$.}
	\par (2)\textit{the Hilbert series of $R_{\Delta}$ is}\\
	\begin{equation}
		H_{R_{\Delta}}(z)=\frac{\underset{j\ge 0}{\sum}h_{j}z^{j}}{(1-z)^{d}}.
	\end{equation}


	\section{Gröbner bases for $I^{2,n}_{2,2}$}
	\par In this section, we present a Gröbner basis $\Gamma$ for the ideal $I^{2,n}_{2,2}$ and identify leading monomials of polynomials in $\Gamma$.
	\par By computing all second order minors of (4), one gets generators of $I^{2,n}_{2,2}$ as follows:
	\begin{center}
		$a_{p,q}=det\left(
		\begin{array}{cc}
			x_{1,p} & x_{1,q}\\x_{2,p} & x_{2,q}
		\end{array}
		\right),1 \le p<q \le n$,
	\end{center}
	\begin{center}
		$b_{p,q}=det\left(
		\begin{array}{cc}
			x_{1,p} & x_{1,q}\\y_{2,p} & y_{2,q}
		\end{array}
		\right)+det\left(
		\begin{array}{cc}
			y_{1,p} & y_{1,q}\\x_{2,p} & x_{2,q}
		\end{array}
		\right),1 \le p<q \le n$,
	\end{center}	
	\begin{center}
		$c_{p,q}=det\left(
		\begin{array}{cc}
			x_{1,p} & x_{1,q}\\z_{2,p} & z_{2,q}
		\end{array}
		\right)+det\left(
		\begin{array}{cc}
			z_{1,p} & z_{1,q}\\x_{2,p} & x_{2,q}
		\end{array}
		\right)+det\left(
		\begin{array}{cc}
			y_{1,p} & y_{1,q}\\y_{2,p} & y_{2,q}
		\end{array}
		\right),1 \le p<q \le n$.
	\end{center}
	\par We introduce the following polynomials:
	\begin{center}
		$d_{p,q,r}=det\left(
		\begin{array}{ccc}
			x_{2,p} & x_{2,q} & x_{2,r}\\y_{1,p} & y_{1,q} & y_{1,r}\\z_{2,p} & z_{2,q} & z_{2,r}
		\end{array}
		\right)+det\left(
		\begin{array}{ccc}
			x_{2,p} & x_{2,q} & x_{2,r}\\z_{1,p} & z_{1,q} & z_{1,r}\\y_{2,p} & y_{2,q} & y_{2,r}
		\end{array}
		\right),p<q<r$,
	\end{center} 
	\begin{center}
		$e_{p,q,r}=det\left(
		\begin{array}{ccc}
			x_{1,p} & x_{1,q} & x_{1,r}\\y_{1,p} & y_{1,q} & y_{1,r}\\z_{2,p} & z_{2,q} & z_{2,r}
		\end{array}
		\right)+det\left(
		\begin{array}{ccc}
			z_{1,p} & z_{1,q} & z_{1,r}\\y_{1,p} & y_{1,q} & y_{1,r}\\x_{2,p} & x_{2,q} & x_{2,r}
		\end{array}
		\right),p<q<r$,
	\end{center} 
	\begin{center}
		$f_{l,p,q,r}=det\left(
		\begin{array}{cccc}
			0 & x_{2,p} & x_{2,q} & x_{2,r}\\x_{2,l} & y_{2,p} & y_{2,q} & y_{2,r}\\y_{1,l} & z_{1,p} & z_{1,q} & z_{1,r}\\y_{2,l} & z_{2,p} & z_{2,q} & z_{2,r}
		\end{array}
		\right),1 \le l \le p<q<r \le n$,
	\end{center} 
	\begin{center}
		$g_{l,p,q,r}=det\left(
		\begin{array}{cccc}
			x_{2,l} & x_{2,p} & x_{2,q} & x_{2,r}\\y_{2,l} & y_{2,p} & y_{2,q} & y_{2,r}\\z_{2,l} & z_{2,p} & z_{2,q} & z_{2,r}\\z_{1,l} & z_{1,p} & z_{1,q} & z_{1,r}
		\end{array}
		\right),1 \le l<p<q<r \le n$.
	\end{center}
	\par The leading monomials of these polynomials are
	\begin{center}
		$lm(a_{p,q})=x_{1,q}x_{2,p}$, \\ $lm(b_{p,q})=x_{1,p}y_{2,q}$, \\
		$lm(c_{p,q})=y_{1,q}y_{2,p}$,\\
		$lm(d_{p,q,r})=x_{2,p}y_{1,q}z_{2,r}$, \\ $lm(e_{p,q,r})=x_{1,p}y_{1,q}z_{2,r}$, \\
		$lm(f_{l,p,q,r})=x_{2,p}y_{1,l}y_{2,q}z_{2,r}$, \\
		$lm(g_{l,p,q,r})=x_{2,l}y_{2,p}z_{1,r}z_{2,q}$.\\
	\end{center}
	\textbf{Proposition 3.1. }\textit{The polynomials $d_{p,q,r}$, $e_{p,q,r}$, $f_{l,p,q,r}$, $g_{l,p,q,r}$ are belong to $I^{2,n}_{2,2}$.}
	\begin{proof}[Proof.]
		We have following equations:
		\begin{center}
			$d_{p,q,r}=-z_{2,p}b_{q,r}+z_{2,q}b_{p,r}-z_{2,r}b_{p,q}-y_{2,p}c_{q,r}+y_{2,q}c_{p,r}-y_{2,r}c_{p,q}$,\\ $e_{p,q,r}=-y_{1,p}c_{q,r}+y_{1,q}c_{p,r}-y_{1,r}c_{p,q}$,\\
			$f_{l,p,q,r}=z_{2,l}z_{2,p}a_{q,r}-z_{2,l}z_{2,q}a_{p,r}+z_{2,l}z_{2,r}a_{p,q}-z_{2,q}x_{2,p}c_{l,r}+z_{2,r}x_{2,p}c_{l,q}-z_{2,r}x_{2,q}c_{l,p}+y_{2,l}d_{p,q,r}$,\\
			$g_{l,p,q,r}=(z_{2,q}y_{2,r}-y_{2,q}z_{2,r})c_{l,p}-(z_{2,p}y_{2,r}-y_{2,p}z_{2,r})c_{l,q}+(z_{2,l}y_{2,r}-y_{2,l}z_{2,r})c_{p,q}+(z_{2,p}y_{2,q}-y_{2,p}z_{2,q})c_{l,r}-(z_{2,l}y_{2,q}-y_{2,l}z_{2,q})c_{p,r}+(z_{2,l}y_{2,p}-y_{2,l}z_{2,p})c_{q,r}$.\\
		\end{center}
		Since $a_{p,q}$, $b_{p,q}$, $c_{p,q}\in I_{2,2}^{2,n}$, it follows that $d_{p,q,r}$, $e_{p,q,r}$, $f_{l,p,q,r}$, $g_{l,p,q,r}\in I^{2,n}_{2,2}$. 
	\end{proof}	
	\par Let $\Gamma$ be the set of all $a_{p,q}$, $b_{p,q}$, $c_{p,q}$, $d_{p,q.r}$, $e_{p,q,r}$, $f_{l,p,q,r}$, $g_{l,p,q,r}$. We aim to prove that $\Gamma$ forms a Gröbner basis for $I^{2,n}_{2,2}$. By Buchberger's criterion (Theorem 2.6), it suffices to show that for every pair of polynomials $\alpha$, $\beta \in \Gamma$, the s-polynomial $S(\alpha,\beta)$ can be expressed as $\underset{\theta \in \Gamma}{\sum} f_{\theta} \theta$ with $lm(f_{\theta} \theta) \le lm(S(\alpha,\beta))$ for all $\theta\in \Gamma$. By the following lemma from \cite{c3}, we can simplify the checking work.\\ \\
	\textbf{Lemma 3.2. }(\cite{c3}, Lemma 2.5) \textit{Let $S(\alpha,\beta)=\underset{\theta \in \Gamma}{\sum}f_{\theta}\theta$ satisfying $lm(f_{\theta} \theta) \le lm(S(\alpha,\beta))$, and all the variables of $\alpha$, $\beta$, $\theta$, $f_{\theta}$ belong to some fixed submatrix $T= \{ (i_{s},j_{s})|i_{1}<\cdots <i_{p}$, $j_{1}<\cdots <j_{q} \}$, $p$, $q \in \mathbb{N}$. If we replace $T$ with another submatrix $T^{'}= \{ (i^{'}_{s},j^{'}_{s})|i^{'}_{1}<\cdots <i^{'}_{p}$, $j^{'}_{1}<\cdots <j^{'}_{q} \} $ of the same size,then we will get new polynomials $\alpha^{'}$, $\beta^{'}$, $\theta^{'}$, $g_{\theta^{'}}$ and $S(\alpha^{'},\beta^{'})=\underset{\theta^{'} \in \Gamma}{\sum}$, $lm(g_{\theta^{'}} \theta^{'}) \le lm(S(\alpha^{'},\beta^{'}))$.}\\
	\par For each $\alpha \in \Gamma$, variables of $\alpha$ comes from at most a $2 \times 4$ matrix. So a $2 \times 8$ matrix can contain all variables of $\alpha$, $\beta \in \Gamma$. If $lm(\alpha)$, $lm(\beta)$ are coprime, then $S(\alpha,\beta)\to_{\Gamma}0$ must hold. So it suffices to consider cases that submatrices of $\alpha$ and $\beta$ have coincident columns. In conclusion, we only have to prove that $\Gamma$ is a Gröbner basis for the case $4 \le n \le 7$. We computed $L(I^{2,n}_{2,2})$ for $n=4,5,6,7$ by the computer algebra system $\mathtt{SINGULAR}$. The results confirmed that $L(I^{2,n}_{2,2})$ is the ideal generated by all leading monomials of polynomials in $\Gamma$ in each case.

