	\par We prove the first part of our main theorem as the end of this section.\\\\
	\textbf{Theorem 5.4. }\textit{$\Delta_{0}$ is shellable and the $*$-ordering of facets gives a shelling of $\Delta_{0}$.}\\\\
	\textit{Proof.} Suppose $P>Q$ are two facets of $\Delta_{0}$. By Corollary 4.4, it suffices to show that $Q$ cannot cover $c(P)$. Then $*$-ordering is a shelling of $\Delta_{0}$.
	\par We first deal with cases that $P$ and $Q$ are from different families of facets of $\Delta_{0}$. If $P\in \bar{A}$ and $Q\in \bar{D}$, $\bar{E}$, or $\bar{F}$, then $A_{1}$ exists and cannot be covered by $Q$. If $P\in \bar{A}$ and $Q\in \bar{C}$, then $A_{1}$ and $A_{3}$ exist and cannot be covered by $Q$, otherwise $c_{2}\le a_{1}<a_{2}\le c_{1}$ leads to contribution. If $P\in \bar{C}$, then $C_{1}$ exists and cannot be covered by $Q$. If $P\in \bar{D}$ and $Q\in \bar{E}$, then $D_{2}$ exists. If $Q$ covers $D_{2}$, then we have $d_{1}<d_{2}\le e_{1}\le e_{2}\le n-1$. Hence $D_{1}$ exists and cannot be covered by $Q$ since $d_{1}<e_{2}$. If $P\in \bar{D}$ or $\bar{E}$ and $Q\in \bar{F}$, then $D_{2}$ or $E_{2}$ exist and cannot be covered by $Q$.
	\par Then we deal with cases that $P$ and $Q$ are from the same families of facets of $\Delta_{0}$. The idea of proof is to find contradiction under the assumption $Q$ cover $c(P)$. For convenience, we use $a_{i}(P)$ and $a_{i}(Q)$ to represent axes of $P$, $Q\in \bar{A}$, which is similar for $\bar{C}$, $\bar{D}$, $\bar{E}$, $\bar{F}$.
	\par \textit{Case $P$, $Q\in \bar{A}$. }$A_{1}$ always exists, so $a_{1}(P)\ge a_{1}(Q)$. Since $P>Q$, we have $a_{1}(P)=a_{1}(Q)$. If $a_{1}(P)\neq a_{r}(P)$, then $A_{2}$ exists and $a_{r}(P)=a_{r}(Q)$. If $a_{1}(P)=a_{r}(P)$, then $a_{r}(Q)=a_{r}(P)$ since $P>Q$. $A_{3}$ always exists so $a_{2}(P)=a_{2}(Q)$. All the three axes are at the same position, which is contradictory to $P>Q$. 
	\par \textit{Case $P$, $Q\in \bar{C}$. }$C_{1}$ always exists, so $c_{2}(P)\ge c_{2}(Q)$. Since $P>Q$, we have $c_{2}(P)=c_{2}(Q)$. Similarly to the discussion in $\bar{A}$, we have $c_{3}(P)=c_{3}(Q)$. If $c_{1}(P)\neq1$, then $C_{3}$ exists and $c_{1}(P)=c_{1}(Q)$. If $c_{1}(P)=1$, then $c_{1}(Q)=1$ since $P>Q$. All the three axes are at the same position, which is contradictory to $P>Q$.
	\par \textit{Case $P$, $Q\in \bar{D}$. }$D_{1}$ vanishes only when $d_{1}(P)=n-1$ and $d_{2}(P)=d_{3}(P)=n$. In this condition, $P$ is the minimal element in $\bar{D}$, so we only have to consider cases that $D_{1}$ exists. We have $e_{1}(P)=e_{1}(Q)$ since $P>Q$. $D_{2}$ exists always, so $e_{2}(P)=e_{2}(Q)$ and $e_{3}(P)=e_{3}(Q)$ similarly to the discussion in $\bar{A}$, which comes to contradiction.
	\par \textit{Case $P$, $Q\in \bar{E}$. }If $e_{2}(P)=n-1$, then $e_{2}(Q)=n-1$ since $P>Q$. If $e_{2}(P)\neq n-1$, then $E_{1}$ exists, which implies $e_{2}(P)=e_{2}(Q)$. $E_{2}$ always exists so $e_{1}(P)=e_{1}(Q)$. Similarly to the discussion of $e_{2}$, we have $e_{3}(P)=e_{3}(Q)$. All the three axes are at the same position, which is contradictory to $P>Q$.
	\par \textit{Case $P$, $Q\in \bar{F}$. }Similarly to discussion in $\bar{E}$, we have $f_{1}(P)=f_{1}(Q)$ and $f_{2}(P)=f_{2}(Q)$. If $f_{2}(P)\neq f_{3}(P)-1$, then $F_{3}$ exists and $f_{3}(P)=f_{3}(Q)$. If $f_{2}(P)=f_{3}(P)-1$, then we have $f_{3}(P)=f_{3}(Q)$ since $P>Q$. The two conditions both lead to contradiction.   \hfill{$\square$} 

	\section{Hilbert Series of $\mathcal{L}^{2,n}_{2,2}$}
	\par We compute $h_{j}(T)$ (recall the notation in Definition 2.12) for $T=\bar{A},\bar{C},\bar{D},\bar{E},\bar{F}$ and $j=1,2,3$ according to the vanishing condition table and additive condition table. The results are as follows:
	\par $h_{1}(\bar{A})=0$,
	\par $h_{1}(\bar{C})=n$, for condition $c_{1}=1,1\le c_{2}=c_{3}\le n$,
	\par $h_{1}(\bar{D})=1$, for condition $d_{1}=n-1,d_{2}=d_{3}=n$,
	\par $h_{1}(\bar{E})=n-1$, for condition $1\le e_{1}\le n-1,e_{2}=n-1,e_{3}=n$,
	\par $h_{1}(\bar{F})=n-3$, for condition $1\le f_{1}\le n-3,f_{2}=n-1,f_{3}=n$,
	\par $h_{2}(\bar{A})=\binom{n}{2}=\frac{n(n-1)}{2}$, for condition $1\le a_{1}=a_{r}<a_{2}\le n$,
	\par $h_{2}(\bar{C})=\binom{n}{2}+\binom{n-1}{2}+\binom{n-1}{1}=n(n-1)$, for conditions $1=c_{1}\le c_{2}<c_{3}\le n$ and $1<c_{1}\le c_{2}=c_{3}\le n$,
	\par $h_{2}(\bar{D})=\binom{n}{2}-\binom{n-1}{1}+n-2=\frac{(n+1)(n-2)}{2}$, for conditions $1\le d_{1}<d_{2}-1=d_{3}-1\le n-1$ and $1\le d_{1}=d_{2}-1=d_{3}-1\le n-1$,
	\par $h_{2}(\bar{E})=\binom{n-2}{2}+\binom{n-2}{1}=\frac{(n-1)(n-2)}{2}$, for condition $1\le e_{1}\le e_{2}<n-1,e_{3}=n$,
	\par $h_{2}(\bar{F})=\binom{n-2}{2}=\frac{(n-2)(n-3)}{2}$, for condition $1\le f_{1}<f_{2}=f_{3}-1<n-1$,
	\par $h_{3}(\bar{A})=\underset{i=1}{\overset{n-1}{\sum}}i^{2}=\frac{n(n-1)(2n-1)}{6}$, for condition $1\le a_{1}<a_{r}\le n,\le a_{1}<a_{2}\le n$,
	\par $h_{3}(\bar{C})=\binom{n-1}{3}+\binom{n-1}{2}=\frac{n(n-1)(n-2)}{6}$, for condition $1<c_{1}\le c_{2}<c_{3}\le n$,
	\par $h_{3}(\bar{D})=\binom{n}{3}=\frac{n(n-1)(n-2)}{6}$, for condition $1\le d_{1}<d_{2}<d_{3}\le n$,
	\par $h_{3}(\bar{E})=\binom{n-1}{3}+\binom{n-1}{2}=\frac{n(n-1)(n-2)}{6}$, for condition $1\le e_{1}\le e_{2}<e_{3}<n$,
	\par $h_{3}(\bar{F})=\binom{n}{3}-\binom{n-1}{2}=\frac{(n-1)(n-2)(n-3)}{6}$, for condition $1\le f_{1}<f_{2}<f_{3}-1\le n-1$.
	\par With above results, we can finish the second part of our main theorem.\\\\
	\textbf{Theorem 6.1. }\textit{The Hilbert series of $\mathcal{L}^{2,n}_{2,2}$ is  $H_{\mathcal{L}^{2,n}_{2,2}}(z)=\big( \frac{1+(n-1)z}{(1-z)^{n+1}}\big)^{3}$.}
	\begin{proof}[Proof.]
		The number $h_{i}$ is just the sum of $h_{i}(\bar{A})$ to $h_{i}(\bar{F})$. As a result of above computation, we have $h_{0}=1$, $h_{1}=3(n-1)$, $h_{2}=3(n-1)^{2}$, $h_{3}=(n-1)^{3}$. Then we have 
		\begin{center}
			$H_{\mathcal{L}^{2,n}_{2,2}}(z)=\frac{h_{0}+h_{1}z+h_{2}z^{2}+h_{3}z^{3}}{(1-z)^{3n+3}}=\big( \frac{1+(n-1)z}{(1-z)^{n+1}}\big)^{3}$. 
		\end{center} 
		\par \noindent by Corollary 4.4, Theorem 5.4, and formula (5). 
	\end{proof} 
	\par It is natural to find some relation between the Hilbert series of determinantal varieties and their jets. For the complicacy of the Hilbert series of arbitrary order jets, we can only deal with some easy cases here. By formula (1), we have 
	\begin{center}
		$H_{\mathcal{L}^{m,n}_{2}}(z)=\frac{\underset{k=0}{\overset{m-1}{\sum}}\binom{m-1}{k} \binom{n-1}{k} z^{k}}{(1-z)^{m+n-1}}$
	\end{center}	
	\par \noindent and it is $H_{\mathcal{L}^{2,n}_{2}}(z)=\frac{1+(n-1)z}{(1-z)^{n+1}}$ for $m=2$. By Theorem 6.1 and (2), it is easy to see that $H_{\mathcal{L}^{m,n}_{2,1}}(z)=H_{\mathcal{L}^{m,n}_{2}}(z)^{2}$ and $H_{\mathcal{L}^{2,n}_{2,2}}(z)=H_{\mathcal{L}^{2,n}_{2}}(z)^{3}$. 
	\par For general condition, we have a conjecture about the Hilbert series:\\\\
	\textbf{Conjecture 6.2. }The Hilbert series of of $\mathcal{L}^{m,n}_{r,k}$ is the $(k+1)$-th power of the Hilbert series of $\mathcal{L}^{m,n}_{r}$. \\\\




